use std::os::unix::fs::chown;
use std::path::Path;

fn update_directory_owner(dir_path: &Path, new_uid: Option<u32>, new_gid: Option<u32>) -> std::io::Result<()> {
    chown(dir_path, new_uid, new_gid)
}

