#[cfg(all(test, unix))]
mod tests {
    use super::*;
    use std::fs;
    use std::os::unix::fs::MetadataExt;
    use std::path::Path;

    fn assert_ok_or_perm_denied(result: std::io::Result<()>) {
        if let Err(err) = result {
            assert!(
                matches!(err.kind(), std::io::ErrorKind::PermissionDenied | std::io::ErrorKind::InvalidInput),
                "Unexpected error: {err}"
            );
        }
    }

    #[test]
    fn test_update_directory_owner_with_existing_ids() {
        let temp_dir = std::env::temp_dir().join("chown_test_dir");
        let _ = fs::remove_dir_all(&temp_dir);
        fs::create_dir_all(&temp_dir).expect("Failed to create temp dir");

        let metadata = fs::metadata(&temp_dir).expect("Failed to get metadata");
        let current_uid = metadata.uid();
        let current_gid = metadata.gid();

        let result = update_directory_owner(&temp_dir, Some(current_uid), Some(current_gid));
        assert_ok_or_perm_denied(result);

        if let Ok(new_metadata) = fs::metadata(&temp_dir) {
            assert_eq!(new_metadata.uid(), current_uid);
            assert_eq!(new_metadata.gid(), current_gid);
        }

        let _ = fs::remove_dir_all(&temp_dir);
    }

    #[test]
    fn test_update_directory_owner_only_uid() {
        let temp_dir = std::env::temp_dir().join("chown_test_dir_uid");
        let _ = fs::remove_dir_all(&temp_dir);
        fs::create_dir_all(&temp_dir).expect("Failed to create temp dir");

        let metadata = fs::metadata(&temp_dir).expect("Failed to get metadata");
        let current_uid = metadata.uid();
        let current_gid = metadata.gid();

        let result = update_directory_owner(&temp_dir, Some(current_uid), None);
        assert_ok_or_perm_denied(result);

        if let Ok(new_metadata) = fs::metadata(&temp_dir) {
            assert_eq!(new_metadata.uid(), current_uid);
            assert_eq!(new_metadata.gid(), current_gid);
        }

        let _ = fs::remove_dir_all(&temp_dir);
    }

    #[test]
    fn test_update_directory_owner_only_gid() {
        let temp_dir = std::env::temp_dir().join("chown_test_dir_gid");
        let _ = fs::remove_dir_all(&temp_dir);
        fs::create_dir_all(&temp_dir).expect("Failed to create temp dir");

        let metadata = fs::metadata(&temp_dir).expect("Failed to get metadata");
        let current_uid = metadata.uid();
        let current_gid = metadata.gid();

        let result = update_directory_owner(&temp_dir, None, Some(current_gid));
        assert_ok_or_perm_denied(result);

        if let Ok(new_metadata) = fs::metadata(&temp_dir) {
            assert_eq!(new_metadata.uid(), current_uid);
            assert_eq!(new_metadata.gid(), current_gid);
        }

        let _ = fs::remove_dir_all(&temp_dir);
    }

    #[test]
    fn test_update_directory_owner_none_values() {
        let temp_dir = std::env::temp_dir().join("chown_test_dir_none");
        let _ = fs::remove_dir_all(&temp_dir);
        fs::create_dir_all(&temp_dir).expect("Failed to create temp dir");

        let metadata = fs::metadata(&temp_dir).expect("Failed to get metadata");
        let original_uid = metadata.uid();
        let original_gid = metadata.gid();

        let result = update_directory_owner(&temp_dir, None, None);
        assert_ok_or_perm_denied(result);

        if let Ok(new_metadata) = fs::metadata(&temp_dir) {
            assert_eq!(new_metadata.uid(), original_uid);
            assert_eq!(new_metadata.gid(), original_gid);
        }

        let _ = fs::remove_dir_all(&temp_dir);
    }

    #[test]
    fn test_update_directory_owner_nonexistent_directory() {
        let non_existent_path = Path::new("/nonexistent/path/that/should/not/exist");
        let result = update_directory_owner(non_existent_path, Some(1000), Some(1000));

        match result {
            Err(e) => assert_eq!(e.kind(), std::io::ErrorKind::NotFound),
            Ok(_) => panic!("Expected error for non-existent path"),
        }
    }
}

