use std::cell::Cell;

thread_local! {
    static COUNTER: Cell<u32> = Cell::new(0);
}

const DEFAULT_COUNTER: u32 = 0;

fn get_counter_if_nonzero() -> u32 {
    let value = COUNTER.get();
    if value == 0 {
        DEFAULT_COUNTER
    } else {
        value
    }
}

