mod tests {
    use super::*;

    #[test]
    fn test_exact_multiples() {
        assert_eq!(min_batches_required(0, 5), 0);
        assert_eq!(min_batches_required(10, 5), 2);
        assert_eq!(min_batches_required(25, 5), 5);
        assert_eq!(min_batches_required(100, 10), 10);
    }

    #[test]
    fn test_partial_batches() {
        assert_eq!(min_batches_required(1, 5), 1);
        assert_eq!(min_batches_required(6, 5), 2);
        assert_eq!(min_batches_required(11, 5), 3);
        assert_eq!(min_batches_required(99, 10), 10);
        assert_eq!(min_batches_required(101, 100), 2);
    }

    #[test]
    fn test_batch_capacity_one() {
        assert_eq!(min_batches_required(0, 1), 0);
        assert_eq!(min_batches_required(1, 1), 1);
        assert_eq!(min_batches_required(100, 1), 100);
        assert_eq!(min_batches_required(u32::MAX, 1), u32::MAX);
    }

    #[test]
    fn test_large_batch_capacity() {
        assert_eq!(min_batches_required(0, u32::MAX), 0);
        assert_eq!(min_batches_required(1, u32::MAX), 1);
        assert_eq!(min_batches_required(u32::MAX - 1, u32::MAX), 1);
        assert_eq!(min_batches_required(u32::MAX, u32::MAX), 1);
    }

    #[test]
    fn test_edge_cases() {
        assert_eq!(min_batches_required(0, 100), 0);
        assert_eq!(min_batches_required(1, 100), 1);
        assert_eq!(min_batches_required(100, 100), 1);
        assert_eq!(min_batches_required(101, 100), 2);
        assert_eq!(min_batches_required(199, 100), 2);
        assert_eq!(min_batches_required(200, 100), 2);
        assert_eq!(min_batches_required(201, 100), 3);
    }

    #[test]
    fn test_powers_of_two() {
        assert_eq!(min_batches_required(0, 2), 0);
        assert_eq!(min_batches_required(1, 2), 1);
        assert_eq!(min_batches_required(2, 2), 1);
        assert_eq!(min_batches_required(3, 2), 2);
        assert_eq!(min_batches_required(4, 2), 2);
        assert_eq!(min_batches_required(7, 4), 2);
        assert_eq!(min_batches_required(8, 4), 2);
        assert_eq!(min_batches_required(9, 4), 3);
    }

    #[test]
    fn test_random_specific_cases() {
        assert_eq!(min_batches_required(17, 3), 6); // 17/3 = 5 remainder 2
        assert_eq!(min_batches_required(23, 7), 4); // 23/7 = 3 remainder 2
        assert_eq!(min_batches_required(47, 13), 4); // 47/13 = 3 remainder 8
        assert_eq!(min_batches_required(999, 1000), 1);
        assert_eq!(min_batches_required(1000, 999), 2);
    }

    #[test]
    fn test_overflow_safety() {
        // These should not panic
        assert_eq!(min_batches_required(u32::MAX, 2), 2147483648);
        assert_eq!(min_batches_required(u32::MAX, u32::MAX), 1);
        assert_eq!(min_batches_required(u32::MAX, 1), u32::MAX);
    }
}

