#[cfg(test)]
mod tests {
    use super::aligned_buffer_size;

    #[test]
    fn test_aligned_buffer_size_basic() {
        // Basic alignment cases
        assert_eq!(aligned_buffer_size(0, 4), 0);
        assert_eq!(aligned_buffer_size(1, 4), 4);
        assert_eq!(aligned_buffer_size(4, 4), 4);
        assert_eq!(aligned_buffer_size(5, 4), 8);
        assert_eq!(aligned_buffer_size(8, 4), 8);
    }

    #[test]
    fn test_aligned_buffer_size_power_of_two_alignments() {
        // Test with various power-of-two alignments
        assert_eq!(aligned_buffer_size(7, 8), 8);
        assert_eq!(aligned_buffer_size(8, 8), 8);
        assert_eq!(aligned_buffer_size(9, 8), 16);

        assert_eq!(aligned_buffer_size(15, 16), 16);
        assert_eq!(aligned_buffer_size(16, 16), 16);
        assert_eq!(aligned_buffer_size(17, 16), 32);

        assert_eq!(aligned_buffer_size(31, 32), 32);
        assert_eq!(aligned_buffer_size(32, 32), 32);
        assert_eq!(aligned_buffer_size(33, 32), 64);
    }

    #[test]
    fn test_aligned_buffer_size_non_power_of_two() {
        // Test with non-power-of-two alignments
        assert_eq!(aligned_buffer_size(5, 3), 6);
        assert_eq!(aligned_buffer_size(6, 3), 6);
        assert_eq!(aligned_buffer_size(7, 3), 9);

        assert_eq!(aligned_buffer_size(9, 5), 10);
        assert_eq!(aligned_buffer_size(10, 5), 10);
        assert_eq!(aligned_buffer_size(11, 5), 15);
    }

    #[test]
    fn test_aligned_buffer_size_edge_cases() {
        // Edge cases
        assert_eq!(aligned_buffer_size(0, 1), 0);
        assert_eq!(aligned_buffer_size(1, 1), 1);
        assert_eq!(aligned_buffer_size(100, 1), 100);

        // Large numbers
        assert_eq!(aligned_buffer_size(1000, 64), 1024);
        assert_eq!(aligned_buffer_size(1024, 64), 1024);
        assert_eq!(aligned_buffer_size(1025, 64), 1088);
    }

    #[test]
    fn test_aligned_buffer_size_already_aligned() {
        // Cases where requested size is already aligned
        assert_eq!(aligned_buffer_size(12, 4), 12);
        assert_eq!(aligned_buffer_size(24, 8), 24);
        assert_eq!(aligned_buffer_size(100, 10), 100);
        assert_eq!(aligned_buffer_size(128, 32), 128);
    }

    #[test]
    fn test_aligned_buffer_size_const_evaluation() {
        // Test that the function works in const context
        const RESULT: usize = aligned_buffer_size(17, 8);
        assert_eq!(RESULT, 24);

        const RESULT2: usize = aligned_buffer_size(0, 16);
        assert_eq!(RESULT2, 0);

        const RESULT3: usize = aligned_buffer_size(32, 32);
        assert_eq!(RESULT3, 32);
    }

    #[test]
    fn test_aligned_buffer_size_max_values() {
        // Test with values near usize::MAX
        let max = usize::MAX;

        // When alignment is 1, should return the same value
        assert_eq!(aligned_buffer_size(max, 1), max);

        // When requested is 0, alignment doesn't matter
        assert_eq!(aligned_buffer_size(0, max), 0);

        // Test with large alignment values
        let large_alignment = 4096;
        let test_value = 5000;
        let expected = ((test_value + large_alignment - 1) / large_alignment) * large_alignment;
        assert_eq!(aligned_buffer_size(test_value, large_alignment), expected);
    }

    #[test]
    fn test_aligned_buffer_size_property_based() {
        // Property-based style tests
        for alignment in 1..=64 {
            for requested in 0..=100 {
                let result = aligned_buffer_size(requested, alignment);

                // Result should be >= requested
                assert!(result >= requested);

                // Result should be divisible by alignment (or 0 when requested is 0)
                if requested == 0 {
                    assert_eq!(result, 0);
                } else {
                    assert_eq!(result % alignment, 0);
                }

                // Result should be the smallest multiple of alignment >= requested
                // Check that (result - alignment) < requested
                if result >= alignment {
                    assert!(result - alignment < requested);
                }
            }
        }
    }
}

