#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::VecDeque;

    #[test]
    fn test_empty_deque() {
        let mut processes: VecDeque<u32> = VecDeque::new();
        rotate_process_ids(&mut processes, 5);
        assert!(processes.is_empty());
    }

    #[test]
    fn test_single_element() {
        let mut processes = VecDeque::from([42]);
        rotate_process_ids(&mut processes, 0);
        assert_eq!(processes, [42]);

        let mut processes = VecDeque::from([42]);
        rotate_process_ids(&mut processes, 1);
        assert_eq!(processes, [42]);

        let mut processes = VecDeque::from([42]);
        rotate_process_ids(&mut processes, 100);
        assert_eq!(processes, [42]);
    }

    #[test]
    fn test_zero_shift() {
        let mut processes = VecDeque::from([1, 2, 3, 4, 5]);
        rotate_process_ids(&mut processes, 0);
        assert_eq!(processes, [1, 2, 3, 4, 5]);
    }

    #[test]
    fn test_small_shift() {
        let mut processes = VecDeque::from([1, 2, 3, 4, 5]);
        rotate_process_ids(&mut processes, 2);
        assert_eq!(processes, [3, 4, 5, 1, 2]);
    }

    #[test]
    fn test_shift_equal_length() {
        let mut processes = VecDeque::from([1, 2, 3, 4, 5]);
        rotate_process_ids(&mut processes, 5);
        assert_eq!(processes, [1, 2, 3, 4, 5]);
    }

    #[test]
    fn test_shift_greater_than_length() {
        let mut processes = VecDeque::from([1, 2, 3, 4, 5]);
        rotate_process_ids(&mut processes, 7);
        assert_eq!(processes, [3, 4, 5, 1, 2]);
    }

    #[test]
    fn test_large_shift() {
        let mut processes = VecDeque::from([1, 2, 3, 4, 5]);
        rotate_process_ids(&mut processes, 102);
        assert_eq!(processes, [3, 4, 5, 1, 2]);
    }

    #[test]
    fn test_shift_length_minus_one() {
        let mut processes = VecDeque::from([1, 2, 3, 4, 5]);
        rotate_process_ids(&mut processes, 4);
        assert_eq!(processes, [5, 1, 2, 3, 4]);
    }

    #[test]
    fn test_multiple_rotations_preserve_elements() {
        let original = vec![10, 20, 30, 40, 50, 60];
        let mut processes = VecDeque::from(original.clone());

        for shift in 0..12 {
            rotate_process_ids(&mut processes, shift);
            let mut sorted_result: Vec<u32> = processes.iter().cloned().collect();
            let mut sorted_original = original.clone();
            sorted_result.sort();
            sorted_original.sort();
            assert_eq!(sorted_result, sorted_original);
        }
    }

    #[test]
    fn test_identity_after_full_rotation() {
        let original = vec![1, 2, 3, 4, 5];
        let mut processes = VecDeque::from(original.clone());

        rotate_process_ids(&mut processes, 5);
        assert_eq!(processes, original);

        rotate_process_ids(&mut processes, 10);
        assert_eq!(processes, original);

        rotate_process_ids(&mut processes, 15);
        assert_eq!(processes, original);
    }

    #[test]
    fn test_consecutive_rotations() {
        let mut processes = VecDeque::from([1, 2, 3, 4, 5]);

        rotate_process_ids(&mut processes, 2);
        assert_eq!(processes, [3, 4, 5, 1, 2]);

        rotate_process_ids(&mut processes, 3);
        assert_eq!(processes, [1, 2, 3, 4, 5]);

        rotate_process_ids(&mut processes, 1);
        assert_eq!(processes, [2, 3, 4, 5, 1]);
    }

    #[test]
    fn test_max_shift_value() {
        let mut processes = VecDeque::from([1, 2, 3]);
        rotate_process_ids(&mut processes, usize::MAX);

        let effective_shift = usize::MAX % 3;
        let expected = match effective_shift {
            0 => vec![1, 2, 3],
            1 => vec![2, 3, 1],
            2 => vec![3, 1, 2],
            _ => unreachable!(),
        };
        assert_eq!(processes, expected);
    }
}

