#[cfg(test)]
mod tests {
    use super::*;
    use std::rc::Rc;

    #[test]
    fn test_increment_rc_count_safely_valid_pointer() {
        let rc = Rc::new(42);
        let ptr = Rc::as_ptr(&rc);

        // Initial strong count should be 1
        assert_eq!(Rc::strong_count(&rc), 1);

        // Increment the count safely
        let result = increment_rc_count_safely(ptr);
        assert!(result.is_ok());

        // Strong count should now be 2
        assert_eq!(Rc::strong_count(&rc), 2);

        // Create another Rc from the same pointer to verify it works
        let _rc2 = unsafe { Rc::from_raw(ptr) };
        assert_eq!(Rc::strong_count(&rc), 2);

        // Clean up - rc2 will be dropped here
    }

    #[test]
    fn test_increment_rc_count_safely_null_pointer() {
        let result = increment_rc_count_safely(std::ptr::null());
        assert!(result.is_err());
        assert_eq!(result.err().unwrap(), "Null pointer provided");
    }

    #[test]
    fn test_increment_rc_count_safely_multiple_increments() {
        let rc = Rc::new(100);
        let ptr = Rc::as_ptr(&rc);

        assert_eq!(Rc::strong_count(&rc), 1);

        // Increment multiple times
        for i in 2..=5 {
            let result = increment_rc_count_safely(ptr);
            assert!(result.is_ok());
            assert_eq!(Rc::strong_count(&rc), i);
        }

        assert_eq!(Rc::strong_count(&rc), 5);
    }

    #[test]
    fn test_increment_rc_count_safely_dropped_original() {
        let ptr;

        {
            let rc = Rc::new(999);
            ptr = Rc::as_ptr(&rc);

            // Increment before dropping original
            let result = increment_rc_count_safely(ptr);
            assert!(result.is_ok());
            assert_eq!(Rc::strong_count(&rc), 2);

            // rc goes out of scope here, count goes to 1
        }

        // The pointer should still be valid because we incremented the count
        // Create a new Rc from the raw pointer
        let rc_recreated = unsafe { Rc::from_raw(ptr) };
        assert_eq!(*rc_recreated, 999);

        // Clean up - this will deallocate the memory
        drop(rc_recreated);
    }

    #[test]
    fn test_increment_rc_count_safely_zero_value() {
        let rc = Rc::new(0);
        let ptr = Rc::as_ptr(&rc);

        let result = increment_rc_count_safely(ptr);
        assert!(result.is_ok());
        assert_eq!(Rc::strong_count(&rc), 2);
    }

    #[test]
    fn test_increment_rc_count_safely_negative_value() {
        let rc = Rc::new(-42);
        let ptr = Rc::as_ptr(&rc);

        let result = increment_rc_count_safely(ptr);
        assert!(result.is_ok());
        assert_eq!(Rc::strong_count(&rc), 2);
    }

    #[test]
    fn test_increment_rc_count_safely_with_cloned_rc() {
        let rc1 = Rc::new(777);
        let rc2 = rc1.clone();
        let ptr = Rc::as_ptr(&rc1);

        assert_eq!(Rc::strong_count(&rc1), 2);

        let result = increment_rc_count_safely(ptr);
        assert!(result.is_ok());
        assert_eq!(Rc::strong_count(&rc1), 3);
    }

    #[test]
    fn test_increment_rc_count_safely_pointer_equality() {
        let rc = Rc::new(123);
        let ptr1 = Rc::as_ptr(&rc);
        let ptr2 = Rc::as_ptr(&rc);

        // Both pointers should be equal
        assert_eq!(ptr1, ptr2);

        let result1 = increment_rc_count_safely(ptr1);
        assert!(result1.is_ok());

        let result2 = increment_rc_count_safely(ptr2);
        assert!(result2.is_ok());

        assert_eq!(Rc::strong_count(&rc), 3);
    }
