#[cfg(test)]
mod tests {
    use std::ffi::OsStr;

    #[cfg(unix)]
    use std::os::unix::ffi::OsStrExt;

    #[cfg(windows)]
    use std::os::windows::ffi::OsStrExt;

    // Helper function to validate bytes for Unix-like systems
    #[cfg(unix)]
    fn validate_unix_bytes(bytes: &[u8]) -> bool {
        // On Unix, any byte sequence is valid for OsStr
        !bytes.contains(&0) // No null bytes in the middle
    }

    // Helper function to validate bytes for Windows
    #[cfg(windows)]
    fn validate_windows_bytes(bytes: &[u8]) -> bool {
        // On Windows, check for valid UTF-16 surrogate pairs
        // This is simplified - real validation would be more complex
        if bytes.len() % 2 != 0 {
            return false;
        }

        // Check for lone surrogates (simplified check)
        let mut i = 0;
        while i < bytes.len() {
            let b1 = bytes[i];
            let b2 = bytes[i + 1];
            let word = u16::from_le_bytes([b1, b2]);

            // Check for invalid UTF-16 code units
            if (0xD800..=0xDFFF).contains(&word) {
                // Would need to check for proper surrogate pairs
                // This is simplified for test purposes
                return false;
            }

            i += 2;
        }
        true
    }

    // Test basic functionality with valid bytes
    #[test]
    fn test_valid_bytes() {
        let test_cases = vec![
            b"hello".as_slice(),
            b"world".as_slice(),
            b"test123".as_slice(),
            b"".as_slice(), // Empty slice
        ];

        for bytes in test_cases {
            // Simulate validation (in real use, this would be done before calling the function)
            #[cfg(unix)]
            let is_valid = validate_unix_bytes(bytes);
            #[cfg(windows)]
            let is_valid = validate_windows_bytes(bytes);

            if is_valid {
                let os_str = unsafe { super::os_str_from_validated_bytes(bytes) };

                // Verify the conversion
                #[cfg(unix)]
                assert_eq!(os_str.as_bytes(), bytes);

                #[cfg(windows)]
                {
                    let expected: Vec<u16> = bytes
                        .chunks_exact(2)
                        .map(|chunk| u16::from_le_bytes([chunk[0], chunk[1]]))
                        .collect();
                    let actual: Vec<u16> = os_str.encode_wide().collect();
                    assert_eq!(actual, expected);
                }
            }
        }
    }

    // Test with special characters
    #[test]
    fn test_special_characters() {
        #[cfg(unix)]
        {
            let bytes = b"hello\xc3\xa9world"; // "helloéworld" in UTF-8
            let os_str = unsafe { super::os_str_from_validated_bytes(bytes) };
            assert_eq!(os_str.as_bytes(), bytes);
