                'w' as u16, 'o' as u16, 'r' as u16, 'l' as u16, 'd' as u16,
            ];
            let actual: Vec<u16> = os_str.encode_wide().collect();
            assert_eq!(actual, expected);
        }
    }

    // Test with empty slice
    #[test]
    fn test_empty_bytes() {
        let bytes = b"";
        let os_str = unsafe { super::os_str_from_validated_bytes(bytes) };

        #[cfg(unix)]
        assert_eq!(os_str.as_bytes(), bytes);

        #[cfg(windows)]
        {
            let actual: Vec<u16> = os_str.encode_wide().collect();
            assert!(actual.is_empty());
        }

        assert_eq!(os_str.len(), 0);
    }

    // Test that the function doesn't panic with valid input
