            let wide: Vec<u16> = "hello\0world".encode_utf16().collect();
            let os_string = OsString::from_wide(&wide);
            let result = serialize_os_string_for_transport(os_string);
            assert!(!result.is_empty());
        }
    }

    #[test]
    fn test_invalid_utf8_sequence() {
        #[cfg(unix)]
        {
            use std::os::unix::ffi::OsStringExt;
            let invalid_utf8 = vec![0xFF, 0xFE, 0xC0, 0xC1];
            let os_string = OsString::from_vec(invalid_utf8.clone());
            let result = serialize_os_string_for_transport(os_string);
            assert_eq!(result, invalid_utf8);
        }

        #[cfg(windows)]
        {
            use std::os::windows::ffi::OsStringExt;
            // On Windows, we need to create from wide chars
            let wide: Vec<u16> = "test".encode_utf16().collect();
            let os_string = OsString::from_wide(&wide);
            let result = serialize_os_string_for_transport(os_string);
            assert!(!result.is_empty());
        }
    }

    #[test]
    fn test_large_os_string() {
        let large_string = "a".repeat(10000);
        let os_string = OsString::from(large_string);
        let result = serialize_os_string_for_transport(os_string.clone());
        let expected = os_string.into_string().unwrap().into_bytes();
        assert_eq!(result.len(), expected.len());
        assert_eq!(result, expected);
    }

    #[test]
    fn test_round_trip_serialization() {
        let test_cases = vec![
            OsString::from("simple"),
            OsString::from("with spaces"),
            OsString::from("with\ttabs"),
            OsString::from("with\nnewlines"),
            OsString::from("emoji: 🚀🌟🎉"),
        ];

        for os_string in test_cases {
            let serialized = serialize_os_string_for_transport(os_string.clone());
            // On Unix, we can reconstruct using OsStringExt
            #[cfg(unix)]
            {
                use std::os::unix::ffi::OsStringExt;
                let reconstructed = OsString::from_vec(serialized);
                assert_eq!(os_string, reconstructed);
            }
            // On Windows, we can't easily reconstruct without knowing the encoding
            #[cfg(windows)]
            {
                // Just verify we got some bytes
                assert!(!serialized.is_empty());
            }
        }
    }

    #[test]
    fn test_platform_specific_encoding_preserved() {
        #[cfg(unix)]
        {
            use std::os::unix::ffi::OsStringExt;
            let raw_bytes = vec![b't', b'e', b's', b't', 0x80, 0xFF];
            let os_string = OsString::from_vec(raw_bytes.clone());
            let result = serialize_os_string_for_transport(os_string);
            assert_eq!(result, raw_bytes);
        }

        #[cfg(windows)]
        {
            use std::os::windows::ffi::OsStringExt;
            let wide: Vec<u16> = "test".encode_utf16().collect();
            let os_string = OsString::from_wide(&wide);
            let result = serialize_os_string_for_transport(os_string);
            assert!(!result.is_empty());
        }
    }

    #[test]
    fn test_multiple_calls_consistency() {
        let os_string = OsString::from("consistent result");
        let result1 = serialize_os_string_for_transport(os_string.clone());
        let result2 = serialize_os_string_for_transport(os_string);
        assert_eq!(result1, result2);
    }

    #[test]
    fn test_ownership_transfer() {
        let os_string = OsString::from("take ownership");
        let result = serialize_os_string_for_transport(os_string);
        assert!(!result.is_empty());
    }
}

