        // We'll create a path with null bytes using OsString from raw bytes

        // This test needs to be platform-specific or removed since
        // OsString::from_encoded_bytes_unchecked is unsafe and not available
        // in stable Rust. We'll test with valid paths containing null bytes
        // using a different approach.

        // On Unix, we can create a path with null bytes using a Vec<u8>
        #[cfg(unix)]
        {
            use std::os::unix::ffi::OsStrExt;
            let bytes = b"path\0with\0nulls";
            let path = OsStr::from_bytes(bytes);
            let result = extract_raw_path_bytes(path);
            assert_eq!(result, bytes);
        }

        // On Windows, we can't easily create paths with null bytes
        #[cfg(windows)]
        {
