        // points to the same memory as the input (for certain cases)
        let original = OsStr::new("test");
        let result = extract_raw_path_bytes(original);

        // For simple ASCII strings, the bytes should match exactly
        assert_eq!(result, b"test");

        // We can't directly compare pointers in safe Rust, but we can
        // verify the function signature returns a reference without 'mut'
        // which implies no allocation
    }

    #[test]
