    #[test]
    fn test_extract_raw_path_bytes_platform_independent_behavior() {
        // Test that the function works with various path formats
        let test_paths = vec![
            OsStr::new("/unix/absolute/path"),
            OsStr::new("relative/path"),
            OsStr::new("C:\\windows\\path"),
            OsStr::new("mixed\\and/separators"),
