        for path in test_paths {
            let result = extract_raw_path_bytes(path);
            assert!(!result.is_empty());
        }
    }

    #[test]
    fn test_extract_raw_path_bytes_checksum_compatible() {
        // Test that the output can be used for checksum validation
        let path = OsStr::new("important/file.dat");
        let raw_bytes = extract_raw_path_bytes(path);

        // Simulate checksum calculation with explicit type annotation
        let checksum: u32 = raw_bytes.iter().fold(0u32, |acc, &b| acc.wrapping_add(b as u32));

        // Verify checksum is consistent
        let expected_checksum: u32 = b"important/file.dat".iter().fold(0u32, |acc, &b| acc.wrapping_add(b as u32));
        assert_eq!(checksum, expected_checksum);
