use std::num::Saturating;

fn check_sensor_palindrome(word: Saturating<u16>) -> (bool, Saturating<u16>) {
    let reversed = word.reverse_bits();
    let is_palindrome = word == reversed;
    (is_palindrome, reversed)
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use std::num::Saturating;

    #[test]
    fn test_palindrome_simple_cases() {
        // All bits same - palindromes
        assert_eq!(
            check_sensor_palindrome(Saturating(0b0000_0000_0000_0000)),
            (true, Saturating(0b0000_0000_0000_0000))
        );
        assert_eq!(
            check_sensor_palindrome(Saturating(0b1111_1111_1111_1111)),
            (true, Saturating(0b1111_1111_1111_1111))
        );
        // 0b1010_1010_1010_1010 is not a palindrome
        // Its reverse is 0b0101_0101_0101_0101
        assert_eq!(
            check_sensor_palindrome(Saturating(0b1010_1010_1010_1010)),
            (false, Saturating(0b0101_0101_0101_0101))
        );
    }

    #[test]
    fn test_non_palindrome_cases() {
        // Clear non-palindrome patterns
        assert_eq!(
            check_sensor_palindrome(Saturating(0b0000_0000_0000_0001)),
            (false, Saturating(0b1000_0000_0000_0000))
        );
        assert_eq!(
            check_sensor_palindrome(Saturating(0b1000_0000_0000_0000)),
            (false, Saturating(0b0000_0000_0000_0001))
        );
        // 0b1100_1100_0011_0011 is actually a palindrome
        // Binary: 1100110000110011, reverse is the same
        assert_eq!(
            check_sensor_palindrome(Saturating(0b1100_1100_0011_0011)),
            (true, Saturating(0b1100_1100_0011_0011))
        );
    }

    #[test]
    fn test_symmetric_palindromes() {
        // Symmetric patterns that are palindromes
        assert_eq!(
            check_sensor_palindrome(Saturating(0b1000_0000_0000_0001)),
            (true, Saturating(0b1000_0000_0000_0001))
        );
        assert_eq!(
            check_sensor_palindrome(Saturating(0b0110_0000_0000_0110)),
            (true, Saturating(0b0110_0000_0000_0110))
        );
        // 0b1110_0111_1110_0111 is a palindrome
        // Binary: 1110011111100111, reverse is the same
        assert_eq!(
            check_sensor_palindrome(Saturating(0b1110_0111_1110_0111)),
            (true, Saturating(0b1110_0111_1110_0111))
        );
    }

    #[test]
    fn test_edge_cases() {
        // Min and max u16 values
        assert_eq!(
            check_sensor_palindrome(Saturating(u16::MIN)),
            (true, Saturating(u16::MIN))
        );
        assert_eq!(
            check_sensor_palindrome(Saturating(u16::MAX)),
            (true, Saturating(u16::MAX))
        );

        // Power of two values (single bit set)
        for i in 0..16 {
            let value = 1u16 << i;
            let reversed = 1u16 << (15 - i);
            assert_eq!(
                check_sensor_palindrome(Saturating(value)),
                (value == reversed, Saturating(reversed))
            );
        }
    }

    #[test]
    fn test_saturation_preserved() {
        // Verify that Saturating wrapper is preserved through operations
        let original = Saturating(0b1010_1010_1010_1010);
        let (is_pal, reversed) = check_sensor_palindrome(original);

        assert!(!is_pal);
        assert_eq!(reversed, Saturating(0b0101_0101_0101_0101));

        // Type check - should still be Saturating<u16>
        let _: Saturating<u16> = reversed;
    }

    #[test]
    fn test_reverse_bits_property() {
        // Test that double reversal returns original
        for &test_value in &[
            0x0000, 0xFFFF, 0x1234, 0xABCD, 0x5555, 0xAAAA, 0x3333, 0xCCCC,
        ] {
            let (_, reversed_once) = check_sensor_palindrome(Saturating(test_value));
            let (_, reversed_twice) = check_sensor_palindrome(reversed_once);
            assert_eq!(reversed_twice, Saturating(test_value));
        }
    }

    #[test]
    fn test_random_samples() {
        // Fixed set of random-looking values for deterministic testing
        let test_cases = [
            (0x1234, false, 0x2C48),
            (0xABCD, false, 0xB3D5),
            (0x5555, false, 0xAAAA),  // 0x5555 reverse is 0xAAAA, not equal
            (0x3333, false, 0xCCCC),  // 0x3333 reverse is 0xCCCC, not equal
            (0x7E7E, true, 0x7E7E),   // Binary: 0111111001111110 is palindrome
            (0x8181, true, 0x8181),   // Binary: 1000000110000001 is palindrome
        ];

        for (input, expected_pal, expected_rev) in test_cases.iter() {
            let result = check_sensor_palindrome(Saturating(*input));
            assert_eq!(result, (*expected_pal, Saturating(*expected_rev)));
        }
    }
}

