fn apply_calibration_power(base: i16, exponent: u32) -> i16 {
    use std::num::Saturating;
    Saturating(base).pow(exponent).0
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_positive_base_positive_exponent() {
        // Basic positive exponentiation
        assert_eq!(apply_calibration_power(2, 3), 8);
        assert_eq!(apply_calibration_power(3, 2), 9);
        assert_eq!(apply_calibration_power(5, 0), 1); // Any number to power 0 is 1
        assert_eq!(apply_calibration_power(1, 100), 1); // 1 to any power is 1
    }

    #[test]
    fn test_negative_base_positive_exponent() {
        // Negative base with various exponents
        assert_eq!(apply_calibration_power(-2, 3), -8);
        assert_eq!(apply_calibration_power(-3, 2), 9); // Negative squared becomes positive
        assert_eq!(apply_calibration_power(-5, 0), 1); // Negative to power 0 is 1
        assert_eq!(apply_calibration_power(-1, 100), 1); // -1 to even power is 1
        assert_eq!(apply_calibration_power(-1, 101), -1); // -1 to odd power is -1
    }

    #[test]
    fn test_zero_base() {
        // Zero to any positive power is 0
        assert_eq!(apply_calibration_power(0, 1), 0);
        assert_eq!(apply_calibration_power(0, 2), 0);
        assert_eq!(apply_calibration_power(0, 10), 0);
        // Zero to power 0 is 1 (mathematical convention)
        assert_eq!(apply_calibration_power(0, 0), 1);
    }

    #[test]
    fn test_saturation_upper_bound() {
        // Test saturation at i16::MAX
        assert_eq!(apply_calibration_power(i16::MAX, 1), i16::MAX);
        assert_eq!(apply_calibration_power(i16::MAX, 0), 1);

        // Values that would overflow without saturation
        // 2^15 = 32768, which is i16::MAX + 1, should saturate to i16::MAX
        assert_eq!(apply_calibration_power(2, 15), i16::MAX);

        // 3^10 = 59049, exceeds i16::MAX, should saturate
        assert_eq!(apply_calibration_power(3, 10), i16::MAX);

        // 10^5 = 100000, exceeds i16::MAX, should saturate
        assert_eq!(apply_calibration_power(10, 5), i16::MAX);
    }

    #[test]
    fn test_saturation_lower_bound() {
        // Test saturation at i16::MIN
        assert_eq!(apply_calibration_power(i16::MIN, 1), i16::MIN);
        assert_eq!(apply_calibration_power(i16::MIN, 0), 1);

        // (-2)^15 = -32768 = i16::MIN
        assert_eq!(apply_calibration_power(-2, 15), i16::MIN);

        // Test that negative to even power saturates at positive max
        // (-100)^2 = 10000, within range, no saturation needed
        assert_eq!(apply_calibration_power(-100, 2), 10000);

        // Test that negative to odd power saturates at negative min
        // (-100)^3 = -1000000, exceeds i16::MIN, should saturate
        assert_eq!(apply_calibration_power(-100, 3), i16::MIN);
    }

    #[test]
    fn test_edge_cases() {
        // Edge case: i16::MAX as base
        assert_eq!(apply_calibration_power(i16::MAX, 1), i16::MAX);
        assert_eq!(apply_calibration_power(i16::MAX, 2), i16::MAX); // Should saturate

        // Edge case: i16::MIN as base
        assert_eq!(apply_calibration_power(i16::MIN, 1), i16::MIN);
        assert_eq!(apply_calibration_power(i16::MIN, 2), i16::MAX); // Should saturate to MAX (positive)
        assert_eq!(apply_calibration_power(i16::MIN, 3), i16::MIN); // Should saturate to MIN (negative)

        // Large exponents
        assert_eq!(apply_calibration_power(2, 100), i16::MAX);
        assert_eq!(apply_calibration_power(-2, 100), i16::MAX);
        assert_eq!(apply_calibration_power(-2, 101), i16::MIN);
    }

    #[test]
    fn test_small_values() {
        // Small bases that won't saturate
        assert_eq!(apply_calibration_power(1, 1000), 1);
        assert_eq!(apply_calibration_power(-1, 1000), 1);
        assert_eq!(apply_calibration_power(-1, 1001), -1);
        assert_eq!(apply_calibration_power(0, 1000), 0);

        // Small positive base with moderate exponent
        assert_eq!(apply_calibration_power(2, 4), 16);
        assert_eq!(apply_calibration_power(2, 5), 32);
        assert_eq!(apply_calibration_power(2, 6), 64);

        // Small negative base with moderate exponent
        assert_eq!(apply_calibration_power(-2, 4), 16);
        assert_eq!(apply_calibration_power(-2, 5), -32);
        assert_eq!(apply_calibration_power(-2, 6), 64);
    }

    #[test]
    fn test_exponent_zero() {
        // Any number to the power of 0 is 1
        assert_eq!(apply_calibration_power(0, 0), 1);
        assert_eq!(apply_calibration_power(1, 0), 1);
        assert_eq!(apply_calibration_power(-1, 0), 1);
        assert_eq!(apply_calibration_power(i16::MAX, 0), 1);
        assert_eq!(apply_calibration_power(i16::MIN, 0), 1);
        assert_eq!(apply_calibration_power(42, 0), 1);
        assert_eq!(apply_calibration_power(-42, 0), 1);
    }

    #[test]
    fn test_exponent_one() {
        // Any number to the power of 1 is itself
        assert_eq!(apply_calibration_power(0, 1), 0);
        assert_eq!(apply_calibration_power(1, 1), 1);
        assert_eq!(apply_calibration_power(-1, 1), -1);
        assert_eq!(apply_calibration_power(i16::MAX, 1), i16::MAX);
        assert_eq!(apply_calibration_power(i16::MIN, 1), i16::MIN);
        assert_eq!(apply_calibration_power(42, 1), 42);
        assert_eq!(apply_calibration_power(-42, 1), -42);
    }
}

