fn count_unused_header_bits(packet_sizes: &[u32]) -> Vec<u32> {
    packet_sizes
        .iter()
        .map(|&size| size.leading_zeros())
        .collect()
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_input() {
        let input: &[u32] = &[];
        let result = count_unused_header_bits(input);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_zero_size_packet() {
        let input = &[0u32];
        let result = count_unused_header_bits(input);
        // 0u32 has all 32 bits as zeros
        assert_eq!(result, vec![32]);
    }

    #[test]
    fn test_max_value_packet() {
        let input = &[u32::MAX];
        let result = count_unused_header_bits(input);
        // u32::MAX has no leading zeros
        assert_eq!(result, vec![0]);
    }

    #[test]
    fn test_single_bit_set() {
        // Test numbers with only one bit set at various positions
        let input = &[1u32, 2, 4, 8, 16, 32, 64, 128];
        let result = count_unused_header_bits(input);
        // For 1 (binary: ...0001): 31 leading zeros
        // For 2 (binary: ...0010): 30 leading zeros
        // etc.
        assert_eq!(result, vec![31, 30, 29, 28, 27, 26, 25, 24]);
    }

    #[test]
    fn test_all_ones_pattern() {
        // Numbers where all lower bits are 1
        let input = &[0b1u32, 0b11, 0b111, 0b1111];
        let result = count_unused_header_bits(input);
        assert_eq!(result, vec![31, 30, 29, 28]);
    }

    #[test]
    fn test_mixed_values() {
        let input = &[0, 1, 255, 256, 65535, 65536, 16777215, 16777216];
        let result = count_unused_header_bits(input);
        // Expected leading zeros:
        // 0: 32, 1: 31, 255: 24, 256: 23, 
        // 65535: 16, 65536: 15, 16777215: 8, 16777216: 7
        assert_eq!(result, vec![32, 31, 24, 23, 16, 15, 8, 7]);
    }

    #[test]
    fn test_power_of_two_values() {
        let input = &[
            1u32, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096,
            8192, 16384, 32768, 65536, 131072, 262144, 524288, 1048576,
            2097152, 4194304, 8388608, 16777216, 33554432, 67108864,
            134217728, 268435456, 536870912, 1073741824, 2147483648
        ];
        let result = count_unused_header_bits(input);
        // Powers of two have exactly (31 - log2(value)) leading zeros
        let expected: Vec<u32> = (0..32).rev().collect();
        assert_eq!(result, expected);
    }

    #[test]
    fn test_large_collection() {
        let input: Vec<u32> = (0..1000).collect();
        let result = count_unused_header_bits(&input);

        // Verify length matches
        assert_eq!(result.len(), 1000);

        // Spot check specific values
        assert_eq!(result[0], 32);    // 0
        assert_eq!(result[1], 31);    // 1
        assert_eq!(result[255], 24);  // 255
        assert_eq!(result[256], 23);  // 256
        assert_eq!(result[999], 22);  // 999

        // Verify monotonic property: as numbers increase, leading zeros decrease or stay same
        for i in 1..result.len() {
            assert!(result[i] <= result[i-1], 
                   "Failed at index {}: {} > {}", i, result[i], result[i-1]);
        }
    }

    #[test]
    fn test_random_scatter() {
        // Test with non-sequential values
        let input = &[42, 1000000, 7, 4294967295, 255, 0, 65536, 131072];
        let result = count_unused_header_bits(input);
        assert_eq!(result, vec![26, 12, 29, 0, 24, 32, 15, 14]);
    }

    #[test]
    fn test_edge_cases() {
        let input = &[
            u32::MIN,           // 0
            u32::MAX,           // 4294967295
            0x80000000,         // 2147483648 (MSB set)
            0x40000000,         // 1073741824
            0x00000001,         // 1 (LSB set)
            0xFFFFFFFF,         // Same as MAX
            0x7FFFFFFF,         // Max positive i32
            0x0000FFFF,         // 65535
            0xFFFF0000,         // 4294901760
        ];
        let result = count_unused_header_bits(input);
        assert_eq!(
            result,
            vec![32, 0, 0, 1, 31, 0, 1, 16, 0]
        );
    }

    #[test]
    fn test_slice_from_vec() {
        let vec_input = vec![0u32, 1, 2, 3, 4, 5];
        let result = count_unused_header_bits(&vec_input);
        assert_eq!(result, vec![32, 31, 30, 30, 29, 29]);
    }

    #[test]
    fn test_array_input() {
        // Test that it works with array slices
        let array_input = [0u32, 255, 65535, 16777215];
        let result = count_unused_header_bits(&array_input);
        assert_eq!(result, vec![32, 24, 16, 8]);
    }
}

