            Saturating(-1),
            Saturating(-42),
            Saturating(i32::MIN + 1),
        ];
        let result = clamp_absolute_readings(&readings);
        assert_eq!(result, vec![
            Saturating(0),
            Saturating(1),
            Saturating(42),
            Saturating(i32::MAX),
        ]);
    }

