        ];
        let result = clamp_absolute_readings(&readings);
        assert_eq!(result, vec![
            Saturating(10),
            Saturating(20),
            Saturating(30),
            Saturating(40),
            Saturating(0),
        ]);
    }

    #[test]
    fn test_i32_min_edge_case() {
        // Special case: i32::MIN.abs() would overflow for i32, but Saturating handles it
        let readings = vec![Saturating(i32::MIN)];
        let result = clamp_absolute_readings(&readings);
        // i32::MIN.abs() as i32 would be i32::MAX + 1, which wraps to i32::MIN
        // But with Saturating, it saturates at i32::MAX
        assert_eq!(result, vec![Saturating(i32::MAX)]);
    }

    #[test]
    fn test_large_negative_to_positive() {
        let readings = vec![
            Saturating(i32::MIN + 1),
            Saturating(i32::MIN + 100),
            Saturating(-1000000),
        ];
        let result = clamp_absolute_readings(&readings);
        assert_eq!(result, vec![
            Saturating(i32::MAX),
            Saturating(i32::MAX - 99),
            Saturating(1000000),
        ]);
    }

    #[test]
    fn test_single_element() {
        let readings = vec![Saturating(-5)];
        let result = clamp_absolute_readings(&readings);
        assert_eq!(result, vec![Saturating(5)]);
    }

    #[test]
    fn test_all_zeros() {
        let readings = vec![Saturating(0), Saturating(0), Saturating(0)];
        let result = clamp_absolute_readings(&readings);
        assert_eq!(result, vec![Saturating(0), Saturating(0), Saturating(0)]);
    }

    #[test]
    fn test_identity_for_positives() {
        let readings = vec![
            Saturating(100),
            Saturating(500),
            Saturating(1000),
            Saturating(i32::MAX),
        ];
        let result = clamp_absolute_readings(&readings);
        // Positive values should remain unchanged
        assert_eq!(result, readings);
    }

    #[test]
    fn test_negative_zero_equivalence() {
        // Note: Saturating doesn't distinguish between -0 and 0
        let readings = vec![Saturating(0), Saturating(0)];
        let result = clamp_absolute_readings(&readings);
        assert_eq!(result, vec![Saturating(0), Saturating(0)]);
    }
}

