#[cfg(test)]
mod tests {
    use super::*;
    use std::num::Saturating;

    #[test]
    fn test_empty_input() {
        let measurements: Vec<Saturating<i32>> = vec![];
        let result = compute_saturated_directions(&measurements);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_single_element() {
        let measurements = vec![Saturating(42)];
        let result = compute_saturated_directions(&measurements);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_increasing_sequence() {
        let measurements = vec![
            Saturating(1),
            Saturating(2),
            Saturating(3),
            Saturating(4),
        ];
        let result = compute_saturated_directions(&measurements);
        assert_eq!(result, vec![Saturating(1), Saturating(1), Saturating(1)]);
    }

    #[test]
    fn test_decreasing_sequence() {
        let measurements = vec![
            Saturating(10),
            Saturating(8),
            Saturating(5),
            Saturating(2),
        ];
        let result = compute_saturated_directions(&measurements);
        assert_eq!(result, vec![Saturating(-1), Saturating(-1), Saturating(-1)]);
    }

    #[test]
    fn test_mixed_sequence() {
        let measurements = vec![
            Saturating(5),
            Saturating(7),
            Saturating(7),
            Saturating(4),
            Saturating(6),
        ];
        let result = compute_saturated_directions(&measurements);
        assert_eq!(
            result,
            vec![Saturating(1), Saturating(0), Saturating(-1), Saturating(1)]
        );
    }

    #[test]
    fn test_saturation_at_max() {
        let measurements = vec![
            Saturating(i32::MAX - 2),
            Saturating(i32::MAX - 1),
            Saturating(i32::MAX),
            Saturating(i32::MAX),
        ];
        let result = compute_saturated_directions(&measurements);
        assert_eq!(result, vec![Saturating(1), Saturating(1), Saturating(0)]);
    }

    #[test]
    fn test_saturation_at_min() {
        let measurements = vec![
            Saturating(i32::MIN + 2),
            Saturating(i32::MIN + 1),
            Saturating(i32::MIN),
            Saturating(i32::MIN),
        ];
        let result = compute_saturated_directions(&measurements);
        assert_eq!(result, vec![Saturating(-1), Saturating(-1), Saturating(0)]);
    }

    #[test]
    fn test_saturated_difference() {
        let measurements = vec![
            Saturating(i32::MAX),
            Saturating(i32::MIN),
            Saturating(i32::MAX),
        ];
        let result = compute_saturated_directions(&measurements);
        // i32::MIN - i32::MAX would overflow but Saturating handles it
        assert_eq!(result, vec![Saturating(-1), Saturating(1)]);
    }

    #[test]
    fn test_zero_values() {
        let measurements = vec![
            Saturating(0),
            Saturating(0),
            Saturating(0),
            Saturating(0),
        ];
        let result = compute_saturated_directions(&measurements);
        assert_eq!(result, vec![Saturating(0), Saturating(0), Saturating(0)]);
    }

    #[test]
    fn test_large_sequence() {
        let measurements: Vec<Saturating<i32>> = 
            (0..100).map(|i| Saturating(i * 10)).collect();
        let result = compute_saturated_directions(&measurements);

        // All differences should be positive 10, signum gives 1
        assert_eq!(result.len(), 99);
        assert!(result.iter().all(|&x| x == Saturating(1)));
    }

    #[test]
    fn test_alternating_sequence() {
        let measurements = vec![
            Saturating(100),
            Saturating(-100),
            Saturating(100),
            Saturating(-100),
        ];
        let result = compute_saturated_directions(&measurements);
        // 100 to -100 = -200 (signum -1)
        // -100 to 100 = 200 (signum 1)
        // 100 to -100 = -200 (signum -1)
        assert_eq!(result, vec![Saturating(-1), Saturating(1), Saturating(-1)]);
    }

    #[test]
    fn test_edge_case_transition() {
        let measurements = vec![
            Saturating(-1),
            Saturating(0),
            Saturating(1),
        ];
        let result = compute_saturated_directions(&measurements);
        assert_eq!(result, vec![Saturating(1), Saturating(1)]);
    }

    #[test]
    fn test_near_overflow_transition() {
        let measurements = vec![
            Saturating(i32::MAX - 1),
            Saturating(i32::MAX),
            Saturating(i32::MAX - 1),
        ];
        let result = compute_saturated_directions(&measurements);
        assert_eq!(result, vec![Saturating(1), Saturating(-1)]);
    }
}

