use std::fs;
use std::path::Path;
use std::time::SystemTime;

fn replicate_file_metadata(source_path: &Path, dest_path: &Path) -> std::io::Result<()> {
    let metadata = fs::metadata(source_path)?;
    let modified_time = metadata.modified()?;

    let file = fs::File::open(dest_path)?;
    file.set_modified(modified_time)?;

    Ok(())
}

