    #[test]
    fn test_replicate_file_metadata_success() {
        // Create temporary files using system temp directory
        let temp_dir = temp_dir();

        let source_path = temp_dir.join("test_source_success.txt");
        let dest_path = temp_dir.join("test_dest_success.txt");

        // Clean up any existing test files
        let _ = fs::remove_file(&source_path);
        let _ = fs::remove_file(&dest_path);

        // Write content to source file
        fs::write(&source_path, "source content").unwrap();

        // Wait a moment to ensure different timestamps
        thread::sleep(Duration::from_millis(10));

        // Write content to destination file
        fs::write(&dest_path, "dest content").unwrap();

        // Get original modified time
        let original_metadata = fs::metadata(&source_path).unwrap();
        let original_modified = original_metadata.modified().unwrap();

        // Replicate metadata
        let result = replicate_file_metadata(&source_path, &dest_path);
        assert!(result.is_ok());

        // Verify metadata was copied
        let dest_metadata = fs::metadata(&dest_path).unwrap();
        let dest_modified = dest_metadata.modified().unwrap();

        // Compare timestamps (allow for small differences due to filesystem precision)
        let diff = if dest_modified > original_modified {
            dest_modified.duration_since(original_modified).unwrap()
        } else {
            original_modified.duration_since(dest_modified).unwrap()
        };

        assert!(diff.as_secs() == 0, "Timestamps should match within 1 second");

        // Clean up
        let _ = fs::remove_file(&source_path);
        let _ = fs::remove_file(&dest_path);
    }

