        };

        assert!(diff.as_secs() == 0, "Timestamps should match");

        // Clean up
        let _ = fs::remove_dir_all(&source_dir);
        let _ = fs::remove_file(&dest_file);
    }

    #[test]
    fn test_replicate_file_metadata_empty_files() {
        let temp_dir = temp_dir();

        let source_path = temp_dir.join("test_empty_source.txt");
        let dest_path = temp_dir.join("test_empty_dest.txt");

        // Clean up any existing test files
        let _ = fs::remove_file(&source_path);
        let _ = fs::remove_file(&dest_path);

        // Create empty files
        File::create(&source_path).unwrap();
        thread::sleep(Duration::from_millis(10));
        File::create(&dest_path).unwrap();

        // Replicate metadata
        replicate_file_metadata(&source_path, &dest_path).unwrap();

        // Verify metadata was copied
        let source_modified = fs::metadata(&source_path).unwrap().modified().unwrap();
        let dest_modified = fs::metadata(&dest_path).unwrap().modified().unwrap();

        let diff = if dest_modified > source_modified {
            dest_modified.duration_since(source_modified).unwrap()
        } else {
            source_modified.duration_since(dest_modified).unwrap()
        };

        assert!(diff.as_secs() == 0, "Timestamps should match for empty files");

        // Clean up
        let _ = fs::remove_file(&source_path);
        let _ = fs::remove_file(&dest_path);
    }
}

