fn get_channel_pointer(pixel: *const u32, channel: usize) -> *const u8 {
    // Each channel is 1 byte, so offset by channel bytes
    let offset = channel as isize;
    // Cast to u8 pointer first, then apply wrapping byte offset
    pixel.cast::<u8>().wrapping_byte_offset(offset)
}

