fn compute_field_ptr(base: *const u8, byte_offset: usize, buffer_size: usize) -> *const u8 {
    let wrapped_offset = byte_offset % buffer_size;
    base.wrapping_byte_add(wrapped_offset)
}

test_program:
#[cfg(test)]
mod tests {
    use super::compute_field_ptr;
    use std::ptr;

    #[test]
    fn test_basic_offset_no_wrap() {
        let buffer = [0u8, 1u8, 2u8, 3u8, 4u8, 5u8];
        let base = buffer.as_ptr();

        // Simple case: offset within buffer size
        let result = compute_field_ptr(base, 2, 6);
        unsafe {
            assert_eq!(*result, 2);
        }

        // Offset at beginning
        let result = compute_field_ptr(base, 0, 6);
        unsafe {
            assert_eq!(*result, 0);
        }

        // Offset at end (but not wrapping)
        let result = compute_field_ptr(base, 5, 6);
        unsafe {
            assert_eq!(*result, 5);
        }
    }

    #[test]
    fn test_wrapping_offset() {
        let buffer = [0u8, 1u8, 2u8, 3u8, 4u8, 5u8];
        let base = buffer.as_ptr();

        // Offset equal to buffer size wraps to beginning
        let result = compute_field_ptr(base, 6, 6);
        unsafe {
            assert_eq!(*result, 0);
        }

        // Offset greater than buffer size wraps appropriately
        let result = compute_field_ptr(base, 8, 6);
        unsafe {
            assert_eq!(*result, 2); // 8 % 6 = 2
        }

        // Multiple wraps
        let result = compute_field_ptr(base, 18, 6);
        unsafe {
            assert_eq!(*result, 0); // 18 % 6 = 0
        }
    }

    #[test]
    fn test_large_offsets() {
        let buffer = [42u8; 100];
        let base = buffer.as_ptr();

        // Test with very large offset that wraps
        let large_offset = usize::MAX - 50;
        let result = compute_field_ptr(base, large_offset, 100);

        // Calculate expected wrapped offset
        let wrapped = large_offset % 100;
        let expected = base.wrapping_add(wrapped);
        assert_eq!(result, expected);
    }

    #[test]
    #[should_panic]
    fn test_zero_buffer_size() {
        // Edge case: buffer size of 0 - should panic on modulo by zero
        let buffer = [0u8; 1];
        let base = buffer.as_ptr();

        // This will panic in both debug and release modes
        let _ = compute_field_ptr(base, 5, 0);
    }

    #[test]
    fn test_null_pointer() {
        // Test with null pointer (should still work with wrapping_add)
        let null_ptr = ptr::null();
        let result = compute_field_ptr(null_ptr, 5, 10);

        // Expected: null + (5 % 10) = null + 5
        let expected = null_ptr.wrapping_add(5);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_buffer_size_one() {
        let buffer = [99u8];
        let base = buffer.as_ptr();

        // Any offset should point to the same element
        for offset in 0..10 {
            let result = compute_field_ptr(base, offset, 1);
            unsafe {
                assert_eq!(*result, 99);
            }
        }
    }

    #[test]
    fn test_sequential_offsets() {
        let buffer = [0u8, 10u8, 20u8, 30u8, 40u8];
        let base = buffer.as_ptr();

        // Test a sequence of offsets that wrap
        for i in 0..15 {
            let result = compute_field_ptr(base, i, 5);
            let expected_offset = i % 5;
            let expected = base.wrapping_add(expected_offset);
            assert_eq!(result, expected);

            // Verify the actual value if we're within the original buffer bounds
            if i < 5 {
                unsafe {
                    assert_eq!(*result, (expected_offset * 10) as u8);
                }
            }
        }
    }

    #[test]
    fn test_different_buffer_sizes() {
        let mut buffer: [u8; 256] = [0; 256];
        // Initialize with pattern
        for (i, elem) in buffer.iter_mut().enumerate() {
            *elem = i as u8;
        }
        let base = buffer.as_ptr();

        // Test various buffer sizes
        let test_cases = vec![
            (10, 3, 3),   // offset 3, size 10 -> offset 3
            (10, 12, 2),  // offset 12, size 10 -> offset 2
            (7, 20, 6),   // offset 20, size 7 -> offset 6 (20 % 7 = 6)
            (100, 150, 50), // offset 150, size 100 -> offset 50
        ];

        for (buffer_size, offset, expected_wrapped) in test_cases {
            let result = compute_field_ptr(base, offset, buffer_size);
            let expected = base.wrapping_add(expected_wrapped);
            assert_eq!(result, expected);
        }
    }

    #[test]
    fn test_alignment_properties() {
        // Test that the function preserves alignment properties
        // by using aligned data types
        #[repr(align(16))]
        struct AlignedBuffer([u8; 32]);

        let buffer = AlignedBuffer([0u8; 32]);
        let base = buffer.0.as_ptr();

        // The base pointer should be 16-byte aligned
        assert_eq!(base as usize % 16, 0);

        // After wrapping, the pointer should still be properly aligned
        // relative to the buffer (though not necessarily to 16 bytes)
        for offset in 0..50 {
            let result = compute_field_ptr(base, offset, 32);
            // Verify it points somewhere within or just past the buffer
            let diff = (result as usize).wrapping_sub(base as usize);
            let wrapped_diff = diff % 32;
            assert!(wrapped_diff < 32);
        }
    }
}

