#[derive(Debug, Clone)]
pub struct AppConfig {
    // Example fields - can be customized as needed
    pub setting1: String,
    pub setting2: u32,
}

pub fn extract_configuration_data(shared_config: Rc<AppConfig>) -> AppConfig {
    Rc::unwrap_or_clone(shared_config)
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use std::rc::Rc;

    #[test]
    fn test_extract_configuration_data_single_reference() {
        // When there's only one reference, unwrap should succeed without cloning
        let config = AppConfig {
            setting1: "test_value".to_string(),
            setting2: 42,
        };

        let rc_config = Rc::new(config);
        let extracted = extract_configuration_data(rc_config);

        assert_eq!(extracted.setting1, "test_value");
        assert_eq!(extracted.setting2, 42);
    }

    #[test]
    fn test_extract_configuration_data_multiple_references() {
        // When there are multiple references, clone should be performed
        let config = AppConfig {
            setting1: "shared_value".to_string(),
            setting2: 100,
        };

        let rc_config = Rc::new(config);
        let rc_clone = Rc::clone(&rc_config);

        // Verify both references point to the same data
        assert_eq!(rc_config.setting1, rc_clone.setting1);
        assert_eq!(rc_config.setting2, rc_clone.setting2);

        // Extract should clone since there are multiple references
        let extracted = extract_configuration_data(rc_config);

        // Verify extracted data matches original
        assert_eq!(extracted.setting1, "shared_value");
        assert_eq!(extracted.setting2, 100);

        // Original clone should still be valid
        assert_eq!(rc_clone.setting1, "shared_value");
        assert_eq!(rc_clone.setting2, 100);
    }

    #[test]
    fn test_extract_configuration_data_empty_string() {
        // Test with empty string field
        let config = AppConfig {
            setting1: String::new(),
            setting2: 0,
        };

        let rc_config = Rc::new(config);
        let extracted = extract_configuration_data(rc_config);

        assert!(extracted.setting1.is_empty());
        assert_eq!(extracted.setting2, 0);
    }

    #[test]
    fn test_extract_configuration_data_large_values() {
        // Test with large values
        let config = AppConfig {
            setting1: "a".repeat(1000),
            setting2: u32::MAX,
        };

        let rc_config = Rc::new(config);
        let extracted = extract_configuration_data(rc_config);

        assert_eq!(extracted.setting1.len(), 1000);
        assert_eq!(extracted.setting2, u32::MAX);
    }

    #[test]
    fn test_extract_configuration_data_after_dropping_other_references() {
        // Test that unwrap works after other references are dropped
        let config = AppConfig {
            setting1: "test".to_string(),
            setting2: 123,
        };

        let rc_config = Rc::new(config);
        let rc_clone = Rc::clone(&rc_config);

        // Drop the clone, leaving only one reference
        drop(rc_clone);

        // Now unwrap should succeed without cloning
        let extracted = extract_configuration_data(rc_config);

        assert_eq!(extracted.setting1, "test");
        assert_eq!(extracted.setting2, 123);
    }

    #[test]
    fn test_extract_configuration_data_verify_no_extra_clones() {
        // This test verifies the behavior when there's only one reference
        // by checking that the extracted data is the same instance
        // (though we can't directly compare addresses in safe Rust)

        let config = AppConfig {
            setting1: "unique".to_string(),
            setting2: 999,
        };

        let rc_config = Rc::new(config);

        // Get the strong count before extraction
        let strong_count_before = Rc::strong_count(&rc_config);

        let extracted = extract_configuration_data(rc_config);

        // After extraction with single reference, Rc is consumed
        // and we have the owned value
        assert_eq!(extracted.setting1, "unique");
        assert_eq!(extracted.setting2, 999);

        // Verify the strong count was 1 before extraction
        assert_eq!(strong_count_before, 1);
    }

    #[test]
    fn test_extract_configuration_data_with_special_characters() {
        // Test with special characters in strings
        let config = AppConfig {
            setting1: "test\n\t\r\"\\".to_string(),
            setting2: 0xDEADBEEF,
        };

        let rc_config = Rc::new(config);
        let extracted = extract_configuration_data(rc_config);

        assert_eq!(extracted.setting1, "test\n\t\r\"\\");
        assert_eq!(extracted.setting2, 0xDEADBEEF);
    }
}

