mod tests {
    use super::*;
    use std::sync::Arc;

    #[test]
    fn test_extract_when_sole_owner() {
        let original = String::from("unique_value");
        let arc = Arc::new(original);

        let result = extract_or_duplicate(arc);

        assert_eq!(result, "unique_value");
    }

    #[test]
    fn test_duplicate_when_multiple_owners() {
        let original = String::from("shared_value");
        let arc1 = Arc::new(original);
        let arc2 = Arc::clone(&arc1);

        let result = extract_or_duplicate(arc1);

        assert_eq!(result, "shared_value");
        assert_eq!(*arc2, "shared_value");
    }

    #[test]
    fn test_empty_string() {
        let arc = Arc::new(String::new());

        let result = extract_or_duplicate(arc);

        assert_eq!(result, "");
    }

    #[test]
    fn test_large_string() {
        let large_string = "x".repeat(10000);
        let arc = Arc::new(large_string.clone());

        let result = extract_or_duplicate(arc);

        assert_eq!(result, large_string);
    }

    #[test]
    fn test_multiple_clones_then_extract() {
        let original = String::from("test");
        let arc = Arc::new(original);
        let clones: Vec<_> = (0..5).map(|_| Arc::clone(&arc)).collect();

        let result = extract_or_duplicate(arc);

        assert_eq!(result, "test");
        for clone in clones {
            assert_eq!(*clone, "test");
        }
    }

    #[test]
    fn test_unicode_string() {
        let unicode = String::from("🎉🦀✨");
        let arc = Arc::new(unicode);

        let result = extract_or_duplicate(arc);

        assert_eq!(result, "🎉🦀✨");
    }
}

