    use super::*;

    // Helper trait to implement round_ties_even
    trait RoundTiesEven {
        fn round_ties_even(self) -> f64;
    }

    impl RoundTiesEven for f64 {
        fn round_ties_even(self) -> f64 {
            let rounded = self.round();
            if (self - 0.5).fract().abs() < f64::EPSILON {
                // Value is exactly halfway between integers
                if rounded % 2.0 == 0.0 {
                    rounded
                } else {
                    rounded - 1.0
                }
            } else {
                rounded
            }
        }
    }

    #[test]
    fn test_empty_input() {
        let measurements: Vec<f64> = vec![];
        let result = round_measurements_unbiased(&measurements);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_single_measurement() {
        let measurements = vec![3.7];
        let result = round_measurements_unbiased(&measurements);
        assert_eq!(result, vec![4]);
    }

    #[test]
    fn test_positive_numbers() {
        let measurements = vec![1.1, 2.5, 3.9, 4.0, 5.4];
        let result = round_measurements_unbiased(&measurements);
        assert_eq!(result, vec![1, 2, 4, 4, 5]);
    }

    #[test]
    fn test_negative_numbers() {
        let measurements = vec![-1.1, -2.5, -3.9, -4.0, -5.4];
        let result = round_measurements_unbiased(&measurements);
        assert_eq!(result, vec![-1, -2, -4, -4, -5]);
    }

    #[test]
    fn test_tie_rounding_to_even_positive() {
        // 2.5 is halfway between 2 and 3, should round to even (2)
        // 3.5 is halfway between 3 and 4, should round to even (4)
        let measurements = vec![2.5, 3.5, 4.5, 5.5];
        let result = round_measurements_unbiased(&measurements);
        assert_eq!(result, vec![2, 4, 4, 6]);
    }

    #[test]
    fn test_tie_rounding_to_even_negative() {
        // -2.5 is halfway between -3 and -2, should round to even (-2)
        // -3.5 is halfway between -4 and -3, should round to even (-4)
        let measurements = vec![-2.5, -3.5, -4.5, -5.5];
        let result = round_measurements_unbiased(&measurements);
        assert_eq!(result, vec![-2, -4, -4, -6]);
    }

    #[test]
    fn test_exact_integers() {
        let measurements = vec![1.0, 2.0, -3.0, -4.0, 0.0];
        let result = round_measurements_unbiased(&measurements);
        assert_eq!(result, vec![1, 2, -3, -4, 0]);
    }

    #[test]
    fn test_large_numbers() {
        let measurements = vec![123456.1, 123456.5, 123456.9];
        let result = round_measurements_unbiased(&measurements);
        assert_eq!(result, vec![123456, 123456, 123457]);
    }

    #[test]
    fn test_small_numbers() {
        let measurements = vec![0.1, 0.5, 0.9];
        let result = round_measurements_unbiased(&measurements);
        assert_eq!(result, vec![0, 0, 1]);
    }

    #[test]
    fn test_mixed_numbers() {
        let measurements = vec![0.0, -0.5, 1.5, -2.5, 3.5, -4.5];
        let result = round_measurements_unbiased(&measurements);
        assert_eq!(result, vec![0, 0, 2, -2, 4, -4]);
    }

    #[test]
    fn test_precision_edge_cases() {
        // Values very close to halfway points
        let measurements = vec![2.499999999999999, 2.500000000000001];
        let result = round_measurements_unbiased(&measurements);
        assert_eq!(result, vec![2, 3]);
    }

    #[test]
    fn test_statistical_unbiased_property() {
        // Test that rounding many halfway points results in equal numbers of round-ups and round-downs
        let mut measurements = Vec::new();
        for i in 0..1000 {
            measurements.push(i as f64 + 0.5);
        }

        let result = round_measurements_unbiased(&measurements);

        // Count how many times we rounded up vs down
        let mut round_up_count = 0;
        let mut round_down_count = 0;

        for (i, &rounded) in result.iter().enumerate() {
            let original = i as f64 + 0.5;
            let expected_up = (original + 0.5) as i64;
            let expected_down = (original - 0.5) as i64;

            if rounded == expected_up {
                round_up_count += 1;
            } else if rounded == expected_down {
                round_down_count += 1;
            }
        }

        // With round-to-even, we should have roughly equal numbers
        // For 1000 numbers from 0.5 to 999.5, half should round to even (down) and half to odd (up)
        assert_eq!(round_up_count, 500);
        assert_eq!(round_down_count, 500);
    }
}

