            (NonZeroI32::new(-1).unwrap(), NonZeroI32::new(1).unwrap()),
            (NonZeroI32::new(-42).unwrap(), NonZeroI32::new(42).unwrap()),
            (NonZeroI32::new(-100).unwrap(), NonZeroI32::new(100).unwrap()),
        ];

        for &(input, expected) in &test_cases {
            let result = compute_absolute_nonzero(input);
            assert_eq!(result, expected);
        }
    }

