        // Test the edge case: i32::MIN
        // Note: NonZeroI32::new(i32::MIN) will panic because i32::MIN is -2147483648
        // and its absolute value would be 2147483648, which overflows i32
        // saturating_abs() should handle this by saturating at i32::MAX

        let min_nonzero = NonZeroI32::new(i32::MIN).unwrap();
        let result = compute_absolute_nonzero(min_nonzero);

        // saturating_abs() on i32::MIN returns i32::MAX for i32
        // So for NonZeroI32, it should be NonZeroI32::new(i32::MAX)
        assert_eq!(result, NonZeroI32::new(i32::MAX).unwrap());
    }

    #[test]
    fn test_negative_max() {
        // Test negative i32::MAX
        let neg_max = NonZeroI32::new(-i32::MAX).unwrap();
        let result = compute_absolute_nonzero(neg_max);

        assert_eq!(result, NonZeroI32::new(i32::MAX).unwrap());
    }

