mod tests {
    use std::num::NonZeroU32;

    use super::sum_leading_zeros;

    #[test]
    fn test_empty_slice() {
        let nums: &[NonZeroU32] = &[];
        assert_eq!(sum_leading_zeros(nums), 0);
    }

    #[test]
    fn test_single_element() {
        let nums = &[NonZeroU32::new(1).unwrap()];
        assert_eq!(sum_leading_zeros(nums), 31);

        let nums = &[NonZeroU32::new(0x80000000).unwrap()];
        assert_eq!(sum_leading_zeros(nums), 0);

        let nums = &[NonZeroU32::new(0x00000001).unwrap()];
        assert_eq!(sum_leading_zeros(nums), 31);

        let nums = &[NonZeroU32::new(0x00008000).unwrap()];
        assert_eq!(sum_leading_zeros(nums), 16);
    }

    #[test]
    fn test_multiple_elements() {
        let nums = &[
            NonZeroU32::new(1).unwrap(),
            NonZeroU32::new(2).unwrap(),
            NonZeroU32::new(4).unwrap(),
        ];
        // 1: 31, 2: 30, 4: 29 = 90
        assert_eq!(sum_leading_zeros(nums), 90);

        let nums = &[
            NonZeroU32::new(0x80000000).unwrap(),
            NonZeroU32::new(0x40000000).unwrap(),
            NonZeroU32::new(0x20000000).unwrap(),
        ];
        // 0x80000000: 0, 0x40000000: 1, 0x20000000: 2 = 3
        assert_eq!(sum_leading_zeros(nums), 3);
    }

    #[test]
    fn test_all_bits_set() {
        let nums = &[NonZeroU32::new(0xFFFFFFFF).unwrap()];
        assert_eq!(sum_leading_zeros(nums), 0);
    }

    #[test]
    fn test_mixed_values() {
        let nums = &[
            NonZeroU32::new(0x00000001).unwrap(), // 31
            NonZeroU32::new(0x00010000).unwrap(), // 15
            NonZeroU32::new(0x10000000).unwrap(), // 3
            NonZeroU32::new(0x80000000).unwrap(), // 0
        ];
        // 31 + 15 + 3 + 0 = 49
        assert_eq!(sum_leading_zeros(nums), 49);
    }

    #[test]
    fn test_powers_of_two() {
        let mut nums = Vec::new();
        for i in 0..32 {
            if let Some(num) = NonZeroU32::new(1 << i) {
                nums.push(num);
            }
        }
        // Sum of leading zeros for 2^i is 31-i
        // Sum from i=0 to 31 of (31-i) = 31*32/2 = 496
        assert_eq!(sum_leading_zeros(&nums), 496);
    }

    #[test]
    fn test_large_slice() {
        // Test with a moderately large slice to ensure performance
        let nums: Vec<NonZeroU32> = (1..=1000)
            .map(|i| NonZeroU32::new(i).unwrap())
            .collect();

        let expected: u32 = nums.iter().map(|&num| num.leading_zeros()).sum();
        assert_eq!(sum_leading_zeros(&nums), expected);
    }

    #[test]
    fn test_edge_cases() {
        // Test minimum non-zero value
        let nums = &[NonZeroU32::new(1).unwrap()];
        assert_eq!(sum_leading_zeros(nums), 31);

        // Test maximum value
        let nums = &[NonZeroU32::new(u32::MAX).unwrap()];
        assert_eq!(sum_leading_zeros(nums), 0);

        // Test value with alternating bits
        let nums = &[NonZeroU32::new(0xAAAAAAAA).unwrap()];
        assert_eq!(sum_leading_zeros(nums), 0);

        // Test value with only lowest bit set
        let nums = &[NonZeroU32::new(0x00000001).unwrap()];
        assert_eq!(sum_leading_zeros(nums), 31);
    }

    #[test]
    fn test_slice_from_array() {
        let nums = [
            NonZeroU32::new(1).unwrap(),
            NonZeroU32::new(256).unwrap(),
            NonZeroU32::new(65536).unwrap(),
        ];
        // 1: 31, 256: 23, 65536: 15 = 69
        assert_eq!(sum_leading_zeros(&nums[..]), 69);
    }

    #[test]
    fn test_consistent_with_leading_zeros() {
        // Verify that the function matches individual leading_zeros calls
        let test_values = [1, 42, 1000, 0x8000, 0x80000000, u32::MAX];

        for &val in &test_values {
            let num = NonZeroU32::new(val).unwrap();
            let nums = &[num];
            assert_eq!(sum_leading_zeros(nums), val.leading_zeros());
        }
    }
}

