#[cfg(test)]
mod tests {
    use super::pow_with_saturation;
    use std::num::NonZeroU32;

    #[test]
    fn test_basic_powers() {
        // Test basic power operations that don't saturate
        let base = NonZeroU32::new(2).unwrap();
        assert_eq!(pow_with_saturation(base, 0).get(), 1);
        assert_eq!(pow_with_saturation(base, 1).get(), 2);
        assert_eq!(pow_with_saturation(base, 2).get(), 4);
        assert_eq!(pow_with_saturation(base, 3).get(), 8);
        assert_eq!(pow_with_saturation(base, 4).get(), 16);
    }

    #[test]
    fn test_exponent_zero() {
        // Any non-zero base to the power of 0 should be 1
        let bases = [1, 2, 5, 10, 100, u32::MAX];
        for &b in &bases {
            let base = NonZeroU32::new(b).unwrap();
            assert_eq!(pow_with_saturation(base, 0).get(), 1);
        }
    }

    #[test]
    fn test_exponent_one() {
        // Any base to the power of 1 should be the base itself
        let bases = [1, 2, 5, 10, 100, u32::MAX];
        for &b in &bases {
            let base = NonZeroU32::new(b).unwrap();
            assert_eq!(pow_with_saturation(base, 1).get(), b);
        }
    }

    #[test]
    fn test_saturation() {
        // Test cases that should saturate to u32::MAX
        let large_base = NonZeroU32::new(u32::MAX).unwrap();
        assert_eq!(pow_with_saturation(large_base, 1).get(), u32::MAX);
        assert_eq!(pow_with_saturation(large_base, 2).get(), u32::MAX);

        // Base 2^32 should saturate when squared
        let base_2_16 = NonZeroU32::new(65536).unwrap(); // 2^16
        // 65536^2 = 2^32 which is u32::MAX + 1, should saturate
        assert_eq!(pow_with_saturation(base_2_16, 2).get(), u32::MAX);

        // Test with base that would overflow quickly
        let base_1000 = NonZeroU32::new(1000).unwrap();
        // 1000^4 = 1,000,000,000,000 which is > u32::MAX
        assert_eq!(pow_with_saturation(base_1000, 4).get(), u32::MAX);
    }

    #[test]
    fn test_no_saturation() {
        // Test cases that should not saturate
        let base = NonZeroU32::new(10).unwrap();
        assert_eq!(pow_with_saturation(base, 2).get(), 100);
        assert_eq!(pow_with_saturation(base, 3).get(), 1000);
        assert_eq!(pow_with_saturation(base, 4).get(), 10000);
        assert_eq!(pow_with_saturation(base, 5).get(), 100000);
        assert_eq!(pow_with_saturation(base, 6).get(), 1000000);

        // 10^9 = 1,000,000,000 which is < u32::MAX
        assert_eq!(pow_with_saturation(base, 9).get(), 1000000000);
    }

    #[test]
    fn test_minimum_base() {
        // Test with minimum non-zero value
        let min_base = NonZeroU32::new(1).unwrap();
        assert_eq!(pow_with_saturation(min_base, 0).get(), 1);
        assert_eq!(pow_with_saturation(min_base, 1).get(), 1);
        assert_eq!(pow_with_saturation(min_base, 2).get(), 1);
        assert_eq!(pow_with_saturation(min_base, 100).get(), 1);
        assert_eq!(pow_with_saturation(min_base, u32::MAX).get(), 1);
    }

    #[test]
    fn test_maximum_exponent() {
        // Test with maximum exponent value
        let base = NonZeroU32::new(2).unwrap();
        // 2^u32::MAX would definitely overflow, should saturate
        assert_eq!(pow_with_saturation(base, u32::MAX).get(), u32::MAX);

        let base_10 = NonZeroU32::new(10).unwrap();
        assert_eq!(pow_with_saturation(base_10, u32::MAX).get(), u32::MAX);
    }

    #[test]
    fn test_const_evaluation() {
        // Verify the function can be used in const contexts
        const BASE: NonZeroU32 = unsafe { NonZeroU32::new_unchecked(2) };
        const RESULT: NonZeroU32 = pow_with_saturation(BASE, 3);
        assert_eq!(RESULT.get(), 8);

        const BASE2: NonZeroU32 = unsafe { NonZeroU32::new_unchecked(10) };
        const RESULT2: NonZeroU32 = pow_with_saturation(BASE2, 2);
        assert_eq!(RESULT2.get(), 100);
    }

    #[test]
    fn test_edge_cases() {
        // Test various edge cases
        let base = NonZeroU32::new(3).unwrap();

        // 3^19 = 1,162,261,467 which is < u32::MAX
        assert_eq!(pow_with_saturation(base, 19).get(), 1162261467);

        // 3^20 = 3,486,784,401 which is > u32::MAX (3,486,784,401 > 4,294,967,295)
        // Actually wait, let me recalculate: 3^20 = 3,486,784,401 which is indeed > u32::MAX
        // But u32::MAX = 4,294,967,295, so 3^20 = 3,486,784,401 is actually < u32::MAX
        // My mistake, 3^20 doesn't overflow u32

        // Let's test with a base that definitely overflows
        let base_100 = NonZeroU32::new(100).unwrap();
        // 100^5 = 10,000,000,000 which is > u32::MAX
        assert_eq!(pow_with_saturation(base_100, 5).get(), u32::MAX);
    }

    #[test]
    fn test_powers_of_two() {
        // Test powers of two up to the point of saturation
        let base = NonZeroU32::new(2).unwrap();

        // 2^0 through 2^31 should not saturate
        let mut expected = 1u32;
        for exp in 0..=31 {
            assert_eq!(pow_with_saturation(base, exp).get(), expected);
            if exp < 31 {
                expected = expected.checked_mul(2).unwrap();
            }
        }

        // 2^32 should saturate
        assert_eq!(pow_with_saturation(base, 32).get(), u32::MAX);

        // Higher exponents should also saturate
        assert_eq!(pow_with_saturation(base, 33).get(), u32::MAX);
        assert_eq!(pow_with_saturation(base, 100).get(), u32::MAX);
    }
}

