use std::collections::HashMap;

fn extract_zero_values_and_count(map: &mut HashMap<String, u32>) -> (Vec<(String, u32)>, usize) {
    let mut extracted = Vec::new();
    let mut extractor = map.extract_if(|_, v| *v == 0);

    while let Some(item) = extractor.next() {
        extracted.push(item);
    }

    (extracted, map.len())
}

