#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    #[test]
    fn test_empty_map() {
        let mut map: HashMap<String, u32> = HashMap::new();
        let (extracted, count) = extract_zero_values_and_count(&mut map);

        assert!(extracted.is_empty());
        assert_eq!(count, 0);
        assert!(map.is_empty());
    }

    #[test]
    fn test_no_zero_values() {
        let mut map = HashMap::from([
            ("one".to_string(), 1),
            ("two".to_string(), 2),
            ("three".to_string(), 3),
        ]);

        let original_keys: Vec<_> = map.keys().cloned().collect();
        let (extracted, count) = extract_zero_values_and_count(&mut map);

        assert!(extracted.is_empty());
        assert_eq!(count, 3);
        assert_eq!(map.len(), 3);
        for key in original_keys {
            assert!(map.contains_key(&key));
        }
    }

    #[test]
    fn test_all_zero_values() {
        let mut map = HashMap::from([
            ("a".to_string(), 0),
            ("b".to_string(), 0),
            ("c".to_string(), 0),
        ]);

        let (extracted, count) = extract_zero_values_and_count(&mut map);

        assert_eq!(extracted.len(), 3);
        assert_eq!(count, 0);
        assert!(map.is_empty());

        let extracted_keys: Vec<_> = extracted.iter().map(|(k, _)| k).collect();
        assert!(extracted_keys.contains(&&"a".to_string()));
        assert!(extracted_keys.contains(&&"b".to_string()));
        assert!(extracted_keys.contains(&&"c".to_string()));

        for (_, value) in extracted {
            assert_eq!(value, 0);
        }
    }

    #[test]
    fn test_mixed_values() {
        let mut map = HashMap::from([
            ("keep1".to_string(), 1),
            ("remove".to_string(), 0),
            ("keep2".to_string(), 2),
            ("remove2".to_string(), 0),
            ("keep3".to_string(), 3),
        ]);

        let (extracted, count) = extract_zero_values_and_count(&mut map);

        assert_eq!(extracted.len(), 2);
        assert_eq!(count, 3);
        assert_eq!(map.len(), 3);

        let extracted_keys: Vec<_> = extracted.iter().map(|(k, _)| k).collect();
        assert!(extracted_keys.contains(&&"remove".to_string()));
        assert!(extracted_keys.contains(&&"remove2".to_string()));

        assert!(map.contains_key("keep1"));
        assert!(map.contains_key("keep2"));
        assert!(map.contains_key("keep3"));
        assert!(!map.contains_key("remove"));
        assert!(!map.contains_key("remove2"));

        for (_, value) in extracted {
            assert_eq!(value, 0);
        }
    }

    #[test]
    fn test_large_map() {
        let mut map = HashMap::new();
        let mut expected_extracted = Vec::new();
        let mut expected_remaining = Vec::new();

        for i in 0..1000 {
            let key = format!("key{}", i);
            if i % 3 == 0 {
                map.insert(key.clone(), 0);
                expected_extracted.push((key, 0));
            } else {
                map.insert(key.clone(), i as u32);
                expected_remaining.push(key);
            }
        }

        let (extracted, count) = extract_zero_values_and_count(&mut map);

        let expected_removed_count = 334; // floor(1000/3) + 1 for i=0
        let expected_remaining_count = 666;

        assert_eq!(extracted.len(), expected_removed_count);
        assert_eq!(count, expected_remaining_count);
        assert_eq!(map.len(), expected_remaining_count);

        for key in expected_remaining {
            assert!(map.contains_key(&key));
        }

        for (key, value) in extracted {
            assert_eq!(value, 0);
            assert!(!map.contains_key(&key));
        }
    }

    #[test]
    fn test_string_cloning_preserved() {
        let mut map = HashMap::new();
        let original_string = "test".to_string();
        map.insert(original_string.clone(), 0);

        let (extracted, _) = extract_zero_values_and_count(&mut map);

        assert_eq!(extracted.len(), 1);
        assert_eq!(extracted[0].0, "test");
        assert_eq!(extracted[0].1, 0);
    }

    #[test]
    fn test_mutability_preserved() {
        let mut map = HashMap::from([
            ("one".to_string(), 1),
            ("zero".to_string(), 0),
            ("two".to_string(), 2),
        ]);

        let (extracted, count) = extract_zero_values_and_count(&mut map);

        assert_eq!(extracted.len(), 1);
        assert_eq!(count, 2);

        // Verify we can still mutate the map
        map.insert("three".to_string(), 3);
        assert_eq!(map.len(), 3);

        // Verify extracted values are correct
        assert_eq!(extracted[0].0, "zero");
        assert_eq!(extracted[0].1, 0);
    }
}

