            assert_eq!(result, value, "Positive value should remain unchanged");
            assert!(!overflow, "Positive value should not overflow");
        }
    }

    #[test]
    fn test_negative_values_no_overflow() {
        // Test negative values that don't cause overflow
        let test_cases = [
            (NonZeroI32::new(-1).unwrap(), NonZeroI32::new(1).unwrap()),
            (NonZeroI32::new(-42).unwrap(), NonZeroI32::new(42).unwrap()),
            (NonZeroI32::new(-i32::MAX).unwrap(), NonZeroI32::new(i32::MAX).unwrap()),
        ];

        for (input, expected) in test_cases {
            let (result, overflow) = safe_overflowing_abs(input);
            assert_eq!(result, expected, "Absolute value mismatch");
            assert!(!overflow, "Should not overflow for negative values except i32::MIN");
        }
