            // This should compile without issues since result is NonZeroI32
            // We can't directly test NonZeroI32 for zero, but we can verify it's valid
            assert!(result.get() != 0, "Result should never be zero");
        }
    }

    #[test]
    fn test_overflowing_abs_behavior_matches_std() {
        // Verify that our wrapper matches the standard library's behavior
        let test_values = [
            1,
            -1,
            42,
            -42,
            i32::MAX,
            -i32::MAX,
            i32::MIN,
        ];

        for &val in &test_values {
            let nz = NonZeroI32::new(val).unwrap();
            let (our_result, our_overflow) = safe_overflowing_abs(nz);

            // Compare with standard library's i32::overflowing_abs
            let (std_result, std_overflow) = val.overflowing_abs();

            assert_eq!(
                our_overflow, std_overflow,
                "Overflow flag mismatch for value {}",
                val
            );

            // Note: For i32::MIN, std_result will be i32::MIN (due to overflow)
            // and our_result will be NonZeroI32::new(i32::MIN).unwrap()
            assert_eq!(
                our_result.get(), std_result,
                "Result value mismatch for value {}",
                val
            );
        }
    }

    #[test]
    fn test_original_value_not_consumed() {
        // Verify we can still use the original value after calling the function
        let original = NonZeroI32::new(-42).unwrap();
        let (result, _) = safe_overflowing_abs(original);

        // Both should be valid and accessible
        assert_eq!(original.get(), -42);
        assert_eq!(result.get(), 42);
    }
}

