mod tests {
    use std::num::NonZeroU64;

    use super::secure_increment;

    #[test]
    fn test_basic_increment() {
        let nz = NonZeroU64::new(5).unwrap();
        let result = secure_increment(nz, 3);
        assert_eq!(result.get(), 8);
    }

    #[test]
    fn test_zero_delta() {
        let nz = NonZeroU64::new(42).unwrap();
        let result = secure_increment(nz, 0);
        assert_eq!(result.get(), 42);
    }

    #[test]
    fn test_saturation_at_max() {
        let max = NonZeroU64::new(u64::MAX).unwrap();
        let result = secure_increment(max, 1);
        assert_eq!(result.get(), u64::MAX);
    }

    #[test]
    fn test_saturation_near_max() {
        let near_max = NonZeroU64::new(u64::MAX - 10).unwrap();
        let result = secure_increment(near_max, 20);
        assert_eq!(result.get(), u64::MAX);
    }

    #[test]
    fn test_no_wrap_to_zero() {
        let nz = NonZeroU64::new(1).unwrap();
        let result = secure_increment(nz, u64::MAX);
        assert_eq!(result.get(), u64::MAX);
    }

    #[test]
    fn test_large_delta_no_overflow() {
        let nz = NonZeroU64::new(1000).unwrap();
        let result = secure_increment(nz, u64::MAX - 500);
        assert_eq!(result.get(), u64::MAX);
    }

    #[test]
    fn test_min_value_increment() {
        let min = NonZeroU64::new(1).unwrap();
        let result = secure_increment(min, 1);
        assert_eq!(result.get(), 2);
    }

    #[test]
    fn test_exact_boundary() {
        let boundary = NonZeroU64::new(u64::MAX - 100).unwrap();
        let result = secure_increment(boundary, 100);
        assert_eq!(result.get(), u64::MAX);
    }

    #[test]
    fn test_non_saturating_addition() {
        let nz = NonZeroU64::new(100).unwrap();
        let result = secure_increment(nz, 200);
        assert_eq!(result.get(), 300);
    }

    #[test]
    fn test_chain_increments() {
        let mut nz = NonZeroU64::new(10).unwrap();
        nz = secure_increment(nz, 20);
        assert_eq!(nz.get(), 30);
        nz = secure_increment(nz, 30);
        assert_eq!(nz.get(), 60);
        nz = secure_increment(nz, u64::MAX - 60);
        assert_eq!(nz.get(), u64::MAX);
    }

    #[test]
    fn test_preserves_non_zero_property() {
        let test_cases = vec![
            (NonZeroU64::new(1).unwrap(), 0),
            (NonZeroU64::new(1).unwrap(), 1),
            (NonZeroU64::new(1).unwrap(), u64::MAX),
            (NonZeroU64::new(u64::MAX).unwrap(), 0),
            (NonZeroU64::new(u64::MAX).unwrap(), 1),
            (NonZeroU64::new(500).unwrap(), 500),
        ];

        for (input, delta) in test_cases {
            let result = secure_increment(input, delta);
            assert!(result.get() > 0, "Result should always be non-zero");
        }
    }

    #[test]
    fn test_edge_case_max_minus_one() {
        let nz = NonZeroU64::new(u64::MAX - 1).unwrap();
        let result = secure_increment(nz, 1);
        assert_eq!(result.get(), u64::MAX);

        let result2 = secure_increment(nz, 2);
        assert_eq!(result2.get(), u64::MAX);
    }
}

