            (1, u32::MAX),
            (u32::MAX, 1),
            (2, 3),
            (100, 100),
            (u32::MAX / 2, 2),
        ];

        for (x, y) in cases {
            let a = NonZeroU32::new(x).unwrap();
            let b = NonZeroU32::new(y).unwrap();
            assert!(saturating_scalar_mul(a, b).get() != 0);
        }
    }
}

