use std::io::{self, Write, Stdout};

fn write_lines_to_stdout(lines: &[&str]) -> io::Result<()> {
    let stdout = io::stdout();
    let mut handle = stdout.lock();

    for line in lines {
        handle.write_all(line.as_bytes())?;
        handle.write_all(b"\n")?;
    }

    handle.flush()?;
    Ok(())
}

