pub fn optimal_worker_count() -> std::io::Result<NonZeroUsize> {
    match thread::available_parallelism() {
        Ok(count) => Ok(count),
        Err(e) => {
            // If the query fails, fall back to a single worker thread
            // This ensures we always return a valid, non-zero count
            Ok(NonZeroUsize::new(1).unwrap())
        }
    }
