mod tests {
    use super::optimal_worker_count;
    use std::io;
    use std::num::NonZeroUsize;

    // Mock for simulating thread::available_parallelism behavior
    struct MockParallelism {
        should_succeed: bool,
        value: Option<NonZeroUsize>,
        error_kind: Option<io::ErrorKind>,
    }

    impl MockParallelism {
        fn new_success(value: usize) -> Self {
            Self {
                should_succeed: true,
                value: NonZeroUsize::new(value),
                error_kind: None,
            }
        }

        fn new_failure(error_kind: io::ErrorKind) -> Self {
            Self {
                should_succeed: false,
                value: None,
                error_kind: Some(error_kind),
            }
        }

        fn available_parallelism(&self) -> io::Result<NonZeroUsize> {
            if self.should_succeed {
                self.value.ok_or_else(|| {
                    io::Error::new(io::ErrorKind::Other, "Invalid mock configuration")
                })
            } else {
                Err(io::Error::new(
                    self.error_kind.unwrap_or(io::ErrorKind::Other),
                    "Mock error",
                ))
            }
        }
    }

    #[test]
    fn test_successful_query_returns_correct_count() {
        // Test with various valid non-zero values
        let test_cases = vec![
            MockParallelism::new_success(1),
            MockParallelism::new_success(4),
            MockParallelism::new_success(8),
            MockParallelism::new_success(16),
