        let mut lock = stdout.lock();

        // Test with very long message
        let message = "A".repeat(10000);
        write_log_entry(&mut lock, &message)?;

        lock.flush()?;
        Ok(())
    }

    #[test]
    fn test_write_log_entry_concurrent_access() -> io::Result<()> {
        let num_threads = 10;
        let num_messages_per_thread = 100;
        let barrier = Arc::new(Barrier::new(num_threads));

        let handles: Vec<_> = (0..num_threads)
            .map(|thread_id| {
                let barrier = Arc::clone(&barrier);
                thread::spawn(move || -> io::Result<()> {
                    // Wait for all threads to be ready
                    barrier.wait();

                    for i in 0..num_messages_per_thread {
                        let stdout = io::stdout();
                        let mut lock = stdout.lock();
                        let message = format!("Thread {}: Message {}", thread_id, i);
                        write_log_entry(&mut lock, &message)?;
                        // Note: Not flushing here to test buffering behavior
                    }
                    Ok(())
                })
            })
            .collect();

        // Collect results
        let mut all_success = true;
        for handle in handles {
            if let Err(e) = handle.join().unwrap() {
                eprintln!("Thread error: {}", e);
                all_success = false;
            }
        }

        // Final flush
        let stdout = io::stdout();
        let mut lock = stdout.lock();
        lock.flush()?;

        assert!(all_success, "All threads should complete successfully");
        Ok(())
    }

    #[test]
    fn test_write_log_entry_error_handling() {
        // Create a custom writer that fails on write
        struct FailingWriter;

        impl Write for FailingWriter {
            fn write(&mut self, _buf: &[u8]) -> io::Result<usize> {
                Err(io::Error::new(io::ErrorKind::Other, "Write failed"))
            }

            fn flush(&mut self) -> io::Result<()> {
                Ok(())
            }
        }

        // Test that error propagates correctly
        let mut writer = FailingWriter;
        // Note: We need to create a StdoutLock-like wrapper for our custom writer
        // Since write_log_entry expects &mut io::StdoutLock, we'll test the underlying logic instead
        let result = writer.write_all(b"test\n");
        assert!(result.is_err());

        // Verify error kind
        if let Err(e) = result {
            assert_eq!(e.kind(), io::ErrorKind::Other);
        }
    }

    #[test]
    fn test_write_log_entry_newline_appended() -> io::Result<()> {
        // Use a Vec as the output to verify content
        let mut buffer = Vec::new();

        // Create a custom writer that writes to buffer
        struct BufferWriter<'a> {
            buffer: &'a mut Vec<u8>,
        }

        impl<'a> Write for BufferWriter<'a> {
            fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
                self.buffer.extend_from_slice(buf);
                Ok(buf.len())
            }

            fn flush(&mut self) -> io::Result<()> {
                Ok(())
            }
        }

        let mut writer = BufferWriter { buffer: &mut buffer };

        // Since write_log_entry expects &mut io::StdoutLock, we'll test the underlying logic
        let message = "Test message";
        writer.write_all(message.as_bytes())?;
        writer.write_all(b"\n")?;

        // Verify the output
        let expected = format!("{}\n", message);
        assert_eq!(String::from_utf8_lossy(&buffer), expected);

        Ok(())
    }

    #[test]
    fn test_write_log_entry_multiple_calls() -> io::Result<()> {
        let stdout = io::stdout();
        let mut lock = stdout.lock();

        // Test multiple consecutive writes
        let messages = ["First", "Second", "Third", "Fourth"];

        for message in &messages {
            write_log_entry(&mut lock, message)?;
        }

        lock.flush()?;
        Ok(())
    }

    #[test]
    fn test_write_log_entry_with_different_lock_lifetimes() -> io::Result<()> {
        // Test that function works with different lock scopes
        {
            let stdout = io::stdout();
            let mut lock = stdout.lock();
            write_log_entry(&mut lock, "Message in inner scope")?;
            // Lock released here
        }

        // New lock in outer scope
        let stdout = io::stdout();
        let mut lock = stdout.lock();
        write_log_entry(&mut lock, "Message in outer scope")?;

        lock.flush()?;
        Ok(())
    }
}

