            (42u8, 42u16),
            (127u8, 127u16),
            (128u8, 128u16),
            (255u8, 255u16),
        ];

        for (input, expected) in test_cases {
            let sensor_value = NonZeroU8::new(input).unwrap();
            let result = create_lookup_table_entry(sensor_value);
            assert_eq!(result.get(), expected);
        }
    }

    #[test]
    fn test_nonzero_property_preserved() {
        // Ensure the NonZero property is preserved through the conversion
        let sensor_value = NonZeroU8::new(1).unwrap();
        let result = create_lookup_table_entry(sensor_value);

        // This should compile without issues since NonZeroU16 guarantees non-zero
        let _: NonZeroU16 = result;

        // Verify the value is indeed non-zero
        assert_ne!(result.get(), 0);
    }

    #[test]
    fn test_const_compatibility() {
        // Demonstrate that the function can be used in const context
        const SENSOR_VALUE: NonZeroU8 = unsafe { NonZeroU8::new_unchecked(100) };
        // Use the conversion directly since create_lookup_table_entry is not const
        // For const context, we need to use the underlying value conversion
        const LOOKUP_ENTRY: NonZeroU16 = unsafe { NonZeroU16::new_unchecked(SENSOR_VALUE.get() as u16) };

        // Verify the const evaluation
        assert_eq!(LOOKUP_ENTRY.get(), 100);
    }

    #[test]
    fn test_all_nonzero_u8_values() {
        // Test all possible NonZeroU8 values (1-255)
        for value in 1..=255 {
            let sensor_value = NonZeroU8::new(value).unwrap();
            let result = create_lookup_table_entry(sensor_value);
            assert_eq!(result.get(), value as u16);
        }
    }

