        // Verify the function takes ownership of the input
        let sensor_value = NonZeroU8::new(50).unwrap();
        let result = create_lookup_table_entry(sensor_value);

        // sensor_value is moved, so we can't use it here
        // This is expected behavior
        assert_eq!(result.get(), 50);
    }

    #[test]
    fn test_from_trait_implementation() {
        // Verify the function uses the From trait implementation correctly
        let sensor_value = NonZeroU8::new(200).unwrap();
        let via_function = create_lookup_table_entry(sensor_value);

        let sensor_value2 = NonZeroU8::new(200).unwrap();
        let via_from_trait = NonZeroU16::from(sensor_value2);

        assert_eq!(via_function, via_from_trait);
