mod tests {
    use super::*;

    #[test]
    fn test_basic_multiplication() {
        // Basic cases without overflow
        unsafe {
            assert_eq!(fast_mul_without_overflow(0, 100), 0);
            assert_eq!(fast_mul_without_overflow(1, 100), 100);
            assert_eq!(fast_mul_without_overflow(100, 1), 100);
            assert_eq!(fast_mul_without_overflow(10, 20), 200);
            assert_eq!(fast_mul_without_overflow(100, 200), 20000);
        }
    }

    #[test]
    fn test_max_values_no_overflow() {
        // Cases where product doesn't overflow u32::MAX
        unsafe {
            assert_eq!(fast_mul_without_overflow(1, u32::MAX), u32::MAX);
            assert_eq!(fast_mul_without_overflow(u32::MAX, 1), u32::MAX);
            assert_eq!(fast_mul_without_overflow(2, u32::MAX / 2), u32::MAX - 1);
            assert_eq!(fast_mul_without_overflow(65535, 65537), 4294967295u32);
        }
    }

    #[test]
    fn test_powers_of_two() {
        // Multiplications with powers of two
        unsafe {
            assert_eq!(fast_mul_without_overflow(2, 2), 4);
            assert_eq!(fast_mul_without_overflow(256, 256), 65536);
            assert_eq!(fast_mul_without_overflow(1024, 1024), 1048576);
            // 1 << 16 * 1 << 16 = 1 << 32 = 4294967296, which wraps to 0 in u32
            // This test case is removed as it causes overflow
        }
    }

    #[test]
    fn test_commutative_property() {
        // Verify multiplication is commutative
        unsafe {
            let a = 12345;
            let b = 67890;
            assert_eq!(
                fast_mul_without_overflow(a, b),
                fast_mul_without_overflow(b, a)
            );
        }
    }

    #[test]
    fn test_identity_properties() {
        // Test multiplicative identity (1) and zero property
        unsafe {
            let value = 123456;
            assert_eq!(fast_mul_without_overflow(value, 1), value);
            assert_eq!(fast_mul_without_overflow(1, value), value);
            assert_eq!(fast_mul_without_overflow(value, 0), 0);
            assert_eq!(fast_mul_without_overflow(0, value), 0);
        }
    }

    #[test]
    fn test_large_numbers_no_overflow() {
        // Large multiplications that stay within bounds
        unsafe {
            assert_eq!(fast_mul_without_overflow(50000, 80000), 4000000000u32);
            assert_eq!(fast_mul_without_overflow(70000, 60000), 4200000000u32);
            assert_eq!(fast_mul_without_overflow(46340, 46340), 2147395600u32);
        }
    }

    #[test]
    fn test_edge_cases() {
        // Edge cases and boundary values
        unsafe {
            assert_eq!(fast_mul_without_overflow(u32::MAX, 0), 0);
            assert_eq!(fast_mul_without_overflow(0, u32::MAX), 0);
            assert_eq!(fast_mul_without_overflow(1, 1), 1);
            assert_eq!(fast_mul_without_overflow(2, 3), 6);
        }
    }

    #[test]
    fn test_sequential_multiplications() {
        // Test chained multiplications
        unsafe {
            let mut result = 1u32;
            for i in 1..=10 {
                result = fast_mul_without_overflow(result, i as u32);
            }
            // 10! = 3628800
            assert_eq!(result, 3628800u32);
        }
    }

    // Note: We cannot test overflow cases because the function is unsafe
    // and assumes overflow won't occur. Testing overflow would be undefined behavior.
    // The caller is responsible for ensuring no overflow occurs.
}

