fn extract_valid_prefix(bytes: &[u8]) -> &str {
    std::str::from_utf8(bytes).unwrap_or_else(|error| {
        let (valid, _) = bytes.split_at(error.valid_up_to());
        unsafe { std::str::from_utf8_unchecked(valid) }
    })
}

