        let bytes: &[u8] = &[b'H', b'e', b'l', b'l', b'o', 0xFF];
        let result = extract_valid_prefix(bytes);
        assert_eq!(result, "Hello");
        assert_eq!(result.len(), 5);
    }

    #[test]
    fn test_partial_utf8_sequence() {
        // Start of a 2-byte UTF-8 character but missing continuation byte
        let bytes: &[u8] = &[b'A', 0xC2, b'B']; // 0xC2 should be followed by continuation byte
        let result = extract_valid_prefix(bytes);
        assert_eq!(result, "A");
        assert_eq!(result.len(), 1);
    }

    #[test]
    fn test_multibyte_utf8_boundary() {
        // Valid 3-byte UTF-8 character followed by invalid byte
        let bytes = "a€".as_bytes(); // '€' is 3 bytes: 0xE2 0x82 0xAC
        let mut modified = bytes.to_vec();
        modified.push(0xFF); // Add invalid byte at end
        let result = extract_valid_prefix(&modified);
        assert_eq!(result, "a€");
        assert_eq!(result.len(), 4); // 'a' (1 byte) + '€' (3 bytes)
    }

    #[test]
    fn test_only_invalid_bytes() {
        let bytes: &[u8] = &[0xFF, 0xFE, 0xC0];
        let result = extract_valid_prefix(bytes);
        assert_eq!(result, "");
        assert_eq!(result.len(), 0);
    }

    #[test]
