        // Invalid, then valid UTF-8
        let mut bytes_vec = vec![0xFF];
        bytes_vec.extend_from_slice("世界".as_bytes());
        let result = extract_valid_prefix(&bytes_vec);
        assert_eq!(result, "");
        assert_eq!(result.len(), 0);
    }

    #[test]
    fn test_multiple_invalid_sequences() {
        // Valid, invalid, valid, invalid
        let bytes: &[u8] = &[b'A', 0xFF, b'B', 0xFE, b'C'];
        let result = extract_valid_prefix(bytes);
        assert_eq!(result, "A");
        assert_eq!(result.len(), 1);
    }

    #[test]
    fn test_complete_utf8_sequences_with_invalid_in_between() {
        let bytes = "Hello世界".as_bytes();
        let mut modified = bytes.to_vec();
        // Insert invalid byte between characters
        modified.insert(5, 0xFF); // After "Hello", before "世界"
        let result = extract_valid_prefix(&modified);
        assert_eq!(result, "Hello");
        assert_eq!(result.len(), 5);
    }

    #[test]
    fn test_large_valid_prefix() {
        let mut bytes = vec![b'a'; 1000];
        bytes.push(0xFF); // Invalid byte at the end
        bytes.extend_from_slice(b"trailing");

        let result = extract_valid_prefix(&bytes);
        assert_eq!(result.len(), 1000);
        assert!(result.chars().all(|c| c == 'a'));
    }

    #[test]
    fn test_slice_from_string() {
        let s = "Hello, 世界!";
        let bytes = s.as_bytes();
        let result = extract_valid_prefix(bytes);
        assert_eq!(result, s);
        assert_eq!(result.as_ptr(), s.as_ptr()); // Should be same memory location
    }

    #[test]
    fn test_borrowed_result_lifetime() {
        let bytes = b"Hello";
        let result = extract_valid_prefix(bytes);
        // The result should borrow from the input
        assert_eq!(result.as_ptr(), bytes.as_ptr());
    }
}

