fn optimize_vector_append(vectors: &mut [Vec<i32>], elements: &[i32]) -> usize {
    let mut total_appended = 0;

    for vec in vectors.iter_mut() {
        let original_len = vec.len();
        vec.reserve(elements.len());

        for &element in elements {
            vec.push(element);
        }

        total_appended += vec.len() - original_len;
    }

    total_appended
}

