    fn test_single_vector() {
        let mut vectors = vec![vec![1, 2, 3]];
        let elements = [4, 5];
        let result = optimize_vector_append(&mut vectors, &elements);
        assert_eq!(result, 2);
        assert_eq!(vectors[0], vec![1, 2, 3, 4, 5]);
    }

    #[test]
    fn test_multiple_vectors() {
        let mut vectors = vec![vec![1], vec![2, 3], vec![]];
        let elements = [4, 5, 6];
        let result = optimize_vector_append(&mut vectors, &elements);
        assert_eq!(result, 9);
        assert_eq!(vectors[0], vec![1, 4, 5, 6]);
        assert_eq!(vectors[1], vec![2, 3, 4, 5, 6]);
        assert_eq!(vectors[2], vec![4, 5, 6]);
    }

    #[test]
    fn test_large_elements() {
        let mut vectors = vec![vec![]; 3];
        let elements: Vec<i32> = (0..1000).collect();
        let result = optimize_vector_append(&mut vectors, &elements);
        assert_eq!(result, 3000);
        for vec in &vectors {
            assert_eq!(vec.len(), 1000);
            assert_eq!(vec.capacity() >= 1000, true);
        }
    }

    #[test]
    fn test_already_has_capacity() {
        let mut vectors = vec![Vec::with_capacity(10), Vec::with_capacity(20)];
        vectors[0].extend([1, 2, 3]);
        vectors[1].extend([4, 5]);

        let original_caps = vectors.iter().map(|v| v.capacity()).collect::<Vec<_>>();
        let elements = [6, 7];
        let result = optimize_vector_append(&mut vectors, &elements);

        assert_eq!(result, 4);
        assert_eq!(vectors[0], vec![1, 2, 3, 6, 7]);
        assert_eq!(vectors[1], vec![4, 5, 6, 7]);
        assert_eq!(vectors[0].capacity(), original_caps[0]);
        assert_eq!(vectors[1].capacity(), original_caps[1]);
    }

    #[test]
    fn test_needs_reallocation() {
        let mut vectors = vec![vec![1, 2, 3, 4, 5]];
        let original_capacity = vectors[0].capacity();
        let elements: Vec<i32> = (6..20).collect();
        let result = optimize_vector_append(&mut vectors, &elements);

        assert_eq!(result, 14);
        assert_eq!(vectors[0].len(), 19);
        assert!(vectors[0].capacity() >= 19);
        assert!(vectors[0].capacity() > original_capacity);
    }

