    fn test_total_appended_calculation() {
        let mut vectors = vec![vec![1], vec![], vec![2, 3, 4]];
        let elements = [5, 6];
        let result = optimize_vector_append(&mut vectors, &elements);

        let expected_total = vectors.iter().map(|v| v.len()).sum::<usize>() - 
                           vectors.iter().map(|v| v.len() - 2).sum::<usize>();
        assert_eq!(result, expected_total);
        assert_eq!(result, 6);
    }

    #[test]
    fn test_preserves_existing_elements() {
        let mut vectors = vec![vec![1, 2, 3], vec![4, 5]];
        let original_first = vectors[0].clone();
        let original_second = vectors[1].clone();
        let elements = [6, 7, 8];

        optimize_vector_append(&mut vectors, &elements);

        assert_eq!(vectors[0][0..3], original_first[..]);
        assert_eq!(vectors[1][0..2], original_second[..]);
    }

