#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_rotate_bits_right_zero_rotation() {
        assert_eq!(rotate_bits_right(0x123456789ABCDEF0, 0), 0x123456789ABCDEF0);
        assert_eq!(rotate_bits_right(0xFFFFFFFFFFFFFFFF, 0), 0xFFFFFFFFFFFFFFFF);
        assert_eq!(rotate_bits_right(0x0000000000000000, 0), 0x0000000000000000);
    }

    #[test]
    fn test_rotate_bits_right_small_rotation() {
        // Test 1-bit rotation
        assert_eq!(rotate_bits_right(0x8000000000000000, 1), 0x4000000000000000);
        assert_eq!(rotate_bits_right(0x0000000000000001, 1), 0x8000000000000000);

        // Test 4-bit rotation
        assert_eq!(rotate_bits_right(0x123456789ABCDEF0, 4), 0x0123456789ABCDEF);
        assert_eq!(rotate_bits_right(0xFEDCBA9876543210, 4), 0x0FEDCBA987654321);
    }

    #[test]
    fn test_rotate_bits_right_exact_width_rotation() {
        // Rotating by 64 should return the original value
        assert_eq!(rotate_bits_right(0x123456789ABCDEF0, 64), 0x123456789ABCDEF0);
        assert_eq!(rotate_bits_right(0xFFFFFFFFFFFFFFFF, 64), 0xFFFFFFFFFFFFFFFF);
        assert_eq!(rotate_bits_right(0x0000000000000000, 64), 0x0000000000000000);
    }

    #[test]
    fn test_rotate_bits_right_multiple_width_rotation() {
        // Rotating by multiples of 64 should return the original value
        assert_eq!(rotate_bits_right(0x123456789ABCDEF0, 128), 0x123456789ABCDEF0);
        assert_eq!(rotate_bits_right(0xAAAAAAAAAAAAAAAA, 192), 0xAAAAAAAAAAAAAAAA);
        assert_eq!(rotate_bits_right(0x5555555555555555, 256), 0x5555555555555555);
    }

    #[test]
    fn test_rotate_bits_right_large_rotation() {
        // Test rotation counts larger than 64
        assert_eq!(rotate_bits_right(0x123456789ABCDEF0, 65), rotate_bits_right(0x123456789ABCDEF0, 1));
        assert_eq!(rotate_bits_right(0xAAAAAAAAAAAAAAAA, 100), rotate_bits_right(0xAAAAAAAAAAAAAAAA, 36));
        assert_eq!(rotate_bits_right(0xFFFFFFFFFFFFFFFF, 255), rotate_bits_right(0xFFFFFFFFFFFFFFFF, 63));
    }

    #[test]
    fn test_rotate_bits_right_max_rotation() {
        // Test with maximum u32 rotation value
        assert_eq!(rotate_bits_right(0x123456789ABCDEF0, u32::MAX), rotate_bits_right(0x123456789ABCDEF0, u32::MAX % 64));
        assert_eq!(rotate_bits_right(0xFFFFFFFFFFFFFFFF, u32::MAX), rotate_bits_right(0xFFFFFFFFFFFFFFFF, u32::MAX % 64));
    }

    #[test]
    fn test_rotate_bits_right_symmetry() {
        // Verify that rotating right by n then left by n returns original
        let value = 0x123456789ABCDEF0;
        for n in 0..=128 {
            let rotated = rotate_bits_right(value, n);
            let restored = rotated.rotate_left(n);
            assert_eq!(value, restored, "Failed symmetry test for n = {}", n);
        }
    }

    #[test]
    fn test_rotate_bits_right_edge_cases() {
        // Test with all bits set
        assert_eq!(rotate_bits_right(0xFFFFFFFFFFFFFFFF, 1), 0xFFFFFFFFFFFFFFFF);
        assert_eq!(rotate_bits_right(0xFFFFFFFFFFFFFFFF, 32), 0xFFFFFFFFFFFFFFFF);

        // Test with alternating bits
        assert_eq!(rotate_bits_right(0xAAAAAAAAAAAAAAAA, 1), 0x5555555555555555);
        assert_eq!(rotate_bits_right(0x5555555555555555, 1), 0xAAAAAAAAAAAAAAAA);

        // Test with single bit set
        for i in 0..64 {
            let value = 1u64 << i;
            for n in 0..64 {
                let expected = if i >= n {
                    1u64 << (i - n)
                } else {
                    1u64 << (64 - n + i)
                };
                assert_eq!(rotate_bits_right(value, n), expected, 
                          "Failed for bit position {} rotated by {}", i, n);
            }
        }
    }

    #[test]
    fn test_rotate_bits_right_consistency() {
        // Verify that rotate_right matches manual calculation for various values
        let test_values = [
            0x123456789ABCDEF0,
            0xFEDCBA9876543210,
            0x0000000000000000,
            0xFFFFFFFFFFFFFFFF,
            0xAAAAAAAAAAAAAAAA,
            0x5555555555555555,
            0x8000000000000000,
            0x0000000000000001,
        ];

        for &value in &test_values {
            for n in 0..=96 { // Test up to 1.5 times the bit width
                let manual_rotate = if n % 64 == 0 {
                    value
                } else {
                    let n = n % 64;
                    (value >> n) | (value << (64 - n))
                };
                assert_eq!(rotate_bits_right(value, n), manual_rotate,
                          "Failed for value {:016x} rotated by {}", value, n);
            }
        }
    }
}

