        let mut numbers = Vec::new();
        for i in 0..=63 {
            numbers.push(1u64 << i);
        }
        // Each number has exactly i trailing zeros
        for i in 0..=63 {
            assert_eq!(count_numbers_with_k_trailing_zeros(&numbers, i), 1);
        }
