    }

    #[test]
    fn test_large_input() {
        // Create a large vector with predictable pattern
        let size = 10000;
        let mut numbers = Vec::with_capacity(size);
        for i in 0..size {
            numbers.push(i as u64);
        }

        // Count numbers with exactly 1 trailing zero manually
        let mut expected_count = 0;
        for &n in &numbers {
            if n.trailing_zeros() == 1 {
                expected_count += 1;
            }
        }

        assert_eq!(
            count_numbers_with_k_trailing_zeros(&numbers, 1),
            expected_count
        );
    }

    #[test]
    fn test_edge_case_max_u64() {
        let numbers = [u64::MAX];
        // u64::MAX has binary representation of all 1s, so 0 trailing zeros
        assert_eq!(count_numbers_with_k_trailing_zeros(&numbers, 0), 1);
        assert_eq!(count_numbers_with_k_trailing_zeros(&numbers, 1), 0);
        assert_eq!(count_numbers_with_k_trailing_zeros(&numbers, 64), 0);
    }

    #[test]
    fn test_pattern_of_alternating_trailing_zeros() {
        // Create numbers with specific trailing zero patterns
        let numbers = [
            0b0001u64,  // 0 trailing zeros
            0b0010u64,  // 1 trailing zero
            0b0100u64,  // 2 trailing zeros
            0b1000u64,  // 3 trailing zeros
            0b0001u64,  // 0 trailing zeros
            0b0010u64,  // 1 trailing zero
        ];

        assert_eq!(count_numbers_with_k_trailing_zeros(&numbers, 0), 2);
        assert_eq!(count_numbers_with_k_trailing_zeros(&numbers, 1), 2);
        assert_eq!(count_numbers_with_k_trailing_zeros(&numbers, 2), 1);
        assert_eq!(count_numbers_with_k_trailing_zeros(&numbers, 3), 1);
    }
}

