pub fn max_digits_in_base(numbers: &[u128], base: u128) -> Option<u32> {
    if base <= 1 {
        return None;
    }

    let max_value = numbers.iter().max().copied().unwrap_or(0);

    // For zero, we need 1 digit (the digit '0')
    if max_value == 0 {
        return Some(1);
    }

    // Use checked_ilog to get floor(log_base(max_value))
    // Then add 1 to get the number of digits needed
    max_value.checked_ilog(base).map(|log| log + 1)
}

