#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, Barrier};
    use std::thread;

    #[test]
    fn test_get_config_returns_static_reference() {
        // Test that the function returns a 'static reference
        let config = get_config("test_path");
        // Verify it's actually a reference to Config
        let _: &Config = config;

        // The function should return the same reference type regardless of path
        let config2 = get_config("different_path");
        assert!(std::ptr::eq(config, config2));
    }

    #[test]
    fn test_get_config_ignores_path_parameter() {
        // The path parameter should be ignored since LazyLock initializes only once
        let config1 = get_config("path1");
        let config2 = get_config("path2");
        let config3 = get_config("");

        // All should return the same reference
        assert!(std::ptr::eq(config1, config2));
        assert!(std::ptr::eq(config2, config3));
    }

    #[test]
    fn test_config_is_globally_accessible() {
        // Test that multiple calls return the same config instance
        let config_ref1 = get_config("any_path");
        let config_ref2 = get_config("any_other_path");

        // They should be the same reference (same memory address)
        assert!(std::ptr::eq(config_ref1, config_ref2));
    }

    #[test]
    fn test_concurrent_access() {
        // Test that concurrent access works correctly
        const NUM_THREADS: usize = 10;
        let barrier = Arc::new(Barrier::new(NUM_THREADS));
        let config_refs = Arc::new(std::sync::Mutex::new(Vec::new()));

        let mut handles = vec![];

        for _ in 0..NUM_THREADS {
            let barrier = Arc::clone(&barrier);
            let config_refs = Arc::clone(&config_refs);

            let handle = thread::spawn(move || {
                barrier.wait(); // Synchronize all threads
                let config = get_config("concurrent_path");

                let mut refs = config_refs.lock().unwrap();
                // Store as usize instead of raw pointer to avoid Send issues
                refs.push(config as *const Config as usize);
            });

            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        let refs = config_refs.lock().unwrap();
        // All threads should have gotten the same reference
        let first_ref = refs[0];
        for &config_ref in refs.iter() {
            assert_eq!(config_ref, first_ref);
        }
    }

    #[test]
    fn test_config_initialized_only_once() {
        // We can't directly test the initialization count without modifying the code,
        // but we can verify that multiple calls return the same instance
        let addresses: Vec<usize> = (0..100)
            .map(|i| get_config(&format!("path_{}", i)) as *const Config as usize)
            .collect();

        let first_address = addresses[0];
        for &addr in &addresses {
            assert_eq!(addr, first_address);
        }
    }

    #[test]
    fn test_empty_path() {
        // Test with empty string path
        let config = get_config("");
        let _: &Config = config; // Type check
    }

    #[test]
    fn test_path_with_special_characters() {
        // Test with various path formats
        let paths = [
            "/absolute/path/config.json",
            "relative/path/config.toml",
            "C:\\Windows\\Path\\config.ini",
            "file:///etc/config.yaml",
            "../parent/../config.json",
        ];

        let first_config = get_config(paths[0]);
        for path in &paths[1..] {
            let config = get_config(path);
            assert!(std::ptr::eq(first_config, config));
        }
    }

    // Helper test to verify the function signature is correct
    #[test]
    fn test_function_signature() {
        // This test just verifies the function can be called with the expected signature
        fn accepts_static_ref(_: &'static Config) {}

        let config = get_config("test");
        accepts_static_ref(config);
    }
}

