#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    #[test]
    fn test_basic_ratios() {
        // Simple integer ratios
        assert_eq!(event_duration_ratio(Duration::from_secs(1), Duration::from_secs(2)), 0.5);
        assert_eq!(event_duration_ratio(Duration::from_secs(2), Duration::from_secs(1)), 2.0);
        assert_eq!(event_duration_ratio(Duration::from_secs(3), Duration::from_secs(3)), 1.0);
    }

    #[test]
    fn test_fractional_seconds() {
        // Ratios with fractional durations
        let dur1 = Duration::from_millis(1500); // 1.5 seconds
        let dur2 = Duration::from_millis(3000); // 3.0 seconds
        assert_eq!(event_duration_ratio(dur1, dur2), 0.5);

        let dur3 = Duration::from_micros(750_000); // 0.75 seconds
        let dur4 = Duration::from_micros(250_000); // 0.25 seconds
        assert_eq!(event_duration_ratio(dur3, dur4), 3.0);
    }

    #[test]
    fn test_large_durations() {
        // Test with large durations to ensure no overflow
        let dur1 = Duration::from_secs(86400); // 1 day
        let dur2 = Duration::from_secs(3600);  // 1 hour
        assert_eq!(event_duration_ratio(dur1, dur2), 24.0);

        let dur3 = Duration::from_secs(3600 * 24 * 365); // ~1 year
        let dur4 = Duration::from_secs(3600 * 24 * 7);   // 1 week
        let expected_ratio = 365.0 / 7.0;
        let result = event_duration_ratio(dur3, dur4);
        assert!((result - expected_ratio).abs() < 1e-10);
    }

    #[test]
    fn test_small_durations() {
        // Test with very small durations
        let dur1 = Duration::from_nanos(100);
        let dur2 = Duration::from_nanos(50);
        assert_eq!(event_duration_ratio(dur1, dur2), 2.0);

        let dur3 = Duration::from_nanos(1);
        let dur4 = Duration::from_nanos(1000);
        assert_eq!(event_duration_ratio(dur3, dur4), 0.001);
    }

    #[test]
    fn test_zero_denominator() {
        // Test edge case where denominator is zero
        // Note: Duration::from_secs(0) creates a zero duration
        let dur1 = Duration::from_secs(5);
        let dur2 = Duration::from_secs(0);

        // div_duration_f64 returns f64::INFINITY for zero denominator
        assert!(event_duration_ratio(dur1, dur2).is_infinite());
        assert!(event_duration_ratio(dur2, dur2).is_nan()); // 0/0 = NaN
    }

    #[test]
    fn test_nanoseconds_precision() {
        // Test that we maintain precision without converting manually
        let dur1 = Duration::new(1, 500_000_000); // 1.5 seconds
        let dur2 = Duration::new(3, 0);           // 3.0 seconds

        // Using div_duration_f64 should give exact 0.5
        let result = event_duration_ratio(dur1, dur2);
        assert!((result - 0.5).abs() < 1e-15);
    }

    #[test]
    fn test_negative_ratio_impossible() {
        // Durations are always non-negative, so ratios should be >= 0
        let dur1 = Duration::from_secs(10);
        let dur2 = Duration::from_secs(20);
        let ratio = event_duration_ratio(dur1, dur2);
        assert!(ratio >= 0.0);
    }

    #[test]
    fn test_commutative_property() {
        // Verify that ratio(a,b) = 1/ratio(b,a)
        let dur1 = Duration::from_secs(7);
        let dur2 = Duration::from_secs(13);

        let ratio1 = event_duration_ratio(dur1, dur2);
        let ratio2 = event_duration_ratio(dur2, dur1);

        assert!((ratio1 * ratio2 - 1.0).abs() < 1e-15);
    }

    #[test]
    fn test_mixed_units() {
        // Test with durations created from different units
        let dur1 = Duration::from_secs(2);
        let dur2 = Duration::from_millis(500);
        assert_eq!(event_duration_ratio(dur1, dur2), 4.0);

        let dur3 = Duration::from_micros(1_000_000);
        let dur4 = Duration::from_nanos(500_000_000);
        assert_eq!(event_duration_ratio(dur3, dur4), 2.0);
    }
}

