        // Test forward offsets
        let ptr1 = unsafe { compute_element_pointer(ptr, 1) };
        assert_eq!(unsafe { *ptr1.as_ptr() }, 2);

        let ptr2 = unsafe { compute_element_pointer(ptr, 2) };
        assert_eq!(unsafe { *ptr2.as_ptr() }, 3);

