    fn test_backward_offset() {
        let mut data = [1, 2, 3, 4, 5];
        let ptr = NonNull::new(&mut data[2] as *mut i32).unwrap(); // Start from middle

        // Test backward offsets
        let ptr_minus1 = unsafe { compute_element_pointer(ptr, -1) };
        assert_eq!(unsafe { *ptr_minus1.as_ptr() }, 2);

        let ptr_minus2 = unsafe { compute_element_pointer(ptr, -2) };
        assert_eq!(unsafe { *ptr_minus2.as_ptr() }, 1);
    }

    #[test]
    fn test_zero_offset() {
        let mut data = [42];
        let ptr = NonNull::new(data.as_mut_ptr()).unwrap();

        let same_ptr = unsafe { compute_element_pointer(ptr, 0) };
        assert_eq!(ptr, same_ptr);
        assert_eq!(unsafe { *same_ptr.as_ptr() }, 42);
    }

    #[test]
    fn test_large_forward_offset() {
        let mut data = vec![0i32; 100];
        data[99] = 999;
        let ptr = NonNull::new(data.as_mut_ptr()).unwrap();

        let ptr_end = unsafe { compute_element_pointer(ptr, 99) };
        assert_eq!(unsafe { *ptr_end.as_ptr() }, 999);
    }

    #[test]
    fn test_large_backward_offset() {
        let mut data = vec![0i32; 100];
        data[0] = 111;
        let ptr = NonNull::new(&mut data[99] as *mut i32).unwrap();

        let ptr_start = unsafe { compute_element_pointer(ptr, -99) };
        assert_eq!(unsafe { *ptr_start.as_ptr() }, 111);
    }

    #[test]
    fn test_pointer_identity() {
        let mut data = [10, 20, 30];
        let ptr = NonNull::new(data.as_mut_ptr()).unwrap();

        let computed_ptr = unsafe { compute_element_pointer(ptr, 1) };
        let expected_ptr = NonNull::new(unsafe { ptr.as_ptr().offset(1) }).unwrap();

        assert_eq!(computed_ptr, expected_ptr);
    }

    #[test]
    fn test_single_element_array() {
        let mut data = [100];
        let ptr = NonNull::new(data.as_mut_ptr()).unwrap();

        // Test various offsets from single element
        let ptr_zero = unsafe { compute_element_pointer(ptr, 0) };
