use std::ptr;

pub fn extract_unaligned_u32(header_slice: &[u8]) -> Option<u32> {
    if header_slice.len() < 4 {
        return None;
    }

    let ptr = header_slice.as_ptr() as *const u32;

    // SAFETY: We have verified the slice has at least 4 bytes,
    // and read_unaligned handles unaligned pointers correctly.
    let value = unsafe { ptr.read_unaligned() };

    Some(value)
}

