#[cfg(test)]
mod tests {
    use super::*;
    use std::mem;

    #[test]
    fn test_extract_unaligned_u32_basic() {
        // Basic aligned case
        let data = [0x01, 0x02, 0x03, 0x04];
        let result = extract_unaligned_u32(&data);
        assert_eq!(result, Some(0x04030201)); // Little-endian interpretation

        // Different values
        let data = [0xFF, 0x00, 0xAA, 0x55];
        let result = extract_unaligned_u32(&data);
        assert_eq!(result, Some(0x55AA00FF));
    }

    #[test]
    fn test_extract_unaligned_u32_insufficient_bytes() {
        // Too short slices
        assert_eq!(extract_unaligned_u32(&[]), None);
        assert_eq!(extract_unaligned_u32(&[0x01]), None);
        assert_eq!(extract_unaligned_u32(&[0x01, 0x02]), None);
        assert_eq!(extract_unaligned_u32(&[0x01, 0x02, 0x03]), None);

        // Exactly 4 bytes should work
        let data = [0x01, 0x02, 0x03, 0x04];
        assert_eq!(extract_unaligned_u32(&data), Some(0x04030201));
    }

    #[test]
    fn test_extract_unaligned_u32_unaligned_access() {
        // Create a larger buffer and test unaligned slices
        let buffer = [0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07];

        // Test all possible 4-byte slices within the buffer
        for start in 0..=4 {
            let slice = &buffer[start..start + 4];
            let result = extract_unaligned_u32(slice);

            // Manual calculation for comparison
            let expected = u32::from_le_bytes([
                slice[0], slice[1], slice[2], slice[3]
            ]);

            assert_eq!(result, Some(expected), 
                      "Failed at start position {}", start);
        }
    }

    #[test]
    fn test_extract_unaligned_u32_endianness() {
        // Test explicit endianness values
        let little_endian = [0x78, 0x56, 0x34, 0x12];
        let result = extract_unaligned_u32(&little_endian);
        assert_eq!(result, Some(0x12345678));

        // All zeros
        let zeros = [0x00, 0x00, 0x00, 0x00];
        assert_eq!(extract_unaligned_u32(&zeros), Some(0x00000000));

        // All ones
        let ones = [0xFF, 0xFF, 0xFF, 0xFF];
        assert_eq!(extract_unaligned_u32(&ones), Some(0xFFFFFFFF));
    }

    #[test]
    fn test_extract_unaligned_u32_with_larger_slice() {
        // Slice larger than 4 bytes
        let data = [0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88];

        // Test first 4 bytes
        let result = extract_unaligned_u32(&data[..4]);
        assert_eq!(result, Some(0x44332211));

        // Test middle 4 bytes (unaligned)
        let result = extract_unaligned_u32(&data[2..6]);
        assert_eq!(result, Some(0x66554433));

        // Test last 4 bytes
        let result = extract_unaligned_u32(&data[4..]);
        assert_eq!(result, Some(0x88776655));
    }

    #[test]
    fn test_extract_unaligned_u32_alignment_safety() {
        // Force unaligned memory access by using odd offsets
        let mut buffer = vec![0u8; 16];

        // Fill with pattern
        for i in 0..buffer.len() {
            buffer[i] = i as u8;
        }

        // Test various unaligned offsets
        let offsets = [1, 2, 3, 5, 6, 7, 9, 10, 11];

        for &offset in &offsets {
            if offset + 4 <= buffer.len() {
                let slice = &buffer[offset..offset + 4];
                let result = extract_unaligned_u32(slice);

                // Verify against manual reconstruction
                let expected = u32::from_le_bytes([
                    slice[0], slice[1], slice[2], slice[3]
                ]);

                assert_eq!(result, Some(expected),
                          "Failed at offset {}", offset);
            }
        }
    }

    #[test]
    fn test_extract_unaligned_u32_edge_cases() {
        // Maximum u32 value
        let max = [0xFF, 0xFF, 0xFF, 0xFF];
        assert_eq!(extract_unaligned_u32(&max), Some(u32::MAX));

        // Minimum u32 value
        let min = [0x00, 0x00, 0x00, 0x00];
        assert_eq!(extract_unaligned_u32(&min), Some(u32::MIN));

        // Pattern that could be misinterpreted
        let pattern = [0x80, 0x00, 0x00, 0x00]; // 128 in little-endian
        assert_eq!(extract_unaligned_u32(&pattern), Some(128));
    }

    #[test]
    fn test_extract_unaligned_u32_memory_safety() {
        // Ensure function doesn't read beyond slice bounds
        let data = [0x01, 0x02, 0x03, 0x04];

        // This should only read the first 4 bytes
        let slice = &data[..];
        let result = extract_unaligned_u32(slice);
        assert_eq!(result, Some(0x04030201));

        // Verify original data unchanged
        assert_eq!(data, [0x01, 0x02, 0x03, 0x04]);
    }

    #[test]
    fn test_extract_unaligned_u32_zero_copy() {
        // Test that the function works with borrowed data
        let original = vec![0xDE, 0xAD, 0xBE, 0xEF];
        let result = extract_unaligned_u32(&original);
        assert_eq!(result, Some(0xEFBEADDE));

