use std::collections::BinaryHeap;

#[derive(Debug, Clone, PartialEq, Eq, Ord, PartialOrd)]
pub struct Task {
    pub priority: u32,
    pub description: String,
}

#[derive(Debug)]
pub struct TaskStatistics {
    pub count: usize,
    pub min_priority: u32,
    pub max_priority: u32,
    pub avg_priority: f64,
    pub median_priority: u32,
}

fn analyze_task_priorities(heap: &BinaryHeap<Task>) -> TaskStatistics {
    let slice = heap.as_slice();

    if slice.is_empty() {
        return TaskStatistics {
            count: 0,
            min_priority: 0,
            max_priority: 0,
            avg_priority: 0.0,
            median_priority: 0,
        };
    }

    let mut priorities: Vec<u32> = slice.iter().map(|task| task.priority).collect();
    priorities.sort_unstable();

    let count = priorities.len();
    let min_priority = *priorities.first().unwrap();
    let max_priority = *priorities.last().unwrap();
    let avg_priority = priorities.iter().map(|&p| p as f64).sum::<f64>() / count as f64;

    let median_priority = if count % 2 == 0 {
        let mid = count / 2;
        (priorities[mid - 1] + priorities[mid]) / 2
    } else {
        priorities[count / 2]
    };

    TaskStatistics {
        count,
        min_priority,
        max_priority,
        avg_priority,
        median_priority,
    }
}

