#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BinaryHeap;

    fn heap_from(priorities: &[u32]) -> BinaryHeap<Task> {
        let mut heap = BinaryHeap::new();
        for &p in priorities {
            heap.push(Task { priority: p, description: format!("t{p}") });
        }
        heap
    }

    #[test]
    fn test_empty_heap() {
        let heap: BinaryHeap<Task> = BinaryHeap::new();
        let stats = analyze_task_priorities(&heap);
        assert_eq!(stats.count, 0);
        assert_eq!(stats.min_priority, 0);
        assert_eq!(stats.max_priority, 0);
        assert_eq!(stats.avg_priority, 0.0);
        assert_eq!(stats.median_priority, 0);
    }

    #[test]
    fn test_single_task() {
        let heap = heap_from(&[5]);
        let stats = analyze_task_priorities(&heap);
        assert_eq!(stats.count, 1);
        assert_eq!(stats.min_priority, 5);
        assert_eq!(stats.max_priority, 5);
        assert_eq!(stats.median_priority, 5);
    }

    #[test]
    fn test_multiple_tasks_odd() {
        let heap = heap_from(&[1, 5, 3]);
        let stats = analyze_task_priorities(&heap);
        assert_eq!(stats.count, 3);
        assert_eq!(stats.min_priority, 1);
        assert_eq!(stats.max_priority, 5);
        assert_eq!(stats.median_priority, 3);
        assert!((stats.avg_priority - 3.0).abs() < 1e-9);
    }

    #[test]
    fn test_multiple_tasks_even() {
        let heap = heap_from(&[2, 4, 6, 8]);
        let stats = analyze_task_priorities(&heap);
        assert_eq!(stats.count, 4);
        assert_eq!(stats.median_priority, 5);
    }

    #[test]
    fn test_duplicate_priorities() {
        let heap = heap_from(&[3, 3, 3]);
        let stats = analyze_task_priorities(&heap);
        assert_eq!(stats.min_priority, 3);
        assert_eq!(stats.max_priority, 3);
        assert_eq!(stats.median_priority, 3);
    }

    #[test]
    fn test_heap_unchanged() {
        let mut heap = heap_from(&[10, 1, 7]);
        let original_len = heap.len();
        let original_top = heap.peek().unwrap().priority;
        let _ = analyze_task_priorities(&heap);
        assert_eq!(heap.len(), original_len);
        assert_eq!(heap.peek().unwrap().priority, original_top);
    }
}

