pub fn batch_process_nanosecond_timestamps(timestamps: &[u128]) -> Vec<std::time::Duration> {
    timestamps
        .iter()
        .map(|&ns| {
            // Convert u128 to u64 safely for from_nanos
            // Since from_nanos only accepts u64, we need to handle potential overflow
            // by saturating at u64::MAX for values that exceed u64::MAX
            let nanos = ns.min(u128::from(u64::MAX)) as u64;
            std::time::Duration::from_nanos(nanos)
        })
        .collect()
}

