mod tests {
    use super::*;
    use std::time::Duration;

    #[test]
    fn test_empty_input() {
        let timestamps: &[u128] = &[];
        let result = batch_process_nanosecond_timestamps(timestamps);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_single_timestamp_within_u64_range() {
        let timestamps = &[1_000_000_000]; // 1 second in nanoseconds
        let result = batch_process_nanosecond_timestamps(timestamps);
        assert_eq!(result, vec![Duration::from_secs(1)]);
    }

    #[test]
    fn test_multiple_timestamps_within_u64_range() {
        let timestamps = &[
            0,
            1_000_000,        // 1 millisecond
            1_000_000_000,    // 1 second
            60_000_000_000,   // 1 minute
        ];
        let result = batch_process_nanosecond_timestamps(timestamps);
        let expected = vec![
            Duration::from_nanos(0),
            Duration::from_millis(1),
            Duration::from_secs(1),
            Duration::from_secs(60),
        ];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_timestamp_at_u64_max() {
        let u64_max = u128::from(u64::MAX);
        let timestamps = &[u64_max];
        let result = batch_process_nanosecond_timestamps(timestamps);
        assert_eq!(result, vec![Duration::from_nanos(u64::MAX)]);
    }

    #[test]
    fn test_timestamp_exceeds_u64_max() {
        let exceeds_u64_max = u128::from(u64::MAX) + 1;
        let timestamps = &[exceeds_u64_max];
        let result = batch_process_nanosecond_timestamps(timestamps);
        // Should saturate to u64::MAX
        assert_eq!(result, vec![Duration::from_nanos(u64::MAX)]);
    }

    #[test]
    fn test_mixed_timestamps_some_exceeding_u64_max() {
        let u64_max = u128::from(u64::MAX);
        let timestamps = &[
            1_000_000_000,
            u64_max,
            u64_max + 1,
            u64_max + 1_000_000,
        ];
        let result = batch_process_nanosecond_timestamps(timestamps);
        let expected = vec![
            Duration::from_secs(1),
            Duration::from_nanos(u64::MAX),
            Duration::from_nanos(u64::MAX), // saturated
            Duration::from_nanos(u64::MAX), // saturated
        ];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_very_large_u128_values() {
        let huge_value = u128::MAX;
        let timestamps = &[huge_value];
        let result = batch_process_nanosecond_timestamps(timestamps);
        assert_eq!(result, vec![Duration::from_nanos(u64::MAX)]);
    }

    #[test]
    fn test_preserves_ordering() {
        let timestamps = &[100, 200, 300, 400];
        let result = batch_process_nanosecond_timestamps(timestamps);

        // Check that durations are in same order as input
        assert_eq!(result[0], Duration::from_nanos(100));
        assert_eq!(result[1], Duration::from_nanos(200));
        assert_eq!(result[2], Duration::from_nanos(300));
        assert_eq!(result[3], Duration::from_nanos(400));

        // Verify monotonic increase
        for i in 1..result.len() {
            assert!(result[i] >= result[i-1]);
        }
    }

    #[test]
    fn test_duration_equivalence() {
        // Test that from_nanos produces equivalent durations to other constructors
        let timestamps = &[
            0,
            1_000_000,        // Should equal Duration::from_millis(1)
            1_000_000_000,    // Should equal Duration::from_secs(1)
            1_500_000_000,    // Should equal Duration::new(1, 500_000_000)
        ];
        let result = batch_process_nanosecond_timestamps(timestamps);

        assert_eq!(result[0], Duration::new(0, 0));
        assert_eq!(result[1], Duration::from_millis(1));
        assert_eq!(result[2], Duration::from_secs(1));
        assert_eq!(result[3], Duration::new(1, 500_000_000));
    }

    #[test]
    fn test_large_batch() {
        // Test with many elements to ensure no panics
        let mut timestamps = Vec::with_capacity(10000);
        for i in 0..10000 {
            timestamps.push(i as u128 * 1000);
        }

        let result = batch_process_nanosecond_timestamps(&timestamps);
        assert_eq!(result.len(), 10000);

        // Verify first and last elements
        assert_eq!(result[0], Duration::from_nanos(0));
        assert_eq!(result[9999], Duration::from_nanos(9999 * 1000));
    }
}

