        // Thin space (U+2009) is NOT ASCII whitespace
        assert_eq!(count_non_empty_ascii_whitespace_segments("hello\u{2009}world"), 1);
    }

    #[test]
    fn test_mixed_ascii_and_non_ascii() {
        assert_eq!(count_non_empty_ascii_whitespace_segments("hello world\u{00A0}test"), 2);
        assert_eq!(count_non_empty_ascii_whitespace_segments("a\u{00A0}b c d"), 3);
