        assert_eq!(count_non_empty_ascii_whitespace_segments("a,b,c,d"), 1);
    }

    #[test]
    fn test_numbers_and_symbols() {
        assert_eq!(count_non_empty_ascii_whitespace_segments("123 456 789"), 3);
        assert_eq!(count_non_empty_ascii_whitespace_segments("a+b c*d e/f"), 3);
        assert_eq!(count_non_empty_ascii_whitespace_segments("! @ # $ %"), 5);
    }

    #[test]
    fn test_edge_case_single_character_words() {
        assert_eq!(count_non_empty_ascii_whitespace_segments("a b c d e"), 5);
        assert_eq!(count_non_empty_ascii_whitespace_segments(" a b c "), 3);
    }

    #[test]
    fn test_empty_segments_between_whitespace() {
        // split_ascii_whitespace() ignores empty segments
        assert_eq!(count_non_empty_ascii_whitespace_segments("hello  world"), 2);
        assert_eq!(count_non_empty_ascii_whitespace_segments("a   b    c"), 3);
