        let timestamps = [2000, 1500, 1000, 500];
        let intervals = compute_intervals(&timestamps);
        let expected = vec![
            Duration::from_millis(0),  // 1500 - 2000 saturates to 0
            Duration::from_millis(0),  // 1000 - 1500 saturates to 0
            Duration::from_millis(0),  // 500 - 1000 saturates to 0
        ];
        assert_eq!(intervals, expected);
    }

    #[test]
