mod tests {
    use std::num::{NonZeroI64, NonZeroU64};
    use super::abs_nonzero_const;

    #[test]
    fn test_positive_value() {
        let input = NonZeroI64::new(42).unwrap();
        let result = abs_nonzero_const(input);
        assert_eq!(result.get(), 42u64);
    }

    #[test]
    fn test_negative_value() {
        let input = NonZeroI64::new(-42).unwrap();
        let result = abs_nonzero_const(input);
        assert_eq!(result.get(), 42u64);
    }

    #[test]
    fn test_max_positive() {
        let input = NonZeroI64::new(i64::MAX).unwrap();
        let result = abs_nonzero_const(input);
        assert_eq!(result.get(), i64::MAX as u64);
    }

    #[test]
    fn test_min_negative() {
        // i64::MIN.abs() overflows in debug mode, so we need to handle it carefully
        // The absolute value of i64::MIN is i64::MAX as u64 + 1
        let input = NonZeroI64::new(i64::MIN).unwrap();
        let result = abs_nonzero_const(input);
        assert_eq!(result.get(), (i64::MAX as u64).wrapping_add(1));
    }

    #[test]
    fn test_one() {
        let input = NonZeroI64::new(1).unwrap();
        let result = abs_nonzero_const(input);
        assert_eq!(result.get(), 1u64);
    }

    #[test]
    fn test_negative_one() {
        let input = NonZeroI64::new(-1).unwrap();
        let result = abs_nonzero_const(input);
        assert_eq!(result.get(), 1u64);
    }

    #[test]
    fn test_const_context() {
        const INPUT: NonZeroI64 = unsafe { NonZeroI64::new_unchecked(100) };
        const RESULT: NonZeroU64 = abs_nonzero_const(INPUT);
        assert_eq!(RESULT.get(), 100u64);
    }

    #[test]
    fn test_negative_const_context() {
        const INPUT: NonZeroI64 = unsafe { NonZeroI64::new_unchecked(-100) };
        const RESULT: NonZeroU64 = abs_nonzero_const(INPUT);
        assert_eq!(RESULT.get(), 100u64);
    }

    #[test]
    fn test_non_zero_property_preserved() {
        // The function should always return NonZeroU64, which guarantees non-zero
        let test_cases = [
            NonZeroI64::new(1).unwrap(),
            NonZeroI64::new(-1).unwrap(),
            NonZeroI64::new(i64::MAX).unwrap(),
            NonZeroI64::new(i64::MIN).unwrap(),
            NonZeroI64::new(7).unwrap(),
            NonZeroI64::new(-7).unwrap(),
        ];

        for input in test_cases {
            let result = abs_nonzero_const(input);
            // NonZeroU64::new would return None for zero, but we know it's non-zero
            assert!(NonZeroU64::new(result.get()).is_some());
        }
    }

    #[test]
    fn test_absolute_value_property() {
        let test_cases = [
            (5, 5),
            (-5, 5),
            (100, 100),
            (-100, 100),
            (i64::MAX, i64::MAX as u64),
        ];

        for (input_val, expected_abs) in test_cases {
            let input = NonZeroI64::new(input_val).unwrap();
            let result = abs_nonzero_const(input);
            assert_eq!(result.get(), expected_abs);
        }
    }
}

