        let result = total_microsecond_duration(intervals);
        assert_eq!(result, Duration::from_micros(u64::MAX));
    }

    #[test]
    fn test_overflow_prevention() {
        // Test that summing multiple large values doesn't overflow
        let intervals = &[u64::MAX / 2, u64::MAX / 2, 1];
        let result = total_microsecond_duration(intervals);
        // This should handle the sum correctly without panicking
        assert_eq!(result, Duration::from_micros(u64::MAX));
    }

    #[test]
    fn test_mixed_precision() {
        let intervals = &[1_234_567, 890, 123];
        let result = total_microsecond_duration(intervals);
        assert_eq!(result, Duration::from_micros(1_235_580));
        assert_eq!(result.as_secs(), 1);
        assert_eq!(result.subsec_micros(), 235_580);
    }

    #[test]
    fn test_zero_intervals() {
        let intervals = &[0, 0, 0, 0];
        let result = total_microsecond_duration(intervals);
        assert_eq!(result, Duration::from_micros(0));
        assert_eq!(result.as_secs(), 0);
        assert_eq!(result.subsec_nanos(), 0);
    }

    #[test]
    fn test_many_intervals() {
        // Test with a large number of small intervals
        let intervals: Vec<u64> = (0..1000).map(|_| 1).collect();
        let result = total_microsecond_duration(&intervals);
        assert_eq!(result, Duration::from_micros(1000));
    }

    #[test]
    fn test_duration_conversion_accuracy() {
        // Verify that microsecond-to-nanosecond conversion is accurate
        let intervals = &[1_500_000]; // 1.5 seconds
        let result = total_microsecond_duration(intervals);

        // Check both seconds and subsecond parts
        assert_eq!(result.as_secs(), 1);
        assert_eq!(result.subsec_micros(), 500_000);
        assert_eq!(result.subsec_nanos(), 500_000_000);

        // Verify the total duration matches expected
        assert_eq!(result, Duration::new(1, 500_000_000));
    }

    #[test]
    fn test_edge_case_near_second_boundary() {
        let intervals = &[999_999, 1];
        let result = total_microsecond_duration(intervals);
        assert_eq!(result, Duration::from_micros(1_000_000));
        assert_eq!(result.as_secs(), 1);
        assert_eq!(result.subsec_micros(), 0);
    }

    #[test]
    fn test_random_access_slice() {
        // Test with a slice that's a view into a larger vector
        let data = vec![10, 20, 30, 40, 50];
        let slice = &data[1..4]; // [20, 30, 40]
        let result = total_microsecond_duration(slice);
        assert_eq!(result, Duration::from_micros(90));
