#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::Arc;
    use std::thread;

    #[test]
    fn test_toggle_encryption_flag_basic() {
        let flag = AtomicBool::new(false);
        let previous = toggle_encryption_flag(&flag);

        assert_eq!(previous, false, "Should return previous value false");
        assert_eq!(flag.load(Ordering::SeqCst), true, "Flag should be toggled to true");

        let previous = toggle_encryption_flag(&flag);
        assert_eq!(previous, true, "Should return previous value true");
        assert_eq!(flag.load(Ordering::SeqCst), false, "Flag should be toggled to false");
    }

    #[test]
    fn test_toggle_encryption_flag_initial_true() {
        let flag = AtomicBool::new(true);
        let previous = toggle_encryption_flag(&flag);

        assert_eq!(previous, true, "Should return previous value true");
        assert_eq!(flag.load(Ordering::SeqCst), false, "Flag should be toggled to false");

        let previous = toggle_encryption_flag(&flag);
        assert_eq!(previous, false, "Should return previous value false");
        assert_eq!(flag.load(Ordering::SeqCst), true, "Flag should be toggled to true");
    }

    #[test]
    fn test_toggle_encryption_flag_concurrent() {
        let flag = Arc::new(AtomicBool::new(false));
        let mut handles = vec![];

        // Spawn 10 threads that toggle the flag multiple times
        for _ in 0..10 {
            let flag_clone = Arc::clone(&flag);
            let handle = thread::spawn(move || {
                for _ in 0..100 {
                    let _ = toggle_encryption_flag(&flag_clone);
                }
            });
            handles.push(handle);
        }

        // Wait for all threads to complete
        for handle in handles {
            handle.join().expect("Thread should complete successfully");
        }

        // After all toggles, the value should be deterministic
        // 10 threads * 100 toggles each = 1000 toggles
        // Starting from false, even number of toggles should leave it false
        assert_eq!(
            flag.load(Ordering::SeqCst), 
            false, 
            "After even number of toggles, flag should return to initial state"
        );
    }

    #[test]
    fn test_toggle_encryption_flag_atomicity() {
        let flag = Arc::new(AtomicBool::new(false));
        let results = Arc::new(std::sync::Mutex::new(Vec::new()));
        let mut handles = vec![];

        // Spawn multiple threads that toggle and record the previous value
        for i in 0..5 {
            let flag_clone = Arc::clone(&flag);
            let results_clone = Arc::clone(&results);
            let handle = thread::spawn(move || {
                let previous = toggle_encryption_flag(&flag_clone);
                let mut results = results_clone.lock().unwrap();
                results.push((i, previous));
            });
            handles.push(handle);
        }

        for handle in handles {
            handle.join().expect("Thread should complete successfully");
        }

        let results = results.lock().unwrap();
        // All previous values should be unique and sequential
        // Since operations are atomic, each thread should see a different state
        let unique_values: std::collections::HashSet<bool> = 
            results.iter().map(|&(_, val)| val).collect();
        assert!(
            unique_values.len() <= 2, 
            "Should only see true or false values"
        );
    }

    #[test]
    fn test_toggle_encryption_flag_memory_ordering() {
        let flag = AtomicBool::new(false);

        // Test that SeqCst ordering provides expected visibility
        let previous = toggle_encryption_flag(&flag);

        // The load should see the updated value
        assert_eq!(flag.load(Ordering::SeqCst), !previous);

        // Additional toggle to ensure consistency
        let new_previous = toggle_encryption_flag(&flag);
        assert_eq!(new_previous, !previous);
        assert_eq!(flag.load(Ordering::SeqCst), previous);
    }

    #[test]
    fn test_toggle_encryption_flag_repeated_operations() {
        let flag = AtomicBool::new(false);

        // Perform 1000 toggles and verify pattern
        for i in 0..1000 {
            let expected_previous = if i % 2 == 0 { false } else { true };
            let previous = toggle_encryption_flag(&flag);

            assert_eq!(
                previous, expected_previous,
                "Iteration {}: expected previous={}, got previous={}",
                i, expected_previous, previous
            );

            let current = flag.load(Ordering::SeqCst);
            let expected_current = !expected_previous;
            assert_eq!(
                current, expected_current,
                "Iteration {}: expected current={}, got current={}",
                i, expected_current, current
            );
        }
    }
}

