use std::cmp::Ordering;

#[derive(Debug, PartialEq, Eq)]
pub struct Packet {
    pub timestamp: u64,
    pub priority: u8,
}

fn sort_packets_by_timestamp_and_priority(packets: &mut [Packet]) {
    packets.sort_unstable_by(|a, b| {
        match a.timestamp.cmp(&b.timestamp) {
            Ordering::Equal => b.priority.cmp(&a.priority),
            other => other,
        }
    });
}

