#[derive(Debug, PartialEq, Eq)]
pub enum TransactionCategory {
    Positive,
    Negative,
    Zero,
    NaN,
}

pub fn categorize_transaction_sign(amount: f64) -> TransactionCategory {
    if amount.is_nan() {
        TransactionCategory::NaN
    } else if amount == 0.0 {
        if amount.is_sign_negative() {
            TransactionCategory::Negative
        } else {
            TransactionCategory::Zero
        }
    } else if amount.is_sign_negative() {
        TransactionCategory::Negative
    } else {
        TransactionCategory::Positive
    }
}

