#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_positive_numbers() {
        assert_eq!(categorize_transaction_sign(1.0), TransactionCategory::Positive);
        assert_eq!(categorize_transaction_sign(42.5), TransactionCategory::Positive);
        assert_eq!(categorize_transaction_sign(0.1), TransactionCategory::Positive);
        assert_eq!(categorize_transaction_sign(f64::MAX), TransactionCategory::Positive);
        assert_eq!(categorize_transaction_sign(f64::MIN_POSITIVE), TransactionCategory::Positive);
    }

    #[test]
    fn test_negative_numbers() {
        assert_eq!(categorize_transaction_sign(-1.0), TransactionCategory::Negative);
        assert_eq!(categorize_transaction_sign(-42.5), TransactionCategory::Negative);
        assert_eq!(categorize_transaction_sign(-0.1), TransactionCategory::Negative);
        assert_eq!(categorize_transaction_sign(f64::MIN), TransactionCategory::Negative);
    }

    #[test]
    fn test_zero_values() {
        assert_eq!(categorize_transaction_sign(0.0), TransactionCategory::Zero);
        assert_eq!(categorize_transaction_sign(-0.0), TransactionCategory::Negative);
    }

    #[test]
    fn test_nan_values() {
        assert_eq!(categorize_transaction_sign(f64::NAN), TransactionCategory::NaN);
        assert_eq!(categorize_transaction_sign(-f64::NAN), TransactionCategory::NaN);
    }

    #[test]
    fn test_infinity_values() {
        assert_eq!(categorize_transaction_sign(f64::INFINITY), TransactionCategory::Positive);
        assert_eq!(categorize_transaction_sign(f64::NEG_INFINITY), TransactionCategory::Negative);
    }

    #[test]
    fn test_subnormal_numbers() {
        let min_subnormal = f64::MIN_POSITIVE / 2.0;
        assert_eq!(categorize_transaction_sign(min_subnormal), TransactionCategory::Positive);
        assert_eq!(categorize_transaction_sign(-min_subnormal), TransactionCategory::Negative);
    }

    #[test]
    fn test_edge_cases() {
        // Test that very small positive numbers are positive
        assert_eq!(categorize_transaction_sign(1e-308), TransactionCategory::Positive);

        // Test that very small negative numbers are negative
        assert_eq!(categorize_transaction_sign(-1e-308), TransactionCategory::Negative);

        // Test with epsilon
        assert_eq!(categorize_transaction_sign(f64::EPSILON), TransactionCategory::Positive);
        assert_eq!(categorize_transaction_sign(-f64::EPSILON), TransactionCategory::Negative);
    }

    #[test]
    fn test_nan_propagation() {
        // Ensure different NaN representations are all categorized as NaN
        let nan1: f64 = 0.0 / 0.0;
        let nan2: f64 = f64::NAN * 2.0;
        let nan3: f64 = (-1.0_f64).sqrt();

        assert_eq!(categorize_transaction_sign(nan1), TransactionCategory::NaN);
        assert_eq!(categorize_transaction_sign(nan2), TransactionCategory::NaN);
        assert_eq!(categorize_transaction_sign(nan3), TransactionCategory::NaN);
    }
}

