fn place_median_by_abs(slice: &mut [i32]) -> Option<&mut i32> {
    if slice.len() % 2 == 0 {
        return None;
    }

    let median_index = slice.len() / 2;
    let (_, median, _) = slice.select_nth_unstable_by_key(median_index, |x| x.abs());
    Some(median)
}

