        let result = compute_log2_for_nonzero(input);
        assert_eq!(result, vec![0]);
    }

    #[test]
    fn test_single_nonzero_not_power_of_two() {
        let input = &[5];
        let result = compute_log2_for_nonzero(input);
        assert_eq!(result, vec![2]); // ilog2(5) = 2
    }

    #[test]
    fn test_mixed_zeros_and_nonzero() {
        let input = &[0, 1, 0, 2, 0, 4, 0, 8];
        let result = compute_log2_for_nonzero(input);
        assert_eq!(result, vec![0, 1, 2, 3]);
    }

