    fn test_large_numbers() {
        let input = &[u32::MAX, 1 << 31, 1 << 16, 1 << 8];
        let result = compute_log2_for_nonzero(input);
        assert_eq!(result, vec![31, 31, 16, 8]);
    }

    #[test]
    fn test_sequential_powers_of_two() {
        let input: Vec<u32> = (0..=31).map(|exp| 1 << exp).collect();
        let result = compute_log2_for_nonzero(&input);
        let expected: Vec<u32> = (0..=31).collect();
        assert_eq!(result, expected);
    }

    #[test]
    fn test_non_power_of_two_values() {
        let input = &[3, 7, 15, 31, 63];
        let result = compute_log2_for_nonzero(input);
        // ilog2 rounds down to nearest power of two
        assert_eq!(result, vec![1, 2, 3, 4, 5]);
    }

    #[test]
    fn test_zero_handling_edge_cases() {
        let input = &[0, 1, 0, 0, 2, 0, 0, 0, 4, 0];
        let result = compute_log2_for_nonzero(input);
        assert_eq!(result, vec![0, 1, 2]);
    }

    #[test]
    fn test_max_u32_value() {
        let input = &[u32::MAX];
        let result = compute_log2_for_nonzero(input);
        assert_eq!(result, vec![31]);
    }

    #[test]
    fn test_min_nonzero_value() {
        let input = &[1];
        let result = compute_log2_for_nonzero(input);
        assert_eq!(result, vec![0]);
    }

    #[test]
    fn test_ordering_preserved() {
        let input = &[8, 0, 4, 0, 0, 2, 1, 0];
        let result = compute_log2_for_nonzero(input);
        assert_eq!(result, vec![3, 2, 1, 0]);
