pub fn sort_tuples_by_second_descending(tuples: &mut Vec<(String, u32)>) -> &mut Vec<(String, u32)> {
    tuples.sort_unstable_by_key(|&(_, key)| std::cmp::Reverse(key));
    tuples
}

