#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_vector() {
        let mut input: Vec<(String, u32)> = vec![];
        let result = sort_tuples_by_second_descending(&mut input);
        assert_eq!(result, &vec![]);
    }

    #[test]
    fn test_single_element() {
        let mut input = vec![("hello".to_string(), 42)];
        let result = sort_tuples_by_second_descending(&mut input);
        assert_eq!(result, &vec![("hello".to_string(), 42)]);
    }

    #[test]
    fn test_already_sorted_descending() {
        let mut input = vec![
            ("a".to_string(), 100),
            ("b".to_string(), 90),
            ("c".to_string(), 80),
            ("d".to_string(), 70),
        ];
        let expected = input.clone();
        let result = sort_tuples_by_second_descending(&mut input);
        assert_eq!(result, &expected);
    }

    #[test]
    fn test_reverse_sorted_ascending() {
        let mut input = vec![
            ("a".to_string(), 10),
            ("b".to_string(), 20),
            ("c".to_string(), 30),
            ("d".to_string(), 40),
        ];
        let expected = vec![
            ("d".to_string(), 40),
            ("c".to_string(), 30),
            ("b".to_string(), 20),
            ("a".to_string(), 10),
        ];
        let result = sort_tuples_by_second_descending(&mut input);
        assert_eq!(result, &expected);
    }

    #[test]
    fn test_random_order() {
        let mut input = vec![
            ("a".to_string(), 5),
            ("b".to_string(), 2),
            ("c".to_string(), 8),
            ("d".to_string(), 1),
            ("e".to_string(), 9),
        ];
        let expected = vec![
            ("e".to_string(), 9),
            ("c".to_string(), 8),
            ("a".to_string(), 5),
            ("b".to_string(), 2),
            ("d".to_string(), 1),
        ];
        let result = sort_tuples_by_second_descending(&mut input);
        assert_eq!(result, &expected);
    }

    #[test]
    fn test_duplicate_keys() {
        let mut input = vec![
            ("a".to_string(), 5),
            ("b".to_string(), 2),
            ("c".to_string(), 5),
            ("d".to_string(), 2),
            ("e".to_string(), 5),
        ];
        // Note: sort_unstable_by_key is unstable, so we can't guarantee order for equal keys
        let result = sort_tuples_by_second_descending(&mut input);

        // Verify all elements with key 5 come first
        assert_eq!(result[0].1, 5);
        assert_eq!(result[1].1, 5);
        assert_eq!(result[2].1, 5);
        assert_eq!(result[3].1, 2);
        assert_eq!(result[4].1, 2);

        // Verify all original elements are still present
        let mut keys: Vec<u32> = result.iter().map(|(_, k)| *k).collect();
        keys.sort();
        assert_eq!(keys, vec![2, 2, 5, 5, 5]);
    }

    #[test]
    fn test_all_same_keys() {
        let mut input = vec![
            ("a".to_string(), 10),
            ("b".to_string(), 10),
            ("c".to_string(), 10),
            ("d".to_string(), 10),
        ];
        let result = sort_tuples_by_second_descending(&mut input);

        // All keys should be 10
        for (_, key) in result {
            assert_eq!(*key, 10);
        }
    }

    #[test]
    fn test_large_numbers() {
        let mut input = vec![
            ("a".to_string(), u32::MAX),
            ("b".to_string(), u32::MIN),
            ("c".to_string(), u32::MAX / 2),
        ];
        let expected = vec![
            ("a".to_string(), u32::MAX),
            ("c".to_string(), u32::MAX / 2),
            ("b".to_string(), u32::MIN),
        ];
        let result = sort_tuples_by_second_descending(&mut input);
        assert_eq!(result, &expected);
    }

    #[test]
    fn test_returns_mutable_reference() {
        let mut input = vec![
            ("a".to_string(), 1),
            ("b".to_string(), 3),
            ("c".to_string(), 2),
        ];

        // Test that we can chain operations
        let result = sort_tuples_by_second_descending(&mut input)
            .iter()
            .map(|(_, k)| *k)
            .collect::<Vec<u32>>();

        assert_eq!(result, vec![3, 2, 1]);
    }

    #[test]
    fn test_string_contents_preserved() {
        let mut input = vec![
            ("hello".to_string(), 3),
            ("world".to_string(), 1),
            ("rust".to_string(), 2),
        ];

        let result = sort_tuples_by_second_descending(&mut input);

        // Check that strings are preserved (not swapped incorrectly)
        let mut found_strings = vec![];
        for (s, _) in result {
            found_strings.push(s.clone());
        }
        found_strings.sort();
        assert_eq!(found_strings, vec!["hello", "rust", "world"]);
    }
}

