    fn test_finalize_buffer_success() {
        // Create an uninitialized buffer
        let mut uninit_vec: Vec<MaybeUninit<Pixel>> = Vec::with_capacity(10);
        unsafe {
            uninit_vec.set_len(10);
        }
        let uninit_buffer = Arc::from(uninit_vec.into_boxed_slice());

