        // For this test, we assume they are properly initialized

        let result = finalize_buffer(uninit_buffer);
        assert!(result.is_ok());

        let initialized_buffer = result.unwrap();
        assert_eq!(initialized_buffer.len(), 10);
    }

    #[test]
    fn test_finalize_buffer_empty() {
        // Test with empty buffer
        let uninit_vec: Vec<MaybeUninit<Pixel>> = vec![];
        let uninit_buffer = Arc::from(uninit_vec.into_boxed_slice());

        let result = finalize_buffer(uninit_buffer);
        assert!(result.is_ok());

        let initialized_buffer = result.unwrap();
        assert_eq!(initialized_buffer.len(), 0);
    }

    #[test]
