        let mut uninit_vec: Vec<MaybeUninit<Pixel>> = Vec::with_capacity(1);
        unsafe {
            uninit_vec.set_len(1);
        }
        let uninit_buffer = Arc::from(uninit_vec.into_boxed_slice());

        let result = finalize_buffer(uninit_buffer);
        assert!(result.is_ok());

        let initialized_buffer = result.unwrap();
        assert_eq!(initialized_buffer.len(), 1);
    }

    #[test]
    fn test_finalize_buffer_arc_cloning() {
        // Test that Arc cloning works correctly
        let mut uninit_vec: Vec<MaybeUninit<Pixel>> = Vec::with_capacity(5);
        unsafe {
            uninit_vec.set_len(5);
        }
        let uninit_buffer = Arc::from(uninit_vec.into_boxed_slice());

        let clone1 = Arc::clone(&uninit_buffer);
        let clone2 = Arc::clone(&uninit_buffer);

        assert_eq!(Arc::strong_count(&uninit_buffer), 3);

        let result1 = finalize_buffer(uninit_buffer);
        assert!(result1.is_ok());

        // After finalization, the original Arc is consumed
        // but clones should still be valid
        let result2 = finalize_buffer(clone1);
        assert!(result2.is_ok());

        let result3 = finalize_buffer(clone2);
        assert!(result3.is_ok());
    }

    #[test]
    fn test_finalize_buffer_type_safety() {
        // Verify the function returns the correct types
        let mut uninit_vec: Vec<MaybeUninit<Pixel>> = Vec::with_capacity(3);
        unsafe {
            uninit_vec.set_len(3);
        }
        let uninit_buffer = Arc::from(uninit_vec.into_boxed_slice());

        let result = finalize_buffer(uninit_buffer);

        // Check return type is Result<Arc<[Pixel]>, UninitializedPixelError>
        match result {
            Ok(buffer) => {
                // Verify buffer is Arc<[Pixel]>
                let _: Arc<[Pixel]> = buffer;
                assert_eq!(buffer.len(), 3);
            }
            Err(err) => {
                // Verify error type is UninitializedPixelError
                let _: UninitializedPixelError = err;
                panic!("Expected Ok but got Err");
            }
        }
    }

    #[test]
    fn test_finalize_buffer_no_allocation() {
        // This test verifies that no additional allocations occur
        // by checking that the Arc count remains the same
        let mut uninit_vec: Vec<MaybeUninit<Pixel>> = Vec::with_capacity(100);
        unsafe {
            uninit_vec.set_len(100);
        }
        let uninit_buffer = Arc::from(uninit_vec.into_boxed_slice());

        let initial_count = Arc::strong_count(&uninit_buffer);

        let result = finalize_buffer(uninit_buffer);
        assert!(result.is_ok());

        let initialized_buffer = result.unwrap();
        let final_count = Arc::strong_count(&initialized_buffer);

        // The Arc count should be the same (1 in this case since we consumed the original)
        assert_eq!(initial_count, final_count);
    }

    // Note: We cannot write a test for the error case without actually
    // having uninitialized memory, which would be unsafe to create.
    // In a real implementation, the function would check initialization
    // and return UninitializedPixelError when appropriate.
}

