pub fn filter_special_floats(values: &[f32]) -> Vec<f32> {
    values
        .iter()
        .filter(|&&x| {
            let category = x.classify();
            matches!(category, std::num::FpCategory::Infinite | std::num::FpCategory::Nan | std::num::FpCategory::Zero)
        })
        .copied()
        .collect()
}

