    fn test_only_zeros() {
        let input = &[0.0, -0.0, 0.0, -0.0];
        let result = filter_special_floats(input);
        assert_eq!(result.len(), 4);
        assert!(result.iter().all(|&x| x.classify() == std::num::FpCategory::Zero));
    }

    #[test]
    fn test_only_infinities() {
        let input = &[f32::INFINITY, f32::NEG_INFINITY, f32::INFINITY];
        let result = filter_special_floats(input);
        assert_eq!(result.len(), 3);
        assert!(result.iter().all(|&x| x.classify() == std::num::FpCategory::Infinite));
    }

    #[test]
    fn test_only_nans() {
        let input = &[f32::NAN, f32::NAN, f32::NAN];
        let result = filter_special_floats(input);
        assert_eq!(result.len(), 3);
        assert!(result.iter().all(|&x| x.is_nan()));
    }

    #[test]
    fn test_mixed_special_values() {
        let input = &[0.0, f32::INFINITY, 1.0, f32::NAN, -0.0, f32::NEG_INFINITY, 2.5, f32::NAN];
        let result = filter_special_floats(input);
        assert_eq!(result.len(), 6);
        assert!(result.iter().all(|&x| {
            let category = x.classify();
            matches!(category, 
                std::num::FpCategory::Infinite | 
                std::num::FpCategory::Nan | 
                std::num::FpCategory::Zero)
        }));
    }

    #[test]
    fn test_all_fp_categories() {
        let input = &[
            1.0,                     // Normal
            0.0,                     // Zero
            -0.0,                    // Zero
            f32::INFINITY,           // Infinite
            f32::NEG_INFINITY,       // Infinite
            f32::NAN,                // NaN
            f32::MIN_POSITIVE,       // Subnormal
            -f32::MIN_POSITIVE,      // Subnormal
            1000.0,                  // Normal
        ];
        let result = filter_special_floats(input);
        assert_eq!(result.len(), 5); // Only zeros, infinities, and NaN
        assert!(!result.iter().any(|&x| x == 1.0));
        assert!(!result.iter().any(|&x| x == f32::MIN_POSITIVE));
        assert!(!result.iter().any(|&x| x == 1000.0));
    }

    #[test]
    fn test_subnormal_not_included() {
        let input = &[f32::MIN_POSITIVE, -f32::MIN_POSITIVE, f32::from_bits(1)];
        let result = filter_special_floats(input);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_preserves_order() {
        let input = &[f32::NAN, 0.0, f32::INFINITY, -0.0, f32::NEG_INFINITY];
        let result = filter_special_floats(input);
        let expected = &[f32::NAN, 0.0, f32::INFINITY, -0.0, f32::NEG_INFINITY];

        assert_eq!(result.len(), expected.len());
        for (i, &val) in result.iter().enumerate() {
            let expected_val = expected[i];
            if expected_val.is_nan() {
                assert!(val.is_nan());
            } else {
                assert_eq!(val, expected_val);
            }
        }
    }

    #[test]
    fn test_large_input() {
        let mut input = Vec::with_capacity(1000);
        for i in 0..1000 {
            match i % 7 {
                0 => input.push(0.0),
                1 => input.push(-0.0),
                2 => input.push(f32::INFINITY),
                3 => input.push(f32::NEG_INFINITY),
                4 => input.push(f32::NAN),
                _ => input.push(i as f32),
            }
        }

        let result = filter_special_floats(&input);
        let expected_count = (1000 / 7) * 5 + (1000 % 7).min(5); // 5 special values per 7 elements
        assert_eq!(result.len(), expected_count);

        for &val in &result {
            let category = val.classify();
            assert!(matches!(category, 
                std::num::FpCategory::Infinite | 
                std::num::FpCategory::Nan | 
                std::num::FpCategory::Zero));
        }
    }
}

