fn categorize_floats(numbers: &[f64]) -> (usize, usize, usize, usize, usize) {
    let mut normal = 0;
    let mut subnormal = 0;
    let mut zero = 0;
    let mut infinite = 0;
    let mut nan = 0;

    for &num in numbers {
        match num.classify() {
            std::num::FpCategory::Normal => normal += 1,
            std::num::FpCategory::Subnormal => subnormal += 1,
            std::num::FpCategory::Zero => zero += 1,
            std::num::FpCategory::Infinite => infinite += 1,
            std::num::FpCategory::Nan => nan += 1,
        }
    }

    (normal, subnormal, zero, infinite, nan)
}

