pub unsafe fn extract_valid_numbers(results: &[Result<u32, &'static str>]) -> Vec<u32> {
    let mut extracted = Vec::with_capacity(results.len());
    for &result in results {
        extracted.push(result.unwrap_unchecked());
    }
    extracted
}

