pub fn serialize_floats_to_bytes(floats: &[f32]) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(floats.len() * 4);
    for &f in floats {
        let bits = f.to_bits();
        bytes.extend_from_slice(&bits.to_le_bytes());
    }
    bytes
}

