            -3.14159f32,
            f32::INFINITY,
            f32::NEG_INFINITY,
            f32::NAN,
            f32::MAX,
            f32::MIN,
            f32::MIN_POSITIVE,
            f32::from_bits(0x00000001), // smallest positive denormal
            f32::from_bits(0x80000001), // smallest negative denormal
        ];

        let serialized = serialize_floats_to_bytes(original_floats);
        assert_eq!(serialized.len(), original_floats.len() * 4);

        // Verify we can reconstruct the bytes
        for (i, &original_float) in original_floats.iter().enumerate() {
            let start = i * 4;
            let end = start + 4;
            let bytes = &serialized[start..end];
            let mut byte_array = [0u8; 4];
            byte_array.copy_from_slice(bytes);
            let reconstructed_bits = u32::from_le_bytes(byte_array);
            let reconstructed_float = f32::from_bits(reconstructed_bits);

            // For NaN values, we need special comparison
            if original_float.is_nan() {
                assert!(reconstructed_float.is_nan());
                // Check that the NaN bits match
                assert_eq!(original_float.to_bits(), reconstructed_float.to_bits());
            } else {
                assert_eq!(original_float.to_bits(), reconstructed_float.to_bits());
            }
        }
    }

    #[test]
    fn test_capacity_allocation() {
        // Test with various sizes to ensure proper capacity allocation
        let sizes = [1, 10, 100, 1000];

        for size in sizes {
            let floats: Vec<f32> = (0..size).map(|i| i as f32).collect();
            let result = serialize_floats_to_bytes(&floats);
            assert_eq!(result.len(), size * 4);

            // Verify all bytes are correct
            for (i, &f) in floats.iter().enumerate() {
                let start = i * 4;
                let end = start + 4;
                let bytes = &result[start..end];
                let expected_bytes = f.to_bits().to_le_bytes();
                assert_eq!(bytes, expected_bytes);
            }
        }
    }

    #[test]
    fn test_deterministic_output() {
        let floats = &[1.5f32, 2.5f32, 3.5f32];
        let result1 = serialize_floats_to_bytes(floats);
        let result2 = serialize_floats_to_bytes(floats);
        let result3 = serialize_floats_to_bytes(floats);

        // All calls should produce identical output
        assert_eq!(result1, result2);
        assert_eq!(result2, result3);
        assert_eq!(result1, result3);
    }

    #[test]
    fn test_byte_order() {
        let floats = &[f32::from_bits(0x12345678)];
        let result = serialize_floats_to_bytes(floats);

        // Verify little-endian byte order
        assert_eq!(result[0], 0x78);
        assert_eq!(result[1], 0x56);
        assert_eq!(result[2], 0x34);
        assert_eq!(result[3], 0x12);
    }

    #[test]
    fn test_mixed_values() {
        let floats = &[
            0.0f32,
            1.0f32,
            -1.0f32,
            f32::INFINITY,
            f32::NEG_INFINITY,
            f32::NAN,
            f32::MAX,
            f32::MIN,
            3.1415926535f32,
            -2.7182818284f32,
        ];

        let result = serialize_floats_to_bytes(floats);
        assert_eq!(result.len(), floats.len() * 4);

        // Verify each float individually
        for (i, &f) in floats.iter().enumerate() {
            let start = i * 4;
            let end = start + 4;
            let bytes = &result[start..end];
            let expected_bytes = f.to_bits().to_le_bytes();
            assert_eq!(bytes, expected_bytes);
        }
    }
}

