        buffers[2].extend(vec![1, 2, 3].into_iter());

        assert_eq!(buffers[0].pop_front(), Some(42));
        assert_eq!(buffers[1].pop_front(), Some(99));
        assert_eq!(buffers[2].len(), 3);
    }

    #[test]
    fn test_empty_buffers_are_independent() {
        let buffers = create_empty_buffers(2);

        // Clone one buffer to show they're independent
        let mut buffer1_clone = buffers[0].clone();
        let mut buffer2_clone = buffers[1].clone();

        // Modify clones without affecting originals
        buffer1_clone.push_back(1);
        buffer2_clone.push_back(2);

        assert!(buffers[0].is_empty());
        assert!(buffers[1].is_empty());
        assert_eq!(buffer1_clone.pop_front(), Some(1));
        assert_eq!(buffer2_clone.pop_front(), Some(2));
    }

    #[test]
    fn test_zero_allocation_until_first_insert() {
        let buffers = create_empty_buffers(5);

        for buffer in &buffers {
            // VecDeque::new() creates a zero-capacity buffer
            assert_eq!(buffer.capacity(), 0);

            // Verify no memory is allocated by checking the raw pointers
            // (VecDeque doesn't expose this directly, but we can infer from capacity)
            assert_eq!(buffer.len(), 0);
        }
    }

    #[test]
    fn test_buffers_are_properly_typed() {
        let buffers = create_empty_buffers(1);

        // Verify type is correct
        let buffer: &VecDeque<u8> = &buffers[0];
        assert_eq!(std::any::type_name::<VecDeque<u8>>(), std::any::type_name_of_val(buffer));
    }

    #[test]
    fn test_function_returns_vec_of_vecdeque() {
        let buffers = create_empty_buffers(3);

        // Verify the return type matches the signature
        let _: Vec<VecDeque<u8>> = buffers;
    }

    #[test]
    fn test_buffer_operations_after_creation() {
        let mut buffers = create_empty_buffers(2);

        // Test various operations on empty buffers
        assert_eq!(buffers[0].pop_front(), None);
        assert_eq!(buffers[0].pop_back(), None);
        assert_eq!(buffers[0].front(), None);
        assert_eq!(buffers[0].back(), None);

        // Test that we can insert and remove items
        buffers[0].push_back(10);
        buffers[0].push_back(20);
        assert_eq!(buffers[0].pop_front(), Some(10));
        assert_eq!(buffers[0].pop_front(), Some(20));
        assert!(buffers[0].is_empty());
    }
}

