mod tests {
    use std::net::Ipv6Addr;

    // Import the function from parent module (assuming it's in scope)
    use super::filter_unique_local_addresses;

    #[test]
    fn test_empty_input() {
        let addresses: &[Ipv6Addr] = &[];
        let result = filter_unique_local_addresses(addresses);
        assert!(result.is_empty());
    }

    #[test]
    fn test_all_unique_local_addresses() {
        let addresses = [
            // fc00::/7 range - first half
            "fc00::1".parse::<Ipv6Addr>().unwrap(),
            "fc00:1234:5678::abcd".parse().unwrap(),
            "fc00:ffff:ffff:ffff:ffff:ffff:ffff:ffff".parse().unwrap(),
            // fd00::/8 range - second half (commonly used for ULAs)
            "fd00::1".parse().unwrap(),
            "fd12:3456:789a::bcde".parse().unwrap(),
            "fdff:ffff:ffff:ffff:ffff:ffff:ffff:ffff".parse().unwrap(),
        ];

        let result = filter_unique_local_addresses(&addresses);
        assert_eq!(result.len(), addresses.len());
        assert!(result.iter().all(|addr| addr.is_unique_local()));
    }

    #[test]
    fn test_no_unique_local_addresses() {
        let addresses = [
            // Global unicast addresses
            "2001:0db8:85a3::8a2e:0370:7334".parse::<Ipv6Addr>().unwrap(),
            "2a00:1450:4001:827::200e".parse().unwrap(),
            // Link-local addresses
            "fe80::1".parse().unwrap(),
            "fe80::abcd:1234:5678:90ef".parse().unwrap(),
            // Loopback
            "::1".parse().unwrap(),
            // Unspecified
            "::".parse().unwrap(),
            // Multicast
            "ff02::1".parse().unwrap(),
        ];

        let result = filter_unique_local_addresses(&addresses);
        assert!(result.is_empty());
    }

    #[test]
    fn test_mixed_addresses() {
        let addresses = [
            // Unique local
            "fd00::1".parse::<Ipv6Addr>().unwrap(),
            // Global unicast
            "2001:db8::1".parse().unwrap(),
            // Unique local
            "fc00:1234::5678".parse().unwrap(),
            // Link-local
            "fe80::1".parse().unwrap(),
            // Unique local
            "fd12:3456::789a".parse().unwrap(),
            // Global unicast
            "2600::1".parse().unwrap(),
        ];

        let result = filter_unique_local_addresses(&addresses);
        assert_eq!(result.len(), 3);
        assert!(result.iter().all(|addr| addr.is_unique_local()));

        // Verify specific addresses are present
        let expected: Vec<Ipv6Addr> = vec![
            "fd00::1".parse().unwrap(),
            "fc00:1234::5678".parse().unwrap(),
            "fd12:3456::789a".parse().unwrap(),
        ];

        for addr in &expected {
            assert!(result.contains(addr));
        }
    }

    #[test]
    fn test_boundary_values() {
        let addresses = [
            // Lower boundary of fc00::/7
            "fc00::".parse::<Ipv6Addr>().unwrap(),
            "fc00::1".parse().unwrap(),
            // Upper boundary of fc00::/7 (fdff:...)
            "fdff:ffff:ffff:ffff:ffff:ffff:ffff:fffe".parse().unwrap(),
            "fdff:ffff:ffff:ffff:ffff:ffff:ffff:ffff".parse().unwrap(),
        ];

        let result = filter_unique_local_addresses(&addresses);
        assert_eq!(result.len(), addresses.len());

        // Test addresses just outside the range
        let outside_addresses = [
            // Just below fc00::/7
            "fbff:ffff:ffff:ffff:ffff:ffff:ffff:ffff".parse::<Ipv6Addr>().unwrap(),
            // Just above fc00::/7
            "fe00::".parse().unwrap(),
        ];

        let result_outside = filter_unique_local_addresses(&outside_addresses);
        assert!(result_outside.is_empty());
    }

    #[test]
    fn test_large_input() {
        // Create a mix of 1000 addresses
        let mut addresses = Vec::with_capacity(1000);

        for i in 0..1000 {
            if i % 3 == 0 {
                // Unique local addresses (fd00::/8)
                let addr_str = format!("fd00::{:x}", i);
                addresses.push(addr_str.parse::<Ipv6Addr>().unwrap());
            } else if i % 3 == 1 {
                // Global unicast
                let addr_str = format!("2001:db8::{:x}", i);
                addresses.push(addr_str.parse().unwrap());
            } else {
                // Link-local
                let addr_str = format!("fe80::{:x}", i);
                addresses.push(addr_str.parse().unwrap());
            }
        }

        let result = filter_unique_local_addresses(&addresses);
        // Approximately 1/3 should be unique local
        let expected_count = (1000 + 2) / 3; // Ceiling division
        assert_eq!(result.len(), expected_count);
        assert!(result.iter().all(|addr| addr.is_unique_local()));
    }

    #[test]
    fn test_preserves_order() {
        let addresses = [
            "fd00::1".parse::<Ipv6Addr>().unwrap(),
            "2001:db8::1".parse().unwrap(),
            "fc00::2".parse().unwrap(),
            "fe80::1".parse().unwrap(),
            "fd12::3456".parse().unwrap(),
        ];

        let result = filter_unique_local_addresses(&addresses);

        // Should preserve the order of unique local addresses as they appear in input
        assert_eq!(result.len(), 3);
        assert_eq!(result[0], "fd00::1".parse::<Ipv6Addr>().unwrap());
        assert_eq!(result[1], "fc00::2".parse::<Ipv6Addr>().unwrap());
        assert_eq!(result[2], "fd12::3456".parse::<Ipv6Addr>().unwrap());
    }
}

