mod tests {
    use std::net::Ipv6Addr;

    // Import the function from the parent module
    use super::is_link_local_address;

    #[test]
    fn test_link_local_addresses() {
        // Test addresses in the link-local range fe80::/10
        assert!(is_link_local_address(Ipv6Addr::new(0xfe80, 0, 0, 0, 0, 0, 0, 0)));
        assert!(is_link_local_address(Ipv6Addr::new(0xfe80, 0, 0, 0, 0, 0, 0, 1)));
        assert!(is_link_local_address(Ipv6Addr::new(0xfe80, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff)));

        // Test the upper boundary of link-local range (febf::/16 is within fe80::/10)
        assert!(is_link_local_address(Ipv6Addr::new(0xfebf, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff)));
    }

    #[test]
    fn test_non_link_local_addresses() {
        // Test addresses outside the link-local range

        // Just below link-local range
        assert!(!is_link_local_address(Ipv6Addr::new(0xfe7f, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff)));

        // Just above link-local range
        assert!(!is_link_local_address(Ipv6Addr::new(0xfec0, 0, 0, 0, 0, 0, 0, 0)));

        // Common non-link-local addresses
        assert!(!is_link_local_address(Ipv6Addr::new(0x2001, 0xdb8, 0, 0, 0, 0, 0, 1))); // Documentation address
        assert!(!is_link_local_address(Ipv6Addr::new(0x2001, 0, 0, 0, 0, 0, 0, 1))); // Global unicast
        assert!(!is_link_local_address(Ipv6Addr::new(0xff02, 0, 0, 0, 0, 0, 0, 1))); // Multicast
        assert!(!is_link_local_address(Ipv6Addr::LOCALHOST)); // ::1
        assert!(!is_link_local_address(Ipv6Addr::UNSPECIFIED)); // ::
    }

    #[test]
    fn test_boundary_addresses() {
        // Test boundary cases around fe80::/10

        // First address in link-local range
        assert!(is_link_local_address(Ipv6Addr::new(0xfe80, 0, 0, 0, 0, 0, 0, 0)));

        // Last address in link-local range
        assert!(is_link_local_address(Ipv6Addr::new(0xfebf, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff)));

        // Address immediately before link-local range
        assert!(!is_link_local_address(Ipv6Addr::new(0xfe7f, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff, 0xffff)));

        // Address immediately after link-local range
        assert!(!is_link_local_address(Ipv6Addr::new(0xfec0, 0, 0, 0, 0, 0, 0, 0)));
    }

    #[test]
    fn test_common_link_local_patterns() {
        // Test common link-local address patterns used in practice

        // Typical link-local address with interface identifier
        assert!(is_link_local_address("fe80::1".parse().unwrap()));
        assert!(is_link_local_address("fe80::abcd:1234:5678:9abc".parse().unwrap()));

        // Link-local address with zone index (zone index is not part of the address for this check)
        let addr_without_zone = "fe80::1".parse::<Ipv6Addr>().unwrap();
        assert!(is_link_local_address(addr_without_zone));

        // Addresses that look similar but aren't link-local
        assert!(!is_link_local_address("fe70::1".parse().unwrap()));
        assert!(!is_link_local_address("fec0::1".parse().unwrap()));
    }

    #[test]
    fn test_from_string_parsing() {
        // Test parsing from string representations

        // Valid link-local addresses
        assert!(is_link_local_address("fe80::".parse().unwrap()));
        assert!(is_link_local_address("fe80::1".parse().unwrap()));
        assert!(is_link_local_address("fe80:0:0:0:0:0:0:1".parse().unwrap()));
        assert!(is_link_local_address("fe80:1234:5678:9abc:def0:1234:5678:9abc".parse().unwrap()));

        // Invalid (not link-local)
        assert!(!is_link_local_address("2001:db8::1".parse().unwrap()));
        assert!(!is_link_local_address("::1".parse().unwrap()));
        assert!(!is_link_local_address("ff02::1".parse().unwrap()));
    }
}

