            NonZeroU32::new(10).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(1024).unwrap()),
            NonZeroU32::new(32).unwrap()
        );
    }

    #[test]
    fn test_non_perfect_squares() {
        // Test cases where input is NOT a perfect square
        assert_eq!(
            largest_square_size(NonZeroU32::new(2).unwrap()),
            NonZeroU32::new(1).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(3).unwrap()),
            NonZeroU32::new(1).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(5).unwrap()),
            NonZeroU32::new(2).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(10).unwrap()),
            NonZeroU32::new(3).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(37).unwrap()),
            NonZeroU32::new(6).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(50).unwrap()),
            NonZeroU32::new(7).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(99).unwrap()),
            NonZeroU32::new(9).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(1025).unwrap()),
            NonZeroU32::new(32).unwrap()
        );
    }

    #[test]
    fn test_edge_cases() {
        // Test minimum and maximum values
        assert_eq!(
            largest_square_size(NonZeroU32::new(1).unwrap()),
            NonZeroU32::new(1).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(u32::MAX).unwrap()),
            NonZeroU32::new(65535).unwrap()  // sqrt(2^32 - 1) = 65535.999...
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(u32::MAX - 1).unwrap()),
            NonZeroU32::new(65535).unwrap()
        );
    }

    #[test]
    fn test_powers_of_two() {
        // Test powers of two which are often edge cases
        assert_eq!(
            largest_square_size(NonZeroU32::new(2).unwrap()),
            NonZeroU32::new(1).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(8).unwrap()),
            NonZeroU32::new(2).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(32).unwrap()),
            NonZeroU32::new(5).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(128).unwrap()),
            NonZeroU32::new(11).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(512).unwrap()),
            NonZeroU32::new(22).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(2048).unwrap()),
            NonZeroU32::new(45).unwrap()
        );
    }

    #[test]
    fn test_sequential_values() {
        // Test a sequence of consecutive values to ensure monotonic behavior
        let mut prev = 0;
        for i in 1..=100 {
            let result = largest_square_size(NonZeroU32::new(i).unwrap()).get();
            // The result should be non-decreasing
            assert!(result >= prev, "Result decreased at i={}: {} < {}", i, result, prev);
            // The square of result should be <= i
            assert!(result * result <= i, "Square too large at i={}: {}^2 = {} > {}", i, result, result * result, i);
            // The next square should be > i
            assert!((result + 1) * (result + 1) > i || i == u32::MAX, "Could fit larger square at i={}", i);
            prev = result;
        }
    }

    #[test]
    fn test_specific_examples_from_query() {
        // Test the specific examples mentioned in the query
        assert_eq!(
            largest_square_size(NonZeroU32::new(36).unwrap()),
            NonZeroU32::new(6).unwrap()
        );
        assert_eq!(
            largest_square_size(NonZeroU32::new(37).unwrap()),
            NonZeroU32::new(6).unwrap()
        );
    }

    #[test]
    fn test_property_based() {
        // Test that for any input n, result^2 <= n < (result+1)^2
        // Use a selection of test values across the range
        let test_values = vec![
            1, 2, 3, 4, 5, 10, 25, 50, 100, 500, 1000, 5000, 10000,
            50000, 100000, 500000, 1000000, 5000000, 10000000,
            u32::MAX / 2, u32::MAX - 1000, u32::MAX - 1, u32::MAX,
        ];

        for &n in &test_values {
            let result = largest_square_size(NonZeroU32::new(n).unwrap()).get();
            assert!(
                result * result <= n,
                "Failed for n={}: {}^2 = {} > {}",
                n, result, result * result, n
            );
            if result < 65535 {  // Avoid overflow for (result+1)^2
                assert!(
                    (result + 1) * (result + 1) > n,
                    "Failed for n={}: ({} + 1)^2 = {} <= {}",
                    n, result, (result + 1) * (result + 1), n
                );
            }
        }
    }
}

