mod tests {
    use super::*;
    use std::collections::BTreeSet;

    #[test]
    fn test_extract_and_remove_present() {
        let mut set = BTreeSet::new();
        set.insert(42);
        set.insert(10);
        set.insert(99);

        let result = extract_and_remove(&mut set, 42);

        assert_eq!(result, Some(42));
        assert!(!set.contains(&42));
        assert_eq!(set.len(), 2);
        assert!(set.contains(&10));
        assert!(set.contains(&99));
    }

    #[test]
    fn test_extract_and_remove_absent() {
        let mut set = BTreeSet::new();
        set.insert(1);
        set.insert(2);
        set.insert(3);

        let result = extract_and_remove(&mut set, 42);

        assert_eq!(result, None);
        assert_eq!(set.len(), 3);
        assert!(set.contains(&1));
        assert!(set.contains(&2));
        assert!(set.contains(&3));
    }

    #[test]
    fn test_extract_and_remove_from_empty_set() {
        let mut set = BTreeSet::new();

        let result = extract_and_remove(&mut set, 42);

        assert_eq!(result, None);
        assert!(set.is_empty());
    }

    #[test]
    fn test_extract_and_remove_single_element() {
        let mut set = BTreeSet::new();
        set.insert(100);

        let result = extract_and_remove(&mut set, 100);

        assert_eq!(result, Some(100));
        assert!(set.is_empty());
    }

    #[test]
    fn test_extract_and_remove_duplicate_calls() {
        let mut set = BTreeSet::new();
        set.insert(5);
        set.insert(6);
        set.insert(7);

        // First call should succeed
        let result1 = extract_and_remove(&mut set, 6);
        assert_eq!(result1, Some(6));
        assert!(!set.contains(&6));
        assert_eq!(set.len(), 2);

        // Second call should fail
        let result2 = extract_and_remove(&mut set, 6);
        assert_eq!(result2, None);
        assert_eq!(set.len(), 2);
    }

    #[test]
    fn test_extract_and_remove_negative_numbers() {
        let mut set = BTreeSet::new();
        set.insert(-10);
        set.insert(0);
        set.insert(10);

        let result = extract_and_remove(&mut set, -10);

        assert_eq!(result, Some(-10));
        assert!(!set.contains(&-10));
        assert!(set.contains(&0));
        assert!(set.contains(&10));
    }

    #[test]
    fn test_extract_and_remove_large_set() {
        let mut set = BTreeSet::new();
        for i in 0..1000 {
            set.insert(i);
        }

        let result = extract_and_remove(&mut set, 500);

        assert_eq!(result, Some(500));
        assert!(!set.contains(&500));
        assert_eq!(set.len(), 999);

        // Verify some other elements are still present
        assert!(set.contains(&0));
        assert!(set.contains(&999));
        assert!(set.contains(&250));
        assert!(set.contains(&750));
    }

    #[test]
    fn test_extract_and_remove_preserves_ordering() {
        let mut set = BTreeSet::new();
        set.insert(3);
        set.insert(1);
        set.insert(4);
        set.insert(2);

        let result = extract_and_remove(&mut set, 3);

        assert_eq!(result, Some(3));

        // Collect remaining elements to verify ordering
        let remaining: Vec<_> = set.iter().cloned().collect();
        assert_eq!(remaining, vec![1, 2, 4]);
    }

    #[test]
    fn test_extract_and_remove_boundary_values() {
        let mut set = BTreeSet::new();
        set.insert(i32::MIN);
        set.insert(0);
        set.insert(i32::MAX);

        let result_min = extract_and_remove(&mut set, i32::MIN);
        assert_eq!(result_min, Some(i32::MIN));
        assert!(!set.contains(&i32::MIN));

        let result_max = extract_and_remove(&mut set, i32::MAX);
        assert_eq!(result_max, Some(i32::MAX));
        assert!(!set.contains(&i32::MAX));

        assert_eq!(set.len(), 1);
        assert!(set.contains(&0));
    }
}

