#[cfg(test)]
mod tests {
    use super::constrain_energy;

    #[test]
    fn test_energy_within_bounds() {
        // Energy already within bounds should remain unchanged
        assert_eq!(constrain_energy(5.0, 0.0, 10.0), 5.0);
        assert_eq!(constrain_energy(-2.5, -5.0, 5.0), -2.5);
        assert_eq!(constrain_energy(0.0, -1.0, 1.0), 0.0);
    }

    #[test]
    fn test_energy_below_min_bound() {
        // Energy below minimum should be clamped to min_bound
        assert_eq!(constrain_energy(-5.0, 0.0, 10.0), 0.0);
        assert_eq!(constrain_energy(2.0, 5.0, 10.0), 5.0);
        assert_eq!(constrain_energy(-10.0, -5.0, 5.0), -5.0);
    }

    #[test]
    fn test_energy_above_max_bound() {
        // Energy above maximum should be clamped to max_bound
        assert_eq!(constrain_energy(15.0, 0.0, 10.0), 10.0);
        assert_eq!(constrain_energy(12.0, 5.0, 10.0), 10.0);
        assert_eq!(constrain_energy(10.0, -5.0, 5.0), 5.0);
    }

    #[test]
    fn test_equal_bounds() {
        // When min_bound == max_bound, all values should be clamped to that value
        assert_eq!(constrain_energy(5.0, 3.0, 3.0), 3.0);
        assert_eq!(constrain_energy(0.0, 3.0, 3.0), 3.0);
        assert_eq!(constrain_energy(10.0, 3.0, 3.0), 3.0);
        assert_eq!(constrain_energy(3.0, 3.0, 3.0), 3.0);
    }

    #[test]
    fn test_special_float_values() {
        // Test with special floating-point values
        assert!(constrain_energy(f64::NAN, 0.0, 10.0).is_nan());
        assert_eq!(constrain_energy(f64::INFINITY, 0.0, 10.0), 10.0);
        assert_eq!(constrain_energy(f64::NEG_INFINITY, 0.0, 10.0), 0.0);

        // Test with bounds that are special float values
        assert_eq!(constrain_energy(5.0, f64::NEG_INFINITY, f64::INFINITY), 5.0);
        assert_eq!(constrain_energy(f64::INFINITY, f64::NEG_INFINITY, f64::INFINITY), f64::INFINITY);
        assert_eq!(constrain_energy(f64::NEG_INFINITY, f64::NEG_INFINITY, f64::INFINITY), f64::NEG_INFINITY);
    }

    #[test]
    fn test_edge_cases() {
        // Test exactly at bounds
        assert_eq!(constrain_energy(0.0, 0.0, 10.0), 0.0);
        assert_eq!(constrain_energy(10.0, 0.0, 10.0), 10.0);

        // Test with very small and very large numbers
        assert_eq!(constrain_energy(1e-100, 0.0, 1.0), 1e-100);
        assert_eq!(constrain_energy(1e100, 0.0, 1.0), 1.0);

        // Test negative bounds
        assert_eq!(constrain_energy(-15.0, -20.0, -10.0), -15.0);
        assert_eq!(constrain_energy(-25.0, -20.0, -10.0), -20.0);
        assert_eq!(constrain_energy(-5.0, -20.0, -10.0), -10.0);
    }

    #[test]
    fn test_precision_handling() {
        // Test that the function handles floating-point precision appropriately
        let min = 0.1 + 0.2; // Not exactly 0.3 due to floating-point arithmetic
        let max = 0.6 + 0.7; // Not exactly 1.3

        // Values close to bounds should work correctly
        // Using approx comparison for floating point values
        let result1 = constrain_energy(0.3, min, max);
        let result2 = constrain_energy(1.3, min, max);
        let result3 = constrain_energy(0.29999999999999999, min, max);

        assert!((result1 - 0.3).abs() < 1e-10);
        assert!((result2 - max).abs() < 1e-10);
        assert!((result3 - min).abs() < 1e-10);
    }
}

