use std::fmt;
use std::num::NonZeroU32;

fn format_nonzero_id(id: NonZeroU32, format_type: &str) -> String {
    match format_type {
        "decimal" => format!("{}", id),
        "hex" => format!("{:x}", id),
        "HEX" => format!("{:X}", id),
        _ => format!("{}", id),
    }
}

