        assert_eq!(format_nonzero_id(id, "decimal"), "42");

        let id = NonZeroU32::new(1).unwrap();
        assert_eq!(format_nonzero_id(id, "decimal"), "1");

        let id = NonZeroU32::new(u32::MAX).unwrap();
        assert_eq!(format_nonzero_id(id, "decimal"), u32::MAX.to_string());
    }

    #[test]
    fn test_format_lowercase_hex() {
        let id = NonZeroU32::new(255).unwrap();
        assert_eq!(format_nonzero_id(id, "hex"), "ff");

        let id = NonZeroU32::new(0xdeadbeef).unwrap();
        assert_eq!(format_nonzero_id(id, "hex"), "deadbeef");

        let id = NonZeroU32::new(0x1a2b3c4d).unwrap();
        assert_eq!(format_nonzero_id(id, "hex"), "1a2b3c4d");
    }

    #[test]
    fn test_format_uppercase_hex() {
        let id = NonZeroU32::new(255).unwrap();
        assert_eq!(format_nonzero_id(id, "HEX"), "FF");

        let id = NonZeroU32::new(0xdeadbeef).unwrap();
        assert_eq!(format_nonzero_id(id, "HEX"), "DEADBEEF");

        let id = NonZeroU32::new(0x1a2b3c4d).unwrap();
        assert_eq!(format_nonzero_id(id, "HEX"), "1A2B3C4D");
    }

    #[test]
    fn test_unknown_format_type_falls_back_to_decimal() {
        let id = NonZeroU32::new(123).unwrap();

        // Test various unknown format types
        assert_eq!(format_nonzero_id(id, "binary"), "123");
        assert_eq!(format_nonzero_id(id, "octal"), "123");
        assert_eq!(format_nonzero_id(id, "unknown"), "123");
        assert_eq!(format_nonzero_id(id, ""), "123");
        assert_eq!(format_nonzero_id(id, "HEXADECIMAL"), "123");
    }

    #[test]
    fn test_edge_cases() {
        // Minimum non-zero value
        let id = NonZeroU32::new(1).unwrap();
        assert_eq!(format_nonzero_id(id, "decimal"), "1");
        assert_eq!(format_nonzero_id(id, "hex"), "1");
        assert_eq!(format_nonzero_id(id, "HEX"), "1");

        // Maximum value
        let id = NonZeroU32::new(u32::MAX).unwrap();
        let expected_hex = format!("{:x}", u32::MAX);
        let expected_HEX = format!("{:X}", u32::MAX);

        assert_eq!(format_nonzero_id(id, "decimal"), u32::MAX.to_string());
        assert_eq!(format_nonzero_id(id, "hex"), expected_hex);
        assert_eq!(format_nonzero_id(id, "HEX"), expected_HEX);
    }

    #[test]
    fn test_case_sensitivity() {
        let id = NonZeroU32::new(255).unwrap();

        // Verify case sensitivity
        assert_eq!(format_nonzero_id(id, "hex"), "ff");
        assert_eq!(format_nonzero_id(id, "HEX"), "FF");
        assert_ne!(format_nonzero_id(id, "hex"), format_nonzero_id(id, "HEX"));

        // Mixed case should fall back to decimal
        assert_eq!(format_nonzero_id(id, "Hex"), "255");
        assert_eq!(format_nonzero_id(id, "hEx"), "255");
    }

    #[test]
    fn test_format_type_matching_exact_strings() {
        let id = NonZeroU32::new(100).unwrap();

        // Only exact matches should work
        assert_eq!(format_nonzero_id(id, "decimal"), "100");
        assert_eq!(format_nonzero_id(id, "hex"), "64");
        assert_eq!(format_nonzero_id(id, "HEX"), "64");

        // Extra whitespace or characters should cause fallback
        assert_eq!(format_nonzero_id(id, " decimal"), "100");
        assert_eq!(format_nonzero_id(id, "decimal "), "100");
        assert_eq!(format_nonzero_id(id, " hex "), "100");
    }
}

