#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_reciprocals() {
        let input = [1.0, 2.0, 4.0, 8.0];
        let result = const_reciprocals(&input);
        let expected = [1.0, 0.5, 0.25, 0.125];
        assert_eq!(result.len(), expected.len());
        for (r, e) in result.iter().zip(expected.iter()) {
            assert!((r - e).abs() < f32::EPSILON);
        }
    }

    #[test]
    fn test_negative_values() {
        let input = [-1.0, -2.0, -4.0];
        let result = const_reciprocals(&input);
        let expected = [-1.0, -0.5, -0.25];
        assert_eq!(result.len(), expected.len());
        for (r, e) in result.iter().zip(expected.iter()) {
            assert!((r - e).abs() < f32::EPSILON);
        }
    }

    #[test]
    fn test_mixed_values() {
        let input = [0.5, -0.25, 10.0, -100.0];
        let result = const_reciprocals(&input);
        let expected = [2.0, -4.0, 0.1, -0.01];
        assert_eq!(result.len(), expected.len());
        for (r, e) in result.iter().zip(expected.iter()) {
            assert!((r - e).abs() < f32::EPSILON * 10.0);
        }
    }

    #[test]
    fn test_special_values() {
        let input = [f32::INFINITY, f32::NEG_INFINITY, f32::NAN, 0.0];
        let result = const_reciprocals(&input);

        // Test infinity reciprocals
        assert_eq!(result[0], 0.0);
        assert_eq!(result[1], 0.0);

        // Test NaN propagates
        assert!(result[2].is_nan());

        // Test zero reciprocal
        assert_eq!(result[3], f32::INFINITY);
    }

    #[test]
    fn test_empty_slice() {
        let input: [f32; 0] = [];
        let result = const_reciprocals(&input);
        assert!(result.is_empty());
    }

    #[test]
    fn test_single_value() {
        let input = [42.0];
        let result = const_reciprocals(&input);
        assert_eq!(result.len(), 1);
        assert!((result[0] - (1.0 / 42.0)).abs() < f32::EPSILON);
    }

    #[test]
    fn test_large_slice() {
        let input: Vec<f32> = (1..=100).map(|x| x as f32).collect();
        let result = const_reciprocals(&input);
        assert_eq!(result.len(), 100);
        for (i, &val) in result.iter().enumerate() {
            let expected = 1.0 / ((i + 1) as f32);
            assert!((val - expected).abs() < f32::EPSILON);
        }
    }

    #[test]
    fn test_reciprocal_identity() {
        let input = [1.0, 0.5, 2.0, 4.0, 0.25];
        let result = const_reciprocals(&input);
        let double_reciprocal: Vec<f32> = result.iter().map(|&x| x.recip()).collect();

        for (original, double_rec) in input.iter().zip(double_reciprocal.iter()) {
            // Skip NaN comparisons
            if original.is_nan() {
                continue;
            }
            assert!((original - double_rec).abs() < f32::EPSILON * 10.0);
        }
    }

    #[test]
    fn test_const_context() {
        // Since const_reciprocals is not a const function, we cannot use it in const context
        // We'll test the runtime behavior instead
        const VALUES: [f32; 3] = [1.0, 2.0, 4.0];
        let result = const_reciprocals(&VALUES);

        assert_eq!(result[0], 1.0);
        assert_eq!(result[1], 0.5);
        assert_eq!(result[2], 0.25);
    }

    #[test]
    fn test_edge_cases() {
        let input = [
            f32::MIN_POSITIVE,
            f32::MAX,
            f32::MIN,
            f32::EPSILON,
        ];
        let result = const_reciprocals(&input);

        // f32::MIN_POSITIVE reciprocal should be large
        assert!(result[0] > 1.0);

        // f32::MAX reciprocal should be very small but positive
        assert!(result[1] > 0.0 && result[1] < f32::EPSILON);

        // f32::MIN reciprocal should be negative and very small
        assert!(result[2] < 0.0 && result[2] > -f32::EPSILON);

        // f32::EPSILON reciprocal should be large
        assert!(result[3] > 1.0);
    }
}

