#[cfg(test)]
mod tests {
    use std::thread;
    use std::sync::{Arc, atomic::{AtomicBool, Ordering}};
    use std::time::Duration;

    // Import the function from the parent module
    use super::notify_thread_to_resume;

    #[test]
    fn test_notify_thread_to_resume_success() {
        // Create a thread that waits for unpark
        let flag = Arc::new(AtomicBool::new(false));
        let flag_clone = Arc::clone(&flag);

        let worker = thread::spawn(move || {
            // Park the thread until unparked
            thread::park();
            flag_clone.store(true, Ordering::SeqCst);
        });

        // Give the thread a moment to start and park
        thread::sleep(Duration::from_millis(10));

        // Test the notification function
        let result = notify_thread_to_resume(worker.thread());

        // Verify the function returns success
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), ());

        // Wait for thread to process the unpark
        worker.join().expect("Thread should join successfully");

        // Verify the flag was set (thread resumed)
        assert!(flag.load(Ordering::SeqCst));
    }

    #[test]
    fn test_notify_thread_to_resume_multiple_times() {
        let counter = Arc::new(AtomicBool::new(false));
        let counter_clone = Arc::clone(&counter);

        let worker = thread::spawn(move || {
            // Park and wait for unpark
            thread::park();
            counter_clone.store(true, Ordering::SeqCst);
        });

        thread::sleep(Duration::from_millis(10));

        // Call multiple times - should not fail
        let thread_ref = worker.thread();
        for _ in 0..3 {
            let result = notify_thread_to_resume(thread_ref);
            assert!(result.is_ok());
        }

        worker.join().expect("Thread should join");
        assert!(counter.load(Ordering::SeqCst));
    }

    #[test]
    fn test_notify_thread_to_resume_already_running() {
        let flag = Arc::new(AtomicBool::new(false));
        let flag_clone = Arc::clone(&flag);

        let worker = thread::spawn(move || {
            // Don't park, just do some work
            for i in 0..1000 {
                let _ = i * i; // Some dummy work
            }
            flag_clone.store(true, Ordering::SeqCst);
        });

        // Notify while thread is running (not parked)
        let result = notify_thread_to_resume(worker.thread());
        assert!(result.is_ok());

        worker.join().expect("Thread should join");
        assert!(flag.load(Ordering::SeqCst));
    }

    #[test]
    fn test_notify_thread_to_resume_with_finished_thread() {
        let flag = Arc::new(AtomicBool::new(false));
        let flag_clone = Arc::clone(&flag);

        let worker = thread::spawn(move || {
            flag_clone.store(true, Ordering::SeqCst);
        });

        // Wait for thread to finish
        worker.join().expect("Thread should join");

        // Try to notify a finished thread
        // Note: We need to store the thread reference before it finishes
        // Since we can't get a reference to a finished thread, we'll create a new one
        let temp_thread = thread::current();
        let result = notify_thread_to_resume(&temp_thread);

        // Should still succeed - unparking a running thread is valid
        assert!(result.is_ok());
        assert!(flag.load(Ordering::SeqCst));
    }

    #[test]
    fn test_notify_thread_to_resume_concurrent_access() {
        let num_threads = 5;
        let mut handles = vec![];

        for i in 0..num_threads {
            let i_clone = i; // Clone i to move into closure
            let handle = thread::spawn(move || {
                let worker = thread::spawn(move || {
                    thread::park();
                    i_clone // Return the index
                });

                thread::sleep(Duration::from_millis(i_clone as u64 * 10));

                let result = notify_thread_to_resume(worker.thread());
                assert!(result.is_ok());

                worker.join().expect("Worker should join")
            });

            handles.push(handle);
        }

        // Collect results from all coordinator threads
        let results: Vec<_> = handles.into_iter()
            .map(|h| h.join().expect("Coordinator should join"))
            .collect();

        // Verify all threads completed successfully
        assert_eq!(results.len(), num_threads);
        for i in 0..num_threads {
            assert!(results.contains(&i));
        }
    }

    #[test]
    fn test_notify_thread_to_resume_thread_local() {
        // Test with the current thread
        let current_thread = thread::current();
        let result = notify_thread_to_resume(&current_thread);
        assert!(result.is_ok());
    }

    #[test]
    fn test_notify_thread_to_resume_never_returns_error() {
        // This test verifies the function signature always returns Ok(())
        // by testing it doesn't panic or return Err in various scenarios

        let scenarios = vec![
            // Scenario 1: Normal thread
            thread::spawn(|| thread::park()),
            // Scenario 2: Busy thread
            thread::spawn(|| {
                for _ in 0..1000 {
                    thread::yield_now();
                }
            }),
        ];

        for worker in scenarios {
            let result = notify_thread_to_resume(worker.thread());
            assert!(result.is_ok(), "Function should never return error");
            assert_eq!(result.unwrap(), ());

            worker.join().expect("Thread should join");
        }
    }
}

