mod tests {
    use super::*;
    use std::f32::consts::PI;

    #[test]
    fn test_geographic_midpoint_basic() {
        // Basic test with simple coordinates
        let (lat, lon) = geographic_midpoint(0.0, 0.0, 10.0, 10.0);
        assert_eq!(lat, 5.0);
        assert_eq!(lon, 5.0);
    }

    #[test]
    fn test_geographic_midpoint_negative_coordinates() {
        // Test with negative coordinates
        let (lat, lon) = geographic_midpoint(-10.0, -20.0, 10.0, 20.0);
        assert_eq!(lat, 0.0);
        assert_eq!(lon, 0.0);
    }

    #[test]
    fn test_geographic_midpoint_same_point() {
        // Test when both points are identical
        let (lat, lon) = geographic_midpoint(45.0, 90.0, 45.0, 90.0);
        assert_eq!(lat, 45.0);
        assert_eq!(lon, 90.0);
    }

    #[test]
    fn test_geographic_midpoint_extreme_latitudes() {
        // Test near poles
        let (lat, lon) = geographic_midpoint(89.0, 0.0, 89.5, 180.0);
        assert_eq!(lat, 89.25);
        // Using f32::midpoint for 0.0 and 180.0 gives 90.0
        assert_eq!(lon, 90.0);
    }

    #[test]
    fn test_geographic_midpoint_antimeridian() {
        // Test crossing the antimeridian (180° longitude)
        let (lat, lon) = geographic_midpoint(0.0, 170.0, 0.0, -170.0);
        assert_eq!(lat, 0.0);
        // f32::midpoint(170.0, -170.0) = 0.0
        assert_eq!(lon, 0.0);
    }

    #[test]
    fn test_geographic_midpoint_large_numbers() {
        // Test with large coordinate values
        let (lat, lon) = geographic_midpoint(1000.0, 2000.0, 3000.0, 4000.0);
        assert_eq!(lat, 2000.0);
        assert_eq!(lon, 3000.0);
    }

    #[test]
    fn test_geographic_midpoint_small_numbers() {
        // Test with very small coordinate values
        let (lat, lon) = geographic_midpoint(0.0001, 0.0002, 0.0003, 0.0004);
        // Use epsilon comparison for floating point precision
        assert!((lat - 0.0002).abs() < f32::EPSILON * 10.0);
        assert!((lon - 0.0003).abs() < f32::EPSILON * 10.0);
    }

    #[test]
    fn test_geographic_midpoint_near_zero() {
        // Test coordinates very close to zero
        let (lat, lon) = geographic_midpoint(-0.0001, -0.0002, 0.0001, 0.0002);
        // f32::midpoint should give exactly 0.0 for symmetric values around 0
        assert_eq!(lat, 0.0);
        assert_eq!(lon, 0.0);
    }

    #[test]
    fn test_geographic_midpoint_float_precision() {
        // Test to verify floating point precision handling
        let (lat, lon) = geographic_midpoint(1.0 / 3.0, 2.0 / 3.0, 2.0 / 3.0, 1.0 / 3.0);
        let expected_lat = 0.5;
        let expected_lon = 0.5;

        // Use epsilon comparison for floating point values
        assert!((lat - expected_lat).abs() < f32::EPSILON * 10.0);
        assert!((lon - expected_lon).abs() < f32::EPSILON * 10.0);
    }

    #[test]
    fn test_geographic_midpoint_radian_conversion() {
        // Test with coordinates in radians (though function expects degrees)
        // This tests the function's behavior with any f32 values
        let (lat, lon) = geographic_midpoint(PI / 4.0, PI / 2.0, PI / 2.0, PI);
        let expected_lat = 3.0 * PI / 8.0;
        let expected_lon = 3.0 * PI / 4.0;

        assert!((lat - expected_lat).abs() < f32::EPSILON * 10.0);
        assert!((lon - expected_lon).abs() < f32::EPSILON * 10.0);
    }

    #[test]
    fn test_geographic_midpoint_commutative() {
        // Test that midpoint calculation is commutative
        let (lat1, lon1) = geographic_midpoint(10.0, 20.0, 30.0, 40.0);
        let (lat2, lon2) = geographic_midpoint(30.0, 40.0, 10.0, 20.0);

        assert_eq!(lat1, lat2);
        assert_eq!(lon1, lon2);
    }

    #[test]
    fn test_geographic_midpoint_extreme_values() {
        // Test with extreme f32 values
        let (lat, lon) = geographic_midpoint(f32::MIN, f32::MIN, f32::MAX, f32::MAX);
        // f32::midpoint(MIN, MAX) should be 0.0
        assert_eq!(lat, 0.0);
        assert_eq!(lon, 0.0);
    }

    #[test]
    fn test_geographic_midpoint_nan_inf() {
        // Test that function handles NaN and Infinity (though not typical for coordinates)
        // This tests the function's robustness
        let (lat, lon) = geographic_midpoint(f32::NAN, f32::INFINITY, 0.0, 0.0);
        // f32::midpoint(NaN, x) returns NaN, midpoint(INFINITY, 0.0) returns INFINITY
        assert!(lat.is_nan());
        assert!(lon.is_infinite() && lon > 0.0);
    }
}

