#[cfg(test)]
mod tests {
    use std::task::Waker;

    #[test]
    fn test_get_inert_waker_returns_static_reference() {
        let waker = super::get_inert_waker();
        // Should be able to get multiple references
        let waker2 = super::get_inert_waker();
        // Both should point to the same memory location
        assert!(std::ptr::eq(waker, waker2));
    }

    #[test]
    fn test_inert_waker_is_send_and_sync() {
        let waker = super::get_inert_waker();
        // Verify it can be sent between threads
        std::thread::spawn(move || {
            let _waker_ref: &'static Waker = waker;
        }).join().unwrap();
    }

    #[test]
    fn test_inert_waker_wake_does_nothing() {
        let waker = super::get_inert_waker();
        // Calling wake should not panic or have side effects
        waker.wake_by_ref();
        // For wake(), we need to clone since it consumes the waker
        waker.clone().wake();
    }

    #[test]
    fn test_inert_waker_clone() {
        let waker = super::get_inert_waker();
        let cloned = waker.clone();
        // Both should behave identically
        cloned.wake_by_ref();
        waker.wake_by_ref();
    }

    #[test]
    fn test_inert_waker_in_context() {
        use std::task::{Context, Poll};

        let waker = super::get_inert_waker();
        let mut cx = Context::from_waker(waker);

        // Should be able to extract waker back
        let extracted_waker = cx.waker();
        extracted_waker.wake_by_ref();

        // Context should be usable with futures
        let mut future = std::future::ready(42);
        match std::future::Future::poll(
            std::pin::Pin::new(&mut future), 
            &mut cx
        ) {
            Poll::Ready(val) => assert_eq!(val, 42),
            Poll::Pending => panic!("Ready future should not be pending"),
        }
    }

    #[test]
    fn test_multiple_threads_access() {
        use std::thread;

        let handles: Vec<_> = (0..10).map(|i| {
            thread::spawn(move || {
                let waker = super::get_inert_waker();
                waker.wake_by_ref();
                i
            })
        }).collect();

        for handle in handles {
            handle.join().unwrap();
        }
    }

    #[test]
    fn test_waker_debug() {
        let waker = super::get_inert_waker();
        let debug_output = format!("{:?}", waker);
        // Should not panic and produce some debug output
        assert!(!debug_output.is_empty());
    }

    #[test]
    fn test_waker_drop() {
        let waker = super::get_inert_waker();
        drop(waker.clone());
        // Original should still be usable
        waker.wake_by_ref();
    }
}

