#[cfg(test)]
mod tests {
    use super::*;
    use std::f64;

    #[test]
    fn test_positive_numbers() {
        // Test with positive numbers
        assert_eq!(find_strictly_less_bound(1.0), 1.0f64.next_down());
        assert_eq!(find_strictly_less_bound(100.5), 100.5f64.next_down());
        assert_eq!(find_strictly_less_bound(0.1), 0.1f64.next_down());
    }

    #[test]
    fn test_negative_numbers() {
        // Test with negative numbers
        assert_eq!(find_strictly_less_bound(-1.0), (-1.0f64).next_down());
        assert_eq!(find_strictly_less_bound(-100.5), (-100.5f64).next_down());
        assert_eq!(find_strictly_less_bound(-0.1), (-0.1f64).next_down());
    }

    #[test]
    fn test_zero() {
        // Test with zero
        assert_eq!(find_strictly_less_bound(0.0), 0.0f64.next_down());
        assert_eq!(find_strictly_less_bound(-0.0), (-0.0f64).next_down());
    }

    #[test]
    fn test_special_values() {
        // Test with special floating-point values
        assert_eq!(find_strictly_less_bound(f64::INFINITY), f64::INFINITY.next_down());
        assert_eq!(find_strictly_less_bound(f64::NEG_INFINITY), f64::NEG_INFINITY.next_down());

        // NaN should propagate
        assert!(find_strictly_less_bound(f64::NAN).is_nan());
    }

    #[test]
    fn test_extreme_values() {
        // Test with extreme values
        assert_eq!(find_strictly_less_bound(f64::MAX), f64::MAX.next_down());
        assert_eq!(find_strictly_less_bound(f64::MIN), f64::MIN.next_down());
        assert_eq!(find_strictly_less_bound(f64::MIN_POSITIVE), f64::MIN_POSITIVE.next_down());
    }

    #[test]
    fn test_property_strictly_less() {
        // Verify that the result is strictly less than input for normal numbers
        let test_values = [1.0, 2.5, -3.7, 0.0, 1e-10, 1e10, -1e-10, -1e10];

        for &value in &test_values {
            let result = find_strictly_less_bound(value);
            if value.is_finite() {
                assert!(result < value, "Result {} should be strictly less than {}", result, value);
            }
        }
    }

    #[test]
    fn test_property_next_down_equivalence() {
        // Verify that the function is equivalent to next_down() for various inputs
        let test_values = [
            0.0, 1.0, -1.0, 
            3.141592653589793,  // pi
            2.718281828459045,  // e
            1.0 / 3.0,
            f64::consts::SQRT_2,
        ];

        for &value in &test_values {
            assert_eq!(find_strictly_less_bound(value), value.next_down());
        }
    }

    #[test]
    fn test_subnormal_numbers() {
        // Test with subnormal numbers
        let subnormal = f64::MIN_POSITIVE / 2.0;  // A subnormal number

        // Verify the function works with subnormals
        let result = find_strictly_less_bound(subnormal);
        assert!(result.is_finite());
        assert!(result < subnormal || result.is_nan());
    }

    #[test]
    fn test_adjacent_values() {
        // Test that consecutive calls produce different results
        let value = 42.0;
        let first_result = find_strictly_less_bound(value);
        let second_result = find_strictly_less_bound(first_result);

        assert!(second_result < first_result);
        assert!(first_result < value);
    }
}

