    }

    #[test]
    fn test_negative_subseconds() {
        // Durations can't be negative, so we test with valid positive values
        let durations = &[
            Duration::new(1, 500_000_000),  // 1.5 seconds
            Duration::new(0, 500_000_000),  // 0.5 seconds
        ];
        assert_eq!(total_nanoseconds(durations), 2_000_000_000);
    }

    #[test]
    fn test_precision_preservation() {
        let durations = &[
            Duration::new(0, 1),  // 1 nanosecond
            Duration::new(0, 999_999_999),  // 999,999,999 nanoseconds
        ];
        assert_eq!(total_nanoseconds(durations), 1_000_000_000);
    }

    #[test]
    fn test_many_durations() {
        let mut durations = Vec::new();
        for i in 0..1000 {
            durations.push(Duration::from_nanos(i as u64));
        }
        let expected = (0..1000u128).sum::<u128>();
        assert_eq!(total_nanoseconds(&durations), expected);
    }

    #[test]
    fn test_as_nanos_overflow_protection() {
        // This test specifically verifies that using as_nanos() (which returns u128)
        // protects against overflow that could happen with other methods
        let max_secs = Duration::new(u64::MAX, 999_999_999);
        let durations = &[max_secs, max_secs];

        // This would overflow with naive second/nanosecond arithmetic
        // but should work with as_nanos()
        let result = total_nanoseconds(durations);
        let single_duration_nanos = (u64::MAX as u128) * 1_000_000_000 + 999_999_999;
        assert_eq!(result, single_duration_nanos * 2);
    }
}

