mod tests {
    use std::ffi::{CStr, FromBytesWithNulError};
    use super::validate_c_string;

    #[test]
    fn test_valid_c_string() {
        // Valid C string with single nul terminator
        let bytes = b"hello\0";
        let result = validate_c_string(bytes);
        assert!(result.is_ok());
        let cstr = result.unwrap();
        assert_eq!(cstr.to_bytes(), b"hello");

        // Valid empty C string
        let bytes = b"\0";
        let result = validate_c_string(bytes);
        assert!(result.is_ok());
        let cstr = result.unwrap();
        assert_eq!(cstr.to_bytes(), b"");

        // Valid C string with special characters
        let bytes = b"test\x01\x02\x03string\0";
        let result = validate_c_string(bytes);
        assert!(result.is_ok());
        let cstr = result.unwrap();
        assert_eq!(cstr.to_bytes(), b"test\x01\x02\x03string");
    }

    #[test]
    fn test_invalid_no_nul_terminator() {
        // No nul terminator
        let bytes = b"hello";
        let result = validate_c_string(bytes);
        assert!(result.is_err());

        // Empty slice without nul
        let bytes = b"";
        let result = validate_c_string(bytes);
        assert!(result.is_err());
    }

    #[test]
    fn test_invalid_interior_nul() {
        // Interior nul byte before terminator
        let bytes = b"hello\0world\0";
        let result = validate_c_string(bytes);
        assert!(result.is_err());

        // Multiple interior nul bytes
        let bytes = b"\0\0\0\0";
        let result = validate_c_string(bytes);
        assert!(result.is_err());
    }

    #[test]
    fn test_invalid_nul_not_last() {
        // Nul byte not at the end
        let bytes = b"\0hello";
        let result = validate_c_string(bytes);
        assert!(result.is_err());

        // Multiple nul bytes with non-nul after
        let bytes = b"test\0\0extra";
        let result = validate_c_string(bytes);
        assert!(result.is_err());
    }

    #[test]
    fn test_valid_max_length() {
        // Test with maximum useful length (no practical limit in Rust)
        let mut long_string = vec![b'a'; 10000];
        long_string.push(0);
        let result = validate_c_string(&long_string);
        assert!(result.is_ok());
        let cstr = result.unwrap();
        assert_eq!(cstr.to_bytes().len(), 10000);
    }

    #[test]
    fn test_edge_cases() {
        // Single nul byte (empty string)
        let bytes = b"\0";
        let result = validate_c_string(bytes);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().to_bytes(), b"");

        // Just nul bytes (should fail due to interior nul)
        let bytes = b"\0\0";
        let result = validate_c_string(bytes);
        assert!(result.is_err());

        // String containing only nul terminator character
        let bytes = [0];
        let result = validate_c_string(&bytes);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().to_bytes(), &[]);
    }

    #[test]
    fn test_unicode_and_special_bytes() {
        // UTF-8 sequences (C strings don't care about UTF-8 validity)
        let bytes = "café\0".as_bytes();
        let result = validate_c_string(bytes);
        assert!(result.is_ok());
        let cstr = result.unwrap();
        assert_eq!(cstr.to_bytes(), "café".as_bytes());

        // Various byte values (including invalid UTF-8)
        let bytes = &[0xFF, 0xFE, 0x00];
        let result = validate_c_string(bytes);
        assert!(result.is_ok());
        let cstr = result.unwrap();
        assert_eq!(cstr.to_bytes(), &[0xFF, 0xFE]);

        // All possible byte values except nul
        let mut all_bytes: Vec<u8> = (1..=255).collect();
        all_bytes.push(0);
        let result = validate_c_string(&all_bytes);
        assert!(result.is_ok());
        let cstr = result.unwrap();
        assert_eq!(cstr.to_bytes().len(), 255);
    }

    #[test]
    fn test_error_details() {
        // Verify error contains correct information
        let bytes = b"hello";
        let result = validate_c_string(bytes);
        assert!(result.is_err());

        let bytes = b"hello\0world\0";
        let result = validate_c_string(bytes);
        assert!(result.is_err());
    }

    #[test]
    fn test_slice_lifetime() {
        // Ensure the returned reference has the same lifetime as input
        let bytes = b"test\0";
        let result = validate_c_string(bytes);
        assert!(result.is_ok());
        let cstr_ref = result.unwrap();

        // Both should point to the same memory
        assert_eq!(cstr_ref.as_ptr() as *const u8, bytes.as_ptr());
        assert_eq!(cstr_ref.to_bytes_with_nul().as_ptr(), bytes.as_ptr());
    }
}

