mod tests {
    use super::process_sensor_reading;

    #[test]
    fn test_positive_values() {
        // Positive values should convert directly
        assert_eq!(process_sensor_reading(0), 0);
        assert_eq!(process_sensor_reading(1), 1);
        assert_eq!(process_sensor_reading(100), 100);
        assert_eq!(process_sensor_reading(32767), 32767); // i16::MAX
    }

    #[test]
    fn test_negative_values() {
        // Negative values should maintain bit pattern
        // -1 in i16 is 0xFFFF, which is 65535 in u16
        assert_eq!(process_sensor_reading(-1), 65535);

        // -32768 in i16 is 0x8000, which is 32768 in u16
        assert_eq!(process_sensor_reading(i16::MIN), 32768); // i16::MIN

        // Test some intermediate negative values
        assert_eq!(process_sensor_reading(-100), 65436); // 65536 - 100
        assert_eq!(process_sensor_reading(-32767), 32769); // 65536 - 32767
    }

    #[test]
    fn test_bit_pattern_preservation() {
        // Verify that the bit pattern is preserved exactly
        use std::mem;

        let test_values = [
            0i16,
            1i16,
            100i16,
            32767i16,  // i16::MAX
            -1i16,
            -100i16,
            i16::MIN,  // -32768i16
            -32767i16,
        ];

        for &signed_val in &test_values {
            let unsigned_result = process_sensor_reading(signed_val);

            // Manually verify bit pattern using transmute
            let expected_bits: u16 = unsafe { mem::transmute(signed_val) };
            assert_eq!(unsigned_result, expected_bits,
                "Failed for i16 value: {}. Got: {}, Expected bits: {}",
                signed_val, unsigned_result, expected_bits);
        }
    }

    #[test]
    fn test_edge_cases() {
        // Test all boundary values
        assert_eq!(process_sensor_reading(i16::MAX), 32767);
        assert_eq!(process_sensor_reading(i16::MIN), 32768);

        // Test that 0 works correctly in both representations
        assert_eq!(process_sensor_reading(0), 0);
    }

    #[test]
    fn test_round_trip() {
        // Test that we can convert back and forth (though not part of the function)
        // This helps verify the conversion is bijective for bit patterns
        use std::mem;

        let test_values = [0i16, 1i16, 100i16, 32767i16, -1i16, -100i16, i16::MIN, -32767i16];

        for &signed_val in &test_values {
            let unsigned = process_sensor_reading(signed_val);
            let round_trip: i16 = unsafe { mem::transmute(unsigned) };
            assert_eq!(round_trip, signed_val,
                "Round trip failed for i16 value: {}", signed_val);
        }
    }

    #[test]
    fn test_property_based() {
        // Test a range of values systematically
        for signed_val in -1000i16..1000i16 {
            let unsigned_result = process_sensor_reading(signed_val);

            // Verify using manual calculation
            let expected = if signed_val >= 0 {
                signed_val as u16
            } else {
                (65536i32 + signed_val as i32) as u16
            };

            assert_eq!(unsigned_result, expected,
                "Failed for i16 value: {}", signed_val);
        }
    }
}

