pub fn saturating_shift_left(value: i32, shift_amount: u32) -> i32 {
    value.unbounded_shl(shift_amount)
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_shifts() {
        assert_eq!(saturating_shift_left(1, 0), 1);
        assert_eq!(saturating_shift_left(1, 1), 2);
        assert_eq!(saturating_shift_left(1, 2), 4);
        assert_eq!(saturating_shift_left(1, 3), 8);
        assert_eq!(saturating_shift_left(1, 4), 16);
    }

    #[test]
    fn test_negative_values() {
        assert_eq!(saturating_shift_left(-1, 0), -1);
        assert_eq!(saturating_shift_left(-1, 1), -2);
        assert_eq!(saturating_shift_left(-1, 2), -4);
        assert_eq!(saturating_shift_left(-1, 3), -8);
        assert_eq!(saturating_shift_left(-1, 4), -16);
        assert_eq!(saturating_shift_left(-5, 2), -20);
        assert_eq!(saturating_shift_left(-5, 3), -40);
    }

    #[test]
    fn test_zero_value() {
        assert_eq!(saturating_shift_left(0, 0), 0);
        assert_eq!(saturating_shift_left(0, 1), 0);
        assert_eq!(saturating_shift_left(0, 10), 0);
        assert_eq!(saturating_shift_left(0, 31), 0);
        assert_eq!(saturating_shift_left(0, 32), 0);
        assert_eq!(saturating_shift_left(0, 100), 0);
    }

    #[test]
    fn test_small_shifts_with_positive_values() {
        assert_eq!(saturating_shift_left(3, 0), 3);
        assert_eq!(saturating_shift_left(3, 1), 6);
        assert_eq!(saturating_shift_left(3, 2), 12);
        assert_eq!(saturating_shift_left(7, 2), 28);
        assert_eq!(saturating_shift_left(7, 3), 56);
    }

    #[test]
    fn test_small_shifts_with_negative_values() {
        assert_eq!(saturating_shift_left(-3, 0), -3);
        assert_eq!(saturating_shift_left(-3, 1), -6);
        assert_eq!(saturating_shift_left(-3, 2), -12);
        assert_eq!(saturating_shift_left(-7, 2), -28);
        assert_eq!(saturating_shift_left(-7, 3), -56);
    }

    #[test]
    fn test_maximum_shift_before_overflow() {
        // i32 has 32 bits, but since it's signed, we only have 31 value bits
        // Shifting 1 by 30 should give us 2^30 = 1073741824
        assert_eq!(saturating_shift_left(1, 30), 1073741824);

        // Shifting 1 by 31 should overflow in normal shift, but unbounded_shl should handle it
        // In two's complement, shifting 1 by 31 gives -2147483648 (i32::MIN)
        assert_eq!(saturating_shift_left(1, 31), -2147483648);
    }

    #[test]
    fn test_shifts_beyond_bit_width() {
        // For shifts >= 32, the result should be 0 according to the query description
        assert_eq!(saturating_shift_left(1, 32), 0);
        assert_eq!(saturating_shift_left(1, 33), 0);
        assert_eq!(saturating_shift_left(1, 40), 0);
        assert_eq!(saturating_shift_left(1, 100), 0);

        // Same for negative values
        assert_eq!(saturating_shift_left(-1, 32), 0);
        assert_eq!(saturating_shift_left(-1, 33), 0);
        assert_eq!(saturating_shift_left(-1, 100), 0);

        // Same for arbitrary values
        assert_eq!(saturating_shift_left(42, 32), 0);
        assert_eq!(saturating_shift_left(-42, 32), 0);
        assert_eq!(saturating_shift_left(i32::MAX, 32), 0);
        assert_eq!(saturating_shift_left(i32::MIN, 32), 0);
    }

    #[test]
    fn test_boundary_shifts() {
        // Test shifts exactly at bit width boundary
        assert_eq!(saturating_shift_left(1, 31), -2147483648);
        assert_eq!(saturating_shift_left(1, 32), 0);

        // Test with maximum value
        assert_eq!(saturating_shift_left(i32::MAX, 0), i32::MAX);
        assert_eq!(saturating_shift_left(i32::MAX, 1), -2); // i32::MAX << 1 = -2 in two's complement
        assert_eq!(saturating_shift_left(i32::MAX, 32), 0);

        // Test with minimum value
        assert_eq!(saturating_shift_left(i32::MIN, 0), i32::MIN);
        assert_eq!(saturating_shift_left(i32::MIN, 1), 0); // i32::MIN << 1 = 0 in two's complement
        assert_eq!(saturating_shift_left(i32::MIN, 32), 0);
    }

    #[test]
    fn test_random_fixed_values() {
        // Using fixed values for deterministic testing
        assert_eq!(saturating_shift_left(123, 5), 123 << 5);
        assert_eq!(saturating_shift_left(-456, 3), -456 << 3);
        assert_eq!(saturating_shift_left(7890, 8), 7890 << 8);
        assert_eq!(saturating_shift_left(-12345, 4), -12345 << 4);
    }

    #[test]
    fn test_property_shifts_within_31_bits() {
        // For shifts < 31, the result should match normal left shift
        for shift in 0..31 {
            let value = 1;
            assert_eq!(saturating_shift_left(value, shift), value << shift);
        }

        // Test with a different value
        for shift in 0..31 {
            let value = 42;
            assert_eq!(saturating_shift_left(value, shift), value << shift);
        }

        // Test with negative value
        for shift in 0..31 {
            let value = -42;
            assert_eq!(saturating_shift_left(value, shift), value << shift);
        }
    }

    #[test]
    fn test_all_shift_amounts_for_specific_value() {
        let value = 1;

        // Test all shift amounts from 0 to 100
        for shift in 0..=100 {
            let result = saturating_shift_left(value, shift);

            if shift < 32 {
                // For shifts < 32, result should be value << shift
                // But we need to handle the special case of shift = 31 separately
                // because 1 << 31 would normally panic
                if shift < 31 {
                    assert_eq!(result, value << shift);
                } else if shift == 31 {
                    assert_eq!(result, -2147483648);
                }
            } else {
                // For shifts >= 32, result should be 0
                assert_eq!(result, 0);
            }
        }
    }

    #[test]
    fn test_edge_case_shift_31() {
        // Special attention to shift = 31 since it's the boundary
        // where we get i32::MIN from shifting 1
        assert_eq!(saturating_shift_left(1, 31), -2147483648);
        assert_eq!(saturating_shift_left(2, 31), 0); // 2 << 31 = 0
        assert_eq!(saturating_shift_left(3, 31), -2147483648); // 3 << 31 = -2147483648
        assert_eq!(saturating_shift_left(-1, 31), -2147483648);
        assert_eq!(saturating_shift_left(i32::MAX, 31), -2147483648);
        assert_eq!(saturating_shift_left(i32::MIN, 31), 0);
    }
}

