    fn test_interpret_sensor_delta_mid_range_values() {
        // Test values in the middle of both ranges
        assert_eq!(interpret_sensor_delta(1000), 1000);
        assert_eq!(interpret_sensor_delta(50000), -15536);
        assert_eq!(interpret_sensor_delta(40000), -25536);
        assert_eq!(interpret_sensor_delta(60000), -5536);
