        for i in 0..=32767 {
            assert_eq!(interpret_sensor_delta(i as u16), i as i16);
        }
    }

    #[test]
    fn test_interpret_sensor_delta_two_complement() {
        // Verify two's complement behavior
        // For values > 32767, result should be value - 65536
        for i in 32768..=65535u32 {
            let input = i as u16;
            let expected = (i as i32 - 65536) as i16;
            assert_eq!(interpret_sensor_delta(input), expected);
