        assert_eq!(shift_permissions_right(0x1234_5678_9ABC_DEF0, u32::MAX), 0);
    }

    #[test]
    fn test_shift_permissions_right_powers_of_two() {
        // Test with powers of two to verify bit positions
        assert_eq!(shift_permissions_right(1 << 63, 0), 1 << 63);
        assert_eq!(shift_permissions_right(1 << 63, 1), 1 << 62);
        assert_eq!(shift_permissions_right(1 << 63, 63), 1);
        assert_eq!(shift_permissions_right(1 << 63, 64), 0);
