        assert_eq!(shift_permissions_right(value, 48), 0xDEAD);
        assert_eq!(shift_permissions_right(value, 56), 0xDE);
        assert_eq!(shift_permissions_right(value, 60), 0xD);
        assert_eq!(shift_permissions_right(value, 64), 0);
        assert_eq!(shift_permissions_right(value, 72), 0);
    }

    #[test]
    fn test_shift_permissions_right_const_evaluation() {
        // Verify the function can be evaluated at compile time
        const SHIFT_RESULT_0: u64 = shift_permissions_right(0xFF00, 8);
        const SHIFT_RESULT_1: u64 = shift_permissions_right(0xFFFF_FFFF, 32);
        const SHIFT_RESULT_2: u64 = shift_permissions_right(0x1234, 100);

        assert_eq!(SHIFT_RESULT_0, 0xFF);
        assert_eq!(SHIFT_RESULT_1, 0);
        assert_eq!(SHIFT_RESULT_2, 0);
    }

    #[test]
    fn test_shift_permissions_right_edge_cases() {
        // Edge case: shifting by exactly the bit width
        assert_eq!(shift_permissions_right(0xFFFF_FFFF_FFFF_FFFF, 63), 1);
        assert_eq!(shift_permissions_right(0xFFFF_FFFF_FFFF_FFFF, 64), 0);

        // Edge case: maximum u64 value
        assert_eq!(shift_permissions_right(u64::MAX, 0), u64::MAX);
        assert_eq!(shift_permissions_right(u64::MAX, 1), u64::MAX >> 1);
        assert_eq!(shift_permissions_right(u64::MAX, 64), 0);
        assert_eq!(shift_permissions_right(u64::MAX, 65), 0);
    }

    #[test]
    fn test_shift_permissions_right_property_based() {
        // Property: shifting by offset >= 64 always yields 0
        for offset in 64..=100 {
            assert_eq!(shift_permissions_right(0xFFFF_FFFF_FFFF_FFFF, offset), 0);
