        // Test with u8::MIN
        let mut data: &[u8] = &[0, 1];
        let result = extract_next_header(&mut data);
        assert_eq!(result, Some(0));
        assert_eq!(data, &[1]);

        // Test with u8::MAX
        let mut data: &[u8] = &[255, 0];
        let result = extract_next_header(&mut data);
        assert_eq!(result, Some(255));
        assert_eq!(data, &[0]);
    }

    #[test]
    fn test_extract_next_header_large_slice() {
        let original_data: Vec<u8> = (0..1000).map(|i| (i % 256) as u8).collect();
        let mut data: &[u8] = &original_data;

        for i in 0..1000 {
            let expected_byte = (i % 256) as u8;
            let result = extract_next_header(&mut data);
            assert_eq!(result, Some(expected_byte));
            assert_eq!(data.len(), 999 - i);
        }

        assert_eq!(data, &[]);

        let final_result = extract_next_header(&mut data);
        assert_eq!(final_result, None);
    }

    #[test]
    fn test_extract_next_header_mutable_reference_behavior() {
        let original = vec![1, 2, 3];
        let mut data: &[u8] = &original;

        // Extract first byte
        let result = extract_next_header(&mut data);
        assert_eq!(result, Some(1));

        // Original data should remain unchanged
        assert_eq!(original, vec![1, 2, 3]);

        // But our mutable reference should be updated
        assert_eq!(data, &[2, 3]);
    }
}

