use std::str::Utf8Error;

fn validate_and_modify_utf8_field(buffer: &mut [u8], field_range: std::ops::Range<usize>) -> Result<&mut str, Utf8Error> {
    let field_slice = &mut buffer[field_range];
    std::str::from_utf8_mut(field_slice)
}

