#[cfg(test)]
mod tests {
    use super::*;
    use std::str::Utf8Error;

    #[test]
    fn test_valid_utf8_field() {
        let mut buffer = vec![b'H', b'e', b'l', b'l', b'o', 0, 0, 0];
        let field_range = 0..5;

        let result = validate_and_modify_utf8_field(&mut buffer, field_range.clone());
        assert!(result.is_ok());

        let string_slice = result.unwrap();
        assert_eq!(string_slice, "Hello");

        // Test that we can modify the string in-place
        string_slice.make_ascii_uppercase();
        assert_eq!(&buffer[field_range], b"HELLO");
    }

    #[test]
    fn test_valid_utf8_multibyte_characters() {
        let mut buffer = vec![0xF0, 0x9F, 0x98, 0x8A, b' ', b'A', b'B', b'C']; // 😊 ABC
        let field_range = 0..8;

        let result = validate_and_modify_utf8_field(&mut buffer, field_range.clone());
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), "😊 ABC");
    }

    #[test]
    fn test_invalid_utf8_field() {
        let mut buffer = vec![0xFF, 0xFE, 0xFD, 0, 0, 0]; // Invalid UTF-8 bytes
        let field_range = 0..3;

        let result = validate_and_modify_utf8_field(&mut buffer, field_range);
        assert!(result.is_err());

        let err = result.unwrap_err();
        assert!(matches!(err, Utf8Error { .. }));
    }

    #[test]
    fn test_partial_invalid_utf8() {
        let mut buffer = vec![b'A', b'B', 0xC0, 0xC1, b'C', b'D']; // 0xC0, 0xC1 are invalid
        let field_range = 0..6;

        let result = validate_and_modify_utf8_field(&mut buffer, field_range);
        assert!(result.is_err());
    }

    #[test]
    fn test_empty_field() {
        let mut buffer = vec![b'A', b'B', b'C'];
        let field_range = 1..1; // Empty range

        let result = validate_and_modify_utf8_field(&mut buffer, field_range.clone());
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), "");
    }

    #[test]
    fn test_field_at_buffer_middle() {
        let mut buffer = vec![0, 0, b'H', b'i', b'!', 0, 0, 0];
        let field_range = 2..5;

        let result = validate_and_modify_utf8_field(&mut buffer, field_range.clone());
        assert!(result.is_ok());

        let string_slice = result.unwrap();
        assert_eq!(string_slice, "Hi!");

        // Modify the string
        string_slice.make_ascii_uppercase();
        assert_eq!(&buffer[field_range], b"HI!");
    }

    #[test]
    fn test_entire_buffer_is_field() {
        let mut buffer = vec![b'T', b'e', b's', b't'];
        let field_range = 0..buffer.len();

        let result = validate_and_modify_utf8_field(&mut buffer, field_range.clone());
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), "Test");
    }

    #[test]
    fn test_field_with_null_bytes() {
        let mut buffer = vec![b'A', 0, b'B', 0, b'C'];
        let field_range = 0..5;

        let result = validate_and_modify_utf8_field(&mut buffer, field_range);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), "A\0B\0C");
    }

    #[test]
    fn test_unicode_normalization_preserved() {
        let mut buffer = "caf\u{e9}".as_bytes().to_vec(); // "café" with acute accent
        let field_range = 0..buffer.len();

        let result = validate_and_modify_utf8_field(&mut buffer, field_range);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), "café");
    }

    #[test]
    #[should_panic(expected = "range end index 10 out of range for slice of length 8")]
    fn test_field_range_out_of_bounds() {
        let mut buffer = vec![b'A', b'B', b'C', b'D', b'E', b'F', b'G', b'H'];
        let field_range = 5..10; // Range exceeds buffer length

        let _ = validate_and_modify_utf8_field(&mut buffer, field_range);
    }

    #[test]
    fn test_modification_affects_only_field() {
        let mut buffer = vec![b'P', b'r', b'e', b' ', b'T', b'e', b'x', b't', b' ', b'P', b'o', b's', b't'];
        let field_range = 4..8; // "Text"

        let result = validate_and_modify_utf8_field(&mut buffer, field_range.clone());
        assert!(result.is_ok());

        let string_slice = result.unwrap();
        string_slice.make_ascii_uppercase();

        // Only the field should be modified
        assert_eq!(&buffer[0..4], b"Pre ");
        assert_eq!(&buffer[field_range], b"TEXT");
        assert_eq!(&buffer[8..], b" Post");
    }

    #[test]
    fn test_valid_utf8_with_surrogate_pairs() {
        // "𐐷" (U+10437) encoded as 0xF0 0x90 0x90 0xB7
        let mut buffer = vec![0xF0, 0x90, 0x90, 0xB7, b' ', b'X'];
        let field_range = 0..6;

        let result = validate_and_modify_utf8_field(&mut buffer, field_range);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), "𐐷 X");
    }
}

