mod tests {
    use super::*;

    #[test]
    fn test_log_buffer_valid_utf8() {
        // Test with ASCII bytes
        let ascii_bytes = b"Hello, world!";
        let result = log_buffer(ascii_bytes);
        assert_eq!(result, "Hello, world!");

        // Test with multi-byte UTF-8 characters
        let utf8_bytes = "Hello, 世界!".as_bytes();
        let result = log_buffer(utf8_bytes);
        assert_eq!(result, "Hello, 世界!");

        // Test with empty slice
        let empty_bytes: &[u8] = &[];
        let result = log_buffer(empty_bytes);
        assert_eq!(result, "");
    }

    #[test]
    fn test_log_buffer_const_context() {
        // Test that the function can be used in const contexts
        const BYTES: &[u8] = b"Constant string";
        const RESULT: &str = log_buffer(BYTES);
        assert_eq!(RESULT, "Constant string");
    }

    #[test]
    fn test_log_buffer_partial_slice() {
        // Test with a slice of a larger valid UTF-8 buffer
        let full_string = "Hello, world! This is a test.";
        let bytes = full_string.as_bytes();

        // Take a slice of the bytes
        let slice = &bytes[7..12]; // "world"
        let result = log_buffer(slice);
        assert_eq!(result, "world");
    }

    #[test]
    fn test_log_buffer_unicode_boundaries() {
        // Test with various Unicode code points
        let test_cases = [
            ("Basic Latin", b"Hello".as_slice()),
            ("Greek", "Γεια σας".as_bytes()),
            ("Cyrillic", "Привет".as_bytes()),
            ("Emoji", "Hello 👋 World".as_bytes()),
            ("Mixed", "Hello 世界 👋".as_bytes()),
        ];

        for (description, bytes) in test_cases {
            let result = log_buffer(bytes);
            // Convert back to bytes to verify round-trip
            assert_eq!(result.as_bytes(), bytes, "Failed for: {}", description);
        }
    }

    // Note: We cannot test invalid UTF-8 in safe code because the function
    // is unsafe and requires the caller to guarantee valid UTF-8.
    // The following test demonstrates what would happen with invalid UTF-8,
    // but it's commented out because it would be undefined behavior.

    // #[test]
    // fn test_log_buffer_invalid_utf8() {
    //     // This would be undefined behavior - DO NOT UNCOMMENT
    //     // let invalid_bytes = &[0xFF, 0xFF, 0xFF];
    //     // let _ = log_buffer(invalid_bytes); // UB!
    // }

    #[test]
    fn test_log_buffer_lifetime() {
        // Test that the returned str has the same lifetime as input
        let bytes = String::from("Hello").into_bytes();
        let result = {
            let slice: &[u8] = &bytes[..];
            log_buffer(slice)
        };
        // result cannot outlive bytes, but this is fine
        assert_eq!(result, "Hello");
    }

    #[test]
    fn test_log_buffer_benchmark_comparison() {
        // Compare with safe version to ensure they produce same results
        // (though our function is unsafe, it should match safe version for valid UTF-8)
        let test_strings = [
            "",
            "a",
            "Hello",
            "Hello, 世界!",
            "👋🌍",
        ];

        for s in test_strings {
            let bytes = s.as_bytes();
            let unsafe_result = log_buffer(bytes);
            let safe_result = std::str::from_utf8(bytes).unwrap();

            assert_eq!(unsafe_result, safe_result);
            assert_eq!(unsafe_result, s);
        }

        // Test with longer string
        let long_string = "A".repeat(100);
        let bytes = long_string.as_bytes();
        let unsafe_result = log_buffer(bytes);
        let safe_result = std::str::from_utf8(bytes).unwrap();

        assert_eq!(unsafe_result, safe_result);
        assert_eq!(unsafe_result, long_string);
    }
}

