        let mut bytes = Vec::new();
        let result = convert_valid_utf8_bytes_to_mutable_string(&mut bytes);
        assert_eq!(result, "");
        assert!(result.is_empty());
    }

    #[test]
    fn test_mutation_preserved() {
        let mut bytes = b"Test".to_vec();
        let string_slice = convert_valid_utf8_bytes_to_mutable_string(&mut bytes);

        // Test that we can modify through the string slice
        unsafe {
            let bytes_ptr = string_slice.as_bytes_mut();
            bytes_ptr[0] = b't';
        }

        assert_eq!(string_slice, "test");
    }

    #[test]
    fn test_multibyte_utf8_sequence() {
        let mut bytes = vec![0xF0, 0x9F, 0x8C, 0x8F]; // 🌏 emoji
        let result = convert_valid_utf8_bytes_to_mutable_string(&mut bytes);
        assert_eq!(result, "🌏");
        assert_eq!(result.len(), 4); // 4 bytes in UTF-8
        assert_eq!(result.chars().count(), 1); // 1 character
    }

    #[test]
    fn test_mixed_content() {
        let mut bytes = "ASCII: ABC, Unicode: 🚀, Numbers: 123".as_bytes().to_vec();
        let result = convert_valid_utf8_bytes_to_mutable_string(&mut bytes);
        assert_eq!(result, "ASCII: ABC, Unicode: 🚀, Numbers: 123");
        assert!(result.starts_with("ASCII:"));
        assert!(result.ends_with("123"));
        assert!(result.contains('🚀'));
    }

    #[test]
    fn test_borrow_checker_compatibility() {
        let mut data = String::from("Mutable test");
        let bytes = unsafe { data.as_bytes_mut() };
        let result = convert_valid_utf8_bytes_to_mutable_string(bytes);

        // Verify we can still use the original data
        assert_eq!(result, "Mutable test");
        assert_eq!(&data, "Mutable test");
    }

    #[test]
    fn test_whitespace_and_control_chars() {
        let mut bytes = "Line1\nLine2\r\nTab\tSpace ".as_bytes().to_vec();
        let result = convert_valid_utf8_bytes_to_mutable_string(&mut bytes);
        assert_eq!(result, "Line1\nLine2\r\nTab\tSpace ");
        assert!(result.contains('\n'));
        assert!(result.contains('\t'));
        assert!(result.ends_with(' '));
    }

    #[test]
    fn test_large_buffer() {
        let text = "A".repeat(10000);
        let mut bytes = text.as_bytes().to_vec();
        let result = convert_valid_utf8_bytes_to_mutable_string(&mut bytes);
        assert_eq!(result.len(), 10000);
        assert!(result.chars().all(|c| c == 'A'));
    }

    #[test]
    fn test_partial_slice() {
        let mut all_bytes = "Hello World".as_bytes().to_vec();
        let slice = &mut all_bytes[0..5]; // "Hello"
        let result = convert_valid_utf8_bytes_to_mutable_string(slice);
