        let result = filter_non_equal(input);
        assert_eq!(result, vec![Ordering::Less, Ordering::Greater, Ordering::Less, Ordering::Greater]);
    }

    #[test]
    fn test_filter_non_equal_with_is_ne_method() {
        // Test that is_ne() method works correctly for all Ordering variants
        assert!(Ordering::Less.is_ne());
        assert!(Ordering::Greater.is_ne());
        assert!(!Ordering::Equal.is_ne());
    }
}

