pub enum ParseError {
    InvalidLength,
}

pub const fn parse_little_endian_i32(bytes: &[u8]) -> Result<i32, ParseError> {
    if bytes.len() != 4 {
        return Err(ParseError::InvalidLength);
    }

    let array = [bytes[0], bytes[1], bytes[2], bytes[3]];
    Ok(i32::from_le_bytes(array))
}

