        assert_eq!(bytes_to_u32_be(&[0x00, 0x00, 0x00, 0x00]), Some(0));
        assert_eq!(bytes_to_u32_be(&[0x00, 0x00, 0x00, 0x01]), Some(1));
        assert_eq!(bytes_to_u32_be(&[0x00, 0x00, 0x00, 0xFF]), Some(255));

        // Test maximum value
        assert_eq!(bytes_to_u32_be(&[0xFF, 0xFF, 0xFF, 0xFF]), Some(u32::MAX));

        // Test typical values
        assert_eq!(bytes_to_u32_be(&[0x12, 0x34, 0x56, 0x78]), Some(0x12345678));
        assert_eq!(bytes_to_u32_be(&[0xDE, 0xAD, 0xBE, 0xEF]), Some(0xDEADBEEF));
    }

    #[test]
    fn test_big_endian_encoding() {
        // Verify big-endian encoding is correctly handled
        let bytes = [0x12, 0x34, 0x56, 0x78];
        let result = bytes_to_u32_be(&bytes).unwrap();

        // In big-endian, most significant byte is first
        assert_eq!(result >> 24, 0x12);
        assert_eq!((result >> 16) & 0xFF, 0x34);
        assert_eq!((result >> 8) & 0xFF, 0x56);
        assert_eq!(result & 0xFF, 0x78);

        // Verify it matches u32::from_be_bytes
        assert_eq!(result, u32::from_be_bytes(bytes));
    }

    #[test]
    fn test_invalid_length() {
        // Test with too few bytes
        assert_eq!(bytes_to_u32_be(&[]), None);
        assert_eq!(bytes_to_u32_be(&[0x01]), None);
        assert_eq!(bytes_to_u32_be(&[0x01, 0x02]), None);
        assert_eq!(bytes_to_u32_be(&[0x01, 0x02, 0x03]), None);

        // Test with too many bytes
        assert_eq!(bytes_to_u32_be(&[0x01, 0x02, 0x03, 0x04, 0x05]), None);
        assert_eq!(bytes_to_u32_be(&[0x01; 5]), None);
        assert_eq!(bytes_to_u32_be(&[0x01; 8]), None);
    }

    #[test]
    fn test_const_context() {
        // Test that function can be used in const context
        const BYTES: [u8; 4] = [0x11, 0x22, 0x33, 0x44];
        const RESULT: Option<u32> = bytes_to_u32_be(&BYTES);

        // Verify the const result is correct
        assert_eq!(RESULT, Some(0x11223344));
    }

    #[test]
    fn test_slice_from_larger_buffer() {
        // Test that function works with slices from larger arrays
        let large_buffer = [0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07];

        // Valid slice from middle of buffer
        assert_eq!(bytes_to_u32_be(&large_buffer[0..4]), Some(0x00010203));
        assert_eq!(bytes_to_u32_be(&large_buffer[1..5]), Some(0x01020304));
        assert_eq!(bytes_to_u32_be(&large_buffer[4..8]), Some(0x04050607));

        // Invalid slices from buffer
        assert_eq!(bytes_to_u32_be(&large_buffer[0..3]), None);
        assert_eq!(bytes_to_u32_be(&large_buffer[0..5]), None);
    }

    #[test]
    fn test_edge_cases() {
        // Test minimum non-zero value
        assert_eq!(bytes_to_u32_be(&[0x00, 0x00, 0x00, 0x01]), Some(1));

        // Test value that would overflow if treated as little-endian
        let bytes = [0x00, 0x00, 0x01, 0x00];
        assert_eq!(bytes_to_u32_be(&bytes), Some(256)); // 0x00000100 = 256
        // If treated as little-endian: 0x00010000 = 65536

        // Test all bytes set to 0x80 (128)
        assert_eq!(bytes_to_u32_be(&[0x80, 0x80, 0x80, 0x80]), Some(0x80808080));
    }

    #[test]
