        assert_eq!(bytes_to_u32_be(&[0x00, 0x00, 0x00, 0x00]), Some(0));
        assert_eq!(bytes_to_u32_be(&[0xFF, 0x00, 0x00, 0x00]), Some(0xFF000000));
        assert_eq!(bytes_to_u32_be(&[0x00, 0xFF, 0x00, 0x00]), Some(0x00FF0000));
        assert_eq!(bytes_to_u32_be(&[0x00, 0x00, 0xFF, 0x00]), Some(0x0000FF00));
        assert_eq!(bytes_to_u32_be(&[0x00, 0x00, 0x00, 0xFF]), Some(0x000000FF));
    }

