        assert_eq!(bytes_to_u32_be(&[0x01, 0x02, 0x03, 0x04]), Some(0x01020304));

        // Test descending pattern
        assert_eq!(bytes_to_u32_be(&[0x04, 0x03, 0x02, 0x01]), Some(0x04030201));

        // Test alternating pattern
        assert_eq!(bytes_to_u32_be(&[0xAA, 0xBB, 0xCC, 0xDD]), Some(0xAABBCCDD));

        // Test palindrome pattern
        assert_eq!(bytes_to_u32_be(&[0x12, 0x34, 0x43, 0x21]), Some(0x12344321));
