mod tests {
    use super::*;
    use std::f64::{NAN, INFINITY, NEG_INFINITY};

    #[test]
    fn test_nan_less_than_finite_positive() {
        // NaN < positive finite should return false
        assert!(!compare_nan_finite(NAN, 1.0));
        assert!(!compare_nan_finite(NAN, 1000.0));
        assert!(!compare_nan_finite(NAN, 0.0001));
        assert!(!compare_nan_finite(NAN, f64::MAX));
        assert!(!compare_nan_finite(NAN, f64::MIN_POSITIVE));
    }

    #[test]
    fn test_nan_less_than_finite_negative() {
        // NaN < negative finite should return false
        assert!(!compare_nan_finite(NAN, -1.0));
        assert!(!compare_nan_finite(NAN, -1000.0));
        assert!(!compare_nan_finite(NAN, -0.0001));
        assert!(!compare_nan_finite(NAN, f64::MIN));
        assert!(!compare_nan_finite(NAN, -f64::MAX));
    }

    #[test]
    fn test_nan_less_than_zero() {
        // NaN < 0.0 should return false
        assert!(!compare_nan_finite(NAN, 0.0));
        assert!(!compare_nan_finite(NAN, -0.0));
    }

    #[test]
    fn test_different_nan_patterns() {
        // Different NaN representations should all behave the same
        let nan1 = f64::from_bits(0x7FF8000000000001);
        let nan2 = f64::from_bits(0x7FF0000000000001);
        let nan3 = f64::from_bits(0xFFF8000000000001);

        assert!(!compare_nan_finite(nan1, 5.0));
        assert!(!compare_nan_finite(nan2, -5.0));
        assert!(!compare_nan_finite(nan3, 0.0));
    }

    #[test]
    fn test_nan_less_than_infinity() {
        // Even though infinity isn't finite, test edge cases
        assert!(!compare_nan_finite(NAN, INFINITY));
        assert!(!compare_nan_finite(NAN, NEG_INFINITY));
    }

    #[test]
    fn test_finite_less_than_nan() {
        // Test that the function only works as intended when a is NaN
        // These cases test the opposite scenario (finite < NaN)
        // which should also return false
        assert!(!compare_nan_finite(1.0, NAN));
        assert!(!compare_nan_finite(-1.0, NAN));
        assert!(!compare_nan_finite(0.0, NAN));
    }

    #[test]
    fn test_both_nan() {
        // NaN < NaN should return false
        assert!(!compare_nan_finite(NAN, NAN));
        let nan1 = f64::from_bits(0x7FF8000000000001);
        let nan2 = f64::from_bits(0x7FF8000000000002);
        assert!(!compare_nan_finite(nan1, nan2));
    }

    #[test]
    fn test_finite_less_than_finite() {
        // Test normal finite comparisons work correctly
        assert!(compare_nan_finite(1.0, 2.0));
        assert!(!compare_nan_finite(2.0, 1.0));
        assert!(!compare_nan_finite(1.0, 1.0));
        assert!(compare_nan_finite(-2.0, -1.0));
        assert!(compare_nan_finite(f64::MIN, f64::MAX));
    }

    #[test]
    fn test_special_cases() {
        // Test with special finite values
        assert!(!compare_nan_finite(NAN, f64::EPSILON));
        assert!(!compare_nan_finite(NAN, -f64::EPSILON));
        assert!(!compare_nan_finite(NAN, std::f64::consts::PI));
        assert!(!compare_nan_finite(NAN, std::f64::consts::E));
    }
