        // Test that each byte position works correctly
        let test_cases = [
            (0x000000FF, [0x00, 0x00, 0x00, 0xFF]),
            (0x0000FF00, [0x00, 0x00, 0xFF, 0x00]),
            (0x00FF0000, [0x00, 0xFF, 0x00, 0x00]),
            (0xFF000000_i64 as i32, [0xFF, 0x00, 0x00, 0x00]),
        ];

        for (input, expected) in test_cases.iter() {
            let result = serialize_to_big_endian(*input);
            assert_eq!(result, *expected);
        }
    }

