            255,
            -255,
            65535,
            -65535,
            16777215,
            -16777215,
            i32::MAX,
            i32::MIN,
        ];

        for &value in test_values.iter() {
            let bytes = serialize_to_big_endian(value);
            let reconstructed = i32::from_be_bytes(bytes);
            assert_eq!(value, reconstructed);
        }
    }

