        const SERIALIZED_ZERO: [u8; 4] = serialize_to_big_endian(0);
        const SERIALIZED_MAX: [u8; 4] = serialize_to_big_endian(i32::MAX);
        const SERIALIZED_MIN: [u8; 4] = serialize_to_big_endian(i32::MIN);

        assert_eq!(SERIALIZED_ZERO, [0x00, 0x00, 0x00, 0x00]);
        assert_eq!(SERIALIZED_MAX, [0x7F, 0xFF, 0xFF, 0xFF]);
