        assert_eq!(serialize_to_network_bytes(4294967296), [0, 0, 0, 1, 0, 0, 0, 0]);
    }

    #[test]
    fn test_serialize_endianness() {
        // Verify big-endian ordering by checking that the most significant byte is first
        let value = 0x123456789ABCDEF0;
        let result = serialize_to_network_bytes(value);

        // In big-endian, the most significant byte (0x12) should be at index 0
        assert_eq!(result[0], 0x12);
        assert_eq!(result[1], 0x34);
        assert_eq!(result[2], 0x56);
        assert_eq!(result[3], 0x78);
        assert_eq!(result[4], 0x9A);
