        const SERIALIZED_MAX: [u8; 8] = serialize_to_network_bytes(u64::MAX);

        assert_eq!(SERIALIZED_ZERO, [0, 0, 0, 0, 0, 0, 0, 0]);
        assert_eq!(SERIALIZED_MAX, [255, 255, 255, 255, 255, 255, 255, 255]);
