fn find_valid_ge_pairs(numbers: &[f64]) -> Vec<(usize, usize)> {
    let mut pairs = Vec::new();

    for i in 0..numbers.len() {
        let a = numbers[i];
        if a.is_nan() {
            continue;
        }

        for j in 0..numbers.len() {
            if i == j {
                continue;
            }

            let b = numbers[j];
            if b.is_nan() {
                continue;
            }

            if a.ge(&b) {
                pairs.push((i, j));
            }
        }
    }

    pairs
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_slice() {
        let numbers: &[f64] = &[];
        let result = find_valid_ge_pairs(numbers);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_single_element() {
        let numbers = &[1.0];
        let result = find_valid_ge_pairs(numbers);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_basic_comparisons() {
        let numbers = &[3.0, 1.0, 2.0];
        let result = find_valid_ge_pairs(numbers);

        // Expected pairs where numbers[i] >= numbers[j]
        let mut expected = vec![
            (0, 1), // 3.0 >= 1.0
            (0, 2), // 3.0 >= 2.0
            (2, 1), // 2.0 >= 1.0
        ];

        // Also include self-comparisons (i, i) are excluded by the function
        // and (1, 2) is excluded because 1.0 < 2.0
        // (2, 0) is excluded because 2.0 < 3.0
        // (1, 0) is excluded because 1.0 < 3.0

        expected.sort();
        let mut result_sorted = result;
        result_sorted.sort();

        assert_eq!(result_sorted, expected);
    }

    #[test]
    fn test_equal_numbers() {
        let numbers = &[2.0, 2.0, 2.0];
        let result = find_valid_ge_pairs(numbers);

        // All pairs where i != j should be included since 2.0 >= 2.0
        let mut expected = vec![
            (0, 1),
            (0, 2),
            (1, 0),
            (1, 2),
            (2, 0),
            (2, 1),
        ];

        expected.sort();
        let mut result_sorted = result;
        result_sorted.sort();

        assert_eq!(result_sorted, expected);
    }

    #[test]
    fn test_with_nan_values() {
        let numbers = &[1.0, f64::NAN, 2.0, f64::NAN, 3.0];
        let result = find_valid_ge_pairs(numbers);

        // NaN values should be skipped entirely
        // Valid comparisons: 1.0, 2.0, 3.0 at indices 0, 2, 4
        let mut expected = vec![
            (0, 2), // 1.0 >= 2.0? false, so not included
            (0, 4), // 1.0 >= 3.0? false, so not included
            (2, 0), // 2.0 >= 1.0? true
            (2, 4), // 2.0 >= 3.0? false, so not included
            (4, 0), // 3.0 >= 1.0? true
            (4, 2), // 3.0 >= 2.0? true
        ];

        // Filter to only true comparisons
        expected.retain(|&(i, j)| {
            let a = numbers[i];
            let b = numbers[j];
            a.ge(&b)
        });

        expected.sort();
        let mut result_sorted = result;
        result_sorted.sort();

        assert_eq!(result_sorted, expected);
    }

    #[test]
    fn test_all_nan() {
        let numbers = &[f64::NAN, f64::NAN, f64::NAN];
        let result = find_valid_ge_pairs(numbers);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_infinity_values() {
        let numbers = &[f64::INFINITY, 1.0, f64::NEG_INFINITY, 0.0];
        let result = find_valid_ge_pairs(numbers);

        // All valid comparisons (no NaN)
        let mut expected = vec![
            (0, 1), // INF >= 1.0
            (0, 2), // INF >= -INF
            (0, 3), // INF >= 0.0
            (1, 2), // 1.0 >= -INF
            (1, 3), // 1.0 >= 0.0
            (3, 2), // 0.0 >= -INF
        ];
        // Note: (1, 0), (2, 0), (3, 0), (2, 1), (3, 1), (2, 3) are false

        expected.sort();
        let mut result_sorted = result;
        result_sorted.sort();

        assert_eq!(result_sorted, expected);
    }

    #[test]
    fn test_mixed_special_values() {
        let numbers = &[f64::INFINITY, f64::NAN, f64::NEG_INFINITY, f64::NAN, 0.0];
        let result = find_valid_ge_pairs(numbers);

        // Valid numbers at indices 0, 2, 4
        let mut expected = vec![
            (0, 2), // INF >= -INF
            (0, 4), // INF >= 0.0
            (4, 2), // 0.0 >= -INF
        ];

        expected.sort();
        let mut result_sorted = result;
        result_sorted.sort();

        assert_eq!(result_sorted, expected);
    }

    #[test]
    fn test_negative_zero_comparison() {
        let numbers = &[0.0, -0.0];
        let result = find_valid_ge_pairs(numbers);

        // 0.0 >= -0.0 is true and -0.0 >= 0.0 is also true
        let mut expected = vec![
            (0, 1),
            (1, 0),
        ];

        expected.sort();
        let mut result_sorted = result;
        result_sorted.sort();

        assert_eq!(result_sorted, expected);
    }

    #[test]
    fn test_large_input() {
        // Test with 1000 elements to ensure no performance issues
        let numbers: Vec<f64> = (0..1000).map(|x| x as f64).collect();
        let result = find_valid_ge_pairs(&numbers);

        // For sorted ascending array, pairs where i >= j (value-wise) 
        // correspond to indices where numbers[i] >= numbers[j]
        // Since array is sorted ascending, this means i >= j
        let expected_count = (1000 * 999) / 2; // n*(n-1)/2 where all comparisons are true

        assert_eq!(result.len(), expected_count);

        // Verify all pairs are valid
        for &(i, j) in &result {
            assert!(i < 1000 && j < 1000);
            assert!(i != j);
            let a = numbers[i];
            let b = numbers[j];
            assert!(!a.is_nan());
            assert!(!b.is_nan());
            assert!(a.ge(&b));
        }
    }

    #[test]
    fn test_descending_order() {
        let numbers = &[3.0, 2.0, 1.0];
        let result = find_valid_ge_pairs(numbers);

        // In descending order, all i,j pairs where i <= j should be valid
        let mut expected = vec![
            (0, 1), // 3.0 >= 2.0
            (0, 2), // 3.0 >= 1.0
            (1, 2), // 2.0 >= 1.0
        ];

        expected.sort();
        let mut result_sorted = result;
        result_sorted.sort();

        assert_eq!(result_sorted, expected);
    }
}

