            (Ordering::Greater, true),
        ];

        for (input, expected) in test_cases {
            assert_eq!(
                filter_greater(input),
                expected,
                "Failed for Ordering variant: {:?}",
                input
            );
        }
    }

    #[test]
    fn test_filter_greater_is_pure_function() {
        // Test that the function returns consistent results for same inputs
        assert_eq!(filter_greater(Ordering::Greater), filter_greater(Ordering::Greater));
        assert_eq!(filter_greater(Ordering::Equal), filter_greater(Ordering::Equal));
        assert_eq!(filter_greater(Ordering::Less), filter_greater(Ordering::Less));
    }

    #[test]
    fn test_filter_greater_with_exhaustive_matching() {
        // Test all possible Ordering values
        match Ordering::Greater {
            Ordering::Greater => assert!(filter_greater(Ordering::Greater)),
            _ => panic!("Should not reach here"),
        }

        match Ordering::Equal {
            Ordering::Equal => assert!(!filter_greater(Ordering::Equal)),
            _ => panic!("Should not reach here"),
        }

        match Ordering::Less {
            Ordering::Less => assert!(!filter_greater(Ordering::Less)),
            _ => panic!("Should not reach here"),
        }
    }

    #[test]
    fn test_filter_greater_edge_cases() {
        // Verify function works correctly with repeated calls
        for _ in 0..100 {
            assert!(filter_greater(Ordering::Greater));
            assert!(!filter_greater(Ordering::Equal));
            assert!(!filter_greater(Ordering::Less));
        }
    }
}

