fn verify_packet_checksums(packets: &[u8]) -> Vec<bool> {
    const PACKET_SIZE: usize = 64;
    const HEADER_SIZE: usize = 4;

    // SAFETY: The function precondition guarantees packets.len() % 64 == 0
    let packet_chunks = unsafe { packets.as_chunks_unchecked::<PACKET_SIZE>() };

    packet_chunks.iter()
        .map(|packet| {
            let checksum = packet[0..HEADER_SIZE]
                .iter()
                .fold(0u32, |acc, &byte| acc.wrapping_add(byte as u32));
            checksum % 256 == 0
        })
        .collect()
}

