mod tests {
    use super::verify_packet_checksums;

    #[test]
    fn test_empty_slice() {
        let packets: &[u8] = &[];
        let result = verify_packet_checksums(packets);
        assert_eq!(result, Vec::<bool>::new());
    }

    #[test]
    fn test_single_packet_valid_checksum() {
        // Packet where sum of first 4 bytes mod 256 == 0
        // 64 + 64 + 64 + 64 = 256, 256 % 256 = 0
        let packets = vec![64u8; 64];
        let result = verify_packet_checksums(&packets);
        assert_eq!(result, vec![true]);
    }

    #[test]
    fn test_single_packet_invalid_checksum() {
        // Packet where sum of first 4 bytes mod 256 != 0
        let mut packets = vec![0u8; 64];
        packets[0] = 1; // 1 % 256 = 1
        let result = verify_packet_checksums(&packets);
        assert_eq!(result, vec![false]);
    }

    #[test]
    fn test_multiple_packets_mixed_results() {
        // Create 3 packets with different checksums
        let mut packets = Vec::new();

        // Packet 1: valid checksum (0, 0, 0, 0) -> 0 % 256 = 0
        packets.extend(vec![0u8; 64]);

        // Packet 2: invalid checksum (1, 0, 0, 0) -> 1 % 256 = 1
        let mut packet2 = vec![0u8; 64];
        packet2[0] = 1;
        packets.extend(packet2);

        // Packet 3: valid checksum (255, 1, 0, 0) -> 256 % 256 = 0
        let mut packet3 = vec![0u8; 64];
        packet3[0] = 255;
        packet3[1] = 1;
        packets.extend(packet3);

        let result = verify_packet_checksums(&packets);
        assert_eq!(result, vec![true, false, true]);
    }

    #[test]
    fn test_wrapping_overflow_checksum() {
        // Test checksum calculation with overflow
        // u8::MAX = 255, so 255 + 255 + 255 + 3 = 768, 768 % 256 = 0
        let mut packets = vec![0u8; 64];
        packets[0] = 255;
        packets[1] = 255;
        packets[2] = 255;
        packets[3] = 3;

        let result = verify_packet_checksums(&packets);
        assert_eq!(result, vec![true]);
    }

    #[test]
    fn test_exactly_two_packets() {
        let mut packets = Vec::new();

        // First packet: invalid checksum
        let mut packet1 = vec![0u8; 64];
        packet1[0] = 42;
        packets.extend(packet1);

        // Second packet: valid checksum
        let packet2 = vec![0u8; 64];
        packets.extend(packet2);

        let result = verify_packet_checksums(&packets);
        assert_eq!(result, vec![false, true]);
    }

    #[test]
    fn test_large_number_of_packets() {
        const NUM_PACKETS: usize = 1000;
        let mut packets = Vec::with_capacity(NUM_PACKETS * 64);
        let mut expected_results = Vec::with_capacity(NUM_PACKETS);

        for i in 0..NUM_PACKETS {
            let mut packet = vec![0u8; 64];
            // Alternate between valid and invalid checksums
            if i % 2 == 0 {
                // Valid checksum: all zeros
                expected_results.push(true);
            } else {
                // Invalid checksum: set first byte to 1
                packet[0] = 1;
                expected_results.push(false);
            }
            packets.extend(packet);
        }

        let result = verify_packet_checksums(&packets);
        assert_eq!(result, expected_results);
    }

    #[test]
    fn test_checksum_only_considers_first_four_bytes() {
        // Packet where first 4 bytes sum to 0, but rest of packet is non-zero
        let mut packets = vec![0u8; 64];
        // Set bytes after header to non-zero values
        for i in 4..64 {
            packets[i] = (i % 256) as u8;
        }

        let result = verify_packet_checksums(&packets);
        assert_eq!(result, vec![true]);
    }

    #[test]
    fn test_all_bytes_in_header_matter() {
        // Test that all 4 header bytes contribute to checksum
        let mut packets = vec![0u8; 64];

        // 64 + 64 + 64 + 64 = 256, 256 % 256 = 0
        packets[0] = 64;
        packets[1] = 64;
        packets[2] = 64;
        packets[3] = 64;

        let result = verify_packet_checksums(&packets);
        assert_eq!(result, vec![true]);

        // Change one byte to make checksum invalid
        packets[3] = 65; // 64 + 64 + 64 + 65 = 257, 257 % 256 = 1
        let result = verify_packet_checksums(&packets);
        assert_eq!(result, vec![false]);
    }
}

