use std::fs;
use std::io;
use std::path::{Path, PathBuf};

fn resolve_link_absolute(link_path: &Path) -> io::Result<PathBuf> {
    let mut current_path = link_path.to_path_buf();
    let mut visited = Vec::new();

    loop {
        let metadata = fs::symlink_metadata(&current_path)?;

        if !metadata.file_type().is_symlink() {
            return Ok(current_path.canonicalize()?);
        }

        if visited.contains(&current_path) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "Symlink cycle detected"
            ));
        }

        visited.push(current_path.clone());
        let target = fs::read_link(&current_path)?;

        current_path = if target.is_absolute() {
            target
        } else {
            current_path.parent()
                .ok_or_else(|| io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "Invalid symlink path"
                ))?
                .join(target)
        };
    }
}

