fn audit_command_envs(command: &mut std::process::Command) -> Vec<(std::ffi::OsString, Option<std::ffi::OsString>)> {
    let mut result = Vec::new();
    let mut env_iter = command.get_envs();

    while let Some((key, value)) = env_iter.next() {
        result.push((
            key.to_os_string(),
            value.map(|v| v.to_os_string())
        ));
    }

    result
}

