        let result = audit_command_envs(&mut cmd);
        assert_eq!(result.len(), 1);
        assert_eq!(result[0].0, OsString::from("KEY1"));
        assert_eq!(result[0].1, Some(OsString::from("value1")));
    }

    #[test]
    fn test_multiple_envs_with_values() {
        let mut cmd = Command::new("echo");
        cmd.env("KEY1", "value1")
           .env("KEY2", "value2")
           .env("KEY3", "value3");

        let result = audit_command_envs(&mut cmd);
        assert_eq!(result.len(), 3);

        // Convert to HashMap for easier comparison (order doesn't matter)
        use std::collections::HashMap;
        let map: HashMap<_, _> = result.into_iter().collect();

        assert_eq!(map.get(&OsString::from("KEY1")), Some(&Some(OsString::from("value1"))));
        assert_eq!(map.get(&OsString::from("KEY2")), Some(&Some(OsString::from("value2"))));
        assert_eq!(map.get(&OsString::from("KEY3")), Some(&Some(OsString::from("value3"))));
    }

    #[test]
    fn test_env_without_value() {
        let mut cmd = Command::new("echo");
        cmd.env_remove("REMOVED_KEY");

        let result = audit_command_envs(&mut cmd);
        assert_eq!(result.len(), 1);
        assert_eq!(result[0].0, OsString::from("REMOVED_KEY"));
        assert_eq!(result[0].1, None);
    }

    #[test]
    fn test_mixed_envs_with_and_without_values() {
        let mut cmd = Command::new("echo");
        cmd.env("SET_KEY", "set_value")
           .env_remove("REMOVED_KEY");

        let result = audit_command_envs(&mut cmd);
        assert_eq!(result.len(), 2);

        // Convert to HashMap for easier comparison
        use std::collections::HashMap;
        let map: HashMap<_, _> = result.into_iter().collect();

        assert_eq!(map.get(&OsString::from("SET_KEY")), Some(&Some(OsString::from("set_value"))));
        assert_eq!(map.get(&OsString::from("REMOVED_KEY")), Some(&None));
    }

    #[test]
    fn test_env_overwrites() {
        let mut cmd = Command::new("echo");
        cmd.env("KEY", "first")
           .env("KEY", "second"); // Overwrites first

        let result = audit_command_envs(&mut cmd);
        assert_eq!(result.len(), 1);
        assert_eq!(result[0].0, OsString::from("KEY"));
        assert_eq!(result[0].1, Some(OsString::from("second")));
    }

    #[test]
    fn test_env_remove_after_set() {
        let mut cmd = Command::new("echo");
        cmd.env("KEY", "value")
           .env_remove("KEY"); // Removes after setting

        let result = audit_command_envs(&mut cmd);
        assert_eq!(result.len(), 1);
        assert_eq!(result[0].0, OsString::from("KEY"));
        assert_eq!(result[0].1, None);
    }

    #[test]
    fn test_env_set_after_remove() {
        let mut cmd = Command::new("echo");
        cmd.env_remove("KEY")
           .env("KEY", "new_value"); // Sets after removing

        let result = audit_command_envs(&mut cmd);
        assert_eq!(result.len(), 1);
        assert_eq!(result[0].0, OsString::from("KEY"));
        assert_eq!(result[0].1, Some(OsString::from("new_value")));
    }

    #[test]
    fn test_non_ascii_env_names_and_values() {
        let mut cmd = Command::new("echo");
        let name = "KEY_WITH_ÜNICØDE";
        let value = "valüe_with_emoji_🚀";

        cmd.env(name, value);

        let result = audit_command_envs(&mut cmd);
        assert_eq!(result.len(), 1);
        assert_eq!(result[0].0, OsString::from(name));
        assert_eq!(result[0].1, Some(OsString::from(value)));
    }

    #[test]
    fn test_empty_string_values() {
        let mut cmd = Command::new("echo");
        cmd.env("EMPTY_KEY", "");

        let result = audit_command_envs(&mut cmd);
        assert_eq!(result.len(), 1);
        assert_eq!(result[0].0, OsString::from("EMPTY_KEY"));
        assert_eq!(result[0].1, Some(OsString::from("")));
    }

    #[test]
    fn test_command_envs_clear() {
        let mut cmd = Command::new("echo");
        cmd.env("KEY1", "value1")
           .env("KEY2", "value2")
           .env_clear(); // Clears all environments

        let result = audit_command_envs(&mut cmd);
        assert!(result.is_empty());
    }

    #[test]
    fn test_command_envs_clear_with_subsequent_adds() {
        let mut cmd = Command::new("echo");
        cmd.env("OLD_KEY", "old_value")
           .env_clear()
           .env("NEW_KEY", "new_value");

        let result = audit_command_envs(&mut cmd);
        assert_eq!(result.len(), 1);
        assert_eq!(result[0].0, OsString::from("NEW_KEY"));
        assert_eq!(result[0].1, Some(OsString::from("new_value")));
    }

    #[test]
    fn test_multiple_calls_preserve_command_state() {
        let mut cmd = Command::new("echo");
        cmd.env("PERSISTENT_KEY", "persistent_value");

        // First call
        let result1 = audit_command_envs(&mut cmd);
        assert_eq!(result1.len(), 1);

        // Second call should still work
        let result2 = audit_command_envs(&mut cmd);
        assert_eq!(result2.len(), 1);
        assert_eq!(result2[0].0, OsString::from("PERSISTENT_KEY"));
        assert_eq!(result2[0].1, Some(OsString::from("persistent_value")));
    }
