fn clean_and_join_lines(lines: &[&str]) -> String {
    let capacity = lines.iter().map(|line| line.trim_end().len()).sum::<usize>() + lines.len();
    let mut result = String::with_capacity(capacity);

    for (i, line) in lines.iter().enumerate() {
        if i > 0 {
            result.push('\n');
        }
        result.push_str(line.trim_end());
    }

    result
}

