mod tests {
    use super::*;

    #[test]
    fn test_positive_numbers() {
        assert!(!is_left_oriented(0.0));
        assert!(!is_left_oriented(1.0));
        assert!(!is_left_oriented(3.14159));
        assert!(!is_left_oriented(f32::MAX));
        assert!(!is_left_oriented(f32::MIN_POSITIVE));
    }

    #[test]
    fn test_negative_numbers() {
        assert!(is_left_oriented(-0.0));
        assert!(is_left_oriented(-1.0));
        assert!(is_left_oriented(-3.14159));
        assert!(is_left_oriented(-f32::MAX));
        assert!(is_left_oriented(-f32::MIN_POSITIVE));
    }

    #[test]
    fn test_special_values() {
        // Positive infinity
        assert!(!is_left_oriented(f32::INFINITY));

        // Negative infinity
        assert!(is_left_oriented(-f32::INFINITY));

        // Positive NaN
        let pos_nan: f32 = f32::NAN;
        assert!(!is_left_oriented(pos_nan));

        // Negative NaN
        let neg_nan: f32 = -f32::NAN;
        assert!(is_left_oriented(neg_nan));
    }

    #[test]
    fn test_edge_cases() {
        // Positive zero
        assert!(!is_left_oriented(0.0f32));

        // Negative zero
        assert!(is_left_oriented(-0.0f32));

        // Smallest positive normal
        assert!(!is_left_oriented(f32::MIN_POSITIVE));

        // Smallest negative normal
        assert!(is_left_oriented(-f32::MIN_POSITIVE));

        // Largest positive finite
        assert!(!is_left_oriented(f32::MAX));

        // Largest negative finite
        assert!(is_left_oriented(-f32::MAX));
    }

    #[test]
    fn test_const_context() {
        // Verify the function can be used in const context
        const POSITIVE_RESULT: bool = is_left_oriented(42.0);
        const NEGATIVE_RESULT: bool = is_left_oriented(-42.0);
        const ZERO_RESULT: bool = is_left_oriented(0.0);
        const NEG_ZERO_RESULT: bool = is_left_oriented(-0.0);

        assert!(!POSITIVE_RESULT);
        assert!(NEGATIVE_RESULT);
        assert!(!ZERO_RESULT);
        assert!(NEG_ZERO_RESULT);
    }

    #[test]
    fn test_sign_bit_behavior() {
        // Test that only the sign bit matters
        assert!(!is_left_oriented(1.0));      // Positive
        assert!(is_left_oriented(-1.0));      // Negative

        assert!(!is_left_oriented(0.1));      // Positive
        assert!(is_left_oriented(-0.1));      // Negative

        assert!(!is_left_oriented(1000.0));   // Positive
        assert!(is_left_oriented(-1000.0));   // Negative
    }
}

