#[cfg(test)]
mod tests {
    use std::ffi::{CStr, CString};
    use std::os::raw::c_char;

    // Helper function to create a CString from bytes, panicking on failure
    fn cstring_from_bytes(bytes: &[u8]) -> CString {
        CString::new(bytes).expect("Failed to create CString from bytes")
    }

    #[test]
    fn test_get_cstr_reference_basic() {
        let cstring = cstring_from_bytes(b"hello");
        let cstr = super::get_cstr_reference(&cstring);

        // Verify the CStr contains the expected data
        assert_eq!(cstr.to_bytes(), b"hello");
        // Verify null termination
        assert_eq!(cstr.to_bytes_with_nul(), b"hello\0");
    }

    #[test]
    fn test_get_cstr_reference_empty_string() {
        let cstring = cstring_from_bytes(b"");
        let cstr = super::get_cstr_reference(&cstring);

        assert_eq!(cstr.to_bytes(), b"");
        assert_eq!(cstr.to_bytes_with_nul(), b"\0");
    }

    #[test]
    fn test_get_cstr_reference_with_nulls_in_content() {
        // CString::new will fail if the input contains interior null bytes
        // This is expected behavior
        let result = CString::new(b"hello\0world");
        assert!(result.is_err());
    }

    #[test]
    fn test_get_cstr_reference_with_special_characters() {
        let cstring = cstring_from_bytes(b"test\x01\x02\x03");
        let cstr = super::get_cstr_reference(&cstring);

        assert_eq!(cstr.to_bytes(), b"test\x01\x02\x03");
        assert_eq!(cstr.to_bytes_with_nul(), b"test\x01\x02\x03\0");
    }

    #[test]
    fn test_get_cstr_reference_unicode() {
        let cstring = CString::new("Hello, 世界!").expect("Failed to create CString from Unicode");
        let cstr = super::get_cstr_reference(&cstring);

        // Verify the UTF-8 bytes are preserved
        assert_eq!(cstr.to_bytes(), "Hello, 世界!".as_bytes());
    }

    #[test]
    fn test_get_cstr_reference_lifetime_validity() {
        let cstring = cstring_from_bytes(b"test");
        let cstr_ref = {
            // Create a reference to the CString
            let cstr = super::get_cstr_reference(&cstring);
            // Verify it's still valid after the CString exists
            assert_eq!(cstr.to_bytes(), b"test");
            cstr
        };

        // Even though cstr_ref was created in inner scope, it should still be valid
        // because it references the CString which is still alive
        assert_eq!(cstr_ref.to_bytes(), b"test");
    }

    #[test]
    fn test_get_cstr_reference_for_c_function() {
        let cstring = cstring_from_bytes(b"c_function_input");
        let cstr = super::get_cstr_reference(&cstring);

        // Simulate passing to a C function by getting the raw pointer
        let ptr: *const c_char = cstr.as_ptr();

        // Verify the pointer is not null
        assert!(!ptr.is_null());

        // Verify we can reconstruct the CStr from the pointer
        unsafe {
            let reconstructed = CStr::from_ptr(ptr);
            assert_eq!(reconstructed.to_bytes(), b"c_function_input");
        }
    }

    #[test]
    fn test_get_cstr_reference_multiple_references() {
        let cstring = cstring_from_bytes(b"shared");
        let cstr1 = super::get_cstr_reference(&cstring);
        let cstr2 = super::get_cstr_reference(&cstring);

        // Both references should point to the same data
        assert_eq!(cstr1.to_bytes(), cstr2.to_bytes());
        assert_eq!(cstr1.as_ptr(), cstr2.as_ptr());
    }

    #[test]
    fn test_get_cstr_reference_from_various_sources() {
        // Test with CString created from Vec<u8>
        let vec = vec![b't', b'e', b's', b't'];
        let cstring1 = CString::new(vec).expect("Failed to create CString from Vec");
        let cstr1 = super::get_cstr_reference(&cstring1);
        assert_eq!(cstr1.to_bytes(), b"test");

        // Test with CString created from &str
        let cstring2 = CString::new("string").expect("Failed to create CString from &str");
        let cstr2 = super::get_cstr_reference(&cstring2);
        assert_eq!(cstr2.to_bytes(), b"string");

        // Test with CString created from String
        let string = String::from("owned");
        let cstring3 = CString::new(string).expect("Failed to create CString from String");
        let cstr3 = super::get_cstr_reference(&cstring3);
        assert_eq!(cstr3.to_bytes(), b"owned");
    }

    #[test]
    fn test_get_cstr_reference_no_allocation() {
        // This test verifies that no additional allocation happens
        // We can't directly test this, but we can verify that the pointer
        // from the CString is the same as from the returned CStr

        let cstring = cstring_from_bytes(b"no_copy");
        let cstring_ptr = cstring.as_ptr();
        let cstr = super::get_cstr_reference(&cstring);
        let cstr_ptr = cstr.as_ptr();

        // Both should point to the same memory location
        assert_eq!(cstring_ptr, cstr_ptr);
    }

    #[test]
    fn test_get_cstr_reference_null_termination() {
        let test_cases = [
            (b"simple".as_ref(), b"simple\0".as_ref()),
            (b"with spaces".as_ref(), b"with spaces\0".as_ref()),
            (b"end_with_null".as_ref(), b"end_with_null\0".as_ref()),
        ];

        for (input, expected_with_null) in test_cases.iter() {
            let cstring = cstring_from_bytes(input);
            let cstr = super::get_cstr_reference(&cstring);

            assert_eq!(cstr.to_bytes_with_nul(), *expected_with_null);

            // Verify the last byte is indeed null
            let bytes_with_nul = cstr.to_bytes_with_nul();
            assert_eq!(bytes_with_nul.last(), Some(&0));
        }
    }
}

