use std::process::Command;

fn get_sorted_env_keys(cmd: &Command) -> Vec<String> {
    let mut env_keys: Vec<String> = cmd
        .get_envs()
        .filter_map(|(key, val)| {
            val.map(|_| key.to_string_lossy().into_owned())
        })
        .collect();

    env_keys.sort_unstable();
    env_keys
}

