mod tests {
    use super::*;
    use std::process::Command;

    #[test]
    fn test_empty_environment() {
        let cmd = Command::new("echo");
        let result = get_sorted_env_keys(&cmd);
        assert!(result.is_empty());
    }

    #[test]
    fn test_single_environment_variable() {
        let mut cmd = Command::new("echo");
        cmd.env("FOO", "bar");

        let result = get_sorted_env_keys(&cmd);
        assert_eq!(result, vec!["FOO".to_string()]);
    }

    #[test]
    fn test_multiple_environment_variables() {
        let mut cmd = Command::new("echo");
        cmd.env("ZOO", "animal")
           .env("APPLE", "fruit")
           .env("BANANA", "fruit");

        let result = get_sorted_env_keys(&cmd);
        assert_eq!(result, vec!["APPLE".to_string(), "BANANA".to_string(), "ZOO".to_string()]);
    }

    #[test]
    fn test_environment_variables_with_none_values() {
        let mut cmd = Command::new("echo");
        cmd.env("PRESENT", "value")
           .env_remove("REMOVED");

        let result = get_sorted_env_keys(&cmd);
        assert_eq!(result, vec!["PRESENT".to_string()]);
        assert!(!result.contains(&"REMOVED".to_string()));
    }

    #[test]
    fn test_mixed_case_environment_variables() {
        let mut cmd = Command::new("echo");
        cmd.env("PATH", "/bin")
           .env("Path", "/usr/bin")
           .env("path", "/local/bin");

        let result = get_sorted_env_keys(&cmd);
        // Should sort lexicographically (ASCII order)
        assert_eq!(result, vec!["PATH".to_string(), "Path".to_string(), "path".to_string()]);
    }

    #[test]
    fn test_special_characters_in_keys() {
        let mut cmd = Command::new("echo");
        cmd.env("FOO-BAR", "value1")
           .env("FOO_BAR", "value2")
           .env("FOO.BAR", "value3");

        let result = get_sorted_env_keys(&cmd);
        assert_eq!(result, vec!["FOO-BAR".to_string(), "FOO.BAR".to_string(), "FOO_BAR".to_string()]);
    }

    #[test]
    fn test_large_number_of_environment_variables() {
        let mut cmd = Command::new("echo");

        // Add 1000 environment variables with numeric keys
        for i in (0..1000).rev() {
            cmd.env(format!("KEY_{:04}", i), "value");
        }

        let result = get_sorted_env_keys(&cmd);

        // Verify all keys are present
        assert_eq!(result.len(), 1000);

        // Verify sorting
        for i in 0..999 {
            assert!(result[i] < result[i + 1]);
        }

        // Verify specific ordering
        assert_eq!(result[0], "KEY_0000");
        assert_eq!(result[999], "KEY_0999");
    }

    #[test]
    fn test_unicode_environment_variables() {
        let mut cmd = Command::new("echo");
        cmd.env("FÖÖ", "value1")
           .env("BAR", "value2")
           .env("BAZ", "value3");

        let result = get_sorted_env_keys(&cmd);
        // Unicode should sort after ASCII in lexicographic order
        assert_eq!(result, vec!["BAR".to_string(), "BAZ".to_string(), "FÖÖ".to_string()]);
    }

    #[test]
    fn test_command_clone_preserves_environment() {
        let mut cmd1 = Command::new("echo");
        cmd1.env("ORIGINAL", "value");

        // Clone by creating a new command with the same environment
        let mut cmd2 = Command::new("echo");
        for (key, value) in cmd1.get_envs() {
            if let Some(val) = value {
                cmd2.env(key, val);
            }
        }

        let result1 = get_sorted_env_keys(&cmd1);
        let result2 = get_sorted_env_keys(&cmd2);

        assert_eq!(result1, result2);
    }

    #[test]
    fn test_environment_after_removal() {
        let mut cmd = Command::new("echo");
        cmd.env("KEEP", "value1")
           .env("REMOVE", "value2");

        // First check both are present
        let result = get_sorted_env_keys(&cmd);
        assert_eq!(result, vec!["KEEP".to_string(), "REMOVE".to_string()]);

        // Remove one and check
        cmd.env_remove("REMOVE");
        let result = get_sorted_env_keys(&cmd);
        assert_eq!(result, vec!["KEEP".to_string()]);
    }
}

