pub fn apply_gamma_correction(buffer: &mut [f32], gamma: f32) -> Result<(), &'static str> {
    if gamma <= 0.0 {
        return Err("Gamma must be positive");
    }

    let inv_gamma = 1.0 / gamma;
    for pixel in buffer.iter_mut() {
        *pixel = pixel.powf(inv_gamma);
    }

    Ok(())
}

