#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_apply_gamma_correction_basic() {
        let mut buffer = vec![0.0, 0.25, 0.5, 0.75, 1.0];
        let gamma = 2.2;

        apply_gamma_correction(&mut buffer, gamma).unwrap();

        // Test with gamma=2.2, inverse gamma = 1/2.2 ≈ 0.454545
        let expected = vec![
            0.0f32.powf(1.0 / 2.2),
            0.25f32.powf(1.0 / 2.2),
            0.5f32.powf(1.0 / 2.2),
            0.75f32.powf(1.0 / 2.2),
            1.0f32.powf(1.0 / 2.2),
        ];

        for (actual, expected) in buffer.iter().zip(expected.iter()) {
            assert!((actual - expected).abs() < 1e-6);
        }
    }

    #[test]
    fn test_apply_gamma_correction_gamma_one() {
        let mut buffer = vec![0.1, 0.5, 0.9];
        let original = buffer.clone();
        let gamma = 1.0;

        apply_gamma_correction(&mut buffer, gamma).unwrap();

        // With gamma=1, inv_gamma=1, values should remain unchanged
        for (actual, expected) in buffer.iter().zip(original.iter()) {
            assert_eq!(actual, expected);
        }
    }

    #[test]
    fn test_apply_gamma_correction_gamma_less_than_one() {
        let mut buffer = vec![0.25, 0.5, 0.75];
        let gamma = 0.5; // inv_gamma = 2.0

        apply_gamma_correction(&mut buffer, gamma).unwrap();

        let expected = vec![
            0.25f32.powf(2.0),
            0.5f32.powf(2.0),
            0.75f32.powf(2.0),
        ];

        for (actual, expected) in buffer.iter().zip(expected.iter()) {
            assert!((actual - expected).abs() < 1e-6);
        }
    }

    #[test]
    fn test_apply_gamma_correction_negative_gamma_error() {
        let mut buffer = vec![1.0, 2.0, 3.0];
        let gamma = -1.0;

        let result = apply_gamma_correction(&mut buffer, gamma);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), "Gamma must be positive");

        // Buffer should remain unchanged
        assert_eq!(buffer, vec![1.0, 2.0, 3.0]);
    }

    #[test]
    fn test_apply_gamma_correction_zero_gamma_error() {
        let mut buffer = vec![1.0, 2.0, 3.0];
        let gamma = 0.0;

        let result = apply_gamma_correction(&mut buffer, gamma);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), "Gamma must be positive");

        // Buffer should remain unchanged
        assert_eq!(buffer, vec![1.0, 2.0, 3.0]);
    }

    #[test]
    fn test_apply_gamma_correction_empty_buffer() {
        let mut buffer: Vec<f32> = vec![];
        let gamma = 2.2;

        let result = apply_gamma_correction(&mut buffer, gamma);
        assert!(result.is_ok());
        assert!(buffer.is_empty());
    }

    #[test]
    fn test_apply_gamma_correction_single_element() {
        let mut buffer = vec![0.5];
        let gamma = 2.0;

        apply_gamma_correction(&mut buffer, gamma).unwrap();

        let expected = 0.5f32.powf(0.5); // sqrt(0.5)
        assert!((buffer[0] - expected).abs() < 1e-6);
    }

    #[test]
    fn test_apply_gamma_correction_large_buffer() {
        let mut buffer: Vec<f32> = (0..1000).map(|i| (i % 100) as f32 / 100.0).collect();
        let original = buffer.clone();
        let gamma = 2.2;

        apply_gamma_correction(&mut buffer, gamma).unwrap();

        for i in 0..buffer.len() {
            let expected = original[i].powf(1.0 / gamma);
            assert!((buffer[i] - expected).abs() < 1e-6);
        }
    }

    #[test]
    fn test_apply_gamma_correction_edge_cases() {
        let mut buffer = vec![0.0, 1.0];
        let gamma = 2.0;

        apply_gamma_correction(&mut buffer, gamma).unwrap();

        // 0^0.5 = 0, 1^0.5 = 1
        assert_eq!(buffer[0], 0.0);
        assert_eq!(buffer[1], 1.0);
    }

    #[test]
    fn test_apply_gamma_correction_negative_values() {
        let mut buffer = vec![-1.0, -0.5, -0.1];
        let gamma = 2.0;

        // powf with negative base and non-integer exponent returns NaN
        apply_gamma_correction(&mut buffer, gamma).unwrap();

        for value in buffer {
            assert!(value.is_nan());
        }
    }

    #[test]
    fn test_apply_gamma_correction_array_slice() {
        let mut array = [0.25, 0.5, 0.75];
        let gamma = 2.0;

        apply_gamma_correction(&mut array[..], gamma).unwrap();

        let expected = [
            0.25f32.powf(0.5),
            0.5f32.powf(0.5),
            0.75f32.powf(0.5),
        ];

        for i in 0..array.len() {
            assert!((array[i] - expected[i]).abs() < 1e-6);
        }
    }

    #[test]
    fn test_apply_gamma_correction_mutability() {
        let mut buffer = vec![0.5, 0.6, 0.7];
        let original_ptr = buffer.as_ptr();
        let gamma = 2.2;

        apply_gamma_correction(&mut buffer, gamma).unwrap();

        // Verify the slice was modified in place
        assert_eq!(buffer.as_ptr(), original_ptr);
        assert_ne!(buffer, vec![0.5, 0.6, 0.7]);
    }
}

