#[cfg(test)]
mod tests {
    use super::*;
    use std::fs::{self, File, OpenOptions};
    use std::io::{self, Write, Read};
    use std::sync::{Arc, Barrier};
    use std::thread;
    use std::time::Duration;
    use std::env::temp_dir;

    #[test]
    fn test_acquire_concurrent_read_lock_success() {
        let temp_dir = temp_dir();
        let path = temp_dir.join("test_file.txt");

        // Create test file
        File::create(&path).unwrap();
        let file = File::open(&path).unwrap();

        // Should acquire shared lock without error
        let result = acquire_concurrent_read_lock(&file);
        assert!(result.is_ok());

        // Cleanup
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn test_acquire_concurrent_read_lock_on_invalid_file() {
        // Create a file and immediately close it to get an invalid file handle
        let temp_dir = temp_dir();
        let path = temp_dir.join("non_existent_file.txt");

        // Try to open a file that doesn't exist
        let result = File::open(&path);
        assert!(result.is_err());
    }

    #[test]
    fn test_multiple_readers_can_lock_simultaneously() {
        let temp_dir = temp_dir();
        let path = temp_dir.join("multi_read_test.txt");

        // Write some content to the file
        fs::write(&path, "test content").unwrap();

        let barrier = Arc::new(Barrier::new(3));
        let mut handles = vec![];

        for _ in 0..3 {
            let path_clone = path.clone();
            let barrier_clone = Arc::clone(&barrier);

            let handle = thread::spawn(move || {
                let file = File::open(&path_clone).unwrap();
                barrier_clone.wait(); // Synchronize all threads

                // All threads should be able to acquire shared locks simultaneously
                let result = acquire_concurrent_read_lock(&file);
                assert!(result.is_ok());

                // Verify we can read from the file while holding the lock
                let mut content = String::new();
                let mut file_clone = file.try_clone().unwrap();
                let read_result = file_clone.read_to_string(&mut content);
                assert!(read_result.is_ok());
                assert_eq!(content, "test content");
            });

            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        // Cleanup
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn test_read_lock_blocks_exclusive_write() {
        let temp_dir = temp_dir();
        let path = temp_dir.join("block_write_test.txt");

        // Write initial content
        fs::write(&path, "initial content").unwrap();

        let (tx, rx) = std::sync::mpsc::channel();
        let (tx2, rx2) = std::sync::mpsc::channel();

        // Thread 1: Acquire shared read lock
        let path_clone = path.clone();
        let reader_thread = thread::spawn(move || {
            let file = File::open(&path_clone).unwrap();
            let lock_result = acquire_concurrent_read_lock(&file);
            assert!(lock_result.is_ok());

            tx.send(()).unwrap(); // Signal that read lock is acquired

            // Hold the lock for a bit
            thread::sleep(Duration::from_millis(100));

            // Read while holding the lock
            let mut content = String::new();
            let mut file_clone = file.try_clone().unwrap();
            file_clone.read_to_string(&mut content).unwrap();
            assert_eq!(content, "initial content");

            rx2.recv().unwrap(); // Wait for writer to try
        });

        // Wait for reader to acquire lock
        rx.recv().unwrap();

        // Thread 2: Try to acquire exclusive write lock (should block or fail)
        let path_clone2 = path.clone();
        let writer_thread = thread::spawn(move || {
            let file = OpenOptions::new()
                .write(true)
                .open(&path_clone2)
                .unwrap();

            // Try to get exclusive lock - this should fail or block while read lock is held
            let result = acquire_concurrent_read_lock(&file);

            // Signal that we tried to write
            tx2.send(()).unwrap();

            // The function should succeed since it's a shared lock
            assert!(result.is_ok());
        });

        reader_thread.join().unwrap();
        writer_thread.join().unwrap();

        // Cleanup
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn test_read_lock_released_when_file_dropped() {
        let temp_dir = temp_dir();
        let path = temp_dir.join("drop_test.txt");

        // Create test file
        File::create(&path).unwrap();

        // Scope to ensure file is dropped
        {
            let file = File::open(&path).unwrap();
            let result = acquire_concurrent_read_lock(&file);
            assert!(result.is_ok());
            // file drops here, releasing the lock
        }

        // Now we should still be able to get a read lock
        let file = File::open(&path).unwrap();
        let result = acquire_concurrent_read_lock(&file);
        // This should succeed now that previous lock is released
        assert!(result.is_ok());

        // Cleanup
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn test_concurrent_reads_with_content_verification() {
        let temp_dir = temp_dir();
        let path = temp_dir.join("content_test.txt");

        // Write known content
        let expected_content = "A".repeat(1024); // 1KB of data
        fs::write(&path, &expected_content).unwrap();

        let num_threads = 5;
        let barrier = Arc::new(Barrier::new(num_threads));
        let mut handles = vec![];

        for i in 0..num_threads {
            let path_clone = path.clone();
            let barrier_clone = Arc::clone(&barrier);
            let expected_clone = expected_content.clone();

            let handle = thread::spawn(move || {
                let file = File::open(&path_clone).unwrap();
                barrier_clone.wait();

                // Acquire shared lock
                let lock_result = acquire_concurrent_read_lock(&file);
                assert!(lock_result.is_ok(), "Thread {} failed to acquire lock", i);

                // Read and verify content
                let mut content = String::new();
                let mut file_clone = file.try_clone().unwrap();
                file_clone.read_to_string(&mut content).unwrap();
                assert_eq!(content, expected_clone, "Thread {} read incorrect content", i);

                // Read again to ensure consistency
                let mut file2 = File::open(&path_clone).unwrap();
                let mut content2 = String::new();
                file2.read_to_string(&mut content2).unwrap();
                assert_eq!(content2, expected_clone, "Thread {} read inconsistent content", i);
            });

            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        // Cleanup
        let _ = fs::remove_file(&path);
    }
}

