mod tests {
    use super::*;
    use std::fs::File;
    use std::io::{ErrorKind, Write};
    use std::path::PathBuf;
    use std::env;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn create_temp_file() -> (PathBuf, File) {
        let mut temp_dir = env::temp_dir();
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let file_name = format!("test_{}.txt", timestamp);
        temp_dir.push(file_name);

        let file = File::create(&temp_dir).unwrap();
        (temp_dir, file)
    }

    fn allow_unsupported(result: Result<(), std::io::Error>) -> Result<(), std::io::Error> {
        match result {
            Err(e) if e.kind() == ErrorKind::Unsupported => Ok(()),
            other => other,
        }
    }

    #[test]
    fn test_exclusive_access_success_or_unsupported() {
        let (_temp_path, file) = create_temp_file();
        let result = attempt_exclusive_file_access(&file);
        let result = allow_unsupported(result);
        assert!(result.is_ok());
    }

    #[test]
    fn test_exclusive_access_would_block_or_ok() {
        let (temp_path, file1) = create_temp_file();
        let file2 = File::open(&temp_path).unwrap();

        let _ = attempt_exclusive_file_access(&file1);
        let result = attempt_exclusive_file_access(&file2);

        match result {
            Ok(()) => {},
            Err(e) if e.kind() == ErrorKind::WouldBlock || e.kind() == ErrorKind::Unsupported => {},
            Err(e) => panic!("Unexpected error kind: {:?}", e.kind()),
        }
    }

    #[test]
    fn test_lock_release_and_reattempt() {
        let (temp_path, file1) = create_temp_file();

        let _ = attempt_exclusive_file_access(&file1);
        drop(file1);

        let file2 = File::open(&temp_path).unwrap();
        let result2 = attempt_exclusive_file_access(&file2);
        let result2 = allow_unsupported(result2);
        assert!(result2.is_ok());

        let _ = std::fs::remove_file(&temp_path);
    }

    #[test]
    fn test_file_operations_while_locked() {
        let (temp_path, file) = create_temp_file();

        let _ = attempt_exclusive_file_access(&file);

        let mut file_for_write = File::create(&temp_path).unwrap();
        let write_result = file_for_write.write_all(b"test data");
        assert!(write_result.is_ok());

        let _ = std::fs::remove_file(&temp_path);
    }
}

