    #[test]
    fn test_successful_shared_lock() {
        // Create a temporary file for testing
        let temp_path = env::temp_dir().join("test_shared_lock.tmp");
        let file = File::create(&temp_path).unwrap();
        drop(file);

        let file = File::open(&temp_path).unwrap();

        // Attempt to acquire shared lock - should succeed
        let result = attempt_non_exclusive_config_lock(&file);
        assert!(result.is_ok());

        // Cleanup
        fs::remove_file(temp_path).ok();
    }

    #[test]
    fn test_multiple_shared_locks_allowed() {
        let temp_path = env::temp_dir().join("test_multiple_shared.tmp");
        let file = File::create(&temp_path).unwrap();
        drop(file);

        let file1 = File::open(&temp_path).unwrap();
        let file2 = File::open(&temp_path).unwrap();

        // First shared lock should succeed
        let result1 = attempt_non_exclusive_config_lock(&file1);
        assert!(result1.is_ok());

        // Second shared lock should also succeed (shared locks don't conflict)
        let result2 = attempt_non_exclusive_config_lock(&file2);
        assert!(result2.is_ok());

        // Cleanup
        fs::remove_file(temp_path).ok();
    }

    #[test]
    fn test_lock_fails_when_exclusive_lock_held() {
        let temp_path = env::temp_dir().join("test_exclusive_held.tmp");
        let file = File::create(&temp_path).unwrap();
        drop(file);

        let path_clone = temp_path.clone();

        // Create a thread that holds an exclusive lock
        let handle = thread::spawn(move || {
            let file = OpenOptions::new()
                .read(true)
                .write(true)
                .open(&path_clone)
                .unwrap();

            // Try to get exclusive lock - on Unix this will block
            // On non-Unix platforms, this test will behave differently
            #[cfg(unix)]
            {
                use std::os::unix::fs::FileExt;
                // Just hold the file open to simulate contention
            }

            // Hold the file open for a bit
            thread::sleep(Duration::from_millis(200));
        });

        // Give the thread time to open the file
        thread::sleep(Duration::from_millis(50));

        // Try to acquire shared lock while other thread has file open
        let file = File::open(&temp_path).unwrap();
        let result = attempt_non_exclusive_config_lock(&file);

        // The function should not panic
        match result {
            Ok(_) | Err(_) => (), // Accept any result
        }

        handle.join().unwrap();

        // Cleanup
        fs::remove_file(temp_path).ok();
    }

    #[test]
    fn test_shared_lock_after_exclusive_lock_released() {
        let temp_path = env::temp_dir().join("test_after_exclusive.tmp");
        let file = File::create(&temp_path).unwrap();
        drop(file);

        // Test that shared locks work normally
        let file = File::open(&temp_path).unwrap();
        let result = attempt_non_exclusive_config_lock(&file);
        assert!(result.is_ok());

        // Cleanup
        fs::remove_file(temp_path).ok();
    }

    #[test]
    fn test_concurrent_shared_locks() {
        let temp_path = env::temp_dir().join("test_concurrent.tmp");
        let file = File::create(&temp_path).unwrap();
        drop(file);

        let num_threads = 10;
        let barrier = Arc::new(Barrier::new(num_threads));

        let mut handles = Vec::new();
        let success_count = Arc::new(std::sync::atomic::AtomicUsize::new(0));

        for _ in 0..num_threads {
            let path_clone = temp_path.clone();
            let barrier_clone = barrier.clone();
            let success_count_clone = success_count.clone();

            let handle = thread::spawn(move || {
                // Wait for all threads to be ready
                barrier_clone.wait();

                let file = File::open(&path_clone).unwrap();
                match attempt_non_exclusive_config_lock(&file) {
                    Ok(()) => {
                        success_count_clone.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    }
                    Err(_) => {
                        panic!("Shared lock should not fail with concurrent shared access");
                    }
                }
            });

            handles.push(handle);
        }

        // Wait for all threads to complete
        for handle in handles {
            handle.join().unwrap();
        }

        // All threads should have successfully acquired shared locks
        assert_eq!(success_count.load(std::sync::atomic::Ordering::SeqCst), num_threads);

        // Cleanup
        fs::remove_file(temp_path).ok();
    }

    #[test]
    fn test_file_already_locked_shared() {
        let temp_path = env::temp_dir().join("test_already_shared.tmp");
        let file = File::create(&temp_path).unwrap();
        drop(file);

        let file = File::open(&temp_path).unwrap();

        // Acquire first shared lock
        let result1 = attempt_non_exclusive_config_lock(&file);
        assert!(result1.is_ok());

        // Try to acquire another shared lock on same file descriptor
        let result2 = attempt_non_exclusive_config_lock(&file);
        // This should succeed
        assert!(result2.is_ok());

        // Cleanup
        fs::remove_file(temp_path).ok();
    }

    #[test]
    fn test_lock_with_file_operations() {
        let temp_path = env::temp_dir().join("test_with_ops.tmp");
        let mut file = File::create(&temp_path).unwrap();

        // Write some data to the file
        writeln!(file, "test configuration data").unwrap();
        drop(file);

        let file = File::open(&temp_path).unwrap();

        // Acquire shared lock
        let result = attempt_non_exclusive_config_lock(&file);
        assert!(result.is_ok());

        // Should still be able to read from the file with shared lock
        let mut contents = String::new();
        let mut read_file = File::open(&temp_path).unwrap();
        read_file.read_to_string(&mut contents).unwrap();
        assert!(contents.contains("test configuration data"));

        // Cleanup
        fs::remove_file(temp_path).ok();
    }

    #[test]
    fn test_error_handling() {
        let temp_path = env::temp_dir().join("test_error.tmp");
        let file = File::create(&temp_path).unwrap();
        drop(file);

        let file = File::open(&temp_path).unwrap();

        // Test successful case returns Ok
        let result = attempt_non_exclusive_config_lock(&file);
        match result {
            Ok(()) => (),
            Err(e) => panic!("Expected Ok, got {:?}", e),
        }

        // Test that the function handles errors properly
        let result = attempt_non_exclusive_config_lock(&file);
        assert!(result.is_ok() || result.is_err());

        // Cleanup
        fs::remove_file(temp_path).ok();
    }
}

