mod tests {
    use super::*;
    use std::ffi::{OsStr, OsString};
    use std::ptr;

    #[test]
    fn test_create_persistent_os_string_basic() {
        let input = "hello world";
        let leaked = create_persistent_os_string(input);

        // Verify content matches
        assert_eq!(leaked, OsStr::new(input));

        // Verify it's mutable
        let ptr = leaked as *mut OsStr;
        unsafe {
            // Can write through the pointer to verify mutability
            let _ = &mut *ptr;
        }
    }

    #[test]
    fn test_create_persistent_os_string_empty() {
        let input = "";
        let leaked = create_persistent_os_string(input);

        assert_eq!(leaked, OsStr::new(""));
        assert_eq!(leaked.len(), 0);
    }

    #[test]
    fn test_create_persistent_os_string_special_characters() {
        let inputs = [
            "café",
            "naïve",
            "🎉🎊",
            "C:\\Program Files\\MyApp",
            "/usr/local/bin",
            "测试",
        ];

        for input in inputs {
            let leaked = create_persistent_os_string(input);
            assert_eq!(leaked, OsStr::new(input));
        }
    }

    #[test]
    fn test_create_persistent_os_string_mutability() {
        let input = "initial";
        let leaked = create_persistent_os_string(input);

        // Convert to OsString to modify
        let mut os_string = leaked.to_os_string();
        os_string.push("_modified");

        // Create new leaked version from modified string
        let modified_leaked = create_persistent_os_string(&os_string.to_string_lossy());
        assert_eq!(modified_leaked, OsStr::new("initial_modified"));
    }

    #[test]
    fn test_create_persistent_os_string_static_lifetime() {
        fn get_static_ref() -> &'static mut OsStr {
            create_persistent_os_string("persistent")
        }

        let static_ref = get_static_ref();
        assert_eq!(static_ref, OsStr::new("persistent"));
    }

    #[test]
    fn test_create_persistent_os_string_multiple_allocations() {
        let strings = [
            "first",
            "second",
            "third",
            "fourth",
            "fifth",
        ];

        let mut leaked_refs: Vec<&mut OsStr> = Vec::new();

        for s in &strings {
            let leaked = create_persistent_os_string(s);
            leaked_refs.push(leaked);
        }

        // Verify all allocations are independent and correct
        for (i, leaked) in leaked_refs.iter().enumerate() {
            assert_eq!(*leaked, OsStr::new(strings[i]));
        }
    }

    #[test]
    fn test_create_persistent_os_string_ffi_compatibility() {
        // Simulate FFI usage pattern
        let c_compatible = "null_terminated_string\0";
        let leaked = create_persistent_os_string(c_compatible.trim_end_matches('\0'));

        // Verify it can be used where C expects a persistent string
        let ptr = leaked as *const OsStr as *const std::os::raw::c_char;
        unsafe {
            // Just checking we can get the pointer, not actually calling C code
            assert!(!ptr.is_null());
        }
    }

    #[test]
    fn test_create_persistent_os_string_unicode() {
        let unicode_strings = [
            "😀😃😄😁😆",
            "αβγδε",
            "🚀🚁🚂🚃🚄",
            "∀∃∈∉∧∨",
        ];

        for s in &unicode_strings {
            let leaked = create_persistent_os_string(s);
            assert_eq!(leaked, OsStr::new(s));

            // Verify length in bytes (not chars)
            let os_string = leaked.to_os_string();
            assert_eq!(os_string.len(), s.len());
        }
    }

    #[test]
    fn test_create_persistent_os_string_large_input() {
        let large_string = "x".repeat(1024 * 1024); // 1MB string
        let leaked = create_persistent_os_string(&large_string);

        assert_eq!(leaked.len(), large_string.len());
        assert_eq!(leaked, OsStr::new(&large_string));
    }

    #[test]
    fn test_create_persistent_os_string_from_os_str() {
        // Test that we can convert back and forth
        let original = OsStr::new("original osstr");
        let leaked = create_persistent_os_string(&original.to_string_lossy());

        assert_eq!(leaked, original);

        // Convert leaked back to OsString
        let converted_back = leaked.to_os_string();
        assert_eq!(converted_back, OsString::from(original));
    }
}

