    fn connected_pair() -> std::io::Result<(TcpStream, TcpStream)> {
        let listener = TcpListener::bind("127.0.0.1:0")?;
        let addr = listener.local_addr()?;
        let client = TcpStream::connect(addr)?;
        let (server, _) = listener.accept()?;
        Ok((client, server))
    }

    #[test]
    fn test_quickack_default_state() -> std::io::Result<()> {
        let (client, _server) = connected_pair()?;
        let result = has_immediate_ack_enabled(&client);
        assert!(result.is_ok());
        Ok(())
    }

    #[test]
    fn test_quickack_enabled() -> std::io::Result<()> {
        let (client, _server) = connected_pair()?;
        client.set_quickack(true)?;
        let enabled = has_immediate_ack_enabled(&client)?;
        assert!(enabled);
        Ok(())
    }

    #[test]
    fn test_quickack_disabled() -> std::io::Result<()> {
        let (client, _server) = connected_pair()?;
        client.set_quickack(false)?;
        let enabled = has_immediate_ack_enabled(&client)?;
        assert!(!enabled);
        Ok(())
    }

    #[test]
    fn test_quickack_toggle() -> std::io::Result<()> {
        let (client, _server) = connected_pair()?;
        client.set_quickack(true)?;
        assert!(has_immediate_ack_enabled(&client)?);
        client.set_quickack(false)?;
        assert!(!has_immediate_ack_enabled(&client)?);
        Ok(())
    }
}

