use std::io::{Read, Seek, SeekFrom};

fn read_stream_segment(
    mut stream: impl Read + Seek,
    offset: u64,
    max_bytes: u64,
) -> std::io::Result<Vec<u8>> {
    // Seek to the desired offset from the start of the stream
    stream.seek(SeekFrom::Start(offset))?;

    // Create a Take wrapper to limit reading to max_bytes
    let mut limited_stream = stream.take(max_bytes);

    // Read the limited segment into a buffer
    let mut buffer = Vec::new();
    limited_stream.read_to_end(&mut buffer)?;

    Ok(buffer)
}

