#[cfg(test)]
mod tests {
    use std::alloc::{alloc, dealloc, Layout};
    use super::allocate_aligned_memory;

    #[test]
    fn test_allocate_aligned_memory_basic() {
        unsafe {
            let layout = Layout::new::<u64>();
            let ptr = allocate_aligned_memory(layout);
            assert!(!ptr.is_null(), "Allocation should return non-null pointer");

            // Write and read back to verify memory is usable
            *ptr = 42u8;
            assert_eq!(*ptr, 42u8);

            dealloc(ptr, layout);
        }
    }

    #[test]
    fn test_allocate_aligned_memory_with_alignment() {
        unsafe {
            // Test with various alignments
            let alignments = [1, 2, 4, 8, 16, 32, 64, 128];

            for &alignment in &alignments {
                let layout = Layout::from_size_align(64, alignment).unwrap();
                let ptr = allocate_aligned_memory(layout);

                assert!(!ptr.is_null(), "Allocation should succeed for alignment {}", alignment);

                // Verify alignment
                let addr = ptr as usize;
                assert_eq!(addr % alignment, 0, "Pointer should be aligned to {}", alignment);

                dealloc(ptr, layout);
            }
        }
    }

    #[test]
    fn test_allocate_aligned_memory_zero_sized() {
        unsafe {
            let layout = Layout::new::<()>();
            let ptr = allocate_aligned_memory(layout);

            // Zero-sized allocations should return a dangling pointer
            // but not necessarily null
            assert!(ptr as usize % layout.align() == 0, 
                   "Zero-sized allocation should respect alignment");

            dealloc(ptr, layout);
        }
    }

    #[test]
    fn test_allocate_aligned_memory_large_allocation() {
        unsafe {
            // Test with a reasonably large allocation
            let layout = Layout::from_size_align(1024 * 1024, 8).unwrap(); // 1MB
            let ptr = allocate_aligned_memory(layout);

            assert!(!ptr.is_null(), "Large allocation should succeed");

            // Write to all bytes to ensure memory is accessible
            for i in 0..1024 {
                *ptr.add(i) = (i % 256) as u8;
            }

            // Verify written values
            for i in 0..1024 {
                assert_eq!(*ptr.add(i), (i % 256) as u8);
            }

            dealloc(ptr, layout);
        }
    }

    #[test]
    fn test_allocate_aligned_memory_multiple_allocations() {
        unsafe {
            let mut pointers = Vec::new();
            let layouts = [
                Layout::new::<i32>(),
                Layout::new::<f64>(),
                Layout::from_size_align(256, 16).unwrap(),
                Layout::from_size_align(512, 32).unwrap(),
            ];

            for layout in layouts.iter() {
                let ptr = allocate_aligned_memory(*layout);
                assert!(!ptr.is_null(), "Allocation should succeed");
                pointers.push((ptr, *layout));
            }

            // Write different values to each allocation
            for (i, &(ptr, layout)) in pointers.iter().enumerate() {
                if layout.size() > 0 {
                    *ptr = (i % 256) as u8;
                }
            }

            // Verify values are independent
            for (i, &(ptr, layout)) in pointers.iter().enumerate() {
                if layout.size() > 0 {
                    assert_eq!(*ptr, (i % 256) as u8);
                }
            }

            // Clean up
            for (ptr, layout) in pointers {
                dealloc(ptr, layout);
            }
        }
    }

    #[test]
    fn test_allocate_aligned_memory_with_max_alignment() {
        unsafe {
            // Test with page alignment (typically 4096 bytes)
            let page_size = 4096;
            let layout = Layout::from_size_align(page_size, page_size).unwrap();
            let ptr = allocate_aligned_memory(layout);

            assert!(!ptr.is_null(), "Page-aligned allocation should succeed");
            assert_eq!(ptr as usize % page_size, 0, "Should be page-aligned");

            dealloc(ptr, layout);
        }
    }

    #[test]
    fn test_allocate_aligned_memory_struct_layout() {
        #[repr(C, align(64))]
        struct AlignedStruct {
            data: [u8; 128],
        }

        unsafe {
            let layout = Layout::new::<AlignedStruct>();
            let ptr = allocate_aligned_memory(layout);

            assert!(!ptr.is_null(), "Struct allocation should succeed");
            assert_eq!(ptr as usize % 64, 0, "Should respect struct alignment");

            // Cast to struct pointer and access fields
            let struct_ptr = ptr as *mut AlignedStruct;
            (*struct_ptr).data[0] = 100;
            assert_eq!((*struct_ptr).data[0], 100);

            dealloc(ptr, layout);
        }
    }

    #[test]
    fn test_allocate_aligned_memory_edge_cases() {
        unsafe {
            // Test minimum valid alignment (1 byte)
            let layout = Layout::from_size_align(1, 1).unwrap();
            let ptr = allocate_aligned_memory(layout);
            assert!(!ptr.is_null());
            dealloc(ptr, layout);

            // Test with size that's not a power of two
            let layout = Layout::from_size_align(100, 8).unwrap();
            let ptr = allocate_aligned_memory(layout);
            assert!(!ptr.is_null());
            dealloc(ptr, layout);
        }
    }

    #[test]
    fn test_allocate_aligned_memory_compare_with_std_alloc() {
        unsafe {
            let layout = Layout::from_size_align(256, 16).unwrap();

            // Test our function
            let our_ptr = allocate_aligned_memory(layout);
            assert!(!our_ptr.is_null());

            // Test standard alloc for comparison
            let std_ptr = alloc(layout);
            assert!(!std_ptr.is_null());

            // Both should have correct alignment
            assert_eq!(our_ptr as usize % 16, 0);
            assert_eq!(std_ptr as usize % 16, 0);

            dealloc(our_ptr, layout);
            dealloc(std_ptr, layout);
        }
    }
}

