use std::sync::atomic::{fence, Ordering};

pub fn synchronize_threads_with_fence(
    writer_data: &mut [u32],
    reader_data: &mut [u32],
    signal: &std::sync::atomic::AtomicBool,
) -> Result<(), &'static str> {
    if writer_data.len() != reader_data.len() {
        return Err("Buffers must have equal length");
    }

    // Writer thread: write data, then signal with release fence
    for (i, val) in writer_data.iter_mut().enumerate() {
        *val = i as u32;
    }
    fence(Ordering::Release);
    signal.store(true, Ordering::Relaxed);

    // Reader thread: wait for signal, then acquire fence before reading
    while !signal.load(Ordering::Relaxed) {
        std::hint::spin_loop();
    }
    fence(Ordering::Acquire);
    for (i, val) in reader_data.iter_mut().enumerate() {
        *val = writer_data[i];
    }

    Ok(())
}

