#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::AtomicBool;
    use std::sync::Arc;
    use std::thread;

    #[test]
    fn test_synchronize_threads_with_fence_basic() {
        let mut writer_data = vec![0u32; 10];
        let mut reader_data = vec![0u32; 10];
        let signal = AtomicBool::new(false);

        let result = synchronize_threads_with_fence(
            &mut writer_data,
            &mut reader_data,
            &signal,
        );

        assert!(result.is_ok());
        assert_eq!(writer_data, reader_data);
        assert!(signal.load(std::sync::atomic::Ordering::Relaxed));
    }

    #[test]
    fn test_synchronize_threads_with_fence_different_lengths() {
        let mut writer_data = vec![0u32; 5];
        let mut reader_data = vec![0u32; 10];
        let signal = AtomicBool::new(false);

        let result = synchronize_threads_with_fence(
            &mut writer_data,
            &mut reader_data,
            &signal,
        );

        assert!(result.is_err());
        assert_eq!(result.err().unwrap(), "Buffers must have equal length");
    }

    #[test]
    fn test_synchronize_threads_with_fence_empty_buffers() {
        let mut writer_data: Vec<u32> = vec![];
        let mut reader_data: Vec<u32> = vec![];
        let signal = AtomicBool::new(false);

        let result = synchronize_threads_with_fence(
            &mut writer_data,
            &mut reader_data,
            &signal,
        );

        assert!(result.is_ok());
        assert!(signal.load(std::sync::atomic::Ordering::Relaxed));
    }

    #[test]
    fn test_synchronize_threads_with_fence_concurrent() {
        const BUFFER_SIZE: usize = 1000;

        let writer_data = Arc::new(vec![0u32; BUFFER_SIZE]);
        let reader_data = Arc::new(vec![0u32; BUFFER_SIZE]);
        let signal = Arc::new(AtomicBool::new(false));

        let writer_data_clone = Arc::clone(&writer_data);
        let reader_data_clone = Arc::clone(&reader_data);
        let signal_clone = Arc::clone(&signal);

        let writer_handle = thread::spawn(move || {
            let mut writer_data_local = writer_data_clone.as_ref().clone();
            let mut reader_data_local = reader_data_clone.as_ref().clone();

            synchronize_threads_with_fence(
                &mut writer_data_local,
                &mut reader_data_local,
                &signal_clone,
            ).unwrap();

            (writer_data_local, reader_data_local)
        });

        let (writer_result, reader_result) = writer_handle.join().unwrap();

        // Verify the writer wrote correct values
        for (i, &val) in writer_result.iter().enumerate() {
            assert_eq!(val, i as u32);
        }

        // Verify the reader read the same values
        assert_eq!(writer_result, reader_result);
        assert!(signal.load(std::sync::atomic::Ordering::Relaxed));
    }

    #[test]
    fn test_synchronize_threads_with_fence_memory_ordering() {
        // This test verifies that the fences establish proper happens-before relationship
        let mut writer_data = vec![0u32; 100];
        let mut reader_data = vec![0u32; 100];
        let signal = AtomicBool::new(false);

        // Store initial values
        for val in writer_data.iter_mut() {
            *val = 999;
        }
        for val in reader_data.iter_mut() {
            *val = 888;
        }

        let result = synchronize_threads_with_fence(
            &mut writer_data,
            &mut reader_data,
            &signal,
        );

        assert!(result.is_ok());

        // Verify all values were properly synchronized
        for (i, (&w_val, &r_val)) in writer_data.iter().zip(reader_data.iter()).enumerate() {
            assert_eq!(w_val, i as u32);
            assert_eq!(r_val, i as u32);
        }
    }

    #[test]
    fn test_synchronize_threads_with_fence_already_signaled() {
        let mut writer_data = vec![0u32; 5];
        let mut reader_data = vec![0u32; 5];
        let signal = AtomicBool::new(true);

        let result = synchronize_threads_with_fence(
            &mut writer_data,
            &mut reader_data,
            &signal,
        );

        assert!(result.is_ok());

        // Reader should still read the data even though signal was already true
        for (i, &val) in reader_data.iter().enumerate() {
            assert_eq!(val, i as u32);
        }
    }

    #[test]
    fn test_synchronize_threads_with_fence_large_buffer() {
        const LARGE_SIZE: usize = 1_000_000;
        let mut writer_data = vec![0u32; LARGE_SIZE];
        let mut reader_data = vec![0u32; LARGE_SIZE];
        let signal = AtomicBool::new(false);

        let result = synchronize_threads_with_fence(
            &mut writer_data,
            &mut reader_data,
            &signal,
        );

        assert!(result.is_ok());

        // Spot check some values
        assert_eq!(writer_data[0], 0);
        assert_eq!(writer_data[LARGE_SIZE / 2], (LARGE_SIZE / 2) as u32);
        assert_eq!(writer_data[LARGE_SIZE - 1], (LARGE_SIZE - 1) as u32);

        assert_eq!(reader_data[0], 0);
        assert_eq!(reader_data[LARGE_SIZE / 2], (LARGE_SIZE / 2) as u32);
        assert_eq!(reader_data[LARGE_SIZE - 1], (LARGE_SIZE - 1) as u32);

        assert!(signal.load(std::sync::atomic::Ordering::Relaxed));
    }
}

