use std::sync::atomic::{AtomicBool, Ordering};

fn try_raise_flag_once(flag: &AtomicBool) -> bool {
    loop {
        let current = flag.load(Ordering::Relaxed);
        if current {
            return false;
        }
        match flag.compare_exchange_weak(
            false,
            true,
            Ordering::Acquire,
            Ordering::Relaxed,
        ) {
            Ok(_) => return true,
            Err(_) => continue,
        }
    }
}

