#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::Arc;
    use std::thread;
    use std::time::Duration;

    #[test]
    fn test_flag_starts_false() {
        let flag = AtomicBool::new(false);
        assert!(try_raise_flag_once(&flag));
        assert!(flag.load(Ordering::Relaxed));
    }

    #[test]
    fn test_flag_already_true() {
        let flag = AtomicBool::new(true);
        assert!(!try_raise_flag_once(&flag));
        assert!(flag.load(Ordering::Relaxed));
    }

    #[test]
    fn test_multiple_calls_sequential() {
        let flag = AtomicBool::new(false);

        // First call should succeed
        assert!(try_raise_flag_once(&flag));
        assert!(flag.load(Ordering::Relaxed));

        // Subsequent calls should fail
        assert!(!try_raise_flag_once(&flag));
        assert!(!try_raise_flag_once(&flag));
        assert!(!try_raise_flag_once(&flag));
        assert!(flag.load(Ordering::Relaxed));
    }

    #[test]
    fn test_concurrent_single_success() {
        let flag = Arc::new(AtomicBool::new(false));
        let mut handles = vec![];
        let success_count = Arc::new(std::sync::atomic::AtomicUsize::new(0));

        // Spawn multiple threads trying to raise the flag
        for _ in 0..10 {
            let flag_clone = Arc::clone(&flag);
            let success_clone = Arc::clone(&success_count);
            let handle = thread::spawn(move || {
                let result = try_raise_flag_once(&flag_clone);
                if result {
                    success_clone.fetch_add(1, Ordering::Relaxed);
                }
            });
            handles.push(handle);
        }

        // Wait for all threads
        for handle in handles {
            handle.join().unwrap();
        }

        // Exactly one thread should have succeeded
        assert_eq!(success_count.load(Ordering::Relaxed), 1);
        assert!(flag.load(Ordering::Relaxed));
    }

    #[test]
    fn test_concurrent_already_true() {
        let flag = Arc::new(AtomicBool::new(true));
        let mut handles = vec![];
        let success_count = Arc::new(std::sync::atomic::AtomicUsize::new(0));

        // Spawn multiple threads trying to raise an already-raised flag
        for _ in 0..10 {
            let flag_clone = Arc::clone(&flag);
            let success_clone = Arc::clone(&success_count);
            let handle = thread::spawn(move || {
                let result = try_raise_flag_once(&flag_clone);
                if result {
                    success_clone.fetch_add(1, Ordering::Relaxed);
                }
            });
            handles.push(handle);
        }

        // Wait for all threads
        for handle in handles {
            handle.join().unwrap();
        }

        // No threads should have succeeded
        assert_eq!(success_count.load(Ordering::Relaxed), 0);
        assert!(flag.load(Ordering::Relaxed));
    }

    #[test]
    fn test_spurious_failure_recovery() {
        let flag = AtomicBool::new(false);

        // This test ensures the loop handles spurious failures correctly
        // We can't force spurious failures, but we can verify the loop logic
        // by calling the function multiple times sequentially
        let mut success_seen = false;
        for _ in 0..100 {
            if try_raise_flag_once(&flag) {
                success_seen = true;
                break;
            }
        }

        assert!(success_seen);
        assert!(flag.load(Ordering::Relaxed));
    }

    #[test]
    fn test_memory_ordering() {
        let flag = AtomicBool::new(false);
        let data = Arc::new(std::sync::atomic::AtomicUsize::new(0));

        // Test that Acquire ordering works correctly
        let flag_clone = Arc::clone(&data);
        let handle = thread::spawn(move || {
            // Write some data
            flag_clone.store(42, Ordering::Release);
            // Then raise the flag
        });

        // In another thread, try to raise the flag and read the data
        if try_raise_flag_once(&flag) {
            // With Acquire ordering, we should see the data written before the flag was set
            // This is a basic sanity check for ordering
            assert!(flag.load(Ordering::Acquire));
        }

        handle.join().unwrap();
    }

    #[test]
    fn test_stress_concurrent() {
        const NUM_THREADS: usize = 20;
        const ATTEMPTS_PER_THREAD: usize = 1000;

        for _ in 0..10 {
            let flag = Arc::new(AtomicBool::new(false));
            let success_count = Arc::new(std::sync::atomic::AtomicUsize::new(0));
            let mut handles = vec![];

            for _ in 0..NUM_THREADS {
                let flag_clone = Arc::clone(&flag);
                let success_clone = Arc::clone(&success_count);
                let handle = thread::spawn(move || {
                    for _ in 0..ATTEMPTS_PER_THREAD {
                        if try_raise_flag_once(&flag_clone) {
                            success_clone.fetch_add(1, Ordering::Relaxed);
                        }
                    }
                });
                handles.push(handle);
            }

            for handle in handles {
                handle.join().unwrap();
            }

            // Exactly one thread should have succeeded in raising the flag
            assert_eq!(success_count.load(Ordering::Relaxed), 1);
            assert!(flag.load(Ordering::Relaxed));
        }
    }

    #[test]
    fn test_return_values() {
        // Test that return values are correct in all scenarios
        let flag1 = AtomicBool::new(false);
        assert_eq!(try_raise_flag_once(&flag1), true);
        assert_eq!(try_raise_flag_once(&flag1), false);

        let flag2 = AtomicBool::new(true);
        assert_eq!(try_raise_flag_once(&flag2), false);

        let flag3 = AtomicBool::new(false);
        let flag4 = AtomicBool::new(false);
        assert_eq!(try_raise_flag_once(&flag3), true);
        assert_eq!(try_raise_flag_once(&flag4), true);
        assert_eq!(try_raise_flag_once(&flag3), false);
        assert_eq!(try_raise_flag_once(&flag4), false);
    }
}

