use std::collections::VecDeque;

#[derive(Debug, Clone)]
struct DataPacket {
    // Define fields as needed
}

#[derive(Debug)]
enum StreamError {
    // Define error variants as needed
    ProcessingError,
}

fn process_data_stream(buffer: &mut VecDeque<DataPacket>, incoming: &[DataPacket]) -> Result<(), StreamError> {
    // Pre-reserve capacity to minimize reallocations during bursts
    buffer.reserve(incoming.len());

    // Append all incoming items with minimal overhead
    for packet in incoming {
        buffer.push_back(packet.clone());
    }

    Ok(())
}

