    fn test_process_data_stream_capacity_management() {
        #[derive(Debug, Clone)]
        struct TestDataPacket {
            id: i32,
        }

        let mut buffer: VecDeque<TestDataPacket> = VecDeque::with_capacity(5);

        // Fill buffer to capacity
        for i in 0..5 {
            buffer.push_back(TestDataPacket { id: i });
        }

        let initial_capacity = buffer.capacity();
        let incoming = vec![
            TestDataPacket { id: 5 },
            TestDataPacket { id: 6 },
        ];

        fn process_test_stream(buffer: &mut VecDeque<TestDataPacket>, incoming: &[TestDataPacket]) -> Result<(), StreamError> {
