    }

    #[test]
    fn test_process_data_stream_clone_semantics() {
        #[derive(Debug, Clone, PartialEq)]
        struct TestDataPacket {
            id: i32,
            data: Vec<i32>,
        }

        let mut buffer: VecDeque<TestDataPacket> = VecDeque::new();

        let original_packet = TestDataPacket { 
            id: 1, 
            data: vec![1, 2, 3],
        };

        let incoming = vec![original_packet.clone()];

        fn process_test_stream(buffer: &mut VecDeque<TestDataPacket>, incoming: &[TestDataPacket]) -> Result<(), StreamError> {
            buffer.reserve(incoming.len());
            for packet in incoming {
                buffer.push_back(packet.clone());
            }
            Ok(())
        }

        let result = process_test_stream(&mut buffer, &incoming);

        assert!(result.is_ok());
        assert_eq!(buffer.len(), 1);

        // Verify it's a clone, not the same reference
        let buffer_packet = &buffer[0];
        assert_eq!(buffer_packet.id, original_packet.id);
        assert_eq!(buffer_packet.data, original_packet.data);
    }

    #[test]
    fn test_process_data_stream_no_side_effects_on_incoming() {
        #[derive(Debug, Clone)]
        struct TestDataPacket {
            id: i32,
        }

        let mut buffer: VecDeque<TestDataPacket> = VecDeque::new();

        let incoming = vec![
            TestDataPacket { id: 1 },
            TestDataPacket { id: 2 },
        ];

        let incoming_len = incoming.len();

        fn process_test_stream(buffer: &mut VecDeque<TestDataPacket>, incoming: &[TestDataPacket]) -> Result<(), StreamError> {
            buffer.reserve(incoming.len());
            for packet in incoming {
                buffer.push_back(packet.clone());
            }
            Ok(())
        }

        let result = process_test_stream(&mut buffer, &incoming);

        assert!(result.is_ok());

        // Verify incoming slice is unchanged
        assert_eq!(incoming.len(), incoming_len);
        assert_eq!(incoming[0].id, 1);
        assert_eq!(incoming[1].id, 2);
    }

    // Test with different buffer states
    #[test]
    fn test_process_data_stream_full_circle_buffer() {
        #[derive(Debug, Clone)]
        struct TestDataPacket {
            id: i32,
        }

        let mut buffer: VecDeque<TestDataPacket> = VecDeque::with_capacity(3);

        // Make it a true circular buffer by removing from front
        buffer.push_back(TestDataPacket { id: 1 });
        buffer.push_back(TestDataPacket { id: 2 });
        buffer.push_back(TestDataPacket { id: 3 });

        // Remove one to make space
        buffer.pop_front();

        let incoming = vec![
            TestDataPacket { id: 4 },
        ];

        fn process_test_stream(buffer: &mut VecDeque<TestDataPacket>, incoming: &[TestDataPacket]) -> Result<(), StreamError> {
            buffer.reserve(incoming.len());
            for packet in incoming {
                buffer.push_back(packet.clone());
            }
            Ok(())
        }

        let result = process_test_stream(&mut buffer, &incoming);

        assert!(result.is_ok());
        assert_eq!(buffer.len(), 3);

        let ids: Vec<i32> = buffer.iter().map(|p| p.id).collect();
        assert_eq!(ids, vec![2, 3, 4]);
    }
}

