    fn test_empty_c_string() {
        // Test with empty string (just null terminator)
        let cstr = CString::new("").unwrap();
        let result = debug_c_string(&cstr);

        // Should show empty string representation
        assert!(result.contains("\"\""));
    }

    #[test]
    fn test_c_string_with_null_bytes_in_middle() {
        // Test string with embedded null bytes (invalid for CString but valid in raw bytes)
        let bytes = b"Hello\0World\0";
        let cstr = unsafe { CStr::from_bytes_with_nul_unchecked(b"Hello\0World\0\0") };
        let result = debug_c_string(&cstr);

        // Should handle embedded nulls in debug output
        assert!(!result.is_empty());
        assert!(result.contains("Hello"));
        assert!(result.contains("World"));
    }

    #[test]
    fn test_non_utf8_c_string() {
        // Test with invalid UTF-8 bytes
        let invalid_bytes = &[0xFF, 0xFE, 0x00]; // Invalid UTF-8 sequence followed by null
        let cstr = unsafe { CStr::from_bytes_with_nul_unchecked(invalid_bytes) };
        let result = debug_c_string(&cstr);

        // Should not panic and produce some debug output
        assert!(!result.is_empty());
        assert!(result.contains("ff")); // Should show hex representation
        assert!(result.contains("fe"));
    }

    #[test]
    fn test_c_string_with_special_characters() {
        // Test with various special characters
        let test_str = "Line1\nLine2\tTab\x1B[31mRed\x1B[0m";
        let cstr = CString::new(test_str).unwrap();
        let result = debug_c_string(&cstr);

        // Should handle escape sequences in debug output
        assert!(result.contains("Line1"));
        assert!(result.contains("Line2"));
        assert!(result.contains("Tab"));
    }

    #[test]
    fn test_c_string_from_raw_pointer() {
        // Test creating CStr from raw pointer
        let bytes = b"Test\0";
        let ptr = bytes.as_ptr() as *const c_char;
        let cstr = unsafe { CStr::from_ptr(ptr) };
        let result = debug_c_string(&cstr);

        assert!(result.contains("Test"));
    }

