#[cfg(test)]
mod tests {
    use std::num::NonZeroU8;

    use super::validate_nonzero_pair;

    #[test]
    fn test_validate_nonzero_pair_equal_values() {
        let a = NonZeroU8::new(1).unwrap();
        let b = NonZeroU8::new(1).unwrap();
        assert!(validate_nonzero_pair(a, b));
    }

    #[test]
    fn test_validate_nonzero_pair_different_values() {
        let a = NonZeroU8::new(5).unwrap();
        let b = NonZeroU8::new(10).unwrap();
        assert!(!validate_nonzero_pair(a, b));
    }

    #[test]
    fn test_validate_nonzero_pair_min_max_values() {
        let min = NonZeroU8::new(1).unwrap();
        let max = NonZeroU8::new(255).unwrap();

        assert!(validate_nonzero_pair(min, min));
        assert!(validate_nonzero_pair(max, max));
        assert!(!validate_nonzero_pair(min, max));
    }

    #[test]
    fn test_validate_nonzero_pair_mid_range_values() {
        let val1 = NonZeroU8::new(42).unwrap();
        let val2 = NonZeroU8::new(100).unwrap();

        assert!(validate_nonzero_pair(val1, val1));
        assert!(validate_nonzero_pair(val2, val2));
        assert!(!validate_nonzero_pair(val1, val2));
    }

    #[test]
    fn test_validate_nonzero_pair_commutative_property() {
        let a = NonZeroU8::new(7).unwrap();
        let b = NonZeroU8::new(7).unwrap();
        let c = NonZeroU8::new(8).unwrap();

        // Equality is commutative
        assert!(validate_nonzero_pair(a, b));
        assert!(validate_nonzero_pair(b, a));

        // Inequality is also commutative
        assert!(!validate_nonzero_pair(a, c));
        assert!(!validate_nonzero_pair(c, a));
    }

    #[test]
    fn test_validate_nonzero_pair_reflexive_property() {
        let values = [
            NonZeroU8::new(1).unwrap(),
            NonZeroU8::new(50).unwrap(),
            NonZeroU8::new(100).unwrap(),
            NonZeroU8::new(200).unwrap(),
            NonZeroU8::new(255).unwrap(),
        ];

        for &val in &values {
            assert!(validate_nonzero_pair(val, val), "Value should equal itself: {}", val);
        }
    }

    #[test]
    fn test_validate_nonzero_pair_transitive_property() {
        let a = NonZeroU8::new(3).unwrap();
        let b = NonZeroU8::new(3).unwrap();
        let c = NonZeroU8::new(3).unwrap();
        let d = NonZeroU8::new(4).unwrap();

        // If a == b and b == c, then a == c
        assert!(validate_nonzero_pair(a, b));
        assert!(validate_nonzero_pair(b, c));
        assert!(validate_nonzero_pair(a, c));

        // If a != d and b != d, then a != d (trivially true)
        assert!(!validate_nonzero_pair(a, d));
        assert!(!validate_nonzero_pair(b, d));
    }

    #[test]
    fn test_validate_nonzero_pair_edge_cases() {
        // Test consecutive values
        let val1 = NonZeroU8::new(1).unwrap();
        let val2 = NonZeroU8::new(2).unwrap();
        assert!(!validate_nonzero_pair(val1, val2));

        // Test values near max
        let val254 = NonZeroU8::new(254).unwrap();
        let val255 = NonZeroU8::new(255).unwrap();
        assert!(!validate_nonzero_pair(val254, val255));
    }

    #[test]
    fn test_validate_nonzero_pair_const_context() {
        // Demonstrate the function works in const context
        const A: NonZeroU8 = unsafe { NonZeroU8::new_unchecked(10) };
        const B: NonZeroU8 = unsafe { NonZeroU8::new_unchecked(10) };
        const C: NonZeroU8 = unsafe { NonZeroU8::new_unchecked(20) };

        // Note: We can't directly test const results in runtime tests,
        // but we can verify the same values work at runtime
        assert!(validate_nonzero_pair(A, B));
        assert!(!validate_nonzero_pair(A, C));
    }

    #[test]
    fn test_validate_nonzero_pair_all_same_values() {
        // Test that identical NonZeroU8 instances compare equal
        let values = [1u8, 2, 5, 10, 20, 50, 100, 200, 255];

        for &value in &values {
            let a = NonZeroU8::new(value).unwrap();
            let b = NonZeroU8::new(value).unwrap();
            assert!(validate_nonzero_pair(a, b), "Failed for value: {}", value);
        }
    }

    #[test]
    fn test_validate_nonzero_pair_all_different_values() {
        // Test that different NonZeroU8 instances compare not equal
        let values = [(1, 2), (2, 3), (5, 10), (10, 20), (100, 200), (200, 255)];

        for &(val1, val2) in &values {
            let a = NonZeroU8::new(val1).unwrap();
            let b = NonZeroU8::new(val2).unwrap();
            assert!(!validate_nonzero_pair(a, b), 
                   "Values {} and {} should not be equal", val1, val2);
        }
    }
}

