use std::collections::VecDeque;
use std::time::{Duration, Instant};

fn benchmark_insert_throughput(
    initial_capacity: usize,
    max_capacity: usize,
    insert_positions: &[usize],
    values: &[i32],
) -> Result<(Duration, Duration), &'static str> {
    if initial_capacity > max_capacity {
        return Err("initial_capacity cannot exceed max_capacity");
    }
    if insert_positions.len() != values.len() {
        return Err("insert_positions and values must have same length");
    }
    if insert_positions.is_empty() {
        return Ok((Duration::ZERO, Duration::ZERO));
    }

    // Benchmark before optimization simulation: shrink and re-extend on overflow.
    let mut deque_before = VecDeque::with_capacity(max_capacity);
    for _ in 0..initial_capacity {
        deque_before.push_back(0);
    }

    let start_before = Instant::now();
    for (&pos, &val) in insert_positions.iter().zip(values.iter()) {
        if pos > deque_before.len() {
            return Err("insert position out of bounds");
        }
        deque_before.insert(pos, val);
        if deque_before.len() > max_capacity {
            let _ = deque_before.pop_front();
        }
    }
    let duration_before = start_before.elapsed();

    // Benchmark after optimization simulation: overwrite ends to avoid extra moves.
    let mut deque_after = VecDeque::with_capacity(max_capacity);
    for _ in 0..initial_capacity {
        deque_after.push_back(0);
    }

    let start_after = Instant::now();
    for (&pos, &val) in insert_positions.iter().zip(values.iter()) {
        if pos > deque_after.len() {
            return Err("insert position out of bounds");
        }
        if deque_after.len() == max_capacity {
            if pos == 0 {
                let _ = deque_after.pop_front();
            } else if pos == deque_after.len() {
                let _ = deque_after.pop_back();
            }
        }
        deque_after.insert(pos.min(deque_after.len()), val);
        if deque_after.len() > max_capacity {
            let _ = deque_after.pop_front();
        }
    }
    let duration_after = start_after.elapsed();

    Ok((duration_before, duration_after))
}

