fn read_from_c_api(buffer_capacity: usize) -> Option<Vec<u8>> {
    let mut buffer = Vec::with_capacity(buffer_capacity);

    unsafe {
        let bytes_written = (C_API_READ)(buffer.as_mut_ptr(), buffer_capacity);
        if bytes_written <= buffer_capacity {
            buffer.set_len(bytes_written);
            Some(buffer)
        } else {
            None
        }
    }
}

