#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_range_returns_some() {
        let mut s = String::from("Hello, World!");
        let range = 7..12;
        let result = extract_and_mutate_substring(s.as_mut_str(), range.clone());

        assert!(result.is_some());
        let substring = result.unwrap();
        assert_eq!(substring, "World");

        // Verify we can mutate the substring
        substring.make_ascii_lowercase();
        assert_eq!(s, "Hello, world!");
    }

    #[test]
    fn test_empty_range_returns_empty_string() {
        let mut s = String::from("test");
        let range = 2..2;
        let result = extract_and_mutate_substring(s.as_mut_str(), range);

        assert!(result.is_some());
        let substring = result.unwrap();
        assert_eq!(substring, "");

        // Empty string mutation should not affect original
        substring.make_ascii_uppercase();
        assert_eq!(s, "test");
    }

    #[test]
    fn test_full_range_returns_entire_string() {
        let mut s = String::from("Rust");
        let range = 0..4;
        let result = extract_and_mutate_substring(s.as_mut_str(), range.clone());

        assert!(result.is_some());
        let substring = result.unwrap();
        assert_eq!(substring, "Rust");

        // Mutate entire string
        substring.make_ascii_uppercase();
        assert_eq!(s, "RUST");
    }

    #[test]
    fn test_range_start_out_of_bounds_returns_none() {
        let mut s = String::from("test");
        let range = 5..7;
        let result = extract_and_mutate_substring(s.as_mut_str(), range);
        assert!(result.is_none());
    }

    #[test]
    fn test_range_end_out_of_bounds_returns_none() {
        let mut s = String::from("test");
        let range = 2..10;
        let result = extract_and_mutate_substring(s.as_mut_str(), range);
        assert!(result.is_none());
    }

    #[test]
    fn test_range_start_greater_than_end_returns_none() {
        let mut s = String::from("test");
        let range = 3..1;
        let result = extract_and_mutate_substring(s.as_mut_str(), range);
        assert!(result.is_none());
    }

    #[test]
    fn test_unicode_char_boundaries() {
        let mut s = String::from("café");
        // 'é' is 2 bytes in UTF-8
        let range = 3..5; // Should extract 'é'
        let result = extract_and_mutate_substring(s.as_mut_str(), range.clone());

        assert!(result.is_some());
        let substring = result.unwrap();
        assert_eq!(substring, "é");

        // Test with range splitting a multi-byte character
        let range_invalid = 3..4; // Middle of 'é'
        let result = extract_and_mutate_substring(s.as_mut_str(), range_invalid);
        assert!(result.is_none());
    }

    #[test]
    fn test_empty_input_string() {
        let mut s = String::new();
        let range = 0..0;
        let result = extract_and_mutate_substring(s.as_mut_str(), range);

        assert!(result.is_some());
        let substring = result.unwrap();
        assert_eq!(substring, "");

        // Any non-zero range should return None
        let range_invalid = 0..1;
        let result = extract_and_mutate_substring(s.as_mut_str(), range_invalid);
        assert!(result.is_none());
    }

    #[test]
    fn test_mutation_preserves_other_parts() {
        let mut s = String::from("abcdefghij");
        let range = 3..7;
        let result = extract_and_mutate_substring(s.as_mut_str(), range.clone());

        assert!(result.is_some());
        let substring = result.unwrap();
        assert_eq!(substring, "defg");

        // Mutate only the substring - using bytes() to modify
        let bytes = unsafe { substring.as_bytes_mut() };
        bytes[0] = b'X';
        bytes[1] = b'X';
        bytes[2] = b'X';
        bytes[3] = b'X';
        assert_eq!(s, "abcXXXXhij");

        // Verify other parts unchanged
        assert_eq!(&s[0..3], "abc");
        assert_eq!(&s[7..10], "hij");
    }

    #[test]
    fn test_multiple_consecutive_mutations() {
        let mut s = String::from("1234567890");

        // First mutation
        let range1 = 0..3;
        let result1 = extract_and_mutate_substring(s.as_mut_str(), range1);
        assert!(result1.is_some());
        let mut substring1 = result1.unwrap();
        let bytes1 = unsafe { substring1.as_bytes_mut() };
        bytes1[0] = b'A';
        bytes1[1] = b'B';
        bytes1[2] = b'C';
        assert_eq!(s, "ABC4567890");

        // Second mutation on same string
        let range2 = 3..6;
        let result2 = extract_and_mutate_substring(s.as_mut_str(), range2);
        assert!(result2.is_some());
        let mut substring2 = result2.unwrap();
        let bytes2 = unsafe { substring2.as_bytes_mut() };
        bytes2[0] = b'D';
        bytes2[1] = b'E';
        bytes2[2] = b'F';
        assert_eq!(s, "ABCDEF7890");

        // Third mutation
        let range3 = 6..10;
        let result3 = extract_and_mutate_substring(s.as_mut_str(), range3);
        assert!(result3.is_some());
        let mut substring3 = result3.unwrap();
        let bytes3 = unsafe { substring3.as_bytes_mut() };
        bytes3[0] = b'G';
        bytes3[1] = b'H';
        bytes3[2] = b'I';
        bytes3[3] = b'J';
        assert_eq!(s, "ABCDEFGHIJ");
    }

    #[test]
    fn test_range_at_string_boundaries() {
        let mut s = String::from("boundary");

        // Start at 0
        let range_start = 0..3;
        let result_start = extract_and_mutate_substring(s.as_mut_str(), range_start);
        assert!(result_start.is_some());
        assert_eq!(result_start.unwrap(), "bou");

        // End at length
        let range_end = 5..8;
        let result_end = extract_and_mutate_substring(s.as_mut_str(), range_end);
        assert!(result_end.is_some());
        assert_eq!(result_end.unwrap(), "ary");
    }

    #[test]
    fn test_very_large_range() {
        let mut s = String::from("short");
        let range = 0..1000;
        let result = extract_and_mutate_substring(s.as_mut_str(), range);
        assert!(result.is_none());
    }
}

