#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_sum_within_bounds() {
        // Test basic addition within u16 bounds
        assert_eq!(sum_sensor_readings(0, 0), 0);
        assert_eq!(sum_sensor_readings(1, 2), 3);
        assert_eq!(sum_sensor_readings(100, 200), 300);
        assert_eq!(sum_sensor_readings(u16::MAX, 0), u16::MAX);
        assert_eq!(sum_sensor_readings(0, u16::MAX), u16::MAX);
    }

    #[test]
    fn test_sum_at_boundary() {
        // Test sums that equal exactly u16::MAX
        assert_eq!(sum_sensor_readings(u16::MAX - 1, 1), u16::MAX);
        assert_eq!(sum_sensor_readings(1, u16::MAX - 1), u16::MAX);
        assert_eq!(sum_sensor_readings(u16::MAX / 2, u16::MAX / 2), u16::MAX - 1);

        // When u16::MAX is odd, the halves sum to MAX-1
        let half1 = u16::MAX / 2;
        let half2 = u16::MAX - half1;
        assert_eq!(sum_sensor_readings(half1, half2), u16::MAX);
    }

    #[test]
    #[should_panic(expected = "attempt to add with overflow")]
    fn test_sum_overflow_panics_1() {
        // Test overflow cases that should panic
        sum_sensor_readings(u16::MAX, 1);
    }

    #[test]
    #[should_panic(expected = "attempt to add with overflow")]
    fn test_sum_overflow_panics_2() {
        sum_sensor_readings(1, u16::MAX);
    }

    #[test]
    #[should_panic(expected = "attempt to add with overflow")]
    fn test_sum_overflow_panics_3() {
        sum_sensor_readings(u16::MAX / 2 + 1, u16::MAX / 2 + 1);
    }

    #[test]
    #[should_panic(expected = "attempt to add with overflow")]
    fn test_sum_overflow_panics_large_values() {
        sum_sensor_readings(40000, 40000);
    }

    #[test]
    fn test_commutative_property() {
        // Verify addition is commutative for valid values
        let test_cases = [(100, 200), (1234, 5678), (0, 65535), (32767, 32767)];

        for &(a, b) in &test_cases {
            if a as u32 + b as u32 <= u16::MAX as u32 {
                assert_eq!(sum_sensor_readings(a, b), sum_sensor_readings(b, a));
            }
        }
    }

    #[test]
    fn test_associative_property_within_bounds() {
        // Test associative property for values that don't overflow
        let a = 10000;
        let b = 20000;
        let c = 10000;

        // (a + b) + c should equal a + (b + c) if both are within bounds
        let ab = sum_sensor_readings(a, b);
        let abc1 = sum_sensor_readings(ab, c);

        let bc = sum_sensor_readings(b, c);
        let abc2 = sum_sensor_readings(a, bc);

        assert_eq!(abc1, abc2);
    }

    #[test]
    fn test_identity_property() {
        // Test that adding zero returns the original value
        for &value in &[0, 1, 100, 1000, u16::MAX] {
            assert_eq!(sum_sensor_readings(value, 0), value);
            assert_eq!(sum_sensor_readings(0, value), value);
        }
    }

    #[test]
    fn test_edge_cases() {
        // Test various edge cases
        assert_eq!(sum_sensor_readings(1, u16::MAX - 1), u16::MAX);
        assert_eq!(sum_sensor_readings(u16::MAX - 100, 100), u16::MAX);

        // Test with values near the midpoint
        let mid = u16::MAX / 2;
        assert_eq!(sum_sensor_readings(mid, mid), u16::MAX - 1);
    }

    #[test]
    #[should_panic]
    fn test_both_max_values() {
        // Edge case: both values are at maximum
        sum_sensor_readings(u16::MAX, u16::MAX);
    }

    #[test]
    fn test_random_valid_pairs() {
        // Test random but deterministic valid pairs
        use std::num::Wrapping;

        // Use a simple deterministic pseudo-random sequence
        let mut seed: u32 = 42;
        for _ in 0..100 {
            seed = seed.wrapping_mul(1664525).wrapping_add(1013904223);
            let a = (seed >> 16) as u16;

            seed = seed.wrapping_mul(1664525).wrapping_add(1013904223);
            let b = (seed >> 16) as u16;

            // Only test if the sum doesn't overflow
            if (a as u32 + b as u32) <= u16::MAX as u32 {
                let expected = a.wrapping_add(b);
                assert_eq!(sum_sensor_readings(a, b), expected);
            }
        }
    }
}

