mod tests {
    use super::checked_neg_panicking;

    #[test]
    fn test_checked_neg_panicking_basic() {
        // Test basic negation cases
        assert_eq!(checked_neg_panicking(0), 0);
        assert_eq!(checked_neg_panicking(1), -1);
        assert_eq!(checked_neg_panicking(-1), 1);
        assert_eq!(checked_neg_panicking(42), -42);
        assert_eq!(checked_neg_panicking(-42), 42);
        assert_eq!(checked_neg_panicking(i32::MAX - 1), -(i32::MAX - 1));
        assert_eq!(checked_neg_panicking(i32::MIN + 1), -(i32::MIN + 1));
    }

    #[test]
    fn test_checked_neg_panicking_const_context() {
        // Verify the function works in const context
        const NEGATED_ZERO: i32 = checked_neg_panicking(0);
        const NEGATED_POSITIVE: i32 = checked_neg_panicking(100);
        const NEGATED_NEGATIVE: i32 = checked_neg_panicking(-100);

        assert_eq!(NEGATED_ZERO, 0);
        assert_eq!(NEGATED_POSITIVE, -100);
        assert_eq!(NEGATED_NEGATIVE, 100);
    }

    #[test]
    #[should_panic(expected = "overflow")]
    fn test_checked_neg_panicking_overflow_min() {
        // This should panic because -i32::MIN overflows
        checked_neg_panicking(i32::MIN);
    }

    #[test]
    fn test_checked_neg_panicking_edge_cases() {
        // Test edge cases that don't overflow
        assert_eq!(checked_neg_panicking(i32::MAX), -i32::MAX);

        // Test symmetry: negating twice should return original (except for i32::MIN)
        let test_values = [0, 1, -1, 42, -42, i32::MAX - 1, i32::MIN + 1];

        for &value in &test_values {
            let negated = checked_neg_panicking(value);
            let double_negated = checked_neg_panicking(negated);
            assert_eq!(double_negated, value, 
                "Failed for value {}: negated = {}, double_negated = {}", 
                value, negated, double_negated);
        }
    }

    #[test]
    fn test_checked_neg_panicking_property() {
        // Property test: For all x except i32::MIN, x + (-x) == 0
        let test_cases = [
            0i32, 1, -1, 2, -2, 100, -100, 
            i32::MAX - 1, i32::MIN + 1
        ];

        for &x in &test_cases {
            let neg_x = checked_neg_panicking(x);
            assert_eq!(x.wrapping_add(neg_x), 0,
                "Failed for x = {}: neg_x = {}, x + neg_x = {}", 
                x, neg_x, x.wrapping_add(neg_x));
        }
    }
}

