mod tests {
    use super::shift_color_channel;

    #[test]
    fn test_shift_color_channel_normal_shifts() {
        // Test shifting by 0 bits returns the same value
        assert_eq!(shift_color_channel(255, 0), 255);
        assert_eq!(shift_color_channel(128, 0), 128);
        assert_eq!(shift_color_channel(0, 0), 0);

        // Test shifting by 1 bit
        assert_eq!(shift_color_channel(255, 1), 127);
        assert_eq!(shift_color_channel(128, 1), 64);
        assert_eq!(shift_color_channel(64, 1), 32);
        assert_eq!(shift_color_channel(1, 1), 0);

        // Test shifting by 2 bits
        assert_eq!(shift_color_channel(255, 2), 63);
        assert_eq!(shift_color_channel(128, 2), 32);
        assert_eq!(shift_color_channel(64, 2), 16);
        assert_eq!(shift_color_channel(3, 2), 0);

        // Test shifting by 3 bits
        assert_eq!(shift_color_channel(255, 3), 31);
        assert_eq!(shift_color_channel(128, 3), 16);
        assert_eq!(shift_color_channel(64, 3), 8);

        // Test shifting by 4 bits
        assert_eq!(shift_color_channel(255, 4), 15);
        assert_eq!(shift_color_channel(128, 4), 8);
        assert_eq!(shift_color_channel(64, 4), 4);

        // Test shifting by 5 bits
        assert_eq!(shift_color_channel(255, 5), 7);
        assert_eq!(shift_color_channel(128, 5), 4);
        assert_eq!(shift_color_channel(64, 5), 2);

        // Test shifting by 6 bits
        assert_eq!(shift_color_channel(255, 6), 3);
        assert_eq!(shift_color_channel(128, 6), 2);
        assert_eq!(shift_color_channel(64, 6), 1);

        // Test shifting by 7 bits
        assert_eq!(shift_color_channel(255, 7), 1);
        assert_eq!(shift_color_channel(128, 7), 1);
        assert_eq!(shift_color_channel(64, 7), 0);
        assert_eq!(shift_color_channel(1, 7), 0);
    }

    #[test]
    fn test_shift_color_channel_max_valid_shift() {
        // Test shifting by exactly 7 bits (maximum valid shift for u8)
        assert_eq!(shift_color_channel(255, 7), 1);
        assert_eq!(shift_color_channel(254, 7), 1);
        assert_eq!(shift_color_channel(128, 7), 1);
        assert_eq!(shift_color_channel(127, 7), 0);
        assert_eq!(shift_color_channel(1, 7), 0);
        assert_eq!(shift_color_channel(0, 7), 0);
    }

    #[test]
    #[should_panic(expected = "attempt to shift right with overflow")]
    fn test_shift_color_channel_overflow_8_bits() {
        shift_color_channel(255, 8);
    }

    #[test]
    #[should_panic(expected = "attempt to shift right with overflow")]
    fn test_shift_color_channel_overflow_9_bits() {
        shift_color_channel(128, 9);
    }

    #[test]
    #[should_panic(expected = "attempt to shift right with overflow")]
    fn test_shift_color_channel_overflow_large_shift() {
        shift_color_channel(64, 32);
    }

    #[test]
    #[should_panic(expected = "attempt to shift right with overflow")]
    fn test_shift_color_channel_overflow_max_u32() {
        shift_color_channel(1, u32::MAX);
    }

    #[test]
    #[should_panic(expected = "attempt to shift right with overflow")]
    fn test_shift_color_channel_overflow_zero_channel_large_shift() {
        // Even with zero channel value, shifting by >= 8 should panic
        shift_color_channel(0, 8);
    }

    #[test]
    #[should_panic(expected = "attempt to shift right with overflow")]
    fn test_shift_color_channel_overflow_zero_channel_max_shift() {
        shift_color_channel(0, u32::MAX);
    }

    #[test]
    fn test_shift_color_channel_edge_cases() {
        // Test various edge values with valid shifts
        assert_eq!(shift_color_channel(255, 0), 255);
        assert_eq!(shift_color_channel(255, 1), 127);
        assert_eq!(shift_color_channel(255, 7), 1);

        assert_eq!(shift_color_channel(1, 0), 1);
        assert_eq!(shift_color_channel(1, 1), 0);
        assert_eq!(shift_color_channel(1, 7), 0);

        assert_eq!(shift_color_channel(0, 0), 0);
        assert_eq!(shift_color_channel(0, 1), 0);
        assert_eq!(shift_color_channel(0, 7), 0);
    }

    #[test]
    fn test_shift_color_channel_powers_of_two() {
        // Test with values that are powers of two
        assert_eq!(shift_color_channel(128, 1), 64);  // 2^7 >> 1 = 2^6
        assert_eq!(shift_color_channel(128, 2), 32);  // 2^7 >> 2 = 2^5
        assert_eq!(shift_color_channel(128, 3), 16);  // 2^7 >> 3 = 2^4
        assert_eq!(shift_color_channel(128, 4), 8);   // 2^7 >> 4 = 2^3
        assert_eq!(shift_color_channel(128, 5), 4);   // 2^7 >> 5 = 2^2
        assert_eq!(shift_color_channel(128, 6), 2);   // 2^7 >> 6 = 2^1
        assert_eq!(shift_color_channel(128, 7), 1);   // 2^7 >> 7 = 2^0

        assert_eq!(shift_color_channel(64, 1), 32);   // 2^6 >> 1 = 2^5
        assert_eq!(shift_color_channel(64, 6), 1);    // 2^6 >> 6 = 2^0
    }

    #[test]
    fn test_shift_color_channel_all_values_small_shift() {
        // Test all possible u8 values with a small shift
        for i in 0..=255u8 {
            let expected = i >> 1;
            assert_eq!(shift_color_channel(i, 1), expected);
        }
    }

    #[test]
    fn test_shift_color_channel_sequential_shifts() {
        // Test that sequential shifts produce the same result as a single larger shift
        let channel = 255u8;
        let shift1 = 2;
        let shift2 = 3;
        let total_shift = shift1 + shift2;

        // Perform sequential shifts
        let result1 = shift_color_channel(channel, shift1);
        let result2 = shift_color_channel(result1, shift2);

        // Perform single shift
        let result_single = shift_color_channel(channel, total_shift);

        assert_eq!(result2, result_single);
    }
}

