        assert_eq!(add_with_overflow_check(0, 5), 5);
        assert_eq!(add_with_overflow_check(u32::MAX, 0), u32::MAX);
        assert_eq!(add_with_overflow_check(0, u32::MAX), u32::MAX);
    }

