        let _ = add_with_overflow_check(u32::MAX / 2 + 1, u32::MAX / 2 + 1);
    }

    #[test]
    fn test_no_overflow_at_boundary() {
        // This should NOT panic - exactly at the boundary
        assert_eq!(add_with_overflow_check(u32::MAX - 100, 100), u32::MAX);
        assert_eq!(add_with_overflow_check(100, u32::MAX - 100), u32::MAX);
    }

    #[test]
    fn test_const_context_usage() {
        // Demonstrate the function can be used in const contexts
        const SUM: u32 = add_with_overflow_check(10, 20);
        assert_eq!(SUM, 30);

