mod tests {
    use super::*;

    #[test]
    fn test_normal_subtraction() {
        assert_eq!(next_expected_sequence(10, 5), 9);
        assert_eq!(next_expected_sequence(100, 50), 99);
        assert_eq!(next_expected_sequence(1, 0), 0);
    }

    #[test]
    fn test_large_numbers() {
        assert_eq!(next_expected_sequence(u32::MAX, u32::MAX - 1), u32::MAX - 1);
    }

    #[test]
    #[should_panic]
    fn test_underflow_panic() {
        next_expected_sequence(0, 0);
    }

    #[test]
    #[should_panic]
    fn test_min_value_underflow() {
        next_expected_sequence(u32::MIN, 100);
    }

    #[test]
    fn test_sequence_progression() {
        let mut current = 5;
        current = next_expected_sequence(current, 0);
        assert_eq!(current, 4);
        current = next_expected_sequence(current, 0);
        assert_eq!(current, 3);
        current = next_expected_sequence(current, 0);
        assert_eq!(current, 2);
    }

    #[test]
    fn test_with_different_acknowledged_values() {
        // The acknowledged parameter doesn't affect the calculation
        assert_eq!(next_expected_sequence(10, 5), 9);
        assert_eq!(next_expected_sequence(10, 9), 9);
        assert_eq!(next_expected_sequence(10, 0), 9);
    }
