pub fn compute_absolute_offset(base_address: u64, signed_offset: i64) -> u64 {
    base_address.strict_sub_signed(-signed_offset)
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_positive_offset() {
        // Positive signed offset should add to base address
        assert_eq!(compute_absolute_offset(100, 50), 150);
        assert_eq!(compute_absolute_offset(0, 100), 100);
        assert_eq!(compute_absolute_offset(u64::MAX - 100, 100), u64::MAX);
    }

    #[test]
    fn test_negative_offset() {
        // Negative signed offset should subtract from base address
        assert_eq!(compute_absolute_offset(150, -50), 100);
        assert_eq!(compute_absolute_offset(100, -100), 0);
        assert_eq!(compute_absolute_offset(1000, -500), 500);
    }

    #[test]
    fn test_zero_offset() {
        // Zero offset should return the base address
        assert_eq!(compute_absolute_offset(0, 0), 0);
        assert_eq!(compute_absolute_offset(100, 0), 100);
        assert_eq!(compute_absolute_offset(u64::MAX, 0), u64::MAX);
    }

    #[test]
    fn test_max_values() {
        // Test with maximum u64 values
        assert_eq!(compute_absolute_offset(u64::MAX, 0), u64::MAX);
        assert_eq!(compute_absolute_offset(u64::MAX, -100), u64::MAX - 100);

        // Test with maximum i64 offset
        assert_eq!(compute_absolute_offset(100, i64::MAX), 100u64.wrapping_add(i64::MAX as u64));
    }

    #[test]
    #[should_panic(expected = "overflow")]
    fn test_overflow_panic() {
        // This should panic due to overflow when subtracting
        compute_absolute_offset(0, -1); // 0 - 1 would underflow
    }

    #[test]
    #[should_panic(expected = "overflow")]
    fn test_underflow_panic() {
        // This should panic when result would underflow below 0
        compute_absolute_offset(50, -100); // 50 - 100 would underflow
    }

    #[test]
    fn test_edge_cases() {
        // Test with i64::MIN
        // i64::MIN as u64 is 2^63, which when subtracted from 100 would underflow
        // This should panic, but we're not testing that here

        // Test boundary conditions
        assert_eq!(compute_absolute_offset(1, -1), 0);
        assert_eq!(compute_absolute_offset(0, 1), 1);
    }

    #[test]
    fn test_large_offsets() {
        // Test with large positive offsets
        let large_base = 1_000_000_000;
        let large_offset = 500_000_000;
        assert_eq!(compute_absolute_offset(large_base, large_offset), 1_500_000_000);

        // Test with large negative offsets
        assert_eq!(compute_absolute_offset(large_base, -large_offset), 500_000_000);
    }

    #[test]
    fn test_property_based_style() {
        // Test that positive offset increases address
        for base in 0..1000u64 {
            for offset in 0..100i64 {
                let result = compute_absolute_offset(base, offset);
                assert!(result >= base, "Positive offset should not decrease address");
            }
        }

        // Test that negative offset decreases address when no underflow
        for base in 100..1000u64 {
            for offset in -100..0i64 {
                let result = compute_absolute_offset(base, offset);
                assert!(result <= base, "Negative offset should not increase address");
            }
        }
    }

    #[test]
    fn test_specific_cases() {
        // Specific test cases that might be interesting
        assert_eq!(compute_absolute_offset(42, 8), 50);
        assert_eq!(compute_absolute_offset(100, -42), 58);
        assert_eq!(compute_absolute_offset(0xFFFF, -0xFF), 0xFF00);
    }
}

