    #[should_panic(expected = "attempt to multiply with overflow")]
    fn test_multiply_with_overflow_panic_edge_case() {
        // Edge case: 2^32 * 2^32 = 2^64 = u64::MAX + 1, which overflows
        let _ = multiply_with_overflow_panic(2_u64.pow(32), 2_u64.pow(32));
    }

    #[test]
    fn test_multiply_with_overflow_panic_const_context() {
        // Test that the function can be used in const context
        const RESULT: u64 = multiply_with_overflow_panic(10, 20);
        assert_eq!(RESULT, 200);
    }

    #[test]
    fn test_multiply_with_overflow_panic_commutative() {
        // Verify commutative property for non-overflowing cases
        let a = 12345;
        let b = 67890;
        assert_eq!(
            multiply_with_overflow_panic(a, b),
            multiply_with_overflow_panic(b, a)
        );
    }

    #[test]
    #[should_panic]
    fn test_multiply_with_overflow_panic_overflow_panics() {
        // Test that overflow in fact causes a panic
        // Using numbers that when multiplied exceed u64::MAX
        let large_num = u64::MAX / 2 + 1;
        let _ = multiply_with_overflow_panic(large_num, 2);
    }

    #[test]
    fn test_multiply_with_overflow_panic_with_u32_max() {
        // Test with u32::MAX which when squared fits in u64
        let u32_max = u32::MAX as u64;
        let result = multiply_with_overflow_panic(u32_max, u32_max);
        let expected = (u32::MAX as u128).pow(2) as u64;
