#[cfg(test)]
mod tests {
    use super::validated_telemetry_remainder;

    #[test]
    fn test_basic_remainder_operations() {
        // Basic remainder calculations
        assert_eq!(validated_telemetry_remainder(10, 3), 1);
        assert_eq!(validated_telemetry_remainder(20, 5), 0);
        assert_eq!(validated_telemetry_remainder(7, 2), 1);
        assert_eq!(validated_telemetry_remainder(100, 30), 10);
    }

    #[test]
    fn test_edge_cases() {
        // Dividend is zero
        assert_eq!(validated_telemetry_remainder(0, 5), 0);

        // Dividend equals divisor
        assert_eq!(validated_telemetry_remainder(7, 7), 0);

        // Dividend less than divisor
        assert_eq!(validated_telemetry_remainder(3, 10), 3);

        // Large values
        assert_eq!(validated_telemetry_remainder(u32::MAX, 2), 1);
        assert_eq!(validated_telemetry_remainder(u32::MAX, u32::MAX), 0);
    }

    #[test]
    fn test_divisor_one() {
        // Any number modulo 1 should be 0
        assert_eq!(validated_telemetry_remainder(0, 1), 0);
        assert_eq!(validated_telemetry_remainder(1, 1), 0);
        assert_eq!(validated_telemetry_remainder(42, 1), 0);
        assert_eq!(validated_telemetry_remainder(u32::MAX, 1), 0);
    }

    #[test]
    #[should_panic(expected = "divisor must be non-zero")]
    fn test_zero_divisor_panics() {
        // Should panic when divisor is zero
        validated_telemetry_remainder(10, 0);
    }

    #[test]
    #[should_panic(expected = "divisor must be non-zero")]
    fn test_zero_divisor_with_zero_dividend() {
        // Should panic even when dividend is zero
        validated_telemetry_remainder(0, 0);
    }

    #[test]
    fn test_remainder_properties() {
        // Test that remainder is always less than divisor
        let test_cases = vec![
            (10, 3),
            (20, 7),
            (100, 33),
            (255, 16),
            (999, 100),
        ];

        for (dividend, divisor) in test_cases {
            let remainder = validated_telemetry_remainder(dividend, divisor);
            assert!(remainder < divisor, 
                   "Remainder {} should be less than divisor {}", remainder, divisor);
        }
    }

    #[test]
    fn test_remainder_identity() {
        // Test that a = b * q + r where r = a % b
        let test_cases = vec![
            (10, 3),
            (20, 7),
            (100, 33),
            (255, 16),
            (999, 100),
        ];

        for (dividend, divisor) in test_cases {
            let remainder = validated_telemetry_remainder(dividend, divisor);
            let quotient = dividend / divisor;
            assert_eq!(dividend, divisor * quotient + remainder,
                      "Failed identity: {} = {} * {} + {}", dividend, divisor, quotient, remainder);
        }
    }

    #[test]
    fn test_powers_of_two() {
        // Remainder with powers of two should be equivalent to bitmask
        assert_eq!(validated_telemetry_remainder(13, 4), 13 & 3); // 4 = 2^2, mask = 3
        assert_eq!(validated_telemetry_remainder(255, 16), 255 & 15); // 16 = 2^4, mask = 15
        assert_eq!(validated_telemetry_remainder(1023, 32), 1023 & 31); // 32 = 2^5, mask = 31
    }
}

