mod tests {
    use super::*;

    #[test]
    fn test_basic_right_shift() {
        // Basic shift operations
        assert_eq!(perform_strict_right_shift(0b1000_0000, 1), 0b0100_0000);
        assert_eq!(perform_strict_right_shift(0b1111_0000, 4), 0b0000_1111);
        assert_eq!(perform_strict_right_shift(0xFFFFFFFF, 1), 0x7FFFFFFF);
    }

    #[test]
    fn test_zero_shift() {
        // Shift by zero should return the original value
        assert_eq!(perform_strict_right_shift(42, 0), 42);
        assert_eq!(perform_strict_right_shift(0, 0), 0);
        assert_eq!(perform_strict_right_shift(u32::MAX, 0), u32::MAX);
    }

    #[test]
    fn test_shift_to_zero() {
        // Shift until value becomes zero
        assert_eq!(perform_strict_right_shift(1, 1), 0);
        assert_eq!(perform_strict_right_shift(4, 2), 1);
        assert_eq!(perform_strict_right_shift(4, 3), 0);
    }

    #[test]
    fn test_boundary_shifts() {
        // Shifts near the bit width boundary
        assert_eq!(perform_strict_right_shift(u32::MAX, 31), 1);
        assert_eq!(perform_strict_right_shift(0x80000000, 31), 1);
        assert_eq!(perform_strict_right_shift(0x40000000, 30), 1);
    }

    #[test]
    #[should_panic(expected = "attempt to shift right with overflow")]
    fn test_panic_on_32_bit_shift() {
        // Shifting by exactly 32 bits should panic
        perform_strict_right_shift(42, 32);
    }

    #[test]
    #[should_panic(expected = "attempt to shift right with overflow")]
    fn test_panic_on_greater_than_32_bit_shift() {
        // Shifting by more than 32 bits should panic
        perform_strict_right_shift(100, 33);
        perform_strict_right_shift(1, u32::MAX);
    }

    #[test]
    #[should_panic(expected = "attempt to shift right with overflow")]
    fn test_panic_with_max_value_at_boundary() {
        // Even with maximum value, shifting by >= 32 should panic
        perform_strict_right_shift(u32::MAX, 32);
    }

    #[test]
    fn test_const_context_usage() {
        // Demonstrate it works in const context (compile-time evaluation)
        const SHIFT_RESULT: u32 = perform_strict_right_shift(256, 3);
        assert_eq!(SHIFT_RESULT, 32);

        const ZERO_SHIFT: u32 = perform_strict_right_shift(100, 0);
        assert_eq!(ZERO_SHIFT, 100);
    }

    #[test]
    fn test_edge_cases() {
        // Various edge cases
        assert_eq!(perform_strict_right_shift(0, 1), 0);
        assert_eq!(perform_strict_right_shift(0, 31), 0);
        assert_eq!(perform_strict_right_shift(1, 31), 0);
        assert_eq!(perform_strict_right_shift(2, 31), 0);
    }

    #[test]
    fn test_powers_of_two() {
        // Test with powers of two
        for i in 0..31 {
            let value = 1u32 << i;
            for j in 0..=i {
                let expected = if j <= i { 1u32 << (i - j) } else { 0 };
                assert_eq!(perform_strict_right_shift(value, j), expected);
            }
        }
    }

    #[test]
    fn test_sequential_shifts() {
        // Test that sequential shifts produce correct results
        let mut value = 0xABCD1234;
        let mut expected = value;

        for shift in 0..16 {
            assert_eq!(perform_strict_right_shift(value, shift), expected >> shift);
        }
    }
}

