#[cfg(test)]
mod tests {
    use super::compute_chained_addition;

    #[test]
    fn test_no_carry_basic_addition() {
        // Basic addition without carry
        assert_eq!(compute_chained_addition(5, 3, false), (8, false));
        assert_eq!(compute_chained_addition(0, 0, false), (0, false));
        assert_eq!(compute_chained_addition(100, 200, false), (300, false));
    }

    #[test]
    fn test_with_incoming_carry() {
        // Addition with incoming carry
        assert_eq!(compute_chained_addition(5, 3, true), (9, false));
        assert_eq!(compute_chained_addition(0, 0, true), (1, false));
        assert_eq!(compute_chained_addition(100, 200, true), (301, false));
    }

    #[test]
    fn test_carry_generation() {
        // Cases that generate carry
        assert_eq!(compute_chained_addition(u32::MAX, 0, false), (u32::MAX, false));
        assert_eq!(compute_chained_addition(u32::MAX, 0, true), (0, true));
        assert_eq!(compute_chained_addition(u32::MAX, 1, false), (0, true));
        assert_eq!(compute_chained_addition(u32::MAX, 1, true), (1, true));
    }

    #[test]
    fn test_overflow_scenarios() {
        // Various overflow scenarios
        assert_eq!(compute_chained_addition(u32::MAX - 1, 1, false), (u32::MAX, false));
        assert_eq!(compute_chained_addition(u32::MAX - 1, 1, true), (0, true));
        assert_eq!(compute_chained_addition(u32::MAX - 1, 2, false), (0, true));
        assert_eq!(compute_chained_addition(u32::MAX - 1, 2, true), (1, true));
    }

    #[test]
    fn test_boundary_values() {
        // Test with boundary values
        assert_eq!(compute_chained_addition(0, u32::MAX, false), (u32::MAX, false));
        assert_eq!(compute_chained_addition(0, u32::MAX, true), (0, true));
        assert_eq!(compute_chained_addition(u32::MAX, u32::MAX, false), (u32::MAX - 1, true));
        assert_eq!(compute_chained_addition(u32::MAX, u32::MAX, true), (u32::MAX, true));
    }

    #[test]
    fn test_random_samples() {
        // Some random test cases to ensure general correctness
        assert_eq!(compute_chained_addition(12345, 67890, false), (80235, false));
        assert_eq!(compute_chained_addition(12345, 67890, true), (80236, false));
        assert_eq!(compute_chained_addition(0xFFFF, 0xFFFF, false), (0x1FFFE, false));
        assert_eq!(compute_chained_addition(0xFFFF, 0xFFFF, true), (0x1FFFF, false));
    }

    #[test]
    fn test_property_based() {
        // Property-based style tests
        // Adding 0 should return the same number (without considering carry)
        for i in 0..=1000u32 {
            let (result, carry) = compute_chained_addition(i, 0, false);
            assert_eq!(result, i);
            assert!(!carry);
        }

        // Adding with incoming carry true should be same as adding 1 more
        for i in 0..=1000u32 {
            for j in 0..=1000u32 {
                let (result_with_carry, carry1) = compute_chained_addition(i, j, true);
                let (result_without_carry, carry2) = compute_chained_addition(i, j, false);
                let (result_plus_one, carry3) = compute_chained_addition(result_without_carry, 1, false);

                // The result with incoming carry should equal result without carry plus 1
                // unless there was already a carry from the first addition
                if !carry2 {
                    assert_eq!(result_with_carry, result_plus_one);
                    assert_eq!(carry1, carry3);
                }
            }
        }
    }

    #[test]
    fn test_commutative_property() {
        // Addition should be commutative
        for i in 0..=100u32 {
            for j in 0..=100u32 {
                for carry in [false, true] {
                    let (result1, carry1) = compute_chained_addition(i, j, carry);
                    let (result2, carry2) = compute_chained_addition(j, i, carry);
                    assert_eq!(result1, result2);
                    assert_eq!(carry1, carry2);
                }
            }
        }
    }
}

