fn align_to_next_char_boundary(text: &str, byte_pos: usize) -> usize {
    text.ceil_char_boundary(byte_pos)
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_align_to_next_char_boundary_empty_string() {
        let text = "";
        assert_eq!(align_to_next_char_boundary(text, 0), 0);
        assert_eq!(align_to_next_char_boundary(text, 5), 0);
    }

    #[test]
    fn test_align_to_next_char_boundary_ascii_only() {
        let text = "hello world";
        // ASCII characters are single-byte
        assert_eq!(align_to_next_char_boundary(text, 0), 0);
        assert_eq!(align_to_next_char_boundary(text, 1), 1);
        assert_eq!(align_to_next_char_boundary(text, 5), 5);
        assert_eq!(align_to_next_char_boundary(text, 10), 10);
        assert_eq!(align_to_next_char_boundary(text, 11), 11);
        // Positions beyond string length
        assert_eq!(align_to_next_char_boundary(text, 12), 11);
        assert_eq!(align_to_next_char_boundary(text, 100), 11);
    }

    #[test]
    fn test_align_to_next_char_boundary_multi_byte_chars() {
        let text = "aαβcδ"; // 'α' and 'β' are 2-byte, 'δ' is 2-byte in UTF-8
        // String layout: a(1) α(2) β(2) c(1) δ(2) = 8 bytes

        // At character boundaries
        assert_eq!(align_to_next_char_boundary(text, 0), 0); // 'a'
        assert_eq!(align_to_next_char_boundary(text, 1), 1); // start of 'α'
        assert_eq!(align_to_next_char_boundary(text, 3), 3); // start of 'β'
        assert_eq!(align_to_next_char_boundary(text, 5), 5); // start of 'c'
        assert_eq!(align_to_next_char_boundary(text, 6), 6); // start of 'δ'
        assert_eq!(align_to_next_char_boundary(text, 8), 8); // end of string

        // Inside multi-byte characters
        assert_eq!(align_to_next_char_boundary(text, 2), 3); // inside 'α'
        assert_eq!(align_to_next_char_boundary(text, 4), 5); // inside 'β'
        assert_eq!(align_to_next_char_boundary(text, 7), 8); // inside 'δ'

        // Beyond string length
        assert_eq!(align_to_next_char_boundary(text, 9), 8);
        assert_eq!(align_to_next_char_boundary(text, 100), 8);
    }

    #[test]
    fn test_align_to_next_char_boundary_mixed_chars() {
        let text = "hello αβγ world 🦀"; // 'αβγ' are 2-byte each, '🦀' is 4-byte
        // Positions: h e l l o space α β γ space w o r l d space 🦀

        // Test various positions
        assert_eq!(align_to_next_char_boundary(text, 0), 0); // 'h'
        assert_eq!(align_to_next_char_boundary(text, 5), 5); // 'o'
        assert_eq!(align_to_next_char_boundary(text, 6), 6); // space before α

        // Inside 2-byte character 'α' (bytes 7-8)
        assert_eq!(align_to_next_char_boundary(text, 7), 8);
        assert_eq!(align_to_next_char_boundary(text, 8), 8); // start of 'β'

        // Inside 4-byte character '🦀'
        let crab_pos = text.find('🦀').unwrap(); // Find start of crab emoji
        assert_eq!(align_to_next_char_boundary(text, crab_pos), crab_pos);
        assert_eq!(align_to_next_char_boundary(text, crab_pos + 1), crab_pos + 4);
        assert_eq!(align_to_next_char_boundary(text, crab_pos + 2), crab_pos + 4);
        assert_eq!(align_to_next_char_boundary(text, crab_pos + 3), crab_pos + 4);
    }

    #[test]
    fn test_align_to_next_char_boundary_edge_cases() {
        // String with various UTF-8 character lengths
        let text = "a©あ🐘"; // a(1), ©(2), あ(3), 🐘(4)

        // Test at each character boundary
        assert_eq!(align_to_next_char_boundary(text, 0), 0); // 'a'
        assert_eq!(align_to_next_char_boundary(text, 1), 1); // start of '©'
        assert_eq!(align_to_next_char_boundary(text, 3), 3); // start of 'あ'
        assert_eq!(align_to_next_char_boundary(text, 6), 6); // start of '🐘'
        assert_eq!(align_to_next_char_boundary(text, 10), 10); // end

        // Test inside each multi-byte character
        assert_eq!(align_to_next_char_boundary(text, 2), 3); // inside '©'
        assert_eq!(align_to_next_char_boundary(text, 4), 6); // inside 'あ'
        assert_eq!(align_to_next_char_boundary(text, 7), 10); // inside '🐘'
        assert_eq!(align_to_next_char_boundary(text, 8), 10); // inside '🐘'
        assert_eq!(align_to_next_char_boundary(text, 9), 10); // inside '🐘'
    }

    #[test]
    fn test_align_to_next_char_boundary_zero_position() {
        let text = "test";
        assert_eq!(align_to_next_char_boundary(text, 0), 0);

        let text = "αβγ";
        assert_eq!(align_to_next_char_boundary(text, 0), 0);
    }

    #[test]
    fn test_align_to_next_char_boundary_exact_end() {
        let text = "hello";
        assert_eq!(align_to_next_char_boundary(text, 5), 5);

        let text = "αβ";
        assert_eq!(align_to_next_char_boundary(text, 4), 4); // 2 + 2 bytes
    }
}

