use std::sync::atomic::{AtomicPtr, Ordering};

pub fn atomic_toggle_address_bits(ptr: &AtomicPtr<i32>, mask: usize) -> *mut i32 {
    ptr.fetch_xor(mask, Ordering::SeqCst)
}

