#[cfg(test)]
mod tests {
    use std::sync::atomic::{AtomicPtr, Ordering};
    use super::atomic_toggle_address_bits;

    #[test]
    fn test_basic_toggle() {
        let value = Box::into_raw(Box::new(42));
        let atomic_ptr = AtomicPtr::new(value);

        let mask = 0b1000;
        let original = atomic_toggle_address_bits(&atomic_ptr, mask);

        assert_eq!(original, value);
        assert_eq!(atomic_ptr.load(Ordering::SeqCst), (value as usize ^ mask) as *mut i32);

        unsafe {
            drop(Box::from_raw(value));
        }
    }

    #[test]
    fn test_toggle_zero_mask() {
        let value = Box::into_raw(Box::new(-5));
        let atomic_ptr = AtomicPtr::new(value);

        let original = atomic_toggle_address_bits(&atomic_ptr, 0);

        assert_eq!(original, value);
        assert_eq!(atomic_ptr.load(Ordering::SeqCst), value);

        unsafe {
            drop(Box::from_raw(value));
        }
    }

    #[test]
    fn test_toggle_full_mask() {
        let value = Box::into_raw(Box::new(100));
        let atomic_ptr = AtomicPtr::new(value);

        let mask = usize::MAX;
        let original = atomic_toggle_address_bits(&atomic_ptr, mask);

        assert_eq!(original, value);
        assert_eq!(atomic_ptr.load(Ordering::SeqCst), (value as usize ^ mask) as *mut i32);

        unsafe {
            drop(Box::from_raw(value));
        }
    }

    #[test]
    fn test_multiple_consecutive_toggles() {
        let value = Box::into_raw(Box::new(0));
        let atomic_ptr = AtomicPtr::new(value);

        let mask1 = 0b1010;
        let mask2 = 0b0101;

        let first_original = atomic_toggle_address_bits(&atomic_ptr, mask1);
        assert_eq!(first_original, value);

        let second_original = atomic_toggle_address_bits(&atomic_ptr, mask2);
        assert_eq!(second_original, (value as usize ^ mask1) as *mut i32);

        let expected_final = (value as usize ^ mask1 ^ mask2) as *mut i32;
        assert_eq!(atomic_ptr.load(Ordering::SeqCst), expected_final);

        unsafe {
            drop(Box::from_raw(value));
        }
    }

    #[test]
    fn test_toggle_specific_bits() {
        let value = Box::into_raw(Box::new(999));
        let atomic_ptr = AtomicPtr::new(value);

        let mask = 0b1;
        let original = atomic_toggle_address_bits(&atomic_ptr, mask);

        assert_eq!(original, value);

        let toggled_ptr = atomic_ptr.load(Ordering::SeqCst);
        let expected = if value as usize & 1 == 1 {
            value as usize & !1
        } else {
            value as usize | 1
        } as *mut i32;

        assert_eq!(toggled_ptr, expected);

        unsafe {
            drop(Box::from_raw(value));
        }
    }

    #[test]
    fn test_null_pointer() {
        let atomic_ptr = AtomicPtr::new(std::ptr::null_mut());

        let mask = 0xFFFF;
        let original = atomic_toggle_address_bits(&atomic_ptr, mask);

        assert!(original.is_null());
        assert_eq!(atomic_ptr.load(Ordering::SeqCst), (0usize ^ mask) as *mut i32);
    }

    #[test]
    fn test_alignment_preservation() {
        let mut value = 1234;
        let ptr = &mut value as *mut i32;
        let atomic_ptr = AtomicPtr::new(ptr);

        let mask = 0b100;
        let original = atomic_toggle_address_bits(&atomic_ptr, mask);

        assert_eq!(original, ptr);

        let toggled = atomic_ptr.load(Ordering::SeqCst);
        assert_eq!(toggled as usize % std::mem::align_of::<i32>(), 0);
    }

    #[test]
    fn test_concurrent_behavior_simulation() {
        let value = Box::into_raw(Box::new(777));
        let atomic_ptr = AtomicPtr::new(value);

        let mask_a = 0b1100;
        let mask_b = 0b0011;

        let thread_a_result = atomic_toggle_address_bits(&atomic_ptr, mask_a);
        assert_eq!(thread_a_result, value);

        let thread_b_result = atomic_toggle_address_bits(&atomic_ptr, mask_b);
        assert_eq!(thread_b_result, (value as usize ^ mask_a) as *mut i32);

        let final_ptr = atomic_ptr.load(Ordering::SeqCst);
        let expected = (value as usize ^ mask_a ^ mask_b) as *mut i32;
        assert_eq!(final_ptr, expected);

        unsafe {
            drop(Box::from_raw(value));
        }
    }

    #[test]
    fn test_memory_cleanup() {
        let value = Box::into_raw(Box::new(42));
        let atomic_ptr = AtomicPtr::new(value);

        let result = atomic_toggle_address_bits(&atomic_ptr, 0b100);

        unsafe {
            drop(Box::from_raw(value));
        }
    }
}

