#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_input() {
        let addresses: Vec<String> = vec![];
        let errors = collect_address_errors(&addresses);
        assert!(errors.is_empty());
    }

    #[test]
    fn test_valid_ipv4_addresses() {
        let addresses = vec![
            "127.0.0.1:8080".to_string(),
            "192.168.1.1:80".to_string(),
            "0.0.0.0:22".to_string(),
        ];
        let errors = collect_address_errors(&addresses);
        assert!(errors.is_empty());
    }

    #[test]
    fn test_valid_ipv6_addresses() {
        let addresses = vec![
            "[::1]:8080".to_string(),
            "[2001:db8::1]:80".to_string(),
            "[::]:22".to_string(),
        ];
        let errors = collect_address_errors(&addresses);
        assert!(errors.is_empty());
    }

    #[test]
    fn test_invalid_ipv4_format() {
        let addresses = vec![
            "127.0.0.1".to_string(), // missing port
            "127.0.0.1:".to_string(), // port missing number
            "256.256.256.256:8080".to_string(), // invalid IP octet
        ];
        let errors = collect_address_errors(&addresses);
        assert_eq!(errors.len(), 3);

        // Check each error starts with its corresponding address
        for error in &errors {
            assert!(addresses.iter().any(|addr| error.starts_with(addr)));
        }
    }

    #[test]
    fn test_invalid_ipv6_format() {
        let addresses = vec![
            "::1".to_string(), // missing brackets and port
            "[::1]".to_string(), // missing port
            "[::1]:".to_string(), // port missing number
            "[gggg::1]:8080".to_string(), // invalid hex in IPv6
        ];
        let errors = collect_address_errors(&addresses);
        assert_eq!(errors.len(), 4);

        // Check each error starts with its corresponding address
        for error in &errors {
            assert!(addresses.iter().any(|addr| error.starts_with(addr)));
        }
    }

    #[test]
    fn test_malformed_addresses() {
        let addresses = vec![
            "".to_string(),
            ":".to_string(),
            "[]".to_string(),
            "[]:".to_string(),
            "not an address at all".to_string(),
        ];
        let errors = collect_address_errors(&addresses);
        assert_eq!(errors.len(), 5);

        for error in errors {
            assert!(!error.is_empty());
        }
    }

    #[test]
    fn test_mixed_valid_and_invalid_addresses() {
        let addresses = vec![
            "127.0.0.1:8080".to_string(), // valid
            "invalid_address".to_string(), // invalid
            "[::1]:80".to_string(), // valid
            "256.300.400.500:9999".to_string(), // invalid
        ];
        let errors = collect_address_errors(&addresses);
        assert_eq!(errors.len(), 2);

        // Check that errors correspond to the invalid addresses
        assert!(errors.iter().any(|e| e.contains("invalid_address")));
        assert!(errors.iter().any(|e| e.contains("256.300.400.500:9999")));
    }

    #[test]
    fn test_large_port_numbers() {
        let addresses = vec![
            "127.0.0.1:65536".to_string(), // port too large
            "127.0.0.1:0".to_string(), // valid port 0
            "127.0.0.1:65535".to_string(), // valid max port
        ];
        let errors = collect_address_errors(&addresses);
        assert_eq!(errors.len(), 1);
        assert!(errors[0].contains("65536"));
    }

    #[test]
    fn test_error_message_format() {
        let addresses = vec!["invalid".to_string()];
        let errors = collect_address_errors(&addresses);

        assert_eq!(errors.len(), 1);
        let error_msg = &errors[0];

        // Verify the error message contains both the address and error description
        assert!(error_msg.starts_with("invalid: "));
        assert!(error_msg.len() > "invalid: ".len());
    }
}

