#[cfg(test)]
mod tests {
    use super::*;
    use std::panic::{self, AssertUnwindSafe};
    use std::sync::{Arc, Mutex};
    use std::thread;

    #[test]
    fn test_propagate_panic_with_string_payload() {
        // Test with a string payload
        let payload = Box::new("test panic message".to_string());

        let result = panic::catch_unwind(AssertUnwindSafe(|| {
            propagate_panic_from_thread(payload);
        }));

        match result {
            Err(e) => {
                if let Some(s) = e.downcast_ref::<String>() {
                    assert_eq!(s, "test panic message");
                } else {
                    panic!("Expected String payload");
                }
            }
            Ok(_) => panic!("Expected panic to be caught"),
        }
    }

    #[test]
    fn test_propagate_panic_with_static_str_payload() {
        // Test with a &'static str payload
        let payload = Box::new("static panic message");

        let result = panic::catch_unwind(AssertUnwindSafe(|| {
            propagate_panic_from_thread(payload);
        }));

        match result {
            Err(e) => {
                if let Some(s) = e.downcast_ref::<&str>() {
                    assert_eq!(*s, "static panic message");
                } else {
                    panic!("Expected &str payload");
                }
            }
            Ok(_) => panic!("Expected panic to be caught"),
        }
    }

    #[test]
    fn test_propagate_panic_with_integer_payload() {
        // Test with an integer payload
        let payload = Box::new(42i32);

        let result = panic::catch_unwind(AssertUnwindSafe(|| {
            propagate_panic_from_thread(payload);
        }));

        match result {
            Err(e) => {
                if let Some(n) = e.downcast_ref::<i32>() {
                    assert_eq!(*n, 42);
                } else {
                    panic!("Expected i32 payload");
                }
            }
            Ok(_) => panic!("Expected panic to be caught"),
        }
    }

    #[test]
    fn test_propagate_panic_with_custom_struct() {
        // Test with a custom struct that implements Any + Send
        #[derive(Debug, PartialEq)]
        struct CustomError {
            code: u32,
            message: String,
        }

        let payload = Box::new(CustomError {
            code: 500,
            message: "Internal server error".to_string(),
        });

        let result = panic::catch_unwind(AssertUnwindSafe(|| {
            propagate_panic_from_thread(payload);
        }));

        match result {
            Err(e) => {
                if let Some(err) = e.downcast_ref::<CustomError>() {
                    assert_eq!(err.code, 500);
                    assert_eq!(err.message, "Internal server error");
                } else {
                    panic!("Expected CustomError payload");
                }
            }
            Ok(_) => panic!("Expected panic to be caught"),
        }
    }

    #[test]
    fn test_panic_hook_bypass() {
        // Test that panic hooks are not called when using resume_unwind
        let hook_called = Arc::new(Mutex::new(false));
        let hook_called_clone = Arc::clone(&hook_called);

        // Install a custom panic hook
        panic::set_hook(Box::new(move |_| {
            *hook_called_clone.lock().unwrap() = true;
        }));

        let payload = Box::new("test hook bypass".to_string());

        let result = panic::catch_unwind(AssertUnwindSafe(|| {
            propagate_panic_from_thread(payload);
        }));

        // Verify the panic was caught
        assert!(result.is_err());

        // Verify the hook was NOT called (resume_unwind bypasses hooks)
        let hook_was_called = *hook_called.lock().unwrap();
        assert!(!hook_was_called, "Panic hook should not be called with resume_unwind");

        // Restore default hook
        let _ = panic::take_hook();
    }

    #[test]
    fn test_from_spawned_thread() {
        // Test that the function works correctly when called from a spawned thread context
        let handle = thread::spawn(|| {
            let payload = Box::new("from spawned thread".to_string());
            propagate_panic_from_thread(payload);
        });

        let result = handle.join();

        match result {
            Err(e) => {
                if let Some(s) = e.downcast_ref::<String>() {
                    assert_eq!(s, "from spawned thread");
                } else {
                    panic!("Expected String payload from thread");
                }
            }
            Ok(_) => panic!("Expected thread to panic"),
        }
    }

    #[test]
    fn test_send_trait_bound() {
        // Test that the payload must implement Send
        struct SendStruct {
            data: i32,
        }
        unsafe impl Send for SendStruct {}

        let payload = Box::new(SendStruct { data: 100 });

        let result = panic::catch_unwind(AssertUnwindSafe(|| {
            propagate_panic_from_thread(payload);
        }));

        match result {
            Err(e) => {
                if let Some(s) = e.downcast_ref::<SendStruct>() {
                    assert_eq!(s.data, 100);
                } else {
                    panic!("Expected SendStruct payload");
                }
            }
            Ok(_) => panic!("Expected panic to be caught"),
        }
    }

    #[test]
    fn test_never_return_type() {
        // Verify the function indeed never returns (diverges)
        let payload = Box::new("diverging".to_string());

        // This should compile and the function should panic
        let result = panic::catch_unwind(AssertUnwindSafe(|| {
            propagate_panic_from_thread(payload);
            // This line should never be reached
            panic!("Should have already panicked");
        }));

        assert!(result.is_err());
    }
}

