use std::net::UdpSocket;

fn bind_to_first_available(addrs: &[&str]) -> std::io::Result<std::net::UdpSocket> {
    let mut last_error = None;

    for addr in addrs {
        match UdpSocket::bind(addr) {
            Ok(socket) => return Ok(socket),
            Err(e) => last_error = Some(e),
        }
    }

    Err(last_error.unwrap_or_else(|| 
        std::io::Error::new(std::io::ErrorKind::InvalidInput, "no addresses provided")
    ))
}

