#[cfg(test)]
mod tests {
    use super::*;
    use std::net::{Ipv4Addr, Ipv6Addr, SocketAddr};
    use std::thread;
    use std::time::Duration;

    #[test]
    fn test_binds_to_first_available_address() {
        // Test binding to localhost on different ports
        let addrs = &["127.0.0.1:0", "127.0.0.1:0"];
        let socket = bind_to_first_available(addrs).unwrap();
        assert!(socket.local_addr().is_ok());
    }

    #[test]
    fn test_ipv4_and_ipv6_addresses() {
        // Test with both IPv4 and IPv6 addresses
        let addrs = &["127.0.0.1:0", "[::1]:0"];
        let socket = bind_to_first_available(addrs).unwrap();
        let local_addr = socket.local_addr().unwrap();

        // Verify it bound to one of the addresses
        assert!(local_addr.ip().is_loopback());
    }

    #[test]
    fn test_falls_back_to_second_address() {
        // Bind to first port to make it unavailable
        let _occupied_socket = UdpSocket::bind("127.0.0.1:12345").unwrap();

        // First address should fail, second should succeed
        let addrs = &["127.0.0.1:12345", "127.0.0.1:0"];
        let socket = bind_to_first_available(addrs).unwrap();

        // Verify we got a socket (bound to second address)
        assert!(socket.local_addr().is_ok());
    }

    #[test]
    fn test_all_addresses_fail() {
        // Try to bind to privileged port without permissions
        let addrs = &["127.0.0.1:1", "127.0.0.1:2", "127.0.0.1:3"];
        let result = bind_to_first_available(addrs);

        assert!(result.is_err());

        // Verify error kind is permission denied (or similar)
        let err = result.unwrap_err();
        assert!(err.kind() == std::io::ErrorKind::PermissionDenied ||
                err.kind() == std::io::ErrorKind::AddrInUse ||
                err.kind() == std::io::ErrorKind::AddrNotAvailable);
    }

    #[test]
    fn test_empty_address_list() {
        let addrs: &[&str] = &[];
        let result = bind_to_first_available(addrs);

        assert!(result.is_err());
        assert_eq!(result.unwrap_err().kind(), std::io::ErrorKind::InvalidInput);
    }

    #[test]
    fn test_invalid_address_format() {
        let addrs = &["not_a_valid_address", "127.0.0.1:0"];
        let socket = bind_to_first_available(addrs).unwrap();

        // Should skip invalid first address and bind to second
        assert!(socket.local_addr().is_ok());
    }

    #[test]
    fn test_preserves_last_error() {
        // All addresses should fail with the same error
        let addrs = &["127.0.0.1:1", "127.0.0.1:2"];
        let result = bind_to_first_available(addrs);

        assert!(result.is_err());
        let err = result.unwrap_err();

        // Error should be from the last failed attempt
        assert!(err.kind() == std::io::ErrorKind::PermissionDenied ||
                err.kind() == std::io::ErrorKind::AddrInUse);
    }

    #[test]
    fn test_with_hostnames() {
        // Test with hostnames that resolve to localhost
        let addrs = &["localhost:0", "127.0.0.1:0"];
        let socket = bind_to_first_available(addrs).unwrap();

        assert!(socket.local_addr().is_ok());
    }

    #[test]
    fn test_socket_is_usable() {
        let addrs = &["127.0.0.1:0"];
        let socket = bind_to_first_available(addrs).unwrap();

        // Test that the socket can actually send/receive
        let test_addr = "127.0.0.1:54321";
        let test_socket = UdpSocket::bind("127.0.0.1:0").unwrap();

        // Send a packet
        let send_result = socket.send_to(b"test", test_addr);
        assert!(send_result.is_ok());

        // Set non-blocking for receive test
        socket.set_nonblocking(true).unwrap();

        // Try to receive (should timeout since nothing is sent back)
        let mut buf = [0u8; 4];
        let recv_result = socket.recv_from(&mut buf);
        assert!(recv_result.is_err()); // Should fail with WouldBlock in non-blocking mode
    }

    #[test]
    fn test_concurrent_binding() {
        // Test that function works correctly when called concurrently
        let addrs = &["127.0.0.1:0"];

        let handles: Vec<_> = (0..10)
            .map(|_| {
                let addrs = addrs.to_vec();
                thread::spawn(move || {
                    bind_to_first_available(&addrs)
                })
            })
            .collect();

        for handle in handles {
            let result = handle.join().unwrap();
            assert!(result.is_ok());
        }
    }
}

