#[derive(Debug, Clone, Copy, PartialEq)]
enum SensorError {
    CalibrationError,
    CommunicationError,
    OutOfRange,
}

fn sum_valid_readings_const(readings: &[Result<f32, SensorError>]) -> Option<f32> {
    let mut sum = 0.0f32;
    let mut has_valid = false;

    for reading in readings.iter() {
        if let Ok(value) = reading {
            sum += *value;
            has_valid = true;
        }
    }

    if has_valid {
        Some(sum)
    } else {
        None
    }
}

