    fn test_all_errors() {
        let readings = &[
            Err(SensorError::CalibrationError),
            Err(SensorError::CommunicationError),
            Err(SensorError::OutOfRange),
            Err(SensorError::CalibrationError),
        ];
        assert_eq!(sum_valid_readings_const(readings), None);
    }

