    fn test_all_valid() {
        let readings = &[Ok(1.5), Ok(2.5), Ok(3.5), Ok(4.5)];
        assert_eq!(sum_valid_readings_const(readings), Some(12.0));
    }

    #[test]
    fn test_mixed_valid_and_errors() {
        let readings = &[
            Ok(1.0),
            Err(SensorError::CalibrationError),
            Ok(2.0),
            Err(SensorError::CommunicationError),
            Ok(3.0),
            Err(SensorError::OutOfRange),
        ];
        assert_eq!(sum_valid_readings_const(readings), Some(6.0));
    }

    #[test]
    fn test_single_valid() {
        let readings = &[Ok(42.0)];
        assert_eq!(sum_valid_readings_const(readings), Some(42.0));
    }

    #[test]
    fn test_single_error() {
        let readings = &[Err(SensorError::CalibrationError)];
        assert_eq!(sum_valid_readings_const(readings), None);
    }

    #[test]
    fn test_negative_values() {
        let readings = &[Ok(-1.5), Ok(2.5), Ok(-3.5), Ok(4.5)];
        assert_eq!(sum_valid_readings_const(readings), Some(2.0));
    }

    #[test]
    fn test_zero_values() {
        let readings = &[Ok(0.0), Ok(0.0), Ok(0.0)];
        assert_eq!(sum_valid_readings_const(readings), Some(0.0));
    }

    #[test]
    fn test_large_slice() {
        let mut readings = Vec::new();
        for i in 0..1000 {
            if i % 3 == 0 {
                readings.push(Err(SensorError::CalibrationError));
            } else {
                readings.push(Ok(i as f32));
            }
        }
        let expected_sum: f32 = (0..1000)
            .filter(|&i| i % 3 != 0)
            .map(|i| i as f32)
            .sum();
        assert_eq!(sum_valid_readings_const(&readings), Some(expected_sum));
    }

    #[test]
    fn test_float_precision() {
        let readings = &[Ok(0.1), Ok(0.2), Ok(0.3)];
        let result = sum_valid_readings_const(readings);
        assert!(result.is_some());
        // Using approximate comparison for floating point
        assert!((result.unwrap() - 0.6).abs() < f32::EPSILON);
    }

    #[test]
    fn test_const_context() {
        // Test that can be evaluated in const context
        const READINGS: &[Result<f32, SensorError>] = &[
            Ok(1.0),
            Err(SensorError::CalibrationError),
            Ok(2.0),
        ];

        // This would normally be const, but we're just verifying the function works
        let result = sum_valid_readings_const(READINGS);
        assert_eq!(result, Some(3.0));
    }

    #[test]
    fn test_different_error_types_mixed() {
        let readings = &[
            Err(SensorError::CalibrationError),
            Ok(10.0),
            Err(SensorError::CommunicationError),
            Ok(20.0),
            Err(SensorError::OutOfRange),
            Ok(30.0),
            Err(SensorError::CalibrationError),
        ];
        assert_eq!(sum_valid_readings_const(readings), Some(60.0));
    }

    #[test]
    fn test_nan_and_infinity() {
        let readings = &[
            Ok(f32::NAN),
            Ok(f32::INFINITY),
            Ok(1.0),
            Ok(f32::NEG_INFINITY),
            Ok(2.0),
        ];
        let result = sum_valid_readings_const(readings);
        assert!(result.is_some());
        let sum = result.unwrap();
        assert!(sum.is_nan()); // NAN + anything = NAN
    }
}

