#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_input() {
        let data: &[u8] = &[];
        let result = encode_rotated_bytes(data, 5);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_zero_shift() {
        let data = [0b10110010, 0b11001100];
        let result = encode_rotated_bytes(&data, 0);
        assert_eq!(result, vec![0b10110010, 0b11001100]);
    }

    #[test]
    fn test_small_shift() {
        let data = [0b10110010, 0b11001100];
        let result = encode_rotated_bytes(&data, 3);
        assert_eq!(result, vec![0b01010110, 0b10011001]);
    }

    #[test]
    fn test_full_rotation() {
        let data = [0b10110010, 0b11001100];
        let result = encode_rotated_bytes(&data, 8);
        assert_eq!(result, vec![0b10110010, 0b11001100]);
    }

    #[test]
    fn test_multiple_rotations() {
        let data = [0b10110010, 0b11001100];
        let result = encode_rotated_bytes(&data, 16);
        assert_eq!(result, vec![0b10110010, 0b11001100]);
    }

    #[test]
    fn test_large_shift() {
        let data = [0b10110010, 0b11001100];
        let result = encode_rotated_bytes(&data, 11);
        let expected = encode_rotated_bytes(&data, 3); // 11 % 8 = 3
        assert_eq!(result, expected);
    }

    #[test]
    fn test_all_ones() {
        let data = [0b11111111, 0b11111111];
        let result = encode_rotated_bytes(&data, 5);
        assert_eq!(result, vec![0b11111111, 0b11111111]);
    }

    #[test]
    fn test_all_zeros() {
        let data = [0b00000000, 0b00000000];
        let result = encode_rotated_bytes(&data, 7);
        assert_eq!(result, vec![0b00000000, 0b00000000]);
    }

    #[test]
    fn test_single_byte() {
        let data = [0b10010110];
        let result = encode_rotated_bytes(&data, 2);
        assert_eq!(result, vec![0b10100101]);
    }

    #[test]
    fn test_shift_greater_than_byte_size() {
        let data = [0b10110010, 0b11001100];
        let shift = 8 + 3; // 11
        let result = encode_rotated_bytes(&data, shift);
        let expected = encode_rotated_bytes(&data, 3);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_various_shifts_same_data() {
        let data = [0b10101010, 0b01010101, 0b11110000, 0b00001111];

        for shift in 0..=16 {
            let result = encode_rotated_bytes(&data, shift);
            let expected_shift = shift % 8;
            let expected: Vec<u8> = data.iter()
                .map(|&byte| byte.rotate_right(expected_shift))
                .collect();
            assert_eq!(result, expected, "Failed for shift = {}", shift);
        }
    }

    #[test]
    fn test_identity_after_full_rotations() {
        let data = [0b10110010, 0b11001100, 0b11111111, 0b00000000, 0b01010101];

        for multiple in 0..5 {
            let shift = multiple * 8;
            let result = encode_rotated_bytes(&data, shift);
            assert_eq!(result, data.to_vec(), "Failed for shift = {}", shift);
        }
    }

    #[test]
    fn test_symmetry() {
        let data = [0b10110010, 0b11001100, 0b11110000];
        let shift = 3;

        // Rotate right by shift
        let rotated = encode_rotated_bytes(&data, shift);
        // Rotate left by shift (equivalent to rotating right by 8-shift)
        let restored = encode_rotated_bytes(&rotated, 8 - shift);

        assert_eq!(restored, data.to_vec());
    }
}

