use std::collections::VecDeque;

fn rotate_log_buffer(buffer: &mut VecDeque<String>, positions: usize) -> Result<(), &'static str> {
    if positions > buffer.len() {
        return Err("Rotation amount exceeds buffer length");
    }

    if positions == 0 || positions == buffer.len() {
        return Ok(());
    }

    buffer.rotate_right(positions);
    Ok(())
}

