use std::ops::Bound;

fn comfort_range(readings: &[i32], min_comfort_f: i32, max_comfort_f: i32) -> (Bound<i32>, Bound<i32>) {
    let min_comfort_c = ((min_comfort_f - 32) * 5) / 9;
    let max_comfort_c = ((max_comfort_f - 32) * 5) / 9;

    let start_idx = readings.partition_point(|&x| x < min_comfort_c);
    let end_idx = readings.partition_point(|&x| x <= max_comfort_c);

    let start_bound = if start_idx < readings.len() && readings[start_idx] <= max_comfort_c {
        Bound::Included(readings[start_idx])
    } else {
        Bound::Unbounded
    };

    let end_bound = if end_idx > 0 && readings[end_idx - 1] >= min_comfort_c {
        Bound::Included(readings[end_idx - 1])
    } else {
        Bound::Unbounded
    };

    (start_bound.map(|x| x), end_bound.map(|x| x))
}

