fn multiply_first_chunk(data: &mut [i32], factor: i32) -> Option<[i32; 4]> {
    data.first_chunk_mut::<4>().map(|chunk| {
        chunk.iter_mut().for_each(|x| *x *= factor);
        *chunk
    })
}

