fn process_last_three_and_update(slice: &mut [i32], update_value: i32) -> Option<i32> {
    let (init, last_three) = slice.split_last_chunk_mut::<3>()?;

    if let Some(first) = init.first_mut() {
        *first = update_value;
    }

    Some(last_three.iter().map(|&x| x * 2).sum())
}

