        assert_eq!(process_last_three_and_update(&mut slice, 42), None);
        assert_eq!(slice, [1]); // Should remain unchanged
    }

    #[test]
    fn test_two_elements() {
        let mut slice = [1, 2];
        assert_eq!(process_last_three_and_update(&mut slice, 42), None);
        assert_eq!(slice, [1, 2]); // Should remain unchanged
    }

    #[test]
    fn test_exactly_three_elements() {
        let mut slice = [1, 2, 3];
        // Sum of (1*2 + 2*2 + 3*2) = 12
        assert_eq!(process_last_three_and_update(&mut slice, 42), Some(12));
        // No initial portion to update when slice length is exactly 3
        assert_eq!(slice, [1, 2, 3]);
    }

    #[test]
    fn test_four_elements() {
