        let mut slice = [1, 2, 3, 4, 5, 6, 7];
        // Sum of (5*2 + 6*2 + 7*2) = 36
        assert_eq!(process_last_three_and_update(&mut slice, 99), Some(36));
        // First element should be updated to 99
        assert_eq!(slice, [99, 2, 3, 4, 5, 6, 7]);
    }

    #[test]
    fn test_negative_values() {
        let mut slice = [-1, -2, -3, -4];
        // Sum of (-2*2 + -3*2 + -4*2) = -18
        assert_eq!(process_last_three_and_update(&mut slice, -10), Some(-18));
        assert_eq!(slice, [-10, -2, -3, -4]);
    }

    #[test]
    fn test_mixed_values() {
        let mut slice = [0, -5, 10, 3, -2];
        // Sum of (10*2 + 3*2 + -2*2) = 22
        assert_eq!(process_last_three_and_update(&mut slice, 100), Some(22));
        assert_eq!(slice, [100, -5, 10, 3, -2]);
    }

