    fn test_update_value_zero() {
        let mut slice = [1, 2, 3, 4, 5];
        assert_eq!(process_last_three_and_update(&mut slice, 0), Some(24)); // (3*2 + 4*2 + 5*2) = 24
        assert_eq!(slice, [0, 2, 3, 4, 5]);
    }

