        let mut slice = [i32::MAX, i32::MIN, 0, 100, 200];
        // Sum of (0*2 + 100*2 + 200*2) = 600
        // Note: i32::MIN * 2 would overflow, but we're only processing last 3: [0, 100, 200]
        assert_eq!(process_last_three_and_update(&mut slice, 999), Some(600));
        assert_eq!(slice, [999, i32::MIN, 0, 100, 200]);
    }

