        assert_eq!(process_last_three_and_update(&mut slice, 10), Some(24)); // (3*2 + 4*2 + 5*2) = 24
        assert_eq!(slice, [10, 2, 3, 4, 5]);

        // Second call on modified slice
        assert_eq!(process_last_three_and_update(&mut slice, 20), Some(24)); // Still (3*2 + 4*2 + 5*2) = 24
        assert_eq!(slice, [20, 2, 3, 4, 5]);

        // Third call
        assert_eq!(process_last_three_and_update(&mut slice, 30), Some(24)); // Same calculation
        assert_eq!(slice, [30, 2, 3, 4, 5]);
    }

