    fn test_slice_from_vec() {
        let mut vec = vec![1, 2, 3, 4, 5];
        let slice = vec.as_mut_slice();

        assert_eq!(process_last_three_and_update(slice, 99), Some(24)); // (3*2 + 4*2 + 5*2) = 24
        assert_eq!(vec, [99, 2, 3, 4, 5]);
    }

    #[test]
    fn test_slice_from_array() {
        let mut array = [10, 20, 30, 40, 50, 60];

        assert_eq!(process_last_three_and_update(&mut array, 999), Some(300)); // (40*2 + 50*2 + 60*2) = 300
        assert_eq!(array, [999, 20, 30, 40, 50, 60]);
    }
