pub fn count_power_of_two_trailing_zeros(numbers: &[std::num::NonZeroU64]) -> usize {
    numbers.iter()
        .filter(|&&n| {
            let tz = n.trailing_zeros();
            tz != 0 && (tz & (tz - 1)) == 0
        })
        .count()
}

