        let a = NonZeroI32::new(8).unwrap();
        let b = NonZeroI32::new(-3).unwrap();
        let result = absolute_difference(a, b);
        assert_eq!(result.get(), 11);
    }

    #[test]
    fn test_reverse_order_same_result() {
        let a = NonZeroI32::new(15).unwrap();
        let b = NonZeroI32::new(7).unwrap();
        let result1 = absolute_difference(a, b);
        let result2 = absolute_difference(b, a);
        assert_eq!(result1.get(), result2.get());
    }

