    fn test_minimum_difference() {
        let a = NonZeroI32::new(1).unwrap();
        let b = NonZeroI32::new(-1).unwrap();
        let result = absolute_difference(a, b);
        assert_eq!(result.get(), 2);
    }

    #[test]
    fn test_large_numbers() {
        let a = NonZeroI32::new(i32::MAX).unwrap();
        let b = NonZeroI32::new(i32::MAX - 100).unwrap();
        let result = absolute_difference(a, b);
        assert_eq!(result.get(), 100);
    }

    #[test]
    fn test_result_always_nonzero() {
        // Test that the result is never zero for various inputs
        let test_cases = [
            (1, 2),
            (-1, -2),
            (1, -1),
            (100, -100),
            (i32::MAX, i32::MAX - 1),
            (i32::MIN + 1, i32::MIN + 2),
        ];

        for (x, y) in test_cases {
            let a = NonZeroI32::new(x).unwrap();
            let b = NonZeroI32::new(y).unwrap();
            let result = absolute_difference(a, b);
            assert_ne!(result.get(), 0, "Result should never be zero for inputs {} and {}", x, y);
        }
    }

    #[test]
    fn test_const_evaluation() {
        // Verify the function can be evaluated at compile time
        // Use NonZeroI32::new_unchecked to avoid const unwrap issues
        const A: NonZeroI32 = unsafe { NonZeroI32::new_unchecked(42) };
        const B: NonZeroI32 = unsafe { NonZeroI32::new_unchecked(17) };
        const RESULT: NonZeroI32 = absolute_difference(A, B);

        assert_eq!(RESULT.get(), 25);
    }

    #[test]
    fn test_edge_cases_near_zero() {
        // Test numbers close to zero (but not zero since NonZeroI32)
        let a = NonZeroI32::new(1).unwrap();
        let b = NonZeroI32::new(2).unwrap();
        let result = absolute_difference(a, b);
        assert_eq!(result.get(), 1);

        let a = NonZeroI32::new(-1).unwrap();
        let b = NonZeroI32::new(-2).unwrap();
        let result = absolute_difference(a, b);
        assert_eq!(result.get(), 1);
    }

    #[test]
    fn test_symmetry_property() {
        // |a - b| = |b - a|
        let a = NonZeroI32::new(50).unwrap();
        let b = NonZeroI32::new(-30).unwrap();

        let diff1 = absolute_difference(a, b);
        let diff2 = absolute_difference(b, a);

        assert_eq!(diff1.get(), diff2.get());
    }
}

