use std::num::{NonZeroI32, NonZeroU32};

pub fn abs_diff_nonzero(a: NonZeroI32, b: NonZeroI32) -> NonZeroU32 {
    let diff = a.get().wrapping_sub(b.get());
    let abs_diff = diff.wrapping_abs() as u32;

    // Since both inputs are non-zero, their absolute difference cannot be zero
    unsafe { NonZeroU32::new_unchecked(abs_diff) }
}

