        let a = NonZeroI32::new(i32::MIN + 1).unwrap();
        let b = NonZeroI32::new(1).unwrap();
        let result = abs_diff_nonzero(a, b);
        assert_eq!(result.get(), i32::MAX as u32 + 1);
    }

    #[test]
    fn test_i32_max_case() {
        let a = NonZeroI32::new(i32::MAX).unwrap();
        let b = NonZeroI32::new(1).unwrap();
        let result = abs_diff_nonzero(a, b);
        assert_eq!(result.get(), i32::MAX as u32 - 1);
    }

    #[test]
    fn test_commutative_property() {
        let a = NonZeroI32::new(42).unwrap();
        let b = NonZeroI32::new(17).unwrap();

        let result1 = abs_diff_nonzero(a, b);
        let result2 = abs_diff_nonzero(b, a);

        assert_eq!(result1, result2);
    }

    #[test]
    fn test_identity_property() {
        let a = NonZeroI32::new(7).unwrap();
        let result = abs_diff_nonzero(a, a);
        assert_eq!(result.get(), 0);
    }

    #[test]
    fn test_edge_cases() {
        // Test various edge cases
        let test_cases = vec![
            (1, 2, 1),
            (2, 1, 1),
            (-1, -2, 1),
            (-2, -1, 1),
            (1, -1, 2),
            (-1, 1, 2),
        ];

        for (x, y, expected) in test_cases {
            let a = NonZeroI32::new(x).unwrap();
            let b = NonZeroI32::new(y).unwrap();
            let result = abs_diff_nonzero(a, b);
            assert_eq!(result.get(), expected as u32);
        }
    }

    #[test]
    fn test_result_is_nonzero() {
        // The function should always return NonZeroU32
        // This is guaranteed by the unsafe block, but we test it
        let a = NonZeroI32::new(100).unwrap();
        let b = NonZeroI32::new(50).unwrap();
        let result = abs_diff_nonzero(a, b);

        // This should not panic
        let _ = NonZeroU32::new(result.get()).unwrap();
    }

    // Removed the test_const_evaluable test since the function
    // uses wrapping operations which are not const in Rust 1.71.0
}

