pub fn send_messages_to_peer(
    socket: &std::os::unix::net::UnixDatagram,
    addr: &std::os::unix::net::SocketAddr,
    messages: &[&[u8]],
) -> std::io::Result<usize> {
    socket.connect_addr(addr)?;

    let mut sent_count = 0;
    for message in messages {
        match socket.send(message) {
            Ok(_) => sent_count += 1,
            Err(e) => return Err(e),
        }
    }

    Ok(sent_count)
}

