    #[test]
    fn test_sum_without_checks_basic() {
        assert_eq!(sum_without_checks(0, 0), 0);
        assert_eq!(sum_without_checks(1, 2), 3);
        assert_eq!(sum_without_checks(100, 200), 300);
        assert_eq!(sum_without_checks(u32::MAX, 0), u32::MAX);
        assert_eq!(sum_without_checks(0, u32::MAX), u32::MAX);
    }

    #[test]
    fn test_sum_without_checks_commutative() {
        let pairs = [(5u32, 10u32), (123u32, 456u32), (999u32, 1u32), (0xFFFFu32, 0xFFFFu32)];

        for &(a, b) in &pairs {
            assert_eq!(
                sum_without_checks(a, b),
                sum_without_checks(b, a),
                "Commutative property failed for ({}, {})",
                a,
                b
            );
        }
    }

    #[test]
    fn test_sum_without_checks_associative() {
        let triplets = [(1u32, 2u32, 3u32), (10u32, 20u32, 30u32), (100u32, 200u32, 300u32)];

        for &(a, b, c) in &triplets {
            let sum_ab = sum_without_checks(a, b);
            let left = sum_without_checks(sum_ab, c);

            let sum_bc = sum_without_checks(b, c);
            let right = sum_without_checks(a, sum_bc);

            assert_eq!(
                left, right,
                "Associative property failed for ({}, {}, {})",
                a, b, c
            );
        }
    }

    #[test]
    fn test_sum_without_checks_identity() {
        for i in 0u32..=1000 {
            assert_eq!(sum_without_checks(i, 0), i, "Zero identity failed for {}", i);
        }
    }

    #[test]
    fn test_sum_without_checks_edge_cases() {
        // Test with values that would overflow if bounds weren't known
        // These are valid since the function assumes bounds prevent overflow
        assert_eq!(sum_without_checks(u32::MAX - 1, 1), u32::MAX);
        assert_eq!(sum_without_checks(u32::MAX - 100, 100), u32::MAX);
        assert_eq!(sum_without_checks(1, u32::MAX - 1), u32::MAX);
    }

    #[test]
    fn test_sum_without_checks_consistency_with_checked_add() {
        // Verify that for a range of values, the result matches checked_add
        // when checked_add doesn't overflow
        for a in 0u32..=1000 {
            for b in 0u32..=1000 {
                if let Some(expected) = a.checked_add(b) {
                    assert_eq!(
                        sum_without_checks(a, b),
                        expected,
                        "Mismatch with checked_add for ({}, {})",
                        a,
                        b
                    );
                }
            }
        }
    }

