                offset += n as u64;
            }
            Err(ref e) if e.is_interrupted() => {}
            Err(e) => return Err(e),
        }
    }
    if !buf.is_empty() {
        Err(io::const_io_error!(io::ErrorKind::UnexpectedEof, "failed to fill whole buffer",))
    } else {
