        fn new(data: Vec<u8>) -> Self {
            Self {
                data,
                read_attempts: 0,
                fail_after: None,
            }
        }

        fn with_partial_reads(mut self, fail_after: usize) -> Self {
            self.fail_after = Some(fail_after);
            self
        }
    }

    impl std::os::unix::fs::FileExt for MockFile {
        fn read_at(&self, buf: &mut [u8], offset: u64) -> std::io::Result<usize> {
            let offset = offset as usize;

            if offset >= self.data.len() {
                return Ok(0);
            }

            let bytes_available = self.data.len() - offset;
            let bytes_to_read = std::cmp::min(buf.len(), bytes_available);

            buf[..bytes_to_read].copy_from_slice(&self.data[offset..offset + bytes_to_read]);
            Ok(bytes_to_read)
        }

        fn write_at(&self, _buf: &[u8], _offset: u64) -> std::io::Result<usize> {
            unimplemented!()
        }
    }

    // Wrapper for Cursor to implement FileExt
    struct CursorWrapper<T>(Cursor<T>);

    impl<T: AsRef<[u8]>> std::os::unix::fs::FileExt for CursorWrapper<T> {
        fn read_at(&self, buf: &mut [u8], offset: u64) -> std::io::Result<usize> {
            let data = self.0.get_ref().as_ref();
            let offset = offset as usize;

            if offset >= data.len() {
                return Ok(0);
            }

            let bytes_available = data.len() - offset;
            let bytes_to_read = std::cmp::min(buf.len(), bytes_available);

            buf[..bytes_to_read].copy_from_slice(&data[offset..offset + bytes_to_read]);
            Ok(bytes_to_read)
        }

        fn write_at(&self, _buf: &[u8], _offset: u64) -> std::io::Result<usize> {
            unimplemented!()
        }
    }

    #[test]
    fn test_read_header_at_success() {
        let data = vec![0x01, 0x02, 0x03, 0x04, 0x05, 0x06];
        let mock_file = MockFile::new(data);
        let mut header = [0u8; 4];

        assert!(read_header_at(&mock_file, 0, &mut header).is_ok());
        assert_eq!(header, [0x01, 0x02, 0x03, 0x04]);
    }

    #[test]
    fn test_read_header_at_offset() {
        let data = vec![0x01, 0x02, 0x03, 0x04, 0x05, 0x06];
        let mock_file = MockFile::new(data);
        let mut header = [0u8; 3];

        assert!(read_header_at(&mock_file, 2, &mut header).is_ok());
        assert_eq!(header, [0x03, 0x04, 0x05]);
    }

    #[test]
    fn test_read_header_at_eof_error() {
        let data = vec![0x01, 0x02, 0x03];
        let mock_file = MockFile::new(data);
        let mut header = [0u8; 5]; // Larger than available data

        let result = read_header_at(&mock_file, 0, &mut header);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err().kind(), ErrorKind::UnexpectedEof);
    }

    #[test]
    fn test_read_header_at_large_offset() {
        let data = vec![0x01, 0x02, 0x03, 0x04, 0x05];
        let mock_file = MockFile::new(data);
        let mut header = [0u8; 2];

        // Offset beyond file size should result in EOF error
        let result = read_header_at(&mock_file, 100, &mut header);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err().kind(), ErrorKind::UnexpectedEof);
    }

    #[test]
    fn test_read_header_at_zero_length_buffer() {
        let data = vec![0x01, 0x02, 0x03];
        let mock_file = MockFile::new(data);
        let mut header = [0u8; 0]; // Empty buffer

        assert!(read_header_at(&mock_file, 0, &mut header).is_ok());
    }

    #[test]
    fn test_read_header_at_exact_fit() {
        let data = vec![0x01, 0x02, 0x03];
        let mock_file = MockFile::new(data);
        let mut header = [0u8; 3];

        assert!(read_header_at(&mock_file, 0, &mut header).is_ok());
        assert_eq!(header, [0x01, 0x02, 0x03]);
    }

    #[test]
    fn test_read_header_at_with_cursor() {
        let test_data = vec![0xAA, 0xBB, 0xCC, 0xDD, 0xEE];
        let cursor = CursorWrapper(Cursor::new(test_data));

        let mut header = [0u8; 3];
        assert!(read_header_at(&cursor, 1, &mut header).is_ok());
        assert_eq!(header, [0xBB, 0xCC, 0xDD]);
    }

    #[test]
    fn test_read_header_at_sparse_file_behavior() {
        // Test with a file that has gaps (simulated using Cursor)
