fn count_with_leading_zeros_in_range(data: &[u64], min_zeros: u32, max_zeros: u32) -> usize {
    data.iter()
        .filter(|&&x| {
            let zeros = x.leading_zeros();
            zeros >= min_zeros && zeros <= max_zeros
        })
        .count()
}

