#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_slice() {
        let data: [u64; 0] = [];
        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 64), 0);
        assert_eq!(count_with_leading_zeros_in_range(&data, 10, 20), 0);
    }

    #[test]
    fn test_single_element_all_zeros() {
        let data = [0u64];
        assert_eq!(count_with_leading_zeros_in_range(&data, 64, 64), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 63), 0);
        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 64), 1);
    }

    #[test]
    fn test_single_element_no_zeros() {
        let data = [1u64 << 63];
        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 0), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 1, 64), 0);
    }

    #[test]
    fn test_single_element_some_zeros() {
        let data = [1u64 << 32]; // 31 leading zeros (since bit 32 is set)
        assert_eq!(count_with_leading_zeros_in_range(&data, 31, 31), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 30, 31), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 31, 32), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 30), 0);
        assert_eq!(count_with_leading_zeros_in_range(&data, 32, 64), 0);
    }

    #[test]
    fn test_multiple_elements_various_zeros() {
        let data = [
            0u64,                    // 64 zeros
            1u64 << 63,              // 0 zeros
            1u64 << 32,              // 31 zeros
            1u64 << 16,              // 47 zeros
            0x0000_0000_FFFF_FFFFu64, // 32 zeros
        ];

        // All elements
        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 64), 5);

        // Only zero
        assert_eq!(count_with_leading_zeros_in_range(&data, 64, 64), 1);

        // No zeros case
        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 0), 1);

        // 31-32 zeros range
        assert_eq!(count_with_leading_zeros_in_range(&data, 31, 32), 2);

        // 47 zeros
        assert_eq!(count_with_leading_zeros_in_range(&data, 47, 47), 1);

        // Range covering none
        assert_eq!(count_with_leading_zeros_in_range(&data, 1, 29), 0);

        // Range covering some
        assert_eq!(count_with_leading_zeros_in_range(&data, 30, 33), 2);
    }

    #[test]
    fn test_edge_cases_zeros_range() {
        let data = [
            0u64,
            1u64,
            1u64 << 63,
            1u64 << 62,
            0x8000_0000_0000_0000u64 | 0x1, // MSB set plus LSB
        ];

        // Min > max should handle gracefully (return 0 for no matches)
        assert_eq!(count_with_leading_zeros_in_range(&data, 10, 5), 0);

        // Same min and max
        assert_eq!(count_with_leading_zeros_in_range(&data, 63, 63), 1); // value 1

        // Full range
        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 64), 5);
    }

    #[test]
    fn test_large_collection() {
        let data: Vec<u64> = (0..1000).map(|i| i as u64).collect();

        // Count numbers with at least 60 leading zeros (very small numbers)
        let count_small = count_with_leading_zeros_in_range(&data, 60, 64);
        // Numbers 0-15 have at least 60 leading zeros in 64-bit
        assert_eq!(count_small, 16);

        // Count numbers with 0 leading zeros (MSB set)
        let count_large = count_with_leading_zeros_in_range(&data, 0, 0);
        // In range 0-999, only numbers >= 2^63 would have MSB set, so none
        assert_eq!(count_large, 0);

        // Count numbers with exactly 54 leading zeros
        // Numbers with bits in positions 9-0 set have 54 leading zeros
        let count_54 = count_with_leading_zeros_in_range(&data, 54, 54);
        // This would be numbers 512-1023, but our max is 999
        assert_eq!(count_54, 488); // 1000 - 512 = 488
    }

    #[test]
    fn test_powers_of_two() {
        let mut data = Vec::new();
        for i in 0..64 {
            data.push(1u64 << i);
        }

        // Each power of two has exactly (63 - i) leading zeros
        for i in 0..64 {
            let expected_zeros = 63 - i;
            let count = count_with_leading_zeros_in_range(&data, expected_zeros, expected_zeros);
            assert_eq!(count, 1, "Failed for 2^{} with expected {} zeros", i, expected_zeros);
        }

        // Test range covering multiple powers
        assert_eq!(count_with_leading_zeros_in_range(&data, 60, 63), 4); // 2^0 through 2^3
        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 3), 4);   // 2^60 through 2^63
    }

    #[test]
    fn test_all_ones_patterns() {
        let data = [
            0xFFFF_FFFF_FFFF_FFFFu64, // 0 zeros
            0x7FFF_FFFF_FFFF_FFFFu64, // 1 zero
            0x3FFF_FFFF_FFFF_FFFFu64, // 2 zeros
            0x1FFF_FFFF_FFFF_FFFFu64, // 3 zeros
            0x0FFF_FFFF_FFFF_FFFFu64, // 4 zeros
        ];

        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 0), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 1, 1), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 2, 2), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 3, 3), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 4, 4), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 4), 5);
    }

    #[test]
    fn test_boundary_conditions() {
        // Test with u64::MAX and similar boundary values
        let data = [
            u64::MAX,           // 0 zeros
            u64::MAX >> 1,      // 1 zero
            u64::MAX >> 32,     // 32 zeros
            u64::MAX >> 63,     // 63 zeros
            1u64,               // 63 zeros
            0u64,               // 64 zeros
        ];

        assert_eq!(count_with_leading_zeros_in_range(&data, 0, 0), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 1, 1), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 32, 32), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 63, 63), 2);
        assert_eq!(count_with_leading_zeros_in_range(&data, 64, 64), 1);
        assert_eq!(count_with_leading_zeros_in_range(&data, 62, 64), 3);
    }
}

