#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, Barrier};
    use std::thread;

    #[test]
    fn test_get_server_config_returns_static_reference() {
        let config = get_server_config();
        // Verify it returns a reference with static lifetime
        let _static_ref: &'static ServerConfig = config;

        // Can store in static variable (compile-time check)
        static TEST_CONFIG: Option<&'static ServerConfig> = None;
        let _ = TEST_CONFIG;
    }

    #[test]
    fn test_config_is_initialized_only_once() {
        // Use a counter to track initialization
        static INIT_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

        // Temporarily replace the LazyLock with our own for testing
        struct TestConfig;

        let test_lazy = LazyLock::new(|| {
            INIT_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            TestConfig
        });

        // Access multiple times from same thread
        let _ = LazyLock::force(&test_lazy);
        let _ = LazyLock::force(&test_lazy);
        let _ = LazyLock::force(&test_lazy);

        assert_eq!(INIT_COUNT.load(std::sync::atomic::Ordering::SeqCst), 1);
    }

    #[test]
    fn test_thread_safe_concurrent_access() {
        const THREAD_COUNT: usize = 10;
        let barrier = Arc::new(Barrier::new(THREAD_COUNT));
        let config_pointers: Arc<std::sync::Mutex<Vec<usize>>> = 
            Arc::new(std::sync::Mutex::new(Vec::new()));

        let mut handles = vec![];

        for _ in 0..THREAD_COUNT {
            let barrier = Arc::clone(&barrier);
            let config_pointers = Arc::clone(&config_pointers);

            handles.push(thread::spawn(move || {
                barrier.wait(); // Synchronize all threads
                let config = get_server_config();
                let ptr = config as *const ServerConfig as usize;

                let mut pointers = config_pointers.lock().unwrap();
                pointers.push(ptr);
            }));
        }

        for handle in handles {
            handle.join().unwrap();
        }

        let pointers = config_pointers.lock().unwrap();
        // All threads should get the same pointer (same instance)
        let first_ptr = pointers[0];
        for &ptr in pointers.iter().skip(1) {
            assert_eq!(ptr, first_ptr, "All threads should get same config instance");
        }
    }

    #[test]
    fn test_config_accessible_from_multiple_threads() {
        let handles: Vec<_> = (0..5)
            .map(|i| {
                thread::spawn(move || {
                    let config = get_server_config();
                    // Verify we can access it (no panic)
                    let _config_ref = config as *const ServerConfig;
                    i // Return something to prove thread executed
                })
            })
            .collect();

        for (i, handle) in handles.into_iter().enumerate() {
            let result = handle.join().unwrap();
            assert_eq!(result, i, "Thread should have executed successfully");
        }
    }

    #[test]
    fn test_repeated_calls_return_same_reference() {
        let config1 = get_server_config();
        let config2 = get_server_config();
        let config3 = get_server_config();

        // All should be the same reference (same memory address)
        assert!(std::ptr::eq(config1, config2));
        assert!(std::ptr::eq(config2, config3));
        assert!(std::ptr::eq(config1, config3));
    }

    // Test that the function signature is correct
    #[test]
    fn test_function_signature() {
        // This is a compile-time test, but we can verify at runtime
        let config = get_server_config();

        // Verify it's actually a ServerConfig reference
        let _: &ServerConfig = config;

        // Verify it has static lifetime by storing in a variable
        // that requires static lifetime
        fn requires_static<T: 'static>(_t: T) {}
        requires_static(config);
    }

    #[test]
    fn test_no_race_conditions() {
        // This test stresses concurrent access
        let mut handles = vec![];
        let results = Arc::new(std::sync::Mutex::new(Vec::new()));

        for i in 0..20 {
            let results = Arc::clone(&results);
            handles.push(thread::spawn(move || {
                let config = get_server_config();
                let ptr = config as *const ServerConfig as usize;
                results.lock().unwrap().push((i, ptr));
            }));
        }

        for handle in handles {
            handle.join().unwrap();
        }

        let results = results.lock().unwrap();
        let first_ptr = results[0].1;
        for &(_, ptr) in results.iter().skip(1) {
            assert_eq!(ptr, first_ptr, "All concurrent accesses should get same instance");
        }
    }
}

