fn apply_alpha_filter(pixels: &[[u8; 4]], alpha_factor: f32) -> Vec<u8> {
    let flattened = pixels.as_flattened();
    let mut result = Vec::with_capacity(flattened.len());

    for chunk in flattened.chunks_exact(4) {
        let r = chunk[0];
        let g = chunk[1];
        let b = chunk[2];
        let a = (chunk[3] as f32 * alpha_factor).clamp(0.0, 255.0) as u8;

        result.extend_from_slice(&[r, g, b, a]);
    }

    result
}

