        let pixels = [[255, 100, 50, 255], [0, 0, 0, 255], [128, 128, 128, 255]];
        let result = apply_alpha_filter(&pixels, 1.0);

        let expected = vec![255, 100, 50, 255, 0, 0, 0, 255, 128, 128, 128, 255];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_alpha_filter_half_transparency() {
        let pixels = [[255, 100, 50, 200], [0, 0, 0, 100], [128, 128, 128, 50]];
        let result = apply_alpha_filter(&pixels, 0.5);

        // 200 * 0.5 = 100, 100 * 0.5 = 50, 50 * 0.5 = 25
        let expected = vec![255, 100, 50, 100, 0, 0, 0, 50, 128, 128, 128, 25];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_alpha_filter_zero_transparency() {
        let pixels = [[255, 100, 50, 255], [0, 0, 0, 100], [128, 128, 128, 50]];
        let result = apply_alpha_filter(&pixels, 0.0);

        let expected = vec![255, 100, 50, 0, 0, 0, 0, 0, 128, 128, 128, 0];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_alpha_filter_double_transparency_clamped() {
        let pixels = [[255, 100, 50, 200], [0, 0, 0, 150], [128, 128, 128, 100]];
        let result = apply_alpha_filter(&pixels, 2.0);

        // 200 * 2.0 = 400 -> clamped to 255
        // 150 * 2.0 = 300 -> clamped to 255
        // 100 * 2.0 = 200 -> stays 200
        let expected = vec![255, 100, 50, 255, 0, 0, 0, 255, 128, 128, 128, 200];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_alpha_filter_empty_input() {
        let pixels: [[u8; 4]; 0] = [];
        let result = apply_alpha_filter(&pixels, 0.5);

        assert_eq!(result, Vec::<u8>::new());
    }

    #[test]
    fn test_alpha_filter_single_pixel() {
        let pixels = [[255, 255, 255, 128]];
        let result = apply_alpha_filter(&pixels, 0.75);

        // 128 * 0.75 = 96
        let expected = vec![255, 255, 255, 96];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_alpha_filter_many_pixels() {
        let mut pixels = Vec::new();
        let mut expected = Vec::new();

        for i in 0..1000 {
            let r = (i % 256) as u8;
            let g = ((i + 64) % 256) as u8;
            let b = ((i + 128) % 256) as u8;
            let a = ((i + 192) % 256) as u8;

            pixels.push([r, g, b, a]);

            // Apply alpha factor of 0.25
            let new_a = (a as f32 * 0.25).clamp(0.0, 255.0) as u8;
            expected.extend_from_slice(&[r, g, b, new_a]);
        }

        let result = apply_alpha_filter(&pixels, 0.25);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_alpha_filter_fractional_alpha_values() {
        let pixels = [[255, 255, 255, 10], [255, 255, 255, 20], [255, 255, 255, 30]];
        let result = apply_alpha_filter(&pixels, 0.33);

        // 10 * 0.33 = 3.3 -> 3
        // 20 * 0.33 = 6.6 -> 6
        // 30 * 0.33 = 9.9 -> 9
        let expected = vec![255, 255, 255, 3, 255, 255, 255, 6, 255, 255, 255, 9];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_alpha_filter_rgb_unchanged() {
        let pixels = [[100, 150, 200, 255], [50, 100, 150, 128]];
        let result = apply_alpha_filter(&pixels, 0.5);

        // Verify RGB channels remain unchanged
        assert_eq!(result[0], 100); // R1
        assert_eq!(result[1], 150); // G1
        assert_eq!(result[2], 200); // B1
        assert_eq!(result[4], 50);  // R2
        assert_eq!(result[5], 100); // G2
        assert_eq!(result[6], 150); // B2
    }

    #[test]
    fn test_alpha_filter_result_length() {
        let pixels = [[255, 255, 255, 255]; 10];
        let result = apply_alpha_filter(&pixels, 0.5);

        // 10 pixels * 4 channels = 40 bytes
        assert_eq!(result.len(), 40);
    }
}

