#[cfg(test)]
mod tests {
    use super::*;
    use std::str;

    #[test]
    fn test_printable_ascii_unchanged() {
        // Printable ASCII characters (32-126) should remain unchanged
        for byte in 32..=126 {
            let escaped: Vec<u8> = debug_byte_escape(byte).collect();
            // Skip escape characters that will be escaped
            if byte != b'\\' && byte != b'\'' && byte != b'"' {
                assert_eq!(escaped.len(), 1, "Printable ASCII should not be escaped for byte: {}", byte);
                assert_eq!(escaped[0], byte, "Byte value should match input for byte: {}", byte);
            }
        }
    }

    #[test]
    fn test_common_escape_sequences() {
        let test_cases = vec![
            (b'\n', "\\n"),
            (b'\t', "\\t"),
            (b'\r', "\\r"),
            (b'\\', "\\\\"),
            (b'\'', "\\'"),
            (b'\"', "\\\""),
            (b'\0', "\\x00"),
        ];

        for (byte, expected) in test_cases {
            let escaped: Vec<u8> = debug_byte_escape(byte).collect();
            let escaped_str = str::from_utf8(&escaped).unwrap();
            assert_eq!(escaped_str, expected, "Failed for byte: {}", byte);
        }
    }

    #[test]
    fn test_hex_escapes_for_non_printable() {
        // Test some non-printable bytes that should be hex-escaped
        let test_cases = vec![
            (0x01, "\\x01"),
            (0x1F, "\\x1f"),
            (0x7F, "\\x7f"),
            (0xFF, "\\xff"),
        ];

        for (byte, expected) in test_cases {
            let escaped: Vec<u8> = debug_byte_escape(byte).collect();
            let escaped_str = str::from_utf8(&escaped).unwrap();
            assert_eq!(escaped_str, expected, "Failed for byte: 0x{:02x}", byte);
        }
    }

    #[test]
    fn test_iterator_properties() {
        // Verify the function returns a proper iterator
        let byte = b'\n';
        let mut iter = debug_byte_escape(byte);

        // Should have exactly 2 items for \n escape sequence
        assert_eq!(iter.next(), Some(b'\\'));
        assert_eq!(iter.next(), Some(b'n'));
        assert_eq!(iter.next(), None);
    }

    #[test]
    fn test_all_bytes() {
        // Comprehensive test for all possible byte values
        for byte in 0..=255 {
            let escaped: Vec<u8> = debug_byte_escape(byte).collect();

            // Should always produce valid UTF-8
            assert!(str::from_utf8(&escaped).is_ok(), 
                   "Failed for byte 0x{:02x}: produced invalid UTF-8", byte);

            // Should not be empty
            assert!(!escaped.is_empty(), 
                   "Failed for byte 0x{:02x}: produced empty output", byte);

            // For bytes that are single characters, verify length
            // Note: ascii::escape_default escapes \ and ' and " even though they're printable
            if (32..=126).contains(&byte) && byte != b'\\' && byte != b'\'' && byte != b'"' {
                assert_eq!(escaped.len(), 1, 
                          "Failed for byte 0x{:02x}: should be single character, got {:?}", 
                          byte, str::from_utf8(&escaped).unwrap());
            }
        }
    }

    #[test]
    fn test_chainable_in_iterator_pipelines() {
        // Test that the function works well in iterator chains
        let bytes = vec![b'H', b'\n', b'i', b'\t', b'!'];
        let result: Vec<u8> = bytes
            .into_iter()
            .flat_map(debug_byte_escape)
            .collect();

        let expected = b"H\\ni\\t!";
        assert_eq!(result, expected);
    }

    #[test]
    fn test_edge_cases() {
        // Test minimum and maximum byte values
        let min_escaped: Vec<u8> = debug_byte_escape(0x00).collect();
        let max_escaped: Vec<u8> = debug_byte_escape(0xFF).collect();

        assert_eq!(str::from_utf8(&min_escaped).unwrap(), "\\x00");
        assert_eq!(str::from_utf8(&max_escaped).unwrap(), "\\xff");
    }

    #[test]
    fn test_consistent_with_ascii_escape_default() {
        // Verify our wrapper matches the behavior of ascii::escape_default
        for byte in 0..=255 {
            let our_result: Vec<u8> = debug_byte_escape(byte).collect();
            let std_result: Vec<u8> = std::ascii::escape_default(byte).collect();
            assert_eq!(our_result, std_result, 
                      "Mismatch for byte 0x{:02x}", byte);
        }
    }
}

