pub fn convert_valid_codepoints(codepoints: &[u32]) -> Vec<char> {
    let mut result = Vec::with_capacity(codepoints.len());

    for &cp in codepoints {
        // SAFETY: Caller guarantees all code points are valid Unicode scalars
        unsafe {
            result.push(core::char::from_u32_unchecked(cp));
        }
    }

    result
}

