#[cfg(test)]
mod tests {
    use super::convert_valid_codepoints;

    #[test]
    fn test_empty_input() {
        let input: [u32; 0] = [];
        let result = convert_valid_codepoints(&input);
        assert!(result.is_empty());
    }

    #[test]
    fn test_single_valid_codepoint() {
        let input = [65]; // 'A'
        let result = convert_valid_codepoints(&input);
        assert_eq!(result.len(), 1);
        assert_eq!(result[0], 'A');
    }

    #[test]
    fn test_multiple_valid_codepoints() {
        let input = [65, 66, 67, 97, 98, 99]; // 'A', 'B', 'C', 'a', 'b', 'c'
        let result = convert_valid_codepoints(&input);
        let expected = vec!['A', 'B', 'C', 'a', 'b', 'c'];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_unicode_range() {
        let input = [
            0x41,           // Basic Latin 'A'
            0x3B1,          // Greek 'α'
            0x4E00,         // CJK '一'
            0x1F600,        // Emoji '😀'
            0x10FFFF,       // Maximum valid Unicode scalar
        ];
        let result = convert_valid_codepoints(&input);
        let expected = vec!['A', 'α', '一', '😀', '\u{10FFFF}'];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_boundary_values() {
        let input = [
            0x0000,         // Minimum valid
            0x007F,         // Last ASCII
            0x0080,         // First non-ASCII
            0x00FF,         // Last Latin-1 Supplement
            0x07FF,         // Last 2-byte UTF-8
            0x0800,         // First 3-byte UTF-8
            0xFFFF,         // Last Basic Multilingual Plane
            0x10000,        // First Supplementary Plane
            0x10FFFF,       // Maximum valid
        ];
        let result = convert_valid_codepoints(&input);
        let expected = vec![
            '\u{0}', '\u{7F}', '\u{80}', '\u{FF}',
            '\u{7FF}', '\u{800}', '\u{FFFF}', '\u{10000}', '\u{10FFFF}'
        ];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_large_input() {
        let input: Vec<u32> = (0x41..=0x5A).collect(); // 'A' to 'Z'
        let result = convert_valid_codepoints(&input);
        let expected: Vec<char> = ('A'..='Z').collect();
        assert_eq!(result, expected);
    }

    #[test]
    fn test_preserves_capacity() {
        let input = [65, 66, 67, 68, 69];
        let result = convert_valid_codepoints(&input);
        assert_eq!(result.len(), input.len());
        assert!(result.capacity() >= input.len());
    }

    #[test]
    fn test_surrogate_range_not_present() {
        // Note: This test documents that surrogate range (0xD800-0xDFFF) should not be in input
        // as they are invalid Unicode scalars. The function assumes valid input.
        let input = [
            0xD799,         // Just before surrogate range
            0xE000,         // Just after surrogate range
        ];
        let result = convert_valid_codepoints(&input);
        let expected = vec!['\u{D799}', '\u{E000}'];
        assert_eq!(result, expected);
    }

    #[test]
    fn test_mixed_scripts() {
        let input = [
            0x0041, // Latin 'A'
            0x0391, // Greek 'Α'
            0x0410, // Cyrillic 'А'
            0x05D0, // Hebrew 'א'
            0x0627, // Arabic 'ا'
            0x3042, // Hiragana 'あ'
            0x4E00, // CJK '一'
        ];
