fn sort_and_get_median(data: &mut [i32]) -> Option<i32> {
    if data.is_empty() {
        return None;
    }

    data.sort_unstable();

    let len = data.len();
    if len % 2 == 1 {
        Some(data[len / 2])
    } else {
        let mid = len / 2;
        let median = (data[mid - 1] as i64 + data[mid] as i64) / 2;
        Some(median as i32)
    }
}

