    }

    #[test]
    fn test_no_memory_leaks() {
        let node = Node::create_self_referential_node();
        let weak_ref = Arc::downgrade(&node);

        drop(node);

        // Weak count should eventually go to zero after all strong references are dropped
        // This is implicitly tested by the fact that weak_ref.upgrade() returns None
        assert!(weak_ref.upgrade().is_none());
    }

    #[test]
    fn test_weak_pointer_accessible_immediately() {
        // The main point of new_cyclic is to provide the weak pointer before full initialization
        let node = Node::create_self_referential_node();

        // Immediately after creation, the weak pointer should work
        assert!(node.weak_self.upgrade().is_some());

        // The weak pointer should be the one that was provided during construction
        let upgraded = node.weak_self.upgrade().unwrap();
        assert!(Arc::ptr_eq(&node, &upgraded));
    }

    #[test]
    fn test_strong_count_behavior() {
        let node = Node::create_self_referential_node();
        assert_eq!(Arc::strong_count(&node), 1);

        let cloned = Arc::clone(&node);
        assert_eq!(Arc::strong_count(&node), 2);
        assert_eq!(Arc::strong_count(&cloned), 2);

        drop(cloned);
        assert_eq!(Arc::strong_count(&node), 1);
    }

    #[test]
    fn test_weak_count_behavior() {
        let node = Node::create_self_referential_node();
        assert_eq!(Arc::weak_count(&node), 1); // The internal weak_self counts

        let weak_external = Arc::downgrade(&node);
        assert_eq!(Arc::weak_count(&node), 2);

        drop(weak_external);
        assert_eq!(Arc::weak_count(&node), 1);
    }
}

