mod tests {
    use super::create_register_pointer;
    use std::ptr;

    #[test]
    fn test_null_pointer_zero_offset() {
        let base = ptr::null_mut();
        let result = create_register_pointer(base, 0);
        assert_eq!(result, ptr::null_mut());
    }

    #[test]
    fn test_valid_pointer_zero_offset() {
        let mut dummy: u32 = 0xDEADBEEF;
        let base = &mut dummy as *mut u32;
        let result = create_register_pointer(base, 0);
        assert_eq!(result, base);
    }

    #[test]
    fn test_register_offset_calculation() {
        let dummy: [u32; 4] = [0x11111111, 0x22222222, 0x33333333, 0x44444444];
        let base = dummy.as_ptr() as *mut u32;

        let register1 = create_register_pointer(base, 1);
        let register2 = create_register_pointer(base, 2);
        let register3 = create_register_pointer(base, 3);

        unsafe {
            assert_eq!(*register1, 0x22222222);
            assert_eq!(*register2, 0x33333333);
            assert_eq!(*register3, 0x44444444);
        }
    }

    #[test]
    fn test_large_register_offset() {
        let mut dummy: u32 = 0x12345678;
        let base = &mut dummy as *mut u32;

        // Test with offset that would overflow in normal arithmetic
        let large_offset = usize::MAX / 4;
        let result = create_register_pointer(base, large_offset);

        // Verify the address calculation
        let expected_addr = (base as usize).wrapping_add(large_offset.wrapping_mul(4));
        assert_eq!(result as usize, expected_addr);
    }

    #[test]
    fn test_offset_wrapping_behavior() {
        let dummy: u32 = 0xAAAAAAAA;
        let base = &dummy as *const u32 as *mut u32;

        // Test wrapping behavior with usize::MAX
        let max_offset = usize::MAX;
        let result = create_register_pointer(base, max_offset);

        let expected_addr = (base as usize).wrapping_add(max_offset.wrapping_mul(4));
        assert_eq!(result as usize, expected_addr);
    }

    #[test]
    fn test_pointer_provenance_preserved() {
        // Create a contiguous block of memory
        let mut buffer: [u32; 8] = [0; 8];
        for (i, elem) in buffer.iter_mut().enumerate() {
            *elem = i as u32;
        }

        let base = buffer.as_mut_ptr();

        // Test multiple offsets within the same allocation
        for offset in 0..8 {
            let register_ptr = create_register_pointer(base, offset);

            unsafe {
                // Verify we can read through the pointer
                let value = *register_ptr;
                assert_eq!(value, offset as u32);

                // Verify we can write through the pointer
                *register_ptr = (offset * 2) as u32;
                assert_eq!(buffer[offset], (offset * 2) as u32);
            }
        }
    }

    #[test]
    fn test_mutable_operations_through_pointer() {
        let mut buffer: [u32; 4] = [0x11111111, 0x22222222, 0x33333333, 0x44444444];
        let base = buffer.as_mut_ptr();

        let register_ptr = create_register_pointer(base, 2);

        unsafe {
            // Test read
            assert_eq!(*register_ptr, 0x33333333);

            // Test write
            *register_ptr = 0x55555555;
            assert_eq!(buffer[2], 0x55555555);

            // Test read after write
            assert_eq!(*register_ptr, 0x55555555);
        }
    }

    #[test]
    fn test_alignment_preservation() {
        // Create an aligned buffer
        let mut buffer: [u32; 4] = [0; 4];
        let base = buffer.as_mut_ptr();

        // All resulting pointers should maintain u32 alignment
        for offset in 0..4 {
            let register_ptr = create_register_pointer(base, offset);
            assert_eq!(register_ptr as usize % std::mem::align_of::<u32>(), 0);
        }
    }

    #[test]
    fn test_edge_case_offsets() {
        let dummy: u32 = 0xFFFFFFFF;
        let base = &dummy as *const u32 as *mut u32;

        // Test various edge cases
        let test_cases = [
            (0, base as usize),
            (1, (base as usize).wrapping_add(4)),
            (usize::MAX, (base as usize).wrapping_add(usize::MAX.wrapping_mul(4))),
            (usize::MAX / 2, (base as usize).wrapping_add((usize::MAX / 2).wrapping_mul(4))),
        ];

        for (offset, expected_addr) in test_cases {
            let result = create_register_pointer(base, offset);
            assert_eq!(result as usize, expected_addr);
        }
    }
}

