#[cfg(test)]
mod tests {
    use super::*;
    use std::thread;
    use std::time::Duration;
    use std::sync::{Arc, atomic::{AtomicBool, Ordering}};

    #[test]
    fn test_empty_handles() {
        let handles: Vec<thread::JoinHandle<()>> = vec![];
        let thread_ids = collect_active_thread_ids(&handles);
        assert!(thread_ids.is_empty());
    }

    #[test]
    fn test_single_thread() {
        let handle = thread::spawn(|| {
            // Simple thread that does nothing
        });

        let handles = vec![handle];
        let thread_ids = collect_active_thread_ids(&handles);

        assert_eq!(thread_ids.len(), 1);

        // Clean up
        handles.into_iter().for_each(|h| h.join().unwrap());
    }

    #[test]
    fn test_multiple_threads() {
        let mut handles = Vec::new();

        for i in 0..5 {
            let handle = thread::spawn(move || {
                // Each thread does some minimal work
                let _ = i * 2;
            });
            handles.push(handle);
        }

        let thread_ids = collect_active_thread_ids(&handles);

        assert_eq!(thread_ids.len(), 5);

        // All thread IDs should be unique
        let unique_ids: std::collections::HashSet<_> = thread_ids.iter().collect();
        assert_eq!(unique_ids.len(), 5);

        // Clean up
        handles.into_iter().for_each(|h| h.join().unwrap());
    }

    #[test]
    fn test_mixed_active_threads() {
        let stop_flag = Arc::new(AtomicBool::new(false));
        let mut handles = Vec::new();

        // Create 3 long-running threads
        for _ in 0..3 {
            let flag = stop_flag.clone();
            let handle = thread::spawn(move || {
                while !flag.load(Ordering::Relaxed) {
                    thread::sleep(Duration::from_millis(10));
                }
            });
            handles.push(handle);
        }

        // Create 2 short-lived threads that finish immediately
        for _ in 0..2 {
            let handle = thread::spawn(|| {
                // Thread finishes immediately
            });
            handles.push(handle);
        }

        // Wait for short threads to finish
        thread::sleep(Duration::from_millis(50));

        let thread_ids = collect_active_thread_ids(&handles);

        // Should still get 5 thread IDs even though some threads may have finished
        assert_eq!(thread_ids.len(), 5);

        // Stop long-running threads
        stop_flag.store(true, Ordering::Relaxed);

        // Clean up
        for handle in handles {
            let _ = handle.join();
        }
    }

    #[test]
    fn test_thread_ids_are_correct() {
        let (tx, rx) = std::sync::mpsc::channel();

        let handle = thread::spawn(move || {
            let thread_id = thread::current().id();
            tx.send(thread_id).unwrap();
        });

        let expected_id = rx.recv().unwrap();
        let handles = vec![handle];
        let collected_ids = collect_active_thread_ids(&handles);

        assert_eq!(collected_ids.len(), 1);
        assert_eq!(collected_ids[0], expected_id);

        handles.into_iter().for_each(|h| h.join().unwrap());
    }

    #[test]
    fn test_handles_from_different_scopes() {
        let mut all_handles = Vec::new();

        // Create threads in different scopes
        {
            let handle = thread::spawn(|| {});
            all_handles.push(handle);
        }

        {
            let handle = thread::spawn(|| {});
            all_handles.push(handle);
        }

        let thread_ids = collect_active_thread_ids(&all_handles);
        assert_eq!(thread_ids.len(), 2);

        // Clean up
        all_handles.into_iter().for_each(|h| h.join().unwrap());
    }
}

