        assert!(cstr.to_str().is_ok());
        assert_eq!(cstr.to_str().unwrap(), "valid utf8");
    }

    // Note: We cannot test invalid cases in unit tests because the function is unsafe
    // and requires the caller to guarantee the invariants. Testing invalid cases
    // would be undefined behavior.

    #[test]
    fn test_c_string_slice_range() {
        let all_bytes = b"prefix\0suffix";
        let cstr_slice = &all_bytes[0..7]; // "prefix\0"
        // SAFETY: cstr_slice is nul-terminated with no interior nul bytes
        let cstr = unsafe { bytes_to_cstr_unchecked(cstr_slice) };
        assert_eq!(cstr.to_bytes(), b"prefix");
    }
}

