mod tests {
    use super::immediate_successor;
    use std::f32;

    #[test]
    fn test_positive_normal_numbers() {
        // Test basic positive numbers
        assert_eq!(immediate_successor(1.0), 1.0000001);
        assert_eq!(immediate_successor(2.0), 2.0000002);
        assert_eq!(immediate_successor(100.0), 100.00001);

        // Test with fractional part
        assert_eq!(immediate_successor(3.1415927), 3.141593);
    }

    #[test]
    fn test_negative_normal_numbers() {
        // Test basic negative numbers
        assert_eq!(immediate_successor(-1.0), -0.99999994);
        assert_eq!(immediate_successor(-2.0), -1.9999999);
        assert_eq!(immediate_successor(-100.0), -99.99999);
    }

    #[test]
    fn test_zero() {
        // Test positive zero
        assert_eq!(immediate_successor(0.0), f32::from_bits(1));
        assert!(immediate_successor(0.0).is_sign_positive());

        // Test negative zero
        assert_eq!(immediate_successor(-0.0), f32::from_bits(1));
        assert!(immediate_successor(-0.0).is_sign_positive());
    }

    #[test]
    fn test_special_values() {
        // Test infinity
        assert!(immediate_successor(f32::INFINITY).is_infinite());
        assert!(immediate_successor(f32::INFINITY).is_sign_positive());

        // Test negative infinity
        assert_eq!(immediate_successor(f32::NEG_INFINITY), f32::MIN);

        // Test NaN - should return NaN
        let result = immediate_successor(f32::NAN);
        assert!(result.is_nan());
    }

    #[test]
    fn test_boundary_values() {
        // Test maximum positive normal
        assert_eq!(immediate_successor(f32::MAX), f32::INFINITY);

        // Test minimum positive normal
        assert!(immediate_successor(f32::MIN_POSITIVE) > f32::MIN_POSITIVE);

        // Test maximum negative normal
        assert!(immediate_successor(-f32::MIN_POSITIVE) > -f32::MIN_POSITIVE);
    }

    #[test]
    fn test_subnormal_numbers() {
        // Test smallest positive subnormal
        let smallest_subnormal = f32::from_bits(1);
        let next_from_smallest = immediate_successor(smallest_subnormal);
        assert_eq!(next_from_smallest, f32::from_bits(2));

        // Test largest subnormal
        let largest_subnormal = f32::from_bits(0x007FFFFF);
        let next_from_largest = immediate_successor(largest_subnormal);
        assert_eq!(next_from_largest, f32::MIN_POSITIVE);
    }

    #[test]
    fn test_powers_of_two() {
        // Test exact powers of two
        assert_eq!(immediate_successor(1.0), 1.0 + f32::EPSILON);
        assert_eq!(immediate_successor(2.0), 2.0 + 2.0 * f32::EPSILON);
        assert_eq!(immediate_successor(0.5), 0.5 + 0.5 * f32::EPSILON);
    }

    #[test]
    fn test_monotonicity() {
        // Verify the function is monotonic
        let values = [-100.0, -10.0, -1.0, -0.1, 0.0, 0.1, 1.0, 10.0, 100.0];

        for window in values.windows(2) {
            let a = window[0];
            let b = window[1];
            let succ_a = immediate_successor(a);
            let succ_b = immediate_successor(b);

            // If a < b, then succ_a <= succ_b
            assert!(succ_a <= succ_b || a.is_nan() || b.is_nan());
        }
    }

    #[test]
    fn test_round_trip_property() {
        // For normal numbers, predecessor of successor should return original
        let test_values = [1.0, 2.0, 3.14159, 100.0, -1.0, -2.0, -100.0];

        for &value in &test_values {
            let successor = immediate_successor(value);
            if successor.is_finite() && value.is_finite() {
                // Using next_down to get predecessor
                let predecessor = successor.next_down();
                assert_eq!(predecessor, value);
            }
        }
    }

    #[test]
    fn test_ulp_distance() {
        // Verify the successor is exactly 1 ULP away
        let test_values = [1.0, 2.0, 3.0, 0.5, 0.25, -1.0, -2.0];

        for &value in &test_values {
            let successor = immediate_successor(value);
            if value.is_finite() && successor.is_finite() {
                // Convert to bits and check difference is exactly 1
                let bits_value = value.to_bits();
                let bits_successor = successor.to_bits();

                // For positive numbers, successor has bits_value + 1
                // For negative numbers, successor has bits_value - 1
                if value >= 0.0 {
                    assert_eq!(bits_successor, bits_value + 1);
                } else {
                    assert_eq!(bits_successor, bits_value - 1);
                }
            }
        }
    }
}

