        let mut_refs = modify_disjoint_elements(&mut data, indices);

        *mut_refs[0] = 1000;
        *mut_refs[1] = 5000;
        *mut_refs[2] = 9000;

        assert_eq!(data[10], 1000);
        assert_eq!(data[50], 5000);
        assert_eq!(data[90], 9000);
    }

    #[test]
    fn test_modify_disjoint_elements_negative_values() {
        let mut data = vec![-5, -4, -3, -2, -1];
        let indices = [0, 2, 3];

        let mut_refs = modify_disjoint_elements(&mut data, indices);

        *mut_refs[0] = 5;
        *mut_refs[1] = 3;
        *mut_refs[2] = 2;

        assert_eq!(data, vec![5, -4, 3, 2, -1]);
    }

    #[test]
    fn test_modify_disjoint_elements_zero_values() {
        let mut data = vec![0; 10];
        let indices = [1, 5, 8];

        let mut_refs = modify_disjoint_elements(&mut data, indices);

        *mut_refs[0] = 42;
        *mut_refs[1] = 99;
        *mut_refs[2] = 77;

        assert_eq!(data[1], 42);
        assert_eq!(data[5], 99);
        assert_eq!(data[8], 77);
    }

    #[test]
    fn test_modify_disjoint_elements_consecutive_indices() {
        let mut data = vec![1, 2, 3, 4, 5, 6];
        let indices = [1, 2, 3];

        let mut_refs = modify_disjoint_elements(&mut data, indices);

        *mut_refs[0] = 20;
        *mut_refs[1] = 30;
        *mut_refs[2] = 40;

        assert_eq!(data, vec![1, 20, 30, 40, 5, 6]);
    }

    #[test]
    fn test_modify_disjoint_elements_mutability_preserved() {
        let mut data = vec![1, 2, 3, 4, 5];
        let indices = [0, 2, 4];

        let mut_refs = modify_disjoint_elements(&mut data, indices);

        // Test that we can modify through the references multiple times
        *mut_refs[0] += 1;
        *mut_refs[1] *= 2;
        *mut_refs[2] -= 1;

        *mut_refs[0] *= 10;
        *mut_refs[1] += 5;
        *mut_refs[2] = 0;

        assert_eq!(data, vec![20, 2, 11, 4, 0]);
    }

    #[test]
    fn test_modify_disjoint_elements_array_slice() {
        let mut array = [1, 2, 3, 4, 5];
        let indices = [0, 1, 4];

        let mut_refs = modify_disjoint_elements(&mut array, indices);

        *mut_refs[0] = 10;
        *mut_refs[1] = 20;
        *mut_refs[2] = 50;

        assert_eq!(array, [10, 20, 3, 4, 50]);
    }
}

