mod tests {
    use std::path::PathBuf;

    use super::validate_absolute_paths;

    #[test]
    fn test_empty_input() {
        let paths: Vec<PathBuf> = vec![];
        let result = validate_absolute_paths(&paths);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_all_absolute_paths() {
        let paths = vec![
            PathBuf::from("/usr/bin"),
            PathBuf::from("/"),
        ];
        let result = validate_absolute_paths(&paths);
        assert_eq!(result, vec![true, true]);

        // Windows paths - test separately since behavior is platform-specific
        #[cfg(windows)]
        {
            let windows_paths = vec![
                PathBuf::from("C:\\Windows\\System32"),
                PathBuf::from("C:\\"),
            ];
            let windows_result = validate_absolute_paths(&windows_paths);
            assert_eq!(windows_result, vec![true, true]);
        }

        // On non-Windows systems, Windows paths are considered relative
        #[cfg(not(windows))]
        {
            let windows_paths = vec![
                PathBuf::from("C:\\Windows\\System32"),
                PathBuf::from("C:\\"),
            ];
            let windows_result = validate_absolute_paths(&windows_paths);
            assert_eq!(windows_result, vec![false, false]);
        }
    }

    #[test]
    fn test_all_relative_paths() {
        let paths = vec![
            PathBuf::from("bin"),
            PathBuf::from("./config"),
            PathBuf::from("docs/readme.md"),
        ];
        let result = validate_absolute_paths(&paths);
        assert_eq!(result, vec![false, false, false]);

        // Windows-style relative path
        let windows_relative = PathBuf::from("..\\Windows");
        let windows_result = validate_absolute_paths(&[windows_relative]);
        assert_eq!(windows_result, vec![false]);
    }

    #[test]
    fn test_mixed_paths() {
        let paths = vec![
            PathBuf::from("/usr/bin"),
            PathBuf::from("local/bin"),
            PathBuf::from("/"),
            PathBuf::from("./current"),
        ];
        let result = validate_absolute_paths(&paths);
        assert_eq!(result, vec![true, false, true, false]);

        // Windows paths handled separately
        #[cfg(windows)]
        {
            let windows_paths = vec![
                PathBuf::from("C:\\Program Files"),
                PathBuf::from("..\\relative"),
            ];
            let windows_result = validate_absolute_paths(&windows_paths);
            assert_eq!(windows_result, vec![true, false]);
        }

        #[cfg(not(windows))]
        {
            let windows_paths = vec![
                PathBuf::from("C:\\Program Files"),
                PathBuf::from("..\\relative"),
            ];
            let windows_result = validate_absolute_paths(&windows_paths);
            assert_eq!(windows_result, vec![false, false]);
        }
    }

    #[test]
    fn test_unusual_absolute_paths() {
        // These tests are platform-specific
        #[cfg(windows)]
        {
            let paths = vec![
                PathBuf::from("\\\\?\\C:\\very\\long\\path"),
                PathBuf::from("\\\\.\\COM1"),
                PathBuf::from("//server/share"),
            ];
            let result = validate_absolute_paths(&paths);
            // On Windows, these should all be absolute
            assert_eq!(result, vec![true, true, true]);
        }

        #[cfg(not(windows))]
        {
            let paths = vec![
                PathBuf::from("\\\\?\\C:\\very\\long\\path"),
                PathBuf::from("\\\\.\\COM1"),
                PathBuf::from("//server/share"),
            ];
            let result = validate_absolute_paths(&paths);
            // On Unix-like systems, only the last one might be absolute
            // The exact behavior depends on the OS
            assert_eq!(result.len(), 3);
        }
    }

    #[test]
    fn test_paths_with_scheme_prefixes() {
        let paths = vec![
            PathBuf::from("file:///usr/bin"),
            PathBuf::from("http://example.com"),
            PathBuf::from("custom-scheme://data"),
        ];
        let result = validate_absolute_paths(&paths);
        // These should all be relative paths since PathBuf treats them as strings
        assert_eq!(result, vec![false, false, false]);
    }

    #[test]
    fn test_single_path() {
        let paths = vec![PathBuf::from("/single/path")];
        let result = validate_absolute_paths(&paths);
        assert_eq!(result, vec![true]);
    }

    #[test]
    fn test_current_and_parent_directory() {
        let paths = vec![
            PathBuf::from("."),
            PathBuf::from(".."),
            PathBuf::from("../.."),
        ];
        let result = validate_absolute_paths(&paths);
        assert_eq!(result, vec![false, false, false]);
    }

    #[test]
    fn test_paths_with_dots() {
        let paths = vec![
            PathBuf::from("/usr/./bin"),
            PathBuf::from("/usr/../bin"),
        ];
        let result = validate_absolute_paths(&paths);
        // These should be absolute regardless of dots
        assert_eq!(result, vec![true, true]);

        // Windows paths with dots
        #[cfg(windows)]
        {
            let windows_paths = vec![
                PathBuf::from("C:\\.\\Windows"),
                PathBuf::from("C:\\..\\Windows"),
            ];
            let windows_result = validate_absolute_paths(&windows_paths);
            assert_eq!(windows_result, vec![true, true]);
        }

        #[cfg(not(windows))]
        {
            let windows_paths = vec![
                PathBuf::from("C:\\.\\Windows"),
                PathBuf::from("C:\\..\\Windows"),
            ];
            let windows_result = validate_absolute_paths(&windows_paths);
            assert_eq!(windows_result, vec![false, false]);
        }
    }

    #[test]
    fn test_paths_with_spaces_and_special_chars() {
        let paths = vec![
            PathBuf::from("/usr/bin/program with spaces"),
            PathBuf::from("relative path with spaces"),
        ];
        let result = validate_absolute_paths(&paths);
        assert_eq!(result, vec![true, false]);

        // Windows path with spaces
        #[cfg(windows)]
        {
            let windows_path = PathBuf::from("C:\\Program Files (x86)");
            let windows_result = validate_absolute_paths(&[windows_path]);
            assert_eq!(windows_result, vec![true]);
        }

        #[cfg(not(windows))]
        {
            let windows_path = PathBuf::from("C:\\Program Files (x86)");
            let windows_result = validate_absolute_paths(&[windows_path]);
            assert_eq!(windows_result, vec![false]);
        }
    }

    #[test]
    fn test_unicode_paths() {
        let paths = vec![
            PathBuf::from("/usr/bin/ Café"),
            PathBuf::from("relative/ Café"),
        ];
        let result = validate_absolute_paths(&paths);
        assert_eq!(result, vec![true, false]);

        // Windows Unicode path
        #[cfg(windows)]
        {
            let windows_path = PathBuf::from("C:\\Tést\\文件.txt");
            let windows_result = validate_absolute_paths(&[windows_path]);
            assert_eq!(windows_result, vec![true]);
        }

        #[cfg(not(windows))]
        {
            let windows_path = PathBuf::from("C:\\Tést\\文件.txt");
            let windows_result = validate_absolute_paths(&[windows_path]);
            assert_eq!(windows_result, vec![false]);
        }
    }

    #[test]
    fn test_pathbuf_from_string() {
        let paths = vec![
            PathBuf::from("/usr/bin".to_string()),
            PathBuf::from("relative/path".to_string()),
        ];
        let result = validate_absolute_paths(&paths);
        assert_eq!(result, vec![true, false]);
    }

    #[test]
    fn test_repeated_calls() {
        let paths = vec![
            PathBuf::from("/usr/bin"),
            PathBuf::from("local/bin"),
        ];

        let result1 = validate_absolute_paths(&paths);
        let result2 = validate_absolute_paths(&paths);

        assert_eq!(result1, result2);
        assert_eq!(result1, vec![true, false]);
    }
}

