use std::fs::File;
use std::io::{self, Write};
use std::sync::{Arc, Mutex};

fn spawn_log_worker(original_handle: &File) -> io::Result<std::thread::JoinHandle<()>> {
    let cloned_handle = original_handle.try_clone()?;
    let shared_handle = Arc::new(Mutex::new(cloned_handle));

    let thread_handle = std::thread::spawn(move || {
        let log_entry = format!("Thread {:?} logging\n", std::thread::current().id());

        let mut guard = match shared_handle.lock() {
            Ok(guard) => guard,
            Err(poisoned) => poisoned.into_inner(),
        };

        let _ = guard.write_all(log_entry.as_bytes());
    });

    Ok(thread_handle)
}

