#[cfg(test)]
mod tests {
    use super::*;
    use std::fs::{self, File, OpenOptions};
    use std::io::{Read, Write, Seek, SeekFrom};
    use std::sync::Arc;
    use std::thread;
    use std::time::Duration;

    // Helper function to create a temporary test file
    fn create_temp_file() -> (String, File) {
        let temp_path = format!("./test_log_{}.txt", std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos());

        let file = OpenOptions::new()
            .create(true)
            .write(true)
            .append(true)
            .open(&temp_path)
            .unwrap();

        (temp_path, file)
    }

    // Cleanup helper
    fn cleanup_temp_file(path: &str) {
        let _ = fs::remove_file(path);
    }

    #[test]
    fn test_spawn_log_worker_successful_creation() {
        let (temp_path, original_handle) = create_temp_file();

        let result = spawn_log_worker(&original_handle);
        assert!(result.is_ok(), "Should successfully spawn log worker");

        let handle = result.unwrap();
        handle.join().expect("Thread should join successfully");

        cleanup_temp_file(&temp_path);
    }

    #[test]
    fn test_spawn_log_worker_clone_failure() {
        // Create a file and get a valid handle
        let (temp_path, original_handle) = create_temp_file();

        // try_clone() on a valid file should succeed
        let result = spawn_log_worker(&original_handle);
        assert!(result.is_ok(), "try_clone on valid file should succeed");

        if let Ok(handle) = result {
            handle.join().expect("Thread should join");
        }

        cleanup_temp_file(&temp_path);
    }

    #[test]
    fn test_single_worker_writes_log() {
        let (temp_path, original_handle) = create_temp_file();

        let worker_handle = spawn_log_worker(&original_handle)
            .expect("Failed to spawn worker");

        worker_handle.join().expect("Thread join failed");

        // Read file contents
        let mut contents = String::new();
        File::open(&temp_path)
            .unwrap()
            .read_to_string(&mut contents)
            .unwrap();

        assert!(!contents.is_empty(), "File should contain log entry");
        assert!(contents.contains("logging"), "Should contain expected log text");

        cleanup_temp_file(&temp_path);
    }

    #[test]
    fn test_multiple_workers_concurrent_writes() {
        let (temp_path, original_handle) = create_temp_file();
        let mut handles = Vec::new();

        // Spawn multiple workers
        for _ in 0..5 {
            let handle = spawn_log_worker(&original_handle)
                .expect("Failed to spawn worker");
            handles.push(handle);
        }

        // Wait for all threads to complete
        for handle in handles {
            handle.join().expect("Thread join failed");
        }

        // Read and verify file contents
        let mut contents = String::new();
        File::open(&temp_path)
            .unwrap()
            .read_to_string(&mut contents)
            .unwrap();

        // Count log entries
        let entry_count = contents.matches("logging").count();
        assert_eq!(entry_count, 5, "Should have 5 log entries");

        cleanup_temp_file(&temp_path);
    }

    #[test]
    fn test_thread_safety_with_mutex() {
        let (temp_path, original_handle) = create_temp_file();
        let shared_original = Arc::new(original_handle);
        let mut handles = Vec::new();

        // Spawn multiple workers that all use the same original handle
        for _ in 0..10 {
            let handle_ref = Arc::clone(&shared_original);
            let handle = thread::spawn(move || {
                // Each thread calls spawn_log_worker with the shared handle
                let worker = spawn_log_worker(&handle_ref).unwrap();
                worker.join().unwrap();
            });
            handles.push(handle);
        }

        for handle in handles {
            handle.join().expect("Thread join failed");
        }

        // Verify all writes completed without corruption
        let mut contents = String::new();
        File::open(&temp_path)
            .unwrap()
            .read_to_string(&mut contents)
            .unwrap();

        let entry_count = contents.matches("logging").count();
        assert_eq!(entry_count, 10, "Should have 10 log entries");

        cleanup_temp_file(&temp_path);
    }

    #[test]
    fn test_poisoned_mutex_recovery() {
        let (temp_path, original_handle) = create_temp_file();
        let cloned_handle = original_handle.try_clone().unwrap();
        let shared_handle = Arc::new(Mutex::new(cloned_handle));

        // Create a thread that will encounter potentially poisoned mutex
        let thread_handle = {
            let shared_handle = Arc::clone(&shared_handle);
            thread::spawn(move || {
                let log_entry = format!("Thread {:?} logging after poison\n", 
                    thread::current().id());

                let mut guard = match shared_handle.lock() {
                    Ok(guard) => guard,
                    Err(poisoned) => poisoned.into_inner(),
                };

                let _ = guard.write_all(log_entry.as_bytes());
            })
        };

        thread_handle.join().expect("Thread should handle poisoned mutex");

        cleanup_temp_file(&temp_path);
    }

    #[test]
    fn test_file_handle_independence() {
        let (temp_path, mut original_handle) = create_temp_file();

        // Get initial file size
        let initial_size = original_handle.metadata().unwrap().len();

        // Spawn worker
        let worker_handle = spawn_log_worker(&original_handle).unwrap();

        // Original handle should still be usable
        let test_data = b"Original handle write\n";
        original_handle.write_all(test_data).unwrap();
        original_handle.sync_all().unwrap();

        worker_handle.join().unwrap();

        // Verify both writes occurred
        let final_size = File::open(&temp_path)
            .unwrap()
            .metadata()
            .unwrap()
            .len();

        assert!(final_size > initial_size, "File should have grown");

        cleanup_temp_file(&temp_path);
    }

    #[test]
    fn test_high_concurrency_stress() {
        let (temp_path, original_handle) = create_temp_file();
        let mut handles = Vec::new();

        // Spawn many workers
        for _ in 0..50 {
            let handle = spawn_log_worker(&original_handle).unwrap();
            handles.push(handle);
        }

        // Join all with timeout to prevent hanging
        for handle in handles {
            handle.join().expect("Thread should complete");
        }

        // Verify all writes completed
        let contents = fs::read_to_string(&temp_path).unwrap();
        let entry_count = contents.matches("logging").count();
        assert_eq!(entry_count, 50, "Should have 50 log entries");

        cleanup_temp_file(&temp_path);
    }
}

