#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_safe_left_shift_basic() {
        // Basic shift operations
        assert_eq!(safe_left_shift(1, 0), 1);
        assert_eq!(safe_left_shift(1, 1), 2);
        assert_eq!(safe_left_shift(1, 2), 4);
        assert_eq!(safe_left_shift(1, 3), 8);
        assert_eq!(safe_left_shift(1, 63), 1u64 << 63);
    }

    #[test]
    fn test_safe_left_shift_with_non_one_base() {
        // Shifting values other than 1
        assert_eq!(safe_left_shift(3, 1), 6);    // 0b11 -> 0b110
        assert_eq!(safe_left_shift(5, 2), 20);   // 0b101 -> 0b10100
        assert_eq!(safe_left_shift(7, 3), 56);   // 0b111 -> 0b111000
        assert_eq!(safe_left_shift(0xFF, 8), 0xFF00);
    }

    #[test]
    fn test_safe_left_shift_zero_value() {
        // Shifting zero should always give zero
        assert_eq!(safe_left_shift(0, 0), 0);
        assert_eq!(safe_left_shift(0, 1), 0);
        assert_eq!(safe_left_shift(0, 10), 0);
        assert_eq!(safe_left_shift(0, 63), 0);
        assert_eq!(safe_left_shift(0, 64), 0);
        assert_eq!(safe_left_shift(0, u32::MAX), 0);
    }

    #[test]
    fn test_safe_left_shift_beyond_bit_width() {
        // Shifts beyond 64 bits should return zero
        assert_eq!(safe_left_shift(1, 64), 0);
        assert_eq!(safe_left_shift(1, 65), 0);
        assert_eq!(safe_left_shift(1, 100), 0);
        assert_eq!(safe_left_shift(u64::MAX, 64), 0);
        assert_eq!(safe_left_shift(0xFFFFFFFF, 64), 0);
    }

    #[test]
    fn test_safe_left_shift_max_shift_amount() {
        // Edge case with maximum shift amount
        assert_eq!(safe_left_shift(1, u32::MAX), 0);
        assert_eq!(safe_left_shift(u64::MAX, u32::MAX), 0);
        assert_eq!(safe_left_shift(0xAAAAAAAA, u32::MAX), 0);
    }

    #[test]
    fn test_safe_left_shift_max_value() {
        // Shifting maximum u64 value
        assert_eq!(safe_left_shift(u64::MAX, 0), u64::MAX);
        assert_eq!(safe_left_shift(u64::MAX, 1), u64::MAX << 1);
        assert_eq!(safe_left_shift(u64::MAX, 63), 1u64 << 63);
        assert_eq!(safe_left_shift(u64::MAX, 64), 0);
    }

    #[test]
    fn test_safe_left_shift_powers_of_two() {
        // Test with various powers of two
        for i in 0..64 {
            let value = 1u64 << i;
            for j in 0..64 {
                let expected = if i + j < 64 { 1u64 << (i + j) } else { 0 };
                assert_eq!(safe_left_shift(value, j as u32), expected);
            }
        }
    }

    #[test]
    fn test_safe_left_shift_const_context() {
        // Test that can be used in const context (compile-time)
        const SHIFT_RESULT_1: u64 = safe_left_shift(1, 3);
        const SHIFT_RESULT_2: u64 = safe_left_shift(0xFF, 8);
        const SHIFT_RESULT_3: u64 = safe_left_shift(u64::MAX, 64);

        assert_eq!(SHIFT_RESULT_1, 8);
        assert_eq!(SHIFT_RESULT_2, 0xFF00);
        assert_eq!(SHIFT_RESULT_3, 0);
    }

    #[test]
    fn test_safe_left_shift_patterns() {
        // Test with specific bit patterns
        assert_eq!(safe_left_shift(0xAAAAAAAAAAAAAAAA, 1), 0x5555555555555554);
        assert_eq!(safe_left_shift(0x5555555555555555, 1), 0xAAAAAAAAAAAAAAAA);
        assert_eq!(safe_left_shift(0xF0F0F0F0F0F0F0F0, 4), 0x0F0F0F0F0F0F0F00);
    }

    #[test]
    fn test_safe_left_shift_carry_bits() {
        // Test cases where shifting causes bits to be lost
        let value = 0x8000000000000001; // MSB and LSB set
        assert_eq!(safe_left_shift(value, 1), 0x0000000000000002); // MSB lost
        assert_eq!(safe_left_shift(value, 63), 0x8000000000000000); // LSB becomes MSB
        assert_eq!(safe_left_shift(value, 64), 0); // All bits lost
    }

    #[test]
    fn test_safe_left_shift_consistency() {
        // Verify consistency with standard shift for valid ranges
        for i in 0..64 {
            for j in 0..64 {
                let value = i as u64;
                let shift = j as u32;
                let expected = if shift < 64 { value << shift } else { 0 };
                assert_eq!(safe_left_shift(value, shift), expected);
            }
        }
    }
}

