#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_functionality() {
        // Create a buffer with 3-byte header and two 8-byte data blocks
        let mut buffer = vec![
            0x01, 0x02, 0x03, // Header (3 bytes)
            0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, // First data block
            0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27, // Second data block
        ];

        let (header, data_blocks) = process_packet_backwards(&mut buffer);

        // Verify header slice
        assert_eq!(header.len(), 3);
        assert_eq!(header, &[0x01, 0x02, 0x03]);

        // Verify data blocks
        assert_eq!(data_blocks.len(), 2);
        assert_eq!(data_blocks[0], [0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17]);
        assert_eq!(data_blocks[1], [0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27]);

        // Test that we can modify data blocks in reverse order
        for (i, block) in data_blocks.iter_mut().rev().enumerate() {
            for byte in block.iter_mut() {
                *byte = (i as u8) + 0x30;
            }
        }

        // Verify modifications
        assert_eq!(data_blocks[0], [0x31, 0x31, 0x31, 0x31, 0x31, 0x31, 0x31, 0x31]);
        assert_eq!(data_blocks[1], [0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30]);

        // Verify header remains unchanged
        assert_eq!(header, &[0x01, 0x02, 0x03]);
    }

    #[test]
    fn test_empty_data_blocks() {
        // Buffer with only header (less than 8 bytes total)
        let mut buffer = vec![0x01, 0x02, 0x03]; // 3-byte header only

        let (header, data_blocks) = process_packet_backwards(&mut buffer);

        assert_eq!(header.len(), 3);
        assert_eq!(header, &[0x01, 0x02, 0x03]);
        assert_eq!(data_blocks.len(), 0);
    }

    #[test]
    fn test_single_data_block() {
        // Buffer with header and exactly one data block
        let mut buffer = vec![
            0xAA, 0xBB, // 2-byte header
            0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, // One data block
        ];

        let (header, data_blocks) = process_packet_backwards(&mut buffer);

        assert_eq!(header.len(), 2);
        assert_eq!(header, &[0xAA, 0xBB]);
        assert_eq!(data_blocks.len(), 1);
        assert_eq!(data_blocks[0], [0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17]);

        // Modify the single data block
        data_blocks[0][0] = 0xFF;
        assert_eq!(data_blocks[0][0], 0xFF);
    }

    #[test]
    fn test_multiple_data_blocks() {
        // Buffer with 5-byte header and 3 data blocks
        let mut buffer = vec![0u8; 5 + 3 * 8];

        // Fill header
        for (i, byte) in buffer[0..5].iter_mut().enumerate() {
            *byte = i as u8;
        }

        // Fill data blocks
        for i in 0..3 {
            let start = 5 + i * 8;
            for j in 0..8 {
                buffer[start + j] = (i * 10 + j) as u8;
            }
        }

        let (header, data_blocks) = process_packet_backwards(&mut buffer);

        assert_eq!(header.len(), 5);
        assert_eq!(header, &[0, 1, 2, 3, 4]);
        assert_eq!(data_blocks.len(), 3);

        // Verify data block contents
        for i in 0..3 {
            let expected: Vec<u8> = (0..8).map(|j| (i * 10 + j) as u8).collect();
            assert_eq!(data_blocks[i], expected.as_slice());
        }
    }

    #[test]
    fn test_header_length_not_multiple_of_8() {
        // Test various header lengths that are not multiples of 8
        for header_len in 1..=7 {
            let total_len = header_len + 16; // header + 2 data blocks
            let mut buffer = vec![0u8; total_len];

            // Mark header bytes
            for i in 0..header_len {
                buffer[i] = 0xA0 + i as u8;
            }

            // Mark data block bytes
            for i in 0..16 {
                buffer[header_len + i] = 0xB0 + i as u8;
            }

            let (header, data_blocks) = process_packet_backwards(&mut buffer);

            assert_eq!(header.len(), header_len);
            assert_eq!(data_blocks.len(), 2);

            // Verify header bytes
            for i in 0..header_len {
                assert_eq!(header[i], 0xA0 + i as u8);
            }

            // Verify first data block
            for i in 0..8 {
                assert_eq!(data_blocks[0][i], 0xB0 + i as u8);
            }

            // Verify second data block
            for i in 0..8 {
                assert_eq!(data_blocks[1][i], 0xB0 + (i + 8) as u8);
            }
        }
    }

    #[test]
    fn test_modification_independence() {
        // Test that modifications to header and data blocks don't interfere
        let mut buffer = vec![0u8; 4 + 16]; // 4-byte header + 2 data blocks

        let (header, data_blocks) = process_packet_backwards(&mut buffer);

        // Modify header
        header.copy_from_slice(&[0xDE, 0xAD, 0xBE, 0xEF]);

        // Modify data blocks
        for (i, block) in data_blocks.iter_mut().enumerate() {
            block.fill(i as u8);
        }

        // Verify modifications are independent
        assert_eq!(header, &[0xDE, 0xAD, 0xBE, 0xEF]);
        assert_eq!(data_blocks[0], [0u8; 8]);
        assert_eq!(data_blocks[1], [1u8; 8]);
    }

    #[test]
    fn test_zero_length_buffer() {
        let mut buffer: Vec<u8> = vec![];

        let (header, data_blocks) = process_packet_backwards(&mut buffer);

        assert_eq!(header.len(), 0);
        assert_eq!(data_blocks.len(), 0);
    }

    #[test]
    fn test_large_buffer() {
        // Test with many data blocks
        let header_len = 7;
        let num_blocks = 100;
        let total_len = header_len + num_blocks * 8;

        let mut buffer = vec![0u8; total_len];

        // Fill with pattern
        for i in 0..total_len {
            buffer[i] = (i % 256) as u8;
        }

        let (header, data_blocks) = process_packet_backwards(&mut buffer);

        assert_eq!(header.len(), header_len);
        assert_eq!(data_blocks.len(), num_blocks);

        // Verify header
        for i in 0..header_len {
            assert_eq!(header[i], (i % 256) as u8);
        }

        // Verify data blocks
        for block_idx in 0..num_blocks {
            let start = header_len + block_idx * 8;
            for i in 0..8 {
                assert_eq!(data_blocks[block_idx][i], ((start + i) % 256) as u8);
            }
        }
    }
}

