        assert_eq!(chunks.next().map(|s| s.to_vec()), Some(vec![2]));
        assert_eq!(chunks.next().map(|s| s.to_vec()), Some(vec![1]));
        assert_eq!(chunks.next(), None);
    }

    #[test]
    fn test_chunk_size_larger_than_slice() {
