#[cfg(test)]
mod tests {
    use std::fs::{File, OpenOptions};
    use std::io;
    use std::io::Write;
    use std::path::Path;
    use std::thread;
    use std::time::Duration;
    use std::sync::{Arc, Barrier};
    use std::sync::atomic::{AtomicBool, Ordering};

    // Helper function to create a temporary file for testing
    fn create_temp_file() -> io::Result<File> {
        let temp_dir = std::env::temp_dir();
        let temp_file_path = temp_dir.join("test_config_lock.tmp");

        // Clean up any existing file
        let _ = std::fs::remove_file(&temp_file_path);

        OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .open(&temp_file_path)
    }

    #[test]
    fn test_acquire_exclusive_config_lock_success() {
        let mut file = create_temp_file().expect("Failed to create temp file");
        let result = super::acquire_exclusive_config_lock(&file);

        assert!(result.is_ok(), "Should successfully acquire lock");

        // Verify we can still write to the file while locked
        let write_result = writeln!(&mut file, "test data");
        assert!(write_result.is_ok(), "Should be able to write to locked file");
    }

    #[test]
    fn test_acquire_exclusive_config_lock_on_invalid_file() {
        // Create a file and close it to get an invalid reference
        let file = create_temp_file().expect("Failed to create temp file");
        drop(file); // File is now closed

        // Try to acquire lock on closed file - should fail
        let temp_dir = std::env::temp_dir();
        let temp_file_path = temp_dir.join("test_config_lock.tmp");
        let closed_file = File::open(&temp_file_path).expect("Failed to open file");

        // This test depends on OS behavior - some OS might allow this, some might not
        let result = super::acquire_exclusive_config_lock(&closed_file);
        // We can't assert specific behavior here as it's OS-dependent
        // Just ensure it doesn't panic
        let _ = result;
    }

    #[test]
    fn test_exclusive_lock_prevents_concurrent_access() {
        let temp_dir = std::env::temp_dir();
        let temp_file_path = temp_dir.join("test_exclusive_lock.tmp");

        // Clean up any existing file
        let _ = std::fs::remove_file(&temp_file_path);

        // Create the file
        let file1 = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .open(&temp_file_path)
            .expect("Failed to create temp file");

        // Acquire exclusive lock in main thread
        super::acquire_exclusive_config_lock(&file1)
            .expect("Failed to acquire lock in main thread");

        let file_path_clone = temp_file_path.clone();
        let lock_acquired = Arc::new(AtomicBool::new(false));
        let lock_acquired_clone = lock_acquired.clone();
        let barrier = Arc::new(Barrier::new(2));
        let barrier_clone = barrier.clone();

        let handle = thread::spawn(move || {
            // Try to acquire lock in another thread
            let file2 = OpenOptions::new()
                .read(true)
                .write(true)
                .open(&file_path_clone)
                .expect("Failed to open file in thread");

            // Signal we're ready to try
            barrier_clone.wait();

            // Try to acquire lock with timeout to prevent hanging
            let result = super::acquire_exclusive_config_lock(&file2);
            lock_acquired_clone.store(result.is_ok(), Ordering::SeqCst);
        });

        // Wait for thread to be ready
        barrier.wait();

        // Give the thread a short time to try to acquire the lock
        thread::sleep(Duration::from_millis(100));

        // Release the lock in main thread
        drop(file1);

        // Wait for thread to complete
        handle.join().expect("Thread should complete without panic");

        // The second thread should eventually succeed after we release
        assert!(lock_acquired.load(Ordering::SeqCst), 
                "Second thread should eventually acquire lock");
    }

    #[test]
    fn test_lock_persistence_across_file_operations() {
        let mut file = create_temp_file().expect("Failed to create temp file");

        // Acquire lock
        super::acquire_exclusive_config_lock(&file)
            .expect("Failed to acquire lock");

        // Perform multiple operations while locked
        writeln!(&mut file, "operation 1").expect("Failed to write");
        writeln!(&mut file, "operation 2").expect("Failed to write");
        writeln!(&mut file, "operation 3").expect("Failed to write");

        // All operations should succeed while lock is held
        assert!(true, "Should reach this point without lock issues");
    }

    #[test]
    fn test_acquire_lock_multiple_times_on_same_file() {
        let file = create_temp_file().expect("Failed to create temp file");

        // First acquisition should succeed
        let result1 = super::acquire_exclusive_config_lock(&file);
        assert!(result1.is_ok(), "First lock acquisition should succeed");

        // Second acquisition on same file handle - behavior is OS dependent
        let result2 = super::acquire_exclusive_config_lock(&file);
        // We can't assert specific behavior here as it's OS-dependent
        // Just ensure it doesn't panic
        let _ = result2;
    }

    #[test]
    fn test_lock_with_readonly_file() {
        let temp_dir = std::env::temp_dir();
        let temp_file_path = temp_dir.join("test_readonly_lock.tmp");

        // Clean up any existing file
        let _ = std::fs::remove_file(&temp_file_path);

        // Create and write to file
        {
            let mut file = File::create(&temp_file_path).expect("Failed to create file");
            writeln!(&mut file, "initial content").expect("Failed to write");
        }

        // Open as read-only
        let file = OpenOptions::new()
            .read(true)
            .open(&temp_file_path)
            .expect("Failed to open read-only file");

        // Try to acquire lock on read-only file
        let result = super::acquire_exclusive_config_lock(&file);

        // This might fail on some systems that require write access for locking
        // We can't assert specific behavior here as it's OS-dependent
        assert!(result.is_ok() || result.is_err(), 
                "Should either succeed or fail cleanly");
    }

    #[test]
    fn test_lock_cleanup_on_file_drop() {
        let temp_dir = std::env::temp_dir();
        let temp_file_path = temp_dir.join("test_lock_cleanup.tmp");

        // Clean up any existing file
        let _ = std::fs::remove_file(&temp_file_path);

        // Create first file and lock it
        let file1 = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .open(&temp_file_path)
            .expect("Failed to create file");

        super::acquire_exclusive_config_lock(&file1)
            .expect("Failed to acquire lock");

        // Drop the file (and presumably the lock)
        drop(file1);

        // Give OS time to release the lock
        thread::sleep(Duration::from_millis(100));

        // Try to create a new file handle and acquire lock
        let file2 = OpenOptions::new()
            .read(true)
            .write(true)
            .open(&temp_file_path)
            .expect("Failed to open file");

        let result = super::acquire_exclusive_config_lock(&file2);

        // This should succeed since the original file was dropped
        // Note: Some OS might have delayed lock release
        assert!(result.is_ok(), 
                "Should be able to acquire lock after original file is dropped");
    }
}

