mod tests {
    use super::configure_tcp_ack_behavior;
    use std::net::{TcpListener, TcpStream};
    use std::os::linux::net::TcpStreamExt;

    fn connected_pair() -> std::io::Result<(TcpStream, TcpStream)> {
        let listener = TcpListener::bind("127.0.0.1:0")?;
        let addr = listener.local_addr()?;
        let client = TcpStream::connect(addr)?;
        let (server, _) = listener.accept()?;
        Ok((client, server))
    }

    #[test]
    fn test_enable_immediate_ack() -> std::io::Result<()> {
        let (client, _server) = connected_pair()?;
        configure_tcp_ack_behavior(&client, true)?;
        assert!(client.quickack()?);
        Ok(())
    }

    #[test]
    fn test_disable_immediate_ack() -> std::io::Result<()> {
        let (client, _server) = connected_pair()?;
        configure_tcp_ack_behavior(&client, false)?;
        assert!(!client.quickack()?);
        Ok(())
    }

    #[test]
    fn test_toggle_ack_behavior() -> std::io::Result<()> {
        let (client, _server) = connected_pair()?;
        configure_tcp_ack_behavior(&client, true)?;
        assert!(client.quickack()?);
        configure_tcp_ack_behavior(&client, false)?;
        assert!(!client.quickack()?);
        Ok(())
    }

    #[test]
    fn test_idempotent_configuration() -> std::io::Result<()> {
        let (client, _server) = connected_pair()?;
        configure_tcp_ack_behavior(&client, true)?;
        configure_tcp_ack_behavior(&client, true)?;
        assert!(client.quickack()?);
        Ok(())
    }
}

