        assert_eq!(result.as_secs(), hours * 3600);
        assert_eq!(result.as_millis(), (hours as u128) * 3600 * 1000);
        assert_eq!(result.as_micros(), (hours as u128) * 3600 * 1_000_000);
        assert_eq!(result.as_nanos(), (hours as u128) * 3600 * 1_000_000_000);
