        assert_eq!(calculate_pixel_offset(0, 0, 100), 0);
        assert_eq!(calculate_pixel_offset(5, 0, 100), 5);
        assert_eq!(calculate_pixel_offset(0, 3, 100), 300);
        assert_eq!(calculate_pixel_offset(10, 20, 100), 2010);
        assert_eq!(calculate_pixel_offset(99, 49, 100), 4999);
    }

    #[test]
    fn test_negative_coordinates() {
        // Negative coordinates should work as long as multiplication doesn't overflow
        assert_eq!(calculate_pixel_offset(-5, 0, 100), -5);
        assert_eq!(calculate_pixel_offset(0, -3, 100), -300);
        assert_eq!(calculate_pixel_offset(-10, -20, 100), -2010);
        assert_eq!(calculate_pixel_offset(50, -2, 100), -150);
    }

    #[test]
    fn test_edge_width_values() {
        // Test with width = 1
        assert_eq!(calculate_pixel_offset(0, 100, 1), 100);
        assert_eq!(calculate_pixel_offset(0, -100, 1), -100);

        // Test with width = 0
        assert_eq!(calculate_pixel_offset(5, 10, 0), 5);
        assert_eq!(calculate_pixel_offset(-5, 10, 0), -5);

        // Test with width = -1
        assert_eq!(calculate_pixel_offset(5, 10, -1), -5);
        assert_eq!(calculate_pixel_offset(5, -10, -1), 15);
    }

    #[test]
    #[should_panic]
    fn test_multiplication_overflow_positive() {
        // y * width should panic when exceeding i32::MAX
        // Example: i32::MAX / 2 * 3 will overflow
        calculate_pixel_offset(0, i32::MAX / 2 + 1, 2);
    }

    #[test]
    #[should_panic]
    fn test_multiplication_overflow_negative() {
        // y * width should panic when exceeding i32::MIN
        // Example: i32::MIN * 2 will overflow
        calculate_pixel_offset(0, i32::MIN / 2 - 1, 2);
    }

    #[test]
    #[should_panic]
    fn test_multiplication_overflow_large_width() {
        // Large width causing overflow
        calculate_pixel_offset(0, 1000000, 1000000);
    }

    #[test]
    fn test_near_overflow_boundaries() {
        // Test values just below overflow thresholds
        assert_eq!(calculate_pixel_offset(0, 2147483, 1), 2147483); // i32::MAX / 1000 ≈ 2147483
        assert_eq!(calculate_pixel_offset(0, -2147483, 1), -2147483); // i32::MIN / 1000 ≈ -2147483

        // Test with x addition that doesn't cause overflow
        assert_eq!(calculate_pixel_offset(100, 2147483, 1), 2147583);
    }

    #[test]
    fn test_addition_overflow_scenarios() {
        // These should work because strict_mul panics on multiplication overflow,
        // but addition overflow in row_offset + x should still occur normally
        // (though the test query suggests we only care about multiplication overflow)

        // Valid multiplication but addition near max
        assert_eq!(calculate_pixel_offset(i32::MAX - 100, 1, 100), i32::MAX - 100 + 100);

        // Valid multiplication but addition near min
        assert_eq!(calculate_pixel_offset(i32::MIN + 100, 1, -100), i32::MIN + 100 - 100);
    }

    #[test]
    fn test_mixed_sign_combinations() {
        // Various combinations of positive and negative values
        assert_eq!(calculate_pixel_offset(10, 5, -100), -490);
        assert_eq!(calculate_pixel_offset(-10, 5, -100), -510);
        assert_eq!(calculate_pixel_offset(10, -5, -100), 510);
        assert_eq!(calculate_pixel_offset(-10, -5, -100), 490);
    }

    #[test]
    fn test_extreme_coordinate_values() {
        // Test with maximum and minimum coordinate values
        assert_eq!(calculate_pixel_offset(i32::MAX, 0, 1), i32::MAX);
        assert_eq!(calculate_pixel_offset(i32::MIN, 0, 1), i32::MIN);
        assert_eq!(calculate_pixel_offset(0, i32::MAX, 1), i32::MAX);
        assert_eq!(calculate_pixel_offset(0, i32::MIN, 1), i32::MIN);
    }

    #[test]
    fn test_zero_cases() {
        // Various zero combinations
        assert_eq!(calculate_pixel_offset(0, 0, 0), 0);
        assert_eq!(calculate_pixel_offset(0, 0, 100), 0);
        assert_eq!(calculate_pixel_offset(0, 0, -100), 0);
        assert_eq!(calculate_pixel_offset(0, 100, 0), 0);
        assert_eq!(calculate_pixel_offset(100, 0, 0), 100);
    }
}

