              without modifying the original"]
#[inline]
#[track_caller]
pub const fn strict_rem_euclid(self, rhs: Self) -> Self {
    let (a, b) = self.overflowing_rem_euclid(rhs);
    if b { overflow_panic::rem() } else { a }
}

