#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_positive_remainders() {
        // Basic positive cases
        assert_eq!(map_hash_to_index(10, 3), 1);
        assert_eq!(map_hash_to_index(7, 5), 2);
        assert_eq!(map_hash_to_index(100, 10), 0);
        assert_eq!(map_hash_to_index(15, 7), 1);
    }

    #[test]
    fn test_negative_hash_values() {
        // Negative hash values should still produce non-negative results
        assert_eq!(map_hash_to_index(-1, 5), 4);
        assert_eq!(map_hash_to_index(-10, 3), 2);
        assert_eq!(map_hash_to_index(-7, 5), 3);
        assert_eq!(map_hash_to_index(-15, 7), 6);
        assert_eq!(map_hash_to_index(-100, 10), 0);
    }

    #[test]
    fn test_edge_cases() {
        // Edge cases with hash = 0
        assert_eq!(map_hash_to_index(0, 5), 0);
        assert_eq!(map_hash_to_index(0, 1), 0);

        // Edge cases with table_size = 1
        assert_eq!(map_hash_to_index(10, 1), 0);
        assert_eq!(map_hash_to_index(-10, 1), 0);
        assert_eq!(map_hash_to_index(0, 1), 0);
    }

    #[test]
    fn test_large_values() {
        // Test with large values
        assert_eq!(map_hash_to_index(i32::MAX, 100), i32::MAX % 100);
        assert_eq!(map_hash_to_index(i32::MIN, 100), i32::MIN.rem_euclid(100));

        // Test with large table sizes
        assert_eq!(map_hash_to_index(1000, 999), 1);
        assert_eq!(map_hash_to_index(-1000, 999), 998);
    }

    #[test]
    fn test_result_range() {
        // Verify results are always in range [0, table_size)
        for hash in [-100, -50, -1, 0, 1, 50, 100] {
            for table_size in 1..=10 {
                let result = map_hash_to_index(hash, table_size);
                assert!(result >= 0, "Result should be non-negative, got {} for hash={}, table_size={}", result, hash, table_size);
                assert!(result < table_size, "Result should be less than table_size, got {} for hash={}, table_size={}", result, hash, table_size);
            }
        }
    }

    #[test]
    fn test_consistent_with_modulo_for_positive() {
        // For positive values, result should match standard modulo
        for hash in 0..=50 {
            for table_size in 1..=10 {
                let expected = hash % table_size;
                let actual = map_hash_to_index(hash, table_size);
                assert_eq!(actual, expected, "For positive hash={}, table_size={}", hash, table_size);
            }
        }
    }

    #[test]
    #[should_panic(expected = "remainder")]
    fn test_panic_on_zero_table_size() {
        // Should panic when table_size is 0
        map_hash_to_index(10, 0);
    }

    #[test]
    fn test_overflow_safety() {
        // Test cases that might trigger overflow in debug builds
        // These would panic in debug mode but work in release
        // We'll test that they at least don't panic with our current implementation

        // Note: We can't easily test debug vs release behavior in a single test,
        // but we can verify the function works for edge cases
        let _ = map_hash_to_index(i32::MIN, 1);
        let _ = map_hash_to_index(i32::MAX, 1);
    }

    #[test]
    fn test_property_based() {
        // Property-based style tests
        for table_size in 1..=20 {
            for hash_offset in -100..=100 {
                let hash = table_size * 10 + hash_offset;
                let result = map_hash_to_index(hash, table_size);

                // Property: (hash - result) should be divisible by table_size
                let diff = hash - result;
                assert_eq!(diff % table_size, 0, "hash={}, table_size={}, result={}", hash, table_size, result);

                // Property: result should be in [0, table_size)
                assert!(result >= 0 && result < table_size);
            }
        }
    }

    #[test]
    fn test_negative_table_size() {
        // Note: The spec doesn't specify behavior for negative table_size,
        // but rem_euclid handles it. We'll test the actual behavior.
        assert_eq!(map_hash_to_index(10, -5), 0);
        assert_eq!(map_hash_to_index(-10, -5), 0);
        assert_eq!(map_hash_to_index(7, -3), 1);
        assert_eq!(map_hash_to_index(-7, -3), 2);
    }
}

