#[cfg(test)]
mod tests {
    use super::euclidean_division;

    #[test]
    fn test_basic_euclidean_division() {
        // Basic cases
        assert_eq!(euclidean_division(10, 3), 3);
        assert_eq!(euclidean_division(10, 2), 5);
        assert_eq!(euclidean_division(0, 1), 0);
        assert_eq!(euclidean_division(1, 1), 1);
    }

    #[test]
    fn test_exact_division() {
        // Cases where dividend is exactly divisible by divisor
        assert_eq!(euclidean_division(15, 5), 3);
        assert_eq!(euclidean_division(100, 10), 10);
        assert_eq!(euclidean_division(u32::MAX, 1), u32::MAX);
    }

    #[test]
    fn test_remainder_cases() {
        // Cases with remainders
        assert_eq!(euclidean_division(7, 3), 2);
        assert_eq!(euclidean_division(17, 5), 3);
        assert_eq!(euclidean_division(99, 10), 9);
    }

    #[test]
    fn test_large_numbers() {
        // Test with large numbers
        assert_eq!(euclidean_division(u32::MAX, 2), 2147483647);
        assert_eq!(euclidean_division(u32::MAX, u32::MAX), 1);
        assert_eq!(euclidean_division(u32::MAX - 1, u32::MAX), 0);
    }

    #[test]
    fn test_edge_cases() {
        // Edge cases
        assert_eq!(euclidean_division(0, u32::MAX), 0);
        assert_eq!(euclidean_division(1, u32::MAX), 0);
        assert_eq!(euclidean_division(u32::MAX - 1, 2), 2147483647);
    }

    #[test]
    fn test_const_context() {
        // Verify the function can be used in const contexts
        const RESULT: u32 = euclidean_division(20, 4);
        assert_eq!(RESULT, 5);

        const LARGE_RESULT: u32 = euclidean_division(1000, 100);
        assert_eq!(LARGE_RESULT, 10);
    }

    #[test]
    #[should_panic(expected = "attempt to divide by zero")]
    fn test_division_by_zero_panics() {
        // Division by zero should panic
        let _ = euclidean_division(10, 0);
    }

    #[test]
    fn test_euclidean_property() {
        // Verify the Euclidean division property:
        // dividend = divisor * quotient + remainder, where 0 <= remainder < divisor
        let test_cases = [
            (10, 3),
            (7, 2),
            (15, 4),
            (0, 5),
            (1, 7),
            (u32::MAX, 2),
            (u32::MAX, 1000),
        ];

        for (dividend, divisor) in test_cases {
            let quotient = euclidean_division(dividend, divisor);
            let remainder = dividend - divisor * quotient;

            // Check Euclidean division property
            assert!(remainder < divisor, 
                   "Remainder {} should be less than divisor {} for dividend {}",
                   remainder, divisor, dividend);
            assert!(remainder >= 0, 
                   "Remainder should be non-negative");
        }
    }

    #[test]
    fn test_rounding_toward_negative_infinity() {
        // For unsigned integers, Euclidean division is the same as floor division
        // which rounds down toward negative infinity
        assert_eq!(euclidean_division(10, 3), 3); // 10/3 = 3.333..., floor = 3
        assert_eq!(euclidean_division(7, 3), 2);  // 7/3 = 2.333..., floor = 2
        assert_eq!(euclidean_division(2, 3), 0);  // 2/3 = 0.666..., floor = 0
    }

    #[test]
    fn test_property_based_style() {
        // Test various properties in a loop
        for divisor in 1..=100 {
            for dividend in 0..=1000 {
                let quotient = euclidean_division(dividend, divisor);
                let remainder = dividend - divisor * quotient;

                // Verify remainder is in [0, divisor)
                assert!(remainder < divisor);
                assert!(remainder >= 0);

                // Verify quotient is correct
                assert!(quotient <= dividend);
            }
        }
    }
}

