    fn test_large_values() {
        assert_eq!(reduce_to_field_element(100, 13), 9);  // 100 % 13 = 9
        assert_eq!(reduce_to_field_element(1000, 31), 8); // 1000 % 31 = 8
        assert_eq!(reduce_to_field_element(65536, 257), 1); // 65536 % 257 = 1
    }

