        assert_eq!(reduce_to_field_element(0, 1), 0);
        assert_eq!(reduce_to_field_element(1, 1), 0);
        assert_eq!(reduce_to_field_element(100, 1), 0);
        assert_eq!(reduce_to_field_element(u32::MAX, 1), 0);
    }

    #[test]
    fn test_modulus_max() {
        // When modulus is u32::MAX, any value less than modulus should remain unchanged
        assert_eq!(reduce_to_field_element(0, u32::MAX), 0);
        assert_eq!(reduce_to_field_element(1, u32::MAX), 1);
        assert_eq!(reduce_to_field_element(u32::MAX - 1, u32::MAX), u32::MAX - 1);
        // u32::MAX % u32::MAX = 0
        assert_eq!(reduce_to_field_element(u32::MAX, u32::MAX), 0);
    }

    #[test]
    fn test_edge_cases() {
        // Test with values just below, at, and just above modulus
        assert_eq!(reduce_to_field_element(14, 15), 14);
        assert_eq!(reduce_to_field_element(15, 15), 0);
        assert_eq!(reduce_to_field_element(16, 15), 1);

        // Test with values that wrap around multiple times
        assert_eq!(reduce_to_field_element(30, 15), 0);
        assert_eq!(reduce_to_field_element(31, 15), 1);
        assert_eq!(reduce_to_field_element(45, 15), 0);
    }

    #[test]
    fn test_const_context() {
        // Verify the function works in const context
        const RESULT: u32 = reduce_to_field_element(100, 13);
        assert_eq!(RESULT, 9);
    }

    #[test]
    fn test_property_based() {
        // Test that result is always less than modulus (when modulus > 0)
        let test_cases = vec![
            (0, 5),
            (1, 5),
            (4, 5),
            (5, 5),
            (6, 5),
            (10, 5),
            (100, 7),
            (u32::MAX / 2, 1000),
            (u32::MAX, 10000),
        ];

        for (value, modulus) in test_cases {
            if modulus > 0 {
                let result = reduce_to_field_element(value, modulus);
                assert!(result < modulus, 
                    "Result {} should be less than modulus {} for input ({}, {})",
                    result, modulus, value, modulus);
            }
        }
    }

    #[test]
    fn test_identity_property() {
        // If value < modulus, result should equal value
        assert_eq!(reduce_to_field_element(3, 10), 3);
        assert_eq!(reduce_to_field_element(9, 10), 9);
        assert_eq!(reduce_to_field_element(0, 10), 0);
    }

    #[test]
    fn test_distributive_property() {
        // (a + b) % m should equal ((a % m) + (b % m)) % m
        let a = 12345;
        let b = 67890;
        let m = 17;

        let left = reduce_to_field_element(a + b, m);
        let right = reduce_to_field_element(
            reduce_to_field_element(a, m) + reduce_to_field_element(b, m),
            m
        );

        assert_eq!(left, right);
    }

    #[test]
    fn test_powers_of_two_modulus() {
        // Test with moduli that are powers of two
        assert_eq!(reduce_to_field_element(10, 2), 0);  // 10 % 2 = 0
        assert_eq!(reduce_to_field_element(11, 2), 1);  // 11 % 2 = 1
        assert_eq!(reduce_to_field_element(10, 4), 2);  // 10 % 4 = 2
        assert_eq!(reduce_to_field_element(15, 8), 7);  // 15 % 8 = 7
        assert_eq!(reduce_to_field_element(255, 16), 15); // 255 % 16 = 15
    }

    #[test]
    fn test_prime_modulus() {
        // Test with prime numbers as modulus
        assert_eq!(reduce_to_field_element(20, 13), 7);    // 20 % 13 = 7
        assert_eq!(reduce_to_field_element(100, 17), 15);  // 100 % 17 = 15
        assert_eq!(reduce_to_field_element(255, 19), 8);   // 255 % 19 = 8
    }
}

source_code:
#[rustc_const_unstable(feature = "bigint_helper_methods", issue = "85532")]
#[must_use = "this returns the result of the operation, \
              without modifying the original"]
#[inline]
pub const fn borrowing_sub(self, rhs: Self, borrow: bool) -> (Self, bool) {
    // note: longer-term this should be done via an intrinsic, but this has been shown
    //   to generate optimal code for now, and LLVM doesn't have an equivalent intrinsic
    let (a, c1) = self.overflowing_sub(rhs);
    let (b, c2) = a.overflowing_sub(borrow as $SelfT);
    // SAFETY: Only one of `c1` and `c2` can be set.
    // For c1 to be set we need to have underflowed, but if we did then
    // `a` is nonzero, which means that `c2` cannot possibly
    // underflow because it's subtracting at most `1` (since it came from `bool`)
    (b, unsafe { intrinsics::disjoint_bitor(c1, c2) })
}

