test_program:
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_subtraction_no_borrow() {
        // Basic subtraction without incoming borrow
        assert_eq!(subtract_with_borrow(10, 3, false), (7, false));
        assert_eq!(subtract_with_borrow(100, 50, false), (50, false));
        assert_eq!(subtract_with_borrow(0, 0, false), (0, false));
    }

    #[test]
    fn test_basic_subtraction_with_borrow() {
        // Basic subtraction with incoming borrow
        assert_eq!(subtract_with_borrow(10, 3, true), (6, false));
        assert_eq!(subtract_with_borrow(100, 50, true), (49, false));
        assert_eq!(subtract_with_borrow(1, 0, true), (0, false));
    }

    #[test]
    fn test_borrow_generation_no_incoming_borrow() {
        // Cases where subtraction generates a borrow
        assert_eq!(subtract_with_borrow(5, 10, false), (u64::MAX - 4, true)); // 5 - 10 = -5
        assert_eq!(subtract_with_borrow(0, 1, false), (u64::MAX, true));
        assert_eq!(subtract_with_borrow(100, 200, false), (u64::MAX - 99, true));
    }

    #[test]
    fn test_borrow_generation_with_incoming_borrow() {
        // Cases where subtraction with incoming borrow generates another borrow
        assert_eq!(subtract_with_borrow(5, 10, true), (u64::MAX - 5, true)); // 5 - 10 - 1 = -6
        assert_eq!(subtract_with_borrow(0, 1, true), (u64::MAX - 1, true));
        assert_eq!(subtract_with_borrow(1, 1, true), (u64::MAX, true));
    }

    #[test]
    fn test_max_values() {
        // Edge cases with maximum u64 values
        assert_eq!(subtract_with_borrow(u64::MAX, 0, false), (u64::MAX, false));
        assert_eq!(subtract_with_borrow(u64::MAX, 0, true), (u64::MAX - 1, false));
        assert_eq!(subtract_with_borrow(u64::MAX, 1, false), (u64::MAX - 1, false));
        assert_eq!(subtract_with_borrow(u64::MAX, 1, true), (u64::MAX - 2, false));
        assert_eq!(subtract_with_borrow(u64::MAX, u64::MAX, false), (0, false));
        assert_eq!(subtract_with_borrow(u64::MAX, u64::MAX, true), (u64::MAX, true));
    }

    #[test]
    fn test_zero_values() {
        // Various combinations with zero
        assert_eq!(subtract_with_borrow(0, 0, false), (0, false));
        assert_eq!(subtract_with_borrow(0, 0, true), (u64::MAX, true));
        assert_eq!(subtract_with_borrow(0, 5, false), (u64::MAX - 4, true));
        assert_eq!(subtract_with_borrow(0, 5, true), (u64::MAX - 5, true));
        assert_eq!(subtract_with_borrow(5, 0, false), (5, false));
        assert_eq!(subtract_with_borrow(5, 0, true), (4, false));
    }

    #[test]
    fn test_chain_of_borrows() {
        // Simulate a chain of subtractions like in multi-precision arithmetic

        // First limb: 100 - 50 = 50, no borrow
        assert_eq!(subtract_with_borrow(100, 50, false), (50, false));

        // Second limb: using borrow from first (false) - 200 - 100 = 100, no borrow
        assert_eq!(subtract_with_borrow(200, 100, false), (100, false));

        // Third limb: 50 - 100 = -50, generates borrow
        assert_eq!(subtract_with_borrow(50, 100, false), (u64::MAX - 49, true));

        // Fourth limb: using borrow from third (true) - 100 - 50 = 49, no borrow
        assert_eq!(subtract_with_borrow(100, 50, true), (49, false));
    }

    #[test]
    fn test_property_based() {
        // Test the mathematical property: (lhs - rhs - borrow) mod 2^64
        // and borrow flag indicates if result would be negative in infinite precision

        for lhs in [0u64, 1, 100, u64::MAX / 2, u64::MAX - 1, u64::MAX].iter() {
            for rhs in [0u64, 1, 100, u64::MAX / 2, u64::MAX - 1, u64::MAX].iter() {
                for &borrow in [false, true].iter() {
                    let (result, new_borrow) = subtract_with_borrow(*lhs, *rhs, borrow);

                    // Calculate expected using 128-bit arithmetic to avoid overflow
                    let lhs_128 = *lhs as u128;
                    let rhs_128 = *rhs as u128;
                    let borrow_128 = borrow as u128;
                    let expected_128 = lhs_128.wrapping_sub(rhs_128).wrapping_sub(borrow_128);

                    // Lower 64 bits should match result
                    assert_eq!(result, expected_128 as u64);

                    // Borrow flag should be set if the full 128-bit result is negative
                    // (i.e., if the result would be negative in infinite precision)
                    let is_negative = expected_128 >= (1u128 << 64);
                    assert_eq!(new_borrow, is_negative);
                }
            }
        }
    }

    #[test]
    fn test_consistency_with_wrapping_sub() {
        // Verify consistency with wrapping_sub for the no-borrow case
        for lhs in [0u64, 1, 100, u64::MAX].iter() {
            for rhs in [0u64, 1, 100, u64::MAX].iter() {
                let (result, borrow) = subtract_with_borrow(*lhs, *rhs, false);
                let wrapped = lhs.wrapping_sub(*rhs);

                assert_eq!(result, wrapped);
                assert_eq!(borrow, *lhs < *rhs);
            }
        }
    }
}

