#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_no_overflow() {
        // Basic operation without any overflow
        assert_eq!(compute_mul_add_with_carry(2, 3, 4, 0), (10, 0));
        assert_eq!(compute_mul_add_with_carry(2, 3, 4, 1), (11, 0));
    }

    #[test]
    fn test_multiplication_overflow_only() {
        // Multiplication overflows but final result doesn't
        let max = u64::MAX;
        assert_eq!(compute_mul_add_with_carry(max, 2, 0, 0), (max.wrapping_sub(1), 1));

        // Verify the carry is correct: max * 2 = (max-1) with carry 1
        let (lo, carry) = compute_mul_add_with_carry(max, 2, 0, 0);
        assert_eq!(lo, max.wrapping_sub(1));
        assert_eq!(carry, 1);
    }

    #[test]
    fn test_addition_overflow_only() {
        // Addition overflows but multiplication doesn't
        let max = u64::MAX;
        assert_eq!(compute_mul_add_with_carry(1, 1, max, 0), (0, 1));

        // 1*1 + max + 0 = max+1 = 0 with carry 1
        let (lo, carry) = compute_mul_add_with_carry(1, 1, max, 0);
        assert_eq!(lo, 0);
        assert_eq!(carry, 1);
    }

    #[test]
    fn test_carry_in_overflow() {
        // Carry-in causes overflow
        let max = u64::MAX;
        assert_eq!(compute_mul_add_with_carry(1, 1, max, 1), (1, 1));

        // 1*1 + max + 1 = max+2 = 1 with carry 1
        let (lo, carry) = compute_mul_add_with_carry(1, 1, max, 1);
        assert_eq!(lo, 1);
        assert_eq!(carry, 1);
    }

    #[test]
    fn test_multiplication_and_addition_overflow() {
        // Both multiplication and addition overflow
        let max = u64::MAX;
        assert_eq!(compute_mul_add_with_carry(max, 2, max, 0), (max.wrapping_sub(2), 2));

        // max*2 + max = (max-1) + max with carry 1 from multiplication
        // = (max-2) with carry 2
        let (lo, carry) = compute_mul_add_with_carry(max, 2, max, 0);
        assert_eq!(lo, max.wrapping_sub(2));
        assert_eq!(carry, 2);
    }

    #[test]
    fn test_all_components_overflow() {
        // Multiplication, addition, and carry-in all cause overflow
        let max = u64::MAX;
        assert_eq!(compute_mul_add_with_carry(max, 2, max, 1), (max.wrapping_sub(1), 2));

        // max*2 + max + 1 = (max-1) + max + 1 with carry 1 from multiplication
        // = (max-1) with carry 2
        let (lo, carry) = compute_mul_add_with_carry(max, 2, max, 1);
        assert_eq!(lo, max.wrapping_sub(1));
        assert_eq!(carry, 2);
    }

    #[test]
    fn test_zero_values() {
        // All zeros
        assert_eq!(compute_mul_add_with_carry(0, 0, 0, 0), (0, 0));

        // Zero multiplication with non-zero addition
        assert_eq!(compute_mul_add_with_carry(0, 5, 10, 0), (10, 0));
        assert_eq!(compute_mul_add_with_carry(5, 0, 10, 0), (10, 0));

        // Zero addition with non-zero multiplication
        assert_eq!(compute_mul_add_with_carry(5, 5, 0, 0), (25, 0));

        // Zero with carry-in
        assert_eq!(compute_mul_add_with_carry(0, 0, 0, 1), (1, 0));
    }

    #[test]
    fn test_edge_cases() {
        let max = u64::MAX;
        let half_max = u64::MAX / 2;

        // Large values without overflow
        assert_eq!(compute_mul_add_with_carry(half_max, 2, 0, 0), (max - 1, 0));

        // Large values with overflow
        assert_eq!(compute_mul_add_with_carry(half_max + 1, 2, 0, 0), (0, 1));

        // Maximum carry propagation
        // max * max + max + max = (2^64 - 1)^2 + 2*(2^64 - 1) = 2^128 - 1
        // So low bits should be all 1s (max) and carry should be max
        let (lo, carry) = compute_mul_add_with_carry(max, max, max, max);
        assert_eq!(lo, max);
        assert_eq!(carry, max);
    }

    #[test]
    fn test_property_based() {
        // Test that the operation is equivalent to using 128-bit arithmetic
        for a in [0u64, 1, 2, 100, u64::MAX / 2, u64::MAX].iter() {
            for b in [0u64, 1, 2, 100, u64::MAX / 2, u64::MAX].iter() {
                for c in [0u64, 1, 2, 100, u64::MAX / 2, u64::MAX].iter() {
                    for carry_in in [0u64, 1, 2].iter() {
                        let (lo, carry) = compute_mul_add_with_carry(*a, *b, *c, *carry_in);

                        // Calculate using 128-bit arithmetic for verification
                        let a_128 = u128::from(*a);
                        let b_128 = u128::from(*b);
                        let c_128 = u128::from(*c);
                        let carry_in_128 = u128::from(*carry_in);

                        let total = a_128 * b_128 + c_128 + carry_in_128;
                        let expected_lo = total as u64;
                        let expected_carry = (total >> 64) as u64;

                        assert_eq!(lo, expected_lo);
                        assert_eq!(carry, expected_carry);
                    }
                }
            }
        }
    }

    #[test]
    fn test_symmetry() {
        // Test commutative property of multiplication
        let a = 123456789;
        let b = 987654321;
        let c = 555555555;
        let carry = 1;

        let result1 = compute_mul_add_with_carry(a, b, c, carry);
        let result2 = compute_mul_add_with_carry(b, a, c, carry);

        assert_eq!(result1, result2);
    }

    #[test]
    fn test_carry_accumulation() {
        // Test that carrying_mul_add correctly accumulates carries
        let max = u64::MAX;

        // This should produce maximum carry
        let (lo, carry) = compute_mul_add_with_carry(max, max, max, max);

        // max * max + max + max in 128-bit:
        // (2^64 - 1)^2 + 2*(2^64 - 1) = 2^128 - 1
        // So low bits should be all 1s (max) and carry should be max
        assert_eq!(lo, max);
        assert_eq!(carry, max);
    }
}

