use std::sync::atomic::{AtomicPtr, Ordering};

fn allocate_from_buffer(buffer: &AtomicPtr<u8>, size: usize) -> Option<*mut u8> {
    let prev_ptr = buffer.fetch_byte_add(size, Ordering::Relaxed);
    if prev_ptr.is_null() {
        None
    } else {
        Some(prev_ptr)
    }
}

