#[cfg(test)]
mod tests {
    use super::*;
    use std::ptr;
    use std::sync::atomic::AtomicPtr;
    use std::sync::Arc;
    use std::thread;

    #[test]
    fn test_allocate_from_buffer_basic() {
        let mut data = vec![0u8; 100];
        let buffer = AtomicPtr::new(data.as_mut_ptr());

        // First allocation
        let allocated = allocate_from_buffer(&buffer, 10);
        assert!(allocated.is_some());
        assert_eq!(allocated.unwrap(), data.as_mut_ptr());

        // Second allocation should be 10 bytes ahead
        let allocated2 = allocate_from_buffer(&buffer, 20);
        assert!(allocated2.is_some());
        let expected_ptr = unsafe { data.as_mut_ptr().add(10) };
        assert_eq!(allocated2.unwrap(), expected_ptr);
    }

    #[test]
    fn test_allocate_from_buffer_null() {
        let buffer = AtomicPtr::new(ptr::null_mut());

        let result = allocate_from_buffer(&buffer, 10);
        assert!(result.is_none());
    }

    #[test]
    fn test_allocate_from_buffer_concurrent() {
        const BUFFER_SIZE: usize = 1000;
        const ALLOCATION_SIZE: usize = 10;
        const NUM_THREADS: usize = 4;
        const ALLOCATIONS_PER_THREAD: usize = 10;

        let mut data = vec![0u8; BUFFER_SIZE];
        let buffer = Arc::new(AtomicPtr::new(data.as_mut_ptr()));

        let mut handles = vec![];

        for _ in 0..NUM_THREADS {
            let buffer_clone = Arc::clone(&buffer);
            let handle = thread::spawn(move || {
                let mut allocations = vec![];
                for _ in 0..ALLOCATIONS_PER_THREAD {
                    if let Some(ptr) = allocate_from_buffer(&buffer_clone, ALLOCATION_SIZE) {
                        allocations.push(ptr as usize);
                    }
                }
                allocations
            });
            handles.push(handle);
        }

        // Collect all allocations from all threads
        let mut all_allocations = vec![];
        for handle in handles {
            let thread_allocations = handle.join().unwrap();
            all_allocations.extend(thread_allocations);
        }

        // Verify we got the expected number of allocations
        assert_eq!(all_allocations.len(), NUM_THREADS * ALLOCATIONS_PER_THREAD);

        // Sort allocations to verify they're all unique and sequential
        all_allocations.sort();

        // Verify all allocations are within the buffer
        let buffer_start = data.as_mut_ptr() as usize;
        let buffer_end = buffer_start + BUFFER_SIZE;

        for allocation in &all_allocations {
            assert!(*allocation >= buffer_start);
            assert!(*allocation < buffer_end);

            // Verify alignment to allocation size
            let offset = allocation - buffer_start;
            assert_eq!(offset % ALLOCATION_SIZE, 0);
        }

        // Verify no duplicate allocations (should be impossible with fetch_add)
        for i in 1..all_allocations.len() {
            assert_ne!(all_allocations[i], all_allocations[i - 1]);
        }
    }

    #[test]
    fn test_allocate_from_buffer_multiple_calls() {
        let mut data = vec![0u8; 100];
        let buffer = AtomicPtr::new(data.as_mut_ptr());

        let mut prev_ptr = data.as_mut_ptr();

        for i in 0..10 {
            let size = (i + 1) * 5; // Different sizes each time
            let allocated = allocate_from_buffer(&buffer, size);
            assert!(allocated.is_some());
            assert_eq!(allocated.unwrap(), prev_ptr);

            // Update expected next pointer
            prev_ptr = unsafe { prev_ptr.add(size) };
        }
    }

    #[test]
    fn test_allocate_from_buffer_zero_size() {
        let mut data = vec![0u8; 100];
        let buffer = AtomicPtr::new(data.as_mut_ptr());

        // First allocation with zero size
        let allocated1 = allocate_from_buffer(&buffer, 0);
        assert!(allocated1.is_some());
        assert_eq!(allocated1.unwrap(), data.as_mut_ptr());

        // Second allocation should still be at the same position
        let allocated2 = allocate_from_buffer(&buffer, 0);
        assert!(allocated2.is_some());
        assert_eq!(allocated2.unwrap(), data.as_mut_ptr());
    }

    #[test]
    fn test_allocate_from_buffer_memory_safety() {
        // Test that we can actually write to the allocated memory
        let mut data = vec![0u8; 100];
        let buffer = AtomicPtr::new(data.as_mut_ptr());

        // Allocate and write to memory
        if let Some(ptr) = allocate_from_buffer(&buffer, 10) {
            unsafe {
                // Write test pattern
                for i in 0..10 {
                    *ptr.add(i) = (i as u8) + 1;
                }
            }
        }

        // Verify the write
        for i in 0..10 {
            assert_eq!(data[i], (i as u8) + 1);
        }
    }
}

