#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicPtr, Ordering};
    use std::ptr;

    #[test]
    fn test_atomic_set_flags_basic_operation() {
        let initial_ptr = Box::into_raw(Box::new(42u8));
        let atomic_ptr = AtomicPtr::new(initial_ptr);

        let mask = 0b1111;
        let result = atomic_set_flags(&atomic_ptr, mask, Ordering::SeqCst);

        assert_eq!(result, initial_ptr, "Should return original pointer");

        let current = atomic_ptr.load(Ordering::SeqCst);
        let expected = (initial_ptr as usize | mask) as *mut u8;
        assert_eq!(current, expected, "Flags should be set via bitwise OR");

        unsafe {
            let _ = Box::from_raw(initial_ptr);
        }
    }

    #[test]
    fn test_atomic_set_flags_all_ordering_semantics() {
        let initial_ptr = Box::into_raw(Box::new(0u8));
        let atomic_ptr = AtomicPtr::new(initial_ptr);

        let orderings = [
            Ordering::Relaxed,
            Ordering::Acquire,
            Ordering::Release,
            Ordering::AcqRel,
            Ordering::SeqCst,
        ];

        for &order in &orderings {
            let atomic_ptr_clone = AtomicPtr::new(initial_ptr);
            let mask = 0b1010;

            let result = atomic_set_flags(&atomic_ptr_clone, mask, order);
            assert_eq!(result, initial_ptr);

            let current = atomic_ptr_clone.load(Ordering::SeqCst);
            let expected = (initial_ptr as usize | mask) as *mut u8;
            assert_eq!(current, expected);
        }

        unsafe {
            let _ = Box::from_raw(initial_ptr);
        }
    }

    #[test]
    fn test_atomic_set_flags_multiple_operations() {
