        let atomic_ptr = AtomicPtr::new(initial_ptr);

        let mask1 = 0b0011;
        let mask2 = 0b1100;
        let mask3 = 0b1010;

        let result1 = atomic_set_flags(&atomic_ptr, mask1, Ordering::SeqCst);
        assert_eq!(result1, initial_ptr);

        let result2 = atomic_set_flags(&atomic_ptr, mask2, Ordering::SeqCst);
        let expected2 = (initial_ptr as usize | mask1) as *mut u8;
        assert_eq!(result2, expected2);

        let result3 = atomic_set_flags(&atomic_ptr, mask3, Ordering::SeqCst);
        let expected3 = (initial_ptr as usize | mask1 | mask2) as *mut u8;
        assert_eq!(result3, expected3);

        let current = atomic_ptr.load(Ordering::SeqCst);
        let expected = (initial_ptr as usize | mask1 | mask2 | mask3) as *mut u8;
        assert_eq!(current, expected);

        unsafe {
            let _ = Box::from_raw(initial_ptr);
        }
    }

    #[test]
    fn test_atomic_set_flags_with_null_pointer() {
        let atomic_ptr = AtomicPtr::new(ptr::null_mut());

        let mask = 0b0101;
        let result = atomic_set_flags(&atomic_ptr, mask, Ordering::SeqCst);

        assert!(result.is_null(), "Should return null pointer");

        let current = atomic_ptr.load(Ordering::SeqCst);
        let expected = (0usize | mask) as *mut u8;
        assert_eq!(current, expected);
