        let initial_ptr = Box::into_raw(Box::new(255u8));
        let atomic_ptr = AtomicPtr::new(initial_ptr);

        let full_mask = usize::MAX;
        let result = atomic_set_flags(&atomic_ptr, full_mask, Ordering::SeqCst);

        assert_eq!(result, initial_ptr);

        let current = atomic_ptr.load(Ordering::SeqCst);
        let expected = (initial_ptr as usize | full_mask) as *mut u8;
        assert_eq!(current, expected);

