        let initial_ptr = Box::into_raw(Box::new(10u8));
        let atomic_ptr = AtomicPtr::new(initial_ptr);

        let result = atomic_set_flags(&atomic_ptr, 0, Ordering::SeqCst);

        assert_eq!(result, initial_ptr);

        let current = atomic_ptr.load(Ordering::SeqCst);
        assert_eq!(current, initial_ptr, "Pointer should remain unchanged with zero mask");

        unsafe {
            let _ = Box::from_raw(initial_ptr);
        }
    }

    #[test]
    fn test_atomic_set_flags_concurrent_simulation() {
        let initial_ptr = Box::into_raw(Box::new(0u8));
        let atomic_ptr = AtomicPtr::new(initial_ptr);

        let masks = [0b0001, 0b0010, 0b0100, 0b1000];
        let mut results = Vec::new();

        for &mask in &masks {
            let result = atomic_set_flags(&atomic_ptr, mask, Ordering::SeqCst);
            results.push(result);
        }

        assert_eq!(results[0], initial_ptr);

        let current = atomic_ptr.load(Ordering::SeqCst);
        let all_masks = masks.iter().fold(0, |acc, &mask| acc | mask);
        let expected = (initial_ptr as usize | all_masks) as *mut u8;
        assert_eq!(current, expected);

        unsafe {
            let _ = Box::from_raw(initial_ptr);
        }
    }

    #[test]
    fn test_atomic_set_flags_pointer_arithmetic_consistency() {
        let base_ptr = Box::into_raw(Box::new(1u8));
        let offset = 0b11110000;

        let atomic_ptr = AtomicPtr::new(base_ptr.wrapping_add(offset));

        let mask = 0b00001111;
        let result = atomic_set_flags(&atomic_ptr, mask, Ordering::SeqCst);

        assert_eq!(result, base_ptr.wrapping_add(offset));

        let current = atomic_ptr.load(Ordering::SeqCst);
        let expected_ptr = base_ptr.wrapping_add(offset);
        let expected = (expected_ptr as usize | mask) as *mut u8;
        assert_eq!(current, expected);

