use std::sync::atomic::{AtomicPtr, Ordering};

fn clear_pointer_bits(ptr: &AtomicPtr<i32>, mask: usize) -> *mut i32 {
    // Invert the mask to clear bits: AND with !mask clears bits where mask has 1s
    ptr.fetch_and(!mask, Ordering::SeqCst)
}

