#[cfg(test)]
mod tests {
    use std::sync::atomic::{AtomicPtr, Ordering};
    use std::ptr;

    // Import the function to test (assuming it's in the parent module)
    use super::clear_pointer_bits;

    #[test]
    fn test_clear_pointer_bits_basic() {
        let value = 42;
        let ptr = &value as *const i32 as *mut i32;
        let atomic_ptr = AtomicPtr::new(ptr);

        // Clear the lowest bit
        let mask = 0b1;
        let result = clear_pointer_bits(&atomic_ptr, mask);

        // Original pointer should be returned
        assert_eq!(result, ptr);

        // Bits should be cleared in the stored pointer
        let stored = atomic_ptr.load(Ordering::SeqCst);
        assert_eq!(stored, (ptr as usize & !mask) as *mut i32);
    }

    #[test]
    fn test_clear_pointer_bits_multiple_bits() {
        let value = 100;
        let ptr = &value as *const i32 as *mut i32;
        let atomic_ptr = AtomicPtr::new(ptr);

        // Clear bits 0, 2, and 4
        let mask = 0b10101;
        let result = clear_pointer_bits(&atomic_ptr, mask);

        assert_eq!(result, ptr);

        let stored = atomic_ptr.load(Ordering::SeqCst);
        assert_eq!(stored, (ptr as usize & !mask) as *mut i32);
    }

    #[test]
    fn test_clear_pointer_bits_all_bits() {
        let value = 255;
        let ptr = &value as *const i32 as *mut i32;
        let atomic_ptr = AtomicPtr::new(ptr);

        // Clear all bits (mask with all 1s)
        let mask = usize::MAX;
        let result = clear_pointer_bits(&atomic_ptr, mask);

        assert_eq!(result, ptr);

        let stored = atomic_ptr.load(Ordering::SeqCst);
        assert_eq!(stored, 0 as *mut i32);
    }

    #[test]
    fn test_clear_pointer_bits_no_bits() {
        let value = 123;
        let ptr = &value as *const i32 as *mut i32;
        let atomic_ptr = AtomicPtr::new(ptr);

        // Clear no bits (mask with all 0s)
        let mask = 0;
        let result = clear_pointer_bits(&atomic_ptr, mask);

        assert_eq!(result, ptr);

        let stored = atomic_ptr.load(Ordering::SeqCst);
        assert_eq!(stored, ptr);
    }

    #[test]
    fn test_clear_pointer_bits_null_pointer() {
        let atomic_ptr = AtomicPtr::new(ptr::null_mut());

        let mask = 0b111;
        let result = clear_pointer_bits(&atomic_ptr, mask);

        assert!(result.is_null());

        let stored = atomic_ptr.load(Ordering::SeqCst);
        assert!(stored.is_null());
    }

    #[test]
    fn test_clear_pointer_bits_alignment_bits() {
        // Create a pointer with specific alignment bits set
        let value = 999;
        let ptr = &value as *const i32 as *mut i32;

        // Force some alignment bits by manipulating the address
        let aligned_ptr = (ptr as usize | 0b111) as *mut i32;
        let atomic_ptr = AtomicPtr::new(aligned_ptr);

        // Clear the alignment bits
        let mask = 0b111;
        let result = clear_pointer_bits(&atomic_ptr, mask);

        assert_eq!(result, aligned_ptr);

        let stored = atomic_ptr.load(Ordering::SeqCst);
        // After clearing alignment bits, pointer should be properly aligned
        assert_eq!(stored as usize % 8, 0);
    }

    #[test]
    fn test_clear_pointer_bits_concurrent_safety() {
        use std::sync::Arc;
        use std::thread;

        let value = 500;
        let ptr = &value as *const i32 as *mut i32;
        let atomic_ptr = Arc::new(AtomicPtr::new(ptr));

        let mut handles = vec![];

        // Spawn multiple threads to clear different bits
        for i in 0..4 {
            let atomic_ptr_clone = Arc::clone(&atomic_ptr);
            let handle = thread::spawn(move || {
                let mask = 1 << i;
                clear_pointer_bits(&atomic_ptr_clone, mask);
            });
            handles.push(handle);
        }

        // Wait for all threads to complete
        for handle in handles {
            handle.join().unwrap();
        }

        // All specified bits should be cleared
        let stored = atomic_ptr.load(Ordering::SeqCst);
        let expected_mask = 0b1111;
        assert_eq!(stored, (ptr as usize & !expected_mask) as *mut i32);
    }

    #[test]
    fn test_clear_pointer_bits_preserves_provenance() {
        // Create an array and get a pointer to an element
        let array = [10, 20, 30, 40];
        let ptr = &array[1] as *const i32 as *mut i32;
        let atomic_ptr = AtomicPtr::new(ptr);

        let mask = 0b11;
        let result = clear_pointer_bits(&atomic_ptr, mask);

        // The returned pointer should still point to the same array element
        unsafe {
            assert_eq!(*result, 20);
        }

        // The stored pointer should also point to valid memory
        let stored = atomic_ptr.load(Ordering::SeqCst);
        unsafe {
            // Even with bits cleared, it should still be within the array bounds
            // or at least dereferenceable if the cleared bits don't affect the offset
            let offset = stored.offset_from(array.as_ptr());
            assert!(offset >= 0 && offset < array.len() as isize);
        }
    }

    #[test]
    fn test_clear_pointer_bits_with_different_orderings() {
        // Note: The function uses SeqCst, but we can test that it works correctly
        let value = 777;
        let ptr = &value as *const i32 as *mut i32;
        let atomic_ptr = AtomicPtr::new(ptr);

        let mask = 0xFF;
        let result = clear_pointer_bits(&atomic_ptr, mask);

        assert_eq!(result, ptr);

        // Verify with different load orderings that the value is consistent
        let stored_relaxed = atomic_ptr.load(Ordering::Relaxed);
        let stored_acquire = atomic_ptr.load(Ordering::Acquire);
        let stored_seqcst = atomic_ptr.load(Ordering::SeqCst);

        assert_eq!(stored_relaxed, stored_acquire);
        assert_eq!(stored_acquire, stored_seqcst);
        assert_eq!(stored_seqcst, (ptr as usize & !mask) as *mut i32);
    }
}

