#[cfg(test)]
mod tests {
    use std::ffi::{CStr, CString};
    use super::is_c_string_empty;

    #[test]
    fn test_empty_c_string() {
        // Create an empty C string (only null terminator)
        let c_string = CString::new("").expect("Failed to create empty CString");
        let c_str = c_string.as_c_str();

        assert!(is_c_string_empty(c_str), "Empty C string should be identified as empty");
    }

    #[test]
    fn test_non_empty_c_string() {
        // Create a C string with some content
        let c_string = CString::new("hello").expect("Failed to create CString");
        let c_str = c_string.as_c_str();

        assert!(!is_c_string_empty(c_str), "Non-empty C string should not be identified as empty");
    }

    #[test]
    fn test_whitespace_c_string() {
        // Create a C string with only whitespace
        let c_string = CString::new(" \t\n").expect("Failed to create whitespace CString");
        let c_str = c_string.as_c_str();

        assert!(!is_c_string_empty(c_str), "Whitespace-only C string should not be identified as empty");
    }

    #[test]
    fn test_null_byte_in_middle() {
        // Create a C string with a null byte in the middle (this actually creates a C string with just "before")
        let c_string = CString::new("before\0after").expect_err("Should not be able to create CString with internal null");

        // Create a valid C string for the "before" part
        let c_string = CString::new("before").expect("Failed to create CString");
        let c_str = c_string.as_c_str();

        assert!(!is_c_string_empty(c_str), "C string with content before null terminator should not be empty");
    }

    #[test]
    fn test_from_bytes_with_nul() {
        // Test creating a CStr from bytes with a trailing null
        let bytes = b"test\0";
        let c_str = unsafe { CStr::from_bytes_with_nul_unchecked(bytes) };

        assert!(!is_c_string_empty(c_str), "C string created from bytes should not be empty");
    }

    #[test]
    fn test_from_bytes_with_nul_empty() {
        // Test creating an empty CStr from bytes with just a null terminator
        let bytes = b"\0";
        let c_str = unsafe { CStr::from_bytes_with_nul_unchecked(bytes) };

        assert!(is_c_string_empty(c_str), "C string with only null terminator should be empty");
    }

    #[test]
    fn test_comparison_with_to_bytes() {
        // Test that is_empty behaves the same as checking the length of to_bytes()
        let test_strings = vec!["", "a", "hello", " ", "\t"];

        for s in test_strings {
            let c_string = CString::new(s).expect("Failed to create CString");
            let c_str = c_string.as_c_str();

            // The to_bytes method returns the string without the null terminator
            let is_empty_result = is_c_string_empty(c_str);
            let to_bytes_empty = c_str.to_bytes().is_empty();

            assert_eq!(is_empty_result, to_bytes_empty, 
                "is_c_string_empty should match to_bytes().is_empty() for string: {:?}", s);
        }
    }
}

