#[cfg(test)]
mod tests {
    use super::safe_divide;
    use std::ops::Div;

    // Test for integers
    #[test]
    fn test_safe_divide_i32() {
        assert_eq!(safe_divide(10, 2), 5);
        assert_eq!(safe_divide(-10, 2), -5);
        assert_eq!(safe_divide(10, -2), -5);
        assert_eq!(safe_divide(-10, -2), 5);
    }

    // Test for floating point numbers
    #[test]
    fn test_safe_divide_f64() {
        assert_eq!(safe_divide(10.0, 2.0), 5.0);
        assert_eq!(safe_divide(-10.0, 2.0), -5.0);
        assert!((safe_divide(1.0f64, 3.0f64) - 0.3333333333333333).abs() < f64::EPSILON);
    }

    // Test for unsigned integers
    #[test]
    fn test_safe_divide_u32() {
        assert_eq!(safe_divide(10u32, 2u32), 5u32);
        assert_eq!(safe_divide(9u32, 3u32), 3u32);
    }

    // Test for custom type implementing Div
    #[derive(Debug, PartialEq)]
    struct Fraction {
        numerator: i32,
        denominator: i32,
    }

    impl Div for Fraction {
        type Output = Fraction;

        fn div(self, rhs: Fraction) -> Fraction {
            Fraction {
                numerator: self.numerator * rhs.denominator,
                denominator: self.denominator * rhs.numerator,
            }
        }
    }

    #[test]
    fn test_safe_divide_custom_type() {
        let a = Fraction { numerator: 1, denominator: 2 };
        let b = Fraction { numerator: 3, denominator: 4 };

        let expected = Fraction { numerator: 4, denominator: 6 };
        assert_eq!(safe_divide(a, b), expected);
    }

    // Test for different integer types
    #[test]
    fn test_safe_divide_different_int_types() {
        assert_eq!(safe_divide(10i8, 2i8), 5i8);
        assert_eq!(safe_divide(10i16, 2i16), 5i16);
        assert_eq!(safe_divide(10i64, 2i64), 5i64);
        assert_eq!(safe_divide(10isize, 2isize), 5isize);

        assert_eq!(safe_divide(10u8, 2u8), 5u8);
        assert_eq!(safe_divide(10u16, 2u16), 5u16);
        assert_eq!(safe_divide(10u64, 2u64), 5u64);
        assert_eq!(safe_divide(10usize, 2usize), 5usize);
    }

    // Test for f32 floating point
    #[test]
    fn test_safe_divide_f32() {
        assert_eq!(safe_divide(10.0f32, 2.0f32), 5.0f32);
        assert!((safe_divide(1.0f32, 3.0f32) - 0.33333334f32).abs() < f32::EPSILON);
    }

    // Test integer division with remainder
    #[test]
    fn test_safe_divide_integer_division() {
        assert_eq!(safe_divide(5i32, 2i32), 2i32); // 5/2 = 2 with remainder 1 (which is truncated)
        assert_eq!(safe_divide(7u32, 3u32), 2u32); // 7/3 = 2 with remainder 1 (which is truncated)
    }
}

