        let initialized = initialize_lazy_value(&mut value, || {
            init_called.set(true);
            String::from("initialized")
        });

        assert!(init_called.get(), "Initialization function should be called");
        assert_eq!(initialized, &mut String::from("initialized"));
        assert_eq!(value, Some(String::from("initialized")));
    }

