        let init_called = Cell::new(false);
        let result = initialize_lazy_value(&mut value, || {
            init_called.set(true);
            String::from("should not be used")
        });

        assert!(!init_called.get(), "Initialization function should not be called");
        assert_eq!(result, &mut String::from("existing"));
        assert_eq!(value, Some(String::from("existing")));
    }

    #[test]
    fn test_different_type_implementations() {
