        let ptrs: Vec<AtomicPtr<i32>> = create_null_atomic_ptrs(count);

        // Check correct length
        assert_eq!(ptrs.len(), count);

        // Check all pointers are null
        for ptr in &ptrs {
            assert_eq!(ptr.load(Ordering::SeqCst), ptr::null_mut());
        }
    }

    #[test]
    fn test_create_null_atomic_ptrs_with_custom_type() {
        struct TestStruct {
            value: i32,
        }

        let count = 3;
        let ptrs: Vec<AtomicPtr<TestStruct>> = create_null_atomic_ptrs(count);

        // Check correct length
        assert_eq!(ptrs.len(), count);

        // Check all pointers are null
        for ptr in &ptrs {
            assert_eq!(ptr.load(Ordering::SeqCst), ptr::null_mut());
        }
    }

    #[test]
    fn test_create_null_atomic_ptrs_with_large_count() {
        let count = 1000;
        let ptrs: Vec<AtomicPtr<u8>> = create_null_atomic_ptrs(count);

        // Check correct length
        assert_eq!(ptrs.len(), count);

        // Verify a sample of the pointers
        assert_eq!(ptrs[0].load(Ordering::SeqCst), ptr::null_mut());
        assert_eq!(ptrs[count / 2].load(Ordering::SeqCst), ptr::null_mut());
        assert_eq!(ptrs[count - 1].load(Ordering::SeqCst), ptr::null_mut());
    }

    #[test]
    fn test_atomic_ptr_modification() {
        // Create an initial set of null pointers
        let mut ptrs: Vec<AtomicPtr<i32>> = create_null_atomic_ptrs(1);
        assert_eq!(ptrs[0].load(Ordering::SeqCst), ptr::null_mut());

        // Create a value and get its raw pointer
        let value = Box::new(42);
        let raw_ptr = Box::into_raw(value);

        // Modify the atomic pointer
        ptrs[0].store(raw_ptr, Ordering::SeqCst);

        // Verify the modification worked
        assert_eq!(ptrs[0].load(Ordering::SeqCst), raw_ptr);

        // Clean up to avoid memory leak
        unsafe {
            let _ = Box::from_raw(ptrs[0].load(Ordering::SeqCst));
        }
    }
}

