use std::ops::Add;

fn safe_add<T: Add<Output = T>>(a: T, b: T) -> T {
    a.add(b)
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use std::panic::{catch_unwind, AssertUnwindSafe};
    use std::num::Wrapping;

    struct TestAddable {
        value: i32,
    }

    impl Add for TestAddable {
        type Output = Self;

        fn add(self, other: Self) -> Self::Output {
            TestAddable {
                value: self.value.wrapping_add(other.value),
            }
        }
    }

    #[test]
    fn test_safe_add_i32() {
        // Basic addition
        assert_eq!(safe_add(1i32, 2i32), 3i32);
        assert_eq!(safe_add(-5i32, 10i32), 5i32);
        assert_eq!(safe_add(0i32, 0i32), 0i32);

        // Edge case: adding zero
        assert_eq!(safe_add(42i32, 0i32), 42i32);
    }

    #[test]
    fn test_safe_add_i32_overflow() {
        // Test overflow scenarios separately
        if cfg!(debug_assertions) {
            // In debug mode, we expect a panic on overflow
            let result = catch_unwind(AssertUnwindSafe(|| {
                safe_add(i32::MAX, 1i32)
            }));
            assert!(result.is_err());

            let result = catch_unwind(AssertUnwindSafe(|| {
                safe_add(i32::MIN, -1i32)
            }));
            assert!(result.is_err());
        } else {
            // In release mode where standard overflow checks are disabled
            // With the current implementation, this will wrap
            assert_eq!(safe_add(i32::MAX, 1i32), i32::MIN);
            assert_eq!(safe_add(i32::MIN, -1i32), i32::MAX);
        }
    }

    #[test]
    fn test_safe_add_u32() {
        // Basic addition
        assert_eq!(safe_add(1u32, 2u32), 3u32);
        assert_eq!(safe_add(5u32, 10u32), 15u32);

        // Edge case: adding zero
        assert_eq!(safe_add(42u32, 0u32), 42u32);
    }

    #[test]
    fn test_safe_add_u32_overflow() {
        // Test overflow separately
        if cfg!(debug_assertions) {
            // In debug mode, expect a panic
            let result = catch_unwind(AssertUnwindSafe(|| {
                safe_add(u32::MAX, 1u32)
            }));
            assert!(result.is_err());
        } else {
            // In release mode, wrapping occurs
            assert_eq!(safe_add(u32::MAX, 1u32), 0u32);
        }
    }

    #[test]
    fn test_safe_add_f64() {
        // Basic addition
        assert_eq!(safe_add(1.0f64, 2.0f64), 3.0f64);
        assert_eq!(safe_add(-5.0f64, 10.0f64), 5.0f64);

        // Testing with special float values
        assert!(safe_add(f64::NAN, 1.0).is_nan());
        assert_eq!(safe_add(f64::INFINITY, 1.0), f64::INFINITY);
        assert_eq!(safe_add(f64::NEG_INFINITY, -1.0), f64::NEG_INFINITY);
    }

    #[test]
    fn test_safe_add_wrapping() {
        // Test with Wrapping type which explicitly handles overflow
        let a = Wrapping(u32::MAX);
        let b = Wrapping(1u32);
        assert_eq!(safe_add(a, b), Wrapping(0u32));

        let c = Wrapping(100i32);
        let d = Wrapping(50i32);
        assert_eq!(safe_add(c, d), Wrapping(150i32));
    }

    #[test]
    fn test_safe_add_custom_type() {
        let a = TestAddable { value: 5 };
        let b = TestAddable { value: 10 };
        let result = safe_add(a, b);
        assert_eq!(result.value, 15);

        // Our implementation now uses wrapping_add so this test will work in all modes
        let c = TestAddable { value: i32::MAX };
        let d = TestAddable { value: 1 };
        let overflow_result = safe_add(c, d);
        assert_eq!(overflow_result.value, i32::MIN);
    }

    #[test]
    fn test_safe_add_checked_overflow() {
        if cfg!(debug_assertions) {
            // In debug mode, attempt to catch the panic from standard integer overflow
            let result = catch_unwind(AssertUnwindSafe(|| {
                safe_add(i32::MAX, 1);
            }));

            // If using standard add (which will panic in debug mode)
            assert!(result.is_err(), "Expected overflow panic did not occur");

            // Optional: check if the panic message contains our expected text
            if let Err(e) = result {
                if let Some(s) = e.downcast_ref::<String>() {
                    assert!(s.contains("attempt to add with overflow"));
                } else if let Some(s) = e.downcast_ref::<&str>() {
                    assert!(s.contains("attempt to add with overflow"));
                }
                // If we can't easily check the message, that's okay too
            }
        } else {
            // In release mode, just skip this test
            // No need to artificially panic as in the original
        }
    }
}

