        let c_str = c_string.as_c_str();

        let result = super::safe_cstr_to_rust_str(c_str);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), "こんにちは世界");
    }

    #[test]
    fn test_empty_string() {
        let c_string = CString::new("").unwrap();
        let c_str = c_string.as_c_str();

        let result = super::safe_cstr_to_rust_str(c_str);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), "");
    }

    #[test]
    fn test_invalid_utf8() {
        // Create a byte array with invalid UTF-8 sequence (ending with null byte)
        let bytes = vec![104, 101, 108, 108, 111, 0xff, 0];

        // SAFETY: We're creating a CStr with proper null termination
        let c_str = unsafe { CStr::from_bytes_with_nul_unchecked(&bytes) };

        let result = super::safe_cstr_to_rust_str(c_str);
        assert!(result.is_err());

        // Verify the error is a Utf8Error
        match result {
            Err(e) => {
                assert_eq!(e.valid_up_to(), 5);
                let _: Utf8Error = e; // Type check
            },
            _ => panic!("Expected UTF-8 error"),
        }
    }

    #[test]
    fn test_string_with_null_bytes() {
        // Create a string with embedded null bytes
        let bytes = [104, 101, 108, 108, 111, 0];

        // SAFETY: We're creating a CStr that's properly null-terminated
        let c_str = unsafe { CStr::from_bytes_with_nul_unchecked(&bytes) };

        // The function should only read up to the first null byte
        let result = super::safe_cstr_to_rust_str(c_str);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), "hello");
    }

    // Modified to use runtime verification instead of const context
    #[test]
    fn test_const_context_compatibility() {
        let hello_bytes = b"hello\0";
