        assert_eq!(conditional_value(false, "hello"), None);
        assert_eq!(conditional_value(false, 3.14), None);

        // Test with more complex types
        let complex = vec![1, 2, 3];
        assert_eq!(conditional_value(false, complex), None);

        // Test with tuples
        assert_eq!(conditional_value(false, (1, "test")), None);
