        #[derive(Debug, PartialEq)]
        struct Config {
            value: String,
        }

        let primary: Option<Config> = None;
        let fallback = || Some(Config { value: String::from("default") });

        let result = get_config_or_fallback(primary, fallback);

        assert_eq!(result, Some(Config { value: String::from("default") }));
    }

    #[test]
    fn test_with_different_types() {
        #[derive(Debug, PartialEq, Copy, Clone)]
        enum ConfigSource {
            Primary,
            Fallback,
        }

        // Test with primary
        let source = std::cell::Cell::new(ConfigSource::Primary);
        let primary = Some(100u32);
        let fallback = || {
            source.set(ConfigSource::Fallback);
            Some(200u32)
        };

        let result = get_config_or_fallback(primary, fallback);

        assert_eq!(result, Some(100u32));
        assert_eq!(source.get(), ConfigSource::Primary);

        // Test with fallback
        let source = std::cell::Cell::new(ConfigSource::Primary);
        let primary: Option<u32> = None;
        let fallback = || {
            source.set(ConfigSource::Fallback);
            Some(200u32)
        };

        let result = get_config_or_fallback(primary, fallback);

        assert_eq!(result, Some(200u32));
        assert_eq!(source.get(), ConfigSource::Fallback);
    }

    #[test]
    fn test_with_complex_fallback_logic() {
        let config_values = vec![10, 20, 30];
        let current_idx = std::cell::Cell::new(0);

        let get_next_value = || {
            let idx = current_idx.get();
            current_idx.set(idx + 1);

            if idx < config_values.len() {
                Some(config_values[idx])
            } else {
                None
            }
        };

        // First call with None primary should get first fallback value
        let result = get_config_or_fallback(None, get_next_value);
        assert_eq!(result, Some(10));

        // Second call with None primary should get second fallback value
        let result = get_config_or_fallback(None, get_next_value);
        assert_eq!(result, Some(20));

        // With Some primary, fallback shouldn't be called
        let result = get_config_or_fallback(Some(99), get_next_value);
        assert_eq!(result, Some(99));
        assert_eq!(current_idx.get(), 2, "Fallback shouldn't be called when primary is Some");

        // Another None primary call should get third fallback value
        let result = get_config_or_fallback(None, get_next_value);
        assert_eq!(result, Some(30));

        // Final None primary call should get None since we've exhausted the values
        let result = get_config_or_fallback(None::<i32>, get_next_value);
        assert_eq!(result, None);
    }
