#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};

    // A simple struct to test hashing with
    #[derive(Debug, PartialEq, Hash)]
    struct TestItem {
        id: u32,
        value: String,
    }

    // Helper function to get hash value for a collection
    fn calculate_hash<T: Hash>(data: &[T]) -> u64 {
        let mut hasher = DefaultHasher::new();
        hash_collection(data, &mut hasher);
        hasher.finish()
    }

    #[test]
    fn test_empty_collection() {
        let empty: Vec<u32> = vec![];
        let hash = calculate_hash(&empty);

        // Hash of empty collection should be consistent
        let mut direct_hasher = DefaultHasher::new();
        Hash::hash_slice(&empty, &mut direct_hasher);
        let direct_hash = direct_hasher.finish();

        assert_eq!(hash, direct_hash);
    }

    #[test]
    fn test_primitive_types() {
        let integers = vec![1, 2, 3, 4, 5];
        let hash1 = calculate_hash(&integers);

        // Same content should produce same hash
        let same_integers = vec![1, 2, 3, 4, 5];
        let hash2 = calculate_hash(&same_integers);

        assert_eq!(hash1, hash2);

        // Different content should produce different hash
        let different_integers = vec![1, 2, 3, 4, 6];
        let hash3 = calculate_hash(&different_integers);

        assert_ne!(hash1, hash3);
    }

    #[test]
    fn test_complex_types() {
        let items = vec![
            TestItem { id: 1, value: "one".to_string() },
            TestItem { id: 2, value: "two".to_string() },
        ];

        let hash1 = calculate_hash(&items);

        // Same content should produce same hash
        let same_items = vec![
            TestItem { id: 1, value: "one".to_string() },
            TestItem { id: 2, value: "two".to_string() },
        ];
        let hash2 = calculate_hash(&same_items);

        assert_eq!(hash1, hash2);

        // Different content should produce different hash
        let different_items = vec![
            TestItem { id: 1, value: "one".to_string() },
            TestItem { id: 3, value: "three".to_string() },
        ];
        let hash3 = calculate_hash(&different_items);

        assert_ne!(hash1, hash3);
    }

    #[test]
    fn test_order_matters() {
        let original = vec![1, 2, 3];
        let reordered = vec![3, 2, 1];

        let hash1 = calculate_hash(&original);
        let hash2 = calculate_hash(&reordered);

        assert_ne!(hash1, hash2, "Different order should produce different hash");
    }

    #[test]
    fn test_different_hasher_implementations() {
        // Define a simple custom hasher for testing
        struct CustomHasher {
            state: u64,
        }

        impl CustomHasher {
            fn new() -> Self {
                CustomHasher { state: 0 }
            }

            fn finish(&self) -> u64 {
                self.state
            }
        }

        impl Hasher for CustomHasher {
            fn finish(&self) -> u64 {
                self.state
            }

            fn write(&mut self, bytes: &[u8]) {
                for &byte in bytes {
                    self.state = self.state.wrapping_add(byte as u64);
                }
            }
        }

        let data = vec![10, 20, 30];

        // Test with DefaultHasher
        let mut default_hasher = DefaultHasher::new();
        hash_collection(&data, &mut default_hasher);
        let default_hash = default_hasher.finish();

        // Verify the DefaultHasher produces expected result
        let mut direct_default = DefaultHasher::new();
        Hash::hash_slice(&data, &mut direct_default);
        assert_eq!(default_hash, direct_default.finish());

        // Test with CustomHasher
        let mut custom_hasher = CustomHasher::new();
        hash_collection(&data, &mut custom_hasher);
        let custom_hash = custom_hasher.finish();

        // Verify the CustomHasher produces expected result
        let mut direct_custom = CustomHasher::new();
        Hash::hash_slice(&data, &mut direct_custom);
        assert_eq!(custom_hash, direct_custom.finish());
    }

    #[test]
    fn test_consistency_with_direct_hashing() {
        let data = vec!["apple", "banana", "cherry"];

        // Hash using our function
        let mut hasher1 = DefaultHasher::new();
        hash_collection(&data, &mut hasher1);
        let hash1 = hasher1.finish();

        // Hash directly using Hash::hash_slice
        let mut hasher2 = DefaultHasher::new();
        Hash::hash_slice(&data, &mut hasher2);
        let hash2 = hasher2.finish();

        assert_eq!(hash1, hash2, "Our function should produce same hash as direct approach");
    }
}

