        assert_eq!(result, Duration::new(2, 750_000_000)); // 2.75 seconds
    }

    #[test]
    fn test_precision_with_small_values() {
        let duration = Duration::from_nanos(1000);
        let result = calculate_scaled_duration(duration, 10.0);
        assert_eq!(result, Duration::from_nanos(100));
    }

    #[test]
    #[should_panic]
    fn test_zero_scale_factor() {
        // This should panic as division by zero is undefined
        let duration = Duration::from_secs(10);
        calculate_scaled_duration(duration, 0.0);
    }

    #[test]
    #[should_panic]
    fn test_negative_scale_factor() {
        // This should panic as a negative scale factor would produce a negative duration
        let duration = Duration::from_secs(10);
        calculate_scaled_duration(duration, -1.0);
    }
}

