#[cfg(test)]
mod tests {
    use super::*;
    use std::fmt::{self, Debug};

    // A large struct for testing that doesn't implement Copy
    #[derive(Debug, PartialEq, Clone)]
    struct LargeStruct {
        data: [i32; 1000],
        name: String,
    }

    impl LargeStruct {
        fn new(value: i32, name: &str) -> Self {
            LargeStruct {
                data: [value; 1000],
                name: name.to_string(),
            }
        }
    }

    // A struct implementing Drop to ensure that the drop semantics are correct
    #[derive(PartialEq)]
    struct DropTrackingStruct {
        id: usize,
        data: [u8; 100],
        dropped: *mut bool,
    }

    impl DropTrackingStruct {
        fn new(id: usize, value: u8, dropped: &mut bool) -> Self {
            DropTrackingStruct {
                id,
                data: [value; 100],
                dropped: dropped as *mut bool,
            }
        }
    }

    impl Drop for DropTrackingStruct {
        fn drop(&mut self) {
            unsafe {
                *self.dropped = true;
            }
        }
    }

    impl Debug for DropTrackingStruct {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            f.debug_struct("DropTrackingStruct")
                .field("id", &self.id)
                .field("data[0]", &self.data[0])
                .finish()
        }
    }

    #[test]
    fn test_swap_basic() {
        // Test with simple structs
        let mut a = LargeStruct::new(1, "struct a");
        let mut b = LargeStruct::new(2, "struct b");

        // Take references to capture initial values
        let a_orig = a.clone();
        let b_orig = b.clone();

        unsafe {
            swap_large_structs(&mut a, &mut b);
        }

        // Verify the swap worked correctly
        assert_eq!(a, b_orig);
        assert_eq!(b, a_orig);
    }

    #[test]
    fn test_swap_identical_structs() {
        // Test with identical structs
        let mut a = LargeStruct::new(42, "identical");
        let mut b = LargeStruct::new(42, "identical");

        let a_ptr = &a as *const LargeStruct;
        let b_ptr = &b as *const LargeStruct;

        unsafe {
            swap_large_structs(&mut a, &mut b);
        }

        // Values should remain the same after swap
        assert_eq!(a, b);

        // Pointers should remain intact
        assert_eq!(&a as *const LargeStruct, a_ptr);
        assert_eq!(&b as *const LargeStruct, b_ptr);
    }

    #[test]
    fn test_drop_semantics() {
        // Test that drop semantics are respected
        let mut drop_a = false;
        let mut drop_b = false;

        {
            let mut a = DropTrackingStruct::new(1, 10, &mut drop_a);
            let mut b = DropTrackingStruct::new(2, 20, &mut drop_b);

            unsafe {
                swap_large_structs(&mut a, &mut b);
            }

            // Verify swap worked for the ID field
            assert_eq!(a.id, 2);
            assert_eq!(b.id, 1);

            // Verify drop flags haven't been triggered yet
            assert_eq!(drop_a, false);
            assert_eq!(drop_b, false);
        }

        // After the scope ends, both structs should be dropped
        assert_eq!(drop_a, true);
        assert_eq!(drop_b, true);
    }

    #[test]
    fn test_with_different_sized_strings() {
        // Test with structs containing different sized strings to check memory handling
        let mut a = LargeStruct::new(1, "a very short name");
        let mut b = LargeStruct::new(2, "a much longer name that takes up more memory to ensure proper handling of heap allocations");

        unsafe {
            swap_large_structs(&mut a, &mut b);
        }

        // Verify the swap worked correctly for both stack and heap data
        assert_eq!(a.data[0], 2);
        assert_eq!(b.data[0], 1);
        assert_eq!(a.name, "a much longer name that takes up more memory to ensure proper handling of heap allocations");
        assert_eq!(b.name, "a very short name");
    }

    #[test]
    fn test_self_swap() {
        // Test swapping a struct with itself
        let mut a = LargeStruct::new(999, "self-swap test");
        let a_orig = a.clone();

        // This test is problematic - we can't have two mutable references to the same value
        // Using ptr::swap directly is better for this specific case
        unsafe {
            let a_ptr = &mut a as *mut LargeStruct;
            std::ptr::swap(&mut a, &mut *a_ptr);
        }

        // Values should remain unchanged
        assert_eq!(a, a_orig);
    }

    // Test with zero-sized types
    #[test]
    fn test_with_zero_sized_type() {
        // ZST (Zero-Sized Type)
        #[derive(Debug, PartialEq)]
        struct ZeroSized;

        let mut a = ZeroSized;
        let mut b = ZeroSized;

        unsafe {
            swap_large_structs(&mut a, &mut b);
        }

        // No real assertion needed here, just ensuring no crashes or UB
        assert_eq!(a, b);
    }

    #[test]
    fn test_nested_structs() {
        // Test with nested structures
        #[derive(Debug, PartialEq, Clone)]
        struct NestedStruct {
            inner: LargeStruct,
            extra: Vec<i32>,
        }

        let mut a = NestedStruct {
            inner: LargeStruct::new(1, "nested a"),
            extra: vec![1, 2, 3],
        };

        let mut b = NestedStruct {
            inner: LargeStruct::new(2, "nested b"),
            extra: vec![4, 5, 6, 7],
        };

        let a_inner_name = a.inner.name.clone();
        let a_extra = a.extra.clone();
        let b_inner_name = b.inner.name.clone();
        let b_extra = b.extra.clone();

        unsafe {
            swap_large_structs(&mut a, &mut b);
        }

        // Verify the swap worked for nested structures
        assert_eq!(a.inner.name, b_inner_name);
        assert_eq!(b.inner.name, a_inner_name);
        assert_eq!(a.extra, b_extra);
        assert_eq!(b.extra, a_extra);
    }
}

