#[cfg(test)]
mod tests {
    use std::sync::Arc;
    use std::rc::Rc;
    use std::cell::RefCell;
    use super::*;

    // Test with primitive types
    #[test]
    fn test_clone_reference_primitive() {
        let original = 42;
        let reference = &original;
        let cloned = clone_reference(reference);

        assert_eq!(*cloned, 42);
        assert_eq!(cloned as *const _, reference as *const _);
    }

    // Test with String
    #[test]
    fn test_clone_reference_string() {
        let original = String::from("test string");
        let reference = &original;
        let cloned = clone_reference(reference);

        assert_eq!(*cloned, "test string");
        assert_eq!(cloned as *const _, reference as *const _);
    }

    // Test with a custom struct
    #[test]
    fn test_clone_reference_custom_struct() {
        #[derive(Debug, PartialEq)]
        struct TestStruct {
            field1: i32,
            field2: String,
        }

        let original = TestStruct {
            field1: 100,
            field2: String::from("hello"),
        };

        let reference = &original;
        let cloned = clone_reference(reference);

        assert_eq!(cloned, reference);
        assert_eq!(cloned as *const _, reference as *const _);
    }

    // Test with a large data structure (Vec)
    #[test]
    fn test_clone_reference_large_data() {
        let large_data: Vec<i32> = (0..10000).collect();
        let reference = &large_data;
        let cloned = clone_reference(reference);

        assert_eq!(cloned, reference);
        assert_eq!(cloned as *const _, reference as *const _);
    }

    // Test with shared ownership (Arc)
    #[test]
    fn test_clone_reference_arc() {
        let shared_data = Arc::new(vec![1, 2, 3, 4, 5]);
        let reference = &shared_data;
        let cloned = clone_reference(reference);

        assert_eq!(**cloned, vec![1, 2, 3, 4, 5]);
        assert_eq!(cloned as *const _, reference as *const _);

        // Ensure the function didn't create a new Arc
        assert_eq!(Arc::strong_count(reference), Arc::strong_count(cloned));
    }

    // Test with dynamically sized type (slice)
    #[test]
    fn test_clone_reference_slice() {
        let data = vec![1, 2, 3, 4, 5];
        let slice: &[i32] = &data;
        let cloned = clone_reference(slice);

        assert_eq!(cloned, slice);
        assert_eq!(cloned as *const [i32], slice as *const [i32]);
    }

    // Test with trait object
    #[test]
    fn test_clone_reference_trait_object() {
        trait TestTrait {
            fn get_value(&self) -> i32;
        }

        struct TraitImpl {
            value: i32,
        }

        impl TestTrait for TraitImpl {
            fn get_value(&self) -> i32 {
                self.value
            }
        }

        let obj = TraitImpl { value: 42 };
        let trait_obj: &dyn TestTrait = &obj;
        let cloned = clone_reference(trait_obj);

        assert_eq!(cloned.get_value(), 42);
    }

    // Test with RefCell
    #[test]
    fn test_clone_reference_refcell() {
        let cell = RefCell::new(String::from("test"));
        let reference = &cell;
        let cloned = clone_reference(reference);

        assert_eq!(cloned.borrow().as_str(), "test");
        assert_eq!(cloned as *const _, reference as *const _);

        // Modify through one reference and check the other
        reference.borrow_mut().push_str(" modified");
        assert_eq!(cloned.borrow().as_str(), "test modified");
    }

    // Test with static references
    #[test]
    fn test_clone_reference_static() {
        static STATIC_DATA: [i32; 3] = [1, 2, 3];
        let reference = &STATIC_DATA;
        let cloned = clone_reference(reference);

        assert_eq!(*cloned, [1, 2, 3]);
        assert_eq!(cloned as *const _, reference as *const _);
    }

    // Test with nested references
    #[test]
    fn test_clone_reference_nested() {
        let data = vec![1, 2, 3];
        let reference1 = &data;
        let reference2 = &reference1;
        let cloned = clone_reference(reference2);

        assert_eq!(**cloned, vec![1, 2, 3]);
        assert_eq!(cloned as *const _, reference2 as *const _);
    }
}

