#[cfg(test)]
mod tests {
    use std::cmp::Ordering;
    use super::compare_tuples;

    #[test]
    fn test_primitive_types() {
        // Test with integers
        assert_eq!(compare_tuples(&5, &10), Some(Ordering::Less));
        assert_eq!(compare_tuples(&10, &5), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&5, &5), Some(Ordering::Equal));

        // Test with floating point
        assert_eq!(compare_tuples(&3.14, &2.71), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&2.71, &3.14), Some(Ordering::Less));
        assert_eq!(compare_tuples(&3.14, &3.14), Some(Ordering::Equal));

        // Test with characters
        assert_eq!(compare_tuples(&'a', &'z'), Some(Ordering::Less));
        assert_eq!(compare_tuples(&'z', &'a'), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&'a', &'a'), Some(Ordering::Equal));

        // Test with booleans
        assert_eq!(compare_tuples(&false, &true), Some(Ordering::Less));
        assert_eq!(compare_tuples(&true, &false), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&true, &true), Some(Ordering::Equal));
    }

    #[test]
    fn test_strings() {
        // Test with String
        let str1 = String::from("apple");
        let str2 = String::from("orange");
        assert_eq!(compare_tuples(&str1, &str2), Some(Ordering::Less));
        assert_eq!(compare_tuples(&str2, &str1), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&str1, &str1), Some(Ordering::Equal));

        // Test with string slices
        assert_eq!(compare_tuples(&"apple", &"orange"), Some(Ordering::Less));
        assert_eq!(compare_tuples(&"orange", &"apple"), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&"apple", &"apple"), Some(Ordering::Equal));
    }

    #[test]
    fn test_collections() {
        // Test with Vec
        assert_eq!(compare_tuples(&vec![1, 2, 3], &vec![1, 2, 4]), Some(Ordering::Less));
        assert_eq!(compare_tuples(&vec![1, 2, 4], &vec![1, 2, 3]), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&vec![1, 2, 3], &vec![1, 2, 3]), Some(Ordering::Equal));

        // Test with slices
        let slice1: &[i32] = &[1, 2, 3];
        let slice2: &[i32] = &[1, 2, 4];
        assert_eq!(compare_tuples(slice1, slice2), Some(Ordering::Less));
        assert_eq!(compare_tuples(slice2, slice1), Some(Ordering::Greater));
        assert_eq!(compare_tuples(slice1, slice1), Some(Ordering::Equal));
    }

    #[test]
    fn test_option_types() {
        // Test with Some values
        assert_eq!(compare_tuples(&Some(5), &Some(10)), Some(Ordering::Less));
        assert_eq!(compare_tuples(&Some(10), &Some(5)), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&Some(5), &Some(5)), Some(Ordering::Equal));

        // Test with None values
        assert_eq!(compare_tuples(&None::<i32>, &Some(5)), Some(Ordering::Less));
        assert_eq!(compare_tuples(&Some(5), &None::<i32>), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&None::<i32>, &None::<i32>), Some(Ordering::Equal));
    }

    #[test]
    fn test_custom_types() {
        // Custom struct implementing PartialOrd
        #[derive(Debug, PartialEq)]
        struct Point {
            x: i32,
            y: i32,
        }

        impl PartialOrd for Point {
            fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
                match self.x.partial_cmp(&other.x) {
                    Some(Ordering::Equal) => self.y.partial_cmp(&other.y),
                    other_ordering => other_ordering,
                }
            }
        }

        let p1 = Point { x: 1, y: 2 };
        let p2 = Point { x: 2, y: 1 };
        let p3 = Point { x: 1, y: 3 };
        let p4 = Point { x: 1, y: 2 };

        assert_eq!(compare_tuples(&p1, &p2), Some(Ordering::Less));
        assert_eq!(compare_tuples(&p2, &p1), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&p1, &p3), Some(Ordering::Less));
        assert_eq!(compare_tuples(&p3, &p1), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&p1, &p4), Some(Ordering::Equal));
    }

    #[test]
    fn test_tuple_comparisons() {
        // Test with simple tuples
        assert_eq!(compare_tuples(&(1, 2), &(1, 3)), Some(Ordering::Less));
        assert_eq!(compare_tuples(&(2, 1), &(1, 2)), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&(1, 2), &(1, 2)), Some(Ordering::Equal));

        // Test with mixed type tuples
        assert_eq!(compare_tuples(&(1, "apple"), &(1, "orange")), Some(Ordering::Less));
        assert_eq!(compare_tuples(&(2, "apple"), &(1, "orange")), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&(1, "apple"), &(1, "apple")), Some(Ordering::Equal));

        // Test with nested tuples
        assert_eq!(compare_tuples(&(1, (2, 3)), &(1, (2, 4))), Some(Ordering::Less));
        assert_eq!(compare_tuples(&(1, (2, 4)), &(1, (2, 3))), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&(1, (2, 3)), &(1, (2, 3))), Some(Ordering::Equal));
    }

    #[test]
    fn test_floats_with_nan() {
        // Test with NaN values
        let nan = f64::NAN;
        let regular = 1.0;

        // NaN is not comparable with any value including itself
        assert_eq!(compare_tuples(&nan, &regular), None);
        assert_eq!(compare_tuples(&regular, &nan), None);
        assert_eq!(compare_tuples(&nan, &nan), None);
    }

    #[test]
    fn test_custom_partial_comparable() {
        // Custom type that implements PartialOrd but sometimes returns None
        struct PartiallyComparable(i32);

        impl PartialEq for PartiallyComparable {
            fn eq(&self, other: &Self) -> bool {
                self.0 == other.0
            }
        }

        impl PartialOrd for PartiallyComparable {
            fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
                // Only compare if both values are positive or both negative
                if (self.0 >= 0 && other.0 >= 0) || (self.0 < 0 && other.0 < 0) {
                    self.0.partial_cmp(&other.0)
                } else {
                    None
                }
            }
        }

        let pos1 = PartiallyComparable(5);
        let pos2 = PartiallyComparable(10);
        let neg1 = PartiallyComparable(-5);
        let neg2 = PartiallyComparable(-10);

        // Comparable cases (both positive or both negative)
        assert_eq!(compare_tuples(&pos1, &pos2), Some(Ordering::Less));
        assert_eq!(compare_tuples(&pos2, &pos1), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&neg1, &neg2), Some(Ordering::Greater));
        assert_eq!(compare_tuples(&neg2, &neg1), Some(Ordering::Less));

        // Non-comparable cases (one positive, one negative)
        assert_eq!(compare_tuples(&pos1, &neg1), None);
        assert_eq!(compare_tuples(&neg1, &pos1), None);
    }
}

