#[cfg(test)]
mod tests {
    use super::find_max_by_key;

    #[test]
    fn test_find_max_by_key_with_integers() {
        // Simple test with integers where the key is the value itself
        let result = find_max_by_key(5, 10, |&x| x);
        assert_eq!(result, 10);

        // Test where the key is a transformation of the value
        let result = find_max_by_key(5, 10, |&x| -x); // Negating to reverse order
        assert_eq!(result, 5);
    }

    #[test]
    fn test_find_max_by_key_with_strings() {
        // Test with strings, comparing by length
        let result = find_max_by_key(
            String::from("hello"), 
            String::from("world"), 
            |s| s.len()
        );
        assert_eq!(result, String::from("world")); // Both are length 5, comparison semantics

        let result = find_max_by_key(
            String::from("hi"), 
            String::from("world"), 
            |s| s.len()
        );
        assert_eq!(result, String::from("world")); // "world" is longer
    }

    #[test]
    fn test_find_max_by_key_with_structs() {
        #[derive(Debug, PartialEq, Clone)]
        struct Person {
            name: String,
            age: u32,
        }

        let alice = Person {
            name: String::from("Alice"),
            age: 30,
        };

        let bob = Person {
            name: String::from("Bob"),
            age: 25,
        };

        // Compare by age
        let result = find_max_by_key(alice.clone(), bob.clone(), |p| p.age);
        assert_eq!(result, alice);

        // Compare by name length
        let result = find_max_by_key(alice.clone(), bob, |p| p.name.len());
        assert_eq!(result, alice); // "Alice" is 5 chars, "Bob" is 3
    }

    #[test]
    fn test_find_max_by_key_with_tuples() {
        // Test with tuples, comparing by the second element
        let tuple1 = (1, 5);
        let tuple2 = (10, 3);

        let result = find_max_by_key(tuple1, tuple2, |&(_, b)| b);
        assert_eq!(result, tuple1);

        // Compare by the first element
        let result = find_max_by_key(tuple1, tuple2, |&(a, _)| a);
        assert_eq!(result, tuple2);
    }

    #[test]
    fn test_find_max_by_key_minimizes_function_calls() {
        use std::cell::Cell;

        // This test verifies the function minimizes calls to the key extractor
        let call_count = Cell::new(0);

        let result = find_max_by_key(5, 10, |&x| {
            call_count.set(call_count.get() + 1);
            x
        });

        assert_eq!(result, 10);
        assert_eq!(call_count.get(), 2); // Should call the function exactly twice, once for each value
    }

    #[test]
    fn test_find_max_by_key_with_computationally_expensive_function() {
        // Simulate a computationally expensive function with a complex type
        #[derive(Debug, PartialEq, Clone)]
        struct ComplexData {
            id: u32,
            data: Vec<u32>,
        }

        let data1 = ComplexData {
            id: 1,
            data: vec![1, 2, 3, 4, 5],
        };

        let data2 = ComplexData {
            id: 2,
            data: vec![5, 6, 7, 8, 9],
        };

        // Expensive computation: sum of all data elements
        let result = find_max_by_key(data1.clone(), data2.clone(), |d| {
            d.data.iter().sum::<u32>()
        });

        assert_eq!(result, data2); // data2 sum is 35, data1 sum is 15
    }

    #[test]
    fn test_find_max_by_key_with_option_type() {
        let option1: Option<i32> = Some(5);
        let option2: Option<i32> = Some(10);

        // Extract the value if Some, or use a default if None
        let result = find_max_by_key(option1, option2, |opt| opt.unwrap_or(0));
        assert_eq!(result, Some(10));

        let option1: Option<i32> = Some(15);
        let option2: Option<i32> = None;

        let result = find_max_by_key(option1, option2, |opt| opt.unwrap_or(0));
        assert_eq!(result, Some(15));
    }

    #[test]
    fn test_find_max_by_key_with_references() {
        let a = 5;
        let b = 10;

        // Test with references to values
        let result = find_max_by_key(&a, &b, |&x| *x);
        assert_eq!(result, &b);

        // Test with references to more complex data
        let vec1 = vec![1, 2, 3];
        let vec2 = vec![4, 5];

        let result = find_max_by_key(&vec1, &vec2, |v| v.iter().sum::<i32>());
        assert_eq!(result, &vec2); // sum of vec2 is 9, sum of vec1 is 6
    }
}

