mod tests {
    use super::*;
    use std::ptr::NonNull;
    use std::alloc::{alloc, dealloc, Layout};
    use std::mem::size_of;

    #[test]
    fn test_clone_data_structure_basic() {
        // Create a value on the heap
        let layout = Layout::new::<i32>();
        let ptr = unsafe {
            let raw_ptr = alloc(layout) as *mut i32;
            *raw_ptr = 42;
            NonNull::new_unchecked(raw_ptr)
        };

        // Clone the pointer
        let cloned_ptr = clone_data_structure(ptr);

        // Verify the cloned pointer points to the same memory
        unsafe {
            assert_eq!(*ptr.as_ptr(), 42);
            assert_eq!(*cloned_ptr.as_ptr(), 42);
            assert_eq!(ptr.as_ptr(), cloned_ptr.as_ptr());

            // Clean up
            dealloc(ptr.as_ptr() as *mut u8, layout);
        }
    }

    #[test]
    fn test_clone_data_structure_with_struct() {
        struct TestStruct {
            x: i32,
            y: bool,
        }

        let layout = Layout::new::<TestStruct>();
        let ptr = unsafe {
            let raw_ptr = alloc(layout) as *mut TestStruct;
            *raw_ptr = TestStruct { x: 123, y: true };
            NonNull::new_unchecked(raw_ptr)
        };

        // Clone the pointer
        let cloned_ptr = clone_data_structure(ptr);

        // Verify the cloned pointer points to the same memory
        unsafe {
            assert_eq!((*ptr.as_ptr()).x, 123);
            assert_eq!((*ptr.as_ptr()).y, true);
            assert_eq!((*cloned_ptr.as_ptr()).x, 123);
            assert_eq!((*cloned_ptr.as_ptr()).y, true);
            assert_eq!(ptr.as_ptr(), cloned_ptr.as_ptr());

            // Clean up
            dealloc(ptr.as_ptr() as *mut u8, layout);
        }
    }

    #[test]
    fn test_clone_data_structure_with_slice() {
        // Create a slice on the heap
        let slice_len = 5;
        let layout = Layout::array::<i32>(slice_len).unwrap();
        let ptr = unsafe {
            let raw_ptr = alloc(layout) as *mut i32;
            for i in 0..slice_len {
                *raw_ptr.add(i) = i as i32;
            }
            let slice_ptr = std::slice::from_raw_parts_mut(raw_ptr, slice_len);
            NonNull::new_unchecked(slice_ptr as *mut [i32])
        };

        // Clone the pointer
        let cloned_ptr = clone_data_structure(ptr);

        // Verify the cloned pointer points to the same memory
        unsafe {
            let orig_slice = &*ptr.as_ptr();
            let cloned_slice = &*cloned_ptr.as_ptr();

            assert_eq!(orig_slice.len(), slice_len);
            assert_eq!(cloned_slice.len(), slice_len);

            for i in 0..slice_len {
                assert_eq!(orig_slice[i], i as i32);
                assert_eq!(cloned_slice[i], i as i32);
            }

            assert_eq!(ptr.as_ptr() as *const i32, cloned_ptr.as_ptr() as *const i32);

            // Clean up
            dealloc(ptr.as_ptr() as *mut [i32] as *mut u8, layout);
        }
