unsafe fn get_element_ptr<T>(ptr: *mut T, index: usize) -> *mut T
where
    T: Sized,
{
    // SAFETY: The caller must ensure that both the starting and resulting pointer
    // are either in bounds or one byte past the end of the same allocated object.
    // The addition must not overflow.
    unsafe { ptr.add(index) }
}

