#[cfg(test)]
mod tests {
    use super::*;
    use std::mem;
    use std::ptr;

    #[test]
    fn test_get_element_ptr_basic() {
        let mut arr = [1, 2, 3, 4, 5];
        let ptr = arr.as_mut_ptr();

        unsafe {
            let element_ptr = get_element_ptr(ptr, 2);
            assert_eq!(*element_ptr, 3);

            // Modify through the returned pointer
            *element_ptr = 42;
            assert_eq!(arr[2], 42);
        }
    }

    #[test]
    fn test_get_element_ptr_zero_index() {
        let mut arr = [10, 20, 30];
        let ptr = arr.as_mut_ptr();

        unsafe {
            let element_ptr = get_element_ptr(ptr, 0);
            assert_eq!(*element_ptr, 10);

            // Modify through the returned pointer
            *element_ptr = 99;
            assert_eq!(arr[0], 99);
        }
    }

    #[test]
    fn test_get_element_ptr_last_element() {
        let mut arr = [10, 20, 30];
        let ptr = arr.as_mut_ptr();

        unsafe {
            let element_ptr = get_element_ptr(ptr, arr.len() - 1);
            assert_eq!(*element_ptr, 30);

            // Modify through the returned pointer
            *element_ptr = 99;
            assert_eq!(arr[arr.len() - 1], 99);
        }
    }

    #[test]
    fn test_get_element_ptr_one_past_end() {
        let mut arr = [10, 20, 30];
        let ptr = arr.as_mut_ptr();

        unsafe {
            // Getting a pointer to one-past-the-end is valid
            // (but dereferencing it would be UB)
            let end_ptr = get_element_ptr(ptr, arr.len());

            // Verify it's the correct address
            assert_eq!(end_ptr, ptr.add(arr.len()));

            // We shouldn't deref end_ptr, but we can check its address
            let addr_diff = end_ptr as usize - ptr as usize;
            assert_eq!(addr_diff, mem::size_of::<i32>() * arr.len());
        }
    }

    #[test]
    fn test_get_element_ptr_different_types() {
        // Test with a different type
        let mut float_arr = [1.1_f64, 2.2_f64, 3.3_f64, 4.4_f64];
        let float_ptr = float_arr.as_mut_ptr();

        unsafe {
            let element_ptr = get_element_ptr(float_ptr, 2);
            assert!((*element_ptr - 3.3_f64).abs() < f64::EPSILON);

            *element_ptr = 9.9_f64;
            assert!((float_arr[2] - 9.9_f64).abs() < f64::EPSILON);
        }

        // Test with a custom struct
        #[derive(Debug, PartialEq)]
        struct TestStruct {
            x: i32,
            y: i32,
        }

        let mut struct_arr = [
            TestStruct { x: 1, y: 2 },
            TestStruct { x: 3, y: 4 },
            TestStruct { x: 5, y: 6 },
        ];
        let struct_ptr = struct_arr.as_mut_ptr();

        unsafe {
            let element_ptr = get_element_ptr(struct_ptr, 1);
            assert_eq!(*element_ptr, TestStruct { x: 3, y: 4 });

            // Modify through the returned pointer
            (*element_ptr).x = 30;
            (*element_ptr).y = 40;

            assert_eq!(struct_arr[1], TestStruct { x: 30, y: 40 });
        }
    }

    #[test]
    fn test_get_element_ptr_empty_array() {
        // Getting a pointer to an empty array is valid
        let mut empty_arr: [i32; 0] = [];
        let ptr = empty_arr.as_mut_ptr();

        unsafe {
            // We can get a one-past-the-end pointer even for an empty array
            let end_ptr = get_element_ptr(ptr, 0);

            // For an empty array, the start and end pointers should be the same
            assert_eq!(end_ptr, ptr);
        }
    }

    #[test]
    fn test_get_element_ptr_null_handling() {
        // WARNING: This test deals with null pointers which is generally unsafe
        // and should be avoided in normal Rust code. This is only for testing
        // pointer arithmetic properties.

        let null_ptr: *mut i32 = ptr::null_mut();

        unsafe {
            // Getting a pointer at index 0 of a null should still be null
            let result_ptr = get_element_ptr(null_ptr, 0);
            assert_eq!(result_ptr, null_ptr);

            // Note: We don't dereference these pointers as that would be UB
        }
    }

    #[test]
    fn test_get_element_ptr_aligned_types() {
        // Test with a type that has specific alignment requirements
        #[repr(align(16))]
        struct AlignedStruct {
            value: i32,
        }

        let mut aligned_arr = [
            AlignedStruct { value: 1 },
            AlignedStruct { value: 2 },
            AlignedStruct { value: 3 },
        ];
        let aligned_ptr = aligned_arr.as_mut_ptr();

        unsafe {
            let element_ptr = get_element_ptr(aligned_ptr, 1);
            assert_eq!((*element_ptr).value, 2);

            // Verify proper alignment is maintained
            assert_eq!(element_ptr as usize % 16, 0);

            // Verify correct offset
            let addr_diff = element_ptr as usize - aligned_ptr as usize;
            assert_eq!(addr_diff, mem::size_of::<AlignedStruct>());
        }
    }

    // This test demonstrates using a ZST (Zero-Sized Type)
    #[test]
    fn test_get_element_ptr_zero_sized_type() {
        struct ZeroSized;

        let mut zst_arr = [ZeroSized, ZeroSized, ZeroSized];
        let zst_ptr = zst_arr.as_mut_ptr();

        unsafe {
            // For zero-sized types, all indices point to the same memory location
            let element_ptr_0 = get_element_ptr(zst_ptr, 0);
            let element_ptr_1 = get_element_ptr(zst_ptr, 1);
            let element_ptr_2 = get_element_ptr(zst_ptr, 2);

            // All pointers should be the same for ZSTs
            assert_eq!(element_ptr_0, zst_ptr);
            assert_eq!(element_ptr_1, zst_ptr);
            assert_eq!(element_ptr_2, zst_ptr);
        }
    }
}

