#[cfg(test)]
mod tests {
    use std::sync::atomic::{AtomicPtr, Ordering};
    use std::ptr;

    // Import the function we're testing
    use super::convert_to_atomic_ptr;

    #[test]
    fn test_convert_null_ptr() {
        let null_ptr: *mut i32 = ptr::null_mut();
        let atomic_ptr = convert_to_atomic_ptr(null_ptr);

        assert_eq!(atomic_ptr.load(Ordering::SeqCst), null_ptr);
    }

    #[test]
    fn test_convert_with_integer() {
        // Create a value on the heap
        let value = Box::new(42);
        let raw_ptr = Box::into_raw(value);

        // Convert to atomic
        let atomic_ptr = convert_to_atomic_ptr(raw_ptr);

        // Validate the pointer points to the same address
        assert_eq!(atomic_ptr.load(Ordering::SeqCst), raw_ptr);

        // Check we can still access the original value
        unsafe {
            assert_eq!(*raw_ptr, 42);

            // Clean up to avoid memory leak
            let _ = Box::from_raw(raw_ptr);
        }
    }

    #[test]
    fn test_convert_with_struct() {
        struct TestStruct {
            a: i32,
            b: String,
        }

        // Create a struct on the heap
        let test_struct = Box::new(TestStruct {
            a: 10,
            b: "test".to_string(),
        });
        let raw_ptr = Box::into_raw(test_struct);

        // Convert to atomic
        let atomic_ptr = convert_to_atomic_ptr(raw_ptr);

        // Verify the pointer address
        assert_eq!(atomic_ptr.load(Ordering::SeqCst), raw_ptr);

        // Verify we can access struct members
        unsafe {
            assert_eq!((*raw_ptr).a, 10);
            assert_eq!((*raw_ptr).b, "test");

            // Clean up
            let _ = Box::from_raw(raw_ptr);
        }
    }

    #[test]
    fn test_store_and_load() {
        // Create two values on the heap
        let value1 = Box::new(42);
        let value2 = Box::new(84);

        let ptr1 = Box::into_raw(value1);
        let ptr2 = Box::into_raw(value2);

        // Convert the first pointer to atomic
        let atomic_ptr = convert_to_atomic_ptr(ptr1);

        // Check initial state
        assert_eq!(atomic_ptr.load(Ordering::SeqCst), ptr1);

        // Store the second pointer
        atomic_ptr.store(ptr2, Ordering::SeqCst);

        // Check the updated state
        assert_eq!(atomic_ptr.load(Ordering::SeqCst), ptr2);

        unsafe {
            // Check we can access both values correctly
            assert_eq!(*ptr1, 42);
            assert_eq!(*ptr2, 84);

            // Clean up
            let _ = Box::from_raw(ptr1);
            let _ = Box::from_raw(ptr2);
        }
    }

    #[test]
    fn test_swap_operation() {
        let value1 = Box::new(100);
        let value2 = Box::new(200);

        let ptr1 = Box::into_raw(value1);
        let ptr2 = Box::into_raw(value2);

        let atomic_ptr = convert_to_atomic_ptr(ptr1);

        // Swap and check the returned old value
        let old = atomic_ptr.swap(ptr2, Ordering::SeqCst);
        assert_eq!(old, ptr1);

        // Check the new value
        assert_eq!(atomic_ptr.load(Ordering::SeqCst), ptr2);

        unsafe {
            // Clean up
            let _ = Box::from_raw(ptr1);
            let _ = Box::from_raw(ptr2);
        }
    }

    #[test]
    fn test_compare_exchange() {
        let value = Box::new(42);
        let new_value = Box::new(100);

        let raw_ptr = Box::into_raw(value);
        let new_ptr = Box::into_raw(new_value);
        let wrong_ptr: *mut i32 = ptr::null_mut();

        let atomic_ptr = convert_to_atomic_ptr(raw_ptr);

        // Attempt with wrong expected - should fail
        let result = atomic_ptr.compare_exchange(
            wrong_ptr,
            new_ptr, 
            Ordering::SeqCst, 
            Ordering::SeqCst
        );

        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), raw_ptr);

        // Attempt with correct expected - should succeed
        let result = atomic_ptr.compare_exchange(
            raw_ptr, 
            new_ptr, 
            Ordering::SeqCst, 
            Ordering::SeqCst
        );

        assert!(result.is_ok());
        assert_eq!(result.unwrap(), raw_ptr);

        // Verify the exchange happened
        assert_eq!(atomic_ptr.load(Ordering::SeqCst), new_ptr);

        unsafe {
            // Clean up
            let _ = Box::from_raw(raw_ptr);
            let _ = Box::from_raw(new_ptr);
        }
    }
}

