mod tests {
    use std::collections::LinkedList;
    use std::mem;

    // Import the function being tested
    use super::optimize_clear_and_reuse;

    #[test]
    fn test_list_is_empty_after_optimization() {
        let mut list: LinkedList<i32> = LinkedList::new();
        list.push_back(1);
        list.push_back(2);
        list.push_back(3);

        optimize_clear_and_reuse(&mut list);

        assert!(list.is_empty());
        assert_eq!(list.len(), 0);
    }

    #[test]
    fn test_with_different_types() {
        // Test with strings
        let mut string_list: LinkedList<String> = LinkedList::new();
        string_list.push_back("hello".to_string());
        string_list.push_back("world".to_string());

        optimize_clear_and_reuse(&mut string_list);

        assert!(string_list.is_empty());

        // Test with custom struct
        #[derive(Debug)]
        struct TestStruct {
            value: i32,
        }

        let mut struct_list: LinkedList<TestStruct> = LinkedList::new();
        struct_list.push_back(TestStruct { value: 10 });
        struct_list.push_back(TestStruct { value: 20 });

        optimize_clear_and_reuse(&mut struct_list);

        assert!(struct_list.is_empty());
    }

    #[test]
    fn test_can_reuse_after_optimization() {
        let mut list: LinkedList<i32> = LinkedList::new();
        for i in 0..1000 {
            list.push_back(i);
        }

        optimize_clear_and_reuse(&mut list);

        // Verify the list can be reused
        for i in 0..500 {
            list.push_back(i);
        }

        assert_eq!(list.len(), 500);
        assert_eq!(list.front(), Some(&0));
        assert_eq!(list.back(), Some(&499));
    }

    #[test]
    fn test_capacity_behavior() {
        let mut list: LinkedList<i32> = LinkedList::new();

        // Fill with significant data
        for i in 0..10_000 {
            list.push_back(i);
        }

        // Record memory usage before optimization
        let size_before = mem::size_of_val(&list);

        optimize_clear_and_reuse(&mut list);

        // The overall container size should remain relatively stable
        // Note: LinkedList doesn't expose capacity directly like Vec does
        let size_after = mem::size_of_val(&list);
        assert_eq!(size_before, size_after, "Container size should remain stable");
    }

    #[test]
    fn test_with_empty_list() {
        let mut list: LinkedList<i32> = LinkedList::new();

        optimize_clear_and_reuse(&mut list);

        assert!(list.is_empty());
    }

    #[test]
    fn test_drop_behavior() {
        use std::rc::Rc;
        use std::cell::RefCell;

        #[derive(Debug)]
        struct DropCounter {
            counter: Rc<RefCell<i32>>,
        }

        impl DropCounter {
            fn new(counter: Rc<RefCell<i32>>) -> Self {
                DropCounter { counter }
            }
        }

        impl Drop for DropCounter {
            fn drop(&mut self) {
                *self.counter.borrow_mut() += 1;
            }
        }

        let drop_count = Rc::new(RefCell::new(0));

        {
            let mut list: LinkedList<DropCounter> = LinkedList::new();

            // Add items that will increment counter when dropped
            for _ in 0..5 {
                list.push_back(DropCounter::new(Rc::clone(&drop_count)));
            }

            optimize_clear_and_reuse(&mut list);

            // Verify all items were properly dropped
            assert_eq!(*drop_count.borrow(), 5);

            // Add more items
            for _ in 0..3 {
                list.push_back(DropCounter::new(Rc::clone(&drop_count)));
            }

            // Items should be dropped when list goes out of scope
        }

        // Verify the 3 new items were also dropped
        assert_eq!(*drop_count.borrow(), 8);
    }
}

