            Some(Person { name: "Alice".to_string(), age: 30 }),
            Some(Person { name: "Bob".to_string(), age: 17 }),
            None,
        ];

        let result = transform_option_sequence(input, |p| Some(PersonSummary { is_adult: p.age >= 18 }));

        assert_eq!(
            result,
            vec![
                Some(PersonSummary { is_adult: true }),
                Some(PersonSummary { is_adult: false }),
                None,
            ]
        );
    }

    #[test]
    fn test_chained_transformations() {
        // First transformation: double the number
        let input = vec![Some(1), Some(2), None, Some(4)];
        let intermediate = transform_option_sequence(input, |x| Some(x * 2));
        assert_eq!(intermediate, vec![Some(2), Some(4), None, Some(8)]);

        // Second transformation: convert to string for even numbers only
        let result = transform_option_sequence(intermediate, |x| {
            if x % 2 == 0 {
                Some(x.to_string())
            } else {
                None
            }
        });

        assert_eq!(result, vec![Some("2".to_string()), Some("4".to_string()), None, Some("8".to_string())]);
    }
