#[cfg(test)]
mod tests {
    use super::*;
    use std::iter::ExactSizeIterator;

    // A custom iterator that implements Iterator<Item = char> + ExactSizeIterator
    struct CustomEscape {
        chars: Vec<char>,
        position: usize,
    }

    impl CustomEscape {
        fn new(s: &str) -> Self {
            CustomEscape {
                chars: s.chars().collect(),
                position: 0,
            }
        }
    }

    impl Iterator for CustomEscape {
        type Item = char;

        fn next(&mut self) -> Option<Self::Item> {
            if self.position < self.chars.len() {
                let c = self.chars[self.position];
                self.position += 1;
                Some(c)
            } else {
                None
            }
        }

        fn size_hint(&self) -> (usize, Option<usize>) {
            let remaining = self.chars.len() - self.position;
            (remaining, Some(remaining))
        }
    }

    impl ExactSizeIterator for CustomEscape {
        fn len(&self) -> usize {
            self.chars.len() - self.position
        }
    }

    #[test]
    fn test_empty_iterator() {
        let iter = CustomEscape::new("");
        assert_eq!(calculate_char_count(&iter), 0);
    }

    #[test]
    fn test_ascii_only_iterator() {
        let iter = CustomEscape::new("hello");
        assert_eq!(calculate_char_count(&iter), 5);
    }

    #[test]
    fn test_unicode_iterator() {
        let iter = CustomEscape::new("こんにちは");  // "Hello" in Japanese
        assert_eq!(calculate_char_count(&iter), 5);
    }

    #[test]
    fn test_mixed_character_iterator() {
        let iter = CustomEscape::new("hello世界");  // "hello world" in mixed English/Chinese
        assert_eq!(calculate_char_count(&iter), 7);
    }

    #[test]
    fn test_iterator_with_emoji() {
        let iter = CustomEscape::new("😊👍🚀");
        assert_eq!(calculate_char_count(&iter), 3);
    }

    #[test]
    fn test_partially_consumed_iterator() {
        let mut iter = CustomEscape::new("testing");
        iter.next();  // Consume the first character 't'
        iter.next();  // Consume the second character 'e'
        assert_eq!(calculate_char_count(&iter), 5);  // Should have 5 characters left
    }

    #[test]
    fn test_fully_consumed_iterator() {
        let mut iter = CustomEscape::new("abc");
        iter.next();
        iter.next();
        iter.next();
        assert_eq!(calculate_char_count(&iter), 0);
    }

    #[test]
    fn test_with_std_chars_iterator() {
        let s = "Hello, world!";
        // Create our own ExactSizeIterator-compatible iterator instead of using s.chars()
        let iter = CustomEscape::new(s);
        assert_eq!(calculate_char_count(&iter), 13);
    }
}

