fn update_collection<T: Clone>(target: &mut Vec<T>, source: &Vec<T>) {
    target.truncate(source.len());
    for (t, s) in target.iter_mut().zip(source.iter()) {
        t.clone_from(s);
    }
    if target.len() < source.len() {
        target.extend(source[target.len()..].iter().cloned());
    }
}

