        impl Clone for TrackingItem {
            fn clone(&self) -> Self {
                TrackingItem {
                    value: self.value,
                    clone_from_called: Cell::new(false),
                }
            }

            fn clone_from(&mut self, source: &Self) {
                self.value = source.value;
                self.clone_from_called.set(true);
