    fn test_create_default_box_str_can_be_cloned() {
        let result = create_default_box_str();
        let cloned = result.clone();
        assert_eq!(&*cloned, "");
    }

    #[test]
    fn test_create_default_box_str_is_distinct_from_other_instances() {
        let result1 = create_default_box_str();
        let result2 = create_default_box_str();

        // Test that they contain the same value
        assert_eq!(&*result1, &*result2);

        // These are empty strings, so comparing their pointers isn't meaningful
        // Since str is a DST (dynamically sized type), two empty strings may
        // point to the same memory location, so this assertion is removed:
        // let ptr1 = &*result1 as *const str;
        // let ptr2 = &*result2 as *const str;
        // assert_ne!(ptr1, ptr2);

        // Instead, ensure they're separate Box instances
        let box_ptr1 = Box::into_raw(Box::new(&*result1));
        let box_ptr2 = Box::into_raw(Box::new(&*result2));
        assert_ne!(box_ptr1, box_ptr2);

        // Clean up to avoid memory leaks
        unsafe {
            let _ = Box::from_raw(box_ptr1);
            let _ = Box::from_raw(box_ptr2);
        }
    }

