    fn test_create_default_box_str_is_usable_in_context() {
        let result = create_default_box_str();

        // Test that we can use string methods on it
        assert!(result.is_empty());
        assert!(!result.contains("a"));

        // Test that we can get a mutable reference to it
        let mut mut_boxed = create_default_box_str();
        let _: &mut str = &mut *mut_boxed;
    }

    #[test]
    fn test_create_default_box_str_into_string() {
        let result = create_default_box_str();
        let owned: String = result.to_string();
        assert_eq!(owned, "");
    }
}

