    struct Message {
        content: String,
    }

    impl Printable for Message {
        fn get_message(&self) -> String {
            self.content.clone()
        }
    }

    // Trait objects can't implement Default directly
    // We'll use a helper function instead
    fn default_printable() -> Box<dyn Printable> {
        Box::new(Message::default())
    }

