        assert_eq!(container.data, 0);
    }

    #[test]
    fn test_create_default_trait_object() {
        // Create a default trait object using our helper function
        let printable = default_printable();

        // Verify it behaves as expected
        assert_eq!(printable.get_message(), "");

        // We can also check if it's the expected concrete type by debugging
        let debug_str = format!("{:?}", printable);
        assert!(debug_str.contains("Message"));
