#[cfg(test)]
mod tests {
    use std::num::Wrapping;
    use super::perform_stable_bitwise_or;

    #[test]
    fn test_basic_bitwise_or() {
        // Test basic OR operation
        assert_eq!(
            perform_stable_bitwise_or(Wrapping(0b1010), Wrapping(0b0101)),
            Wrapping(0b1111)
        );

        // Test with zeros
        assert_eq!(
            perform_stable_bitwise_or(Wrapping(0), Wrapping(0)),
            Wrapping(0)
        );

        // Test with ones
        assert_eq!(
            perform_stable_bitwise_or(Wrapping(u32::MAX), Wrapping(u32::MAX)),
            Wrapping(u32::MAX)
        );
    }

    #[test]
    fn test_identity_property() {
        // Test OR with 0 (identity property)
        let value = Wrapping(0b1010_1010);
        assert_eq!(
            perform_stable_bitwise_or(value, Wrapping(0)),
            value
        );
    }

    #[test]
    fn test_domination_property() {
        // Test OR with all 1s (domination property)
        let value = Wrapping(0b1010_1010);
        assert_eq!(
            perform_stable_bitwise_or(value, Wrapping(u32::MAX)),
            Wrapping(u32::MAX)
        );
    }

    #[test]
    fn test_commutativity() {
        // Test commutativity (a OR b = b OR a)
        let a = Wrapping(0b1010_0000);
        let b = Wrapping(0b0101_1111);
        assert_eq!(
            perform_stable_bitwise_or(a, b),
            perform_stable_bitwise_or(b, a)
        );
    }

    #[test]
    fn test_wrapping_behavior() {
        // Test that wrapping works correctly
        let a = Wrapping(u32::MAX);
        let b = Wrapping(1);
        assert_eq!(
            perform_stable_bitwise_or(a, b),
            Wrapping(u32::MAX)
        );
    }

    #[test]
    fn test_associativity() {
        // Test associativity (a OR (b OR c) = (a OR b) OR c)
        let a = Wrapping(0b1010_0000);
        let b = Wrapping(0b0101_0000);
        let c = Wrapping(0b0000_1111);

        let result1 = perform_stable_bitwise_or(a, perform_stable_bitwise_or(b, c));
        let result2 = perform_stable_bitwise_or(perform_stable_bitwise_or(a, b), c);

        assert_eq!(result1, result2);
    }

    #[test]
    fn test_idempotence() {
        // Test idempotence (a OR a = a)
        let a = Wrapping(0b1010_1010);
        assert_eq!(
            perform_stable_bitwise_or(a, a),
            a
        );
    }

    #[test]
    fn test_boundary_values() {
        // Test boundary values
        assert_eq!(
            perform_stable_bitwise_or(Wrapping(1), Wrapping(2)),
            Wrapping(3)
        );

        assert_eq!(
            perform_stable_bitwise_or(Wrapping(0), Wrapping(u32::MAX)),
            Wrapping(u32::MAX)
        );

        assert_eq!(
            perform_stable_bitwise_or(Wrapping(u32::MAX - 1), Wrapping(1)),
            Wrapping(u32::MAX)
        );
    }

    #[test]
    fn test_alternating_bits() {
        // Test with alternating bit patterns
        assert_eq!(
            perform_stable_bitwise_or(Wrapping(0xAAAAAAAA), Wrapping(0x55555555)),
            Wrapping(0xFFFFFFFF)
        );
    }
}

