        let result = find_max(5, 10, |a, b| b.cmp(a));
        assert_eq!(result, 5);
    }

    #[test]
    fn test_with_strings() {
        let result = find_max(
            String::from("apple"),
            String::from("banana"),
            |a, b| a.cmp(b),
        );
        assert_eq!(result, "banana");

        let result = find_max(
            String::from("zebra"),
            String::from("aardvark"),
            |a, b| a.cmp(b),
        );
        assert_eq!(result, "zebra");
    }

    #[test]
    fn test_with_custom_struct() {
        #[derive(Debug, Clone, PartialEq)]
        struct Person {
            name: String,
            age: u32,
        }

        let alice = Person {
            name: String::from("Alice"),
            age: 30,
        };

        let bob = Person {
            name: String::from("Bob"),
            age: 25,
        };

        // Compare by age
        let result = find_max(alice.clone(), bob.clone(), |a, b| a.age.cmp(&b.age));
        assert_eq!(result.name, "Alice");

        // Compare by name
        let result = find_max(alice.clone(), bob.clone(), |a, b| a.name.cmp(&b.name));
        assert_eq!(result.name, "Bob");
    }

    #[test]
    fn test_with_custom_tuple_comparison() {
        let tuple1 = (5, "apple", true);
        let tuple2 = (10, "banana", false);

        // Compare by first element only
        let result = find_max(tuple1, tuple2, |a, b| a.0.cmp(&b.0));
        assert_eq!(result, (10, "banana", false));

        // Compare by second element only
        let tuple1 = (15, "cherry", true);
        let tuple2 = (5, "apple", false);
        let result = find_max(tuple1, tuple2, |a, b| a.1.cmp(&b.1));
        assert_eq!(result, (15, "cherry", true));
    }

    #[test]
    fn test_with_option_types() {
        let some_value = Some(42);
        let none_value: Option<i32> = None;

        // In standard ordering, Some > None
        let result = find_max(some_value, none_value, |a, b| a.cmp(b));
        assert_eq!(result, Some(42));

        let some_value1 = Some(10);
        let some_value2 = Some(20);
        let result = find_max(some_value1, some_value2, |a, b| a.cmp(b));
        assert_eq!(result, Some(20));
    }

    #[test]
