        let result = find_max(a, b, |x, y| {
            let sum_x = x.0 + x.1;
            let sum_y = y.0 + y.1;
            sum_x.cmp(&sum_y)
        });

        assert_eq!(result, (4, 7)); // 4+7 = 11 > 5+3 = 8
    }

    #[test]
    fn test_with_destructible_types() {
        // Test with types that would be problematic without FnOnce
        // (types that implement Drop or cannot be copied)

        struct Wrapper<T> {
            value: T,
            data: Vec<u8>, // Adds a Drop implementation
        }

        impl<T: PartialEq> PartialEq for Wrapper<T> {
            fn eq(&self, other: &Self) -> bool {
                self.value == other.value
            }
        }

        let w1 = Wrapper {
            value: 10,
            data: vec![1, 2, 3],
        };

        let w2 = Wrapper {
            value: 20,
            data: vec![4, 5, 6],
        };

        // Compare based on the value field
        let result = find_max(w1, w2, |a, b| a.value.cmp(&b.value));
        assert_eq!(result.value, 20);
    }
