        let mut string_list = LinkedList::new();
        string_list.push_back(String::from("Hello"));

        let string_elements = vec![String::from("World"), String::from("!")];
        let expected_strings = vec![String::from("Hello"), String::from("World"), String::from("!")];

        append_elements(&mut string_list, string_elements);

        assert_eq!(string_list.len(), 3);
        assert_eq!(string_list.iter().cloned().collect::<Vec<_>>(), expected_strings);

        // Test with custom type that implements Clone
        #[derive(Debug, Clone, PartialEq)]
        struct TestStruct {
            value: i32,
        }

        let mut struct_list = LinkedList::new();
        struct_list.push_back(TestStruct { value: 1 });

        let struct_elements = vec![
            TestStruct { value: 2 },
            TestStruct { value: 3 },
        ];

        let expected_structs = vec![
            TestStruct { value: 1 },
            TestStruct { value: 2 },
            TestStruct { value: 3 },
        ];

        append_elements(&mut struct_list, struct_elements);

        assert_eq!(struct_list.len(), 3);
        assert_eq!(struct_list.iter().cloned().collect::<Vec<_>>(), expected_structs);
