mod tests {
    use super::*;

    #[test]
    fn test_empty_vec() {
        let input: Vec<i32> = vec![];
        let result = compute_signums(input);
        assert_eq!(result, Vec::<i32>::new());
    }

    #[test]
    fn test_positive_numbers() {
        let input = vec![1, 2, 5, 10, 42];
        let result = compute_signums(input);
        assert_eq!(result, vec![1, 1, 1, 1, 1]);
    }

    #[test]
    fn test_negative_numbers() {
        let input = vec![-1, -2, -5, -10, -42];
        let result = compute_signums(input);
        assert_eq!(result, vec![-1, -1, -1, -1, -1]);
    }

    #[test]
    fn test_zero() {
        let input = vec![0, 0, 0];
        let result = compute_signums(input);
        assert_eq!(result, vec![0, 0, 0]);
    }

    #[test]
    fn test_mixed_numbers() {
        let input = vec![-3, 0, 5, -10, 0, 42, -1];
        let result = compute_signums(input);
        assert_eq!(result, vec![-1, 0, 1, -1, 0, 1, -1]);
    }

    #[test]
    fn test_integer_boundaries() {
        let input = vec![i32::MIN, i32::MAX, 0];
        let result = compute_signums(input);
        assert_eq!(result, vec![-1, 1, 0]);
    }

    #[test]
    fn test_large_dataset() {
        // Create a large dataset with 100,000 elements
        let mut input = Vec::with_capacity(100_000);
        let mut expected = Vec::with_capacity(100_000);

        for i in 0..100_000 {
            let value = if i % 3 == 0 {
                -i as i32
            } else if i % 3 == 1 {
                0
            } else {
                i as i32
            };

            input.push(value);
            expected.push(value.signum());
        }

        let result = compute_signums(input);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_consumption() {
        // Verify that the input vector is consumed
        let input = vec![1, -2, 0];
        let _result = compute_signums(input.clone());

        // This should still work because we cloned the input
        let result2 = compute_signums(input);
        assert_eq!(result2, vec![1, -1, 0]);
    }
}

