#[cfg(test)]
mod tests {
    use std::ops::BitXor;
    use super::perform_bitwise_xor;

    // Simple custom type that implements BitXor
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    struct CustomBitfield(u32);

    impl BitXor for CustomBitfield {
        type Output = Self;

        fn bitxor(self, rhs: Self) -> Self::Output {
            CustomBitfield(self.0 ^ rhs.0)
        }
    }

    #[test]
    fn test_xor_u8() {
        assert_eq!(perform_bitwise_xor(0b1010u8, 0b1100u8), 0b0110u8);
        assert_eq!(perform_bitwise_xor(0u8, 0u8), 0u8);
        assert_eq!(perform_bitwise_xor(0u8, 255u8), 255u8);
        assert_eq!(perform_bitwise_xor(255u8, 255u8), 0u8);
    }

    #[test]
    fn test_xor_u16() {
        assert_eq!(perform_bitwise_xor(0b1010_1010u16, 0b0101_0101u16), 0b1111_1111u16);
        assert_eq!(perform_bitwise_xor(0u16, 65535u16), 65535u16);
        assert_eq!(perform_bitwise_xor(65535u16, 65535u16), 0u16);
    }

    #[test]
    fn test_xor_i32() {
        assert_eq!(perform_bitwise_xor(42i32, 27i32), 49i32);
        assert_eq!(perform_bitwise_xor(-1i32, 0i32), -1i32);
        assert_eq!(perform_bitwise_xor(-1i32, -1i32), 0i32);
    }

    #[test]
    fn test_xor_usize() {
        assert_eq!(perform_bitwise_xor(0xF0F0usize, 0x0F0Fusize), 0xFFFFusize);
        assert_eq!(perform_bitwise_xor(0usize, usize::MAX), usize::MAX);
        assert_eq!(perform_bitwise_xor(usize::MAX, usize::MAX), 0usize);
    }

    #[test]
    fn test_custom_type() {
        let a = CustomBitfield(0xAAAAAAAA);
        let b = CustomBitfield(0x55555555);
        let expected = CustomBitfield(0xFFFFFFFF);

        assert_eq!(perform_bitwise_xor(a, b), expected);
        assert_eq!(perform_bitwise_xor(a, a), CustomBitfield(0));
    }

    #[test]
    fn test_commutative_property() {
        // XOR should be commutative: a ^ b = b ^ a
        assert_eq!(
            perform_bitwise_xor(0xABCD1234u32, 0x12345678u32),
            perform_bitwise_xor(0x12345678u32, 0xABCD1234u32)
        );

        let custom_a = CustomBitfield(0xDEADBEEF);
        let custom_b = CustomBitfield(0xCAFEBABE);

        assert_eq!(
            perform_bitwise_xor(custom_a, custom_b),
            perform_bitwise_xor(custom_b, custom_a)
        );
    }

    #[test]
    fn test_associative_property() {
        // XOR should be associative: (a ^ b) ^ c = a ^ (b ^ c)
        let a = 0xABCDu32;
        let b = 0x1234u32;
        let c = 0x5678u32;

        assert_eq!(
            perform_bitwise_xor(perform_bitwise_xor(a, b), c),
            perform_bitwise_xor(a, perform_bitwise_xor(b, c))
        );
    }

    #[test]
    fn test_identity_property() {
        // XOR with 0 should return the original value
        assert_eq!(perform_bitwise_xor(42u32, 0u32), 42u32);
        assert_eq!(perform_bitwise_xor(0u64, 42u64), 42u64);

        let custom = CustomBitfield(0xDEADBEEF);
        assert_eq!(perform_bitwise_xor(custom, CustomBitfield(0)), custom);
    }

    #[test]
    fn test_self_inverse_property() {
        // XOR of a value with itself should be 0
        assert_eq!(perform_bitwise_xor(0xFFFFu16, 0xFFFFu16), 0u16);
        assert_eq!(perform_bitwise_xor(123i8, 123i8), 0i8);

        let custom = CustomBitfield(0xCAFEBABE);
        assert_eq!(perform_bitwise_xor(custom, custom), CustomBitfield(0));
    }
}

