#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::UnsafeCell;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::Arc;
    use std::thread;

    #[test]
    fn test_create_unsafe_cell_with_primitive_types() {
        // Test with integer
        let cell = create_unsafe_cell(42);
        unsafe {
            assert_eq!(*cell.get(), 42);
        }

        // Test with float
        let cell = create_unsafe_cell(3.14);
        unsafe {
            assert_eq!(*cell.get(), 3.14);
        }

        // Test with boolean
        let cell = create_unsafe_cell(true);
        unsafe {
            assert_eq!(*cell.get(), true);
        }

        // Test with char
        let cell = create_unsafe_cell('a');
        unsafe {
            assert_eq!(*cell.get(), 'a');
        }
    }

    #[test]
    fn test_create_unsafe_cell_with_compound_types() {
        // Test with String
        let cell = create_unsafe_cell(String::from("hello"));
        unsafe {
            assert_eq!(&*cell.get(), "hello");
        }

        // Test with Vec
        let cell = create_unsafe_cell(vec![1, 2, 3]);
        unsafe {
            assert_eq!(&*cell.get(), &vec![1, 2, 3]);
        }

        // Test with tuple
        let cell = create_unsafe_cell((42, "answer"));
        unsafe {
            assert_eq!(&*cell.get(), &(42, "answer"));
        }

        // Test with Option
        let cell = create_unsafe_cell(Some(42));
        unsafe {
            assert_eq!(&*cell.get(), &Some(42));
        }
    }

    #[test]
    fn test_create_unsafe_cell_with_custom_struct() {
        #[derive(Debug, PartialEq)]
        struct TestStruct {
            x: i32,
            y: String,
        }

        let test_struct = TestStruct {
            x: 10,
            y: "test".to_string(),
        };

        let cell = create_unsafe_cell(test_struct);

        unsafe {
            let inner = &*cell.get();
            assert_eq!(inner.x, 10);
            assert_eq!(inner.y, "test");
        }
    }

    #[test]
    fn test_create_unsafe_cell_interior_mutability() {
        let cell = create_unsafe_cell(42);

        unsafe {
            let ptr = cell.get();
            *ptr = 100;
            assert_eq!(*ptr, 100);
        }
    }

    #[test]
    fn test_create_unsafe_cell_with_zero_sized_type() {
        struct ZeroSized;

        let cell = create_unsafe_cell(ZeroSized);

        // Just verify we can create it without panics
        unsafe {
            let _inner = &*cell.get();
        }
    }

    #[test]
    fn test_create_unsafe_cell_in_multiple_threads() {
        // Create a thread-safe counter
        let counter = Arc::new(AtomicBool::new(false));
        let ready = Arc::new(AtomicBool::new(false));

        // Since UnsafeCell isn't Send, we test create_unsafe_cell
        // by having each thread create its own instance
        let handles: Vec<_> = (0..10)
            .map(|i| {
                let counter = Arc::clone(&counter);
                let ready = Arc::clone(&ready);

                thread::spawn(move || {
                    // Each thread creates its own UnsafeCell
                    let cell = create_unsafe_cell(0);

                    // Wait until all threads are ready
                    while !ready.load(Ordering::SeqCst) {
                        thread::yield_now();
                    }

                    // Modify our local UnsafeCell
                    unsafe {
                        *cell.get() = 42 + i;
                        assert_eq!(*cell.get(), 42 + i);
                    }

                    // Signal completion
                    counter.store(true, Ordering::SeqCst);

                    i
                })
            })
            .collect();

        // Signal to all threads to proceed
        ready.store(true, Ordering::SeqCst);

        // Wait for all threads to complete
        for handle in handles {
            let _ = handle.join();
        }

        // By this point, all threads completed successfully
        assert!(counter.load(Ordering::SeqCst));
    }

