fn escape_non_printable(input: &str) -> Vec<u8> {
    let mut result = Vec::with_capacity(input.len());

    for byte in input.bytes() {
        if byte.is_ascii_graphic() || byte == b' ' || byte == b'\t' {
            // Printable characters are copied directly
            result.push(byte);
        } else {
            // Escape sequence for non-printable characters
            let mut escape = format!("\\x{:02x}", byte).into_bytes();
            let mut iter = escape.into_iter();
            while let Some(b) = iter.next() {
                result.push(b);
            }
        }
    }

    result
}

