fn write_buffers_to_vecdeque(buffers: &[&[u8]], deque: &mut VecDeque<u8>) -> io::Result<usize> {
    let mut total_written = 0;

    for buffer in buffers {
        let bytes_written = deque.write(buffer)?;
        total_written += bytes_written;
    }

    Ok(total_written)
}

