#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::VecDeque;
    use std::io::{self, Write};

    #[test]
    fn test_write_empty_buffers() {
        let buffers: &[&[u8]] = &[];
        let mut deque = VecDeque::new();

        let result = write_buffers_to_vecdeque(buffers, &mut deque);

        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 0);
        assert!(deque.is_empty());
    }

    #[test]
    fn test_write_single_buffer() {
        let buffer = b"hello world";
        let buffers: &[&[u8]] = &[buffer];
        let mut deque = VecDeque::new();

        let result = write_buffers_to_vecdeque(buffers, &mut deque);

        assert!(result.is_ok());
        assert_eq!(result.unwrap(), buffer.len());
        assert_eq!(deque.len(), buffer.len());

        let output: Vec<u8> = deque.into_iter().collect();
        assert_eq!(output, buffer);
    }

    #[test]
    fn test_write_multiple_buffers() {
        let buffer1 = b"hello";
        let buffer2 = b" ";
        let buffer3 = b"world";
        let buffers: &[&[u8]] = &[buffer1, buffer2, buffer3];
        let mut deque = VecDeque::new();

        let result = write_buffers_to_vecdeque(buffers, &mut deque);

        assert!(result.is_ok());
        assert_eq!(result.unwrap(), buffer1.len() + buffer2.len() + buffer3.len());
        assert_eq!(deque.len(), buffer1.len() + buffer2.len() + buffer3.len());

        let output: Vec<u8> = deque.into_iter().collect();
        let expected = b"hello world";
        assert_eq!(output, expected);
    }

    #[test]
    fn test_write_to_non_empty_deque() {
        let initial_data = b"initial: ";
        let buffer = b"appended data";
        let buffers: &[&[u8]] = &[buffer];

        let mut deque = VecDeque::new();
        deque.extend(initial_data.iter().cloned());

        let result = write_buffers_to_vecdeque(buffers, &mut deque);

        assert!(result.is_ok());
        assert_eq!(result.unwrap(), buffer.len());
        assert_eq!(deque.len(), initial_data.len() + buffer.len());

        let output: Vec<u8> = deque.into_iter().collect();
        let expected = b"initial: appended data";
        assert_eq!(output, expected);
    }

    #[test]
    fn test_write_large_buffers() {
        // Create a large buffer to test handling of larger data
        let large_buffer1 = vec![b'A'; 10_000];
        let large_buffer2 = vec![b'B'; 5_000];
        let buffers: &[&[u8]] = &[&large_buffer1, &large_buffer2];

        let mut deque = VecDeque::new();
        let result = write_buffers_to_vecdeque(buffers, &mut deque);

        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 15_000);
        assert_eq!(deque.len(), 15_000);

        // Verify first 10,000 bytes are 'A' and next 5,000 are 'B'
        for (i, &byte) in deque.iter().enumerate() {
            if i < 10_000 {
                assert_eq!(byte, b'A');
            } else {
                assert_eq!(byte, b'B');
            }
        }
    }

    #[test]
    fn test_write_empty_buffer() {
        let buffer1 = b"hello";
        let buffer2 = b"";  // Empty buffer
        let buffer3 = b"world";
        let buffers: &[&[u8]] = &[buffer1, buffer2, buffer3];

        let mut deque = VecDeque::new();
        let result = write_buffers_to_vecdeque(buffers, &mut deque);

        assert!(result.is_ok());
        assert_eq!(result.unwrap(), buffer1.len() + buffer2.len() + buffer3.len());
        assert_eq!(deque.len(), buffer1.len() + buffer2.len() + buffer3.len());

        let output: Vec<u8> = deque.into_iter().collect();
        let expected = b"helloworld";
        assert_eq!(output, expected);
    }

    // Mock struct to simulate a case where Write implementation could return partial writes
    struct MockWrite {
        max_bytes_per_write: usize,
    }

    impl Write for MockWrite {
        fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
            Ok(std::cmp::min(buf.len(), self.max_bytes_per_write))
        }

        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    // Helper function to test our function with a custom Write implementation
    fn write_buffers_to_mock(buffers: &[&[u8]], max_bytes: usize) -> io::Result<usize> {
        let mut mock = MockWrite { max_bytes_per_write: max_bytes };
        let mut total_written = 0;

        for buffer in buffers {
            let remaining = buffer;
            let mut position = 0;

            while position < remaining.len() {
                let bytes_written = mock.write(&remaining[position..])?;
                position += bytes_written;
                total_written += bytes_written;

                if bytes_written == 0 {
                    break;  // Avoid infinite loop
                }
            }
        }

        Ok(total_written)
    }

    #[test]
    fn test_partial_writes() {
        let buffer1 = b"hello";
        let buffer2 = b"world";
        let buffers: &[&[u8]] = &[buffer1, buffer2];

        // Test with a mock that writes at most 2 bytes at a time
        let result = write_buffers_to_mock(buffers, 2);

        assert!(result.is_ok());
        assert_eq!(result.unwrap(), buffer1.len() + buffer2.len());
    }
}

