    fn test_get_returns_reference() {
        let cell = initialize_once_cell(String::from("hello"));
        let reference = cell.get().unwrap();
        assert_eq!(*reference, "hello");
    }

    #[test]
    fn test_cell_is_initialized() {
        let cell = initialize_once_cell(100);
        assert!(cell.get().is_some());
    }

    #[test]
    fn test_expensive_computation_happens_once() {
        // Create a counter to track how many times computation happens
        let counter = Arc::new(AtomicUsize::new(0));
        let counter_clone = counter.clone();

        // This closure represents an expensive computation
        let expensive_operation = || {
            counter_clone.fetch_add(1, Ordering::SeqCst);
            "expensive result"
        };

        // Call the function with the expensive operation
        let cell = initialize_once_cell(expensive_operation());

        // Verify the operation was performed exactly once
        assert_eq!(counter.load(Ordering::SeqCst), 1);

        // Verify the result is correct
        assert_eq!(*cell.get().unwrap(), "expensive result");
    }

    #[test]
    fn test_with_complex_struct() {
        #[derive(Debug, PartialEq)]
        struct ComplexStruct {
            id: u32,
            name: String,
            values: Vec<f64>,
        }

        let complex = ComplexStruct {
            id: 1,
            name: String::from("test"),
            values: vec![1.0, 2.0, 3.0],
        };

        let cell = initialize_once_cell(complex);

        let stored = cell.get().unwrap();
        assert_eq!(stored.id, 1);
        assert_eq!(stored.name, "test");
        assert_eq!(stored.values, vec![1.0, 2.0, 3.0]);
    }

    #[test]
    fn test_into_inner() {
        let cell = initialize_once_cell(42);
        let value = cell.into_inner().unwrap();
        assert_eq!(value, 42);
    }

    #[test]
    fn test_with_zero_sized_type() {
        // Unit type is a zero-sized type
        let cell = initialize_once_cell(());
        assert!(cell.get().is_some());
    }
}

