        let mut was_called = false;
        let option: Option<i32> = None;

        let result: Result<i32, ExpensiveError> = transform_option(option, || {
            was_called = true;
            ExpensiveError {
                message: "expensive computation".to_string(),
                code: 500,
            }
        });

        assert!(result.is_err());
        assert_eq!(was_called, true); // Error function should be called
    }

    #[test]
    fn test_transform_option_with_captured_variables() {
        // Test with closure that captures variables from the environment
        let base_error = "base error";
        let error_code = 404;

        let option: Option<String> = None;
        let result: Result<String, String> = transform_option(
            option, 
            || format!("{}: code {}", base_error, error_code)
        );

        assert_eq!(result, Err("base error: code 404".to_string()));
    }

    #[test]
    fn test_transform_option_with_mutable_capture() {
        // Test with closure that mutates captured variables
        let mut call_count = 0;

        let option: Option<i32> = None;
        let result: Result<i32, i32> = transform_option(option, || {
            call_count += 1;
            call_count
        });

        assert_eq!(result, Err(1));

        // Call again with None to ensure the closure gets called again
        let option: Option<i32> = None;
        let result: Result<i32, i32> = transform_option(option, || {
            call_count += 1;
            call_count
        });

        assert_eq!(result, Err(2));
    }
}

