#[cfg(test)]
mod tests {
    use std::boxed::Box;

    // Import the function under test
    use super::convert_to_mutable_reference;

    #[test]
    fn test_convert_primitive_type() {
        let boxed_value = Box::new(42);
        let reference = convert_to_mutable_reference(boxed_value);

        assert_eq!(*reference, 42);

        // Verify we can mutate through the reference
        *reference = 100;
        assert_eq!(*reference, 100);
    }

    #[test]
    fn test_convert_string_type() {
        let boxed_value = Box::new(String::from("hello"));
        let reference = convert_to_mutable_reference(boxed_value);

        assert_eq!(*reference, "hello");

        // Verify we can mutate through the reference
        reference.push_str(" world");
        assert_eq!(*reference, "hello world");
    }

    #[test]
    fn test_convert_struct_type() {
        #[derive(Debug, PartialEq)]
        struct TestStruct {
            value: i32,
            name: String,
        }

        let boxed_value = Box::new(TestStruct {
            value: 10,
            name: String::from("test"),
        });

        let reference = convert_to_mutable_reference(boxed_value);

        assert_eq!(reference.value, 10);
        assert_eq!(reference.name, "test");

        // Verify we can mutate struct fields through the reference
        reference.value = 20;
        reference.name = String::from("modified");

        assert_eq!(reference.value, 20);
        assert_eq!(reference.name, "modified");
    }

    #[test]
    fn test_multiple_references() {
        let boxed_value1 = Box::new(1);
        let boxed_value2 = Box::new(2);

        let reference1 = convert_to_mutable_reference(boxed_value1);
        let reference2 = convert_to_mutable_reference(boxed_value2);

        assert_eq!(*reference1, 1);
        assert_eq!(*reference2, 2);

        // Modify both references
        *reference1 = 10;
        *reference2 = 20;

        assert_eq!(*reference1, 10);
        assert_eq!(*reference2, 20);
    }

    #[test]
    fn test_large_allocation() {
        // Test with a larger allocation to ensure it works with bigger memory blocks
        let large_vec = vec![0; 1_000_000];
        let boxed_value = Box::new(large_vec);
        let reference = convert_to_mutable_reference(boxed_value);

        assert_eq!(reference.len(), 1_000_000);

        // Modify the vector through the reference
        reference[0] = 42;
        reference[999_999] = 24;

        assert_eq!(reference[0], 42);
        assert_eq!(reference[999_999], 24);
    }

    #[test]
    fn test_reference_lifetime() {
        // This test verifies that the reference remains valid even after leaving the scope
        // where it was created

        // Create a reference in an inner scope
        let reference;
        {
            let boxed_value = Box::new(100);
            reference = convert_to_mutable_reference(boxed_value);
            assert_eq!(*reference, 100);
        }

        // Verify the reference is still valid outside the scope where the box was created
        assert_eq!(*reference, 100);
        *reference = 200;
        assert_eq!(*reference, 200);
    }
}

