mod tests {
    use super::*;
    use std::cmp::Ordering;

    #[derive(Debug, Copy, Clone, PartialEq, Eq)]
    struct Point {
        x: i32,
        y: i32,
    }

    #[test]
    fn test_compare_structures_with_integers() {
        let a = 5;
        let b = 10;

        // Compare integers naturally
        let result = compare_structures(a, b, |x, y| x.cmp(y));
        assert_eq!(result, 5);

        // Compare integers in reverse
        let result = compare_structures(a, b, |x, y| y.cmp(x));
        assert_eq!(result, 10);
    }

    #[test]
    fn test_compare_structures_with_floats() {
        let a = 3.14;
        let b = 2.71;

        // For floats, we need to use partial_cmp
        let result = compare_structures(a, b, |x, y| {
            x.partial_cmp(y).unwrap_or(Ordering::Equal)
        });
        assert_eq!(result, 2.71);
    }

    #[test]
    fn test_compare_structures_with_equal_values() {
        let a = 42;
        let b = 42;

        let result = compare_structures(a, b, |x, y| x.cmp(y));
        assert_eq!(result, 42);
    }

    #[test]
    fn test_compare_structures_with_custom_struct() {
        let point_a = Point { x: 3, y: 4 };
        let point_b = Point { x: 1, y: 8 };

        // Compare by x-coordinate
        let result = compare_structures(point_a, point_b, |p1, p2| p1.x.cmp(&p2.x));
        assert_eq!(result, Point { x: 1, y: 8 });

        // Compare by y-coordinate
        let result = compare_structures(point_a, point_b, |p1, p2| p1.y.cmp(&p2.y));
        assert_eq!(result, Point { x: 3, y: 4 });

        // Compare by Manhattan distance from origin (x + y)
        let result = compare_structures(point_a, point_b, |p1, p2| {
            let dist1 = p1.x.abs() + p1.y.abs();
            let dist2 = p2.x.abs() + p2.y.abs();
            dist1.cmp(&dist2)
        });
        assert_eq!(result, Point { x: 3, y: 4 });
    }

    #[test]
    fn test_compare_structures_with_strings() {
        let a = "hello";
        let b = "world";

        // Lexicographic comparison
        let result = compare_structures(a, b, |x, y| x.cmp(y));
        assert_eq!(result, "hello");

        // Compare by length
        let result = compare_structures(a, b, |x, y| x.len().cmp(&y.len()));
        assert_eq!(result, "hello"); // Both are 5 chars, but first arg returned for equal
    }

    #[test]
    fn test_compare_structures_with_tuples() {
        let a = (5, "apple");
        let b = (3, "banana");

        // Compare by first element
        let result = compare_structures(a, b, |x, y| x.0.cmp(&y.0));
        assert_eq!(result, (3, "banana"));

        // Compare by second element
        let result = compare_structures(a, b, |x, y| x.1.cmp(&y.1));
        assert_eq!(result, (5, "apple"));
    }

    #[test]
    fn test_compare_structures_with_custom_complex_comparison() {
        let point_a = Point { x: 5, y: 10 };
        let point_b = Point { x: 10, y: 5 };

        // Compare points by distance from origin using Euclidean distance
        let result = compare_structures(point_a, point_b, |p1, p2| {
            let dist1 = (p1.x * p1.x + p1.y * p1.y) as f64;
            let dist2 = (p2.x * p2.x + p2.y * p2.y) as f64;

            if dist1 < dist2 {
                Ordering::Less
            } else if dist1 > dist2 {
                Ordering::Greater
            } else {
                Ordering::Equal
            }
        });

        // Both points have the same distance from origin (sqrt(125)), so either could be returned
        // but in min_by's implementation, the first argument is returned if they're equal
        assert_eq!(result, point_a);
    }
}

