#[cfg(test)]
mod tests {
    use super::*;
    use std::fmt::{self, Debug};
    use std::rc::Rc;
    use std::sync::Arc;

    // A custom type that implements PartialEq
    #[derive(Debug, PartialEq)]
    struct TestStruct {
        value: i32,
    }

    // A custom type with unsized inner content
    struct UnsizedWrapper<T: ?Sized> {
        data: Box<T>,
    }

    impl<T: ?Sized + PartialEq> PartialEq for UnsizedWrapper<T> {
        fn eq(&self, other: &Self) -> bool {
            self.data.eq(&other.data)
        }
    }

    impl<T: ?Sized + Debug> Debug for UnsizedWrapper<T> {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            write!(f, "UnsizedWrapper({:?})", self.data)
        }
    }

    #[test]
    fn test_compare_primitive_types() {
        // Integer tuples
        let t1 = (5,);
        let t2 = (5,);
        let t3 = (10,);

        assert!(compare_tuples(&t1, &t2));
        assert!(!compare_tuples(&t1, &t3));

        // Float tuples
        let f1 = (3.14,);
        let f2 = (3.14,);
        let f3 = (2.71,);

        assert!(compare_tuples(&f1, &f2));
        assert!(!compare_tuples(&f1, &f3));

        // String tuples
        let s1 = ("hello",);
        let s2 = ("hello",);
        let s3 = ("world",);

        assert!(compare_tuples(&s1, &s2));
        assert!(!compare_tuples(&s1, &s3));
    }

    #[test]
    fn test_compare_custom_types() {
        let t1 = (TestStruct { value: 42 },);
        let t2 = (TestStruct { value: 42 },);
        let t3 = (TestStruct { value: 100 },);

        assert!(compare_tuples(&t1, &t2));
        assert!(!compare_tuples(&t1, &t3));
    }

    #[test]
    fn test_compare_unsized_types() {
        // Slices as unsized types
        let slice1: Box<[i32]> = Box::new([1, 2, 3]);
        let slice2: Box<[i32]> = Box::new([1, 2, 3]);
        let slice3: Box<[i32]> = Box::new([1, 2, 3, 4]);

        let s1: &[i32] = slice1.as_ref();
        let s2: &[i32] = slice2.as_ref();
        let s3: &[i32] = slice3.as_ref();

        assert!(compare_tuples(&(s1,), &(s2,)));
        assert!(!compare_tuples(&(s1,), &(s3,)));

        // String slices
        let str1: Box<str> = "test string".into();
        let str2: Box<str> = "test string".into();
        let str3: Box<str> = "different string".into();

        let ss1: &str = str1.as_ref();
        let ss2: &str = str2.as_ref();
        let ss3: &str = str3.as_ref();

        assert!(compare_tuples(&(ss1,), &(ss2,)));
        assert!(!compare_tuples(&(ss1,), &(ss3,)));
    }

    #[test]
    fn test_compare_with_trait_objects() {
        // Creating trait objects
        trait MyTrait: Debug {
            fn get_value(&self) -> i32;
        }

        impl PartialEq for dyn MyTrait {
            fn eq(&self, other: &Self) -> bool {
                self.get_value() == other.get_value()
            }
        }

        #[derive(Debug)]
        struct Impl1 { val: i32 }
        #[derive(Debug)]
        struct Impl2 { val: i32 }

        impl MyTrait for Impl1 {
            fn get_value(&self) -> i32 { self.val }
        }

        impl MyTrait for Impl2 {
            fn get_value(&self) -> i32 { self.val }
        }

        let obj1: Box<dyn MyTrait> = Box::new(Impl1 { val: 42 });
        let obj2: Box<dyn MyTrait> = Box::new(Impl2 { val: 42 });
        let obj3: Box<dyn MyTrait> = Box::new(Impl1 { val: 100 });

        let to1: &dyn MyTrait = obj1.as_ref();
        let to2: &dyn MyTrait = obj2.as_ref();
        let to3: &dyn MyTrait = obj3.as_ref();

        assert!(compare_tuples(&(to1,), &(to2,)));
        assert!(!compare_tuples(&(to1,), &(to3,)));
    }

    #[test]
    fn test_compare_with_smart_pointers() {
        // Rc
        let rc1 = Rc::new([1, 2, 3]);
        let rc2 = Rc::new([1, 2, 3]);
        let rc3 = Rc::new([4, 5, 6]);

        let rc_ref1: &[i32] = rc1.as_ref();
