        let mut value = ManuallyDrop::new(String::from("Hello"));
        let inner_ref = modify_manually_drop(&mut value);

        // Modify the string
        inner_ref.push_str(", World!");

        // Check that the modification happened
        assert_eq!(inner_ref, "Hello, World!");
    }

