    fn test_modify_struct() {
        // Define a test struct
        struct TestStruct {
            field1: i32,
            field2: String,
        }

        // Create an instance wrapped in ManuallyDrop
        let mut value = ManuallyDrop::new(TestStruct {
            field1: 10,
            field2: String::from("test"),
        });

        // Get mutable reference to inner value
        let inner_ref = modify_manually_drop(&mut value);

        // Modify struct fields
        inner_ref.field1 = 20;
        inner_ref.field2 = String::from("modified");

        // Check that modifications happened
        assert_eq!(inner_ref.field1, 20);
        assert_eq!(inner_ref.field2, "modified");
    }

    #[test]
    fn test_modify_vec() {
        // Test with a Vec (heap-allocated type)
        let mut value = ManuallyDrop::new(vec![1, 2, 3]);
        let inner_ref = modify_manually_drop(&mut value);

        // Modify the vector
        inner_ref.push(4);
        inner_ref[0] = 10;

        // Check modifications
        assert_eq!(inner_ref, &vec![10, 2, 3, 4]);
        assert_eq!(inner_ref.len(), 4);
    }

    #[test]
    fn test_reference_identity() {
        // Test that the returned reference points to the same memory
        // as the original value
        let mut value = ManuallyDrop::new(String::from("test"));
        let inner_ref = modify_manually_drop(&mut value);

        // Get raw pointers for comparison
        let value_ptr = inner_ref as *const String;
        let inner_ref_ptr = inner_ref as *const String;

        // Pointers should be identical
        assert_eq!(value_ptr, inner_ref_ptr);
    }

    #[test]
    fn test_nested_manually_drop() {
        // Test with nested ManuallyDrop
        let mut nested = ManuallyDrop::new(
            ManuallyDrop::new(42)
