        // First unwrap the outer ManuallyDrop
        let inner_ref = modify_manually_drop(&mut nested);

        // Then unwrap the inner ManuallyDrop
        let final_ref = modify_manually_drop(inner_ref);

        // Modify the value
        *final_ref = 100;

        // Verify through the reference chain
        assert_eq!(*final_ref, 100);
    }
