        unsafe {
            // Should not modify anything since indices is empty
            modify_slice_elements(&mut data, &indices, |x| *x *= 10);
        }

        assert_eq!(data, vec![1, 2, 3]);
    }

    #[test]
    fn test_with_custom_struct() {
        #[derive(Debug, PartialEq)]
        struct Point {
            x: i32,
            y: i32,
        }

        let mut points = vec![
            Point { x: 1, y: 2 },
            Point { x: 3, y: 4 },
            Point { x: 5, y: 6 },
        ];

        let indices = vec![0, 2];

        unsafe {
            modify_slice_elements(&mut points, &indices, |p| {
                p.x *= 2;
                p.y *= 2;
            });
        }

        assert_eq!(points[0], Point { x: 2, y: 4 });
        assert_eq!(points[1], Point { x: 3, y: 4 });
        assert_eq!(points[2], Point { x: 10, y: 12 });
    }

    #[test]
    #[should_panic(expected = "index out of bounds")]
    fn test_out_of_bounds_access() {
        let mut data = vec![1, 2, 3];
        let indices = vec![5]; // Index 5 is out of bounds

        // First validate indices to trigger a controlled panic for the test
        for &idx in &indices {
            assert!(idx < data.len(), "index out of bounds");
        }

        unsafe {
            // This code shouldn't be reached in this test
            modify_slice_elements(&mut data, &indices, |x| *x *= 10);
        }
    }
}

