    }

    #[test]
    fn test_persist_log_message_empty() {
        let message = String::new();
        let static_str = persist_log_message(message);

        assert_eq!(static_str, "");
        assert_eq!(static_str.len(), 0);
    }

    #[test]
    fn test_persist_log_message_with_special_chars() {
        let message = "Special 😊 chars 🦀 #@!".to_string();
        let static_str = persist_log_message(message);

        assert_eq!(static_str, "Special 😊 chars 🦀 #@!");
    }

    #[test]
    fn test_persist_log_message_long_string() {
        let long_message = "a".repeat(1000);
        let static_str = persist_log_message(long_message.clone());

        assert_eq!(static_str, long_message.as_str());
        assert_eq!(static_str.len(), 1000);
    }

    #[test]
    fn test_persist_log_message_multiple_calls() {
        let message1 = "First message".to_string();
        let message2 = "Second message".to_string();

        let static_str1 = persist_log_message(message1);
        let static_str2 = persist_log_message(message2);

        // Ensure they are different strings
        assert_ne!(static_str1, static_str2);
        assert_ne!(static_str1 as *const str, static_str2 as *const str);

        // Modify one without affecting the other
        static_str1.make_ascii_uppercase();
        assert_eq!(static_str1, "FIRST MESSAGE");
        assert_eq!(static_str2, "Second message");
    }

    #[test]
    fn test_persist_log_message_persistence() {
        let message = "This will persist".to_string();
        let static_str_ptr: *mut str;

        // Scope to demonstrate that static_str outlives this scope
        {
            let static_str = persist_log_message(message);
            static_str_ptr = static_str as *mut str;
            assert_eq!(static_str, "This will persist");
        }

        // Outside the scope, the memory should still be valid
        unsafe {
            let still_valid = &mut *static_str_ptr;
            assert_eq!(still_valid, "This will persist");

            // Can still modify it
            still_valid.make_ascii_uppercase();
            assert_eq!(still_valid, "THIS WILL PERSIST");
        }
    }

    #[test]
    fn test_persist_log_message_memory_layout() {
        let original = "Memory layout test".to_string();

        let static_str = persist_log_message(original);

        // The leaked string should maintain the same memory layout
        assert!(ptr::eq(static_str.as_ptr(), static_str.as_ptr()));

        // In a real application, checking capacity would require unsafe code
        // This is just to demonstrate that the memory layout is preserved
        assert_eq!(static_str.len(), "Memory layout test".len());
    }
}

