#[cfg(test)]
mod tests {
    use std::sync::Arc;

    // Import the function being tested
    use super::are_arcs_same_allocation;

    #[test]
    fn test_same_allocation() {
        // Create a single Arc instance
        let data = Arc::new(42);

        // Create a clone of the Arc
        let data_clone = Arc::clone(&data);

        // Both should point to the same allocation
        assert!(are_arcs_same_allocation(&data, &data_clone));
    }

    #[test]
    fn test_different_allocation() {
        // Create two separate Arc instances with the same value
        let data1 = Arc::new(42);
        let data2 = Arc::new(42);

        // These should be different allocations despite having the same value
        assert!(!are_arcs_same_allocation(&data1, &data2));
    }

    #[test]
    fn test_after_drop() {
        // Create an original Arc
        let data1 = Arc::new(String::from("test"));

        // Create a second reference
        let data1_clone = Arc::clone(&data1);

        // Create a third Arc with different allocation
        let data2 = Arc::new(String::from("test"));

        // Verify our starting state
        assert!(are_arcs_same_allocation(&data1, &data1_clone));
        assert!(!are_arcs_same_allocation(&data1, &data2));

        // Drop the original reference
        drop(data1);

        // Clone should still point to the same allocation
        assert!(!are_arcs_same_allocation(&data1_clone, &data2));
    }

    #[test]
    fn test_different_types() {
        // Test with different concrete types

        // String type
        let string1 = Arc::new(String::from("hello"));
        let string2 = Arc::clone(&string1);
        let string3 = Arc::new(String::from("hello"));

        assert!(are_arcs_same_allocation(&string1, &string2));
        assert!(!are_arcs_same_allocation(&string1, &string3));

        // Vec type
        let vec1 = Arc::new(vec![1, 2, 3]);
        let vec2 = Arc::clone(&vec1);
        let vec3 = Arc::new(vec![1, 2, 3]);

        assert!(are_arcs_same_allocation(&vec1, &vec2));
        assert!(!are_arcs_same_allocation(&vec1, &vec3));

        // Custom struct type
        struct TestStruct {
            value: i32,
        }

        let struct1 = Arc::new(TestStruct { value: 10 });
        let struct2 = Arc::clone(&struct1);
        let struct3 = Arc::new(TestStruct { value: 10 });

        assert!(are_arcs_same_allocation(&struct1, &struct2));
        assert!(!are_arcs_same_allocation(&struct1, &struct3));
    }

    #[test]
    fn test_empty_types() {
        // Test with empty/zero-sized types
        let empty1 = Arc::new(());
        let empty2 = Arc::clone(&empty1);
        let empty3 = Arc::new(());

        assert!(are_arcs_same_allocation(&empty1, &empty2));
        assert!(!are_arcs_same_allocation(&empty1, &empty3));
    }

    #[test]
    fn test_nested_arcs() {
        // Test with nested Arc types
        let nested1 = Arc::new(Arc::new(5));
        let nested2 = Arc::clone(&nested1);
        let nested3 = Arc::new(Arc::new(5));

        // Outer Arcs should follow the same rules
        assert!(are_arcs_same_allocation(&nested1, &nested2));
        assert!(!are_arcs_same_allocation(&nested1, &nested3));

        // Inner Arcs should also follow the same rules, but need to be dereferenced first
        assert!(are_arcs_same_allocation(&nested1, &nested2));
        assert!(!are_arcs_same_allocation(&nested1.as_ref(), &nested3.as_ref()));
    }
}

