use std::collections::BTreeMap;
use std::time::{Duration, Instant};

pub struct SessionData {
    last_active: Instant,
}

pub fn remove_inactive_sessions(sessions: &mut BTreeMap<u32, SessionData>, max_inactive_duration: Duration) -> usize {
    let now = Instant::now();
    let initial_len = sessions.len();
    sessions.retain(|_, session| now.duration_since(session.last_active) <= max_inactive_duration);
    initial_len - sessions.len()
}

