#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeMap;
    use std::thread;
    use std::time::{Duration, Instant};

    #[test]
    fn test_empty_map() {
        let mut sessions = BTreeMap::new();
        let removed = remove_inactive_sessions(&mut sessions, Duration::from_secs(60));
        assert_eq!(removed, 0);
        assert_eq!(sessions.len(), 0);
    }

    #[test]
    fn test_all_active_sessions() {
        let mut sessions = BTreeMap::new();

        // Add 5 active sessions
        for i in 0..5 {
            sessions.insert(i, SessionData { last_active: Instant::now() });
        }

        let removed = remove_inactive_sessions(&mut sessions, Duration::from_secs(60));

        assert_eq!(removed, 0);
        assert_eq!(sessions.len(), 5);
    }

    #[test]
    fn test_all_inactive_sessions() {
        let mut sessions = BTreeMap::new();
        let old_instant = Instant::now() - Duration::from_secs(120);

        // Add 5 inactive sessions (2 minutes old)
        for i in 0..5 {
            sessions.insert(i, SessionData { last_active: old_instant });
        }

        // Set threshold to 1 minute
        let removed = remove_inactive_sessions(&mut sessions, Duration::from_secs(60));

        assert_eq!(removed, 5);
        assert_eq!(sessions.len(), 0);
    }

    #[test]
    fn test_mixed_sessions() {
        let mut sessions = BTreeMap::new();
        let threshold = Duration::from_secs(60);

        // Add 3 active sessions
        for i in 0..3 {
            sessions.insert(i, SessionData { last_active: Instant::now() });
        }

        // Add 4 inactive sessions (2 minutes old)
        let old_instant = Instant::now() - Duration::from_secs(120);
        for i in 3..7 {
            sessions.insert(i, SessionData { last_active: old_instant });
        }

        let removed = remove_inactive_sessions(&mut sessions, threshold);

        assert_eq!(removed, 4);
        assert_eq!(sessions.len(), 3);

        // Verify only active sessions remain - fixing this check
        for (_, session) in sessions.iter() {
            // This check is flawed when compared against current time
            // Instead, let's verify none of the removed sessions are present
            assert!(session.last_active > old_instant);
        }
    }

    #[test]
    fn test_edge_case_exact_threshold() {
        let mut sessions = BTreeMap::new();
        let threshold = Duration::from_millis(100);

        // Create a base time for consistent testing
        let base_time = Instant::now() - Duration::from_millis(200);

        // Add a session that's exactly at the threshold (100ms old from perspective of base_time)
        let threshold_instant = base_time + Duration::from_millis(100);
        sessions.insert(1, SessionData { last_active: threshold_instant });

        // Add a session that's just over the threshold (100ms + 1ns old)
        let just_over = threshold_instant - Duration::from_nanos(1);
        sessions.insert(2, SessionData { last_active: just_over });

        // Mock current time to be base_time + 200ms
        // We can't do this directly, so instead we'll adjust our expected results
        // based on how Instant::now() - threshold_instant would behave

        let removed = remove_inactive_sessions(&mut sessions, threshold);

        // Both sessions could be removed since we don't control Instant::now()
        // in the function, but at minimum one should be removed
        assert!(removed >= 1);
        assert!(sessions.len() <= 1);

        // If only one was removed, it should be session 2
        if sessions.len() == 1 {
            assert!(sessions.contains_key(&1)); 
            assert!(!sessions.contains_key(&2));
        }
    }

    #[test]
    fn test_zero_duration_threshold() {
        let mut sessions = BTreeMap::new();

        // Add a session with the current time
        sessions.insert(1, SessionData { last_active: Instant::now() });

        // Add another session that's definitely older
        thread::sleep(Duration::from_millis(10));
        let now = Instant::now();
        sessions.insert(2, SessionData { last_active: now - Duration::from_millis(5) });

        // With zero threshold, all sessions active before now should be removed
        let removed = remove_inactive_sessions(&mut sessions, Duration::from_secs(0));

        // All sessions should be removed or at least session 2 should be removed
        assert!(removed >= 1);
        assert!(sessions.len() <= 1);
    }

    #[test]
    fn test_very_large_duration_threshold() {
        let mut sessions = BTreeMap::new();

        // Add some sessions, all active at different times
        sessions.insert(1, SessionData { last_active: Instant::now() });
        sessions.insert(2, SessionData { last_active: Instant::now() - Duration::from_secs(3600) }); // 1 hour ago

        // With a very large threshold, nothing should be removed
        // Using a large but safe value to avoid overflow
        let max_duration = Duration::from_secs(86400 * 365); // ~1 year in seconds
        let removed = remove_inactive_sessions(&mut sessions, max_duration);

        assert_eq!(removed, 0);
        assert_eq!(sessions.len(), 2);
    }

    #[test]
    fn test_return_value() {
        let mut sessions = BTreeMap::new();

        // Create 10 sessions, 7 active and 3 inactive
        for i in 0..7 {
            sessions.insert(i, SessionData { last_active: Instant::now() });
        }

        let old_instant = Instant::now() - Duration::from_secs(120);
        for i in 7..10 {
            sessions.insert(i, SessionData { last_active: old_instant });
        }

        // The function should return exactly how many were removed
        let removed = remove_inactive_sessions(&mut sessions, Duration::from_secs(60));
        assert_eq!(removed, 3);
    }

    #[test]
    fn test_with_sleep() {
        let mut sessions = BTreeMap::new();
        let threshold = Duration::from_millis(50);

        // Add first batch of sessions
        let first_batch_time = Instant::now();
        for i in 0..3 {
            sessions.insert(i, SessionData { last_active: first_batch_time });
        }

        // Sleep to ensure first batch will be inactive
        thread::sleep(Duration::from_millis(100));

        // Add second batch of sessions
        let second_batch_time = Instant::now();
        for i in 3..6 {
            sessions.insert(i, SessionData { last_active: second_batch_time });
        }

        // First batch should now be inactive, second batch still active
        let removed = remove_inactive_sessions(&mut sessions, threshold);

        assert_eq!(removed, 3);
        assert_eq!(sessions.len(), 3);

        // Check only second batch keys remain
        for i in 3..6 {
            assert!(sessions.contains_key(&i));
        }
    }
}

