use std::collections::BinaryHeap;
use std::collections::binary_heap::PeekMut;

fn modify_top_element<T: Ord>(heap: &mut BinaryHeap<T>, modifier: impl FnOnce(&mut T)) -> Result<(), &'static str> {
    if let Some(mut top) = heap.peek_mut() {
        modifier(&mut top);
        Ok(())
    } else {
        Err("Heap is empty")
    }
}

