#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BinaryHeap;
    use std::cmp::Reverse;

    #[test]
    fn test_modify_top_element_increases_value() {
        let mut heap = BinaryHeap::new();
        heap.push(5);
        heap.push(3);
        heap.push(1);

        // Before modification, top should be 5
        assert_eq!(heap.peek(), Some(&5));

        // Modify the top element by increasing it
        let result = modify_top_element(&mut heap, |x| *x += 10);

        // Check result is Ok
        assert!(result.is_ok());

        // After modification, top should be 15
        assert_eq!(heap.peek(), Some(&15));

        // Check the heap property is maintained
        assert_eq!(heap.pop(), Some(15));
        assert_eq!(heap.pop(), Some(3));
        assert_eq!(heap.pop(), Some(1));
        assert_eq!(heap.pop(), None);
    }

    #[test]
    fn test_modify_top_element_decreases_value() {
        let mut heap = BinaryHeap::new();
        heap.push(5);
        heap.push(3);
        heap.push(1);

        // Before modification, top should be 5
        assert_eq!(heap.peek(), Some(&5));

        // Modify the top element by decreasing it
        let result = modify_top_element(&mut heap, |x| *x -= 4);

        // Check result is Ok
        assert!(result.is_ok());

        // After modification, heap property is restored automatically by PeekMut
        assert_eq!(heap.peek(), Some(&3));

        // Check the heap property is maintained
        assert_eq!(heap.pop(), Some(3));
        assert_eq!(heap.pop(), Some(1));
        assert_eq!(heap.pop(), Some(1)); // The original 5 is now 1
        assert_eq!(heap.pop(), None);
    }

    #[test]
    fn test_modify_top_element_min_heap() {
        // Create a min-heap using BinaryHeap with Reverse
        let mut min_heap = BinaryHeap::new();
        min_heap.push(Reverse(10));
        min_heap.push(Reverse(20));
        min_heap.push(Reverse(30));

        // Before modification, top should be Reverse(10)
        assert_eq!(min_heap.peek(), Some(&Reverse(10)));

        // Modify the top element
        let result = modify_top_element(&mut min_heap, |x| x.0 += 25);

        // Check result is Ok
        assert!(result.is_ok());

        // After modification, heap property should be restored
        assert_eq!(min_heap.peek(), Some(&Reverse(20)));

        // Check the heap property is maintained
        assert_eq!(min_heap.pop(), Some(Reverse(20)));
        assert_eq!(min_heap.pop(), Some(Reverse(30)));
        assert_eq!(min_heap.pop(), Some(Reverse(35))); // Original Reverse(10) is now Reverse(35)
        assert_eq!(min_heap.pop(), None);
    }

    #[test]
    fn test_modify_top_element_empty_heap() {
        let mut empty_heap: BinaryHeap<i32> = BinaryHeap::new();

        // Attempting to modify an empty heap should return an error
        let result = modify_top_element(&mut empty_heap, |x| *x += 1);

        // Check result is Err with correct message
        assert_eq!(result, Err("Heap is empty"));

        // Heap should still be empty
        assert_eq!(empty_heap.len(), 0);
    }

    #[test]
    fn test_modify_top_element_custom_type() {
        #[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
        struct Task {
            priority: i32,
            id: String,
        }

        let mut heap = BinaryHeap::new();
        heap.push(Task { priority: 10, id: "task1".to_string() });
        heap.push(Task { priority: 5, id: "task2".to_string() });
        heap.push(Task { priority: 7, id: "task3".to_string() });

        // Before modification, top should be the task with priority 10
        assert_eq!(heap.peek().unwrap().priority, 10);
        assert_eq!(heap.peek().unwrap().id, "task1");

        // Modify the top element by changing its priority
        let result = modify_top_element(&mut heap, |task| {
            task.priority = 3;
            task.id = "modified_task1".to_string();
        });

        // Check result is Ok
        assert!(result.is_ok());

        // After modification, heap property should be restored
        assert_eq!(heap.peek().unwrap().priority, 7);
        assert_eq!(heap.peek().unwrap().id, "task3");

        // Check the heap property is maintained
        let top = heap.pop().unwrap();
        assert_eq!(top.priority, 7);
        assert_eq!(top.id, "task3");

        let next = heap.pop().unwrap();
        assert_eq!(next.priority, 5);
        assert_eq!(next.id, "task2");

        let last = heap.pop().unwrap();
        assert_eq!(last.priority, 3);
        assert_eq!(last.id, "modified_task1");
    }

    #[test]
    fn test_modify_top_element_preserves_heap_size() {
        let mut heap = BinaryHeap::new();
        for i in 0..5 {
            heap.push(i);
        }

        // Heap initially has 5 elements
        assert_eq!(heap.len(), 5);

        // Modify the top element
        let _ = modify_top_element(&mut heap, |x| *x = 100);

        // Heap should still have 5 elements
        assert_eq!(heap.len(), 5);
    }

    #[test]
    fn test_modify_top_element_complex_modification() {
        let mut heap = BinaryHeap::new();
        heap.push(5);
        heap.push(3);
        heap.push(1);

        // Modify with a complex logic
        let result = modify_top_element(&mut heap, |x| {
            if *x > 3 {
                *x -= 10;  // This should make it negative and move it down
            } else {
                *x += 10;  // This would move it up
            }
        });

        assert!(result.is_ok());

        // After this modification, the heap should have rebalanced
        assert_eq!(heap.pop(), Some(3));
        assert_eq!(heap.pop(), Some(1));
        assert_eq!(heap.pop(), Some(-5)); // Original 5 is now -5
        assert_eq!(heap.pop(), None);
    }

    #[test]
    fn test_modify_top_element_with_vec_as_inner_value() {
        // Using vectors as the elements in the heap
        let mut heap = BinaryHeap::new();
        heap.push(vec![3, 2, 1]);
        heap.push(vec![1, 2]);
        heap.push(vec![2]);

        // Before modification, top should be [3, 2, 1] (longest lexicographically)
        assert_eq!(heap.peek().unwrap(), &vec![3, 2, 1]);

        // Modify the top element by changing the vector
        let result = modify_top_element(&mut heap, |v| {
            v.clear();
            v.push(0);
        });

        // Check result is Ok
        assert!(result.is_ok());

        // After modification, heap property should be restored
        assert_eq!(heap.peek().unwrap(), &vec![2]);

        // Check the heap property is maintained
        assert_eq!(heap.pop(), Some(vec![2]));
        assert_eq!(heap.pop(), Some(vec![1, 2]));
        assert_eq!(heap.pop(), Some(vec![0])); // Modified vector
        assert_eq!(heap.pop(), None);
    }
}

