use std::io::{self, Cursor, LineWriter, Write};

fn write_log_entry<W: ?Sized + Write>(writer: &mut LineWriter<W>, entry: &[u8]) -> io::Result<()> {
    // Directly use the write method to ensure we're following the requirement
    let mut bytes_written = 0;
    let total_bytes = entry.len();

    // Continue writing until we've written the entire entry
    while bytes_written < total_bytes {
        match writer.write(&entry[bytes_written..]) {
            Ok(0) => return Err(io::Error::new(io::ErrorKind::WriteZero, "failed to write log entry")),
            Ok(n) => bytes_written += n,
            Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e),
        }
    }

    // Flush to ensure the entry is actually written
    writer.flush()
}

