#[cfg(test)]
mod tests {
    use super::*;

    // Mock writer that can fail after a certain number of bytes
    struct MockLimitedWriter {
        data: Vec<u8>,
        write_limit: usize,
        bytes_written: usize,
        interrupt_on: Option<usize>,
        interrupt_count: usize,
    }

    impl MockLimitedWriter {
        fn new(write_limit: usize) -> Self {
            Self {
                data: Vec::new(),
                write_limit,
                bytes_written: 0,
                interrupt_on: None,
                interrupt_count: 0,
            }
        }

        fn with_interrupt(write_limit: usize, interrupt_on: usize) -> Self {
            Self {
                data: Vec::new(),
                write_limit,
                bytes_written: 0,
                interrupt_on: Some(interrupt_on),
                interrupt_count: 0,
            }
        }
    }

    impl Write for MockLimitedWriter {
        fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
            // Check if we should simulate an interrupt
            if let Some(interrupt_point) = self.interrupt_on {
                if self.bytes_written == interrupt_point && self.interrupt_count < 1 {
                    self.interrupt_count += 1;
                    return Err(io::Error::new(io::ErrorKind::Interrupted, "interrupted"));
                }
            }

            // If we've reached the write limit, return WriteZero
            if self.bytes_written >= self.write_limit {
                return Ok(0);
            }

            // Calculate how many bytes we can write before hitting the limit
            let remaining = self.write_limit - self.bytes_written;
            let bytes_to_write = std::cmp::min(buf.len(), remaining);

            // Write the bytes
            self.data.extend_from_slice(&buf[..bytes_to_write]);
            self.bytes_written += bytes_to_write;

            Ok(bytes_to_write)
        }

        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    #[test]
    fn test_successful_write() -> io::Result<()> {
        let buffer = Cursor::new(Vec::new());
        let mut writer = LineWriter::new(buffer);
        let entry = b"This is a log entry";

        write_log_entry(&mut writer, entry)?;

        writer.flush()?;
        let buffer = writer.into_inner()?;
        assert_eq!(buffer.into_inner(), entry);
        Ok(())
    }

    #[test]
    fn test_empty_entry() -> io::Result<()> {
        let buffer = Cursor::new(Vec::new());
        let mut writer = LineWriter::new(buffer);
        let entry = b"";

        write_log_entry(&mut writer, entry)?;

        writer.flush()?;
        let buffer = writer.into_inner()?;
        assert_eq!(buffer.into_inner(), entry);
        Ok(())
    }

    #[test]
    fn test_multiple_write_operations() -> io::Result<()> {
        let mock_writer = MockLimitedWriter::new(5);
        let mut writer = LineWriter::new(mock_writer);
        let entry = b"This is a longer log entry that will require multiple writes";

        let result = write_log_entry(&mut writer, entry);

        assert!(result.is_err());
        if let Err(e) = result {
            assert_eq!(e.kind(), io::ErrorKind::WriteZero);
        }

        Ok(())
    }

    #[test]
    fn test_write_with_interruption() -> io::Result<()> {
        let mock_writer = MockLimitedWriter::with_interrupt(100, 5);
        let mut writer = LineWriter::new(mock_writer);
        let entry = b"This log entry will be interrupted but should still complete";

        write_log_entry(&mut writer, entry)?;

        // Extract the inner writer to check its contents
        let inner_writer = writer.into_inner()?;
        assert_eq!(inner_writer.data, entry);

        Ok(())
    }

    #[test]
    fn test_large_entry() -> io::Result<()> {
        let buffer = Cursor::new(Vec::new());
        let mut writer = LineWriter::new(buffer);
        // Create a 100KB entry
        let entry = vec![b'A'; 102400];

        write_log_entry(&mut writer, &entry)?;

        writer.flush()?;
        let buffer = writer.into_inner()?;
        let final_buffer = buffer.into_inner();
        assert_eq!(final_buffer.len(), entry.len());
        assert_eq!(final_buffer, entry);

        Ok(())
    }

    #[test]
    fn test_binary_data() -> io::Result<()> {
        let buffer = Cursor::new(Vec::new());
        let mut writer = LineWriter::new(buffer);
        // Include null bytes and other binary data
        let entry = b"\x00\x01\x02\xFF\xFE\xFD\x00This\x00is\x00binary\x00data";

        write_log_entry(&mut writer, entry)?;

        writer.flush()?;
        let buffer = writer.into_inner()?;
        assert_eq!(buffer.into_inner(), entry);

        Ok(())
    }
}

