    enum TestEnum {
        A,
        B(i32),
    }

    // Unit test functions
    #[test]
    fn test_same_types() {
        assert!(are_types_equal::<i32, i32>());
        assert!(are_types_equal::<&str, &str>());
        assert!(are_types_equal::<Foo, Foo>());
        assert!(are_types_equal::<TestEnum, TestEnum>());
    }

    #[test]
    fn test_different_types() {
        assert!(!are_types_equal::<i32, u32>());
        assert!(!are_types_equal::<i32, i64>());
        assert!(!are_types_equal::<&str, String>());
        assert!(!are_types_equal::<Foo, Bar>());
        assert!(!are_types_equal::<TestEnum, Foo>());
    }

    #[test]
    fn test_with_references() {
        assert!(are_types_equal::<&i32, &i32>());
        assert!(!are_types_equal::<&i32, &u32>());
        assert!(!are_types_equal::<&i32, i32>());
        assert!(!are_types_equal::<&mut i32, &i32>());
    }

    #[test]
    fn test_with_lifetimes() {
        // All references with 'static lifetime
        assert!(are_types_equal::<&'static str, &'static str>());

        // Different reference types with same static lifetime
        assert!(!are_types_equal::<&'static str, &'static i32>());
    }

    #[test]
    fn test_with_generics() {
        assert!(are_types_equal::<Vec<i32>, Vec<i32>>());
        assert!(!are_types_equal::<Vec<i32>, Vec<u32>>());

        assert!(are_types_equal::<Baz<i32>, Baz<i32>>());
        assert!(!are_types_equal::<Baz<i32>, Baz<u32>>());
    }

    #[test]
    fn test_with_nested_generics() {
        assert!(are_types_equal::<Option<Vec<i32>>, Option<Vec<i32>>>());
        assert!(!are_types_equal::<Option<Vec<i32>>, Option<Vec<u32>>>());

        assert!(are_types_equal::<Result<Vec<String>, i32>, Result<Vec<String>, i32>>());
        assert!(!are_types_equal::<Result<Vec<String>, i32>, Result<Vec<&str>, i32>>());
    }

    #[test]
    fn test_with_trait_objects() {
        assert!(are_types_equal::<Box<dyn Debug>, Box<dyn Debug>>());
        assert!(!are_types_equal::<Box<dyn Debug>, Box<dyn TestTrait>>());
    }

    #[test]
    fn test_with_smart_pointers() {
        assert!(are_types_equal::<Rc<i32>, Rc<i32>>());
        assert!(!are_types_equal::<Rc<i32>, Rc<u32>>());

        assert!(are_types_equal::<RefCell<String>, RefCell<String>>());
        assert!(!are_types_equal::<RefCell<String>, RefCell<&str>>());
    }

    #[test]
    fn test_with_arrays_and_tuples() {
        assert!(are_types_equal::<[i32; 5], [i32; 5]>());
        assert!(!are_types_equal::<[i32; 5], [i32; 4]>());
        assert!(!are_types_equal::<[i32; 5], [u32; 5]>());

        assert!(are_types_equal::<(i32, &str), (i32, &str)>());
        assert!(!are_types_equal::<(i32, &str), (&str, i32)>());
    }

    #[test]
    fn test_with_functions() {
        type Fn1 = fn(i32) -> i32;
        type Fn2 = fn(i32) -> u32;

        assert!(are_types_equal::<Fn1, Fn1>());
        assert!(!are_types_equal::<Fn1, Fn2>());
    }

    #[test]
    fn test_unit_type() {
        assert!(are_types_equal::<(), ()>());
        assert!(!are_types_equal::<(), bool>());
    }

