mod tests {
    use std::rc::Rc;
    use super::is_same_allocation;

    #[test]
    fn test_same_allocation() {
        // Create a single allocation and two Rc pointers to it
        let data = Rc::new(42);
        let data_clone = Rc::clone(&data);

        // These should point to the same allocation
        assert!(is_same_allocation(&data, &data_clone));
    }

    #[test]
    fn test_different_allocations() {
        // Create two separate allocations with the same value
        let data1 = Rc::new(42);
        let data2 = Rc::new(42);

        // These should not point to the same allocation
        assert!(!is_same_allocation(&data1, &data2));
    }

    #[test]
    fn test_with_struct_data() {
        // Define a test struct
        #[derive(Debug)]
        struct TestStruct {
            id: u32,
            name: String,
        }

        // Create a single allocation with struct data
        let data = Rc::new(TestStruct {
            id: 1,
            name: "Test".to_string(),
        });
        let data_clone = Rc::clone(&data);

        // These should point to the same allocation
        assert!(is_same_allocation(&data, &data_clone));

        // Create a separate allocation with identical struct data
        let data2 = Rc::new(TestStruct {
            id: 1,
            name: "Test".to_string(),
        });

        // These should not point to the same allocation even though content is equal
        assert!(!is_same_allocation(&data, &data2));
    }

    #[test]
    fn test_with_string_data() {
        // Test with String data
        let text1 = Rc::new(String::from("Hello, world!"));
        let text1_clone = Rc::clone(&text1);
        let text2 = Rc::new(String::from("Hello, world!"));

        // Same allocation
        assert!(is_same_allocation(&text1, &text1_clone));

        // Different allocations despite identical content
        assert!(!is_same_allocation(&text1, &text2));
    }

    #[test]
    fn test_complex_nesting() {
        // Test with nested Rc
        let nested1 = Rc::new(Rc::new(vec![1, 2, 3]));
        let nested1_clone = Rc::clone(&nested1);
        let nested2 = Rc::new(Rc::new(vec![1, 2, 3]));

        // Same outer allocation
        assert!(is_same_allocation(&nested1, &nested1_clone));

        // Different outer allocations
        assert!(!is_same_allocation(&nested1, &nested2));
    }

    #[test]
    fn test_empty_data() {
        // Test with empty data structures
        let empty_vec1 = Rc::new(Vec::<i32>::new());
        let empty_vec1_clone = Rc::clone(&empty_vec1);
        let empty_vec2 = Rc::new(Vec::<i32>::new());

        // Same allocation for empty vec
        assert!(is_same_allocation(&empty_vec1, &empty_vec1_clone));

        // Different allocations for empty vecs
        assert!(!is_same_allocation(&empty_vec1, &empty_vec2));
    }

    #[test]
    fn test_reference_cycles() {
        use std::cell::RefCell;

        // Create a structure that can form reference cycles
        struct CyclicStruct {
            id: u32,
            other: RefCell<Option<Rc<CyclicStruct>>>,
        }

        // Create two objects that will reference each other
        let obj1 = Rc::new(CyclicStruct {
            id: 1,
            other: RefCell::new(None),
        });

        let obj2 = Rc::new(CyclicStruct {
            id: 2,
            other: RefCell::new(Some(Rc::clone(&obj1))),
        });

        // Complete the cycle
        *obj1.other.borrow_mut() = Some(Rc::clone(&obj2));

        // Clone one of the Rcs
        let obj1_clone = Rc::clone(&obj1);

        // These should be the same allocation
        assert!(is_same_allocation(&obj1, &obj1_clone));

        // These should be different allocations
        assert!(!is_same_allocation(&obj1, &obj2));
    }
}

