#[cfg(test)]
mod tests {
    use super::*;
    use std::io::{self, Read, Cursor};

    // A custom reader that fails after reading some data
    struct FailingReader {
        data: Vec<u8>,
        fail_after: usize,
        bytes_read: usize,
    }

    impl FailingReader {
        fn new(data: Vec<u8>, fail_after: usize) -> Self {
            FailingReader {
                data,
                fail_after,
                bytes_read: 0,
            }
        }
    }

    impl Read for FailingReader {
        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
            if self.bytes_read >= self.fail_after {
                return Err(io::Error::new(io::ErrorKind::Other, "Simulated failure"));
            }

            let available = self.data.len() - self.bytes_read;
            if available == 0 {
                return Ok(0);
            }

            let to_read = std::cmp::min(buf.len(), available);
            let end = self.bytes_read + to_read;

            buf[..to_read].copy_from_slice(&self.data[self.bytes_read..end]);
            self.bytes_read += to_read;

            Ok(to_read)
        }
    }

    #[test]
    fn test_empty_file() {
        let reader = Cursor::new(Vec::<u8>::new());
        let result = read_large_file_to_string(reader).unwrap();
        assert_eq!(result, "");
    }

    #[test]
    fn test_small_file() {
        let data = "Hello, world!".as_bytes().to_vec();
        let reader = Cursor::new(data);
        let result = read_large_file_to_string(reader).unwrap();
        assert_eq!(result, "Hello, world!");
    }

    #[test]
    fn test_large_file() {
        // Create a large string that's larger than the default buffer size
        let large_string = "a".repeat(1024 * 1024); // 1MB of 'a's
        let reader = Cursor::new(large_string.clone().into_bytes());

        let result = read_large_file_to_string(reader).unwrap();
        assert_eq!(result, large_string);
    }

    #[test]
    fn test_non_utf8_data() {
        // Invalid UTF-8 sequence
        let invalid_utf8 = vec![0, 159, 146, 150];
        let reader = Cursor::new(invalid_utf8);

        let result = read_large_file_to_string(reader);
        assert!(result.is_err());

        if let Err(e) = result {
            assert_eq!(e.kind(), io::ErrorKind::InvalidData);
        }
    }

    #[test]
    fn test_reader_error() {
        let data = "Some data that will be partially read".as_bytes().to_vec();
        let reader = FailingReader::new(data, 10);

        let result = read_large_file_to_string(reader);
        assert!(result.is_err());

        if let Err(e) = result {
            assert_eq!(e.kind(), io::ErrorKind::Other);
        }
    }

    #[test]
    fn test_very_large_file_simulation() {
        // Create a reader that pretends to have a lot of data
        // without actually allocating gigabytes of memory
        struct LargeFileSimulator {
            data: Vec<u8>,
            size: usize,
            position: usize,
        }

        impl LargeFileSimulator {
            fn new(pattern: &[u8], size: usize) -> Self {
                LargeFileSimulator {
                    data: pattern.to_vec(),
                    size,
                    position: 0,
                }
            }
        }

        impl Read for LargeFileSimulator {
            fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
                if self.position >= self.size {
                    return Ok(0);
                }

                let remaining = self.size - self.position;
                let to_read = std::cmp::min(buf.len(), remaining);

                for i in 0..to_read {
                    buf[i] = self.data[self.position % self.data.len()];
                    self.position += 1;
                }

                Ok(to_read)
            }
        }

        // Simulate a 100MB file with repeating "abc" pattern
        let pattern = b"abc";
        let simulated_size = 100 * 1024 * 1024;
        let reader = LargeFileSimulator::new(pattern, simulated_size);

        let result = read_large_file_to_string(reader);
        assert!(result.is_ok());

        let content = result.unwrap();
        assert_eq!(content.len(), simulated_size);

        // Check the pattern at different points in the result
        for i in 0..10 {
            let pos = i * simulated_size / 10;
            if pos < simulated_size {
                let expected = pattern[pos % pattern.len()] as char;
                assert_eq!(content.chars().nth(pos).unwrap(), expected);
            }
        }
    }

    #[test]
    fn test_with_internal_buffering() {
        // Create a reader that tracks how many times read is called
        struct ReadCounter<R> {
            inner: R,
            read_count: usize,
        }

        impl<R: Read> ReadCounter<R> {
            fn new(inner: R) -> Self {
                ReadCounter {
                    inner,
                    read_count: 0,
                }
            }

            fn read_count(&self) -> usize {
                self.read_count
            }
        }

        impl<R: Read> Read for ReadCounter<R> {
            fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
                self.read_count += 1;
                self.inner.read(buf)
            }
        }

        // Create data larger than the default buffer size but not huge
        let data = "x".repeat(64 * 1024); // 64KB
        let counter = ReadCounter::new(Cursor::new(data.clone().into_bytes()));

        let result = read_large_file_to_string(counter);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), data);
    }
}

