fn find_last_match<T, P>(slice: &[T], predicate: P) -> Option<&T>
where
    P: Fn(&T) -> bool,
{
    let mut iter = slice.iter();
    while let Some(item) = iter.next_back() {
        if predicate(item) {
            return Some(item);
        }
    }
    None
}

