    fn test_prev_element_with_different_types() {
        // Test with a different type (f64)
        let arr = [1.1, 2.2, 3.3, 4.4];
        let ptr = arr.as_ptr().wrapping_add(3); // Points to 4.4

        unsafe {
            let prev = prev_element(ptr, 2);
            assert_eq!(*prev, 2.2); // Should point to the element at index 1
        }

        // Test with a custom struct
        #[derive(Debug, PartialEq)]
        struct TestStruct {
            value: i32,
        }

        let arr = [
            TestStruct { value: 10 },
            TestStruct { value: 20 },
            TestStruct { value: 30 },
        ];

        let ptr = arr.as_ptr().wrapping_add(2); // Points to value: 30

        unsafe {
            let prev = prev_element(ptr, 1);
            assert_eq!(*prev, TestStruct { value: 20 }); // Should point to the middle element
        }
    }

    #[test]
    fn test_prev_element_zero_sized_type() {
        // Create an array of a zero-sized type
        struct ZeroSized;

        let arr = [ZeroSized, ZeroSized, ZeroSized];
        let ptr = arr.as_ptr().wrapping_add(2); // Conceptually points to the third element

        unsafe {
            // For ZSTs, the pointer should remain unchanged regardless of n
            let prev = prev_element(ptr, 1);
            assert_eq!(prev as usize, ptr as usize);

            let prev2 = prev_element(ptr, 2);
            assert_eq!(prev2 as usize, ptr as usize);
        }
    }

    #[test]
    fn test_prev_element_large_offset() {
        let arr = [0; 1000]; // Create a large array
        let ptr = arr.as_ptr().wrapping_add(999); // Point to the last element

        unsafe {
            let prev = prev_element(ptr, 999);
            assert_eq!(prev, arr.as_ptr()); // Should point to the first element
        }
    }

    #[test]
    fn test_prev_element_alignment() {
        // Test with a type that has specific alignment requirements
        #[repr(align(16))]
        struct Aligned {
            value: i64,
        }

        let arr = [
            Aligned { value: 10 },
            Aligned { value: 20 },
            Aligned { value: 30 },
        ];

        // Verify alignment
        assert_eq!(mem::align_of::<Aligned>(), 16);

        let ptr = arr.as_ptr().wrapping_add(2); // Points to the third element

        unsafe {
            let prev = prev_element(ptr, 2);
            assert_eq!((*prev).value, 10); // Should point to the first element

            // Verify alignment is preserved
            assert_eq!(prev as usize % 16, 0);
        }
    }

