#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::OnceCell;
    use std::sync::{Arc, Barrier, OnceLock};
    use std::thread;

    #[test]
    fn test_uninit_state() {
        let cell: OnceCell<i32> = OnceCell::new();
        let result = log_once_cell_state(&cell);
        assert!(result.contains("OnceCell") && result.contains("uninit"));
    }

    #[test]
    fn test_init_state() {
        let cell = OnceCell::new();
        cell.set(42).unwrap();
        let result = log_once_cell_state(&cell);
        assert!(result.contains("OnceCell") && result.contains("42"));
    }

    #[test]
    fn test_complex_type() {
        #[derive(Debug)]
        struct TestStruct {
            id: usize,
            name: String,
        }

        let test_struct = TestStruct {
            id: 1,
            name: "test".to_string(),
        };

        let cell = OnceCell::new();
        cell.set(test_struct).unwrap();
        let result = log_once_cell_state(&cell);

        assert!(result.contains("OnceCell") && result.contains("TestStruct") && 
                result.contains("id: 1") && result.contains("name: \"test\""));
    }

    #[test]
    fn test_concurrent_access() {
        // Use OnceLock instead of OnceCell for thread-safe operation
        let cell = Arc::new(OnceLock::new());
        let barrier = Arc::new(Barrier::new(3));

        // Clone for threads
        let cell_clone1 = Arc::clone(&cell);
        let barrier_clone1 = Arc::clone(&barrier);

        let cell_clone2 = Arc::clone(&cell);
        let barrier_clone2 = Arc::clone(&barrier);

        // Thread 1 - tries to set value
        let t1 = thread::spawn(move || {
            barrier_clone1.wait();
            let _ = cell_clone1.set(100);
        });

        // Thread 2 - tries to set value too
        let t2 = thread::spawn(move || {
            barrier_clone2.wait();
            let _ = cell_clone2.set(200);
        });

        // Main thread - logs the state
        barrier.wait();

        // Let threads compete to set the value
        thread::sleep(std::time::Duration::from_millis(10));

        // Since our function expects OnceCell, create a OnceCell and set it based on OnceLock value
        let single_thread_cell = OnceCell::new();
        if let Some(value) = cell.get() {
            let _ = single_thread_cell.set(*value);
        }

        // Log state should not panic 
        let result = log_once_cell_state(&single_thread_cell);

        t1.join().unwrap();
        t2.join().unwrap();

        // Check the result based on whether a value was set
        if single_thread_cell.get().is_some() {
            assert!(result.contains("OnceCell") && 
                  (result.contains("100") || result.contains("200")));
        } else {
            assert!(result.contains("OnceCell") && result.contains("uninit"));
        }
    }

    #[test]
    fn test_custom_debug_implementation() {
        // Create a custom type with Debug implementation
        struct CustomDebug(i32);

        impl std::fmt::Debug for CustomDebug {
            fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                write!(f, "CustomValue({})", self.0)
            }
        }

        let cell = OnceCell::new();
        cell.set(CustomDebug(42)).unwrap();

        let result = log_once_cell_state(&cell);
        assert!(result.contains("OnceCell") && result.contains("CustomValue(42)"));
    }

    #[test]
    fn test_empty_string_value() {
        let cell = OnceCell::new();
        cell.set("".to_string()).unwrap();

        let result = log_once_cell_state(&cell);
        assert!(result.contains("OnceCell") && result.contains("\"\""));
    }

    #[test]
    fn test_option_type() {
        let cell = OnceCell::new();
        cell.set(Some(42)).unwrap();

        let result = log_once_cell_state(&cell);
        assert!(result.contains("OnceCell") && result.contains("Some(42)"));
    }
}

