    fn test_zero_weak_references() {
        let data = Rc::new(42);
        assert_eq!(count_weak_references(&data), 0);
    }

    #[test]
    fn test_single_weak_reference() {
        let data = Rc::new(String::from("test"));
        let _weak = Rc::downgrade(&data);
        assert_eq!(count_weak_references(&data), 1);
    }

    #[test]
    fn test_multiple_weak_references() {
        let data = Rc::new(vec![1, 2, 3]);

        let _weak1 = Rc::downgrade(&data);
        let _weak2 = Rc::downgrade(&data);
        let _weak3 = Rc::downgrade(&data);

        assert_eq!(count_weak_references(&data), 3);
    }

    #[test]
    fn test_weak_reference_after_clone() {
        let data = Rc::new(42);
        let _data_clone = Rc::clone(&data);

        let _weak = Rc::downgrade(&data);

        assert_eq!(count_weak_references(&data), 1);
        assert_eq!(count_weak_references(&_data_clone), 1);
    }

    #[test]
    fn test_weak_references_survive_clone_drop() {
        let data = Rc::new(42);
        let weak = Rc::downgrade(&data);

        {
            let data_clone = Rc::clone(&data);
            let _another_weak = Rc::downgrade(&data_clone);
            assert_eq!(count_weak_references(&data), 2);
        } // data_clone is dropped here

        // Original Rc still exists, so weak references should still be counted
        assert_eq!(count_weak_references(&data), 1);
        assert!(weak.upgrade().is_some());
    }

    #[test]
    fn test_custom_type() {
        struct TestStruct {
            value: i32,
        }

        let data = Rc::new(TestStruct { value: 100 });
        let _weak1 = Rc::downgrade(&data);
        let _weak2 = Rc::downgrade(&data);

        assert_eq!(count_weak_references(&data), 2);
    }

    #[test]
    fn test_empty_struct() {
        struct Empty;

        let data = Rc::new(Empty);
        let _weak = Rc::downgrade(&data);

        assert_eq!(count_weak_references(&data), 1);
    }

    #[test]
    fn test_original_rc_dropped() {
        // We can't test actual counting after the original is dropped since we 
        // need the original Rc to call our function, but we can verify the weak 
        // reference behavior for completeness

        let data = Rc::new(String::from("will be dropped"));
        let weak = Rc::downgrade(&data);

        assert_eq!(count_weak_references(&data), 1);

        drop(data);

        // Verify weak reference is now invalid
        assert!(weak.upgrade().is_none());
    }
}

