fn reverse_slice<T>(iter: &mut impl DoubleEndedIterator<Item = T>) -> Vec<T> {
    let mut reversed = Vec::new();
    while let Some(item) = iter.next_back() {
        reversed.push(item);
    }
    reversed
}

