        #[derive(Debug, PartialEq, Clone)]
        struct TestStruct {
            value: i32,
        }

        let items = vec![
            TestStruct { value: 1 },
            TestStruct { value: 2 },
            TestStruct { value: 3 },
        ];

        let mut iter = items.iter().cloned();
        let result = reverse_slice(&mut iter);

        assert_eq!(result.len(), 3);
        assert_eq!(result[0], TestStruct { value: 3 });
        assert_eq!(result[1], TestStruct { value: 2 });
        assert_eq!(result[2], TestStruct { value: 1 });
    }

    #[test]
    fn test_reverse_slice_half_consumed() {
        // Test with an iterator that has already been partially consumed
        let mut iter = [1, 2, 3, 4, 5, 6].iter().cloned();

        // Consume the first three elements
        assert_eq!(iter.next(), Some(1));
        assert_eq!(iter.next(), Some(2));
        assert_eq!(iter.next(), Some(3));

        // Now reverse the rest
        let result = reverse_slice(&mut iter);
        assert_eq!(result, vec![6, 5, 4]);
    }

    #[test]
    fn test_reverse_slice_custom_double_ended_iterator() {
        // Create a simple struct that implements DoubleEndedIterator
        struct CounterIter {
            start: i32,
            end: i32,
        }

        impl Iterator for CounterIter {
            type Item = i32;

            fn next(&mut self) -> Option<Self::Item> {
                if self.start <= self.end {
                    let result = self.start;
                    self.start += 1;
                    Some(result)
                } else {
                    None
                }
            }
        }

        impl DoubleEndedIterator for CounterIter {
            fn next_back(&mut self) -> Option<Self::Item> {
                if self.start <= self.end {
                    let result = self.end;
                    self.end -= 1;
                    Some(result)
                } else {
                    None
                }
            }
        }

        // Test with our custom iterator
        let mut iter = CounterIter { start: 1, end: 5 };
        let result = reverse_slice(&mut iter);
        assert_eq!(result, vec![5, 4, 3, 2, 1]);
    }
