        lock.get_or_init(|| 42);
        let debug_output = debug_oncelock(&lock);
        assert!(debug_output.contains("OnceLock"), "Debug output should mention OnceLock");
        assert!(debug_output.contains("42"), "Debug output should contain the initialized value");
    }

