        lock.get_or_init(|| TestStruct {
            id: 123,
            name: "test".to_string(),
        });

        let debug_output = debug_oncelock(&lock);
        assert!(debug_output.contains("OnceLock"), "Debug output should mention OnceLock");
        assert!(debug_output.contains("123"), "Debug output should contain the id");
        assert!(debug_output.contains("test"), "Debug output should contain the name");
    }

    #[test]
    fn test_debug_oncelock_with_empty_string() {
        let lock: OnceLock<String> = OnceLock::new();
        lock.get_or_init(|| String::new());
        let debug_output = debug_oncelock(&lock);
        assert!(debug_output.contains("OnceLock"), "Debug output should mention OnceLock");
        assert!(debug_output.contains("\"\"") || debug_output.contains(""), 
                "Debug output should indicate empty string");
    }

    #[test]
    fn test_debug_oncelock_with_option_type() {
        let lock: OnceLock<Option<i32>> = OnceLock::new();
        lock.get_or_init(|| None);
        let debug_output = debug_oncelock(&lock);
        assert!(debug_output.contains("OnceLock"), "Debug output should mention OnceLock");
        assert!(debug_output.contains("None"), "Debug output should contain None");

        let lock2: OnceLock<Option<i32>> = OnceLock::new();
        lock2.get_or_init(|| Some(42));
        let debug_output2 = debug_oncelock(&lock2);
        assert!(debug_output2.contains("Some"), "Debug output should contain Some");
        assert!(debug_output2.contains("42"), "Debug output should contain the value 42");
    }

    #[test]
    fn test_debug_oncelock_output_consistency() {
        let lock1: OnceLock<i32> = OnceLock::new();
        let lock2: OnceLock<i32> = OnceLock::new();

        // Both uninitialized
        assert_eq!(debug_oncelock(&lock1), debug_oncelock(&lock2), 
                  "Debug output should be consistent for identical uninitialized instances");

        // Initialize both with same value
        lock1.get_or_init(|| 100);
        lock2.get_or_init(|| 100);
        assert_eq!(debug_oncelock(&lock1), debug_oncelock(&lock2), 
