    #[test]
    fn test_accessible_resource() {
        // Create a strong reference to a resource
        let strong = Rc::new(42);

        // Create a weak reference from the strong reference
        let weak = Rc::downgrade(&strong);

        // The resource should be accessible since the strong reference exists
        assert!(is_resource_accessible(&weak));
    }

    #[test]
    fn test_inaccessible_resource() {
        // Create a strong reference to a resource
        let strong = Rc::new("test data");

        // Create a weak reference from the strong reference
        let weak = Rc::downgrade(&strong);

        // Drop the strong reference
        drop(strong);

        // The resource should no longer be accessible
        assert!(!is_resource_accessible(&weak));
    }

    #[test]
    fn test_multiple_strong_references() {
        // Create a strong reference to a resource
        let strong1 = Rc::new(vec![1, 2, 3]);

        // Create another strong reference to the same resource
        let strong2 = strong1.clone();

        // Create a weak reference
        let weak = Rc::downgrade(&strong1);

        // Drop the first strong reference
        drop(strong1);

        // The resource should still be accessible due to the second strong reference
        assert!(is_resource_accessible(&weak));

        // Drop the second strong reference
        drop(strong2);

        // Now the resource should be inaccessible
        assert!(!is_resource_accessible(&weak));
    }

