        // Create a weak reference
        let weak = Rc::downgrade(&strong);

        // The resource should be accessible
        assert!(is_resource_accessible(&weak));

        // Drop the strong reference
        drop(strong);

        // The resource should no longer be accessible
        assert!(!is_resource_accessible(&weak));
    }

