mod tests {
    use super::*;
    use std::sync::Arc;
    use std::ptr;
    use std::mem;

    #[test]
    fn test_increment_strong_count() {
        // Create an Arc with an initial count of 1
        let original = Arc::new(42i32);
        let raw_ptr = Arc::as_ptr(&original);

        // Check initial count
        assert_eq!(Arc::strong_count(&original), 1);

        // Increment the count using our function
        unsafe { increment_arc_strong_count(raw_ptr) };

        // Check that the count was incremented
        assert_eq!(Arc::strong_count(&original), 2);

        // Create a temporary Arc from the raw pointer to clean up the extra reference
        let temp = unsafe { Arc::from_raw(raw_ptr) };
        mem::forget(temp); // Prevent double drop
    }

    #[test]
    fn test_multiple_increments() {
        // Create an Arc with initial count of 1
        let original = Arc::new(String::from("test"));
        let raw_ptr = Arc::as_ptr(&original);

        // Check initial count
        assert_eq!(Arc::strong_count(&original), 1);

        // Increment multiple times
        for _ in 0..5 {
            unsafe { increment_arc_strong_count(raw_ptr) };
        }

        // Verify count was incremented correctly
        assert_eq!(Arc::strong_count(&original), 6);

        // Create a temporary Arc to decrement the counter properly
        let temp = unsafe { Arc::from_raw(raw_ptr) };
        // Manually adjust the count to account for the 5 additional references
        // We don't actually drop the temp Arc to avoid double-free
        mem::forget(temp);
    }

    #[test]
    fn test_with_custom_struct() {
        struct TestStruct {
            value: Vec<i32>,
        }

        // Create Arc with custom type
        let original = Arc::new(TestStruct { value: vec![1, 2, 3] });
        let raw_ptr = Arc::as_ptr(&original);

        // Check initial count
        assert_eq!(Arc::strong_count(&original), 1);

        // Increment and check
        unsafe { increment_arc_strong_count(raw_ptr) };
        assert_eq!(Arc::strong_count(&original), 2);

        // Make sure we can still access the data correctly
        unsafe {
            let data = &*raw_ptr;
            assert_eq!(data.value, vec![1, 2, 3]);
        }

        // Create a temporary Arc to clean up properly
        let temp = unsafe { Arc::from_raw(raw_ptr) };
        mem::forget(temp); // Prevent double free
    }

    #[test]
    fn test_with_clone_comparison() {
        // Create Arc and get its strong count
        let original = Arc::new(100u64);
        let clone = original.clone();

        // Count should be 2 after clone
        assert_eq!(Arc::strong_count(&original), 2);

        // Get the raw pointer and increment using our function
        let raw_ptr = Arc::as_ptr(&original);
        unsafe { increment_arc_strong_count(raw_ptr) };

        // Count should now be 3
        assert_eq!(Arc::strong_count(&original), 3);

        // Verify all Arcs point to the same value
        assert_eq!(*original, 100u64);
        assert_eq!(*clone, 100u64);
        unsafe {
