        let data = Arc::new(String::from("test"));

        // Create weak reference
        let weak_data = Arc::downgrade(&data);

        // Drop all strong references
        drop(data);

        // This would fail to compile as we need a strong reference to call is_weakly_referenced
        // assert_eq!(is_weakly_referenced(&weak_data), true);

        // Verify weak reference still exists but can't be upgraded
        assert!(weak_data.upgrade().is_none());
