        let weak_data1 = Arc::downgrade(&data);
        let weak_data2 = Arc::downgrade(&data);

        assert_eq!(is_weakly_referenced(&data), false);
        assert_eq!(Arc::strong_count(&data), 1);
        assert_eq!(Arc::weak_count(&data), 2);

        // We can still upgrade weak references
        let strong_from_weak = weak_data1.upgrade().unwrap();
        assert_eq!(Arc::strong_count(&data), 2);

        // Keep strong_from_weak in scope to avoid compiler warnings
        assert_eq!(strong_from_weak.len(), 0);
    }

    #[test]
