        struct DropLogger {
            id: u32,
        }

        impl Drop for DropLogger {
            fn drop(&mut self) {
                println!("Dropping DropLogger {}", self.id);
            }
        }

        let data = Arc::new(DropLogger { id: 1 });
        let weak_data = Arc::downgrade(&data);

        assert_eq!(is_weakly_referenced(&data), false);

        // Drop the strong reference
        drop(data);

        // Now we can't test is_weakly_referenced directly since we don't have a strong reference
        // But we can verify the weak reference behavior
        assert!(weak_data.upgrade().is_none());
    }

    #[test]
