        assert_eq!(is_weakly_referenced(&data), false);

        // Testing after dropping weak references
        drop(weak1);
        assert_eq!(Arc::weak_count(&data), 2);
        assert_eq!(is_weakly_referenced(&data), false);

        // Testing with zero references (edge case)
        drop(weak2);
        drop(weak3);
        assert_eq!(Arc::weak_count(&data), 0);
        assert_eq!(is_weakly_referenced(&data), false);
    }
