fn compute_log10_values(input: Vec<f64>) -> Vec<f64> {
    input.into_iter()
        .map(|value| {
            if value <= 0.0 {
                f64::NAN
            } else {
                value.log10()
            }
        })
        .collect()
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use std::f64;

    #[test]
    fn test_compute_log10_values_positive_numbers() {
        let input = vec![1.0, 10.0, 100.0, 1000.0];
        let expected = vec![0.0, 1.0, 2.0, 3.0];

        let result = compute_log10_values(input);

        assert_eq!(result.len(), expected.len());
        for (actual, expected) in result.iter().zip(expected.iter()) {
            assert!((actual - expected).abs() < f64::EPSILON);
        }
    }

    #[test]
    fn test_compute_log10_values_non_positive_numbers() {
        let input = vec![0.0, -1.0, -10.0];
        let result = compute_log10_values(input);

        assert_eq!(result.len(), 3);
        for val in result {
            assert!(val.is_nan());
        }
    }

    #[test]
    fn test_compute_log10_values_mixed_values() {
        let input = vec![-5.0, 0.0, 0.1, 1.0, 10.0];
        let result = compute_log10_values(input);

        assert_eq!(result.len(), 5);

        // The first two values should be NaN
        assert!(result[0].is_nan());
        assert!(result[1].is_nan());

        // The rest should be valid log10 values
        assert!((result[2] - (-1.0)).abs() < 1e-15);  // log10(0.1) = -1.0
        assert!((result[3] - 0.0).abs() < f64::EPSILON);  // log10(1.0) = 0.0
        assert!((result[4] - 1.0).abs() < f64::EPSILON);  // log10(10.0) = 1.0
    }

    #[test]
    fn test_compute_log10_values_empty_input() {
        let input: Vec<f64> = vec![];
        let result = compute_log10_values(input);
        assert!(result.is_empty());
    }

    #[test]
    fn test_compute_log10_values_large_numbers() {
        let input = vec![1e10, 1e15, 1e20];
        let expected = vec![10.0, 15.0, 20.0];

        let result = compute_log10_values(input);

        assert_eq!(result.len(), expected.len());
        for (actual, expected) in result.iter().zip(expected.iter()) {
            assert!((actual - expected).abs() < 1e-10);
        }
    }

    #[test]
    fn test_compute_log10_values_small_numbers() {
        let input = vec![1e-5, 1e-10, 1e-15];
        let expected = vec![-5.0, -10.0, -15.0];

        let result = compute_log10_values(input);

        assert_eq!(result.len(), expected.len());
        for (actual, expected) in result.iter().zip(expected.iter()) {
            assert!((actual - expected).abs() < 1e-10);
        }
    }

    #[test]
    fn test_compute_log10_values_precision() {
