pub fn downcast<T: Any>(self) -> Result<Rc<T, A>, Self> {
    if (*self).is::<T>() {
        unsafe {
            let ptr = self.ptr.cast::<RcBox<T>>();
            let alloc = self.alloc.clone();
            forget(self);
            Ok(Rc::from_inner_in(ptr, alloc))
        }
    } else {
        Err(self)
    }
}

