use std::rc::Rc;

fn try_downcast<T: Any>(rc: Rc<dyn Any>) -> Result<Rc<T>, Rc<dyn Any>> {
    rc.downcast::<T>().map_err(|rc| rc)
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use std::any::Any;
    use std::rc::Rc;

    // Simple structs for testing
    struct TestStruct {
        value: i32,
    }

    struct AnotherStruct {
        name: String,
    }

    #[test]
    fn test_successful_downcast() {
        // Create a test struct and wrap it in Rc<dyn Any>
        let original = TestStruct { value: 42 };
        let rc_any: Rc<dyn Any> = Rc::new(original);

        // Test the downcast
        let result = try_downcast::<TestStruct>(rc_any);

        // Assert that downcast succeeded
        assert!(result.is_ok());

        // Verify the value was preserved
        let rc_test_struct = result.unwrap();
        assert_eq!(rc_test_struct.value, 42);
    }

    #[test]
    fn test_failed_downcast() {
        // Create a struct and wrap it in Rc<dyn Any>
        let original = TestStruct { value: 42 };
        let rc_any: Rc<dyn Any> = Rc::new(original);

        // Attempt to downcast to wrong type
        let result = try_downcast::<AnotherStruct>(rc_any.clone());

        // Assert that downcast failed
        assert!(result.is_err());

        // Verify the original Rc was returned
        let returned_rc = result.err().unwrap();

        // We can't directly compare Rc instances, so downcast back to TestStruct
        // to verify it's the original value
        let returned_as_test = returned_rc.downcast::<TestStruct>();
        assert!(returned_as_test.is_ok());
        assert_eq!(returned_as_test.unwrap().value, 42);
    }

    #[test]
    fn test_reference_counting() {
        // Create a struct and wrap it in Rc<dyn Any>
        let original = TestStruct { value: 42 };
        let rc_any: Rc<dyn Any> = Rc::new(original);

        // Check initial reference count
        assert_eq!(Rc::strong_count(&rc_any), 1);

        // Clone the Rc to increase ref count
        let rc_clone = rc_any.clone();
        assert_eq!(Rc::strong_count(&rc_any), 2);

        // Perform successful downcast
        let result = try_downcast::<TestStruct>(rc_any);

        // Check that reference count is maintained
        assert_eq!(Rc::strong_count(&result.unwrap()), 2);

        // Check that the clone still works
        let downcast_clone = rc_clone.downcast::<TestStruct>();
        assert!(downcast_clone.is_ok());
        assert_eq!(downcast_clone.unwrap().value, 42);
    }

    #[test]
    fn test_with_different_types() {
        // Test with a String
        let str_value = "test string".to_string();
        let rc_string: Rc<dyn Any> = Rc::new(str_value.clone());

        let result = try_downcast::<String>(rc_string);
        assert!(result.is_ok());
        assert_eq!(*result.unwrap(), str_value);

        // Test with a Vec
        let vec_value = vec![1, 2, 3];
        let rc_vec: Rc<dyn Any> = Rc::new(vec_value.clone());

        let result = try_downcast::<Vec<i32>>(rc_vec);
        assert!(result.is_ok());
        assert_eq!(*result.unwrap(), vec_value);

        // Test with a primitive type
        let int_value = 42;
        let rc_int: Rc<dyn Any> = Rc::new(int_value);

        let result = try_downcast::<i32>(rc_int);
        assert!(result.is_ok());
        assert_eq!(*result.unwrap(), int_value);
    }

    #[test]
    fn test_nested_types() {
        // Create a nested type
        let nested = Rc::new(TestStruct { value: 100 });
        let rc_any: Rc<dyn Any> = Rc::new(nested.clone());

        // Attempt to downcast to Rc<TestStruct>
        let result = try_downcast::<Rc<TestStruct>>(rc_any);

        // Assert that downcast succeeded
        assert!(result.is_ok());

        // Verify the nested value was preserved
        let rc_nested = result.unwrap();
        assert_eq!(rc_nested.value, 100);
    }

    #[test]
    fn test_empty_struct() {
        // Test with an empty struct
        struct Empty;

        let empty = Empty;
        let rc_any: Rc<dyn Any> = Rc::new(empty);

        let result = try_downcast::<Empty>(rc_any);
        assert!(result.is_ok());

        // Can't compare the contents, but we can check that it's the right type
        std::mem::drop(result.unwrap()); // Should compile if type is correct
    }
}

