        let input = OsStr::new("こんにちは");
        let bytes = extract_raw_bytes(input);

        // Unicode characters are multi-byte in UTF-8
        // "こんにちは" is 15 bytes in UTF-8
        assert_eq!(bytes.len(), 15);

        // Manually verify expected bytes for "こんにちは"
        assert_eq!(bytes, &[
            0xE3, 0x81, 0x93, // こ
            0xE3, 0x82, 0x93, // ん
            0xE3, 0x81, 0xAB, // に
            0xE3, 0x81, 0xA1, // ち
            0xE3, 0x81, 0xAF  // は
        ]);
    }

    #[test]
    fn test_special_characters() {
        let input = OsStr::new("path/with\\special@#$%^&*()chars");
        let bytes = extract_raw_bytes(input);
        assert_eq!(bytes, b"path/with\\special@#$%^&*()chars");
    }

    #[test]
    #[cfg(unix)]
    fn test_unix_invalid_utf8() {
        // On Unix platforms, we can create OsStr with invalid UTF-8
        // This test is specific to Unix platforms
        let bytes = &[0xFF, 0xFE, 0xFD]; // Invalid UTF-8 sequence
        let os_str = OsStr::from_bytes(bytes);
        let result = extract_raw_bytes(os_str);

        assert_eq!(result, bytes);
        assert_eq!(result.len(), 3);
    }

    #[test]
    #[cfg(windows)]
    fn test_windows_wide_chars() {
        // On Windows, OsStr uses UTF-16 encoding internally
        // This test verifies proper handling of wide characters on Windows

        // Use a string with characters outside the ASCII range
        let input = OsStr::new("Unicode␠Symbols␡");

        // Get the wide char representation on Windows
        let wide_chars: Vec<u16> = input.encode_wide().collect();

        let result = extract_raw_bytes(input);

        // The result should match the bytes representation of the string
        // Not directly comparing to wide_chars as as_encoded_bytes() doesn't
        // necessarily return the UTF-16 representation
        assert!(!result.is_empty());
        assert_eq!(result.len(), input.len());
    }

    #[test]
    fn test_reference_borrowing() {
        // Test that the function properly borrows and returns a reference
        // without taking ownership of the data
        let input = OsStr::new("reference_test");
        let bytes1 = extract_raw_bytes(input);
        let bytes2 = extract_raw_bytes(input); // Should be able to borrow multiple times

        assert_eq!(bytes1, bytes2);
        assert_eq!(bytes1, b"reference_test");

        // We can still use input after extracting bytes
        assert_eq!(input, OsStr::new("reference_test"));
    }
