mod tests {
    use std::num::Saturating;
    use super::*;

    #[test]
    fn test_combine_signals_normal_values() {
        let signal1 = Saturating(0b1010_1010_1010_1010);
        let signal2 = Saturating(0b1100_1100_1100_1100);
        let expected = Saturating(0b1000_1000_1000_1000);

        let result = combine_signals(signal1, signal2);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_combine_signals_with_zeros() {
        let signal1 = Saturating(0xFFFF);
        let signal2 = Saturating(0);
        let expected = Saturating(0);

        let result = combine_signals(signal1, signal2);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_combine_signals_identity() {
        // Bitwise AND with all 1s should return the original value
        let signal1 = Saturating(0b0101_0101_0101_0101);
        let signal2 = Saturating(0xFFFF);
        let expected = signal1;

        let result = combine_signals(signal1, signal2);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_combine_signals_commutative() {
        // Bitwise AND should be commutative
        let signal1 = Saturating(0b1010_1100_0011_0101);
        let signal2 = Saturating(0b0011_1010_1100_1010);

        let result1 = combine_signals(signal1, signal2);
        let result2 = combine_signals(signal2, signal1);

        assert_eq!(result1, result2);
    }

    #[test]
    fn test_combine_signals_all_ones() {
        // Bitwise AND with all 1s on both sides should return all 1s
        let signal1 = Saturating(0xFFFF);
        let signal2 = Saturating(0xFFFF);
        let expected = Saturating(0xFFFF);

        let result = combine_signals(signal1, signal2);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_combine_signals_alternating_bits() {
        let signal1 = Saturating(0b1010_1010_1010_1010);
        let signal2 = Saturating(0b0101_0101_0101_0101);
        let expected = Saturating(0); // No overlapping bits

        let result = combine_signals(signal1, signal2);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_combine_signals_max_values() {
        let signal1 = Saturating(u16::MAX);
        let signal2 = Saturating(u16::MAX);
        let expected = Saturating(u16::MAX);

        let result = combine_signals(signal1, signal2);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_combine_signals_boundary_values() {
        let test_cases = [
            (0, 0, 0),
            (0, u16::MAX, 0),
            (u16::MAX, 0, 0),
            (u16::MAX, u16::MAX, u16::MAX),
            (1, 1, 1),
            (1, 3, 1),
            (0xFF00, 0x00FF, 0),
        ];

        for (s1, s2, expected) in test_cases {
            let result = combine_signals(Saturating(s1), Saturating(s2));
            assert_eq!(result, Saturating(expected));
