        ];
        let result = count_inactive_devices(&flags);

        // Count zeros in each value
        assert_eq!(result[0], 16);  // 0xF0F0F0F0 has 16 zeros

        // Correct the count for 0x12345678
        let zeros_in_12345678 = 0x12345678u32.count_zeros();
        assert_eq!(result[1], zeros_in_12345678);  

        // Correct the count for 0x00FF00FF
        let zeros_in_00FF00FF = 0x00FF00FFu32.count_zeros();
        assert_eq!(result[2], zeros_in_00FF00FF);  
    }

    #[test]
    fn test_single_inactive_bit() {
        let flags = [
            0xFFFFFFFE,  // Only the least significant bit is 0
            0xFFFFFFFD,  // Second bit from right is 0
            0xFFFFFFFB,  // Third bit from right is 0
        ];
        let result = count_inactive_devices(&flags);
        assert_eq!(result, vec![1, 1, 1]);  // Each has exactly 1 inactive bit
    }

    #[test]
    fn test_boundary_values() {
        let flags = [
            0x00000001,  // Only LSB is active
            0x80000000,  // Only MSB is active
            0x7FFFFFFF,  // All bits active except MSB
            0xFFFFFFFE,  // All bits active except LSB
        ];
        let result = count_inactive_devices(&flags);
        assert_eq!(result, vec![31, 31, 1, 1]);
    }

    #[test]
    fn test_large_dataset() {
        // Create a dataset with 1000 entries of alternating patterns
        let mut large_flags = Vec::with_capacity(1000);
        for i in 0..1000 {
            if i % 3 == 0 {
                large_flags.push(0xAAAAAAAA);  // 16 zeros
            } else if i % 3 == 1 {
                large_flags.push(0x55555555);  // 16 zeros
            } else {
                large_flags.push(0);  // 32 zeros
            }
        }

        let result = count_inactive_devices(&large_flags);

        // Verify the results
        for (i, &count) in result.iter().enumerate() {
            if i % 3 == 0 || i % 3 == 1 {
                assert_eq!(count, 16, "Expected 16 zeros at index {}", i);
            } else {
                assert_eq!(count, 32, "Expected 32 zeros at index {}", i);
            }
        }

        assert_eq!(result.len(), 1000);
    }
}

