#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_identity_on_big_endian_system() {
        if cfg!(target_endian = "big") {
            // On big-endian systems, the function should return the same value
            assert_eq!(ensure_big_endian(0x12345678), 0x12345678);
        }
    }

    #[test]
    fn test_byte_swap_on_little_endian_system() {
        if cfg!(target_endian = "little") {
            // On little-endian systems, the function should swap the bytes
            // 0x12345678 in little endian is stored as 0x78563412 in memory
            // but to_be() will swap it to 0x12345678 for network transmission
            let original: u32 = 0x12345678;
            let expected = original.swap_bytes();
            assert_eq!(ensure_big_endian(original), expected);
        }
    }

    #[test]
    fn test_ensure_big_endian_with_zero() {
        // Zero should remain unchanged regardless of endianness
        assert_eq!(ensure_big_endian(0), 0);
    }

    #[test]
    fn test_ensure_big_endian_with_ones() {
        // All bits set should remain unchanged regardless of endianness
        assert_eq!(ensure_big_endian(0xFFFFFFFF), 0xFFFFFFFF);
    }

    #[test]
    fn test_ensure_big_endian_idempotence() {
        // The function converts to big-endian, so applying from_be to the result
        // should give back the original value
        let original: u32 = 0x12345678;
        let once = ensure_big_endian(original);
        let twice = u32::from_be(once);
        assert_eq!(twice, original);
    }

    #[test]
    fn test_ensure_big_endian_with_alternating_bits() {
        // Test with alternating bit pattern
        let alternating: u32 = 0xAAAAAAAA;

        // Alternating pattern should remain unchanged after converting to big-endian
        // only if each byte has the same bit pattern (which 0xAA does)
        if cfg!(target_endian = "big") {
            assert_eq!(ensure_big_endian(alternating), alternating);
        } else {
            assert_eq!(ensure_big_endian(alternating), alternating);
        }
    }

    #[test]
    fn test_ensure_big_endian_boundary_values() {
        // Test with minimum and maximum u32 values
        assert_eq!(ensure_big_endian(u32::MIN), u32::MIN);
        assert_eq!(ensure_big_endian(u32::MAX), u32::MAX);
    }

    #[test]
    fn test_ensure_big_endian_network_byte_order() {
        // Test against a known network byte order value
        // IP address 192.168.1.1 in decimal is 3232235777
        let ip_addr: u32 = 192 << 24 | 168 << 16 | 1 << 8 | 1;

        // The expected result depends on the system's endianness
        let expected = if cfg!(target_endian = "big") {
            ip_addr
        } else {
            ip_addr.swap_bytes()
        };

        let result = ensure_big_endian(ip_addr);

        // This value should be converted to network byte order (big-endian)
        assert_eq!(result, expected);

        // Verify individual bytes are in the correct order when interpreted as big-endian
        let result_be = u32::from_be(result);
        assert_eq!((result_be >> 24) & 0xFF, 192);
        assert_eq!((result_be >> 16) & 0xFF, 168);
        assert_eq!((result_be >> 8) & 0xFF, 1);
        assert_eq!(result_be & 0xFF, 1);
    }
}

