mod tests {
    use super::count_leading_zeros;

    #[test]
    fn test_zero_value() {
        // 0 should have 64 leading zeros in a u64
        assert_eq!(count_leading_zeros(0), 64);
    }

    #[test]
    fn test_one_value() {
        // 1 (binary: 0000...0001) should have 63 leading zeros
        assert_eq!(count_leading_zeros(1), 63);
    }

    #[test]
    fn test_power_of_two() {
        // 2^32 (100...0 with 32 zeros) should have 31 leading zeros
        assert_eq!(count_leading_zeros(1u64 << 32), 31);

        // 2^63 (10...0 with 63 zeros) should have 0 leading zeros
        assert_eq!(count_leading_zeros(1u64 << 63), 0);
    }

    #[test]
    fn test_all_bits_set() {
        // All bits set (no leading zeros)
        assert_eq!(count_leading_zeros(u64::MAX), 0);
    }

    #[test]
    fn test_specific_patterns() {
        // 0xFF (0000...11111111) should have 56 leading zeros
        assert_eq!(count_leading_zeros(0xFF), 56);

        // 0xFFFF (0000...1111111111111111) should have 48 leading zeros
        assert_eq!(count_leading_zeros(0xFFFF), 48);

        // 0xFFFF_FFFF (32 ones) should have 32 leading zeros
        assert_eq!(count_leading_zeros(0xFFFF_FFFF), 32);
    }

    #[test]
    fn test_alternating_bit_patterns() {
        // 0xAAAAAAAAAAAAAAAA (pattern of alternating 1s and 0s) should have 0 leading zeros
        assert_eq!(count_leading_zeros(0xAAAAAAAAAAAAAAAA), 0);

        // 0x5555555555555555 (pattern of alternating 0s and 1s) should have 1 leading zero
        assert_eq!(count_leading_zeros(0x5555555555555555), 1);
    }

    #[test]
    fn test_boundary_values() {
        // One less than max
        assert_eq!(count_leading_zeros(u64::MAX - 1), 0);

        // Just the highest bit set
        assert_eq!(count_leading_zeros(1u64 << 63), 0);

        // Just the second highest bit set
        assert_eq!(count_leading_zeros(1u64 << 62), 1);
    }

    #[test]
    fn test_function_preserves_input() {
        // This test ensures the function doesn't modify the input value
        let original_key = 0x123456789ABCDEF0;
        let copy_key = original_key;

        // Call the function
        let _ = count_leading_zeros(copy_key);

        // Verify the value hasn't changed (this is guaranteed by Rust's type system
        // since u64 is Copy, but we test it explicitly for the cryptographic requirement)
        assert_eq!(copy_key, original_key);
    }
}

