#[cfg(test)]
mod tests {
    use std::fmt::{Error, Write};
    use super::write_chars_to_buffer;

    // Simple buffer implementation for testing
    struct TestBuffer {
        content: String,
    }

    impl TestBuffer {
        fn new() -> Self {
            TestBuffer {
                content: String::new(),
            }
        }

        fn contents(&self) -> &str {
            &self.content
        }
    }

    impl Write for TestBuffer {
        fn write_str(&mut self, s: &str) -> Result<(), Error> {
            self.content.push_str(s);
            Ok(())
        }
    }

    // A writer that fails after N characters
    struct FailingWriter {
        max_chars: usize,
        current_count: usize,
        content: String,
    }

    impl FailingWriter {
        fn new(max_chars: usize) -> Self {
            FailingWriter {
                max_chars,
                current_count: 0,
                content: String::new(),
            }
        }

        fn contents(&self) -> &str {
            &self.content
        }
    }

    impl Write for FailingWriter {
        fn write_str(&mut self, s: &str) -> Result<(), Error> {
            if self.current_count + s.len() > self.max_chars {
                return Err(Error);
            }
            self.content.push_str(s);
            self.current_count += s.len();
            Ok(())
        }
    }

    #[test]
    fn test_empty_char_slice() {
        let mut buffer = TestBuffer::new();
        let result = write_chars_to_buffer(&mut buffer, &[]);

        assert!(result.is_ok());
        assert_eq!(buffer.contents(), "");
    }

    #[test]
    fn test_ascii_chars() {
        let mut buffer = TestBuffer::new();
        let chars = ['a', 'b', 'c', '1', '2', '3'];

        let result = write_chars_to_buffer(&mut buffer, &chars);

        assert!(result.is_ok());
        assert_eq!(buffer.contents(), "abc123");
    }

    #[test]
    fn test_non_ascii_chars() {
        let mut buffer = TestBuffer::new();
        let chars = ['α', 'β', 'γ', '漢', '字', '😀'];

        let result = write_chars_to_buffer(&mut buffer, &chars);

        assert!(result.is_ok());
        assert_eq!(buffer.contents(), "αβγ漢字😀");
    }

    #[test]
    fn test_mixed_chars() {
        let mut buffer = TestBuffer::new();
        let chars = ['a', 'β', '1', '漢', '!', '😀'];

        let result = write_chars_to_buffer(&mut buffer, &chars);

        assert!(result.is_ok());
        assert_eq!(buffer.contents(), "aβ1漢!😀");
    }

    #[test]
    fn test_large_char_slice() {
        let mut buffer = TestBuffer::new();
        let chars: Vec<char> = "abcdefghijklmnopqrstuvwxyz0123456789".chars().collect();

        let result = write_chars_to_buffer(&mut buffer, &chars);

        assert!(result.is_ok());
        assert_eq!(buffer.contents(), "abcdefghijklmnopqrstuvwxyz0123456789");
    }

    #[test]
    fn test_writer_error_propagation() {
        let mut writer = FailingWriter::new(3);
        let chars = ['a', 'b', 'c', 'd', 'e'];

        let result = write_chars_to_buffer(&mut writer, &chars);

        assert!(result.is_err());
