#[cfg(test)]
mod tests {
    use std::cell::RefCell;
    use std::panic::{self, AssertUnwindSafe};
    use std::sync::{Arc, Mutex};
    use std::thread;

    // Import the function being tested
    use super::safe_borrow_and_process;

    #[test]
    fn test_normal_operation() {
        let data = RefCell::new(42);

        let result = safe_borrow_and_process(&data, |value| {
            assert_eq!(*value, 42);
        });

        assert!(result.is_ok());
    }

    #[test]
    fn test_with_complex_data() {
        #[derive(Debug, PartialEq)]
        struct TestStruct {
            value: i32,
            text: String,
        }

        let complex_data = RefCell::new(TestStruct {
            value: 100,
            text: "test string".to_string(),
        });

        let result = safe_borrow_and_process(&complex_data, |data| {
            assert_eq!(data.value, 100);
            assert_eq!(data.text, "test string");
        });

        assert!(result.is_ok());
    }

    #[test]
    fn test_panic_handling() {
        let data = RefCell::new(10);

        let result = safe_borrow_and_process(&data, |_| {
            panic!("This processor panics");
        });

        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), "Processing panicked".to_string());
    }

    #[test]
    fn test_multiple_borrows() {
        let data = RefCell::new(vec![1, 2, 3]);

        // First borrow
        let result1 = safe_borrow_and_process(&data, |vec| {
            assert_eq!(vec.len(), 3);
            assert_eq!(vec[0], 1);
        });

        // Second borrow
        let result2 = safe_borrow_and_process(&data, |vec| {
            assert_eq!(vec[1], 2);
            assert_eq!(vec[2], 3);
        });

        assert!(result1.is_ok());
        assert!(result2.is_ok());
    }

    #[test]
    fn test_multithreaded_access() {
        // Replace RefCell with Mutex for thread-safe access
        let data = Arc::new(Mutex::new(0));
        let mut handles = vec![];

        for _ in 0..5 {
            let data_clone = Arc::clone(&data);
            let handle = thread::spawn(move || {
                // Create a temporary RefCell to use with our function
                // This simulates using the thread-safe data in a thread-local way
                let result = {
                    if let Ok(guard) = data_clone.lock() {
                        let temp_refcell = RefCell::new(*guard);
                        safe_borrow_and_process(&temp_refcell, |&val| {
                            // Just a read operation
                        })
                    } else {
                        Err("Failed to acquire lock".to_string())
                    }
                };

                result
            });
            handles.push(handle);
        }

        for handle in handles {
            let _ = handle.join().unwrap();
        }

        // The test passes if we get here without the program crashing
    }

    #[test]
    fn test_nested_processing() {
        let outer_data = RefCell::new(RefCell::new(42));

        let result = safe_borrow_and_process(&outer_data, |inner_cell| {
            let inner_result = safe_borrow_and_process(inner_cell, |value| {
                assert_eq!(*value, 42);
            });

            assert!(inner_result.is_ok());
        });

        assert!(result.is_ok());
    }

    #[test]
    fn test_processor_side_effects() {
        let data = RefCell::new(10);
        let counter = RefCell::new(0);

        let result = safe_borrow_and_process(&data, |_| {
            *counter.borrow_mut() += 1;
        });

        assert!(result.is_ok());
        assert_eq!(*counter.borrow(), 1);
    }

    #[test]
    fn test_with_empty_data() {
        let data = RefCell::new(());

        let result = safe_borrow_and_process(&data, |_| {
            // Do nothing with the unit value
        });

        assert!(result.is_ok());
    }
}

