        // Note: This test is for demonstration purposes only
        // In real code, dereferencing the resulting pointer would be unsafe and invalid

        let null_ptr: *const u8 = ptr::null();
        let backtracked = backtrack_pointer(null_ptr, 10);

        // The result should be 10 bytes before the null pointer address
        // We can compare raw addresses but not dereference them
        assert_eq!(backtracked as usize, (null_ptr as usize).wrapping_sub(10));
    }
}

