    fn test_wrapping_behavior() {
        let data = [10u8, 20, 30, 40, 50];
        let base_ptr = data.as_ptr();

        // Test wrapping behavior using pointer arithmetic
        let test_offsets = [usize::MAX, usize::MAX - 1, usize::MAX - 2];

        for &offset in &test_offsets {
            let wrapped_ptr = calculate_wrapped_address(base_ptr, offset);
            let expected_ptr = unsafe { base_ptr.wrapping_byte_add(offset) };

            assert_eq!(wrapped_ptr, expected_ptr);

            // Don't dereference - this would cause undefined behavior
        }
    }

    #[test]
    fn test_large_offset() {
        let data = [10u8, 20, 30, 40, 50];
        let base_ptr = data.as_ptr();

        // For wrapping_byte_add, (ptr + usize::MAX) is equivalent to (ptr - 1)
        let large_offset = usize::MAX;
        let result = calculate_wrapped_address(base_ptr, large_offset);

        // Verify the mathematical property without dereferencing
        let expected = unsafe { base_ptr.wrapping_byte_sub(1) };
        assert_eq!(result, expected);
    }

    #[test]
    fn test_null_pointer() {
        let null_ptr: *const u8 = ptr::null();

        // Even with null pointer, the function should compute an offset
        let result = calculate_wrapped_address(null_ptr, 5);
        let expected = unsafe { null_ptr.wrapping_byte_add(5) };

        assert_eq!(result, expected);
    }

    #[test]
    fn test_aligned_offset() {
        // Create aligned data
        let data = [1u32, 2, 3, 4, 5];

        // Cast to byte pointer
        let base_ptr = data.as_ptr() as *const u8;

        // Test offsets that align with u32 boundaries (4 bytes each)
        for i in 0..data.len() {
            let offset = i * std::mem::size_of::<u32>();
            let result = calculate_wrapped_address(base_ptr, offset);

            // Ensure we're properly aligned
            assert_eq!(result as usize % std::mem::align_of::<u32>(), 0);

            // Only dereference if we're within bounds
            if i < data.len() {
                unsafe {
                    // Cast back to u32 pointer and dereference
                    let u32_ptr = result.cast::<u32>();
                    assert_eq!(*u32_ptr, data[i]);
                }
            }
        }
    }

    #[test]
    fn test_offset_arithmetic_properties() {
        let data = [10u8, 20, 30, 40, 50];
        let base_ptr = data.as_ptr();

        // Test with various offsets that stay within bounds
        let test_cases = [(0, 1), (1, 2), (0, 3), (2, 1)];

        for (offset1, offset2) in test_cases {
            // Make sure the combined offset is still within bounds
            assert!(offset1 + offset2 < data.len());

            let result1 = calculate_wrapped_address(base_ptr, offset1 + offset2);

            let interim_ptr = calculate_wrapped_address(base_ptr, offset1);
            let result2 = calculate_wrapped_address(interim_ptr, offset2);

            assert_eq!(result1, result2);

            // Additionally verify we can safely dereference
            unsafe {
                assert_eq!(*result1, data[offset1 + offset2]);
                assert_eq!(*result2, data[offset1 + offset2]);
            }
        }
    }
}

