    fn test_simple_backward_move() {
        let data = [1u8, 2, 3, 4, 5];
        let ptr = &data[3] as *const u8;
        let result = backward_traverse(ptr, 2);

        assert_eq!(result, &data[1] as *const u8);

        // Verify the result points to the correct value
        unsafe {
            assert_eq!(*result, 2);
        }
    }

    #[test]
    fn test_zero_move() {
        let data = [1u8, 2, 3];
        let ptr = &data[1] as *const u8;
        let result = backward_traverse(ptr, 0);

        assert_eq!(result, ptr);

        // Verify the result points to the correct value
        unsafe {
            assert_eq!(*result, 2);
        }
    }

    #[test]
    fn test_boundary_case() {
        // Test with a pointer at the start of a slice
        let data = [10u8, 20, 30];
        let ptr = &data[0] as *const u8;

        // Moving backward should wrap around
        let result = backward_traverse(ptr, 1);

        // This should have wrapped around
        assert_ne!(result, ptr);

        // Can't safely dereference the wrapped pointer,
        // but we can verify it's exactly one byte behind
        assert_eq!(result as usize, ptr as usize - 1);
    }

    #[test]
    fn test_large_offset() {
        // Test with a very large offset that would cause wrapping
        let data = [100u8, 110, 120];
        let ptr = &data[1] as *const u8;

        // Use a large value that will definitely cause wrapping
        let large_offset = usize::MAX - 10;
        let result = backward_traverse(ptr, large_offset);

        // Expected value: ptr + 11 (due to wrapping)
        // Original: ptr - (usize::MAX - 10) = ptr - usize::MAX + 10 = ptr + 10 + 1
        assert_eq!(result as usize, ptr as usize + 11);
    }

    #[test]
    fn test_null_ptr() {
        // Even null pointers should work with wrapping_byte_sub
        let ptr = ptr::null();

        // Move backward, which should wrap around to the end of address space
        let result = backward_traverse(ptr, 1);

        // Expected result: usize::MAX as a pointer
        assert_eq!(result as usize, usize::MAX);
    }

    #[test]
    fn test_max_address() {
        // Create a pointer at the maximum possible address
        let ptr = usize::MAX as *const u8;

        // Move backward by different amounts
        let result1 = backward_traverse(ptr, 1);
        let result2 = backward_traverse(ptr, usize::MAX);

        // Expected results
        assert_eq!(result1 as usize, usize::MAX - 1);
        assert_eq!(result2 as usize, 0);
    }
}

