#[cfg(test)]
mod tests {
    use std::ptr;
    use std::sync::atomic::{AtomicI32, Ordering};
    use std::thread;
    use std::sync::Arc;

    // Import the function being tested
    use super::create_atomic_reference;

    #[test]
    fn test_basic_functionality() {
        // Allocate memory for an integer
        let mut value = Box::new(42);
        let raw_ptr = &mut *value as *mut i32;

        unsafe {
            // Create an atomic reference to our integer
            let atomic_ref = create_atomic_reference(raw_ptr);

            // Check that the initial value is correct
            assert_eq!(atomic_ref.load(Ordering::SeqCst), 42);

            // Modify the value through the atomic reference
            atomic_ref.store(100, Ordering::SeqCst);

            // Verify that the value was changed
            assert_eq!(*value, 100);
        }
    }

    #[test]
    fn test_multithreaded_access() {
        // Create value in heap memory that will outlive all threads
        let value = Box::into_raw(Box::new(0));

        // Create atomic reference - we need to wrap it in an Arc for sharing
        let atomic_ref = unsafe { create_atomic_reference(value) };

        // Reference counter to share the atomic reference between threads
        let atomic_arc = Arc::new(atomic_ref);

        // Number of threads and increments per thread
        const NUM_THREADS: usize = 10;
        const INCREMENTS_PER_THREAD: usize = 1000;

        // Create handles for all threads
        let mut handles = Vec::with_capacity(NUM_THREADS);

        // Spawn threads that will increment the counter
        for _ in 0..NUM_THREADS {
            let atomic_clone = Arc::clone(&atomic_arc);

            let handle = thread::spawn(move || {
                for _ in 0..INCREMENTS_PER_THREAD {
                    // Fetch and add 1 atomically
                    atomic_clone.fetch_add(1, Ordering::SeqCst);
                }
            });

            handles.push(handle);
        }

        // Wait for all threads to complete
        for handle in handles {
            handle.join().unwrap();
        }

        // Check final value
        let expected = (NUM_THREADS * INCREMENTS_PER_THREAD) as i32;
        assert_eq!(atomic_arc.load(Ordering::SeqCst), expected);

        // Clean up the box to prevent memory leak
        unsafe {
            drop(Box::from_raw(value));
        }
    }

    // Remove the test_null_pointer_handling test as it causes undefined behavior
    // Using AtomicI32 with a null pointer is always unsafe and not a valid test case

    #[test]
    fn test_aligned_memory() {
        // Test aligned memory allocation
        // AtomicI32 requires 4-byte alignment

        // Create an aligned allocation
        let mut aligned_value = Box::new([0i32; 4]); // This should be properly aligned
        let raw_ptr = &mut aligned_value[2] as *mut i32;

        unsafe {
            let atomic_ref = create_atomic_reference(raw_ptr);

            // Check initial value
            assert_eq!(atomic_ref.load(Ordering::SeqCst), 0);

            // Store a value
            atomic_ref.store(123, Ordering::SeqCst);

            // Verify through direct access
            assert_eq!(aligned_value[2], 123);
        }
    }

    #[test]
    fn test_multiple_atomic_references() {
        // Test creating multiple atomic references to the same memory
        let mut value = Box::new(0i32);
        let raw_ptr = &mut *value as *mut i32;

        unsafe {
            let atomic_ref1 = create_atomic_reference(raw_ptr);
            let atomic_ref2 = create_atomic_reference(raw_ptr);

            // Store using first reference
            atomic_ref1.store(42, Ordering::SeqCst);

            // Load using second reference
            assert_eq!(atomic_ref2.load(Ordering::SeqCst), 42);

            // Modify using compare_exchange
            let result = atomic_ref1.compare_exchange(
                42, 100, Ordering::SeqCst, Ordering::SeqCst
            );
            assert_eq!(result, Ok(42));

            // Verify with both references
            assert_eq!(atomic_ref1.load(Ordering::SeqCst), 100);
            assert_eq!(atomic_ref2.load(Ordering::SeqCst), 100);
            assert_eq!(*value, 100);
        }
    }
}

