use std::mem::MaybeUninit;

fn duplicate_maybe_uninit<T: Copy>(uninit: &MaybeUninit<T>) -> (T, T) {
    unsafe {
        let first = uninit.assume_init_read();
        let second = uninit.assume_init_read();
        (first, second)
    }
}

