        // Test with bool
        let value: bool = true;
        let uninit = MaybeUninit::new(value);
        let (first, second) = duplicate_maybe_uninit(&uninit);
        assert_eq!(first, true);
        assert_eq!(second, true);

        // Test with char
        let value: char = 'x';
        let uninit = MaybeUninit::new(value);
        let (first, second) = duplicate_maybe_uninit(&uninit);
        assert_eq!(first, 'x');
        assert_eq!(second, 'x');
    }

    #[test]
    fn test_duplicate_arrays_and_tuples() {
        // Test with array
        let value: [i32; 3] = [1, 2, 3];
        let uninit = MaybeUninit::new(value);
        let (first, second) = duplicate_maybe_uninit(&uninit);
        assert_eq!(first, [1, 2, 3]);
        assert_eq!(second, [1, 2, 3]);

        // Test with tuple
        let value: (u8, bool) = (255, false);
        let uninit = MaybeUninit::new(value);
        let (first, second) = duplicate_maybe_uninit(&uninit);
        assert_eq!(first, (255, false));
        assert_eq!(second, (255, false));
    }

    #[test]
    fn test_duplicate_custom_types() {
        // Define a custom struct that implements Copy
        #[derive(Debug, Copy, Clone, PartialEq)]
        struct Point {
            x: f32,
            y: f32,
        }

        let value = Point { x: 1.0, y: 2.0 };
        let uninit = MaybeUninit::new(value);
        let (first, second) = duplicate_maybe_uninit(&uninit);
        assert_eq!(first.x, 1.0);
        assert_eq!(first.y, 2.0);
        assert_eq!(second.x, 1.0);
        assert_eq!(second.y, 2.0);
        assert_eq!(first, second);
    }

    #[test]
    fn test_with_zero_sized_types() {
        // Zero-sized types are also Copy
        #[derive(Debug, Copy, Clone, PartialEq)]
        struct Empty;

        let value = Empty;
        let uninit = MaybeUninit::new(value);
        let (_first, _second) = duplicate_maybe_uninit(&uninit);
        // No assertions needed for ZSTs besides the fact that it compiles and runs
    }

    #[test]
    fn test_reference_passing() {
        // Test that we correctly handle the reference to MaybeUninit
        let value: u64 = 0xDEADBEEF;
        let uninit = MaybeUninit::new(value);

        // Test with reference
        let (first, second) = duplicate_maybe_uninit(&uninit);
        assert_eq!(first, 0xDEADBEEF);
        assert_eq!(second, 0xDEADBEEF);

        // The original MaybeUninit should still be usable
        let value_after = unsafe { uninit.assume_init() };
        assert_eq!(value_after, 0xDEADBEEF);
    }

    #[test]
    fn test_with_option_enum() {
        // Option is Copy when T is Copy
        let value: Option<u32> = Some(123);
        let uninit = MaybeUninit::new(value);
        let (first, second) = duplicate_maybe_uninit(&uninit);
        assert_eq!(first, Some(123));
        assert_eq!(second, Some(123));

        let value: Option<u32> = None;
        let uninit = MaybeUninit::new(value);
        let (first, second) = duplicate_maybe_uninit(&uninit);
        assert_eq!(first, None);
        assert_eq!(second, None);
    }

    #[test]
    fn test_uninit_created_with_zeroed() {
        // Test with MaybeUninit created with zeroed
        let uninit = MaybeUninit::<u32>::zeroed();
        let (first, second) = duplicate_maybe_uninit(&uninit);
        assert_eq!(first, 0);
        assert_eq!(second, 0);
    }
}

