use std::alloc::{GlobalAlloc, Layout, System};
use std::ptr;

fn allocate_uefi_buffer(size: usize) -> Option<*mut u8> {
    if size == 0 {
        return None;
    }

    let layout = match Layout::from_size_align(size, 8) {
        Ok(layout) => layout,
        Err(_) => return None,
    };

    let ptr = unsafe { System.alloc(layout) };
    if ptr.is_null() {
        None
    } else {
        Some(ptr)
    }
}

