#[cfg(test)]
mod tests {
    use super::*;
    use std::alloc::{Layout, System};
    use std::ptr;
    use std::mem;

    #[test]
    fn test_zero_size_returns_none() {
        assert_eq!(allocate_uefi_buffer(0), None);
    }

    #[test]
    fn test_successful_allocation() {
        let size = 1024;
        let ptr = allocate_uefi_buffer(size);

        assert!(ptr.is_some());

        // Check that the allocated memory can be written to and read from
        if let Some(buffer) = ptr {
            unsafe {
                // Write a pattern to the buffer
                for i in 0..size {
                    *buffer.add(i) = (i % 255) as u8;
                }

                // Read and verify the pattern
                for i in 0..size {
                    assert_eq!(*buffer.add(i), (i % 255) as u8);
                }

                // Clean up - deallocate the memory
                System.dealloc(buffer, Layout::from_size_align(size, 8).unwrap());
            }
        }
    }

    #[test]
    fn test_alignment_requirement() {
        let size = 100;
        let ptr = allocate_uefi_buffer(size);

        assert!(ptr.is_some());

        if let Some(buffer) = ptr {
            // Check that the pointer is 8-byte aligned
            assert_eq!(buffer as usize % 8, 0);

            // Clean up
            unsafe {
                System.dealloc(buffer, Layout::from_size_align(size, 8).unwrap());
            }
        }
    }

    #[test]
    fn test_large_allocation() {
        // 1 MB allocation
        let size = 1024 * 1024;
        let ptr = allocate_uefi_buffer(size);

        assert!(ptr.is_some());

        if let Some(buffer) = ptr {
            unsafe {
                // Write to the beginning and end of the buffer to ensure it's usable
                *buffer = 42;
                *buffer.add(size - 1) = 42;

                assert_eq!(*buffer, 42);
                assert_eq!(*buffer.add(size - 1), 42);

                // Clean up
                System.dealloc(buffer, Layout::from_size_align(size, 8).unwrap());
            }
        }
    }

    #[test]
    fn test_multiple_allocations() {
        let allocations = 10;
        let size = 128;
        let mut ptrs = Vec::with_capacity(allocations);

        // Perform multiple allocations
        for _ in 0..allocations {
            let ptr = allocate_uefi_buffer(size);
            assert!(ptr.is_some());
            ptrs.push(ptr.unwrap());
        }

        // Verify all allocations are unique
        for i in 0..allocations {
            for j in i+1..allocations {
                assert_ne!(ptrs[i], ptrs[j]);
            }
        }

        // Clean up
        for ptr in ptrs {
            unsafe {
                System.dealloc(ptr, Layout::from_size_align(size, 8).unwrap());
            }
        }
    }

    // This test checks the behavior when memory allocation fails
    // Note: This test is conditionally compiled because forcing allocation failure
    // is challenging in a portable way
    #[cfg(feature = "allocation_failure_test")]
    #[test]
    fn test_allocation_failure() {
        use std::sync::atomic::{AtomicBool, Ordering};

        static FORCE_ALLOCATION_FAILURE: AtomicBool = AtomicBool::new(false);

        // A custom allocator that can be forced to fail
        struct TestAllocator;

        unsafe impl GlobalAlloc for TestAllocator {
            unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
                if FORCE_ALLOCATION_FAILURE.load(Ordering::SeqCst) {
                    ptr::null_mut()
                } else {
                    System.alloc(layout)
                }
            }

            unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
                System.dealloc(ptr, layout)
            }
        }

        // Set up the test
        FORCE_ALLOCATION_FAILURE.store(true, Ordering::SeqCst);

        // Try to allocate - this should fail
        assert_eq!(allocate_uefi_buffer(1024), None);

        // Reset for other tests
        FORCE_ALLOCATION_FAILURE.store(false, Ordering::SeqCst);
    }

    #[test]
    fn test_invalid_layout() {
        // Try to create a layout that would cause Layout::from_size_align to fail
        // This should be caught and handled gracefully
        let size = usize::MAX;
        assert_eq!(allocate_uefi_buffer(size), None);
    }
}

