mod tests {
    use super::log_successful_query;
    use std::cell::RefCell;
    use std::rc::Rc;

    #[test]
    fn test_successful_result_is_logged() {
        // Arrange
        let log_called = Rc::new(RefCell::new(false));
        let log_value = Rc::new(RefCell::new(0));

        let log_called_clone = log_called.clone();
        let log_value_clone = log_value.clone();

        let logger = move |value: &i32| {
            *log_called_clone.borrow_mut() = true;
            *log_value_clone.borrow_mut() = *value;
        };

        // Act
        let result: Result<i32, &str> = log_successful_query(Ok(42), logger);

        // Assert
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 42);
        assert!(*log_called.borrow());
        assert_eq!(*log_value.borrow(), 42);
    }

    #[test]
    fn test_error_result_is_not_logged() {
        // Arrange
        let log_called = Rc::new(RefCell::new(false));

        let log_called_clone = log_called.clone();

        let logger = move |_: &String| {
            *log_called_clone.borrow_mut() = true;
        };

        // Act
        let result: Result<String, &str> = log_successful_query(Err("error message"), logger);

        // Assert
        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), "error message");
        assert!(!*log_called.borrow());
    }

    #[test]
    fn test_with_different_types() {
        // Arrange
        let logged_values = Rc::new(RefCell::new(Vec::new()));
        let logged_values_clone = logged_values.clone();

        let logger = move |value: &Vec<i32>| {
            logged_values_clone.borrow_mut().push(value.clone());
        };

        // Act
        let test_vec = vec![1, 2, 3];
        let result: Result<Vec<i32>, &str> = log_successful_query(Ok(test_vec.clone()), logger);

        // Assert
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), test_vec);
        assert_eq!(logged_values.borrow().len(), 1);
        assert_eq!(logged_values.borrow()[0], test_vec);
    }

    #[test]
    fn test_custom_error_type() {
        // Define a custom error type
        #[derive(Debug, PartialEq)]
        struct CustomError(String);

        // Arrange
        let log_called = Rc::new(RefCell::new(false));

        let log_called_clone = log_called.clone();

        let logger = move |_: &u32| {
            *log_called_clone.borrow_mut() = true;
        };

        // Act
        let result: Result<u32, CustomError> = log_successful_query(
            Err(CustomError("custom error".to_string())), 
            logger
        );

        // Assert
        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), CustomError("custom error".to_string()));
        assert!(!*log_called.borrow());
    }

    #[test]
    fn test_logger_side_effects() {
        // Arrange
        let counter = Rc::new(RefCell::new(0));
        let counter_clone = counter.clone();

        let logger = move |value: &i32| {
            *counter_clone.borrow_mut() += *value;
        };

        // Act
        let _: Result<i32, &str> = log_successful_query(Ok(5), logger.clone());
        let _: Result<i32, &str> = log_successful_query(Ok(10), logger.clone());
        let _: Result<i32, &str> = log_successful_query(Err("error"), logger);

        // Assert
        assert_eq!(*counter.borrow(), 15);
    }
}

