#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, Mutex};
    use std::fmt::Debug;

    #[test]
    fn test_log_errors_with_error() {
        // Create a shared counter to verify the logging function was called
        let counter = Arc::new(Mutex::new(0));
        let counter_clone = Arc::clone(&counter);

        // Create a test error
        let error_result: Result<i32, String> = Err("test error".to_string());

        // Define a logging function that increments the counter
        let log_fn = move |e: &String| {
            assert_eq!(e, "test error");
            let mut count = counter_clone.lock().unwrap();
            *count += 1;
        };

        // Call log_errors with the error result
        let result = log_errors(error_result, log_fn);

        // Verify the result is still an error
        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), "test error".to_string());

        // Verify the logging function was called exactly once
        assert_eq!(*counter.lock().unwrap(), 1);
    }

    #[test]
    fn test_log_errors_with_ok() {
        // Create a shared counter to verify the logging function is not called
        let counter = Arc::new(Mutex::new(0));
        let counter_clone = Arc::clone(&counter);

        // Create a test success result
        let ok_result: Result<i32, String> = Ok(42);

        // Define a logging function that increments the counter
        let log_fn = move |_: &String| {
            let mut count = counter_clone.lock().unwrap();
            *count += 1;
        };

        // Call log_errors with the ok result
        let result = log_errors(ok_result, log_fn);

        // Verify the result is still ok
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 42);

        // Verify the logging function was not called
        assert_eq!(*counter.lock().unwrap(), 0);
    }

    #[test]
    fn test_log_errors_with_custom_type() {
        // Define a custom error type
        #[derive(Debug, PartialEq)]
        struct CustomError {
            code: i32,
            message: String,
        }

        // Create a shared value to capture the error details
        let captured_code = Arc::new(Mutex::new(0));
        let captured_code_clone = Arc::clone(&captured_code);

        // Create a test error with custom type
        let error = CustomError {
            code: 404,
            message: "Not Found".to_string(),
        };
        let error_result: Result<(), CustomError> = Err(error);

        // Define a logging function that captures error details
        let log_fn = move |e: &CustomError| {
            let mut code = captured_code_clone.lock().unwrap();
            *code = e.code;
        };

        // Call log_errors with the custom error
        let result = log_errors(error_result, log_fn);

        // Verify the result is still an error
        assert!(result.is_err());
        assert_eq!(result.unwrap_err().message, "Not Found".to_string());

        // Verify the logging function captured the error code
        assert_eq!(*captured_code.lock().unwrap(), 404);
    }

    #[test]
    fn test_log_errors_chaining() {
        // Create counters for each stage
        let stage1_counter = Arc::new(Mutex::new(0));
        let stage1_clone = Arc::clone(&stage1_counter);

        let stage2_counter = Arc::new(Mutex::new(0));
        let stage2_clone = Arc::clone(&stage2_counter);

        // Setup a two-stage processing pipeline
        let process_stage1 = |input: i32| -> Result<i32, String> {
            if input < 0 {
                Err("Stage 1 error: negative input".to_string())
            } else {
                Ok(input * 2)
            }
        };

        let process_stage2 = |input: i32| -> Result<i32, String> {
            if input > 100 {
                Err("Stage 2 error: value too large".to_string())
            } else {
                Ok(input + 10)
            }
        };

        // Test with input that fails at stage 1
        let input = -5;
        let stage1_log = move |e: &String| {
            assert!(e.starts_with("Stage 1 error"));
            let mut count = stage1_clone.lock().unwrap();
            *count += 1;
        };

        let stage2_log = move |e: &String| {
            assert!(e.starts_with("Stage 2 error"));
            let mut count = stage2_clone.lock().unwrap();
            *count += 1;
        };

        let result = process_stage1(input)
            .inspect_err(|_| println!("Raw error in stage 1"))  // Should not affect the pipeline
            .and_then(process_stage2);

        let logged_result = log_errors(result, stage1_log);

        assert!(logged_result.is_err());
        assert_eq!(*stage1_counter.lock().unwrap(), 1);
        assert_eq!(*stage2_counter.lock().unwrap(), 0);

        // Test with input that fails at stage 2
        let stage1_counter = Arc::new(Mutex::new(0));
        let stage1_clone = Arc::clone(&stage1_counter);

        let stage2_counter = Arc::new(Mutex::new(0));
        let stage2_clone = Arc::clone(&stage2_counter);

        let stage1_log = move |e: &String| {
            let mut count = stage1_clone.lock().unwrap();
            *count += 1;
        };

        let stage2_log = move |e: &String| {
            assert!(e.starts_with("Stage 2 error"));
            let mut count = stage2_clone.lock().unwrap();
            *count += 1;
        };

        let input = 60;  // Will pass stage 1 but fail stage 2 after multiplication
        let result = process_stage1(input)
            .and_then(process_stage2);

        let logged_result = log_errors(result, stage2_log);

        assert!(logged_result.is_err());
        assert_eq!(*stage1_counter.lock().unwrap(), 0);
        assert_eq!(*stage2_counter.lock().unwrap(), 1);
    }

    #[test]
    fn test_log_errors_with_mutable_state() {
        // Create a mutable state that will be modified by the logging function
        let mut log_messages = Vec::new();

        // Create a test error
        let error_result: Result<(), &'static str> = Err("critical error");

        // Define a logging function that captures the error message
        let log_fn = |e: &&'static str| {
            log_messages.push((*e).to_string());
        };

        // Call log_errors with the error result
        let result = log_errors(error_result, log_fn);

        // Verify the result is still an error
        assert!(result.is_err());

        // Verify the logging function captured the error message
        assert_eq!(log_messages.len(), 1);
        assert_eq!(log_messages[0], "critical error");
    }
}

