    fn test_extract_primitive() {
        // Case 1: Single reference - should extract without cloning
        let value = 42;
        let rc = Rc::new(value);
        assert_eq!(Rc::strong_count(&rc), 1);

        let result = extract_or_clone(rc);
        assert_eq!(result, 42);

        // Case 2: Multiple references - should clone
        let value = 100;
        let rc = Rc::new(value);
        let rc_clone = Rc::clone(&rc);
        assert_eq!(Rc::strong_count(&rc), 2);

        let result = extract_or_clone(rc);
        assert_eq!(result, 100);
        // Verify rc_clone is still valid
        assert_eq!(*rc_clone, 100);
    }

    // Test with a String (heap allocated type)
    #[test]
    fn test_extract_string() {
        // Single reference - should extract without cloning
        let value = String::from("test string");
        let rc = Rc::new(value);
        assert_eq!(Rc::strong_count(&rc), 1);

        let result = extract_or_clone(rc);
        assert_eq!(result, "test string");

        // Multiple references - should clone
        let value = String::from("another test");
        let rc = Rc::new(value);
        let rc_clone = Rc::clone(&rc);
        assert_eq!(Rc::strong_count(&rc), 2);

        let result = extract_or_clone(rc);
        assert_eq!(result, "another test");
        // Verify rc_clone is still valid
        assert_eq!(*rc_clone, "another test");
    }

    // Test with a custom struct implementing Clone
    #[derive(Debug, Clone, PartialEq)]
    struct TestStruct {
        value: i32,
        name: String,
    }

    #[test]
    fn test_extract_custom_struct() {
        // Single reference - should extract without cloning
        let value = TestStruct {
            value: 123,
            name: String::from("test struct"),
        };
        let rc = Rc::new(value);
        assert_eq!(Rc::strong_count(&rc), 1);

        let result = extract_or_clone(rc);
        assert_eq!(result.value, 123);
        assert_eq!(result.name, "test struct");

        // Multiple references - should clone
        let value = TestStruct {
            value: 456,
            name: String::from("another struct"),
        };
        let rc = Rc::new(value);
        let rc_clone = Rc::clone(&rc);
        assert_eq!(Rc::strong_count(&rc), 2);

        let result = extract_or_clone(rc);
        assert_eq!(result.value, 456);
        assert_eq!(result.name, "another struct");
        // Verify rc_clone is still valid
        assert_eq!(rc_clone.value, 456);
        assert_eq!(rc_clone.name, "another struct");
    }

    // Test with nested Rc structures
    #[test]
    fn test_nested_rc() {
        // Create an Rc inside an Rc
        let inner = Rc::new(42);
        let outer = Rc::new(inner);

        // Single reference to outer - should extract without cloning
        let result = extract_or_clone(outer);

        // Still have the inner reference
        assert_eq!(Rc::strong_count(&result), 1);
        assert_eq!(*result, 42);

        // Multiple references - should clone
        let inner = Rc::new(100);
        let outer = Rc::new(Rc::clone(&inner));
        let outer_clone = Rc::clone(&outer);

        let result = extract_or_clone(outer);

        // Verify the result and that outer_clone is still valid
        assert_eq!(*result, 100);
        assert_eq!(**outer_clone, 100);
    }

    // Test with empty/zero-sized types
    #[test]
    fn test_zero_sized_type() {
        // Unit type ()
        let rc = Rc::new(());
        let result = extract_or_clone(rc);
        assert_eq!(result, ());

        // Multiple references
        let rc = Rc::new(());
        let rc_clone = Rc::clone(&rc);
        let result = extract_or_clone(rc);
        assert_eq!(result, ());
        assert_eq!(*rc_clone, ());
    }
}

