#[cfg(test)]
mod tests {
    use std::collections::HashMap;
    use std::collections::hash_map::RandomState;
    use std::hash::{Hash, BuildHasher};
    use super::create_consistent_hash_map;

    #[test]
    fn test_create_empty_hash_map() {
        // Test with concrete types
        let map: HashMap<i32, String, RandomState> = create_consistent_hash_map();

        // An empty map should have zero length
        assert_eq!(map.len(), 0);
        assert!(map.is_empty());
    }

    #[test]
    fn test_hash_map_insertion_works() {
        // Create empty map with concrete types
        let mut map: HashMap<String, u32, RandomState> = create_consistent_hash_map();

        // Insert values and verify they can be retrieved
        map.insert("test".to_string(), 42);
        map.insert("another".to_string(), 100);

        assert_eq!(map.len(), 2);
        assert_eq!(map.get("test"), Some(&42));
        assert_eq!(map.get("another"), Some(&100));
        assert_eq!(map.get("nonexistent"), None);
    }

    #[test]
    fn test_consistent_hasher_behavior() {
        // Create two maps with the default RandomState hasher
        let mut map1: HashMap<i32, i32, RandomState> = create_consistent_hash_map();
        let mut map2: HashMap<i32, i32, RandomState> = create_consistent_hash_map();

        // Each map uses its own RandomState instance, so we'll just
        // verify that basic operations work consistently
        for i in 0..100 {
            map1.insert(i, i * 2);
            map2.insert(i, i * 2);
        }

        // Both maps should have the same size
        assert_eq!(map1.len(), map2.len());

        // Check that values can be retrieved from both maps
        for i in 0..100 {
            assert_eq!(map1.get(&i), Some(&(i * 2)));
            assert_eq!(map2.get(&i), Some(&(i * 2)));
        }
    }

    #[test]
    fn test_with_complex_types() {
        // Test with struct keys
        #[derive(Eq, PartialEq, Hash)]
        struct TestKey {
            id: i32,
            name: String,
        }

        let mut map: HashMap<TestKey, Vec<f64>, RandomState> = create_consistent_hash_map();

        let key1 = TestKey { id: 1, name: "first".to_string() };
        let key2 = TestKey { id: 2, name: "second".to_string() };

        map.insert(key1, vec![1.0, 2.0, 3.0]);
        map.insert(key2, vec![4.0, 5.0, 6.0]);

        assert_eq!(map.len(), 2);

        // Create identical key to test lookup
        let lookup_key = TestKey { id: 1, name: "first".to_string() };
        assert_eq!(map.get(&lookup_key), Some(&vec![1.0, 2.0, 3.0]));
    }

    #[test]
    fn test_capacity_behavior() {
        // Test that the map correctly handles capacity growth
        let mut map: HashMap<u64, String, RandomState> = create_consistent_hash_map();

        // Insert a larger number of elements to test automatic capacity adjustment
        for i in 0..1000 {
            map.insert(i, i.to_string());
        }

        assert_eq!(map.len(), 1000);

        // Verify all values can be retrieved
        for i in 0..1000 {
            assert_eq!(map.get(&i), Some(&i.to_string()));
        }
    }
}

