fn compare_raw_pointers<T>(slice1: &[*const T], slice2: &[*const T]) -> bool {
    if slice1.len() != slice2.len() {
        return false;
    }

    slice1.iter().zip(slice2.iter()).all(|(a, b)| a.eq(b))
}

