mod tests {
    use super::*;
    use std::ptr;

    #[test]
    fn test_empty_slices() {
        let slice1: &[*const i32] = &[];
        let slice2: &[*const i32] = &[];
        assert!(compare_raw_pointers(slice1, slice2));
    }

    #[test]
    fn test_different_lengths() {
        let val1: i32 = 42;
        let ptr1 = &val1 as *const i32;

        let slice1: &[*const i32] = &[ptr1];
        let slice2: &[*const i32] = &[ptr1, ptr1];

        assert!(!compare_raw_pointers(slice1, slice2));
    }

    #[test]
    fn test_same_pointers() {
        let val1: i32 = 10;
        let val2: i32 = 20;

        let ptr1 = &val1 as *const i32;
        let ptr2 = &val2 as *const i32;

        let slice1: &[*const i32] = &[ptr1, ptr2, ptr1];
        let slice2: &[*const i32] = &[ptr1, ptr2, ptr1];

        assert!(compare_raw_pointers(slice1, slice2));
    }

    #[test]
    fn test_different_pointers_same_address() {
        let val: i32 = 42;

        // Two ways to get the same address
        let ptr1 = &val as *const i32;
        let ptr2 = ptr::addr_of!(val);

        let slice1: &[*const i32] = &[ptr1];
        let slice2: &[*const i32] = &[ptr2];

        assert!(compare_raw_pointers(slice1, slice2));
    }

    #[test]
    fn test_different_pointers_different_values() {
        let val1: i32 = 10;
        let val2: i32 = 20;

        let ptr1 = &val1 as *const i32;
        let ptr2 = &val2 as *const i32;

        let slice1: &[*const i32] = &[ptr1];
        let slice2: &[*const i32] = &[ptr2];

        assert!(!compare_raw_pointers(slice1, slice2));
    }

    #[test]
    fn test_null_pointers() {
        let null_ptr: *const i32 = ptr::null();

        let slice1: &[*const i32] = &[null_ptr, null_ptr];
        let slice2: &[*const i32] = &[null_ptr, null_ptr];

        assert!(compare_raw_pointers(slice1, slice2));
    }

    #[test]
    fn test_mixed_null_and_valid_pointers() {
        let val: i32 = 42;
        let valid_ptr = &val as *const i32;
        let null_ptr: *const i32 = ptr::null();

        let slice1: &[*const i32] = &[valid_ptr, null_ptr];
        let slice2: &[*const i32] = &[valid_ptr, null_ptr];

        assert!(compare_raw_pointers(slice1, slice2));
    }

    #[test]
    fn test_different_generic_types() {
        // Test with a different concrete type
        let s1 = String::from("test");
        let s2 = String::from("test");

        let ptr1 = &s1 as *const String;
        let ptr2 = &s2 as *const String;

        let slice1: &[*const String] = &[ptr1];
        let slice2: &[*const String] = &[ptr2];

        assert!(!compare_raw_pointers(slice1, slice2));
    }

    #[test]
    fn test_dangling_pointers() {
        let ptr1: *const i32;
        let ptr2: *const i32;

        {
            let val1 = 10;
            let val2 = 10;
            ptr1 = &val1 as *const i32;
            ptr2 = &val2 as *const i32;
        } // val1 and val2 go out of scope, pointers are now dangling

        // Even though the pointers are dangling, they have different addresses
        let slice1: &[*const i32] = &[ptr1];
        let slice2: &[*const i32] = &[ptr2];

        assert!(!compare_raw_pointers(slice1, slice2));
    }

    #[test]
    fn test_wide_pointers() {
        let s1 = "hello";
        let s2 = "hello"; // Same content but potentially different addresses

        // Use pointer to pointer to avoid issues with unsized types
        let ptr1 = &s1 as *const &str;
        let ptr2 = &s2 as *const &str;

        let slice1: &[*const &str] = &[ptr1];
        let slice2: &[*const &str] = &[ptr2];

        let result = compare_raw_pointers(slice1, slice2);

        // Not asserting a specific result as string literals might be interned
        // Just making sure it doesn't crash or have undefined behavior
        let _ = result;
    }

    #[test]
    fn test_trait_object_pointers() {
        trait MyTrait {}

        struct Struct1;
        impl MyTrait for Struct1 {}

        struct Struct2;
        impl MyTrait for Struct2 {}

        let obj1 = Struct1;
        let obj2 = Struct1;

        // Use pointers to trait object references instead of direct trait object pointers
        let trait_ref1: &dyn MyTrait = &obj1;
        let trait_ref2: &dyn MyTrait = &obj2;

        let ptr1 = &trait_ref1 as *const &dyn MyTrait;
        let ptr2 = &trait_ref2 as *const &dyn MyTrait;

        let slice1: &[*const &dyn MyTrait] = &[ptr1];
        let slice2: &[*const &dyn MyTrait] = &[ptr2];

        // Different instances should have different addresses
        assert!(!compare_raw_pointers(slice1, slice2));
    }

    #[test]
    fn test_aligned_pointers() {
        // Create values with specific alignment
        #[repr(align(16))]
        struct Aligned(i32);

        let val1 = Aligned(10);
        let val2 = Aligned(10);

        let ptr1 = &val1 as *const Aligned;
        let ptr2 = &val2 as *const Aligned;

        let slice1: &[*const Aligned] = &[ptr1];
        let slice2: &[*const Aligned] = &[ptr2];

        assert!(!compare_raw_pointers(slice1, slice2));
    }
