            fn dummy(&self) -> i32 { 42 }
        }

        let mut test_struct = TestStruct;
        let trait_obj: &mut dyn Example = &mut test_struct;

        let ptr1 = unsafe { NonNull::new_unchecked(trait_obj) };
        let ptr2 = unsafe { NonNull::new_unchecked(trait_obj) };

        assert!(are_pointers_equal(ptr1, ptr2));
    }

    #[test]
    fn test_with_zero_sized_type() {
        // Zero-sized types (ZST) still have addresses, even though they don't occupy space
        let mut zst1 = ();
        let mut zst2 = ();

        let ptr1 = unsafe { NonNull::new_unchecked(&mut zst1) };
        let ptr2 = unsafe { NonNull::new_unchecked(&mut zst1) }; // Same location
        let ptr3 = unsafe { NonNull::new_unchecked(&mut zst2) }; // Different location

        assert!(are_pointers_equal(ptr1, ptr2));
        // Note: ZSTs may have the same address even when they're different instances
        // So we don't assert on ptr1 vs ptr3 as the result is implementation-defined
    }

    #[test]
    fn test_pointer_from_box() {
        let mut boxed1 = Box::new(42);
        let mut boxed2 = Box::new(42);

        let ptr1 = NonNull::from(&mut *boxed1);
        let ptr2 = NonNull::from(&mut *boxed1); // Same box
        let ptr3 = NonNull::from(&mut *boxed2); // Different box

        assert!(are_pointers_equal(ptr1, ptr2));
        assert!(!are_pointers_equal(ptr1, ptr3));
    }

    #[test]
    fn test_pointer_from_vec() {
        let mut vec1 = vec![1, 2, 3];
        let mut vec2 = vec![1, 2, 3];

        // Get pointers to the first elements
        let ptr1 = NonNull::new(vec1.as_mut_ptr()).unwrap();
        let ptr2 = NonNull::new(vec1.as_mut_ptr()).unwrap(); // Same vec
        let ptr3 = NonNull::new(vec2.as_mut_ptr()).unwrap(); // Different vec

        assert!(are_pointers_equal(ptr1, ptr2));
        assert!(!are_pointers_equal(ptr1, ptr3));
    }
}

