fn upgrade_equipment_attributes(attributes: &mut [i32; 3], upgrades: [i32; 3]) -> [&mut i32; 3] {
    let mut upgraded_attributes = attributes.each_mut();
    for (attr, upgrade) in upgraded_attributes.iter_mut().zip(upgrades.iter()) {
        **attr += *upgrade;
    }
    upgraded_attributes
}

