#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_upgrade() {
        // Initial attributes: [10, 5, 3] (attack, defense, speed)
        let mut attributes = [10, 5, 3];

        // Apply upgrades: [2, 1, 4]
        let upgrades = [2, 1, 4];

        // Get mutable references to the upgraded attributes
        let upgraded_refs = upgrade_equipment_attributes(&mut attributes, upgrades);

        // Check that the original array was modified correctly
        // We need to check via the references to avoid multiple borrows
        assert_eq!(*upgraded_refs[0], 12);
        assert_eq!(*upgraded_refs[1], 6);
        assert_eq!(*upgraded_refs[2], 7);
    }

    #[test]
    fn test_negative_upgrades() {
        // Initial attributes
        let mut attributes = [20, 15, 10];

        // Apply negative upgrades (downgrades)
        let upgrades = [-5, -3, -2];

        let upgraded_refs = upgrade_equipment_attributes(&mut attributes, upgrades);

        // Check attributes via the references to avoid multiple borrows
        assert_eq!(*upgraded_refs[0], 15);
        assert_eq!(*upgraded_refs[1], 12);
        assert_eq!(*upgraded_refs[2], 8);
    }

    #[test]
    fn test_zero_upgrades() {
        let mut attributes = [7, 7, 7];
        let upgrades = [0, 0, 0];

        let upgraded_refs = upgrade_equipment_attributes(&mut attributes, upgrades);

        // Check values via the references to avoid multiple borrows
        assert_eq!(*upgraded_refs[0], 7);
        assert_eq!(*upgraded_refs[1], 7);
        assert_eq!(*upgraded_refs[2], 7);
    }

    #[test]
    fn test_mutation_through_returned_refs() {
        let mut attributes = [10, 20, 30];
        let upgrades = [1, 2, 3];

        // Get the mutable references
        let mut upgraded_refs = upgrade_equipment_attributes(&mut attributes, upgrades);

        // First, check the values through the references
        assert_eq!(*upgraded_refs[0], 11);
        assert_eq!(*upgraded_refs[1], 22);
        assert_eq!(*upgraded_refs[2], 33);

        // Modify values through the returned references
        *upgraded_refs[0] += 5;
        *upgraded_refs[1] -= 2;
        *upgraded_refs[2] *= 2;

        // Check the modified values through the references
        assert_eq!(*upgraded_refs[0], 16);
        assert_eq!(*upgraded_refs[1], 20);
        assert_eq!(*upgraded_refs[2], 66);
    }

    #[test]
    fn test_overflow_behavior() {
        // In debug mode, we test for the expected panic
        #[cfg(debug_assertions)]
        {
            let result = std::panic::catch_unwind(|| {
                let mut attributes = [i32::MAX - 1, 5, 10];
                let upgrades = [2, 0, 0];
                let _ = upgrade_equipment_attributes(&mut attributes, upgrades);
            });
            assert!(result.is_err());
        }

        // In release mode, we test the overflow behavior
        #[cfg(not(debug_assertions))]
        {
            let mut attributes = [i32::MAX - 1, 5, 10];
            let upgrades = [2, 0, 0];
            let upgraded_refs = upgrade_equipment_attributes(&mut attributes, upgrades);
            // In release mode, i32::MAX + 1 wraps to i32::MIN
            assert_eq!(*upgraded_refs[0], i32::MIN);
        }
    }
}

