fn secure_erase_last_16_bytes(buffer: &mut [u8]) -> Result<(), &'static str> {
    if let Some(last_chunk) = buffer.last_chunk_mut::<16>() {
        last_chunk.fill(0);
        Ok(())
    } else {
        Err("Buffer is too short")
    }
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_successful_erase() {
        let mut buffer = [0xFF; 32];

        // Fill the last 16 bytes with known pattern
        for i in 16..32 {
            buffer[i] = (i - 16) as u8;
        }

        let result = secure_erase_last_16_bytes(&mut buffer);

        assert!(result.is_ok());

        // Verify first 16 bytes are untouched
        for i in 0..16 {
            assert_eq!(buffer[i], 0xFF);
        }

        // Verify last 16 bytes are zeroed
        for i in 16..32 {
            assert_eq!(buffer[i], 0);
        }
    }

    #[test]
    fn test_minimum_size_buffer() {
        let mut buffer = [0xFF; 16];

        let result = secure_erase_last_16_bytes(&mut buffer);

        assert!(result.is_ok());

        // Verify all bytes are zeroed
        for byte in buffer.iter() {
            assert_eq!(*byte, 0);
        }
    }

    #[test]
    fn test_buffer_too_short() {
        let mut buffer = [0xFF; 15];

        let result = secure_erase_last_16_bytes(&mut buffer);

        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), "Buffer is too short");

        // Verify buffer was not modified
        for byte in buffer.iter() {
            assert_eq!(*byte, 0xFF);
        }
    }

    #[test]
    fn test_empty_buffer() {
        let mut buffer: [u8; 0] = [];

        let result = secure_erase_last_16_bytes(&mut buffer);

        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), "Buffer is too short");
    }

    #[test]
    fn test_exact_size_boundary() {
        // Test with buffers of sizes around the boundary
        let sizes = [15, 16, 17];

        for &size in &sizes {
            let mut buffer = vec![0xFF; size];
            let result = secure_erase_last_16_bytes(&mut buffer);

            if size < 16 {
                assert!(result.is_err());
                assert_eq!(result.unwrap_err(), "Buffer is too short");
                // Verify buffer was not modified
                for byte in buffer.iter() {
                    assert_eq!(*byte, 0xFF);
                }
            } else {
                assert!(result.is_ok());
                // Verify last chunk is zeroed
                for i in (buffer.len() - 16)..buffer.len() {
                    assert_eq!(buffer[i], 0);
                }
                // Verify beginning is untouched if buffer is larger than 16
                if size > 16 {
                    assert_eq!(buffer[0], 0xFF);
                }
            }
        }
    }

    #[test]
    fn test_large_buffer() {
        let mut buffer = vec![0xFF; 1024];

        // Fill with pattern
        for i in 0..buffer.len() {
            buffer[i] = (i % 256) as u8;
        }

        let result = secure_erase_last_16_bytes(&mut buffer);

        assert!(result.is_ok());

        // Verify only last 16 bytes are zeroed
        for i in 0..(buffer.len() - 16) {
            assert_eq!(buffer[i], (i % 256) as u8);
        }

        for i in (buffer.len() - 16)..buffer.len() {
            assert_eq!(buffer[i], 0);
        }
    }

    #[test]
    fn test_slice_of_larger_buffer() {
        let mut large_buffer = vec![0xFF; 100];

        // Fill with pattern
        for i in 0..large_buffer.len() {
            large_buffer[i] = i as u8;
        }

        // Test with slice from middle of buffer
        {
            let slice = &mut large_buffer[20..50];
            let result = secure_erase_last_16_bytes(slice);

            assert!(result.is_ok());

            // Verify untouched portion
            for i in 0..20 {
                assert_eq!(large_buffer[i], i as u8);
            }

            // Verify middle portion - first part untouched
            for i in 20..34 {
                assert_eq!(large_buffer[i], i as u8);
            }

            // Verify middle portion - last 16 bytes zeroed
            for i in 34..50 {
                assert_eq!(large_buffer[i], 0);
            }

            // Verify end untouched
            for i in 50..100 {
                assert_eq!(large_buffer[i], i as u8);
            }
        }
    }
}

