#[cfg(test)]
mod tests {
    use super::*;

    // Helper function to verify that the iterator produced by group_identical_readings
    // correctly groups identical consecutive elements
    fn verify_grouping(input: &mut [i32], expected_groups: Vec<&[i32]>) {
        let groups: Vec<Vec<i32>> = group_identical_readings(input)
            .map(|group| group.to_vec())
            .collect();

        assert_eq!(groups.len(), expected_groups.len(), "Wrong number of groups");

        for (i, (actual, expected)) in groups.iter().zip(expected_groups.iter()).enumerate() {
            assert_eq!(
                actual, expected,
                "Group {} doesn't match. Expected {:?}, got {:?}",
                i, expected, actual
            );
        }
    }

    #[test]
    fn test_empty_slice() {
        let mut empty: [i32; 0] = [];
        let groups: Vec<Vec<i32>> = group_identical_readings(&mut empty)
            .map(|group| group.to_vec())
            .collect();

        assert_eq!(groups.len(), 0, "Empty slice should produce no groups");
    }

    #[test]
    fn test_single_element() {
        let mut readings = [42];
        let groups: Vec<Vec<i32>> = group_identical_readings(&mut readings)
            .map(|group| group.to_vec())
            .collect();

        assert_eq!(groups.len(), 1, "Single element should produce one group");
        assert_eq!(groups[0], vec![42]);
    }

    #[test]
    fn test_all_identical() {
        let mut readings = [5, 5, 5, 5, 5];

        verify_grouping(&mut readings, vec![&[5, 5, 5, 5, 5]]);
    }

    #[test]
    fn test_all_different() {
        let mut readings = [1, 2, 3, 4, 5];

        verify_grouping(&mut readings, vec![&[1], &[2], &[3], &[4], &[5]]);
    }

    #[test]
    fn test_mixed_groups() {
        let mut readings = [1, 1, 2, 3, 3, 3, 4, 4, 5];

        verify_grouping(&mut readings, vec![&[1, 1], &[2], &[3, 3, 3], &[4, 4], &[5]]);
    }

    #[test]
    fn test_negative_values() {
        let mut readings = [-5, -5, -4, -3, -3, -2, -1];

        verify_grouping(&mut readings, vec![&[-5, -5], &[-4], &[-3, -3], &[-2], &[-1]]);
    }

    #[test]
    fn test_mutation_of_groups() {
        let mut readings = [10, 10, 20, 20, 20, 30];

        // Modify each group
        for group in group_identical_readings(&mut readings) {
            // Add 1 to each element in the group
            for value in group.iter_mut() {
                *value += 1;
            }
        }

        // Verify the modifications
        assert_eq!(readings, [11, 11, 21, 21, 21, 31]);
    }

    #[test]
    fn test_large_groups() {
        let mut readings = [0; 1000];
        // Fill with alternating blocks of 100 zeros and 100 ones
        for i in 0..10 {
            if i % 2 == 1 {
                for j in 0..100 {
                    readings[i * 100 + j] = 1;
                }
            }
        }

        // We should have 10 groups (5 of zeros, 5 of ones)
        let group_count = group_identical_readings(&mut readings).count();
        assert_eq!(group_count, 10);
    }

    #[test]
    fn test_edge_cases() {
        // Test with minimum and maximum i32 values
        let mut readings = [i32::MIN, i32::MIN, i32::MAX, i32::MAX, i32::MAX];

        verify_grouping(&mut readings, vec![&[i32::MIN, i32::MIN], &[i32::MAX, i32::MAX, i32::MAX]]);
    }
}

