use std::fs;
use std::io;
use std::path::{Path, PathBuf};

fn read_files_to_strings<P: AsRef<Path>>(dir_path: P) -> io::Result<Vec<String>> {
    let mut contents = Vec::new();
    for entry in fs::read_dir(dir_path)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_file() {
            let file_content = fs::read_to_string(path)?;
            contents.push(file_content);
        }
    }
    Ok(contents)
}

