#[cfg(test)]
mod tests {
    use super::*;
    use std::fs::{self, File};
    use std::io::{self, Write};
    use std::path::{Path, PathBuf};
    use std::env;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn create_temp_dir() -> io::Result<PathBuf> {
        // Replace rand with SystemTime to generate unique directory names
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos();
        let tmp_dir = env::temp_dir().join(format!("test_dir_{}", timestamp));
        fs::create_dir_all(&tmp_dir)?;
        Ok(tmp_dir)
    }

    fn cleanup_temp_dir(dir: &Path) -> io::Result<()> {
        fs::remove_dir_all(dir)
    }

    fn create_test_file(dir: &Path, filename: &str, content: &str) -> io::Result<PathBuf> {
        let file_path = dir.join(filename);
        let mut file = File::create(&file_path)?;
        file.write_all(content.as_bytes())?;
        Ok(file_path)
    }

    #[test]
    fn test_empty_directory() -> io::Result<()> {
        let temp_dir = create_temp_dir()?;
        let results = read_files_to_strings(&temp_dir)?;
        assert!(results.is_empty());
        cleanup_temp_dir(&temp_dir)?;
        Ok(())
    }

    #[test]
    fn test_single_file() -> io::Result<()> {
        let temp_dir = create_temp_dir()?;
        let content = "Hello, world!";
        create_test_file(&temp_dir, "test.txt", content)?;

        let results = read_files_to_strings(&temp_dir)?;

        assert_eq!(results.len(), 1);
        assert_eq!(results[0], content);
        cleanup_temp_dir(&temp_dir)?;
        Ok(())
    }

    #[test]
    fn test_multiple_files() -> io::Result<()> {
        let temp_dir = create_temp_dir()?;
        let contents = vec![
            ("file1.txt", "Content of file 1"),
            ("file2.txt", "Content of file 2"),
            ("file3.txt", "Content of file 3"),
        ];

        for (name, content) in &contents {
            create_test_file(&temp_dir, name, content)?;
        }

        let results = read_files_to_strings(&temp_dir)?;

        assert_eq!(results.len(), contents.len());
        // Sort both collections to ensure order-independent comparison
        let mut expected_contents: Vec<String> = contents.iter()
            .map(|(_, content)| content.to_string())
            .collect();
        expected_contents.sort();

        let mut actual_contents = results;
        actual_contents.sort();

        assert_eq!(actual_contents, expected_contents);
        cleanup_temp_dir(&temp_dir)?;
        Ok(())
    }

    #[test]
    fn test_mixed_content() -> io::Result<()> {
        let temp_dir = create_temp_dir()?;

        // Create a subdirectory (should be ignored)
        fs::create_dir(temp_dir.join("subdir"))?;

        // Create some files
        create_test_file(&temp_dir, "file1.txt", "Content 1")?;
        create_test_file(&temp_dir, "file2.txt", "Content 2")?;

        // Create a file in the subdirectory (should be ignored)
        create_test_file(&temp_dir.join("subdir"), "subfile.txt", "Sub content")?;

        let results = read_files_to_strings(&temp_dir)?;

        assert_eq!(results.len(), 2);
        let mut expected = vec!["Content 1".to_string(), "Content 2".to_string()];
        expected.sort();

        let mut actual = results;
        actual.sort();

        assert_eq!(actual, expected);
        cleanup_temp_dir(&temp_dir)?;
        Ok(())
    }

    #[test]
    fn test_empty_files() -> io::Result<()> {
        let temp_dir = create_temp_dir()?;
        create_test_file(&temp_dir, "empty.txt", "")?;
        create_test_file(&temp_dir, "nonempty.txt", "Some content")?;

        let results = read_files_to_strings(&temp_dir)?;

        assert_eq!(results.len(), 2);
        let mut expected = vec!["".to_string(), "Some content".to_string()];
        expected.sort();

        let mut actual = results;
        actual.sort();

        assert_eq!(actual, expected);
        cleanup_temp_dir(&temp_dir)?;
        Ok(())
    }

    #[test]
    fn test_large_file() -> io::Result<()> {
        let temp_dir = create_temp_dir()?;
        let large_content = "X".repeat(1_000_000); // 1MB of data
        create_test_file(&temp_dir, "large.txt", &large_content)?;

        let results = read_files_to_strings(&temp_dir)?;

        assert_eq!(results.len(), 1);
        assert_eq!(results[0].len(), large_content.len());
        assert_eq!(results[0], large_content);
        cleanup_temp_dir(&temp_dir)?;
        Ok(())
    }

    #[test]
    fn test_non_utf8_content() -> io::Result<()> {
        let temp_dir = create_temp_dir()?;
        let file_path = temp_dir.join("invalid_utf8.txt");

        // Create a file with invalid UTF-8 sequence
        {
            let mut file = File::create(&file_path)?;
            let invalid_utf8 = [0x80, 0x90, 0xA0, 0xB0, 0xC0]; // Invalid UTF-8 bytes
            file.write_all(&invalid_utf8)?;
        }

        // This should return an error
        let result = read_files_to_strings(&temp_dir);
        assert!(result.is_err());
        cleanup_temp_dir(&temp_dir)?;
        Ok(())
    }

    #[test]
    fn test_different_path_types() -> io::Result<()> {
        let temp_dir = create_temp_dir()?;
        create_test_file(&temp_dir, "test.txt", "Hello")?;

        // Test with different path types
        let path_buf = PathBuf::from(&temp_dir);
        let results_from_pathbuf = read_files_to_strings(path_buf.clone())?;
        assert_eq!(results_from_pathbuf.len(), 1);

        let path_str = temp_dir.to_str().unwrap();
        let results_from_str = read_files_to_strings(path_str)?;
        assert_eq!(results_from_str.len(), 1);

        // Test with a borrowed Path
        let path_ref: &Path = temp_dir.as_path();
        let results_from_path = read_files_to_strings(path_ref)?;
        assert_eq!(results_from_path.len(), 1);

        cleanup_temp_dir(&temp_dir)?;
        Ok(())
    }

    #[test]
    fn test_nonexistent_directory() {
        let result = read_files_to_strings("/nonexistent/directory/path");
        assert!(result.is_err());
    }
}

