#[cfg(test)]
mod tests {
    use super::*;
    use std::num::NonZeroU64;

    #[test]
    fn test_basic_multiplication() {
        // Basic multiplication with small numbers
        let a = NonZeroU64::new(5).unwrap();
        let b = NonZeroU64::new(7).unwrap();
        let result = safe_nonzero_mul(a, b);
        assert_eq!(result, Some(NonZeroU64::new(35).unwrap()));
    }

    #[test]
    fn test_multiplication_with_one() {
        // Multiplication with 1 should return the other number
        let a = NonZeroU64::new(42).unwrap();
        let b = NonZeroU64::new(1).unwrap();
        let result = safe_nonzero_mul(a, b);
        assert_eq!(result, Some(a));
    }

    #[test]
    fn test_large_numbers_within_bounds() {
        // Test with large numbers that don't overflow
        let a = NonZeroU64::new(1_000_000_000).unwrap(); // 10^9
        let b = NonZeroU64::new(1_000_000).unwrap();     // 10^6
        let result = safe_nonzero_mul(a, b);
        assert_eq!(result, Some(NonZeroU64::new(1_000_000_000_000_000).unwrap())); // 10^15
    }

    #[test]
    fn test_overflow_handling() {
        // Test with numbers that will overflow u64
        let a = NonZeroU64::new(u64::MAX).unwrap();
        let b = NonZeroU64::new(2).unwrap();
        let result = safe_nonzero_mul(a, b);
        assert_eq!(result, None);
    }

    #[test]
    fn test_max_value_edge_case() {
        // Test with max value and 1
        let a = NonZeroU64::new(u64::MAX).unwrap();
        let b = NonZeroU64::new(1).unwrap();
        let result = safe_nonzero_mul(a, b);
        assert_eq!(result, Some(a));
    }

    #[test]
    fn test_commutative_property() {
        // Test that a * b == b * a
        let a = NonZeroU64::new(123).unwrap();
        let b = NonZeroU64::new(456).unwrap();
        let result1 = safe_nonzero_mul(a, b);
        let result2 = safe_nonzero_mul(b, a);
        assert_eq!(result1, result2);
    }

    #[test]
    fn test_near_overflow_boundary() {
        // Test numbers just below the overflow boundary
        let a = NonZeroU64::new(u64::MAX / 2).unwrap();
        let b = NonZeroU64::new(2).unwrap();
        let result = safe_nonzero_mul(a, b);
        assert_eq!(result, Some(NonZeroU64::new(u64::MAX - 1).unwrap()));

        // Test numbers just above the overflow boundary
        let a = NonZeroU64::new(u64::MAX / 2 + 1).unwrap();
        let b = NonZeroU64::new(2).unwrap();
        let result = safe_nonzero_mul(a, b);
        assert_eq!(result, None);
    }

    #[test]
    fn test_sqrt_max_boundary() {
        // Test with sqrt(u64::MAX)
        let sqrt_max = 4_294_967_295; // Approximate sqrt of u64::MAX
        let a = NonZeroU64::new(sqrt_max).unwrap();

        // a * a should be close to u64::MAX but not overflow
        let result1 = safe_nonzero_mul(a, a);
        assert!(result1.is_some());

        // a * (a+1) should overflow
        let b = NonZeroU64::new(sqrt_max + 1).unwrap();
        let result2 = safe_nonzero_mul(a, b);
        // This test was incorrect - the multiplication doesn't overflow
        // sqrt_max * (sqrt_max + 1) = 4_294_967_295 * 4_294_967_296 = 18_446_744_069_414_584_320
        // which is < u64::MAX (18_446_744_073_709_551_615)
        assert!(result2.is_some());
    }
}

