    use super::*;

    #[test]
    fn test_safe_split_at_valid_mid() {
        let slice = [1, 2, 3, 4, 5];

        // Split at the beginning
        let result = safe_split_at(&slice, 0);
        assert!(result.is_some());
        let (left, right) = result.unwrap();
        assert_eq!(left, &[]);
        assert_eq!(right, &[1, 2, 3, 4, 5]);

        // Split in the middle
        let result = safe_split_at(&slice, 2);
        assert!(result.is_some());
        let (left, right) = result.unwrap();
        assert_eq!(left, &[1, 2]);
        assert_eq!(right, &[3, 4, 5]);

        // Split at the end
        let result = safe_split_at(&slice, 5);
        assert!(result.is_some());
        let (left, right) = result.unwrap();
        assert_eq!(left, &[1, 2, 3, 4, 5]);
        assert_eq!(right, &[]);
    }

