    fn test_safe_split_at_invalid_mid() {
        let slice = [1, 2, 3, 4, 5];

        // Index beyond the end
        let result = safe_split_at(&slice, 6);
        assert!(result.is_none());

        // Far beyond the end
        let result = safe_split_at(&slice, usize::MAX);
        assert!(result.is_none());
    }

