use std::pin::Pin;
use std::cmp::Ordering;
use std::ops::Deref;

fn sort_pinned_refs<T, P>(refs: &mut [Pin<P>]) -> Result<(), &'static str>
where
    P: Deref<Target = T>,
    T: PartialOrd + ?Sized,
{
    refs.sort_by(|a, b| {
        a.partial_cmp(b).unwrap_or(Ordering::Equal)
    });
    Ok(())
}

