#[cfg(test)]
mod tests {
    use std::cmp::Ordering;
    use std::pin::Pin;
    use std::ops::Deref;

    // Import the function we're testing
    use super::sort_pinned_refs;

    // Simple struct that implements PartialOrd
    #[derive(Debug, Clone, PartialEq)]
    struct TestStruct {
        value: Option<i32>, // Can be None to test partial ordering
    }

    // Custom implementation of PartialOrd that demonstrates partially ordered values
    impl PartialOrd for TestStruct {
        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
            match (self.value, other.value) {
                (Some(a), Some(b)) => a.partial_cmp(&b),
                (None, None) => Some(Ordering::Equal),
                // Return None when comparing Some with None to demonstrate partial ordering
                _ => None,
            }
        }
    }

    // A wrapper struct to implement Deref
    #[derive(Debug)]
    struct TestRef(TestStruct);

    impl Deref for TestRef {
        type Target = TestStruct;

        fn deref(&self) -> &Self::Target {
            &self.0
        }
    }

    #[test]
    fn test_sort_pinned_refs_with_comparable_values() {
        // Create an array of pinned references with comparable values
        let mut pinned_refs = [
            Pin::new(TestRef(TestStruct { value: Some(5) })),
            Pin::new(TestRef(TestStruct { value: Some(3) })),
            Pin::new(TestRef(TestStruct { value: Some(8) })),
            Pin::new(TestRef(TestStruct { value: Some(1) })),
        ];

        // Sort the array
        let result = sort_pinned_refs(&mut pinned_refs);

        // Assert that sorting was successful
        assert!(result.is_ok());

        // Check that the array is sorted in ascending order
        let values: Vec<_> = pinned_refs.iter().map(|p| p.value.unwrap()).collect();
        assert_eq!(values, vec![1, 3, 5, 8]);
    }

    #[test]
    fn test_sort_pinned_refs_with_partially_ordered_values() {
        // Create an array with some incomparable values (None)
        let mut pinned_refs = [
            Pin::new(TestRef(TestStruct { value: Some(5) })),
            Pin::new(TestRef(TestStruct { value: None })),
            Pin::new(TestRef(TestStruct { value: Some(3) })),
            Pin::new(TestRef(TestStruct { value: None })),
        ];

        // Sort the array
        let result = sort_pinned_refs(&mut pinned_refs);

        // Assert that sorting was successful even with partially ordered values
        assert!(result.is_ok());

        // Check that comparable values are sorted
        // Note: The None values will be placed somewhere in the array based on the 
        // unwrap_or(Ordering::Equal) in the sort function
        let values: Vec<_> = pinned_refs.iter()
            .map(|p| p.value)
            .collect();

        // Find the positions of Some values and ensure they're in order relative to each other
        let some_values: Vec<_> = values.iter()
            .filter_map(|&v| v)
            .collect();
        assert!(some_values == vec![3, 5] || some_values == vec![5, 3]);
    }

    #[test]
    fn test_sort_pinned_refs_empty_slice() {
        // Test with an empty slice
        let mut empty_slice: [Pin<TestRef>; 0] = [];

        let result = sort_pinned_refs(&mut empty_slice);

        // Should succeed with empty slice
        assert!(result.is_ok());
    }

    #[test]
    fn test_sort_pinned_refs_single_element() {
        // Test with a single element
        let mut single_element = [
            Pin::new(TestRef(TestStruct { value: Some(42) })),
        ];

        let result = sort_pinned_refs(&mut single_element);

        // Should succeed with a single element
        assert!(result.is_ok());
        assert_eq!(single_element[0].value, Some(42));
    }

    #[test]
    fn test_sort_pinned_refs_all_equal() {
        // Test with all equal elements
        let mut equal_elements = [
            Pin::new(TestRef(TestStruct { value: Some(10) })),
            Pin::new(TestRef(TestStruct { value: Some(10) })),
            Pin::new(TestRef(TestStruct { value: Some(10) })),
        ];

        let result = sort_pinned_refs(&mut equal_elements);

        // Should succeed with equal elements
        assert!(result.is_ok());

        // All elements should still be equal
        for element in &equal_elements {
            assert_eq!(element.value, Some(10));
        }
    }

    #[test]
    fn test_sort_pinned_refs_all_incomparable() {
        // Test with all incomparable elements (None values)
        let mut all_none = [
            Pin::new(TestRef(TestStruct { value: None })),
            Pin::new(TestRef(TestStruct { value: None })),
            Pin::new(TestRef(TestStruct { value: None })),
        ];

        let result = sort_pinned_refs(&mut all_none);

        // Should succeed even with all incomparable elements
        assert!(result.is_ok());

        // Verify all elements are still None
        for element in &all_none {
            assert_eq!(element.value, None);
        }
    }

    #[test]
    fn test_sort_pinned_refs_already_sorted() {
        // Test with already sorted elements
        let mut already_sorted = [
            Pin::new(TestRef(TestStruct { value: Some(1) })),
            Pin::new(TestRef(TestStruct { value: Some(2) })),
            Pin::new(TestRef(TestStruct { value: Some(3) })),
        ];

        let result = sort_pinned_refs(&mut already_sorted);

        // Should succeed with already sorted elements
        assert!(result.is_ok());

        // Verify the order is maintained
        let values: Vec<_> = already_sorted.iter().map(|p| p.value.unwrap()).collect();
        assert_eq!(values, vec![1, 2, 3]);
    }

    #[test]
    fn test_sort_pinned_refs_reverse_order() {
        // Test with elements in reverse order
        let mut reverse_order = [
            Pin::new(TestRef(TestStruct { value: Some(5) })),
            Pin::new(TestRef(TestStruct { value: Some(4) })),
            Pin::new(TestRef(TestStruct { value: Some(3) })),
            Pin::new(TestRef(TestStruct { value: Some(2) })),
            Pin::new(TestRef(TestStruct { value: Some(1) })),
        ];

        let result = sort_pinned_refs(&mut reverse_order);

        // Should succeed with reverse order elements
        assert!(result.is_ok());

        // Verify they are now in correct order
        let values: Vec<_> = reverse_order.iter().map(|p| p.value.unwrap()).collect();
        assert_eq!(values, vec![1, 2, 3, 4, 5]);
    }
}

