#[cfg(test)]
mod tests {
    use std::pin::Pin;
    use std::marker::PhantomPinned;
    use super::pin_mut_ref;

    // A simple struct that is !Unpin
    struct TestStruct {
        data: u32,
        _pin: PhantomPinned,
    }

    impl TestStruct {
        fn new(data: u32) -> Self {
            TestStruct {
                data,
                _pin: PhantomPinned,
            }
        }

        fn get_data(self: Pin<&mut Self>) -> &mut u32 {
            unsafe {
                let this = self.get_unchecked_mut();
                &mut this.data
            }
        }
    }

    #[test]
    fn test_pin_mut_ref() {
        let mut test_struct = TestStruct::new(42);

        // Pin the mutable reference
        let mut pinned = pin_mut_ref(&mut test_struct);

        // Verify we can use it with methods requiring Pin<&mut T>
        assert_eq!(*pinned.as_mut().get_data(), 42);

        // Modify through the pin
        *pinned.as_mut().get_data() = 100;
        assert_eq!(*pinned.as_mut().get_data(), 100);
    }

    #[test]
    fn test_pin_mut_ref_preserves_pinning() {
        let mut data = 10;
        let pinned = pin_mut_ref(&mut data);

        // This would fail to compile if pinning wasn't preserved
        // as Pin<&mut T> can't be dereferenced directly
        // We need to use as_mut() or get_mut() to access the value
        assert_eq!(*Pin::into_inner(pinned), 10);
    }
}

