#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Cursor;

    struct MockReader {
        data: Vec<u8>,
        read_index: usize,
    }

    impl MockReader {
        fn new(data: Vec<u8>) -> Self {
            MockReader {
                data,
                read_index: 0,
            }
        }
    }

    impl Read for MockReader {
        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
            if buf.is_empty() {
                return Ok(0);
            }

            let mut bytes_read = 0;
            for (i, byte) in buf.iter_mut().enumerate() {
                *byte = self.data[self.read_index % self.data.len()];
                self.read_index += 1;
                bytes_read = i + 1;
            }
            Ok(bytes_read)
        }
    }

    #[test]
    fn test_empty_buffers() {
        let mut source = Cursor::new(vec![1, 2, 3, 4, 5]);
        let mut buffers: Vec<IoSliceMut<'_>> = Vec::new();

        let result = read_repeated_data_into_buffers(&mut source, &mut buffers);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 0);
    }

    #[test]
    fn test_single_buffer() {
        let mut source = Cursor::new(vec![1, 2, 3, 4, 5]);
        let mut buffer = [0u8; 3];
        let mut buffers = [IoSliceMut::new(&mut buffer)];

        let result = read_repeated_data_into_buffers(&mut source, &mut buffers);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 3);
        assert_eq!(buffer, [1, 2, 3]);
    }

    #[test]
    fn test_multiple_buffers() {
        let mut source = Cursor::new(vec![1, 2, 3, 4, 5]);
        let mut buffer1 = [0u8; 2];
        let mut buffer2 = [0u8; 2];
        let mut buffers = [
            IoSliceMut::new(&mut buffer1),
            IoSliceMut::new(&mut buffer2),
        ];

        let result = read_repeated_data_into_buffers(&mut source, &mut buffers);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 4);
        assert_eq!(buffer1, [1, 2]);
        assert_eq!(buffer2, [3, 4]);
    }

    #[test]
    fn test_exact_buffer_size() {
        let mut source = Cursor::new(vec![1, 2, 3, 4, 5]);
        let mut buffer = [0u8; 5];
        let mut buffers = [IoSliceMut::new(&mut buffer)];

        let result = read_repeated_data_into_buffers(&mut source, &mut buffers);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 5);
        assert_eq!(buffer, [1, 2, 3, 4, 5]);
    }

    #[test]
    fn test_incomplete_read() {
        let mut source = Cursor::new(vec![1, 2, 3]);
        let mut buffer = [0u8; 5];
        let mut buffers = [IoSliceMut::new(&mut buffer)];

        let result = read_repeated_data_into_buffers(&mut source, &mut buffers);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 3);
        assert_eq!(buffer[0..3], [1, 2, 3]);
    }

    #[test]
    fn test_infinite_source() {
        let mut source = MockReader::new(vec![1, 2, 3]);
        let mut buffer1 = [0u8; 4];
        let mut buffer2 = [0u8; 4];
        let mut buffers = [
            IoSliceMut::new(&mut buffer1),
            IoSliceMut::new(&mut buffer2),
        ];

        let result = read_repeated_data_into_buffers(&mut source, &mut buffers);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 8);
        assert_eq!(buffer1, [1, 2, 3, 1]);
        assert_eq!(buffer2, [2, 3, 1, 2]);
    }

    #[test]
    fn test_read_into_partially_filled_buffers() {
        let mut source = Cursor::new(vec![1, 2, 3, 4, 5]);
        let mut buffer1 = [99u8; 2];
        let mut buffer2 = [99u8; 2];
        let mut buffers = [
            IoSliceMut::new(&mut buffer1),
            IoSliceMut::new(&mut buffer2),
        ];

        let result = read_repeated_data_into_buffers(&mut source, &mut buffers);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 4);
        assert_eq!(buffer1, [1, 2]);
        assert_eq!(buffer2, [3, 4]);
    }

    #[test]
    fn test_read_error() {
        struct ErrorReader;

        impl Read for ErrorReader {
            fn read(&mut self, _buf: &mut [u8]) -> io::Result<usize> {
                Err(io::Error::new(io::ErrorKind::Other, "mock error"))
            }
        }

        let mut source = ErrorReader;
        let mut buffer = [0u8; 5];
        let mut buffers = [IoSliceMut::new(&mut buffer)];

        let result = read_repeated_data_into_buffers(&mut source, &mut buffers);
        assert!(result.is_err());
    }

    #[test]
    fn test_zero_length_buffers() {
        let mut source = Cursor::new(vec![1, 2, 3, 4, 5]);
        let mut buffer1 = [0u8; 0];
        let mut buffer2 = [0u8; 2];
