use std::collections::HashMap;
use std::hash::Hash;

fn drain_to_vec<K: Eq + Hash, V>(map: &mut HashMap<K, V>) -> Vec<(K, V)> {
    let mut vec = Vec::with_capacity(map.len());
    let mut drain = map.drain();
    while let Some(pair) = drain.next() {
        vec.push(pair);
    }
    vec
}

