#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    #[test]
    fn test_drain_to_vec_empty() {
        let mut map: HashMap<i32, String> = HashMap::new();
        let vec = drain_to_vec(&mut map);
        assert!(vec.is_empty());
        assert!(map.is_empty());
    }

    #[test]
    fn test_drain_to_vec_single_element() {
        let mut map = HashMap::new();
        map.insert(42, "answer".to_string());

        let vec = drain_to_vec(&mut map);

        assert_eq!(vec.len(), 1);
        assert!(vec.contains(&(42, "answer".to_string())));
        assert!(map.is_empty());
    }

    #[test]
    fn test_drain_to_vec_multiple_elements() {
        let mut map = HashMap::new();
        map.insert(1, "one".to_string());
        map.insert(2, "two".to_string());
        map.insert(3, "three".to_string());

        let vec = drain_to_vec(&mut map);

        assert_eq!(vec.len(), 3);
        assert!(vec.contains(&(1, "one".to_string())));
        assert!(vec.contains(&(2, "two".to_string())));
        assert!(vec.contains(&(3, "three".to_string())));
        assert!(map.is_empty());
    }

    #[test]
    fn test_drain_to_vec_with_custom_types() {
        #[derive(PartialEq, Eq, Hash, Debug)]
        struct CustomKey {
            id: u32,
        }

        #[derive(PartialEq, Debug)]
        struct CustomValue {
            data: String,
        }

        let mut map = HashMap::new();
        map.insert(
            CustomKey { id: 1 },
            CustomValue { data: "first".to_string() }
        );
        map.insert(
            CustomKey { id: 2 },
            CustomValue { data: "second".to_string() }
        );

        let vec = drain_to_vec(&mut map);

        assert_eq!(vec.len(), 2);
        assert!(vec.iter().any(|(k, v)| k.id == 1 && v.data == "first"));
        assert!(vec.iter().any(|(k, v)| k.id == 2 && v.data == "second"));
        assert!(map.is_empty());
    }

    #[test]
    fn test_drain_to_vec_capacity() {
        let mut map = HashMap::new();
        for i in 0..100 {
            map.insert(i, i.to_string());
        }

        let original_size = map.len();
        let vec = drain_to_vec(&mut map);

        assert_eq!(vec.len(), original_size);
        assert!(map.is_empty());
    }

    #[test]
    fn test_original_map_emptied() {
        let mut map = HashMap::new();
        map.insert("key1", 1);
        map.insert("key2", 2);

        let _vec = drain_to_vec(&mut map);

        assert!(map.is_empty());
        assert_eq!(map.len(), 0);

        // Verify we can reuse the map
        map.insert("new_key", 42);
        assert_eq!(map.len(), 1);
        assert_eq!(map.get("new_key"), Some(&42));
    }
}

