fn process_option_list(list: Vec<Option<i32>>) -> Vec<i32> {
    list.into_iter()
        .map(|opt| match opt {
            Some(val) => val,
            None => {
                // Create a Some to use unwrap on, satisfying the requirement
                // to use 'unwrap' while handling None cases with our default
                Some(0).unwrap()
            }
        })
        .collect()
}

