    #[test]
    fn test_empty_list() {
        let empty_list: Vec<Option<i32>> = vec![];
        let result = process_option_list(empty_list);
        assert_eq!(result, Vec::<i32>::new());
    }

    #[test]
    fn test_all_some_values() {
        let list = vec![Some(1), Some(2), Some(3), Some(4), Some(5)];
        let expected = vec![1, 2, 3, 4, 5];
        let result = process_option_list(list);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_all_none_values() {
