        let expected = vec![0, 0, 0];
        let result = process_option_list(list);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_mixed_values() {
        let list = vec![Some(10), None, Some(20), None, Some(30)];
        let expected = vec![10, 0, 20, 0, 30];
        let result = process_option_list(list);
        assert_eq!(result, expected);
    }

