    fn test_large_list() {
        // Create a large list with alternating Some and None values
        let mut large_list = Vec::with_capacity(1000);
        let mut expected = Vec::with_capacity(1000);

        for i in 0..1000 {
            if i % 2 == 0 {
                large_list.push(Some(i));
                expected.push(i);
            } else {
                large_list.push(None);
                expected.push(0);
            }
        }

        let result = process_option_list(large_list);
        assert_eq!(result, expected);
    }

