    fn test_edge_cases() {
        let list = vec![Some(i32::MAX), None, Some(i32::MIN)];
        let expected = vec![i32::MAX, 0, i32::MIN];
        let result = process_option_list(list);
        assert_eq!(result, expected);
    }
}

