use std::io::{self, Write, Stdout, StdoutLock};

fn write_to_stdout(message: &str) -> io::Result<()> {
    let stdout = io::stdout();
    let mut handle = stdout.lock();
    handle.write_all(message.as_bytes())?;
    handle.flush()
}

