use std::sync::{PoisonError, MutexGuard};
use std::fmt;

fn handle_poisoned_lock<T>(guard: T, context: &str) -> Result<(), String>
where
    T: fmt::Debug,
{
    let poison_error = PoisonError::new(guard);
    let error_message = format!("Poisoned lock detected in context: {}. Error: {:?}", context, poison_error);
    Err(error_message)
}

