        // Create a mutex that will be poisoned
        let mutex = Arc::new(Mutex::new(TestData { value: 10 }));
        let mutex_clone = Arc::clone(&mutex);

        // Spawn a thread that will panic while holding the lock
        let handle = thread::spawn(move || {
            let _guard = mutex_clone.lock().unwrap();
            panic!("Intentional panic to poison the mutex");
        });

        // Wait for the thread to complete (and panic)
        let _ = handle.join();

        // Now the mutex should be poisoned
        let mutex_result = mutex.lock();
        match mutex_result {
            Ok(_) => panic!("Mutex should be poisoned"),
            Err(poison_error) => {
                let context = "mutex guard test";
                let guard = poison_error.into_inner();

                let result = handle_poisoned_lock(guard, context);

                assert!(result.is_err());
                let error_msg = result.unwrap_err();
                assert!(error_msg.contains("mutex guard test"));
                assert!(error_msg.contains("Poisoned lock detected in context"));
            }
        }
    }

