        let result = handle_poisoned_lock(string_data, "string context");
        assert!(result.is_err());
        assert!(result.unwrap_err().contains("string context"));

        // Test with a Vec
        let vec_data = vec![1, 2, 3];
        let result = handle_poisoned_lock(vec_data, "vector context");
        assert!(result.is_err());
        assert!(result.unwrap_err().contains("vector context"));

        // Test with a tuple
        let tuple_data = (42, "test", true);
        let result = handle_poisoned_lock(tuple_data, "tuple context");
        assert!(result.is_err());
        assert!(result.unwrap_err().contains("tuple context"));
    }

    #[test]
    fn test_handle_poisoned_lock_empty_context() {
        // Test with an empty context string
        let test_data = TestData { value: 100 };
        let result = handle_poisoned_lock(test_data, "");

        assert!(result.is_err());
        let error_msg = result.unwrap_err();
        assert!(error_msg.contains("Poisoned lock detected in context: "));
    }

    #[test]
    fn test_actual_poison_error() {
        // Create a real PoisonError and test with it
        let mutex = Arc::new(Mutex::new(TestData { value: 20 }));
        let mutex_clone = Arc::clone(&mutex);

        // Spawn a thread that will panic while holding the lock
        let handle = thread::spawn(move || {
            let mut guard = mutex_clone.lock().unwrap();
            guard.value += 1;
            panic!("Intentional panic to poison the mutex");
        });

        // Wait for the thread to complete (and panic)
        let _ = handle.join();

        // Now test our function with the poisoned mutex
        let poison_error = mutex.lock().expect_err("Expected poisoned mutex");
        let guard = poison_error.into_inner();

        // Verify the value was changed before the panic
        assert_eq!(guard.value, 21);

