use std::sync::{Arc, atomic::{AtomicBool, Ordering}};
use std::thread;

fn wait_for_signal(flag: Arc<AtomicBool>) -> Result<(), Box<dyn std::error::Error>> {
    let thread_handle = thread::current();
    while !flag.load(Ordering::Acquire) {
        thread::park();
    }
    Ok(())
}

