#[cfg(test)]
mod tests {
    use std::sync::{Arc, atomic::{AtomicBool, Ordering}};
    use std::thread;
    use std::time::Duration;

    use super::wait_for_signal;

    #[test]
    fn test_wait_for_signal_immediate() {
        // Test that function returns immediately when flag is already set
        let flag = Arc::new(AtomicBool::new(true));
        let result = wait_for_signal(flag);
        assert!(result.is_ok());
    }

    #[test]
    fn test_wait_for_signal_from_another_thread() {
        // Test that function blocks until flag is set by another thread
        let flag = Arc::new(AtomicBool::new(false));
        let flag_clone = Arc::clone(&flag);

        let handle = thread::current();
        let waiter_thread = thread::spawn(move || {
            // Short delay to ensure waiter thread is blocked
            thread::sleep(Duration::from_millis(50));

            // Set the flag and unpark the main thread
            flag_clone.store(true, Ordering::Release);
            handle.unpark();

            // Give the main thread time to wake up
            thread::sleep(Duration::from_millis(50));
        });

        // This should block until the other thread sets the flag
        let result = wait_for_signal(Arc::clone(&flag));

        waiter_thread.join().unwrap();
        assert!(result.is_ok());
        assert!(flag.load(Ordering::Acquire));
    }

    #[test]
    fn test_spurious_wakeup() {
        // Test that function handles spurious wake-ups correctly
        let flag = Arc::new(AtomicBool::new(false));
        let flag_clone = Arc::clone(&flag);

        let handle = thread::current();
        let unparker_thread = thread::spawn(move || {
            // Short delay before first unpark
            thread::sleep(Duration::from_millis(50));

            // Cause a spurious wake-up by unparking without setting the flag
            handle.unpark();

            // Wait a bit more before setting the flag
            thread::sleep(Duration::from_millis(100));

            // Now set the flag and unpark again
            flag_clone.store(true, Ordering::Release);
            handle.unpark();
        });

        // This should block until the flag is actually set, even with spurious wake-ups
        let result = wait_for_signal(Arc::clone(&flag));

        unparker_thread.join().unwrap();
        assert!(result.is_ok());
        assert!(flag.load(Ordering::Acquire));
    }

    #[test]
    fn test_multiple_waiters() {
        // Test that multiple threads can wait on the same signal
        let flag = Arc::new(AtomicBool::new(false));

        let mut waiter_threads = vec![];
        let num_waiters = 5;

        // Store thread handles so we can unpark them
        let mut handles = vec![];

        for _ in 0..num_waiters {
            let flag_clone = Arc::clone(&flag);
            let (tx, rx) = std::sync::mpsc::channel();

            let waiter = thread::spawn(move || {
                // Send the thread handle to the main thread
                let handle = thread::current();
                tx.send(handle).unwrap();

                let result = wait_for_signal(flag_clone);
                assert!(result.is_ok());
            });

            // Collect the thread handle
            handles.push(rx.recv().unwrap());
            waiter_threads.push(waiter);
        }

        // Give the waiter threads time to start and block
        thread::sleep(Duration::from_millis(100));

        // Signal all waiters
        flag.store(true, Ordering::Release);

        // Unpark all waiters
        for handle in handles {
            handle.unpark();
        }

        // Wait for all waiter threads to complete
        for waiter in waiter_threads {
            waiter.join().unwrap();
        }

        assert!(flag.load(Ordering::Acquire));
    }

    #[test]
    fn test_flag_toggling() {
        // Test behavior when flag is toggled multiple times
        let flag = Arc::new(AtomicBool::new(false));
        let flag_clone = Arc::clone(&flag);

        let handle = thread::current();
        let toggler_thread = thread::spawn(move || {
            // Toggle flag a few times
            for _ in 0..3 {
                thread::sleep(Duration::from_millis(50));
                flag_clone.store(true, Ordering::Release);
                thread::sleep(Duration::from_millis(50));
                flag_clone.store(false, Ordering::Release);
            }

            // Finally set it to true and unpark
            thread::sleep(Duration::from_millis(50));
            flag_clone.store(true, Ordering::Release);
            handle.unpark();
        });

        // Should only return when flag is finally set to true
        let result = wait_for_signal(Arc::clone(&flag));

        toggler_thread.join().unwrap();
        assert!(result.is_ok());
        assert!(flag.load(Ordering::Acquire));
    }
}

