pub unsafe fn create_mutable_slice<'a, T>(data: *mut T, len: usize) -> &'a mut [T] {
    // Check that the pointer is aligned and non-null
    assert!(!data.is_null(), "pointer must not be null");
    assert!(
        (data as usize) % std::mem::align_of::<T>() == 0,
        "pointer must be aligned"
    );

    // Check that the total size doesn't exceed isize::MAX
    if len > 0 {
        assert!(
            len <= isize::MAX as usize / std::mem::size_of::<T>(),
            "total size must not exceed isize::MAX"
        );
    }

    // SAFETY: We've verified the preconditions that:
    // - The pointer is aligned and non-null
    // - The total size of the slice doesn't exceed isize::MAX
    unsafe { core::slice::from_raw_parts_mut(data, len) }
}

