        let ptr = data.as_mut_ptr();
        let len = data.len();

        // SAFETY: ptr is valid for len elements and we don't use data while the slice exists
        let slice = unsafe { create_mutable_slice(ptr, len) };

        assert_eq!(slice, &mut [1, 2, 3, 4, 5]);

        // Modify through the slice to verify mutability
        slice[0] = 10;
