fn process_options<T>(options: Vec<Option<T>>) -> Vec<T> {
    // Create a new vector with reserved capacity
    let mut result = Vec::with_capacity(options.len());

    for option in options {
        // SAFETY: We assume that all Option<T> values are guaranteed to be Some by the caller,
        // as specified in the requirements. This avoids unnecessary checks for performance.
        unsafe {
            result.push(option.unwrap_unchecked());
        }
    }

    result
}

