        let boxed_error = convert_to_boxed_error(static_message);

        // Check that the error message is preserved
        assert_eq!(boxed_error.to_string(), "static error message");
    }

    #[test]
    fn test_owned_string_conversion() {
        // Test with an owned string
        let owned_message = Cow::Owned(String::from("owned error message"));
        let boxed_error = convert_to_boxed_error(owned_message);

        // Check that the error message is preserved
        assert_eq!(boxed_error.to_string(), "owned error message");
    }

