        // This test ensures the lifetime of the error is preserved
        // by using the boxed error in a function that requires the same lifetime

        fn use_error<'a>(error: Box<dyn Error + 'a>) -> &'a str {
            error.to_string().leak() // Not ideal in production, but works for testing
        }

        let static_message = Cow::Borrowed("lifetime test");
        let boxed_error = convert_to_boxed_error(static_message);
        let result = use_error(boxed_error);

        assert_eq!(result, "lifetime test");
    }

    #[test]
