        let long_message = Cow::Owned("This is a much longer error message that contains multiple words and might trigger different behavior in certain implementations. It's important to test edge cases like this to ensure robustness.".to_string());
        let boxed_error = convert_to_boxed_error(long_message);

        assert!(boxed_error.to_string().contains("longer error message"));
        assert!(boxed_error.to_string().contains("edge cases"));
    }

    #[test]
    fn test_empty_message() {
