use std::mem;

unsafe fn copy_memory<T>(src: *const T, dst: *mut T, count: usize) -> Result<(), &'static str> {
    if src.is_null() || dst.is_null() {
        return Err("Null pointer");
    }

    if count == 0 || mem::size_of::<T>() == 0 {
        return Ok(());
    }

    let align = mem::align_of::<T>();
    if (src as usize) % align != 0 || (dst as usize) % align != 0 {
        return Err("Unaligned pointer");
    }

    std::ptr::copy(src, dst, count);
    Ok(())
}

