    use std::mem;

    #[test]
    fn test_null_pointer() {
        let null_ptr: *mut i32 = std::ptr::null_mut();
        assert_eq!(verify_alignment(null_ptr), false);
    }

    #[test]
    fn test_aligned_i32() {
        let mut value: i32 = 42;
        let ptr: *mut i32 = &mut value;
        assert_eq!(verify_alignment(ptr), true);
    }

    #[test]
    fn test_aligned_u8() {
        let mut value: u8 = 42;
        let ptr: *mut u8 = &mut value;
        assert_eq!(verify_alignment(ptr), true);
    }

    #[test]
    fn test_aligned_large_struct() {
        #[repr(C)]
        struct LargeStruct {
            a: i64,
            b: i64,
            c: i64,
        }

        let mut value = LargeStruct { a: 1, b: 2, c: 3 };
        let ptr: *mut LargeStruct = &mut value;
        assert_eq!(verify_alignment(ptr), true);
    }

    #[test]
    fn test_aligned_custom_struct() {
        struct CustomStruct {
            x: i32,
            y: i32,
        }

        let mut value = CustomStruct { x: 10, y: 20 };
        let ptr: *mut CustomStruct = &mut value;
        assert_eq!(verify_alignment(ptr), true);
    }

    #[test]
    fn test_unaligned_pointer() {
        // Create an unaligned pointer by taking a pointer to a byte within a larger aligned value
        let mut value: u64 = 0xFFFFFFFFFFFFFFFF;
        let base_ptr = &mut value as *mut u64;

        // Convert to a u8 pointer and offset by 1 byte to create misalignment for a u16
        let u8_ptr = base_ptr as *mut u8;
        let offset_ptr = unsafe { u8_ptr.add(1) };

        // Convert back to a u16 pointer, which should now be unaligned
        let unaligned_ptr = offset_ptr as *mut u16;

        // Test that the unaligned pointer is detected
        assert_eq!(verify_alignment(unaligned_ptr), false);
    }

    #[test]
    fn test_alignment_with_boxed_values() {
        let mut boxed_value = Box::new(42i32);
        let ptr: *mut i32 = &mut *boxed_value;
        assert_eq!(verify_alignment(ptr), true);
    }

