mod tests {
    use super::*;
    use std::alloc::{alloc, dealloc, Layout};
    use std::ptr::NonNull;

    #[test]
    fn test_aligned_pointers() {
        // Test with u8 (alignment 1)
        let layout = Layout::new::<u8>();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };
        assert!(is_pointer_aligned(ptr));
        unsafe { dealloc(ptr.as_ptr(), layout); }

        // Test with u16 (alignment 2)
        let layout = Layout::new::<u16>();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };
        assert!(is_pointer_aligned(ptr));
        unsafe { dealloc(ptr.as_ptr(), layout); }

        // Test with u32 (alignment 4)
        let layout = Layout::new::<u32>();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };
        assert!(is_pointer_aligned(ptr));
        unsafe { dealloc(ptr.as_ptr(), layout); }

        // Test with u64 (alignment 8)
        let layout = Layout::new::<u64>();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };
        assert!(is_pointer_aligned(ptr));
        unsafe { dealloc(ptr.as_ptr(), layout); }
    }

    #[test]
    fn test_custom_struct_alignment() {
        // Define a struct with explicit alignment
        #[repr(align(16))]
        struct Aligned16Bytes {
            data: [u8; 16],
        }

        // Define a struct with default alignment
        struct DefaultAligned {
            data: u32,
        }

        // Test with 16-byte aligned struct
        let layout = Layout::new::<Aligned16Bytes>();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };
        assert!(is_pointer_aligned(ptr));
        unsafe { dealloc(ptr.as_ptr(), layout); }

        // Test with default aligned struct
        let layout = Layout::new::<DefaultAligned>();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };
        assert!(is_pointer_aligned(ptr));
        unsafe { dealloc(ptr.as_ptr(), layout); }
    }

    #[test]
    fn test_misaligned_pointers() {
        unsafe {
            // Allocate memory for a u64 (8-byte alignment)
            let layout = Layout::new::<u64>();
            let ptr = alloc(layout);

            // Create a pointer offset by 1 byte, which will be misaligned for u16, u32, u64
            let offset_ptr = ptr.add(1);

            // Test with u8 (alignment 1) - should still be aligned
            let u8_ptr = NonNull::new_unchecked(offset_ptr as *mut u8);
            assert!(is_pointer_aligned(u8_ptr));

            // Test with u16 (alignment 2) - should be misaligned
            let u16_ptr = NonNull::new_unchecked(offset_ptr as *mut u16);
            assert!(!is_pointer_aligned(u16_ptr));

            // Test with u32 (alignment 4) - should be misaligned
            let u32_ptr = NonNull::new_unchecked(offset_ptr as *mut u32);
            assert!(!is_pointer_aligned(u32_ptr));

            // Test with u64 (alignment 8) - should be misaligned
            let u64_ptr = NonNull::new_unchecked(offset_ptr as *mut u64);
            assert!(!is_pointer_aligned(u64_ptr));

            // Clean up
            dealloc(ptr, layout);
        }
    }

    #[test]
    fn test_with_generic_types() {
        // Test with Vec<T> - should be aligned for Vec<u8>
        let layout = Layout::new::<Vec<u8>>();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };
        assert!(is_pointer_aligned(ptr));
        unsafe { dealloc(ptr.as_ptr(), layout); }

        // Test with Option<T> - should be aligned for Option<u64>
        let layout = Layout::new::<Option<u64>>();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };
        assert!(is_pointer_aligned(ptr));
        unsafe { dealloc(ptr.as_ptr(), layout); }
    }

    #[test]
    fn test_null_pointers() {
        // This test is more for demonstration since NonNull can't be null
        // But we can test with a pointer that's non-null but would be invalid to dereference
        let ptr = NonNull::new(1 as *mut u32).unwrap();

        // The alignment check should work independently of whether the pointer
        // can be dereferenced - it's just checking the address
        assert!(!is_pointer_aligned(ptr));
    }
}

