        let slice: &[TestStruct] = &structs;
        let ptr = NonNull::new(slice as *const [TestStruct] as *mut [TestStruct]).unwrap();
        assert!(!is_slice_empty(ptr));

        let empty_structs: &[TestStruct] = &[];
        let ptr = NonNull::new(empty_structs as *const [TestStruct] as *mut [TestStruct]).unwrap();
        assert!(is_slice_empty(ptr));
    }

    #[test]
    fn test_with_zero_sized_type() {
        let slice: &[()] = &[(), (), ()];
        let ptr = NonNull::new(slice as *const [()] as *mut [()]).unwrap();
        assert!(!is_slice_empty(ptr));

        let empty_slice: &[()] = &[];
        let ptr = NonNull::new(empty_slice as *const [()] as *mut [()]).unwrap();
        assert!(is_slice_empty(ptr));
    }

