        let mut empty_data: Vec<i32> = vec![];
        let empty_slice: &mut [i32] = &mut empty_data;
        let ptr = NonNull::new(empty_slice as *mut [i32]).unwrap();
        assert!(is_slice_empty(ptr));
    }

    // This test is to ensure the function works in const contexts
    const EMPTY_SLICE: &[i32] = &[];
    const NON_EMPTY_SLICE: &[i32] = &[1];

    // Using transmute for const context since NonNull::new isn't const stable
    const EMPTY_PTR: NonNull<[i32]> = unsafe {
        std::mem::transmute::<*const [i32], NonNull<[i32]>>(
            EMPTY_SLICE as *const [i32]
        )
    };

    const NON_EMPTY_PTR: NonNull<[i32]> = unsafe {
        std::mem::transmute::<*const [i32], NonNull<[i32]>>(
            NON_EMPTY_SLICE as *const [i32]
        )
    };

    const EMPTY_RESULT: bool = is_slice_empty(EMPTY_PTR);
    const NON_EMPTY_RESULT: bool = is_slice_empty(NON_EMPTY_PTR);

    #[test]
    fn test_const_fn() {
        assert!(EMPTY_RESULT);
        assert!(!NON_EMPTY_RESULT);
    }
}

