#[cfg(test)]
mod tests {
    use super::*;

    struct CustomEscape {
        data: Vec<char>,
        index: usize,
    }

    impl CustomEscape {
        fn new(s: &str) -> Self {
            Self { data: s.chars().collect(), index: 0 }
        }
    }

    impl Iterator for CustomEscape {
        type Item = char;

        fn next(&mut self) -> Option<Self::Item> {
            if self.index >= self.data.len() {
                None
            } else {
                let ch = self.data[self.index];
                self.index += 1;
                Some(ch)
            }
        }

        fn size_hint(&self) -> (usize, Option<usize>) {
            let remaining = self.data.len().saturating_sub(self.index);
            (remaining, Some(remaining))
        }
    }

    impl ExactSizeIterator for CustomEscape {
        fn len(&self) -> usize {
            self.data.len().saturating_sub(self.index)
        }
    }

    #[test]
    fn test_empty_iter() {
        let iter = CustomEscape::new("");
        assert_eq!(calculate_char_count(&iter), 0);
    }

    #[test]
    fn test_basic_len() {
        let iter = CustomEscape::new("escape");
        assert_eq!(calculate_char_count(&iter), 6);
    }

    #[test]
    fn test_after_advance() {
        let mut iter = CustomEscape::new("abcd");
        let _ = iter.next();
        let _ = iter.next();
        assert_eq!(calculate_char_count(&iter), 2);
    }
}

