mod tests {
    use super::*;

    #[test]
    fn test_valid_shift() {
        // Test with a positive number
        assert_eq!(safe_right_shift(8, 1), Some(4));
        assert_eq!(safe_right_shift(8, 2), Some(2));
        assert_eq!(safe_right_shift(8, 3), Some(1));
        assert_eq!(safe_right_shift(8, 4), Some(0));

        // Test with larger values
        assert_eq!(safe_right_shift(1024, 5), Some(32));

        // Test with negative numbers
        assert_eq!(safe_right_shift(-8, 1), Some(-4));
        assert_eq!(safe_right_shift(-8, 2), Some(-2));

        // Test with extreme values
        assert_eq!(safe_right_shift(i32::MAX, 1), Some(i32::MAX >> 1));
        assert_eq!(safe_right_shift(i32::MIN, 1), Some(i32::MIN >> 1));

        // Test with zero shift
        assert_eq!(safe_right_shift(42, 0), Some(42));

        // Test with zero value
        assert_eq!(safe_right_shift(0, 5), Some(0));
    }

    #[test]
    fn test_edge_cases() {
        // Test with shift amount at the boundary (31 for i32)
        assert_eq!(safe_right_shift(i32::MIN, 31), Some(-1));
        assert_eq!(safe_right_shift(i32::MAX, 31), Some(0));

        // Test with shift amount exactly equal to bit size (32 for i32)
        assert_eq!(safe_right_shift(123, 32), None);

        // Test with shift amount greater than bit size
        assert_eq!(safe_right_shift(42, 33), None);
        assert_eq!(safe_right_shift(-42, 100), None);
        assert_eq!(safe_right_shift(0, u32::MAX), None);
    }

    #[test]
    fn test_all_bits_set() {
        // Test with all bits set to 1
        let all_ones: i32 = -1;  // This is 0xFFFFFFFF in two's complement
        assert_eq!(safe_right_shift(all_ones, 1), Some(-1));  // Should remain -1
        assert_eq!(safe_right_shift(all_ones, 31), Some(-1)); // Should still be -1
    }

    #[test]
    fn test_single_bit_patterns() {
        // Test shifting with single bit set
        for bit_position in 0..31 {
            let value = 1 << bit_position;

            // When shifting right by exactly the bit position, result should be 1
            assert_eq!(safe_right_shift(value, bit_position), Some(1));

            // When shifting right by more than the bit position, result should be 0
            if bit_position < 30 {
                assert_eq!(safe_right_shift(value, bit_position + 1), Some(0));
            }

            // When shifting right by less than the bit position, result should have the bit at (bit_position - shift)
            if bit_position > 0 {
                assert_eq!(safe_right_shift(value, 1), Some(value >> 1));
            }
        }
    }
}

