            y: 3.14,
            name: String::from("test"),
        };
        let boxed = Box::new(original);

        // Convert the box to a raw pointer
        let raw_ptr = convert_box_to_raw(boxed);

        // Verify the raw pointer is not null
        assert!(!raw_ptr.is_null());

        // Safely access fields from the raw pointer
        unsafe {
            assert_eq!((*raw_ptr).x, 10);
            assert_eq!((*raw_ptr).y, 3.14);
            assert_eq!((*raw_ptr).name, "test");
        }

        // Clean up the memory to avoid leaks
        unsafe { Box::from_raw(raw_ptr) };
    }

    #[test]
    fn test_convert_box_to_raw_zero_sized_type() {
        // Test with a zero-sized type
        struct ZST;

        let boxed = Box::new(ZST);
        let raw_ptr = convert_box_to_raw(boxed);

        // Even for ZSTs, the pointer should be valid
        assert!(!raw_ptr.is_null());

        // No need to dereference a ZST, but we still need to clean up
        unsafe { Box::from_raw(raw_ptr) };
    }

