        let boxed_addr = &*boxed as *const i32 as usize;

        // Convert to raw pointer
        let raw_ptr = convert_box_to_raw(boxed);
        let raw_addr = raw_ptr as usize;

        // Addresses should match
        assert_eq!(boxed_addr, raw_addr);

