        unsafe { Box::from_raw(raw_ptr) };
    }

    #[test]
    fn test_memory_leak_detection() {
        use std::sync::{Arc, Mutex};

        // Create a structure to track destructor calls
        struct Tracked {
            counter: Arc<Mutex<i32>>,
            id: i32,
        }

        impl Drop for Tracked {
            fn drop(&mut self) {
                let mut count = self.counter.lock().unwrap();
                *count += 1;
            }
        }

        // Set up counter and create tracked instances
        let counter = Arc::new(Mutex::new(0));
        let tracked = Tracked { counter: Arc::clone(&counter), id: 1 };
        let boxed = Box::new(tracked);

        // Convert to raw pointer
        let raw_ptr = convert_box_to_raw(boxed);

        // At this point, no destructor should have been called
        assert_eq!(*counter.lock().unwrap(), 0);

        // Explicitly reconstruct and drop the box to trigger destructor
        unsafe { Box::from_raw(raw_ptr) };

        // Verify that the destructor was called exactly once
        assert_eq!(*counter.lock().unwrap(), 1);
    }
}

