use std::collections::HashSet;

fn count_unique_rotated_values(data: &[u64], rotation_bits: u32) -> usize {
    let mut unique_values = HashSet::new();
    for &value in data {
        unique_values.insert(value.rotate_right(rotation_bits));
    }
    unique_values.len()
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_array() {
        let data: Vec<u64> = vec![];
        assert_eq!(count_unique_rotated_values(&data, 1), 0);
    }

    #[test]
    fn test_single_element() {
        let data = vec![0x1234_5678_9ABC_DEF0];
        assert_eq!(count_unique_rotated_values(&data, 4), 1);
    }

    #[test]
    fn test_no_rotation() {
        let data = vec![0x1111, 0x2222, 0x3333, 0x1111];
        assert_eq!(count_unique_rotated_values(&data, 0), 3);
    }

    #[test]
    fn test_full_rotation() {
        let data = vec![0x1111, 0x2222, 0x3333];
        assert_eq!(count_unique_rotated_values(&data, 64), 3);
    }

    #[test]
    fn test_rotation_creates_duplicates() {
        // When rotated right by 1 bit:
        // 0x1 becomes 0x8000_0000_0000_0000
        // 0x8000_0000_0000_0000 becomes 0x4000_0000_0000_0000
        let data = vec![0x1, 0x8000_0000_0000_0000, 0x2, 0x3];
        assert_eq!(count_unique_rotated_values(&data, 1), 4);

        // With a 2-bit rotation:
        // 0x1 becomes 0x4000_0000_0000_0000
        // 0x8000_0000_0000_0000 becomes 0x2000_0000_0000_0000
        // 0x4000_0000_0000_0000 becomes 0x1000_0000_0000_0000
        // 0x2 becomes 0x8000_0000_0000_0000
        // So we should have 4 unique values
        let data = vec![0x1, 0x2, 0x4000_0000_0000_0000, 0x8000_0000_0000_0000];
        assert_eq!(count_unique_rotated_values(&data, 2), 4);
    }

    #[test]
    fn test_rotation_eliminates_duplicates() {
        // These values are different, but some are duplicates
        let data = vec![0x1, 0x2, 0x4, 0x8, 0x1, 0x2];
        assert_eq!(count_unique_rotated_values(&data, 0), 4);

        // After rotation by 1, we should have 0x8000...0000 and 0x0000...0001 (2 unique values)
        let data = vec![0x1, 0x1 << 63, 0x1, 0x1 << 63];
        assert_eq!(count_unique_rotated_values(&data, 1), 2);
    }

    #[test]
    fn test_large_rotation() {
        let data = vec![0x1234_5678_9ABC_DEF0, 0xFEDC_BA98_7654_3210];

        // Rotation by 32 bits should swap the high and low 32 bits
        assert_eq!(count_unique_rotated_values(&data, 32), 2);
    }

    #[test]
    fn test_large_dataset() {
        // Test with a larger dataset
        let mut data = Vec::with_capacity(1000);
        for i in 0..1000 {
            data.push(i as u64);
        }

        // All values should remain unique after rotation
        assert_eq!(count_unique_rotated_values(&data, 8), 1000);
    }

    #[test]
    fn test_rotation_wrapping() {
        // Test that rotation wraps properly
        let value = 0x8000_0000_0000_0001;
        let data = vec![value];

        // Rotating by 63 should move the highest bit to the second position
        // and the lowest bit to the highest position
        // 0x8000_0000_0000_0001 becomes 0x0000_0000_0000_0003
        assert_eq!(count_unique_rotated_values(&data, 63), 1);

        // A different dataset to verify wrapping behavior
        let data = vec![0x1, 0x2, 0x1 << 63, 0x1 | (0x1 << 63)];
        assert_eq!(count_unique_rotated_values(&data, 1), 4);
    }
}

