    fn test_rotate_by_32_bits() {
        // Rotating by 32 bits should return the original value
        assert_eq!(rotate_bits_left(0xABCDEF12, 32), 0xABCDEF12);
    }

    #[test]
    fn test_rotate_beyond_32_bits() {
        // Rotation should wrap around after 32 bits
        assert_eq!(rotate_bits_left(0xABCDEF12, 40), 0xCDEF12AB); // Equivalent to rotating by 8
    }

    #[test]
    fn test_all_ones() {
        assert_eq!(rotate_bits_left(0xFFFFFFFF, 16), 0xFFFFFFFF);
    }

