        assert_eq!(rotate_bits_left(u32::MIN, 16), u32::MIN);
        assert_eq!(rotate_bits_left(u32::MAX, 16), u32::MAX);

        // Power of two values
        assert_eq!(rotate_bits_left(0x00010000, 16), 0x00000001);
    }

