        // 0xAAAAAAAA = 10101010...
        // 0x55555555 = 01010101...
        assert_eq!(rotate_bits_left(0xAAAAAAAA, 1), 0x55555555);
        assert_eq!(rotate_bits_left(0x55555555, 1), 0xAAAAAAAA);
    }

