#[cfg(test)]
mod tests {
    use super::count_three_trailing_zeros;

    #[test]
    fn test_empty_array() {
        let empty: [u64; 0] = [];
        assert_eq!(count_three_trailing_zeros(&empty), 0);
    }

    #[test]
    fn test_no_matching_numbers() {
        let numbers = [1u64, 2, 4, 16, 32]; // All have 0, 1, 2, 4, 5 trailing zeros respectively, none have exactly 3
        assert_eq!(count_three_trailing_zeros(&numbers), 0);
    }

    #[test]
    fn test_all_matching_numbers() {
        let numbers = [8u64, 24, 40, 56]; // All have exactly 3 trailing zeros in binary
        assert_eq!(count_three_trailing_zeros(&numbers), 4);
    }

    #[test]
    fn test_mixed_numbers() {
        let numbers = [0u64, 1, 8, 16, 24, 32, 40, 64, 128];
        // 8 (1000) -> 3 trailing zeros
        // 24 (11000) -> 3 trailing zeros
        // 40 (101000) -> 3 trailing zeros
        // Expected count: 3
        assert_eq!(count_three_trailing_zeros(&numbers), 3);
    }

    #[test]
    fn test_large_numbers() {
        let numbers = [
            0xFFFFFFFFFFFFFFFFu64, // All bits set, 0 trailing zeros
            0xFFFFFFFFFFFFFFF8u64, // 3 trailing zeros
            0xFFFFFFFFFFFFFFF0u64, // 4 trailing zeros
            0x8000000000000000u64, // Largest power of 2, 63 trailing zeros
        ];
        assert_eq!(count_three_trailing_zeros(&numbers), 1);
    }

    #[test]
    fn test_binary_values_with_three_trailing_zeros() {
        // Create numbers with exactly 3 trailing zeros
        let values = [
            0b1000u64,         // 8 in decimal
            0b11000u64,        // 24 in decimal
            0b101000u64,       // 40 in decimal
            0b111000u64,       // 56 in decimal
            0b1001000u64,      // 72 in decimal
            0b1000001000u64,   // 520 in decimal
        ];
        assert_eq!(count_three_trailing_zeros(&values), 6);
    }

    #[test]
    fn test_performance_with_large_dataset() {
        // Create a large dataset with a mix of values
        let mut large_dataset = Vec::with_capacity(10_000);
        let mut expected_count = 0;

        for i in 0..10_000u64 {
            large_dataset.push(i);
            // Corrected condition: i has exactly 3 trailing zeros when binary representation
            // ends with exactly 3 zeros (divisible by 8 but not by 16)
            if i != 0 && i & 0b111 == 0 && i & 0b1000 != 0 {
                expected_count += 1;
            }
        }

        assert_eq!(count_three_trailing_zeros(&large_dataset), expected_count);
    }

    #[test]
    fn test_edge_cases() {
        // Test with zero (special case, all trailing zeros or u64::MAX trailing zeros)
        let zeros = [0u64, 0, 0];
        assert_eq!(count_three_trailing_zeros(&zeros), 0);

        // Test with powers of 2
        let powers_of_two = [1u64, 2, 4, 8, 16, 32, 64];
        // Only 8 (2^3) has exactly 3 trailing zeros
        assert_eq!(count_three_trailing_zeros(&powers_of_two), 1);
    }
}

