mod tests {
    use super::*;

    #[test]
    fn test_append_to_dataset_returns_dataset() {
        let mut dataset = vec![1, 2, 3];
        let result = append_to_dataset(&mut dataset, 4);
        assert_eq!(result, &mut vec![1, 2, 3, 4]);
    }

    #[test]
    fn test_append_to_dataset_adds_value() {
        let mut dataset = vec![1, 2, 3];
        append_to_dataset(&mut dataset, 4);
        assert_eq!(dataset, vec![1, 2, 3, 4]);
    }

    #[test]
    fn test_append_to_dataset_empty() {
        let mut dataset = Vec::<i32>::new();
        append_to_dataset(&mut dataset, 42);
        assert_eq!(dataset, vec![42]);
    }

    #[test]
    fn test_append_to_dataset_at_capacity() {
        // Create a vector with capacity 4 and fill it
        let mut dataset = Vec::with_capacity(4);
        dataset.push(1);
        dataset.push(2);
        dataset.push(3);
        dataset.push(4);

        // Verify it's at capacity
        assert_eq!(dataset.capacity(), 4);
        assert_eq!(dataset.len(), 4);

        // Append a new value (should cause reallocation)
        let original_capacity = dataset.capacity();
        append_to_dataset(&mut dataset, 5);

        // Verify the value was added and capacity increased
        assert_eq!(dataset, vec![1, 2, 3, 4, 5]);
        assert!(dataset.capacity() > original_capacity);
    }

    #[test]
    fn test_append_to_dataset_with_reserved_capacity() {
        // Create a vector with extra reserved capacity
        let mut dataset = Vec::with_capacity(10);
        dataset.push(1);
        dataset.push(2);

        // Verify current state
        assert_eq!(dataset.len(), 2);
        assert_eq!(dataset.capacity(), 10);

        // Store original capacity for comparison
        let original_capacity = dataset.capacity();

        // Append a new value (should not cause reallocation)
        append_to_dataset(&mut dataset, 3);

        // Verify the value was added and capacity remained the same
        assert_eq!(dataset, vec![1, 2, 3]);
        assert_eq!(dataset.capacity(), original_capacity);
    }

    #[test]
    fn test_append_to_dataset_with_negative_values() {
        let mut dataset = vec![10, 20, 30];
        append_to_dataset(&mut dataset, -5);
        assert_eq!(dataset, vec![10, 20, 30, -5]);
    }

    #[test]
    fn test_append_to_dataset_preserves_existing_data() {
        let mut dataset = vec![42, 17, 8];
        let original_data = dataset.clone();
        append_to_dataset(&mut dataset, 99);

        // Verify all original elements are still present
        for i in 0..original_data.len() {
            assert_eq!(dataset[i], original_data[i]);
        }

        // Verify new element is at the end
        assert_eq!(dataset[dataset.len() - 1], 99);
    }

    #[test]
    fn test_append_to_dataset_large_dataset() {
        // Create a larger dataset to simulate real-world usage
        let mut dataset: Vec<i32> = (0..1000).collect();
        let original_len = dataset.len();
        append_to_dataset(&mut dataset, 1000);

        assert_eq!(dataset.len(), original_len + 1);
        assert_eq!(dataset[dataset.len() - 1], 1000);
    }
}

