    fn test_single_entry() {
        let mut buffer = Cursor::new(Vec::new());
        let entries = &[b"Single log entry".as_ref()];

        let result = write_log_entries(&mut buffer, entries);

        assert!(result.is_ok());
        assert_eq!(buffer.get_ref(), b"Single log entry");
    }

    #[test]
    fn test_multiple_entries() {
        let mut buffer = Cursor::new(Vec::new());
        let entries = &[b"First entry".as_ref(), b"Second entry".as_ref(), b"Third entry".as_ref()];

        let result = write_log_entries(&mut buffer, entries);

        assert!(result.is_ok());
        assert_eq!(buffer.get_ref(), b"First entrySecond entryThird entry");
    }

    #[test]
    fn test_large_entries() {
        let mut buffer = Cursor::new(Vec::new());
        let large_entry = vec![b'X'; 1024 * 1024]; // 1MB of data
        let entries = &[large_entry.as_slice(), large_entry.as_slice()];

        let result = write_log_entries(&mut buffer, entries);

        assert!(result.is_ok());
        assert_eq!(buffer.get_ref().len(), 2 * 1024 * 1024);
        assert!(buffer.get_ref().iter().all(|&b| b == b'X'));
    }

    #[test]
    fn test_error_propagation() {
        // A custom Write implementation that fails after a certain number of bytes
        struct FailingWriter {
            bytes_until_error: usize,
            written: Vec<u8>,
        }

        impl Write for FailingWriter {
            fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
                if self.bytes_until_error == 0 {
                    return Err(io::Error::new(io::ErrorKind::Other, "Simulated error"));
                }

                let to_write = std::cmp::min(buf.len(), self.bytes_until_error);
                self.written.extend_from_slice(&buf[..to_write]);
                self.bytes_until_error -= to_write;

                Ok(to_write)
            }

            fn flush(&mut self) -> io::Result<()> {
                Ok(())
            }
        }

        let mut writer = FailingWriter {
            bytes_until_error: 10,
            written: Vec::new(),
        };

        let entries = &[b"First 10 bytes".as_ref(), b"This won't be fully written".as_ref()];

        let result = write_log_entries(&mut writer, entries);

        assert!(result.is_err());
        assert_eq!(writer.written.len(), 10);
        assert_eq!(&writer.written, b"First 10 b");
    }

    #[test]
    fn test_with_newlines() {
        let mut buffer = Cursor::new(Vec::new());
        let entries = &[b"First line\n".as_ref(), b"Second line\n".as_ref(), b"Third line\n".as_ref()];

        let result = write_log_entries(&mut buffer, entries);

        assert!(result.is_ok());
        assert_eq!(buffer.get_ref(), b"First line\nSecond line\nThird line\n");
    }

    #[test]
    fn test_binary_data() {
        let mut buffer = Cursor::new(Vec::new());
        let binary_data = [0u8, 1u8, 255u8, 128u8];
        let entries = &[binary_data.as_ref()];

        let result = write_log_entries(&mut buffer, entries);

        assert!(result.is_ok());
        assert_eq!(buffer.get_ref(), &[0u8, 1u8, 255u8, 128u8]);
    }

    #[test]
    fn test_zero_capacity_writer() {
        struct ZeroCapacityWriter {
            data: Vec<u8>,
        }

        impl Write for ZeroCapacityWriter {
            fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
                // This writer only writes one byte at a time
                if !buf.is_empty() {
                    self.data.push(buf[0]);
                    Ok(1)
                } else {
                    Ok(0)
                }
            }

            fn flush(&mut self) -> io::Result<()> {
                Ok(())
            }
        }

        let mut writer = ZeroCapacityWriter { data: Vec::new() };
        let entries = &[b"test".as_ref()];

        let result = write_log_entries(&mut writer, entries);

        assert!(result.is_ok());
        assert_eq!(writer.data, b"test");
    }
}

