#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_positive_inputs() {
        // Basic cases
        assert_eq!(compute_logarithm(8, 2), Some(3));  // 2^3 = 8
        assert_eq!(compute_logarithm(27, 3), Some(3));  // 3^3 = 27
        assert_eq!(compute_logarithm(100, 10), Some(2));  // 10^2 = 100
        assert_eq!(compute_logarithm(16, 4), Some(2));  // 4^2 = 16

        // Edge cases for valid inputs
        assert_eq!(compute_logarithm(1, 2), Some(0));  // Any number^0 = 1
        assert_eq!(compute_logarithm(2, 2), Some(1));  // 2^1 = 2
        assert_eq!(compute_logarithm(3, 2), Some(1));  // log_2(3) = 1.58... truncated to 1
    }

    #[test]
    fn test_large_inputs() {
        // Test with larger numbers
        assert_eq!(compute_logarithm(1_000_000, 10), Some(6));  // 10^6 = 1,000,000
        assert_eq!(compute_logarithm(1_073_741_824, 2), Some(30));  // 2^30

        // Test near the limits of i128
        let large_value = i128::MAX / 2;
        let result = compute_logarithm(large_value, 2);
        assert!(result.is_some());

        // Verify result is reasonable for a large number
        // i128::MAX is roughly 2^127, so log base 2 should be < 127
        assert!(result.unwrap() < 127);
    }

    #[test]
    fn test_invalid_inputs() {
        // Test with negative value
        assert_eq!(compute_logarithm(-5, 2), None);

        // Test with zero value
        assert_eq!(compute_logarithm(0, 2), None);

        // Test with invalid bases
        assert_eq!(compute_logarithm(100, 1), None);  // Base 1 is invalid
        assert_eq!(compute_logarithm(100, 0), None);  // Base 0 is invalid
        assert_eq!(compute_logarithm(100, -2), None);  // Negative base is invalid
    }

    #[test]
    fn test_boundary_cases() {
        // Test with minimum valid inputs
        assert_eq!(compute_logarithm(1, 2), Some(0));

        // Test with a base equal to the value
        assert_eq!(compute_logarithm(5, 5), Some(1));  // 5^1 = 5

        // Test with a large base
        assert_eq!(compute_logarithm(1000, 1000), Some(1));  // 1000^1 = 1000

        // Test with a base larger than the value
        assert_eq!(compute_logarithm(2, 3), Some(0));  // log_3(2) = 0.63... truncated to 0
    }

    #[test]
    fn test_perfect_powers() {
        // Test with perfect powers
        assert_eq!(compute_logarithm(8, 2), Some(3));  // 2^3 = 8
        assert_eq!(compute_logarithm(9, 3), Some(2));  // 3^2 = 9
        assert_eq!(compute_logarithm(32, 2), Some(5));  // 2^5 = 32
        assert_eq!(compute_logarithm(1_048_576, 4), Some(10));  // 4^10 = 1,048,576
    }

    #[test]
    fn test_non_perfect_powers() {
        // Test with non-perfect powers (should truncate)
        assert_eq!(compute_logarithm(10, 3), Some(2));  // log_3(10) = 2.09... truncated to 2
        assert_eq!(compute_logarithm(20, 2), Some(4));  // log_2(20) = 4.32... truncated to 4
        assert_eq!(compute_logarithm(100, 3), Some(4));  // log_3(100) = 4.19... truncated to 4
    }
}

