            value: f64,
        }

        let structs = [
            TestStruct { id: 1, value: 1.1 },
            TestStruct { id: 2, value: 2.2 },
            TestStruct { id: 3, value: 3.3 },
        ];

        let ptr = NonNull::new(structs.as_ptr() as *mut TestStruct).unwrap();

        let skipped_ptr = skip_elements(ptr, 1);

        unsafe {
            assert_eq!((*skipped_ptr.as_ptr()).id, 2);
            assert_eq!((*skipped_ptr.as_ptr()).value, 2.2);
        }
    }

    #[test]
    fn test_skip_elements_alignment() {
        // Test with a type that has specific alignment requirements
        #[repr(align(16))]
        struct AlignedStruct {
            data: [u8; 32],
        }

        let structs = [
            AlignedStruct { data: [1; 32] },
            AlignedStruct { data: [2; 32] },
            AlignedStruct { data: [3; 32] },
        ];

        let ptr = NonNull::new(structs.as_ptr() as *mut AlignedStruct).unwrap();

        let skipped_ptr = skip_elements(ptr, 2);

        unsafe {
            assert_eq!((*skipped_ptr.as_ptr()).data[0], 3);

            // Verify alignment is preserved
            assert_eq!(skipped_ptr.as_ptr() as usize % 16, 0);
        }
