        let size = values.len();

        unsafe {
            // Get a non-null pointer to the end of the array
            let ptr = NonNull::new((values.as_ptr() as *mut i32).add(size)).unwrap();

            // Test retrieving values from different positions
            assert_eq!(get_value_before_end(ptr, 1), 50); // Last value
            assert_eq!(get_value_before_end(ptr, 2), 40); // Second-to-last value
            assert_eq!(get_value_before_end(ptr, 5), 10); // First value
        }
    }

