        unsafe {
            // Create a heap-allocated array
            let size = 10;
            let layout = Layout::array::<i32>(size).unwrap();
            let ptr = NonNull::new(alloc(layout) as *mut i32).unwrap();

            // Initialize with values
            for i in 0..size {
                *ptr.as_ptr().add(i) = (i as i32) * 10;
            }

            // Calculate end pointer for retrieval (since the function works from the end)
            let end_ptr = NonNull::new(ptr.as_ptr().add(size)).unwrap();

            // Test retrieving values
