mod tests {
    use super::*;
    use std::ptr::NonNull;
    use std::alloc::{alloc, dealloc, Layout};

    #[test]
    fn test_zero_count_returns_ok() {
        // Create dummy pointers that won't be used
        let src = NonNull::dangling();
        let dest = NonNull::dangling();

        let result = transfer_data_block(src, dest, 0);
        assert!(result.is_ok());
    }

    #[test]
    fn test_successful_transfer() {
        // Allocate test buffers
        let layout = Layout::array::<u8>(100).unwrap();
        let src_ptr = unsafe { alloc(layout) };
        let dest_ptr = unsafe { alloc(layout) };

        assert!(!src_ptr.is_null() && !dest_ptr.is_null(), "Failed to allocate memory for test");

        let src = unsafe { NonNull::new_unchecked(src_ptr) };
        let dest = unsafe { NonNull::new_unchecked(dest_ptr) };

        // Initialize source data
        let test_data: [u8; 5] = [1, 2, 3, 4, 5];
        unsafe {
            std::ptr::copy_nonoverlapping(test_data.as_ptr(), src.as_ptr(), test_data.len());
        }

        // Perform transfer
        let result = transfer_data_block(src, dest, test_data.len());

        // Verify result
        assert!(result.is_ok());

        // Verify destination data
        let mut dest_data = [0u8; 5];
        unsafe {
            std::ptr::copy_nonoverlapping(dest.as_ptr(), dest_data.as_mut_ptr(), dest_data.len());
        }

        assert_eq!(dest_data, test_data);

        // Clean up
        unsafe {
            dealloc(src_ptr, layout);
            dealloc(dest_ptr, layout);
        }
    }

    #[test]
    fn test_large_data_transfer() {
        const SIZE: usize = 1024 * 64; // 64KB

        // Allocate test buffers
        let layout = Layout::array::<u8>(SIZE).unwrap();
        let src_ptr = unsafe { alloc(layout) };
        let dest_ptr = unsafe { alloc(layout) };

        assert!(!src_ptr.is_null() && !dest_ptr.is_null(), "Failed to allocate memory for test");

        let src = unsafe { NonNull::new_unchecked(src_ptr) };
        let dest = unsafe { NonNull::new_unchecked(dest_ptr) };

        // Initialize source data with pattern
        unsafe {
            for i in 0..SIZE {
                *src_ptr.add(i) = (i % 256) as u8;
            }
        }

        // Perform transfer
        let result = transfer_data_block(src, dest, SIZE);

        // Verify result
        assert!(result.is_ok());

        // Verify destination data
        unsafe {
            for i in 0..SIZE {
                assert_eq!(*dest_ptr.add(i), (i % 256) as u8);
            }
        }

        // Clean up
        unsafe {
            dealloc(src_ptr, layout);
            dealloc(dest_ptr, layout);
        }
    }

    #[test]
    fn test_overlapping_memory() {
        // Allocate a buffer large enough for overlapping regions
        const SIZE: usize = 100;
        const OVERLAP_SIZE: usize = 50;

        let layout = Layout::array::<u8>(SIZE).unwrap();
        let buffer_ptr = unsafe { alloc(layout) };

        assert!(!buffer_ptr.is_null(), "Failed to allocate memory for test");

        // Create two overlapping regions in the same buffer
        let src = unsafe { NonNull::new_unchecked(buffer_ptr) };
        let dest = unsafe { NonNull::new_unchecked(buffer_ptr.add(OVERLAP_SIZE)) };

        // Initialize source data
