        #[derive(Debug, PartialEq, Clone, Copy)]
        struct TestStruct {
            id: u64,
            value: f32,
            flag: bool,
        }

        // Allocate memory for source and destination
        let layout = Layout::array::<TestStruct>(3).unwrap();
        let src_ptr = unsafe { alloc(layout) as *mut TestStruct };
        let dest_ptr = unsafe { alloc(layout) as *mut TestStruct };

        // Test data - now Copy is implemented
        let test_data = [
            TestStruct { id: 1, value: 3.14, flag: true },
            TestStruct { id: 2, value: 2.71, flag: false },
            TestStruct { id: 3, value: 1.618, flag: true },
        ];

        unsafe {
            // Initialize source with test data
            for i in 0..3 {
                std::ptr::write(src_ptr.add(i), test_data[i]);
            }

            // Convert raw pointers to NonNull
            let src = NonNull::new(src_ptr).unwrap();
            let dest = NonNull::new(dest_ptr).unwrap();

            // Call the function being tested
            transfer_memory_block(src, dest, 3);

            // Verify the data was transferred correctly
            for i in 0..3 {
                assert_eq!(std::ptr::read(dest_ptr.add(i)), test_data[i]);
            }

            // Clean up allocated memory
            dealloc(src_ptr as *mut u8, layout);
            dealloc(dest_ptr as *mut u8, layout);
        }
    }

    #[test]
    fn test_transfer_zero_elements() {
        // Allocate memory for source and destination
        let layout = Layout::array::<u8>(1).unwrap();
        let src_ptr = unsafe { alloc(layout) as *mut u8 };
        let dest_ptr = unsafe { alloc(layout) as *mut u8 };

        unsafe {
            // Initialize with different values
            *src_ptr = 42;
            *dest_ptr = 10;

            // Convert raw pointers to NonNull
            let src = NonNull::new(src_ptr).unwrap();
            let dest = NonNull::new(dest_ptr).unwrap();

            // Call with count = 0 (should not modify destination)
            transfer_memory_block(src, dest, 0);

            // Verify destination is unchanged
            assert_eq!(*dest_ptr, 10);

            // Clean up allocated memory
            dealloc(src_ptr as *mut u8, layout);
            dealloc(dest_ptr as *mut u8, layout);
        }
    }

    #[test]
    fn test_transfer_large_array() {
        const SIZE: usize = 1000;

        // Allocate memory for source and destination
        let layout = Layout::array::<u32>(SIZE).unwrap();
        let src_ptr = unsafe { alloc(layout) as *mut u32 };
        let dest_ptr = unsafe { alloc(layout) as *mut u32 };

        unsafe {
            // Initialize source with test values
            for i in 0..SIZE {
                *src_ptr.add(i) = i as u32;
            }

            // Clear destination
            for i in 0..SIZE {
                *dest_ptr.add(i) = 0;
            }

            // Convert raw pointers to NonNull
            let src = NonNull::new(src_ptr).unwrap();
            let dest = NonNull::new(dest_ptr).unwrap();

            // Call the function being tested
            transfer_memory_block(src, dest, SIZE);

            // Verify the data was transferred correctly
            for i in 0..SIZE {
                assert_eq!(*dest_ptr.add(i), i as u32);
            }

            // Clean up allocated memory
            dealloc(src_ptr as *mut u8, layout);
            dealloc(dest_ptr as *mut u8, layout);
        }
    }

    #[test]
    #[should_panic]
    fn test_null_source_pointer() {
        unsafe {
            // Allocate memory only for destination
            let layout = Layout::array::<i32>(5).unwrap();
            let dest_ptr = alloc(layout) as *mut i32;

            // Create a null source pointer
            let src_ptr: *mut i32 = std::ptr::null_mut();

            // This will cause a panic when unwrapping None
            let src = NonNull::new(src_ptr).unwrap(); // This properly tests the null check
            let dest = NonNull::new(dest_ptr).unwrap();

            // Should panic before reaching this point
            transfer_memory_block(src, dest, 5);

            // Clean up
            dealloc(dest_ptr as *mut u8, layout);
        }
    }

    #[test]
    fn test_partial_transfer() {
        // Allocate memory for source and destination
        let src_layout = Layout::array::<i32>(10).unwrap();
        let dest_layout = Layout::array::<i32>(5).unwrap();
        let src_ptr = unsafe { alloc(src_layout) as *mut i32 };
        let dest_ptr = unsafe { alloc(dest_layout) as *mut i32 };

        unsafe {
            // Initialize source with test values
            for i in 0..10 {
                *src_ptr.add(i) = i as i32;
            }

            // Clear destination
            for i in 0..5 {
                *dest_ptr.add(i) = 99;
            }

            // Convert raw pointers to NonNull
            let src = NonNull::new(src_ptr).unwrap();
            let dest = NonNull::new(dest_ptr).unwrap();

            // Transfer only first 5 elements
            transfer_memory_block(src, dest, 5);

            // Verify only the requested amount was transferred
            for i in 0..5 {
                assert_eq!(*dest_ptr.add(i), i as i32);
            }

            // Clean up allocated memory
            dealloc(src_ptr as *mut u8, src_layout);
            dealloc(dest_ptr as *mut u8, dest_layout);
        }
    }
}

