        let mut buffer = [1, 2, 3];

        // Split at the end
        let result = split_buffer_at_mid(&mut buffer, 3);

        assert!(result.is_some());

        let (left, right) = result.unwrap();
        assert_eq!(left, &mut [1, 2, 3]);
        assert_eq!(right, &mut []);
    }

