        let mut buffer = [1, 2, 3, 4, 5];

        // Try to split at an invalid index (out of bounds)
        let result = split_buffer_at_mid(&mut buffer, 6);

        assert!(result.is_none());
    }

    #[test]
    fn test_split_buffer_at_mid_empty_buffer() {
        let mut empty_buffer: [i32; 0] = [];

        // Split at index 0 on empty buffer
        let result = split_buffer_at_mid(&mut empty_buffer, 0);

        assert!(result.is_some());

        let (left, right) = result.unwrap();
        assert_eq!(left, &mut []);
        assert_eq!(right, &mut []);

        // Out of bounds on empty buffer
        let result = split_buffer_at_mid(&mut empty_buffer, 1);
        assert!(result.is_none());
    }

    #[test]
    fn test_split_buffer_at_mid_different_types() {
        // Test with a different type
        let mut string_buffer = ["hello", "world", "rust", "programming"];

        let result = split_buffer_at_mid(&mut string_buffer, 2);

        assert!(result.is_some());

        let (left, right) = result.unwrap();
        assert_eq!(left, &mut ["hello", "world"]);
        assert_eq!(right, &mut ["rust", "programming"]);
    }

    #[test]
