        let input = "hello\u{00A0}world";
        let result: Vec<&str> = split_non_empty_ascii_whitespace(input).collect();
        assert_eq!(result, vec!["hello\u{00A0}world"]);
    }

    #[test]
    fn test_mixed_whitespace() {
        let input = " word1\t\tword2  \nword3\r\n word4 ";
        let result: Vec<&str> = split_non_empty_ascii_whitespace(input).collect();
        assert_eq!(result, vec!["word1", "word2", "word3", "word4"]);
    }

    #[test]
    fn test_iterator_behavior() {
        let input = "one two three";
        let mut iter = split_non_empty_ascii_whitespace(input);

        assert_eq!(iter.next(), Some("one"));
        assert_eq!(iter.next(), Some("two"));
        assert_eq!(iter.next(), Some("three"));
        assert_eq!(iter.next(), None);
    }
}

