use std::cell::Cell;
use std::thread::LocalKey;

thread_local! {
    static COUNTER: Cell<u32> = Cell::new(0);
}

fn thread_local_counter() -> impl Fn() -> u32 {
    move || {
        COUNTER.with(|counter| {
            let current = counter.get();
            counter.set(current + 1);
            current + 1
        })
    }
}

