#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, Barrier};
    use std::thread;

    #[test]
    fn test_single_thread_counter() {
        let counter = thread_local_counter();

        assert_eq!(counter(), 1);
        assert_eq!(counter(), 2);
        assert_eq!(counter(), 3);
    }

    #[test]
    fn test_counter_is_thread_local() {
        let counter_fn = thread_local_counter();

        // Initialize counter in main thread
        assert_eq!(counter_fn(), 1);
        assert_eq!(counter_fn(), 2);

        // Spawn a new thread with its own counter
        let handle = thread::spawn(|| {
            let thread_counter = thread_local_counter();
            // This should be a fresh counter starting at 1
            assert_eq!(thread_counter(), 1);
            assert_eq!(thread_counter(), 2);
            assert_eq!(thread_counter(), 3);
        });

        handle.join().unwrap();

        // Continue counting in main thread
        assert_eq!(counter_fn(), 3);
        assert_eq!(counter_fn(), 4);
    }

    #[test]
    fn test_counter_with_multiple_threads() {
        let num_threads = 4;
        let iterations_per_thread = 100;

        // Create a barrier to synchronize thread starts
        let barrier = Arc::new(Barrier::new(num_threads));

        let mut handles = vec![];

        // Spawn multiple threads
        for _ in 0..num_threads {
            let thread_barrier = Arc::clone(&barrier);

            let handle = thread::spawn(move || {
                let thread_counter = thread_local_counter();
                // Wait for all threads to be ready
                thread_barrier.wait();

                // Each thread should get values 1..=iterations_per_thread
                let mut values = vec![];
                for _ in 0..iterations_per_thread {
                    values.push(thread_counter());
                }

                // Verify sequence is correct
                for i in 0..iterations_per_thread {
                    assert_eq!(values[i], i as u32 + 1);
                }

                values
            });

            handles.push(handle);
        }

        // Collect all thread results
        let results: Vec<Vec<u32>> = handles
            .into_iter()
            .map(|h| h.join().unwrap())
            .collect();

        // Verify each thread got the expected sequence
        for thread_results in results {
            assert_eq!(thread_results.len(), iterations_per_thread);
            for i in 0..iterations_per_thread {
                assert_eq!(thread_results[i], i as u32 + 1);
            }
        }
    }

    #[test]
    fn test_counter_closure_independence() {
        // Create multiple counter closures
        let counter1 = thread_local_counter();
        let counter2 = thread_local_counter();

        // They should all share the same thread-local storage
        assert_eq!(counter1(), 1);
        assert_eq!(counter2(), 2);
        assert_eq!(counter1(), 3);
        assert_eq!(counter2(), 4);
    }

    #[test]
    fn test_counter_across_nested_threads() {
        // Initialize counter in main thread
        let main_counter = thread_local_counter();
        assert_eq!(main_counter(), 1);

        // Spawn a thread that spawns another thread
        let handle = thread::spawn(|| {
            // This should be a fresh counter starting at 1
            let parent_counter = thread_local_counter();
            assert_eq!(parent_counter(), 1);

            // Spawn a nested thread
            let nested_handle = thread::spawn(|| {
                // This should also be a fresh counter
                let nested_counter = thread_local_counter();
                assert_eq!(nested_counter(), 1);
                assert_eq!(nested_counter(), 2);
            });

            nested_handle.join().unwrap();

            // Continue counting in the first thread
            assert_eq!(parent_counter(), 2);
        });

        handle.join().unwrap();
    }
}

