    fn test_exactly_one_second() {
        let nanos_in_second = 1_000_000_000;
        let result = create_duration_from_nanos(nanos_in_second);
        assert_eq!(result.as_secs(), 1);
        assert_eq!(result.subsec_nanos(), 0);
        assert_eq!(result.as_nanos(), nanos_in_second as u128);
    }

    #[test]
    fn test_mixed_seconds_and_nanos() {
        let nanos = 1_500_000_000; // 1.5 seconds
        let result = create_duration_from_nanos(nanos);
        assert_eq!(result.as_secs(), 1);
        assert_eq!(result.subsec_nanos(), 500_000_000);
        assert_eq!(result.as_nanos(), nanos as u128);
    }

    #[test]
    fn test_large_nanos() {
        let large_nanos = 123_456_789_012_345; // Over 34 hours
        let result = create_duration_from_nanos(large_nanos);

        // Calculate expected seconds and remaining nanos
        let expected_secs = large_nanos / 1_000_000_000;
        let expected_subsec_nanos = (large_nanos % 1_000_000_000) as u32;

        assert_eq!(result.as_secs(), expected_secs);
        assert_eq!(result.subsec_nanos(), expected_subsec_nanos);
        assert_eq!(result.as_nanos(), large_nanos as u128);
    }

    #[test]
    fn test_max_nanos() {
        let max_nanos = u64::MAX;
        let result = create_duration_from_nanos(max_nanos);

        // Calculate expected seconds and remaining nanos
        let expected_secs = max_nanos / 1_000_000_000;
        let expected_subsec_nanos = (max_nanos % 1_000_000_000) as u32;

        assert_eq!(result.as_secs(), expected_secs);
        assert_eq!(result.subsec_nanos(), expected_subsec_nanos);
        assert_eq!(result.as_nanos(), max_nanos as u128);
    }

    #[test]
    fn test_duration_methods() {
        let nanos = 3_750_000_000; // 3.75 seconds
        let result = create_duration_from_nanos(nanos);

        assert_eq!(result.as_secs_f64(), 3.75);
        assert_eq!(result.as_millis(), 3750);
        assert_eq!(result.as_micros(), 3_750_000);
    }

    #[test]
    fn test_arithmetic_operations() {
        let duration1 = create_duration_from_nanos(2_000_000_000); // 2 seconds
        let duration2 = create_duration_from_nanos(500_000_000);  // 0.5 seconds

        let sum = duration1 + duration2;
        assert_eq!(sum.as_secs(), 2);
        assert_eq!(sum.subsec_nanos(), 500_000_000);

        let diff = duration1 - duration2;
        assert_eq!(diff.as_secs(), 1);
        assert_eq!(diff.subsec_nanos(), 500_000_000);
    }
}

