mod tests {
    use std::fmt;
    use std::io::{self, Write};

    // Mock writer that always succeeds
    struct MockWriter {
        data: Vec<u8>,
    }

    impl MockWriter {
        fn new() -> Self {
            MockWriter { data: Vec::new() }
        }

        fn contents(&self) -> String {
            String::from_utf8_lossy(&self.data).to_string()
        }
    }

    impl Write for MockWriter {
        fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
            self.data.extend_from_slice(buf);
            Ok(buf.len())
        }

        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    // Mock writer that always fails
    struct FailingWriter;

    impl Write for FailingWriter {
        fn write(&mut self, _buf: &[u8]) -> io::Result<usize> {
            Err(io::Error::new(io::ErrorKind::Other, "mock write error"))
        }

        fn flush(&mut self) -> io::Result<()> {
            Err(io::Error::new(io::ErrorKind::Other, "mock flush error"))
        }
    }

    // Import the function to test
    use super::format_and_write;

    #[test]
    fn test_format_and_write_success() {
        let mut writer = MockWriter::new();

        // Test simple string
        let result = format_and_write(&mut writer, format_args!("Hello, World!"));
        assert!(result.is_ok());
        assert_eq!(writer.contents(), "Hello, World!");

        // Test with formatting
        let result = format_and_write(&mut writer, format_args!(" Value: {}", 42));
        assert!(result.is_ok());
        assert_eq!(writer.contents(), "Hello, World! Value: 42");
    }

    #[test]
    fn test_format_and_write_multiple_args() {
        let mut writer = MockWriter::new();

        let result = format_and_write(&mut writer, format_args!("{} {} {}", "One", "Two", "Three"));
        assert!(result.is_ok());
        assert_eq!(writer.contents(), "One Two Three");
    }

    #[test]
    fn test_format_and_write_complex_formatting() {
        let mut writer = MockWriter::new();

        let result = format_and_write(&mut writer, format_args!("{:?} {:>5} {:.2}", 
            vec![1, 2, 3], "pad", 3.14159));
        assert!(result.is_ok());
        assert_eq!(writer.contents(), "[1, 2, 3]   pad 3.14");
    }

    #[test]
    fn test_format_and_write_empty_string() {
        let mut writer = MockWriter::new();

        let result = format_and_write(&mut writer, format_args!(""));
        assert!(result.is_ok());
        assert_eq!(writer.contents(), "");
    }

    #[test]
    fn test_format_and_write_failure() {
        let mut writer = FailingWriter;

        let result = format_and_write(&mut writer, format_args!("This will fail"));
        assert!(result.is_err());

        // Check that the error is the expected kind
        if let Err(err) = result {
            assert_eq!(err.kind(), io::ErrorKind::Other);
            assert_eq!(err.to_string(), "mock write error");
        }
    }

    #[test]
    fn test_format_and_write_with_buffer() {
        let mut buffer = Vec::new();

        let result = format_and_write(&mut buffer, format_args!("Writing to a Vec<u8>"));
        assert!(result.is_ok());
        assert_eq!(String::from_utf8_lossy(&buffer), "Writing to a Vec<u8>");
    }

    #[test]
    fn test_format_and_write_with_cursor() {
        let mut cursor = io::Cursor::new(Vec::new());

        let result = format_and_write(&mut cursor, format_args!("Writing to a Cursor"));
        assert!(result.is_ok());
        assert_eq!(String::from_utf8_lossy(&cursor.into_inner()), "Writing to a Cursor");
    }
}

