fn process_chunks<T>(vec: Vec<T>, chunk_size: usize) -> Vec<Vec<T>> {
    let mut iter = vec.into_iter();
    let mut chunks = Vec::new();

    loop {
        let mut chunk = Vec::with_capacity(chunk_size);
        for _ in 0..chunk_size {
            if let Some(item) = iter.next() {
                chunk.push(item);
            } else {
                break;
            }
        }
        if chunk.is_empty() {
            break;
        }
        chunks.push(chunk);
    }

    chunks
}

