        merge_collections(&mut target, source);

        assert_eq!(target.0.len(), SIZE);
        assert_eq!(target.1.len(), SIZE);

        // Verify some elements to ensure correctness
        assert_eq!(target.0[0], 0);
        assert_eq!(target.1[0], 0);
        assert_eq!(target.0[SIZE - 1], SIZE - 1);
        assert_eq!(target.1[SIZE - 1], (SIZE - 1) * 2);
    }

    // Custom struct that implements Extend for testing
    struct ExtendableVec<T>(Vec<T>);

    impl<T> Extend<T> for ExtendableVec<T> {
        fn extend<I: IntoIterator<Item = T>>(&mut self, iter: I) {
            self.0.extend(iter);
        }
    }

    #[test]
    fn test_with_custom_extendable_types() {
        let mut target: (ExtendableVec<i32>, ExtendableVec<i32>) = (ExtendableVec(Vec::new()), ExtendableVec(Vec::new()));
        let source = vec![(1, 2), (3, 4), (5, 6)];

        merge_collections(&mut target, source);

        assert_eq!(target.0.0, vec![1, 3, 5]);
        assert_eq!(target.1.0, vec![2, 4, 6]);
    }
}

