use std::mem::MaybeUninit;

fn initialize_array<T>(array: &mut [MaybeUninit<T>], values: Vec<T>) -> &mut [T] {
    assert_eq!(array.len(), values.len(), "Array and values length mismatch");

    for (i, val) in values.into_iter().enumerate() {
        array[i].write(val);
    }

    // SAFETY: We have initialized all elements of the array.
    unsafe { &mut *(array as *mut [MaybeUninit<T>] as *mut [T]) }
}

