        // Test with edge values
        assert_eq!(safe_add(u32::MAX, 0), Some(u32::MAX));
        assert_eq!(safe_add(0, u32::MAX), Some(u32::MAX));
        assert_eq!(safe_add(u32::MAX - 1, 1), Some(u32::MAX));
    }

    #[test]
    fn test_safe_add_overflow() {
        // Test when addition would overflow
        assert_eq!(safe_add(u32::MAX, 1), None);
        assert_eq!(safe_add(1, u32::MAX), None);
        assert_eq!(safe_add(u32::MAX, u32::MAX), None);
        assert_eq!(safe_add(u32::MAX / 2 + 1, u32::MAX / 2 + 1), None);
    }

    #[test]
    fn test_safe_add_boundary_cases() {
        // Test boundary cases
        let half_max = u32::MAX / 2;
        assert_eq!(safe_add(half_max, half_max), Some(u32::MAX - 1));
        assert_eq!(safe_add(half_max + 1, half_max + 1), None);
        assert_eq!(safe_add(half_max, half_max + 1), Some(u32::MAX));
    }

    #[test]
    fn test_safe_add_commutative() {
        // Test commutativity property
        let test_cases = [
            (0, 42),
            (100, 200),
            (u32::MAX / 4, u32::MAX / 4),
        ];

        for &(a, b) in &test_cases {
            assert_eq!(safe_add(a, b), safe_add(b, a));
        }
    }
}

