#[cfg(test)]
mod tests {
    use std::io;
    use std::sync::{Arc, Mutex};
    use std::thread;
    use std::time::Duration;

    // Import the function to test
    use super::spawn_log_worker;

    #[test]
    fn test_spawn_log_worker_basic_task() -> io::Result<()> {
        let builder = thread::Builder::new().name("test_worker".to_string());

        // A simple task that returns a value
        let result_handle = unsafe {
            spawn_log_worker(builder, || {
                // Simulate some work
                thread::sleep(Duration::from_millis(10));
                42
            })
        }?;

        // Check that the thread completed and returned the expected value
        let result = result_handle.join().unwrap();
        assert_eq!(result, 42);

        Ok(())
    }

    #[test]
    fn test_spawn_log_worker_shared_data() -> io::Result<()> {
        // Create some shared data that the worker will access
        let shared_data = Arc::new(Mutex::new(Vec::new()));
        let shared_data_clone = shared_data.clone();

        let builder = thread::Builder::new().name("shared_data_worker".to_string());

        // Spawn a worker that modifies the shared data
        let handle = unsafe {
            spawn_log_worker(builder, move || {
                // Access and modify the shared data
                let mut data = shared_data_clone.lock().unwrap();
                data.push(1);
                data.push(2);
                data.push(3);

                // Return the sum
                data.iter().sum::<i32>()
            })
        }?;

        // Wait for the worker to complete
        let sum = handle.join().unwrap();

        // Verify the shared data was modified correctly
        let data = shared_data.lock().unwrap();
        assert_eq!(*data, vec![1, 2, 3]);
        assert_eq!(sum, 6);

        Ok(())
    }

    #[test]
    fn test_spawn_log_worker_stack_references() -> io::Result<()> {
        // This test demonstrates the unsafe nature of the function
        // by allowing a thread to reference stack data

        // Create a structure to hold our data
        struct LogContext {
            entries: Vec<String>,
        }

        // Set up our log context
        let log_context = LogContext {
            entries: vec!["entry1".to_string(), "entry2".to_string()],
        };

        // Create a completion flag to know when the thread is done
        let completion_flag = Arc::new(Mutex::new(false));
        let completion_flag_clone = completion_flag.clone();

        let builder = thread::Builder::new().name("stack_reference_worker".to_string());

        // SAFETY: We ensure the log_context outlives the thread
        let handle = unsafe {
            spawn_log_worker(builder, move || {
                // Access the log context (which is on the caller's stack)
                let entry_count = log_context.entries.len();

                // Set the completion flag
                let mut flag = completion_flag_clone.lock().unwrap();
                *flag = true;

                entry_count
            })
        }?;

        // Wait for the thread to complete
        let count = handle.join().unwrap();

        // Verify the thread completed successfully
        assert_eq!(count, 2);
        assert!(*completion_flag.lock().unwrap());

        Ok(())
    }

    #[test]
    fn test_spawn_log_worker_panic_handling() -> io::Result<()> {
        let builder = thread::Builder::new().name("panicking_worker".to_string());

        // Spawn a worker that will panic
        let handle = unsafe {
            spawn_log_worker(builder, || {
                panic!("This worker is supposed to panic");
            })
        }?;

        // The join should return an Err because the thread panicked
        let result = handle.join();
        assert!(result.is_err());

        Ok(())
    }

    #[test]
    fn test_spawn_log_worker_custom_thread_name() -> io::Result<()> {
        let expected_name = "custom_worker_name";
        let builder = thread::Builder::new().name(expected_name.to_string());

        // We'll use thread::current().name() to verify the thread name
        let handle = unsafe {
            spawn_log_worker(builder, || {
                let current_thread_name = thread::current().name().unwrap_or("unnamed").to_string();
                current_thread_name
            })
        }?;

        // Check that the thread had the expected name
        let thread_name = handle.join().unwrap();
        assert_eq!(thread_name, expected_name);

        Ok(())
    }

    #[test]
    fn test_spawn_log_worker_with_stack_size() -> io::Result<()> {
        // Create a builder with a custom stack size
        let stack_size = 4 * 1024 * 1024; // 4 MB
        let builder = thread::Builder::new()
            .name("stack_size_worker".to_string())
            .stack_size(stack_size);

        // Spawn a worker with the custom stack size
        let handle = unsafe {
            spawn_log_worker(builder, || {
                // Just return true to indicate success
                true
            })
        }?;

        // Check that the thread completed successfully
        let result = handle.join().unwrap();
        assert!(result);

        Ok(())
    }
}

