mod tests {
    use super::*;
    use std::cell::Cell;

    #[test]
    fn test_empty_sequence() {
        // Empty sequence (count = 0)
        let sequence: Vec<i32> = generate_random_sequence(|| 42, 0).collect();
        assert_eq!(sequence.len(), 0);
        assert!(sequence.is_empty());
    }

    #[test]
    fn test_specific_count() {
        // Test with specific count
        let count = 5;
        let sequence: Vec<i32> = generate_random_sequence(|| 42, count).collect();
        assert_eq!(sequence.len(), count);

        // All elements should be the constant we're generating
        for item in sequence {
            assert_eq!(item, 42);
        }
    }

    #[test]
    fn test_generator_called_correct_number_of_times() {
        // Test that generator is called exactly 'count' times
        let call_count = Cell::new(0);

        let generator = || {
            let current = call_count.get();
            call_count.set(current + 1);
            current
        };

        let count = 10;
        let sequence: Vec<usize> = generate_random_sequence(generator, count).collect();

        assert_eq!(call_count.get(), count);
        assert_eq!(sequence, (0..count).collect::<Vec<_>>());
    }

    #[test]
    fn test_different_types() {
        // Test with different output types

        // String type
        let string_sequence: Vec<String> = generate_random_sequence(|| "test".to_string(), 3).collect();
        assert_eq!(string_sequence.len(), 3);
        for s in string_sequence {
            assert_eq!(s, "test");
        }

        // Boolean type
        let bool_sequence: Vec<bool> = generate_random_sequence(|| true, 4).collect();
        assert_eq!(bool_sequence.len(), 4);
        for b in bool_sequence {
            assert!(b);
        }

        // Custom struct
        struct TestStruct(i32);
        let struct_sequence: Vec<TestStruct> = generate_random_sequence(|| TestStruct(123), 2).collect();
        assert_eq!(struct_sequence.len(), 2);
        for s in struct_sequence {
            assert_eq!(s.0, 123);
        }
    }

    #[test]
    fn test_mutable_state() {
        // Test with a stateful generator
        let mut counter = 0;

        let generator = move || {
            counter += 1;
            counter
        };

        let count = 5;
        let sequence: Vec<i32> = generate_random_sequence(generator, count).collect();

        assert_eq!(sequence, vec![1, 2, 3, 4, 5]);
    }

    #[test]
    fn test_large_count() {
        // Test with a large count to verify no performance issues
        const LARGE_COUNT: usize = 10_000;

        let sequence: Vec<u8> = generate_random_sequence(|| 1, LARGE_COUNT).collect();
        assert_eq!(sequence.len(), LARGE_COUNT);
    }

    #[test]
    fn test_lazy_evaluation() {
        // Test lazy evaluation - iterator should only generate values when consumed
        let evaluation_count = Cell::new(0);

        let iterator = generate_random_sequence(|| {
            let current = evaluation_count.get();
            evaluation_count.set(current + 1);
            current + 1
        }, 10);

        // At this point, nothing should be evaluated yet
        assert_eq!(evaluation_count.get(), 0);

        // Take only first 5 elements
        let partial: Vec<i32> = iterator.take(5).collect();

        // Only 5 evaluations should have happened
        assert_eq!(evaluation_count.get(), 5);
        assert_eq!(partial, vec![1, 2, 3, 4, 5]);
    }
}

