fn repeat_elements<T: Clone>(elements: impl Iterator<Item = T>, count: usize) -> impl Iterator<Item = T> {
    elements.flat_map(move |element| {
        let element_clone = element.clone();
        std::iter::repeat(element_clone).take(count)
    })
}

