        assert!(is_production_efficient(scores.into_iter(), |a, b| a <= b));
    }

    #[test]
    fn test_partially_increasing_integers() {
        let scores = vec![1, 2, 3, 2, 4];
        assert!(!is_production_efficient(scores.into_iter(), |a, b| a <= b));
    }

    #[test]
    fn test_empty_sequence() {
        let scores: Vec<i32> = vec![];
        assert!(is_production_efficient(scores.into_iter(), |a, b| a <= b));
    }

