    fn test_shared_reference_count() {
        let slice: Rc<[MaybeUninit<u8>]> = create_shared_uninit_slice(10);

        assert_eq!(Rc::strong_count(&slice), 1);

        {
            let _clone = Rc::clone(&slice);
            assert_eq!(Rc::strong_count(&slice), 2);
        }

        assert_eq!(Rc::strong_count(&slice), 1);
    }

    #[test]
    fn test_write_and_read() {
        // Create a shared slice for integers
        let slice: Rc<[MaybeUninit<i32>]> = create_shared_uninit_slice(5);

        // Get a mutable reference to the underlying slice
        // This is safe because we have the only reference to this Rc at this point
        // In real code, you would need to ensure exclusive access (e.g., with RefCell or Mutex)
        let slice_ptr = Rc::as_ptr(&slice) as *mut [MaybeUninit<i32>];

        unsafe {
            // Write values to the uninitialized memory
            for i in 0..5 {
                (*slice_ptr)[i].write(i as i32 * 10);
            }

            // Read values back (via assuming initialized)
            for i in 0..5 {
                let value = (*slice_ptr)[i].assume_init_ref();
                assert_eq!(*value, i as i32 * 10);
            }
        }
    }

    #[test]
    fn test_zero_sized_type() {
        // Test with a zero-sized type
        let slice: Rc<[MaybeUninit<()>]> = create_shared_uninit_slice(100);
        assert_eq!(slice.len(), 100);
    }

