    fn test_multiple_references() {
        let original: Rc<[MaybeUninit<u32>]> = create_shared_uninit_slice(5);

        let ref1 = Rc::clone(&original);
        let ref2 = Rc::clone(&original);
        let ref3 = Rc::clone(&original);

