mod tests {
    use std::mem::MaybeUninit;
    use std::sync::Arc;
    use std::thread;

    // Import the function from parent module
    use super::create_shared_uninit_array;

    #[test]
    fn test_create_shared_uninit_array_size() {
        // Test with different types and sizes
        let array: Arc<[MaybeUninit<u8>]> = create_shared_uninit_array(10);
        assert_eq!(array.len(), 10);

        let array: Arc<[MaybeUninit<u64>]> = create_shared_uninit_array(5);
        assert_eq!(array.len(), 5);

        let array: Arc<[MaybeUninit<String>]> = create_shared_uninit_array(0);
        assert_eq!(array.len(), 0);
    }

    #[test]
    fn test_arc_strong_count() {
        // Test that the Arc has the correct initial reference count
        let array: Arc<[MaybeUninit<i32>]> = create_shared_uninit_array(3);
        assert_eq!(Arc::strong_count(&array), 1);

        // Clone the Arc and check reference count
        let cloned = array.clone();
        assert_eq!(Arc::strong_count(&array), 2);
        assert_eq!(Arc::strong_count(&cloned), 2);

        // Drop one reference and check again
        drop(cloned);
        assert_eq!(Arc::strong_count(&array), 1);
    }

    #[test]
    fn test_shared_across_threads() {
        // Test that the array can be shared across threads properly
        let array: Arc<[MaybeUninit<u32>]> = create_shared_uninit_array(1000);

        // Create multiple threads that access the array
        let mut handles = vec![];

        for _ in 0..10 {
            let thread_array = array.clone();

            let handle = thread::spawn(move || {
                // Just verify we can access the array and its length
                assert_eq!(thread_array.len(), 1000);

                // Verify the strong count is at least 2 (main thread + this thread)
                assert!(Arc::strong_count(&thread_array) >= 2);
            });

            handles.push(handle);
        }

        // Wait for all threads to complete
        for handle in handles {
            handle.join().unwrap();
        }

        // After all threads complete, we should be back to just one reference
        assert_eq!(Arc::strong_count(&array), 1);
    }

    #[test]
    fn test_with_custom_struct() {
        // Test with a custom struct type
        struct TestStruct {
            value: i32,
            name: String,
        }

        let size = 5;
        let array: Arc<[MaybeUninit<TestStruct>]> = create_shared_uninit_array(size);

        assert_eq!(array.len(), size);
    }

    #[test]
    fn test_write_and_read() {
        // Test that we can write to and read from the array safely
        let array: Arc<[MaybeUninit<i32>]> = create_shared_uninit_array(3);

        // Write directly to the array elements
        unsafe {
            // We need to get a mutable pointer to the elements
            let ptr = Arc::as_ptr(&array) as *mut [MaybeUninit<i32>];
            (*ptr)[0].write(42);
            (*ptr)[1].write(100);
            (*ptr)[2].write(-7);

            // Read back the values
            assert_eq!((*array[0].as_ptr()), 42);
            assert_eq!((*array[1].as_ptr()), 100);
            assert_eq!((*array[2].as_ptr()), -7);
        }
    }

    #[test]
    fn test_large_allocation() {
        // Test allocating a large array
        const LARGE_SIZE: usize = 1_000_000;
        let array: Arc<[MaybeUninit<u8>]> = create_shared_uninit_array(LARGE_SIZE);

        assert_eq!(array.len(), LARGE_SIZE);
    }

    #[test]
    fn test_zero_size_type() {
        // Test with a zero-sized type
        struct ZeroSized;

        let array: Arc<[MaybeUninit<ZeroSized>]> = create_shared_uninit_array(100);
        assert_eq!(array.len(), 100);
    }
