#[cfg(test)]
mod tests {
    use std::rc::Rc;

    // Import the function we're testing
    use super::extract_unique_value;

    #[test]
    fn test_unique_reference() {
        // Create a single reference to a value
        let rc = Rc::new(42);

        // Since there's only one reference, extraction should succeed
        let result = extract_unique_value(rc);

        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 42);
    }

    #[test]
    fn test_multiple_references() {
        // Create a reference
        let rc1 = Rc::new(String::from("test"));

        // Create a second reference to the same value
        let rc2 = Rc::clone(&rc1);

        // Try to extract from one of the references
        let result = extract_unique_value(rc1);

        // Should fail because rc2 is still alive
        assert!(result.is_err());

        // The returned error should be the original Rc
        let returned_rc = result.unwrap_err();
        assert_eq!(*returned_rc, "test");

        // Strong count should be 2 (rc2 and returned_rc)
        assert_eq!(Rc::strong_count(&returned_rc), 2);
        assert_eq!(Rc::strong_count(&rc2), 2);
    }

    #[test]
    fn test_with_complex_type() {
        // Test with a more complex type
        #[derive(Debug, PartialEq)]
        struct TestStruct {
            x: i32,
            y: String,
        }

        let test_struct = TestStruct {
            x: 10,
            y: String::from("hello"),
        };

        let rc = Rc::new(test_struct);

        // Extract the unique value
        let result = extract_unique_value(rc);

        assert!(result.is_ok());

        let extracted = result.unwrap();
        assert_eq!(extracted.x, 10);
        assert_eq!(extracted.y, "hello");
    }

    #[test]
    fn test_reference_dropped_before_extraction() {
        // Create two references
        let rc1 = Rc::new(100);
        let rc2 = Rc::clone(&rc1);

        // Verify we have two references
        assert_eq!(Rc::strong_count(&rc1), 2);

        // Drop the second reference
        drop(rc2);

        // Now we should be able to extract
        let result = extract_unique_value(rc1);

        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 100);
    }

    #[test]
    fn test_with_zero_sized_type() {
        // Test with a zero-sized type
        #[derive(Debug)]
        struct ZeroSized;

        let rc = Rc::new(ZeroSized);
        let result = extract_unique_value(rc);

        assert!(result.is_ok());

        // We can't really check the value of a ZST, 
        // but we can check that extraction succeeded
        let _ = result.unwrap();
    }

    #[test]
    fn test_with_nested_rc() {
        // Test with nested Rc
        let inner_rc = Rc::new(42);
        let outer_rc = Rc::new(inner_rc);

        // Extract the outer Rc
        let result = extract_unique_value(outer_rc);

        assert!(result.is_ok());

        // Now we should have the inner Rc
        let inner = result.unwrap();
        assert_eq!(*inner, 42);

        // The inner Rc should still be reference counted
        assert_eq!(Rc::strong_count(&inner), 1);
    }
}

