#[cfg(test)]
mod tests {
    use super::*;
    use std::f64::{INFINITY, NEG_INFINITY, NAN};
    use std::mem;

    #[test]
    fn test_normal_values() {
        // Test some basic normal values
        assert_eq!(convert_bits_to_f64(0x3FF0000000000000), 1.0);
        assert_eq!(convert_bits_to_f64(0x4000000000000000), 2.0);
        assert_eq!(convert_bits_to_f64(0x4008000000000000), 3.0);
        assert_eq!(convert_bits_to_f64(0xBFF0000000000000), -1.0);
        assert_eq!(convert_bits_to_f64(0xC000000000000000), -2.0);
    }

    #[test]
    fn test_special_values() {
        // Test zero (positive and negative)
        assert_eq!(convert_bits_to_f64(0x0000000000000000), 0.0);
        assert_eq!(convert_bits_to_f64(0x8000000000000000), -0.0);

        // Test infinity (positive and negative)
        assert_eq!(convert_bits_to_f64(0x7FF0000000000000), INFINITY);
        assert_eq!(convert_bits_to_f64(0xFFF0000000000000), NEG_INFINITY);

        // Test that retrieved bit patterns match original patterns
        let pos_inf_bits = INFINITY.to_bits();
        let neg_inf_bits = NEG_INFINITY.to_bits();
        assert_eq!(convert_bits_to_f64(pos_inf_bits), INFINITY);
        assert_eq!(convert_bits_to_f64(neg_inf_bits), NEG_INFINITY);
    }

    #[test]
    fn test_nan_values() {
        // Test a standard NaN value
        let nan_bits = 0x7FF8000000000000;
        let nan_value = convert_bits_to_f64(nan_bits);
        assert!(nan_value.is_nan());

        // Test a few different NaN bit patterns
        assert!(convert_bits_to_f64(0x7FF0000000000001).is_nan()); // Signaling NaN
        assert!(convert_bits_to_f64(0x7FF8000000000001).is_nan()); // Different quiet NaN
        assert!(convert_bits_to_f64(0xFFF8000000000000).is_nan()); // Negative NaN

        // Test that NaN bit patterns are preserved
        // Note: We can't directly compare NaN values with ==, so we compare their bit patterns
        let custom_nan_bits = 0x7FF0000000000123;
        let custom_nan = convert_bits_to_f64(custom_nan_bits);
        assert!(custom_nan.is_nan());
        assert_eq!(custom_nan.to_bits(), custom_nan_bits);
    }

    #[test]
    fn test_subnormal_values() {
        // Test smallest positive subnormal number
        assert_eq!(convert_bits_to_f64(0x0000000000000001), 5.0e-324);

        // Test largest subnormal number (just below the smallest normal number)
        assert_eq!(convert_bits_to_f64(0x000FFFFFFFFFFFFF), 2.225073858507201e-308);

        // Test negative subnormal numbers
        assert_eq!(convert_bits_to_f64(0x8000000000000001), -5.0e-324);
        assert_eq!(convert_bits_to_f64(0x800FFFFFFFFFFFFF), -2.225073858507201e-308);
    }

    #[test]
    fn test_round_trip() {
        // Test that conversion preserves bit patterns for various values
        let test_values = [
            0.0f64, -0.0f64, 1.0f64, -1.0f64, 
            f64::MIN, f64::MAX, 
            f64::MIN_POSITIVE, 
            INFINITY, NEG_INFINITY,
            3.14159265358979323846f64,
            2.718281828459045f64,
            1.0e-100f64, 1.0e100f64
        ];

        for &value in &test_values {
            let bits = value.to_bits();
            let roundtrip = convert_bits_to_f64(bits);

            // Use bit comparison to ensure exact representation is preserved
            assert_eq!(roundtrip.to_bits(), bits);
        }
    }

    #[test]
    fn test_denormal_to_normal_boundary() {
        // Test values at the boundary between denormal and normal numbers
        let smallest_normal = 2.2250738585072014e-308f64;
        let largest_subnormal = 2.225073858507201e-308f64;

        let smallest_normal_bits = smallest_normal.to_bits();
        let largest_subnormal_bits = largest_subnormal.to_bits();

        assert_eq!(convert_bits_to_f64(smallest_normal_bits), smallest_normal);
        assert_eq!(convert_bits_to_f64(largest_subnormal_bits), largest_subnormal);

        // Verify that these are actually different values
        assert!(smallest_normal > largest_subnormal);
        assert_eq!(smallest_normal_bits, 0x0010000000000000);
        assert_eq!(largest_subnormal_bits, 0x000FFFFFFFFFFFFF);
    }

    #[test]
    fn test_bitwise_operations() {
        // Test that bit-level operations work correctly after conversion
        let original_bits = 0x3FF0000000000000; // 1.0
        let modified_bits = original_bits ^ 0x8000000000000000; // Flip sign bit to get -1.0

        assert_eq!(convert_bits_to_f64(original_bits), 1.0);
        assert_eq!(convert_bits_to_f64(modified_bits), -1.0);

        // Test incremental bit changes
        let almost_two = 0x3FFFFFFFFFFFFFFF; // Just below 2.0
        let exactly_two = 0x4000000000000000; // Exactly 2.0

        let almost_two_f64 = convert_bits_to_f64(almost_two);
        let exactly_two_f64 = convert_bits_to_f64(exactly_two);

        assert!(almost_two_f64 < 2.0);
        assert_eq!(exactly_two_f64, 2.0);
        assert!(almost_two_f64 < exactly_two_f64);
    }

    #[test]
    fn test_transmute_equivalence() {
        // Test that our implementation behaves the same as transmute
        // when it's expected to (for normal values)
        let test_bits = 0x3FF0000000000000; // 1.0

        let transmuted: f64 = unsafe { mem::transmute(test_bits) };
        let converted = convert_bits_to_f64(test_bits);

        assert_eq!(transmuted, converted);
        assert_eq!(transmuted.to_bits(), converted.to_bits());
    }
}

