#[cfg(test)]
mod tests {
    use std::sync::Arc;
    use std::ptr;
    use std::sync::atomic::{AtomicUsize, Ordering};

    // Import the function we're testing
    use super::convert_arc_to_raw;

    #[test]
    fn test_convert_arc_to_raw_preserves_data() {
        // Arrange
        let data = 42;
        let arc = Arc::new(data);
        let expected = &*arc as *const i32;

        // Act
        let raw_ptr = convert_arc_to_raw(arc.clone());

        // Assert
        assert_eq!(raw_ptr, expected);

        // Ensure data can be accessed through raw pointer
        unsafe {
            assert_eq!(*raw_ptr, 42);
        }

        // Clean up to avoid memory leak
        unsafe {
            let _ = Arc::from_raw(raw_ptr);
        }
    }

    #[test]
    fn test_convert_arc_to_raw_preserves_reference_count() {
        // Arrange
        let arc = Arc::new(100);
        let arc_clone = arc.clone(); // Create a clone to ensure count > 1

        // The initial reference count should be 2
        let initial_count = Arc::strong_count(&arc);
        assert_eq!(initial_count, 2);

        // Act
        let raw_ptr = convert_arc_to_raw(arc);

        // Assert
        // Reference count should still be 2 (one from arc_clone, one from the raw pointer)
        // We must reconstruct an Arc to check the count
        let reconstructed_arc = unsafe { Arc::from_raw(raw_ptr) };
        assert_eq!(Arc::strong_count(&reconstructed_arc), initial_count);

        // We need to forget the reconstructed_arc to avoid decreasing the count
        // otherwise we would double-free when arc_clone goes out of scope
        std::mem::forget(reconstructed_arc);

        // Clean up to avoid memory leak
        unsafe {
            let _ = Arc::from_raw(raw_ptr);
        }

        // Verify arc_clone is still valid
        assert_eq!(*arc_clone, 100);
    }

    #[test]
    fn test_convert_arc_to_raw_with_complex_type() {
        // Test with a more complex struct
        struct TestStruct {
            value: i32,
            name: String,
        }

        let test_data = TestStruct {
            value: 123,
            name: "test".to_string(),
        };

        let arc = Arc::new(test_data);

        // Act
        let raw_ptr = convert_arc_to_raw(arc.clone());

        // Assert
        unsafe {
            assert_eq!((*raw_ptr).value, 123);
            assert_eq!((*raw_ptr).name, "test");
        }

        // Clean up
        unsafe {
            let _ = Arc::from_raw(raw_ptr);
        }
    }

    #[test]
    fn test_convert_arc_to_raw_with_drop_counter() {
        // Use an AtomicUsize to count drops
        static DROP_COUNTER: AtomicUsize = AtomicUsize::new(0);

        struct DropCounter;

        impl Drop for DropCounter {
            fn drop(&mut self) {
                DROP_COUNTER.fetch_add(1, Ordering::SeqCst);
            }
        }

        // Reset counter
        DROP_COUNTER.store(0, Ordering::SeqCst);

        // Create scope to control when values are dropped
        {
            let arc = Arc::new(DropCounter);
            let _arc_clone = arc.clone(); // Create a clone

            // Convert to raw
            let raw_ptr = convert_arc_to_raw(arc);

            // At this point, no drop should have occurred
            assert_eq!(DROP_COUNTER.load(Ordering::SeqCst), 0);

            // We need to convert back to Arc for the raw pointer before the scope ends
            unsafe {
                let _reconstructed = Arc::from_raw(raw_ptr);
                // _reconstructed will be dropped at end of scope
            }

            // _arc_clone will be dropped at end of scope
        }

        // After scope, both arcs should have been dropped, triggering one drop of the inner value
        assert_eq!(DROP_COUNTER.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn test_convert_arc_to_raw_with_zero_sized_type() {
        // Test with a zero-sized type
        struct ZeroSized;

        let arc = Arc::new(ZeroSized);
        let ptr_before = &*arc as *const ZeroSized;

        let raw_ptr = convert_arc_to_raw(arc);

        // Even for ZSTs, the pointer should be valid (though may not be meaningful)
        assert!(!raw_ptr.is_null());

        // Clean up
        unsafe {
            let _ = Arc::from_raw(raw_ptr);
        }
    }

    #[test]
    fn test_convert_arc_to_raw_multiple_conversions() {
        // Test that multiple conversions work correctly
        let data = vec![1, 2, 3, 4, 5];
        let arc1 = Arc::new(data);
        let arc2 = arc1.clone();
        let arc3 = arc1.clone();

        let raw_ptr1 = convert_arc_to_raw(arc1);
        let raw_ptr2 = convert_arc_to_raw(arc2);

        // Both pointers should point to the same data
        assert_eq!(raw_ptr1, raw_ptr2);

        // Data should be accessible through both pointers
        unsafe {
            assert_eq!((*raw_ptr1)[0], 1);
            assert_eq!((*raw_ptr2)[4], 5);
        }

        // Reference count check
        let reconstructed = unsafe { Arc::from_raw(raw_ptr1) };
        // One reference from arc3, one from reconstructed, and raw_ptr2
        assert_eq!(Arc::strong_count(&reconstructed), 3);

        // Clean up to avoid memory leaks
        std::mem::forget(reconstructed);
        unsafe {
            let _ = Arc::from_raw(raw_ptr1);
            let _ = Arc::from_raw(raw_ptr2);
        }
    }
}

