use std::mem::align_of;

fn safe_align_offset<T>(ptr: *const T, align: usize, buffer_len: usize) -> Option<usize>
where
    T: Sized,
{
    if !align.is_power_of_two() {
        return None;
    }

    let offset = ptr.align_offset(align);
    if offset == usize::MAX || offset >= buffer_len {
        None
    } else {
        Some(offset)
    }
}

