#[cfg(test)]
mod tests {
    use super::*;
    use std::mem::align_of;

    #[test]
    fn test_alignment_success() {
        let buffer = [0u8; 100];
        let ptr = buffer.as_ptr();

        // Try to align to 8 bytes (common alignment)
        let offset = safe_align_offset(ptr, 8, buffer.len());

        // Calculate expected offset manually for verification
        let addr = ptr as usize;
        let expected = if addr % 8 == 0 {
            0
        } else {
            8 - (addr % 8)
        };

        assert_eq!(offset, Some(expected));
    }

    #[test]
    fn test_already_aligned() {
        // Create an aligned buffer
        let buffer = [0u8; 100];
        let ptr = buffer.as_ptr();

        // Find an alignment that the pointer already satisfies
        let mut current_alignment = 1usize;
        while current_alignment <= 64 && (ptr as usize) % current_alignment == 0 {
            let offset = safe_align_offset(ptr, current_alignment, buffer.len());
            assert_eq!(offset, Some(0), "Should return 0 offset for already aligned pointer");

            // Only test power of two alignments
            current_alignment *= 2;
        }
    }

    #[test]
    fn test_non_power_of_two_alignment() {
        let buffer = [0u8; 100];
        let ptr = buffer.as_ptr();

        // Try various non-power-of-two alignments
        assert_eq!(safe_align_offset(ptr, 3, buffer.len()), None);
        assert_eq!(safe_align_offset(ptr, 6, buffer.len()), None);
        assert_eq!(safe_align_offset(ptr, 10, buffer.len()), None);
        assert_eq!(safe_align_offset(ptr, 15, buffer.len()), None);
    }

    #[test]
    fn test_buffer_too_small() {
        let buffer = [0u8; 16];
        let ptr = buffer.as_ptr();

        // Calculate the current alignment and find an alignment that would require an offset
        let addr = ptr as usize;
        let align = 256; // Large alignment that likely exceeds buffer size

        // Determine what the offset would be (if buffer were large enough)
        let theoretical_offset = if addr % align == 0 {
            0
        } else {
            align - (addr % align)
        };

        // If the theoretical offset is greater than buffer length, test should return None
        if theoretical_offset >= buffer.len() {
            assert_eq!(safe_align_offset(ptr, align, buffer.len()), None);
        }
    }

    #[test]
    fn test_different_types() {
        // Test with different sized types

        // u8 array
        let buffer_u8 = [0u8; 100];
        let ptr_u8 = buffer_u8.as_ptr();
        let align_u8 = align_of::<u64>(); // 8 bytes alignment
        let offset_u8 = safe_align_offset(ptr_u8, align_u8, buffer_u8.len());
        assert!(offset_u8.is_some());

        // u32 array
        let buffer_u32 = [0u32; 25];
        let ptr_u32 = buffer_u32.as_ptr();
        let align_u32 = align_of::<u64>(); // 8 bytes alignment
        let offset_u32 = safe_align_offset(ptr_u32, align_u32, buffer_u32.len());
        assert!(offset_u32.is_some());

        // Custom struct
        #[repr(C)]
        #[derive(Copy, Clone)]  // Added Clone and Copy traits
        struct TestStruct {
            a: u32,
            b: u64,
        }

        // Create the buffer with Copy trait now implemented
        let test_struct = TestStruct { a: 0, b: 0 };
        let buffer_struct = vec![test_struct; 10];
        let ptr_struct = buffer_struct.as_ptr();
        let align_struct = align_of::<TestStruct>(); // Should be 8 due to u64
        let offset_struct = safe_align_offset(ptr_struct, align_struct * 2, buffer_struct.len());
        // Since TestStruct is already aligned to align_of::<TestStruct>(), the offset for
        // align_struct * 2 may or may not be possible, so we don't assert specific values
    }

    #[test]
    fn test_edge_cases() {
        // Test with empty buffer
        let buffer: [u8; 0] = [];
        let ptr = buffer.as_ptr();
        assert_eq!(safe_align_offset(ptr, 4, buffer.len()), None);

        // Test with minimal buffer
        let buffer = [0u8; 1];
        let ptr = buffer.as_ptr();

        // For a 1-byte buffer, any alignment greater than 1 that isn't already satisfied
        // should return None
        if (ptr as usize) % 2 != 0 {
            assert_eq!(safe_align_offset(ptr, 2, buffer.len()), None);
        }

        // Test with alignment of 1 (should always work and return 0)
        assert_eq!(safe_align_offset(ptr, 1, buffer.len()), Some(0));

        // Test with very large alignment
        let buffer = [0u8; 4096];
        let ptr = buffer.as_ptr();
        let large_align = 2048;

        // Calculate expected offset
        let addr = ptr as usize;
        let expected = if addr % large_align == 0 {
            Some(0)
        } else if large_align - (addr % large_align) < buffer.len() {
            Some(large_align - (addr % large_align))
        } else {
            None
        };

        assert_eq!(safe_align_offset(ptr, large_align, buffer.len()), expected);
    }
}

