        let mut vec = Vec::<i32>::with_capacity(2);
        vec.push(1);
        vec.push(2);
        // This should cause a resize
        vec.push(3);
        let capacity = get_compile_time_capacity(&vec);
        // Capacity should be greater than 3, but the exact value depends on the 
        // growth strategy of Vec. It's typically doubled, so 4 is expected.
        assert!(capacity >= 3);
    }

