        let vec_string = vec![String::from("hello"), String::from("world")];
        let ptr_string = get_const_ptr(&vec_string);

        // Check that the pointer points to the first element
        assert_eq!(unsafe { &*ptr_string }, &vec_string[0]);

        // Test with an empty vector
        let empty_vec: Vec<u8> = Vec::new();
        let empty_ptr = get_const_ptr(&empty_vec);

        // For an empty vector, the pointer should be non-null but not dereferenceable
        assert_ne!(empty_ptr, ptr::null());
    }

    #[test]
    fn test_get_const_ptr_matches_as_ptr() {
        // Verify that get_const_ptr returns the same pointer as Vec::as_ptr()
        let vec = vec!["test", "vector", "content"];
        let expected_ptr = vec.as_ptr();
        let actual_ptr = get_const_ptr(&vec);

        assert_eq!(actual_ptr, expected_ptr);
    }

    #[test]
    fn test_get_const_ptr_with_custom_type() {
        // Define a custom struct to test with a non-primitive type
        #[derive(Debug, PartialEq)]
        struct TestStruct {
            x: i32,
            y: f64,
        }

        let vec = vec![
            TestStruct { x: 1, y: 1.0 },
            TestStruct { x: 2, y: 2.0 },
        ];

        let ptr = get_const_ptr(&vec);

        // Check that the pointer points to the first element
        assert_eq!(unsafe { &*ptr }, &vec[0]);
    }

    #[test]
    fn test_pointer_arithmetic() {
        let vec = vec![10, 20, 30, 40];
        let ptr = get_const_ptr(&vec);

        // Use pointer arithmetic to access elements (this is unsafe and just for testing)
        unsafe {
            assert_eq!(*ptr, 10);
            assert_eq!(*ptr.add(1), 20);
            assert_eq!(*ptr.add(2), 30);
            assert_eq!(*ptr.add(3), 40);
        }
    }

    #[test]
    fn test_get_const_ptr_preserves_const() {
        // This test ensures the returned pointer is truly a *const T
        // We can't compile-time check this, but we can ensure we can't mutate through it

        let vec = vec![100, 200, 300];
        let ptr = get_const_ptr(&vec);

        // The following line would fail to compile if uncommented:
        // unsafe { *(ptr as *mut i32) = 999; } // Casting required to mutate

        // Instead just verify we can read through it
        assert_eq!(unsafe { *ptr }, 100);
    }

    #[test]
    fn test_with_zero_capacity_vec() {
        // Create a vector with zero capacity
        let vec: Vec<i32> = Vec::with_capacity(0);
        let ptr = get_const_ptr(&vec);

        // Pointer should be non-null even for zero capacity vector
        assert_ne!(ptr, ptr::null());
    }
}

