    fn test_bmp_characters() {
        // Characters from Basic Multilingual Plane (BMP) are 1 UTF-16 code unit each
        // Latin, Greek, Cyrillic, etc.
        assert_eq!(calculate_utf16_units("áéíóú"), 5); // Latin accented chars
        assert_eq!(calculate_utf16_units("αβγδε"), 5); // Greek
        assert_eq!(calculate_utf16_units("абвгд"), 5); // Cyrillic
        assert_eq!(calculate_utf16_units("你好世界"), 4); // Chinese
    }

