    fn test_supplementary_characters() {
        // Characters outside BMP require 2 UTF-16 code units each (surrogate pairs)
        // Emoji, mathematical symbols, rare scripts, etc.

        // "𐐷" U+10437 (DESERET SMALL YEE) requires 2 UTF-16 code units
        assert_eq!(calculate_utf16_units("𐐷"), 2);

        // "𠜎" U+2070E (CJK UNIFIED IDEOGRAPH-2070E) requires 2 UTF-16 code units
        assert_eq!(calculate_utf16_units("𠜎"), 2);

        // "😀" U+1F600 (GRINNING FACE) requires 2 UTF-16 code units
        assert_eq!(calculate_utf16_units("😀"), 2);
    }

