        // "a" (1 unit) + "😀" (2 units) + "b" (1 unit) = 4 UTF-16 code units
        assert_eq!(calculate_utf16_units("a😀b"), 4);

        // "Hello" (5 units) + "😀" (2 units) + "World" (5 units) = 12 UTF-16 code units
        assert_eq!(calculate_utf16_units("Hello😀World"), 12);

        // "你好" (2 units) + "😀" (2 units) + "世界" (2 units) = 6 UTF-16 code units
        assert_eq!(calculate_utf16_units("你好😀世界"), 6);
    }

