    // A basic struct that holds a reference to itself
    struct Node {
        id: usize,
        parent: Weak<Node>,
        // Adding some data to make tests more meaningful
        children: RefCell<Vec<Arc<Node>>>,
    }

    // A more complex struct for additional testing
    struct Graph {
        id: String,
        nodes: RefCell<Vec<Arc<Node>>>,
        self_ref: Weak<Graph>,
    }

    #[test]
    fn test_basic_self_reference() {
        let node = create_self_referential(|self_ref| {
            Node {
                id: 42,
                parent: self_ref.clone(),
                children: RefCell::new(Vec::new()),
            }
        });

        // Verify the self-reference works
        let parent_ref = node.parent.upgrade().unwrap();
        assert_eq!(Arc::ptr_eq(&node, &parent_ref), true);
        assert_eq!(node.id, 42);
    }

    #[test]
    fn test_complex_structure() {
        let graph = create_self_referential(|self_ref| {
            Graph {
                id: "test_graph".to_string(),
                nodes: RefCell::new(Vec::new()),
                self_ref: self_ref.clone(),
            }
        });

        // Verify the self-reference
        let self_ref = graph.self_ref.upgrade().unwrap();
        assert_eq!(Arc::ptr_eq(&graph, &self_ref), true);
        assert_eq!(graph.id, "test_graph");
    }

    #[test]
    fn test_add_children_using_self_ref() {
        let root = create_self_referential(|self_ref| {
            Node {
                id: 1,
                parent: self_ref.clone(),
                children: RefCell::new(Vec::new()),
            }
        });

        // Create child nodes that reference the parent
        for i in 2..5 {
            let child = create_self_referential(|child_self_ref| {
                Node {
                    id: i,
                    parent: root.parent.clone(), // This should be a weak reference to root
                    children: RefCell::new(Vec::new()),
                }
            });

            // Add the child to parent's children
            root.children.borrow_mut().push(child);
        }

        // Verify structure
        assert_eq!(root.children.borrow().len(), 3);

        // Verify the parent references in children
        for child in root.children.borrow().iter() {
            let parent_ref = child.parent.upgrade().unwrap();
            assert_eq!(Arc::ptr_eq(&root, &parent_ref), true);
        }
    }

    #[test]
    fn test_dropping_references() {
        // Use an outer scope to control when root is dropped
        let child_arc = {
            let root = create_self_referential(|self_ref| {
                Node {
                    id: 100,
                    parent: self_ref.clone(),
                    children: RefCell::new(Vec::new()),
                }
            });

            // Create a child and keep it alive outside this scope
            let child = create_self_referential(|child_self_ref| {
                Node {
                    id: 101,
                    parent: root.parent.clone(),
                    children: RefCell::new(Vec::new()),
                }
            });

            // Add child to parent
            root.children.borrow_mut().push(child.clone());

            // Return child to outer scope
            child
        };

        // Now root should be dropped, and child's parent weak reference should be dangling
        assert_eq!(child_arc.parent.upgrade().is_none(), true);
    }

    #[test]
    fn test_panic_handling() {
        // Test that the function handles panics in initialization gracefully
        // This is done by checking that no resources are leaked

        use std::panic::{catch_unwind, AssertUnwindSafe};

        let result = catch_unwind(AssertUnwindSafe(|| {
            create_self_referential(|_self_ref| {
                // This will panic during initialization
                panic!("Intentional panic for testing");
            })
        }));

        assert!(result.is_err());
        // If we reach here without segfaults or other issues, the test passes
        // The precise cleanup behavior depends on Arc::new_cyclic's implementation
    }

    #[test]
    fn test_mutability_through_refcell() {
        let node = create_self_referential(|self_ref| {
            Node {
                id: 200,
                parent: self_ref.clone(),
                children: RefCell::new(Vec::new()),
            }
        });

        // Modify the node after creation
        node.children.borrow_mut().push(
            create_self_referential(|child_self_ref| {
                Node {
                    id: 201,
                    parent: node.parent.clone(),
                    children: RefCell::new(Vec::new()),
                }
            })
        );

        assert_eq!(node.children.borrow().len(), 1);
        assert_eq!(node.children.borrow()[0].id, 201);
    }

    #[test]
    fn test_strong_count() {
        let node = create_self_referential(|self_ref| {
            Node {
                id: 300,
                parent: self_ref.clone(),
                children: RefCell::new(Vec::new()),
            }
        });

        // Should be 1 because there's only one Arc to the node
        assert_eq!(Arc::strong_count(&node), 1);

        // Create a clone to increase the count
        let node_clone = node.clone();
        assert_eq!(Arc::strong_count(&node), 2);

        // The weak reference shouldn't affect the strong count
        assert_eq!(node.parent.strong_count(), 2);

        // Drop the clone
        drop(node_clone);
        assert_eq!(Arc::strong_count(&node), 1);
    }
}

