        let capacity = const_capacity(&s);
        assert!(capacity >= 5, "Capacity should be at least the length of the string");
    }

    #[test]
    fn test_with_reserve() {
        let mut s = String::from("test");
        s.reserve(100);
        assert!(const_capacity(&s) >= 100, "Capacity should be at least the reserved amount");
    }

    #[test]
    fn test_capacity_after_push() {
        let mut s = String::from("test");
        let initial_capacity = const_capacity(&s);

        // Push characters until we're likely to trigger a reallocation
        for _ in 0..20 {
            s.push('a');
        }

        let new_capacity = const_capacity(&s);
        assert!(new_capacity >= s.len(), "Capacity should be at least the length of the string");

        // The new capacity should either be the same (if initial capacity was large enough)
        // or larger (if reallocation occurred)
        assert!(new_capacity >= initial_capacity, "New capacity should not be less than initial");
    }

    #[test]
    fn test_capacity_after_shrink_to_fit() {
        let mut s = String::with_capacity(100);
        s.push_str("test");

        assert!(const_capacity(&s) >= 100, "Initial capacity should be at least 100");

        s.shrink_to_fit();
        assert!(const_capacity(&s) >= s.len(), "After shrink_to_fit, capacity should still be at least the length");
    }

    #[test]
    fn test_with_long_string() {
        let long_string = "a".repeat(1000);
        assert!(const_capacity(&long_string) >= 1000, "Capacity should handle long strings");
    }

    #[test]
    fn test_const_capacity_matches_string_capacity() {
        let cases = [
            String::new(),
            String::from("hello"),
            String::with_capacity(50),
            "a".repeat(200),
        ];

        for mut s in cases {
            // Try different operations that might affect capacity
            let operations: Vec<Box<dyn Fn(&mut String)>> = vec![
                Box::new(|s: &mut String| s.push_str("test")),
                Box::new(|s: &mut String| s.reserve(10)),
                Box::new(|s: &mut String| if !s.is_empty() { s.pop(); }),
                Box::new(|s: &mut String| s.shrink_to_fit()),
            ];

            for op in operations {
                op(&mut s);
                assert_eq!(const_capacity(&s), s.capacity(), 
                          "const_capacity should return the same value as String::capacity()");
            }
        }
    }
}

