fn to_uppercase_optimized(input: &str) -> String {
    if input.is_empty() {
        return String::new();
    }

    // Fast path for ASCII-only strings
    if input.is_ascii() {
        return input.chars()
            .map(|c| c.to_ascii_uppercase())
            .collect();
    }

    // For mixed ASCII/Unicode, leverage the built-in to_uppercase method
    let mut result = String::with_capacity(input.len());

    for c in input.chars() {
        // Append all uppercase variants of the character
        result.push_str(&c.to_uppercase().collect::<String>());
    }

    result
}

