mod tests {
    use super::*;
    use std::rc::{Rc, Weak};
    use std::cell::RefCell;

    // Test structure with reference to self
    struct Node {
        value: i32,
        parent: Weak<Node>,
        children: RefCell<Vec<Rc<Node>>>,
    }

    #[test]
    fn test_create_self_referential_node() {
        let node = create_self_referential(|weak_self| {
            Node {
                value: 42,
                parent: weak_self.clone(),
                children: RefCell::new(Vec::new()),
            }
        });

        // Check that the node has the correct value
        assert_eq!(node.value, 42);

        // Verify self-reference works by checking if parent points to self
        let parent_rc_opt = node.parent.upgrade();
        assert!(parent_rc_opt.is_some());
        let parent_rc = parent_rc_opt.unwrap();

        // Compare node addresses to confirm it's the same object
        assert!(Rc::ptr_eq(&node, &parent_rc));

        // Verify node has no children initially
        assert_eq!(node.children.borrow().len(), 0);
    }

    #[test]
    fn test_create_multiple_linked_nodes() {
        // Create parent node
        let parent = create_self_referential(|weak_self| {
            Node {
                value: 1,
                parent: weak_self.clone(),
                children: RefCell::new(Vec::new()),
            }
        });

        // Create child node that references parent
        let child = create_self_referential(|weak_self| {
            Node {
                value: 2,
                parent: Rc::downgrade(&parent),
                children: RefCell::new(Vec::new()),
            }
        });

        // Update parent's children list
        parent.children.borrow_mut().push(Rc::clone(&child));

        // Verify parent-child relationship
        assert_eq!(parent.value, 1);
        assert_eq!(child.value, 2);

        // Child should have parent reference
        let child_parent = child.parent.upgrade().unwrap();
        assert!(Rc::ptr_eq(&parent, &child_parent));

        // Check that parent references itself
        let parent_parent = parent.parent.upgrade().unwrap();
        assert!(Rc::ptr_eq(&parent, &parent_parent));
    }

    // Test with a different data structure
    struct Graph {
        id: usize,
        neighbors: RefCell<Vec<Weak<Graph>>>,
    }

    impl Graph {
        fn add_neighbor(&self, neighbor: &Rc<Graph>) {
            self.neighbors.borrow_mut().push(Rc::downgrade(neighbor));
        }

        fn count_neighbors(&self) -> usize {
            self.neighbors.borrow().iter().filter(|weak| weak.upgrade().is_some()).count()
        }
    }

    #[test]
    fn test_cyclic_graph() {
        // Create a cyclic graph with 3 nodes
        let node1 = create_self_referential(|_| {
            Graph {
                id: 1,
                neighbors: RefCell::new(Vec::new()),
            }
        });

        let node2 = create_self_referential(|_| {
            Graph {
                id: 2,
                neighbors: RefCell::new(Vec::new()),
            }
        });

        let node3 = create_self_referential(|_| {
            Graph {
                id: 3,
                neighbors: RefCell::new(Vec::new()),
            }
        });

        // Create a cycle: 1 -> 2 -> 3 -> 1
        node1.add_neighbor(&node2);
        node2.add_neighbor(&node3);
        node3.add_neighbor(&node1);

        // Verify connections
        assert_eq!(node1.count_neighbors(), 1);
        assert_eq!(node2.count_neighbors(), 1);
        assert_eq!(node3.count_neighbors(), 1);

        // Check that the cycle is correctly formed
        let neighbor_of_1 = node1.neighbors.borrow()[0].upgrade().unwrap();
        assert_eq!(neighbor_of_1.id, 2);

        let neighbor_of_2 = node2.neighbors.borrow()[0].upgrade().unwrap();
        assert_eq!(neighbor_of_2.id, 3);

        let neighbor_of_3 = node3.neighbors.borrow()[0].upgrade().unwrap();
        assert_eq!(neighbor_of_3.id, 1);
    }

    #[test]
    fn test_memory_management() {
        // Test that weak references don't prevent deallocation
        struct Counter {
            self_ref: Weak<Counter>,
            count: Rc<RefCell<i32>>,
        }

        impl Drop for Counter {
            fn drop(&mut self) {
                *self.count.borrow_mut() += 1;
            }
        }

        let drop_counter = Rc::new(RefCell::new(0));

        {
            // Create in nested scope so it can be dropped
            let counter = create_self_referential(|weak_self| {
                Counter {
                    self_ref: weak_self.clone(),
                    count: Rc::clone(&drop_counter),
                }
            });

            // Verify self-reference works
            let self_ref = counter.self_ref.upgrade().unwrap();
            assert!(Rc::ptr_eq(&counter, &self_ref));
        }

        // Verify the object was dropped exactly once
        assert_eq!(*drop_counter.borrow(), 1);
    }
}

