            Ipv6Addr::new(0x2001, 0xdb8, 0, 0, 0, 0, 0, 1), // Global unicast
            Ipv6Addr::new(0xfc00, 0, 0, 0, 0, 0, 0, 1), // Unique local
            Ipv6Addr::new(0xff02, 0, 0, 0, 0, 0, 0, 1), // Multicast
