            Ipv6Addr::from_str("2001:db8::1").unwrap(), // Documentation prefix
            Ipv6Addr::from_str("fd00::1").unwrap(), // Unique local
            Ipv6Addr::from_str("::ffff:192.168.1.1").unwrap(), // IPv4-mapped
            Ipv6Addr::from_str("::1").unwrap(), // Loopback
            Ipv6Addr::from_str("ff01::1").unwrap(), // Multicast
            Ipv6Addr::from_str("fc00::1").unwrap(), // Unique local
            Ipv6Addr::from_str("fe70::1").unwrap(), // Just below fe80 range
            Ipv6Addr::from_str("fec0::1").unwrap(), // Just above febf range
        ];

        for addr in &non_local_link_addresses {
            assert!(!is_local_link_address(addr), 
                   "Expected {:?} to NOT be recognized as a local link address", addr);
        }
