        assert!(is_local_link_address(&zero_interface_id), 
               "Local link with zero interface ID should return true");

        // Test with all ones in the interface identifier
        let all_ones_interface_id = Ipv6Addr::from_str("fe80::ffff:ffff:ffff:ffff").unwrap();
        assert!(is_local_link_address(&all_ones_interface_id), 
               "Local link with all ones interface ID should return true");
    }

