fn max_texture_size(memory_budget: u32) -> u32 {
    // Each pixel requires 4 bytes
    // For a square texture with side length n, total memory = n² * 4 bytes
    // n² * 4 <= memory_budget
    // n² <= memory_budget / 4
    // n <= sqrt(memory_budget / 4)

    // Calculate the maximum number of pixels
    let max_pixels = memory_budget / 4;

    // Calculate the maximum side length
    max_pixels.isqrt()
}

