        let ptr = &value as *const i32;
        let address = extract_address(ptr);

        // The address should be non-zero for a valid reference
        assert_ne!(address, 0);

        // Casting back to a pointer and dereferencing should give the original value
        let ptr_back = address as *const i32;
        unsafe {
