        let ptr = &value as *const TestStruct;
        let address = extract_address(ptr);

        assert_ne!(address, 0);

        // Verify we can access struct fields through the extracted address
        unsafe {
            let ptr_back = address as *const TestStruct;
            assert_eq!((*ptr_back).field1, 10);
            assert_eq!((*ptr_back).field2, true);
        }
    }

    #[test]
    fn test_extract_address_with_null() {
        let ptr: *const i32 = null();
        let address = extract_address(ptr);

        // A null pointer should have address 0
        assert_eq!(address, 0);
    }

    #[test]
    fn test_extract_address_with_different_types() {
        // Test with various types to ensure the generic works properly

        let int_val = 42i32;
        let int_ptr = &int_val as *const i32;
        let int_addr = extract_address(int_ptr);
        assert_ne!(int_addr, 0);

        let float_val = 3.14f64;
        let float_ptr = &float_val as *const f64;
        let float_addr = extract_address(float_ptr);
        assert_ne!(float_addr, 0);

        let string_val = String::from("test");
        let string_ptr = &string_val as *const String;
        let string_addr = extract_address(string_ptr);
        assert_ne!(string_addr, 0);
    }

