        // Test that the function correctly handles pointers after arithmetic
        let array = [1, 2, 3, 4, 5];
        let base_ptr = array.as_ptr();
        let base_addr = extract_address(base_ptr);

        // Get a pointer to the third element
        let offset_ptr = unsafe { base_ptr.add(2) };
        let offset_addr = extract_address(offset_ptr);

        // The offset address should be greater than the base address
        // by exactly 2 * size_of::<i32>()
        assert_eq!(offset_addr, base_addr + 2 * std::mem::size_of::<i32>());

        // Verify we can dereference the calculated address
        unsafe {
            assert_eq!(*(offset_addr as *const i32), 3);
        }
