        let transform = |addr: usize| addr - std::mem::size_of::<i32>();

        // Apply the transformation
        let adjusted_ptr = adjust_pointer_address(middle_ptr, transform);

        // Verify that the address has been decremented
        assert_eq!(
            middle_ptr as usize - std::mem::size_of::<i32>(),
