#[cfg(test)]
mod tests {
    use std::ptr;

    // Import the function under test
    use super::create_register_pointer;

    #[test]
    fn test_base_zero_offset() {
        // Create a buffer to work with
        let mut buffer = [0u32; 10];
        let base_ptr = buffer.as_mut_ptr();

        // Test with zero offset (should return the same address)
        let register_ptr = create_register_pointer(base_ptr, 0);

        // Verify pointers point to the same address
        assert_eq!(register_ptr as usize, base_ptr as usize);

        // Verify we can safely write to the pointer
        unsafe {
            *register_ptr = 42;
            assert_eq!(buffer[0], 42);
        }
    }

    #[test]
    fn test_positive_offset() {
        let mut buffer = [0u32; 10];
        let base_ptr = buffer.as_mut_ptr();

        // Test with offset of 3 registers (12 bytes, since u32 is 4 bytes)
        let offset = 3 * std::mem::size_of::<u32>();
        let register_ptr = create_register_pointer(base_ptr, offset);

        // Verify pointer arithmetic is correct
        assert_eq!(register_ptr as usize, (base_ptr as usize) + offset);

        // Verify we can safely write to the pointer
        unsafe {
            *register_ptr = 99;
            assert_eq!(buffer[3], 99);
        }
    }

    #[test]
    fn test_multiple_offsets() {
        let mut buffer = [0u32; 10];
        let base_ptr = buffer.as_mut_ptr();

        // Create pointers to different offsets
        let offsets = [0, 1, 4, 9];
        let values = [123, 456, 789, 999];

        for (i, &offset) in offsets.iter().enumerate() {
            let byte_offset = offset * std::mem::size_of::<u32>();
            let register_ptr = create_register_pointer(base_ptr, byte_offset);

            unsafe {
                *register_ptr = values[i];
            }
        }

        // Verify all values were written correctly
        for (i, &offset) in offsets.iter().enumerate() {
            assert_eq!(buffer[offset], values[i]);
        }
    }

    #[test]
    fn test_provenance_preservation() {
        // Create two separate buffers
        let mut buffer1 = [0u32; 5];
        let mut buffer2 = [0u32; 5];

        let ptr1 = buffer1.as_mut_ptr();
        let ptr2 = buffer2.as_mut_ptr();

        // Create pointers with the same address but different provenance
        let offset1 = 2 * std::mem::size_of::<u32>();
        let register_ptr1 = create_register_pointer(ptr1, offset1);

        // Write using the derived pointer
        unsafe {
            *register_ptr1 = 0xDEADBEEF;
        }

        // Verify the value was written to the correct buffer
        assert_eq!(buffer1[2], 0xDEADBEEF);
        assert_eq!(buffer2[2], 0); // Other buffer should be unchanged
    }

    #[test]
    fn test_null_pointer_handling() {
        // Test with a null pointer (safe because we're not dereferencing)
        let null_ptr: *mut u32 = ptr::null_mut();
        let offset = 4 * std::mem::size_of::<u32>();

        let result_ptr = create_register_pointer(null_ptr, offset);

        // The result should be a null pointer plus the offset
        assert_eq!(result_ptr as usize, null_ptr as usize + offset);
    }

    #[test]
    fn test_large_offset() {
        // Test with a large offset to ensure no integer overflow issues
        let mut buffer = [0u32; 10];
        let base_ptr = buffer.as_mut_ptr();

        // Create a large offset but still within buffer bounds
        let offset = 8 * std::mem::size_of::<u32>();
        let register_ptr = create_register_pointer(base_ptr, offset);

        // Verify pointer calculation
        assert_eq!(register_ptr as usize, (base_ptr as usize) + offset);

        // Verify we can write to the last element
        unsafe {
            *register_ptr = 0xCAFEBABE;
            assert_eq!(buffer[8], 0xCAFEBABE);
        }
    }
}

