        let path = path_buf.as_path();
        let rc_path1 = create_rc_path(&mut path.to_path_buf());
        let rc_path2 = Rc::clone(&rc_path1);

        assert_eq!(rc_path1.to_string_lossy(), "/tmp/shared");
        assert_eq!(rc_path2.to_string_lossy(), "/tmp/shared");
        assert!(Rc::ptr_eq(&rc_path1, &rc_path2));
    }

    #[test]
    fn test_with_empty_path() {
        let path_buf = PathBuf::from("");
        let path = path_buf.as_path();
        let rc_path = create_rc_path(&mut path.to_path_buf());

        assert_eq!(rc_path.to_string_lossy(), "");
    }

    #[test]
    fn test_with_complex_path() {
        let path_buf = PathBuf::from("/usr/local/bin/rust/test/path");
        let path = path_buf.as_path();
        let rc_path = create_rc_path(&mut path.to_path_buf());

        assert_eq!(rc_path.to_string_lossy(), "/usr/local/bin/rust/test/path");
    }

    #[test]
    fn test_strong_count() {
        let path_buf = PathBuf::from("/tmp/count");
        let path = path_buf.as_path();
        let rc_path = create_rc_path(&mut path.to_path_buf());

        assert_eq!(Rc::strong_count(&rc_path), 1);

        let rc_path2 = Rc::clone(&rc_path);
        assert_eq!(Rc::strong_count(&rc_path), 2);

        drop(rc_path2);
        assert_eq!(Rc::strong_count(&rc_path), 1);
    }

    #[test]
    fn test_original_path_modification() {
        let mut path_buf = PathBuf::from("/tmp/original");
        let path = path_buf.as_path();
        let rc_path = create_rc_path(&mut path.to_path_buf());

        // Store the original path for comparison
        let original_path_str = rc_path.to_string_lossy().to_string();

        // Modify the original path
        path_buf.push("modified");

        // The Rc path should NOT reflect the change (showing the limitation)
        assert_eq!(rc_path.to_string_lossy(), original_path_str);
        assert_ne!(rc_path.to_string_lossy(), path_buf.to_string_lossy());
    }
