#[cfg(test)]
mod tests {
    use super::*;
    use std::fmt;

    // A simple struct that implements Debug
    #[derive(PartialEq, Clone)]
    struct TestStruct {
        value: i32,
    }

    impl fmt::Debug for TestStruct {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            write!(f, "TestStruct({})", self.value)
        }
    }

    // A struct with multiple fields
    #[derive(PartialEq, Clone)]
    struct ComplexStruct {
        id: u32,
        name: String,
        flag: bool,
    }

    impl fmt::Debug for ComplexStruct {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            f.debug_struct("ComplexStruct")
                .field("id", &self.id)
                .field("name", &self.name)
                .field("flag", &self.flag)
                .finish()
        }
    }

    // An enum that implements Debug
    #[derive(Debug, PartialEq, Clone)]
    enum TestEnum {
        A,
        B(i32),
        C { x: f64, y: f64 },
    }

    #[test]
    fn test_format_box_with_address_primitive() {
        let boxed = Box::new(42);
        let result = format_box_with_address(boxed);

        // Check if the result contains the value
        assert!(result.contains("42"));

        // Check if the result contains a pointer address format (0x...)
        assert!(result.contains(" @ 0x"));
    }

    #[test]
    fn test_format_box_with_address_struct() {
        let boxed = Box::new(TestStruct { value: 123 });
        let result = format_box_with_address(boxed);

        // Check if the result contains the struct's debug representation
        assert!(result.contains("TestStruct(123)"));

        // Check if the result contains a pointer address
        assert!(result.contains(" @ 0x"));
    }

    #[test]
    fn test_format_box_with_address_complex_struct() {
        let boxed = Box::new(ComplexStruct {
            id: 1,
            name: "test".to_string(),
            flag: true,
        });
        let result = format_box_with_address(boxed);

        // Check if the result contains the struct's debug representation
        assert!(result.contains("ComplexStruct"));
        assert!(result.contains("id: 1"));
        assert!(result.contains("name: \"test\""));
        assert!(result.contains("flag: true"));

        // Check if the result contains a pointer address
        assert!(result.contains(" @ 0x"));
    }

    #[test]
    fn test_format_box_with_address_enum() {
        // Test each variant of the enum
        let variants = vec![
            TestEnum::A,
            TestEnum::B(42),
            TestEnum::C { x: 1.0, y: 2.0 },
        ];

        for variant in variants {
            let boxed = Box::new(variant.clone());
            let result = format_box_with_address(boxed);

            // Check if the result contains the enum's debug representation
            match variant {
                TestEnum::A => assert!(result.contains("A")),
                TestEnum::B(val) => assert!(result.contains(&format!("B({})", val))),
                TestEnum::C { x, y } => {
                    assert!(result.contains("C"));
                    assert!(result.contains(&format!("x: {}", x)));
                    assert!(result.contains(&format!("y: {}", y)));
                }
            }

            // Check if the result contains a pointer address
            assert!(result.contains(" @ 0x"));
        }
    }

    #[test]
    fn test_format_box_with_address_string() {
        let boxed = Box::new("Hello, world!".to_string());
        let result = format_box_with_address(boxed);

        // Check if the result contains the string's debug representation
        assert!(result.contains("\"Hello, world!\""));

        // Check if the result contains a pointer address
        assert!(result.contains(" @ 0x"));
    }

    #[test]
    fn test_format_box_with_address_nested() {
        // Test with a Box containing another Box
        let inner_boxed = Box::new(42);
        let boxed = Box::new(inner_boxed);
        let result = format_box_with_address(boxed);

        // Should contain the value's debug format
        assert!(result.contains("42"));

        // Check if the result contains a pointer address
        assert!(result.contains(" @ 0x"));
    }

    #[test]
    fn test_format_box_with_address_format() {
        // Test the format of the output
        let boxed = Box::new(42);
        let result = format_box_with_address(boxed);

        // Split the result by " @ "
        let parts: Vec<&str> = result.split(" @ ").collect();

        // Should have exactly two parts
        assert_eq!(parts.len(), 2);

        // First part should be the Debug output
        assert_eq!(parts[0], "42");

        // Second part should be a pointer address starting with "0x"
        assert!(parts[1].starts_with("0x"));
    }
}

