    use std::mem::MaybeUninit;

    #[test]
    fn test_sort_initialized_buffer_already_sorted() {
        // Create a buffer with values already in sorted order
        let mut buffer = MaybeUninit::uninit();

        unsafe {
            // Populate buffer with sequential values (already sorted)
            let ptr = buffer.as_mut_ptr() as *mut [u8; 1024];
            for i in 0..1024 {
                (*ptr)[i] = i as u8;  // Will wrap around after 255, which is fine for this test
            }

            // Call the function to sort the buffer
            let result = sort_initialized_buffer(&mut buffer);

            // Verify buffer is still sorted
            for i in 0..1023 {
                assert!(result[i] <= result[i + 1]);
            }
        }
    }

