            // Populate buffer with all the same value
            let ptr = buffer.as_mut_ptr() as *mut [u8; 1024];
            for i in 0..1024 {
                (*ptr)[i] = 42u8;
            }

            // Call the function to sort the buffer
            let result = sort_initialized_buffer(&mut buffer);

            // Verify all values are still the same
            for value in result.iter() {
                assert_eq!(*value, 42u8);
            }
        }
