        // Create a buffer with edge case values
        let mut buffer = MaybeUninit::uninit();

        unsafe {
            // Populate buffer with a mix of min, max, and mid-range values
            let ptr = buffer.as_mut_ptr() as *mut [u8; 1024];

            // Fill with mid-range value first
            for i in 0..1024 {
                (*ptr)[i] = 128u8;
            }

            // Add extreme values at specific positions
            (*ptr)[0] = 255u8;
            (*ptr)[1] = 0u8;
            (*ptr)[1022] = 255u8;
            (*ptr)[1023] = 0u8;

            // Call the function to sort the buffer
            let result = sort_initialized_buffer(&mut buffer);

            // Verify sorting - first 2 elements should be 0, last 2 should be 255
            assert_eq!(result[0], 0u8);
            assert_eq!(result[1], 0u8);

            // Middle elements should be 128
            for i in 2..1022 {
                assert_eq!(result[i], 128u8);
            }

            assert_eq!(result[1022], 255u8);
            assert_eq!(result[1023], 255u8);
        }
    }

    #[test]
    fn test_sort_initialized_buffer_returns_correct_reference() {
        // Test that the function returns a reference to the same memory
        let mut buffer = MaybeUninit::uninit();

        unsafe {
            // Get the raw pointer to the buffer for later comparison
            let original_ptr = buffer.as_mut_ptr();

            // Initialize buffer with some values
            let ptr = original_ptr as *mut [u8; 1024];
            for i in 0..1024 {
                (*ptr)[i] = i as u8;
            }

            // Call the function
            let result = sort_initialized_buffer(&mut buffer);

            // Verify the returned reference points to the same memory
            let result_ptr = result as *const [u8; 1024];
            assert_eq!(result_ptr as *const u8, original_ptr as *const u8);
        }
    }
