mod tests {
    use super::*;
    use std::panic::{catch_unwind, AssertUnwindSafe};

    #[test]
    fn test_valid_decimal_digits() {
        for c in '0'..='9' {
            let expected = Some((c as u32) - ('0' as u32));
            assert_eq!(is_valid_digit(c, 10), expected, "Failed for char {}", c);
        }
    }

    #[test]
    fn test_valid_hex_digits() {
        // Test lowercase hex digits
        for (i, c) in ('a'..='f').enumerate() {
            let expected = Some(10 + i as u32);
            assert_eq!(is_valid_digit(c, 16), expected, "Failed for lowercase hex char {}", c);
        }

        // Test uppercase hex digits
        for (i, c) in ('A'..='F').enumerate() {
            let expected = Some(10 + i as u32);
            assert_eq!(is_valid_digit(c, 16), expected, "Failed for uppercase hex char {}", c);
        }
    }

    #[test]
    fn test_invalid_digits_for_radix() {
        // Test digits that are valid in higher radixes but not in lower ones
        assert_eq!(is_valid_digit('9', 8), None, "9 should be invalid in octal");
        assert_eq!(is_valid_digit('a', 10), None, "'a' should be invalid in decimal");
        assert_eq!(is_valid_digit('z', 35), None, "'z' should be invalid in base 35");

        // Test non-digit characters
        assert_eq!(is_valid_digit('-', 10), None, "'-' should be invalid");
        assert_eq!(is_valid_digit('+', 10), None, "'+' should be invalid");
        assert_eq!(is_valid_digit('.', 10), None, "'.' should be invalid");
        assert_eq!(is_valid_digit(' ', 10), None, "Space should be invalid");
    }

    #[test]
    fn test_boundary_radixes() {
        // Test minimum radix (2)
        assert_eq!(is_valid_digit('0', 2), Some(0), "'0' should be valid in binary");
        assert_eq!(is_valid_digit('1', 2), Some(1), "'1' should be valid in binary");
        assert_eq!(is_valid_digit('2', 2), None, "'2' should be invalid in binary");

        // Test maximum radix (36)
        assert_eq!(is_valid_digit('z', 36), Some(35), "'z' should be valid in base 36");
        assert_eq!(is_valid_digit('Z', 36), Some(35), "'Z' should be valid in base 36");
    }

    #[test]
    fn test_unicode_characters() {
        // Unicode characters beyond ASCII should not be valid digits
        assert_eq!(is_valid_digit('😀', 10), None, "Emoji should be invalid");
        assert_eq!(is_valid_digit('ö', 16), None, "Non-ASCII characters should be invalid");
    }

    #[test]
    fn test_invalid_radix_panics() {
        // Test radix below minimum (2)
        let result = catch_unwind(AssertUnwindSafe(|| {
            is_valid_digit('0', 1);
        }));
        assert!(result.is_err(), "Function should panic with radix < 2");

        // Test radix above maximum (36)
        let result = catch_unwind(AssertUnwindSafe(|| {
            is_valid_digit('0', 37);
        }));
        assert!(result.is_err(), "Function should panic with radix > 36");
    }

    #[test]
    fn test_various_radixes() {
        // Test octal
        assert_eq!(is_valid_digit('7', 8), Some(7));
        assert_eq!(is_valid_digit('8', 8), None);

        // Test base 12
        assert_eq!(is_valid_digit('b', 12), Some(11));
        assert_eq!(is_valid_digit('B', 12), Some(11));
        assert_eq!(is_valid_digit('c', 12), None);

        // Test base 35
        assert_eq!(is_valid_digit('y', 35), Some(34));
        assert_eq!(is_valid_digit('Y', 35), Some(34));
        assert_eq!(is_valid_digit('z', 35), None);
    }
