    fn test_regular_negation() {
        // Test with a simple positive number
        let num = NonZeroI32::new(5).unwrap();
        let (result, overflow) = negate_with_overflow_check(num);
        assert_eq!(result.get(), -5);
        assert_eq!(overflow, false);

        // Test with a negative number
        let num = NonZeroI32::new(-10).unwrap();
        let (result, overflow) = negate_with_overflow_check(num);
        assert_eq!(result.get(), 10);
        assert_eq!(overflow, false);
    }

    #[test]
    fn test_edge_cases() {
        // Test with -1
        let num = NonZeroI32::new(-1).unwrap();
        let (result, overflow) = negate_with_overflow_check(num);
        assert_eq!(result.get(), 1);
        assert_eq!(overflow, false);

        // Test with 1
        let num = NonZeroI32::new(1).unwrap();
        let (result, overflow) = negate_with_overflow_check(num);
        assert_eq!(result.get(), -1);
        assert_eq!(overflow, false);

        // Test with the largest positive i32
        let num = NonZeroI32::new(i32::MAX).unwrap();
        let (result, overflow) = negate_with_overflow_check(num);
        assert_eq!(result.get(), -i32::MAX);
        assert_eq!(overflow, false);
    }

    #[test]
    fn test_smallest_i32_overflow() {
        // Test with the smallest negative i32 (which is -2^31 or -2147483648)
        // This should cause an overflow because its absolute value is 2^31,
        // which exceeds the maximum positive i32 value (which is 2^31-1 or 2147483647)
        let num = NonZeroI32::new(i32::MIN).unwrap();
        let (result, overflow) = negate_with_overflow_check(num);

        // After overflow, the result should be i32::MIN itself
        // This is because the two's complement representation wraps around
        assert_eq!(result.get(), i32::MIN);
        assert_eq!(overflow, true);
    }

    #[test]
    fn test_construction_from_values() {
        // Test various ways to create NonZeroI32 values
        for val in [1, -1, 42, -100, i32::MAX, i32::MIN] {
            if let Some(num) = NonZeroI32::new(val) {
                let (result, _) = negate_with_overflow_check(num);
                if val != i32::MIN {
                    // For all values except i32::MIN, we expect no overflow
                    // and the result should be the negative of the input
                    assert_eq!(result.get(), -val);
                }
            }
        }

        // Zero cannot be constructed as NonZeroI32
        assert!(NonZeroI32::new(0).is_none());
    }
}

