fn sum_from_offset(ptr: *mut i32, offset: isize, len: usize) -> i32 {
    let mut sum = 0;
    unsafe {
        let start = ptr.offset(offset);
        for i in 0..len {
            sum += *start.add(i);
        }
    }
    sum
}

