    fn test_sum_with_positive_offset() {
        let mut arr = [10, 20, 30, 40, 50];
        let result = sum_from_offset(arr.as_mut_ptr(), 2, 3);
        assert_eq!(result, 120); // 30 + 40 + 50 = 120
    }

    #[test]
    fn test_sum_with_negative_offset() {
        let mut arr = [10, 20, 30, 40, 50];
        // Create a pointer to the middle of the array
        let middle_ptr = unsafe { arr.as_mut_ptr().add(2) };
        // Use a negative offset to go back to the start
        let result = sum_from_offset(middle_ptr, -2, 3);
        assert_eq!(result, 60); // 10 + 20 + 30 = 60
    }

    #[test]
    fn test_sum_with_zero_len() {
        let mut arr = [1, 2, 3, 4, 5];
        let result = sum_from_offset(arr.as_mut_ptr(), 2, 0);
        assert_eq!(result, 0);
    }

