        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs(5));
    }

    #[test]
    fn test_positive_decimal_seconds() {
        let result = safe_duration_from_seconds(3.5);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs(3) + Duration::from_nanos(500_000_000));
    }

    #[test]
    fn test_zero_seconds() {
        let result = safe_duration_from_seconds(0.0);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs(0));
    }

    #[test]
    fn test_negative_seconds() {
        let result = safe_duration_from_seconds(-1.0);
        assert!(result.is_err());
    }

    #[test]
    fn test_infinity() {
        let result = safe_duration_from_seconds(f64::INFINITY);
        assert!(result.is_err());
    }

    #[test]
    fn test_negative_infinity() {
        let result = safe_duration_from_seconds(f64::NEG_INFINITY);
        assert!(result.is_err());
    }

