    fn test_nan() {
        let result = safe_duration_from_seconds(f64::NAN);
        assert!(result.is_err());
    }

    #[test]
    fn test_very_large_value() {
        // A value that's too large for u64 (> u64::MAX seconds)
        let result = safe_duration_from_seconds(f64::MAX);
        assert!(result.is_err());
    }

    #[test]
    fn test_edge_case_max() {
        // The maximum safe value for f64 that can be converted to u64
        // without loss of precision is 2^53 - 1
        let max_safe_secs = (1u64 << 53) - 1;
        let result = safe_duration_from_seconds(max_safe_secs as f64);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs(max_safe_secs));
    }

    #[test]
    fn test_very_small_positive() {
        // Test with a very small positive number
        let result = safe_duration_from_seconds(1e-10);
        assert!(result.is_ok());
        // 1e-10 seconds = 100 picoseconds = 0.1 nanoseconds
        // Duration will round to 0 nanoseconds
        assert_eq!(result.unwrap(), Duration::from_nanos(0));
    }
}

