use std::num::Wrapping;

fn wrapping_div_chain(values: Vec<Wrapping<u32>>, divisors: Vec<Wrapping<u32>>) -> Vec<Wrapping<u32>> {
    values.into_iter()
        .zip(divisors.into_iter())
        .map(|(val, div)| val / div)
        .collect()
}

