#[cfg(test)]
mod tests {
    use std::num::Wrapping;
    use super::*;

    #[test]
    fn test_wrapping_div_chain_basic() {
        let values = vec![Wrapping(10_u32), Wrapping(20_u32), Wrapping(30_u32)];
        let divisors = vec![Wrapping(2_u32), Wrapping(4_u32), Wrapping(3_u32)];
        let expected = vec![Wrapping(5_u32), Wrapping(5_u32), Wrapping(10_u32)];

        let result = wrapping_div_chain(values, divisors);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_wrapping_div_chain_empty() {
        let values: Vec<Wrapping<u32>> = vec![];
        let divisors: Vec<Wrapping<u32>> = vec![];
        let expected: Vec<Wrapping<u32>> = vec![];

        let result = wrapping_div_chain(values, divisors);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_wrapping_div_chain_single() {
        let values = vec![Wrapping(100_u32)];
        let divisors = vec![Wrapping(25_u32)];
        let expected = vec![Wrapping(4_u32)];

        let result = wrapping_div_chain(values, divisors);
        assert_eq!(result, expected);
    }

    #[test]
    #[should_panic]
    fn test_wrapping_div_chain_with_zero_divisor() {
        let values = vec![Wrapping(10_u32), Wrapping(20_u32)];
        let divisors = vec![Wrapping(2_u32), Wrapping(0_u32)];

        // Division by zero always panics in Rust, even with Wrapping
        let _ = wrapping_div_chain(values, divisors);
    }

    #[test]
    fn test_wrapping_div_chain_with_wrapping_behavior() {
        // Test wrapping division with max values
        let values = vec![Wrapping(u32::MAX), Wrapping(u32::MAX - 1)];
        let divisors = vec![Wrapping(1_u32), Wrapping(u32::MAX)];
        // Expected: u32::MAX / 1 = u32::MAX, (u32::MAX - 1) / u32::MAX = 0
        let expected = vec![Wrapping(u32::MAX), Wrapping(0_u32)];

        let result = wrapping_div_chain(values, divisors);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_wrapping_div_chain_different_length_vectors() {
        // If values is longer than divisors, only elements with matching pairs should be processed
        let values = vec![Wrapping(10_u32), Wrapping(20_u32), Wrapping(30_u32)];
        let divisors = vec![Wrapping(2_u32), Wrapping(4_u32)];
        let expected = vec![Wrapping(5_u32), Wrapping(5_u32)];

        let result = wrapping_div_chain(values, divisors);
        assert_eq!(result, expected);

        // If divisors is longer than values, only elements with matching pairs should be processed
        let values = vec![Wrapping(10_u32), Wrapping(20_u32)];
        let divisors = vec![Wrapping(2_u32), Wrapping(4_u32), Wrapping(8_u32)];
        let expected = vec![Wrapping(5_u32), Wrapping(5_u32)];

        let result = wrapping_div_chain(values, divisors);
        assert_eq!(result, expected);
    }

    #[test]
    fn test_wrapping_div_chain_large_numbers() {
        let values = vec![Wrapping(u32::MAX), Wrapping(u32::MAX / 2), Wrapping(u32::MAX / 4)];
        let divisors = vec![Wrapping(2_u32), Wrapping(2_u32), Wrapping(2_u32)];
        let expected = vec![
            Wrapping(2147483647), // u32::MAX / 2
            Wrapping(1073741823), // (u32::MAX / 2) / 2
            Wrapping(536870911)   // (u32::MAX / 4) / 2
        ];

        let result = wrapping_div_chain(values, divisors);
        assert_eq!(result, expected);
    }
}

