use std::time::Duration;

#[derive(Debug)]
pub enum DurationError {
    InvalidValue,
}

pub fn safe_duration_from_secs(secs: f32) -> Result<Duration, DurationError> {
    if secs.is_nan() || secs.is_infinite() || secs < 0.0 {
        return Err(DurationError::InvalidValue);
    }
    Ok(Duration::from_secs_f32(secs))
}

