#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    #[test]
    fn test_safe_duration_valid_values() {
        // Test with zero
        let result = safe_duration_from_secs(0.0);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs(0));

        // Test with positive integer
        let result = safe_duration_from_secs(5.0);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs(5));

        // Test with positive decimal
        let result = safe_duration_from_secs(3.5);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs_f32(3.5));

        // Test with very small positive value
        let result = safe_duration_from_secs(0.000001);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs_f32(0.000001));

        // Test with large value - but not too large to avoid precision issues
        let result = safe_duration_from_secs(1_000_000.0);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs(1_000_000));
    }

    #[test]
    fn test_safe_duration_invalid_values() {
        // Test with NaN
        let result = safe_duration_from_secs(f32::NAN);
        assert!(result.is_err());
        match result {
            Err(DurationError::InvalidValue) => (),
            _ => panic!("Expected InvalidValue error for NaN"),
        }

        // Test with positive infinity
        let result = safe_duration_from_secs(f32::INFINITY);
        assert!(result.is_err());
        match result {
            Err(DurationError::InvalidValue) => (),
            _ => panic!("Expected InvalidValue error for positive infinity"),
        }

        // Test with negative infinity
        let result = safe_duration_from_secs(f32::NEG_INFINITY);
        assert!(result.is_err());
        match result {
            Err(DurationError::InvalidValue) => (),
            _ => panic!("Expected InvalidValue error for negative value"),
        }

        // Test with negative value
        let result = safe_duration_from_secs(-1.0);
        assert!(result.is_err());
        match result {
            Err(DurationError::InvalidValue) => (),
            _ => panic!("Expected InvalidValue error for negative value"),
        }

        // Test with slightly negative value
        let result = safe_duration_from_secs(-0.000001);
        assert!(result.is_err());
        match result {
            Err(DurationError::InvalidValue) => (),
            _ => panic!("Expected InvalidValue error for slightly negative value"),
        }
    }

    #[test]
    fn test_safe_duration_edge_cases() {
        // Test with value close to zero
        let result = safe_duration_from_secs(f32::EPSILON);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs_f32(f32::EPSILON));

        // Test with a large but safe value 
        // Using a value well within u64::MAX to avoid overflow
        let large_but_valid = 1_000_000_000.0; // 1 billion seconds
        let result = safe_duration_from_secs(large_but_valid);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs_f32(large_but_valid));

        // Test with zero represented as -0.0 (should be treated as valid)
        let result = safe_duration_from_secs(-0.0);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Duration::from_secs(0));
    }
}

