mod tests {
    use super::process_linked_lists;
    use std::collections::LinkedList;

    #[test]
    fn test_empty_count() {
        let result = process_linked_lists(0);
        assert_eq!(result.len(), 0);
    }

    #[test]
    fn test_non_empty_count() {
        let result = process_linked_lists(5);
        assert_eq!(result.len(), 5);

        // All lists should be empty
        for list in &result {
            assert_eq!(list.len(), 0);
        }
    }

    #[test]
    fn test_large_count() {
        let count = 1000;
        let result = process_linked_lists(count);
        assert_eq!(result.len(), count);
    }

    #[test]
    fn test_mutability() {
        let mut result = process_linked_lists(3);

        // Verify we can modify the returned lists
        for list in &mut result {
            list.push_back(42);
            assert_eq!(list.len(), 1);
            assert_eq!(list.back(), Some(&42));
        }
    }

    #[test]
    fn test_capacity_hint() {
        // This is a bit of an implementation detail, but we
        // want to verify the Vec has the correct capacity
        let count = 10;
        let result = process_linked_lists(count);

        // We expect the capacity to be at least `count`
        assert!(result.capacity() >= count);
    }

    #[test]
    fn test_separation() {
        let mut result = process_linked_lists(2);

        // Modify the first list
        result[0].push_back(1);
        result[0].push_back(2);

        // Modify the second list differently
        result[1].push_back(3);

        // Verify the lists are separate and maintain their own state
        assert_eq!(result[0].len(), 2);
        assert_eq!(result[1].len(), 1);

        let first_values: Vec<i32> = result[0].iter().cloned().collect();
        let second_values: Vec<i32> = result[1].iter().cloned().collect();

        assert_eq!(first_values, vec![1, 2]);
        assert_eq!(second_values, vec![3]);
    }
}

