mod tests {
    use super::*;
    use std::ffi::{OsStr, OsString};

    #[cfg(unix)]
    mod unix_tests {
        use super::*;
        use std::os::unix::ffi::{OsStrExt, OsStringExt};

        #[test]
        fn test_empty_bytes() {
            let bytes: &[u8] = &[];
            let os_str = unsafe { os_str_from_bytes_unchecked(bytes) };
            assert_eq!(os_str, OsStr::new(""));
            assert_eq!(os_str.len(), 0);
        }

        #[test]
        fn test_ascii_bytes() {
            let bytes = b"hello world";
            let os_str = unsafe { os_str_from_bytes_unchecked(bytes) };
            assert_eq!(os_str, OsStr::new("hello world"));
            assert_eq!(os_str.len(), bytes.len());
        }

        #[test]
        fn test_non_utf8_bytes() {
            let bytes = &[0x68, 0x65, 0x6c, 0x6c, 0x6f, 0xff, 0xfe, 0xfd];
            let os_str = unsafe { os_str_from_bytes_unchecked(bytes) };

            // Convert back to bytes for comparison as the string might not be displayable
            let bytes_after = os_str.as_bytes();
            assert_eq!(bytes_after, bytes);
            assert_eq!(os_str.len(), bytes.len());
        }

        #[test]
        fn test_path_like_bytes() {
            let bytes = b"/usr/local/bin/rust";
            let os_str = unsafe { os_str_from_bytes_unchecked(bytes) };
            assert_eq!(os_str, OsStr::new("/usr/local/bin/rust"));
        }

        #[test]
        fn test_null_bytes() {
            let bytes = &[0x68, 0x65, 0x6c, 0x6c, 0x6f, 0x00, 0x77, 0x6f, 0x72, 0x6c, 0x64];
            let os_str = unsafe { os_str_from_bytes_unchecked(bytes) };

            // Check if the OsStr contains the null byte correctly
            let bytes_after = os_str.as_bytes();
            assert_eq!(bytes_after, bytes);
            assert_eq!(os_str.len(), bytes.len());
        }

        #[test]
        fn test_memory_layout_preservation() {
            let bytes = &[0x41, 0x42, 0x43, 0x44, 0x45];
            let os_str = unsafe { os_str_from_bytes_unchecked(bytes) };

            // Convert to OsString and back to bytes to verify preservation
            let os_string: OsString = os_str.to_owned();
            let bytes_after: Vec<u8> = os_string.into_vec();

            assert_eq!(bytes, bytes_after.as_slice());
        }

        #[test]
        fn test_roundtrip_conversion() {
            let original = b"some/path/with/special/chars/\xff\xfe";

            // Convert bytes to OsStr
            let os_str = unsafe { os_str_from_bytes_unchecked(original) };

            // Convert OsStr back to bytes
            let roundtrip = os_str.as_bytes();

            // Verify the bytes are preserved through the conversion
            assert_eq!(original, roundtrip);
        }

        #[test]
        fn test_large_input() {
            // Create a large byte array (100KB)
            let large_bytes: Vec<u8> = (0..102400).map(|i| (i % 256) as u8).collect();

            // Test with a slice of the large byte array
            let os_str = unsafe { os_str_from_bytes_unchecked(&large_bytes) };

            // Verify the length is preserved
            assert_eq!(os_str.len(), large_bytes.len());

            // Verify content by checking a few random positions
            let back_to_bytes = os_str.as_bytes();
            assert_eq!(back_to_bytes[1000], large_bytes[1000]);
            assert_eq!(back_to_bytes[50000], large_bytes[50000]);
            assert_eq!(back_to_bytes[100000], large_bytes[100000]);
        }
    }

    #[cfg(windows)]
    mod windows_tests {
        use super::*;
        use std::os::windows::ffi::OsStrExt;

        #[test]
        fn test_basic_functionality() {
            // On Windows, we can only test with valid UTF-8 bytes
            let bytes = b"hello world";
            let os_str = unsafe { os_str_from_bytes_unchecked(bytes) };
            assert_eq!(os_str, OsStr::new("hello world"));
            assert_eq!(os_str.len(), "hello world".len());
        }
    }
}

