use std::num::Saturating;

fn rotate_saturated_bits(value: Saturating<u32>, rotation: u32) -> Saturating<u32> {
    value.rotate_left(rotation)
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use std::num::Saturating;

    #[test]
    fn test_zero_rotation() {
        let value = Saturating(42_u32);
        let result = rotate_saturated_bits(value, 0);
        assert_eq!(result, Saturating(42_u32));
    }

    #[test]
    fn test_full_rotation() {
        let value = Saturating(0xABCD1234_u32);
        // Rotating by 32 bits (full width) should result in the same value
        let result = rotate_saturated_bits(value, 32);
        assert_eq!(result, Saturating(0xABCD1234_u32));
    }

    #[test]
    fn test_partial_rotation() {
        let value = Saturating(0x01_u32); // 0000 0000 0000 0000 0000 0000 0000 0001
        // Rotating left by 1 should result in 0000 0000 0000 0000 0000 0000 0000 0010
        let result = rotate_saturated_bits(value, 1);
        assert_eq!(result, Saturating(0x02_u32));
    }

    #[test]
    fn test_large_rotation() {
        let value = Saturating(0x01_u32);
        // Rotating left by 31 should result in 1000 0000 0000 0000 0000 0000 0000 0000
        let result = rotate_saturated_bits(value, 31);
        assert_eq!(result, Saturating(0x80000000_u32));
    }

    #[test]
    fn test_rotation_greater_than_32() {
        let value = Saturating(0x01_u32);
        // Rotating left by 33 should be equivalent to rotating by 1
        let result = rotate_saturated_bits(value, 33);
        assert_eq!(result, Saturating(0x02_u32));
    }

    #[test]
    fn test_rotation_with_multiple_bits_set() {
        let value = Saturating(0xF0F0F0F0_u32); // 1111 0000 1111 0000 1111 0000 1111 0000
        // Rotating left by 4 should result in 0000 1111 0000 1111 0000 1111 0000 1111
        let result = rotate_saturated_bits(value, 4);
        assert_eq!(result, Saturating(0x0F0F0F0F_u32));
    }

    #[test]
    fn test_max_value() {
        let value = Saturating(u32::MAX); // All bits set to 1
        // Rotating a value with all bits set should result in the same value
        let result = rotate_saturated_bits(value, 16);
        assert_eq!(result, Saturating(u32::MAX));
    }

    #[test]
    fn test_min_value() {
        let value = Saturating(0_u32);
        // Rotating 0 should always result in 0
        let result = rotate_saturated_bits(value, 8);
        assert_eq!(result, Saturating(0_u32));
    }

    #[test]
    fn test_property_double_rotation_equals_single() {
        let value = Saturating(0xDEADBEEF_u32);
        let rotation1 = 5;
        let rotation2 = 7;

        // Rotating by a + b should be equivalent to rotating by a then by b
        let result1 = rotate_saturated_bits(rotate_saturated_bits(value, rotation1), rotation2);
        let result2 = rotate_saturated_bits(value, rotation1 + rotation2);

        assert_eq!(result1, result2);
    }

    #[test]
    fn test_idempotent_rotation() {
        // Test that rotating by n then by 32-n gives back the original value
        let value = Saturating(0x12345678_u32);
        let rotation = 13;

        let intermediate = rotate_saturated_bits(value, rotation);
        let result = rotate_saturated_bits(intermediate, 32 - rotation);

        assert_eq!(result, value);
    }
}

