#[cfg(test)]
mod tests {
    use super::*;
    use std::num::Saturating;

    #[test]
    fn test_ensure_little_endian_positive_values() {
        let input = Saturating(42);
        let result = ensure_little_endian(input);

        // On little-endian systems (which is common), the value should remain the same
        // On big-endian systems, the bytes would be swapped
        if cfg!(target_endian = "little") {
            assert_eq!(result, Saturating(42));
        } else {
            assert_eq!(result, Saturating(i32::from_be_bytes(42i32.to_le_bytes())));
        }
    }

    #[test]
    fn test_ensure_little_endian_negative_values() {
        let input = Saturating(-12345);
        let result = ensure_little_endian(input);

        if cfg!(target_endian = "little") {
            assert_eq!(result, Saturating(-12345));
        } else {
            assert_eq!(result, Saturating(i32::from_be_bytes((-12345i32).to_le_bytes())));
        }
    }

    #[test]
    fn test_ensure_little_endian_zero() {
        let input = Saturating(0);
        let result = ensure_little_endian(input);

        // Zero should remain zero regardless of endianness
        assert_eq!(result, Saturating(0));
    }

    #[test]
    fn test_ensure_little_endian_max_value() {
        let input = Saturating(i32::MAX);
        let result = ensure_little_endian(input);

        if cfg!(target_endian = "little") {
            assert_eq!(result, Saturating(i32::MAX));
        } else {
            assert_eq!(result, Saturating(i32::from_be_bytes(i32::MAX.to_le_bytes())));
        }
    }

    #[test]
    fn test_ensure_little_endian_min_value() {
        let input = Saturating(i32::MIN);
        let result = ensure_little_endian(input);

        if cfg!(target_endian = "little") {
            assert_eq!(result, Saturating(i32::MIN));
        } else {
            assert_eq!(result, Saturating(i32::from_be_bytes(i32::MIN.to_le_bytes())));
        }
    }

    #[test]
    fn test_ensure_little_endian_roundtrip() {
        // Test that converting to little-endian and back works correctly
        let original = Saturating(987654);
        let le_value = ensure_little_endian(original);

        // Simulate a roundtrip by manually converting back to native endianness
        let bytes = (le_value.0).to_le_bytes();
        let roundtrip = Saturating(i32::from_le_bytes(bytes));

        assert_eq!(original, roundtrip);
    }

    #[test]
    fn test_ensure_little_endian_idempotent() {
        // Applying the function multiple times should have the same effect as applying it once
        let input = Saturating(54321);
        let result1 = ensure_little_endian(input);
        let result2 = ensure_little_endian(result1);

        assert_eq!(result1, result2);
    }
}

