fn safe_absolute_transaction(amount: Saturating<i32>) -> Saturating<i32> {
    amount.abs()
}

test_program:
#[cfg(test)]
mod tests {
    use std::num::Saturating;
    use super::safe_absolute_transaction;

    #[test]
    fn test_positive_amount() {
        let amount = Saturating(42);
        let result = safe_absolute_transaction(amount);
        assert_eq!(result.0, 42);
    }

    #[test]
    fn test_negative_amount() {
        let amount = Saturating(-42);
        let result = safe_absolute_transaction(amount);
        assert_eq!(result.0, 42);
    }

    #[test]
    fn test_zero_amount() {
        let amount = Saturating(0);
        let result = safe_absolute_transaction(amount);
        assert_eq!(result.0, 0);
    }

    #[test]
    fn test_extreme_positive_amount() {
        let amount = Saturating(i32::MAX);
        let result = safe_absolute_transaction(amount);
        assert_eq!(result.0, i32::MAX);
    }

    #[test]
    fn test_extreme_negative_amount() {
        // This is the critical test for safe absolute calculation
        let amount = Saturating(i32::MIN);
        let result = safe_absolute_transaction(amount);

        // i32::MIN is -2147483648, and its absolute value would be 2147483648,
        // which exceeds i32::MAX (2147483647). The Saturating type should handle this.
        assert_eq!(result.0, i32::MAX);
    }

    #[test]
    fn test_near_extreme_negative_amount() {
        let amount = Saturating(i32::MIN + 1);
        let result = safe_absolute_transaction(amount);

        // i32::MIN + 1 is -2147483647, and its absolute value is 2147483647 (i32::MAX)
        assert_eq!(result.0, i32::MAX);
    }

    #[test]
    fn test_idempotence() {
        // Running abs twice should be the same as running it once for positive values
        let amount = Saturating(42);
        let result1 = safe_absolute_transaction(amount);
        let result2 = safe_absolute_transaction(result1);
        assert_eq!(result1.0, result2.0);
    }

    #[test]
    fn test_original_amount_unchanged() {
        // Ensure the original Saturating<i32> is not modified
        let original = Saturating(-100);
        let amount = original;
        let _ = safe_absolute_transaction(amount);
        assert_eq!(original.0, -100);
    }
}

