fn initialize_shared_resource(resource: &OnceLock<String>, value: String) -> Result<(), String> {
    resource.set(value)
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, OnceLock};
    use std::thread;

    #[test]
    fn test_first_initialization_succeeds() {
        let resource = OnceLock::new();
        let result = initialize_shared_resource(&resource, "initial value".to_string());
        assert!(result.is_ok());
        assert_eq!(resource.get().unwrap(), "initial value");
    }

    #[test]
    fn test_second_initialization_fails() {
        let resource = OnceLock::new();
        let first_result = initialize_shared_resource(&resource, "first value".to_string());
        let second_result = initialize_shared_resource(&resource, "second value".to_string());

        assert!(first_result.is_ok());
        assert!(second_result.is_err());
        assert_eq!(resource.get().unwrap(), "first value");
    }

    #[test]
    fn test_concurrent_initialization() {
        let resource = Arc::new(OnceLock::new());
        let threads_count = 10;
        let mut handles = Vec::with_capacity(threads_count);

        // Count successful and failed initializations
        let success_count = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let failure_count = Arc::new(std::sync::atomic::AtomicUsize::new(0));

        for i in 0..threads_count {
            let resource_clone = Arc::clone(&resource);
            let success_counter = Arc::clone(&success_count);
            let failure_counter = Arc::clone(&failure_count);

            let handle = thread::spawn(move || {
                let value = format!("value from thread {}", i);
                let result = initialize_shared_resource(&resource_clone, value);

                match result {
                    Ok(_) => {
                        success_counter.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    }
                    Err(_) => {
                        failure_counter.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    }
                }
            });

            handles.push(handle);
        }

        // Wait for all threads to complete
        for handle in handles {
            handle.join().unwrap();
        }

        // Verify that exactly one thread succeeded and the rest failed
        assert_eq!(success_count.load(std::sync::atomic::Ordering::SeqCst), 1);
        assert_eq!(failure_count.load(std::sync::atomic::Ordering::SeqCst), threads_count - 1);

        // Verify that the resource contains a value
        assert!(resource.get().is_some());
        assert!(resource.get().unwrap().starts_with("value from thread "));
    }

    #[test]
    fn test_empty_string_initialization() {
        let resource = OnceLock::new();
        let result = initialize_shared_resource(&resource, String::new());

        assert!(result.is_ok());
        assert_eq!(resource.get().unwrap(), "");
    }

    #[test]
    fn test_read_after_initialization() {
        let resource = OnceLock::new();
        initialize_shared_resource(&resource, "test value".to_string()).unwrap();

        // Multiple reads should return the same value
        assert_eq!(resource.get().unwrap(), "test value");
        assert_eq!(resource.get().unwrap(), "test value");
    }
}

