    fn test_ipv4_mapped_alternate_form() {
        // Another valid form (::ffff:127.0.0.1)
        let ipv6 = Ipv6Addr::new(0, 0, 0, 0, 0, 0xffff, 0x7f00, 0x0001);
        let expected = Ipv4Addr::new(127, 0, 0, 1);
        let result = convert_to_ipv4_mapped(&ipv6);
        assert_eq!(result, Some(expected));
    }

    #[test]
    fn test_not_ipv4_mapped_invalid_prefix() {
        // Not an IPv4-mapped address (2001:db8::1)
        let ipv6 = Ipv6Addr::new(0x2001, 0x0db8, 0, 0, 0, 0, 0, 1);
        let result = convert_to_ipv4_mapped(&ipv6);
        assert_eq!(result, None);
