        // Has last 32 bits like IPv4 but wrong prefix (::192.0.2.1 instead of ::ffff:192.0.2.1)
        let ipv6 = Ipv6Addr::new(0, 0, 0, 0, 0, 0, 0xc000, 0x0201);
        let result = convert_to_ipv4_mapped(&ipv6);
