        }
    }

    impl Error for CustomError {
        fn description(&self) -> &str {
            &self.message
        }
    }

    // Test with a basic custom error
    #[test]
    fn test_custom_error() {
        let error = Box::new(CustomError::new("Test error message")) as Box<dyn Error>;
        let result = extract_error_description(error);
        assert_eq!(result, "Test error message");
    }

    // Test with a standard library error
    #[test]
    fn test_io_error() {
        let error = Box::new(io::Error::new(io::ErrorKind::NotFound, "File not found")) as Box<dyn Error>;
        let result = extract_error_description(error);
        assert_eq!(result, "File not found");
    }

    // Test with nested errors (error wrapping another error)
    #[derive(Debug)]
    struct WrappingError {
        source: Box<dyn Error>,
        context: String,
    }

    impl WrappingError {
        fn new(source: Box<dyn Error>, context: &str) -> Self {
            WrappingError {
                source,
                context: context.to_string(),
            }
        }
    }

    impl fmt::Display for WrappingError {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            write!(f, "{}: {}", self.context, self.source)
        }
    }

    impl Error for WrappingError {
        fn description(&self) -> &str {
            &self.context
        }

        fn source(&self) -> Option<&(dyn Error + 'static)> {
            Some(self.source.as_ref())
        }
    }

    #[test]
    fn test_wrapped_error() {
        let inner_error = Box::new(CustomError::new("Inner error")) as Box<dyn Error>;
        let error = Box::new(WrappingError::new(inner_error, "Wrapped context")) as Box<dyn Error>;
        let result = extract_error_description(error);
