use std::cmp::Ordering;

fn find_pointer_position(sorted_pointers: &[*const i32], target: *const i32) -> Option<usize> {
    let mut left = 0;
    let mut right = sorted_pointers.len();

    while left < right {
        let mid = left + (right - left) / 2;
        match sorted_pointers[mid].cmp(&target) {
            Ordering::Less => left = mid + 1,
            Ordering::Greater => right = mid,
            Ordering::Equal => return Some(mid),
        }
    }

    None
}

