#[cfg(test)]
mod tests {
    use std::cmp::Ordering;
    use std::ptr;

    // Import the function we're testing
    use super::find_pointer_position;

    #[test]
    fn test_empty_array() {
        let pointers: Vec<*const i32> = Vec::new();
        let target = ptr::null();
        assert_eq!(find_pointer_position(&pointers, target), None);
    }

    #[test]
    fn test_target_not_present() {
        let values = [1, 2, 3, 4, 5];
        let pointers: Vec<*const i32> = values.iter().map(|v| v as *const i32).collect();
        let non_existent = &10 as *const i32;

        assert_eq!(find_pointer_position(&pointers, non_existent), None);
    }

    #[test]
    fn test_target_present_beginning() {
        let values = [1, 2, 3, 4, 5];
        let pointers: Vec<*const i32> = values.iter().map(|v| v as *const i32).collect();

        assert_eq!(find_pointer_position(&pointers, pointers[0]), Some(0));
    }

    #[test]
    fn test_target_present_middle() {
        let values = [1, 2, 3, 4, 5];
        let pointers: Vec<*const i32> = values.iter().map(|v| v as *const i32).collect();

        assert_eq!(find_pointer_position(&pointers, pointers[2]), Some(2));
    }

    #[test]
    fn test_target_present_end() {
        let values = [1, 2, 3, 4, 5];
        let pointers: Vec<*const i32> = values.iter().map(|v| v as *const i32).collect();

        assert_eq!(find_pointer_position(&pointers, pointers[4]), Some(4));
    }

    #[test]
    fn test_with_duplicates() {
        let values = [1, 2, 2, 3, 4, 4, 5];
        let pointers: Vec<*const i32> = values.iter().map(|v| v as *const i32).collect();

        // Should find the first occurrence of the duplicate
        assert_eq!(find_pointer_position(&pointers, pointers[1]), Some(1));
        assert_eq!(find_pointer_position(&pointers, pointers[2]), Some(2));
    }

    #[test]
    fn test_single_element() {
        let values = [42];
        let pointers: Vec<*const i32> = values.iter().map(|v| v as *const i32).collect();

        assert_eq!(find_pointer_position(&pointers, pointers[0]), Some(0));

        let non_existent = &10 as *const i32;
        assert_eq!(find_pointer_position(&pointers, non_existent), None);
    }

    #[test]
    fn test_with_null_pointers() {
        let mut values = [1, 2, 3];
        let null_ptr = ptr::null();

        // Create an array of pointers including a null pointer
        let pointers = [
            &values[0] as *const i32,
            null_ptr,
            &values[1] as *const i32,
            &values[2] as *const i32,
        ];

        // Sort the pointers (null is typically the smallest)
        let mut sorted_pointers = pointers.to_vec();
        sorted_pointers.sort_by(|a, b| a.cmp(b));

        // Find null pointer
        assert_eq!(find_pointer_position(&sorted_pointers, null_ptr), Some(0));

        // Find a regular pointer
        assert_eq!(find_pointer_position(&sorted_pointers, &values[0] as *const i32), Some(1));
    }

    #[test]
    fn test_large_array() {
        let values: Vec<i32> = (0..1000).collect();
        let pointers: Vec<*const i32> = values.iter().map(|v| v as *const i32).collect();

        // Test finding an element in the first third
        assert_eq!(find_pointer_position(&pointers, pointers[123]), Some(123));

        // Test finding an element in the middle
        assert_eq!(find_pointer_position(&pointers, pointers[500]), Some(500));

        // Test finding an element in the last third
        assert_eq!(find_pointer_position(&pointers, pointers[876]), Some(876));
    }

    #[test]
    fn test_with_unaligned_pointers() {
        // Create a struct with padding to ensure unaligned memory access
        #[repr(C)]
        struct Padded {
            _pad: u8,
            value: i32,
        }

        let values = [
            Padded { _pad: 0, value: 1 },
            Padded { _pad: 0, value: 2 },
            Padded { _pad: 0, value: 3 },
        ];

        // Create pointers to the i32 fields inside the structs
        let pointers: Vec<*const i32> = values.iter()
            .map(|v| &v.value as *const i32)
            .collect();

        // Find a pointer in the array
        assert_eq!(find_pointer_position(&pointers, pointers[1]), Some(1));
    }
}

