        let mut large_data = [0; 1024];
        for i in 0..large_data.len() {
            large_data[i] = (i % 256) as u8;
        }

        if let Some((header, remainder)) = split_header_mut(&mut large_data) {
            assert_eq!(header.len(), 16);
