        }
    }

    #[test]
    fn test_idempotence() {
        // Testing that applying the function twice gives the same result as applying it once
        let test_values = [-42, -1, 1, 42];

        for &val in &test_values {
            let nonzero = NonZeroI32::new(val).unwrap();
            let result_once = compute_absolute_value(nonzero);
            let result_twice = compute_absolute_value(result_once);

            assert_eq!(result_once, result_twice);
        }
    }
}

