    fn test_powers_of_two() {
        // Powers of two should return themselves
        for i in 0..31 {
            let power_of_two = 1u32 << i;
            let input = NonZeroU32::new(power_of_two).unwrap();
            let result = next_power_of_two_safe(input).unwrap();
            assert_eq!(result.get(), power_of_two);
        }
    }

    #[test]
    fn test_non_powers_of_two() {
        // Test with values that are not powers of two
        let test_cases = [
            (3, 4),
            (5, 8),
            (6, 8),
            (7, 8),
            (9, 16),
            (15, 16),
            (17, 32),
            (42, 64),
            (100, 128),
            (1000, 1024),
            (1025, 2048),
            (123456, 131072),
        ];

        for (input, expected) in test_cases {
            let input = NonZeroU32::new(input).unwrap();
            let result = next_power_of_two_safe(input).unwrap();
            assert_eq!(result.get(), expected);
        }
    }

    #[test]
    fn test_edge_cases() {
        // Test minimum value
        let min = NonZeroU32::new(1).unwrap();
        assert_eq!(next_power_of_two_safe(min).unwrap().get(), 1);

        // Test values close to max
        let almost_max = NonZeroU32::new(1 << 30).unwrap();
        assert_eq!(next_power_of_two_safe(almost_max).unwrap().get(), 1 << 30);

        let almost_max_plus_one = NonZeroU32::new((1 << 30) + 1).unwrap();
        assert_eq!(next_power_of_two_safe(almost_max_plus_one).unwrap().get(), 1 << 31);

        // Test maximum power of two (2^31)
        let max_power = NonZeroU32::new(1 << 31).unwrap();
        assert_eq!(next_power_of_two_safe(max_power).unwrap().get(), 1 << 31);
    }

    #[test]
    fn test_overflow_cases() {
        // Test values that would cause overflow in next power of two

        // Any value larger than 2^31 should return None
        let largest_valid = NonZeroU32::new((1u32 << 31) - 1).unwrap();
        assert_eq!(next_power_of_two_safe(largest_valid).unwrap().get(), 1 << 31);

        let overflow_value = NonZeroU32::new(1u32 << 31).unwrap();
        assert_eq!(next_power_of_two_safe(overflow_value).unwrap().get(), 1 << 31);

        // Check values beyond 2^31 but less than u32::MAX
        for i in 1..100 {
            let overflow_value = NonZeroU32::new((1u32 << 31) + i).unwrap();
            assert!(next_power_of_two_safe(overflow_value).is_none());
        }

        // Test absolute maximum value
        let max = NonZeroU32::new(u32::MAX).unwrap();
        assert!(next_power_of_two_safe(max).is_none());
    }
}

