#[cfg(test)]
mod tests {
    use super::*;
    use std::thread;
    use std::sync::Arc;
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::io;

    #[test]
    fn test_adjust_thread_pool_size_returns_nonzero() {
        // Basic test to ensure we get a non-zero thread count
        match adjust_thread_pool_size() {
            Ok(size) => {
                assert!(size > 0, "Thread pool size should be greater than zero");
            }
            Err(e) => {
                panic!("adjust_thread_pool_size failed: {}", e);
            }
        }
    }

    #[test]
    fn test_adjust_thread_pool_size_matches_available_parallelism() {
        // Test that the function returns the same value as thread::available_parallelism
        let expected = thread::available_parallelism().map(|p| p.get());
        let actual = adjust_thread_pool_size();

        match (expected, actual) {
            (Ok(e), Ok(a)) => {
                assert_eq!(e, a, "Thread pool size should match available_parallelism");
            }
            (Err(_), Err(_)) => {
                // Both failed, which is consistent
            }
            (Ok(_), Err(e)) => {
                panic!("adjust_thread_pool_size failed but available_parallelism succeeded: {}", e);
            }
            (Err(e), Ok(_)) => {
                panic!("available_parallelism failed but adjust_thread_pool_size succeeded: {}", e);
            }
        }
    }

    #[test]
    fn test_thread_pool_size_can_utilize_all_cores() {
        // Test that we can actually create and use the suggested number of threads
        match adjust_thread_pool_size() {
            Ok(size) => {
                let counter = Arc::new(AtomicUsize::new(0));
                let mut handles = vec![];

                for _ in 0..size {
                    let counter_clone = Arc::clone(&counter);
                    let handle = thread::spawn(move || {
                        counter_clone.fetch_add(1, Ordering::SeqCst);
                    });
                    handles.push(handle);
                }

                for handle in handles {
                    handle.join().expect("Thread panicked");
                }

                assert_eq!(counter.load(Ordering::SeqCst), size, 
                           "All threads should have executed successfully");
            }
            Err(e) => {
                panic!("adjust_thread_pool_size failed: {}", e);
            }
        }
    }

    #[test]
    fn test_error_propagation() {
        // This test uses a mock to verify error handling
        // In a real environment, it's hard to cause thread::available_parallelism to fail
        // So we'll test our error handling with a mock implementation

        // Normally you would use a mocking framework, but for simplicity
        // we're just going to test the error handling directly

        // This assumes adjust_thread_pool_size only fails if thread::available_parallelism fails
        // and that it correctly propagates the error type

        let os_error = io::Error::new(io::ErrorKind::Other, "Mock error for testing");
        if let Err(e) = adjust_thread_pool_size() {
            assert_eq!(e.kind(), io::ErrorKind::Other, 
                      "Error should be of same kind as available_parallelism would return");
        }
        // Note: This test will pass regardless of whether adjust_thread_pool_size returns Ok or Err
        // In a real test, you would mock thread::available_parallelism to force an error
    }
}

