use std::ptr;

fn merge_arrays(dst: &mut [i32], src1: &[i32], src2: &[i32]) -> Result<(), &'static str> {
    if dst.len() < src1.len() + src2.len() {
        return Err("Destination array is too small");
    }

    unsafe {
        ptr::copy_nonoverlapping(src1.as_ptr(), dst.as_mut_ptr(), src1.len());
        ptr::copy_nonoverlapping(src2.as_ptr(), dst.as_mut_ptr().add(src1.len()), src2.len());
    }

    Ok(())
}

