mod tests {
    use std::io::{self, Write, Result};
    use super::write_static_strings_to_buffer;

    struct MockWriter {
        data: Vec<u8>,
        write_error_on: Option<usize>,
        bytes_written: usize,
    }

    impl MockWriter {
        fn new() -> Self {
            Self {
                data: Vec::new(),
                write_error_on: None,
                bytes_written: 0,
            }
        }

        fn with_error_on_byte(byte_position: usize) -> Self {
            Self {
                data: Vec::new(),
                write_error_on: Some(byte_position),
                bytes_written: 0,
            }
        }

        fn as_string(&self) -> String {
            String::from_utf8_lossy(&self.data).to_string()
        }
    }

    impl Write for MockWriter {
        fn write(&mut self, buf: &[u8]) -> Result<usize> {
            if let Some(pos) = self.write_error_on {
                if self.bytes_written + buf.len() > pos {
                    return Err(io::Error::new(io::ErrorKind::Other, "simulated write error"));
                }
            }

            self.data.extend_from_slice(buf);
            self.bytes_written += buf.len();
            Ok(buf.len())
        }

        fn flush(&mut self) -> Result<()> {
            Ok(())
        }
    }

    #[test]
    fn test_empty_strings_array() {
