fn extract_invalid_sequences(input: &str) -> Vec<(usize, &[u8])> {
    let mut result = Vec::new();
    let mut bytes = input.as_bytes();
    let mut pos = 0;

    while let Some((invalid, len)) = std::str::from_utf8(&bytes[pos..])
        .err()
        .and_then(|e| e.valid_up_to().checked_add(e.error_len().unwrap_or(0)))
        .map(|len| (&bytes[pos..pos + len], len))
    {
        result.push((pos, invalid));
        pos += len;
    }

    result
}

