    fn test_invalid_digit_error() {
        // Attempt to parse a string with invalid digits
        let error = "abc".parse::<i32>().unwrap_err();
        let kind = classify_parsing_error(&error);
        assert!(matches!(kind, IntErrorKind::InvalidDigit));
    }

