    fn test_positive_overflow_error() {
        // Attempt to parse a number too large for i32
        let error = "2147483648".parse::<i32>().unwrap_err();
        let kind = classify_parsing_error(&error);
        assert!(matches!(kind, IntErrorKind::PosOverflow));
    }

    #[test]
    fn test_negative_overflow_error() {
        // Attempt to parse a number too small for i32
        let error = "-2147483649".parse::<i32>().unwrap_err();
        let kind = classify_parsing_error(&error);
        assert!(matches!(kind, IntErrorKind::NegOverflow));
    }

