        // with different ParseIntError instances

        // u64
        let error = "18446744073709551616".parse::<u64>().unwrap_err();
        let kind = classify_parsing_error(&error);
        assert!(matches!(kind, IntErrorKind::PosOverflow));

        // i16
        let error = "32768".parse::<i16>().unwrap_err();
        let kind = classify_parsing_error(&error);
        assert!(matches!(kind, IntErrorKind::PosOverflow));

        // i8
        let error = "-129".parse::<i8>().unwrap_err();
        let kind = classify_parsing_error(&error);
        assert!(matches!(kind, IntErrorKind::NegOverflow));
    }

    #[test]
    fn test_negative_for_unsigned() {
