fn transform_chars_with_position(s: &str, transform: fn(char, usize) -> char) -> String {
    let mut result = String::with_capacity(s.len());
    let mut chars = s.chars();
    let mut index = 0;

    while let Some(c) = chars.next() {
        result.push(transform(c, index));
        index += 1;
    }

    result
}

