        let input = "abcde";
        let result = transform_chars_with_position(input, |c, i| {
            if i % 2 == 0 {
                c.to_ascii_uppercase()
            } else {
                c
            }
        });
        assert_eq!(result, "AbCdE");
    }

    #[test]
    fn test_shift_based_on_position() {
        let input = "abcde";
        let result = transform_chars_with_position(input, |c, i| {
            if c.is_ascii_lowercase() {
                // Shift character by its position (wrapping around the alphabet)
                let base = 'a' as u8;
                let shifted = (((c as u8 - base) + (i as u8 % 26)) % 26) + base;
                shifted as char
            } else {
                c
            }
        });
        assert_eq!(result, "acegi");
    }

    #[test]
    fn test_with_unicode() {
        let input = "こんにちは";
        let result = transform_chars_with_position(input, |c, i| {
            if i % 2 == 0 {
                c
            } else {
                '★' // Replace odd-positioned characters with a star
            }
        });
        assert_eq!(result, "こ★に★は");
    }

    #[test]
    fn test_large_string() {
        let input = "a".repeat(10000);
        let result = transform_chars_with_position(&input, |_, i| {
            // Convert position to digit character (cycling through 0-9)
            let digit = (i % 10) as u8 + b'0';
            digit as char
        });

        // Check the first 20 characters should be "01234567890123456789"
        assert_eq!(&result[0..20], "01234567890123456789");

        // Check the length is preserved
        assert_eq!(result.len(), 10000);

        // Check the last 10 characters
        let expected_end: String = (0..10).map(|i| char::from_digit((i % 10) as u32, 10).unwrap()).collect();
        assert_eq!(&result[9990..10000], expected_end);
    }

    #[test]
    fn test_change_string_length() {
        // This is testing a specific use case where we might want to
        // return empty for certain characters, effectively reducing the string length
        let input = "a1b2c3";
        let result = transform_chars_with_position(input, |c, _| {
            if c.is_digit(10) {
                '\0' // Using null character which will be included in the string
            } else {
