use std::collections::VecDeque;

fn process_front_n_elements(queue: &mut VecDeque<i32>, n: usize) -> Vec<i32> {
    let mut result = Vec::with_capacity(n);
    for _ in 0..n {
        if let Some(element) = queue.pop_front() {
            result.push(element);
        } else {
            break;
        }
    }
    result
}

