    use std::thread;

    #[test]
    fn test_get_shared_config_returns_valid_reference() {
        let config = get_shared_config();
        assert!(!config.is_null());
    }

    #[test]
    fn test_get_shared_config_returns_same_instance() {
        let config1 = get_shared_config() as *const Configuration;
        let config2 = get_shared_config() as *const Configuration;
        assert_eq!(config1, config2);
    }

    #[test]
    fn test_get_shared_config_initializes_only_once() {
        // This test requires modifying the actual implementation to include
        // a counter that tracks initialization, but we'll simulate the check here

        // Get the initial reference
        let initial_ref = get_shared_config() as *const Configuration;

        // Access from multiple threads
        let thread_count = 8;
        let barrier = Arc::new(Barrier::new(thread_count));

        let handles: Vec<_> = (0..thread_count)
            .map(|_| {
                let barrier_clone = Arc::clone(&barrier);
                thread::spawn(move || {
                    // Synchronize all threads to call get_shared_config simultaneously
                    barrier_clone.wait();
                    let thread_ref = get_shared_config() as *const Configuration;
                    // Return plain pointer address as usize which is thread-safe
                    thread_ref as usize
                })
            })
            .collect();

        // Collect all thread results
        let thread_refs: Vec<_> = handles
            .into_iter()
            .map(|h| h.join().unwrap())
            .collect();

        // Get the initial reference as usize for comparison
        let initial_ref_addr = initial_ref as usize;

        // Verify all threads got the same reference
        for thread_ref in thread_refs {
            assert_eq!(initial_ref_addr, thread_ref);
        }
    }

    #[test]
    fn test_get_shared_config_is_thread_safe() {
        let thread_count = 100;
        let handles: Vec<_> = (0..thread_count)
            .map(|_| {
                thread::spawn(|| {
                    // Simply accessing the config from multiple threads
                    // If there's a thread safety issue, this might panic or cause data races
                    let _ = get_shared_config();
                })
            })
            .collect();

        // Make sure all threads complete without panicking
        for handle in handles {
            handle.join().unwrap();
        }
    }

    // Helper method to check if a reference is null without using is_null directly
    trait NullCheck {
        fn is_null(&self) -> bool;
    }

    impl NullCheck for &Configuration {
        fn is_null(&self) -> bool {
            let ptr = *self as *const Configuration;
            ptr == std::ptr::null()
        }
    }
}

