        assert_eq!(convert_ipv6_from_bits(bits), expected);
    }

    #[test]
    fn test_bit_conversion() {
        // Verify that each octet is positioned correctly
        let bits: u128 = 0x0123456789abcdef0123456789abcdef;
        let expected = Ipv6Addr::new(0x0123, 0x4567, 0x89ab, 0xcdef, 0x0123, 0x4567, 0x89ab, 0xcdef);
        assert_eq!(convert_ipv6_from_bits(bits), expected);
    }

    #[test]
    fn test_from_octets_equality() {
        // Test that conversion from bits matches the Ipv6Addr::new construction
        let bits: u128 = 0xaa01bb02cc03dd04ee05ff060708090a;

        // Create the same address using the byte-level constructor
        let bytes = [
            0xaa, 0x01, 0xbb, 0x02, 0xcc, 0x03, 0xdd, 0x04,
            0xee, 0x05, 0xff, 0x06, 0x07, 0x08, 0x09, 0x0a,
        ];
        let expected = Ipv6Addr::from(bytes);

        assert_eq!(convert_ipv6_from_bits(bits), expected);
    }

    #[test]
    fn test_to_string_representation() {
        // Test the string representation after conversion
        let bits: u128 = 0x20010db8000000000000000000000001;
        let addr = convert_ipv6_from_bits(bits);
        assert_eq!(addr.to_string(), "2001:db8::1");
    }

    #[test]
    fn test_roundtrip_conversion() {
        // Test that converting to bits and back preserves the address
        let original_bits: u128 = 0x20010db8000300000000ffff00000001;
        let addr = convert_ipv6_from_bits(original_bits);
        let roundtrip_bits = u128::from_be_bytes(addr.octets());
        assert_eq!(original_bits, roundtrip_bits);
    }
}

