#[cfg(test)]
mod tests {
    use std::ptr::NonNull;
    use std::alloc::{alloc, Layout, dealloc};

    // Import the function being tested
    use super::compute_byte_address;

    #[test]
    fn test_zero_offset() {
        // Allocate memory
        let layout = Layout::from_size_align(8, 1).unwrap();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };

        // Test with zero offset
        let result = compute_byte_address(ptr, 0);
        assert_eq!(result.as_ptr(), ptr.as_ptr());

        // Clean up
        unsafe { dealloc(ptr.as_ptr(), layout); }
    }

    #[test]
    fn test_positive_offset() {
        // Allocate memory
        let layout = Layout::from_size_align(8, 1).unwrap();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };

        // Initialize memory
        unsafe {
            for i in 0..8 {
                *ptr.as_ptr().add(i) = i as u8;
            }
        }

        // Test with various offsets
        for offset in 1..8 {
            let result = compute_byte_address(ptr, offset);
            assert_eq!(result.as_ptr(), unsafe { ptr.as_ptr().add(offset) });

            // Check that the value at the computed address is correct
            unsafe {
                assert_eq!(*result.as_ptr(), offset as u8);
            }
        }

        // Clean up
        unsafe { dealloc(ptr.as_ptr(), layout); }
    }

    #[test]
    fn test_large_offset() {
        // Allocate larger memory block
        let layout = Layout::from_size_align(1024, 1).unwrap();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };

        // Test with larger offset
        let offset = 1000;
        let result = compute_byte_address(ptr, offset);
        assert_eq!(result.as_ptr(), unsafe { ptr.as_ptr().add(offset) });

        // Clean up
        unsafe { dealloc(ptr.as_ptr(), layout); }
    }

    #[test]
    fn test_with_aligned_memory() {
        // Allocate aligned memory
        let layout = Layout::from_size_align(16, 8).unwrap();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };

        // Ensure pointer is aligned correctly
        assert_eq!(ptr.as_ptr() as usize % 8, 0);

        // Test with offsets that maintain and break alignment
        let aligned_offset = 8;
        let unaligned_offset = 3;

        let aligned_result = compute_byte_address(ptr, aligned_offset);
        let unaligned_result = compute_byte_address(ptr, unaligned_offset);

        assert_eq!(aligned_result.as_ptr() as usize % 8, 0);
        assert_eq!(unaligned_result.as_ptr() as usize % 8, 3);

        // Clean up
        unsafe { dealloc(ptr.as_ptr(), layout); }
    }

    #[test]
    fn test_address_calculation() {
        // Allocate memory
        let layout = Layout::from_size_align(8, 1).unwrap();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };

        // Calculate expected address manually
        let base_addr = ptr.as_ptr() as usize;
        let offset = 5;
        let expected_addr = base_addr + offset;

        // Test with offset
        let result = compute_byte_address(ptr, offset);
        assert_eq!(result.as_ptr() as usize, expected_addr);

        // Clean up
        unsafe { dealloc(ptr.as_ptr(), layout); }
    }

    #[test]
    fn test_multiple_operations() {
        // Allocate memory
        let layout = Layout::from_size_align(16, 1).unwrap();
        let ptr = unsafe { NonNull::new_unchecked(alloc(layout)) };

        // Apply multiple offsets
        let first_offset = 4;
        let second_offset = 3;

        let intermediate = compute_byte_address(ptr, first_offset);
        let final_result = compute_byte_address(intermediate, second_offset);

        // Compare with directly computing the total offset
        let direct_result = compute_byte_address(ptr, first_offset + second_offset);

        assert_eq!(final_result.as_ptr(), direct_result.as_ptr());
        assert_eq!(final_result.as_ptr(), unsafe { ptr.as_ptr().add(first_offset + second_offset) });

        // Clean up
        unsafe { dealloc(ptr.as_ptr(), layout); }
    }
}

