    fn test_previous_byte_address_with_zero_offset() {
        // Create a buffer
        let mut buffer = vec![1, 2, 3, 4, 5];

        // Get a non-null pointer to the start of the buffer
        let ptr = NonNull::new(buffer.as_mut_ptr()).unwrap();

        // With zero offset, the address should remain the same
        let result = previous_byte_address(ptr, 0);

        assert_eq!(ptr.as_ptr(), result.as_ptr());
    }

