    fn test_previous_byte_address_with_small_offset() {
        // Create a buffer large enough to test
        let mut buffer = vec![10, 20, 30, 40, 50];

        // Get a non-null pointer to the 3rd element
        let third_element_ptr = NonNull::new(unsafe { buffer.as_mut_ptr().add(2) }).unwrap();

        // Go back 2 bytes, should point to the 1st element
        let result = previous_byte_address(third_element_ptr, 2);

        // The result should point to the first element
        assert_eq!(unsafe { *result.as_ptr() }, 10);
    }

    #[test]
    fn test_previous_byte_address_with_exact_buffer_size() {
        // Create a buffer
        let mut buffer = vec![1, 2, 3, 4, 5];

        // Get a non-null pointer to the end of the buffer
        let end_ptr = NonNull::new(unsafe { buffer.as_mut_ptr().add(buffer.len()) }).unwrap();

        // Go back exactly the buffer size
        let result = previous_byte_address(end_ptr, buffer.len());

        // The result should point to the beginning of the buffer
        assert_eq!(buffer.as_ptr(), result.as_ptr());
    }

    #[test]
    fn test_previous_byte_address_aligned_memory() {
        // Create a buffer with i32 values to test memory alignment
        let mut buffer: Vec<i32> = vec![101, 102, 103, 104];

        // Get pointer to end of buffer
        let ptr_end = NonNull::new(unsafe { 
            buffer.as_mut_ptr().cast::<u8>().add(buffer.len() * std::mem::size_of::<i32>())
        }).unwrap();

        // Go back one i32 (4 bytes on most systems)
        let result = previous_byte_address(ptr_end, std::mem::size_of::<i32>());

        // Cast the pointer to i32 pointer and check the value
        let value = unsafe { *(result.as_ptr() as *const i32) };
        assert_eq!(value, 104); // Should point to the last element
    }

    #[test]
    fn test_previous_byte_address_with_custom_struct() {
        // Define a custom struct with different sized fields
        #[repr(C)]
        struct TestStruct {
            a: u8,
            b: u16,
            c: u32,
        }

        // Create an instance of the struct
        let mut test_struct = TestStruct {
            a: 10,
            b: 20,
            c: 30,
        };

        // Get pointer to the struct
        let struct_ptr = NonNull::new(&mut test_struct as *mut TestStruct).unwrap();

        // Convert to u8 pointer and point to the end
        let end_ptr = NonNull::new(unsafe {
            (struct_ptr.as_ptr() as *mut u8).add(std::mem::size_of::<TestStruct>())
        }).unwrap();

        // Go back to the start of field c (offset by size of u32)
        let field_c_ptr = previous_byte_address(end_ptr, std::mem::size_of::<u32>());

        // Verify we're pointing to field c
        let value = unsafe { *(field_c_ptr.as_ptr() as *const u32) };
        assert_eq!(value, 30);
    }
