#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_already_aligned() {
        // Create a memory block aligned to 8 bytes
        let data = vec![0u8; 64];
        let aligned_offset = 8 - (data.as_ptr() as usize % 8);
        let aligned_ptr = unsafe { NonNull::new_unchecked(data.as_ptr().add(aligned_offset).cast_mut()) };

        // If already aligned to 8, offset should be 0
        assert_eq!(calculate_alignment_offset(aligned_ptr, 8), 0);
    }

    #[test]
    fn test_power_of_two_alignments() {
        // Allocate memory that we can manipulate
        let mut data = vec![0u8; 256];
        let base_ptr = data.as_mut_ptr();

        // Test various power-of-two alignments
        for align in [2, 4, 8, 16, 32, 64, 128].iter() {
            // Create a deliberately misaligned pointer by adding 1 to an aligned address
            let aligned_addr = (base_ptr as usize + *align - 1) & !(align - 1);
            let misaligned_ptr = unsafe { NonNull::new_unchecked((aligned_addr + 1) as *mut u8) };

            let offset = calculate_alignment_offset(misaligned_ptr, *align);

            // Verify offset is correct by checking the aligned pointer
            let resulting_addr = misaligned_ptr.as_ptr() as usize + offset;
            assert_eq!(resulting_addr % align, 0, 
                       "Alignment to {} failed: address {:#x} with offset {} resulted in {:#x}", 
                       align, misaligned_ptr.as_ptr() as usize, offset, resulting_addr);

            // Offset should be less than the alignment
            assert!(offset < *align);
        }
    }

    #[test]
    fn test_alignment_of_one() {
        // Any pointer is already aligned to 1
        let data = vec![0u8; 16];
        let ptr = unsafe { NonNull::new_unchecked(data.as_ptr().cast_mut()) };

        assert_eq!(calculate_alignment_offset(ptr, 1), 0);
    }

    #[test]
    fn test_large_alignment() {
        // Test with a larger, but still power-of-two alignment
        const LARGE_ALIGN: usize = 4096; // 4KB, typical page size

        let data = vec![0u8; LARGE_ALIGN * 2];
        let ptr = unsafe { NonNull::new_unchecked(data.as_ptr().cast_mut()) };

        let offset = calculate_alignment_offset(ptr, LARGE_ALIGN);

        // Verify the resulting pointer is properly aligned
        let aligned_addr = ptr.as_ptr() as usize + offset;
        assert_eq!(aligned_addr % LARGE_ALIGN, 0);
        assert!(offset < LARGE_ALIGN);
    }

    #[test]
    fn test_real_allocation() {
        // Allocate memory using the system allocator, which might not be aligned
        // to our desired alignment
        let layout = std::alloc::Layout::from_size_align(100, 8).unwrap();
        let ptr = unsafe { std::alloc::alloc(layout) };
        assert!(!ptr.is_null());

        let ptr = unsafe { NonNull::new_unchecked(ptr) };

        // Test alignment to 64 bytes (typical cache line size)
        let offset = calculate_alignment_offset(ptr, 64);
        let aligned_addr = ptr.as_ptr() as usize + offset;

        assert_eq!(aligned_addr % 64, 0);
        assert!(offset < 64);

        // Clean up
        unsafe { std::alloc::dealloc(ptr.as_ptr(), layout); }
    }

    #[test]
    #[should_panic]
    fn test_non_power_of_two_alignment() {
        // Alignment must be a power of two, so this should panic
        let data = vec![0u8; 16];
        let ptr = unsafe { NonNull::new_unchecked(data.as_ptr().cast_mut()) };

        // This should panic because 3 is not a power of two
        let _ = calculate_alignment_offset(ptr, 3);
    }

    #[test]
    fn test_zero_offset_when_already_aligned() {
        let mut data = [0u8; 64];
        let addr = data.as_mut_ptr() as usize;

        // Find an alignment that divides our address evenly
        // This is a bit of a hack but works for testing
        for align in [2, 4, 8, 16, 32].iter() {
            if addr % align == 0 {
                let ptr = unsafe { NonNull::new_unchecked(data.as_mut_ptr()) };
                assert_eq!(calculate_alignment_offset(ptr, *align), 0,
                           "Expected zero offset for pointer {:#x} already aligned to {}", 
                           addr, align);
                break;
            }
        }
    }
}

