use std::num::{NonZero, NonZeroI32};

pub fn compute_unsigned_abs(n: NonZeroI32) -> NonZero<u32> {
    n.unsigned_abs()
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_positive_values() {
        // Test with positive values
        let test_values = [1, 5, 10, 42, i32::MAX];

        for &val in &test_values {
            let non_zero = NonZeroI32::new(val).unwrap();
            let result = compute_unsigned_abs(non_zero);

            // The result should be the same as the input for positive values
            assert_eq!(result.get(), val as u32);
        }
    }

    #[test]
    fn test_negative_values() {
        // Test with negative values
        let test_values = [-1, -5, -10, -42, i32::MIN + 1]; // Avoid MIN as absolute value would overflow

        for &val in &test_values {
            let non_zero = NonZeroI32::new(val).unwrap();
            let result = compute_unsigned_abs(non_zero);

            // The result should be the absolute value of the input
            assert_eq!(result.get(), val.unsigned_abs());
        }
    }

    #[test]
    fn test_i32_min_edge_case() {
        // Special edge case for i32::MIN
        // i32::MIN is -2147483648, and its absolute value as u32 is 2147483648
        if let Some(min_value) = NonZeroI32::new(i32::MIN) {
            let result = compute_unsigned_abs(min_value);
            assert_eq!(result.get(), 2_147_483_648u32);
        }
    }

    #[test]
    fn test_nonzero_property() {
        // Verify that the NonZero property is preserved
        // This is a compile-time guarantee, but we can verify that the result is never zero
        let test_values = [
            NonZeroI32::new(1).unwrap(),
            NonZeroI32::new(-1).unwrap(),
            NonZeroI32::new(i32::MAX).unwrap(),
            NonZeroI32::new(i32::MIN).unwrap(),
        ];

        for val in &test_values {
            let result = compute_unsigned_abs(*val);
            assert_ne!(result.get(), 0);
        }
    }

    #[test]
    fn test_original_value_unchanged() {
        // Ensure that the original value is not modified
        let original = NonZeroI32::new(-42).unwrap();
        let original_value = original.get();

        let _ = compute_unsigned_abs(original);

        // Verify the original value is unchanged
        assert_eq!(original.get(), original_value);
    }
}

