#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_slice() {
        let mut tasks: Vec<Task> = Vec::new();
        sort_tasks_by_priority(&mut tasks);
        assert_eq!(tasks, Vec::<Task>::new());
    }

    #[test]
    fn test_single_task() {
        let mut tasks = vec![Task { priority: 5 }];
        sort_tasks_by_priority(&mut tasks);
        assert_eq!(tasks, vec![Task { priority: 5 }]);
    }

    #[test]
    fn test_already_sorted() {
        let mut tasks = vec![
            Task { priority: 10 },
            Task { priority: 5 },
            Task { priority: 1 },
        ];
        sort_tasks_by_priority(&mut tasks);
        assert_eq!(
            tasks,
            vec![
                Task { priority: 10 },
                Task { priority: 5 },
                Task { priority: 1 },
            ]
        );
    }

    #[test]
    fn test_reverse_sorted() {
        let mut tasks = vec![
            Task { priority: 1 },
            Task { priority: 5 },
            Task { priority: 10 },
        ];
        sort_tasks_by_priority(&mut tasks);
        assert_eq!(
            tasks,
            vec![
                Task { priority: 10 },
                Task { priority: 5 },
                Task { priority: 1 },
            ]
        );
    }

    #[test]
    fn test_random_order() {
        let mut tasks = vec![
            Task { priority: 3 },
            Task { priority: 1 },
            Task { priority: 7 },
            Task { priority: 2 },
            Task { priority: 5 },
        ];
        sort_tasks_by_priority(&mut tasks);
        assert_eq!(
            tasks,
            vec![
                Task { priority: 7 },
                Task { priority: 5 },
                Task { priority: 3 },
                Task { priority: 2 },
                Task { priority: 1 },
            ]
        );
    }

    #[test]
    fn test_duplicate_priorities() {
        let mut tasks = vec![
            Task { priority: 5 },
            Task { priority: 10 },
            Task { priority: 5 },
            Task { priority: 3 },
            Task { priority: 10 },
        ];
        sort_tasks_by_priority(&mut tasks);

        // Check that priorities are in descending order
        let priorities: Vec<u32> = tasks.iter().map(|task| task.priority).collect();
        for i in 1..priorities.len() {
            assert!(priorities[i - 1] >= priorities[i]);
        }
    }

    #[test]
    fn test_large_dataset() {
        // Create a large dataset with predictable pattern
        let mut tasks: Vec<Task> = (0..1000)
            .map(|i| Task { priority: (i * 17) % 100 })
            .collect();

        // Create a copy for verification
        let orig_priorities: Vec<u32> = tasks.iter().map(|task| task.priority).collect();

        // Sort using our function
        sort_tasks_by_priority(&mut tasks);

        // Verify sorting is correct (descending)
        let sorted_priorities: Vec<u32> = tasks.iter().map(|task| task.priority).collect();
        for i in 1..sorted_priorities.len() {
            assert!(sorted_priorities[i - 1] >= sorted_priorities[i]);
        }

        // Verify we have the same priorities as before, just sorted
        assert_eq!(
            orig_priorities.iter().fold(0, |acc, &x| acc + x as u64),
            sorted_priorities.iter().fold(0, |acc, &x| acc + x as u64)
        );
    }
}

