mod tests {
    use super::*;
    use std::any::TypeId;

    // Test basic functionality with primitive types
    #[test]
    fn test_debug_primitive_types() {
        let i32_type_id = TypeId::of::<i32>();
        let u64_type_id = TypeId::of::<u64>();
        let bool_type_id = TypeId::of::<bool>();

        let i32_debug = debug_type_id(i32_type_id);
        let u64_debug = debug_type_id(u64_type_id);
