        assert!(!u64_debug.is_empty());
        assert!(!bool_debug.is_empty());

        // Check that different types have different debug outputs
        assert_ne!(i32_debug, u64_debug);
        assert_ne!(i32_debug, bool_debug);
        assert_ne!(u64_debug, bool_debug);
    }

