        let vec_i32_debug = debug_type_id(vec_i32_type_id);
        let vec_u64_debug = debug_type_id(vec_u64_type_id);
        let option_bool_debug = debug_type_id(option_bool_type_id);

        // Check that outputs are non-empty strings
        assert!(!vec_i32_debug.is_empty());
        assert!(!vec_u64_debug.is_empty());
        assert!(!option_bool_debug.is_empty());

        // Check that different generic instantiations have different debug outputs
        assert_ne!(vec_i32_debug, vec_u64_debug);
        assert_ne!(vec_i32_debug, option_bool_debug);
    }

