fn proportion_negative(numbers: Vec<f64>) -> f64 {
    let negative_count = numbers.iter().filter(|&&x| x.is_sign_negative()).count();
    if numbers.is_empty() {
        0.0
    } else {
        negative_count as f64 / numbers.len() as f64
    }
}

