    fn test_unsorted() {
        let mut data = vec![3, 1, 5, 2, 4];
        let result = efficient_sort_in_place(&mut data);
        assert_eq!(result, &mut vec![1, 2, 3, 4, 5]);
    }

    #[test]
    fn test_with_duplicates() {
        let mut data = vec![3, 1, 3, 2, 1];
        let result = efficient_sort_in_place(&mut data);
        assert_eq!(result, &mut vec![1, 1, 2, 3, 3]);
    }

