    fn test_with_negative_numbers() {
        let mut data = vec![-3, 1, -5, 2, 0];
        let result = efficient_sort_in_place(&mut data);
        assert_eq!(result, &mut vec![-5, -3, 0, 1, 2]);
    }

    #[test]
    fn test_large_vector() {
        let mut data: Vec<i32> = (0..10000).rev().collect();
        let mut expected: Vec<i32> = (0..10000).collect();
        let result = efficient_sort_in_place(&mut data);
        assert_eq!(result, &mut expected);
    }

    #[test]
    fn test_same_reference_returned() {
        let mut data = vec![3, 1, 5, 2, 4];
        let data_ptr = data.as_mut_ptr();
        let result = efficient_sort_in_place(&mut data);
        let result_ptr = result.as_mut_ptr();
        // Verify that the returned reference points to the same memory
        assert_eq!(data_ptr, result_ptr);
    }

    #[test]
    fn test_stability_with_many_duplicates() {
        // Sort_unstable doesn't guarantee stability, but we should test with many duplicates
        let mut data = vec![5, 5, 5, 4, 4, 3, 3, 3, 3, 2, 1, 1, 1];
        let result = efficient_sort_in_place(&mut data);
        assert_eq!(result, &mut vec![1, 1, 1, 2, 3, 3, 3, 3, 4, 4, 5, 5, 5]);
    }

    #[test]
    fn test_single_element() {
        let mut data = vec![42];
        let result = efficient_sort_in_place(&mut data);
        assert_eq!(result, &mut vec![42]);
    }

    #[test]
    fn test_performance_edge_cases() {
        // Test for edge cases that might affect performance

        // Nearly sorted (just one element out of place)
        let mut nearly_sorted = (0..1000).collect::<Vec<i32>>();
        nearly_sorted[500] = 1001;
        let nearly_sorted_copy = nearly_sorted.clone();
        let sorted = efficient_sort_in_place(&mut nearly_sorted);

        // Create proper expected result
        let mut expected = nearly_sorted_copy;
        expected.sort_unstable();
        assert_eq!(sorted, &mut expected);

        // All same values
        let mut all_same = vec![7; 1000];
        let sorted_same = efficient_sort_in_place(&mut all_same);
        assert_eq!(sorted_same, &mut vec![7; 1000]);
    }

    #[test]
    fn test_min_max_values() {
        let mut data = vec![i32::MAX, i32::MIN, 0, 42, -42];
        let result = efficient_sort_in_place(&mut data);
        assert_eq!(result, &mut vec![i32::MIN, -42, 0, 42, i32::MAX]);
    }
}

