            Task {
                priority: 1,
                description: "Low priority task".to_string(),
            },
            Task {
                priority: 5,
                description: "Medium priority task".to_string(),
            },
            Task {
                priority: 10,
                description: "High priority task".to_string(),
            },
        ];

        let expected_priorities = vec![10, 5, 1];
        sort_tasks_by_priority(&mut tasks);

        let actual_priorities: Vec<u32> = tasks.iter().map(|t| t.priority).collect();
        assert_eq!(actual_priorities, expected_priorities);
    }

    #[test]
    fn test_random_order() {
        let mut tasks = vec![
            Task {
                priority: 5,
                description: "Medium priority task".to_string(),
            },
            Task {
                priority: 10,
                description: "High priority task".to_string(),
            },
            Task {
                priority: 1,
                description: "Low priority task".to_string(),
            },
            Task {
                priority: 7,
                description: "Another medium priority task".to_string(),
            },
        ];

        let expected_priorities = vec![10, 7, 5, 1];
        sort_tasks_by_priority(&mut tasks);

        let actual_priorities: Vec<u32> = tasks.iter().map(|t| t.priority).collect();
        assert_eq!(actual_priorities, expected_priorities);
    }

    #[test]
    fn test_duplicate_priorities() {
        let mut tasks = vec![
            Task {
                priority: 5,
                description: "First medium priority task".to_string(),
            },
            Task {
                priority: 10,
                description: "High priority task".to_string(),
            },
            Task {
                priority: 5,
                description: "Second medium priority task".to_string(),
            },
            Task {
                priority: 1,
                description: "Low priority task".to_string(),
            },
        ];

        sort_tasks_by_priority(&mut tasks);

        // Check that priorities are correctly sorted
        assert_eq!(tasks[0].priority, 10);
        assert_eq!(tasks[1].priority, 5);
        assert_eq!(tasks[2].priority, 5);
        assert_eq!(tasks[3].priority, 1);

        // Check that the tasks with the same priority retain their descriptions
        let medium_priority_descriptions: Vec<&str> = tasks
            .iter()
            .filter(|t| t.priority == 5)
            .map(|t| t.description.as_str())
            .collect();

        assert!(medium_priority_descriptions.contains(&"First medium priority task"));
        assert!(medium_priority_descriptions.contains(&"Second medium priority task"));
    }

    #[test]
    fn test_large_dataset() {
        // Create a larger dataset to test performance with many items
        let mut tasks: Vec<Task> = (0..1000)
            .map(|i| {
                // Create priority in reverse order so we test worst-case scenario
                let priority = 1000 - i;
                Task {
                    priority,
                    description: format!("Task {}", i),
                }
            })
            .collect();

        sort_tasks_by_priority(&mut tasks);

        // Verify the sorting is correct
        for i in 0..tasks.len() - 1 {
            assert!(tasks[i].priority >= tasks[i + 1].priority);
        }

        // Check first and last elements specifically
        assert_eq!(tasks[0].priority, 1000);
        assert_eq!(tasks[tasks.len() - 1].priority, 1);
    }

    #[test]
    fn test_stability_with_equal_priorities() {
        // This test checks if the original order is preserved for equal priorities
        // Note: sort_unstable_by_key doesn't guarantee stability, so this test
        // is mostly informational about the behavior rather than a requirement

        let task1 = Task {
            priority: 5,
            description: "Task A".to_string(),
        };

        let task2 = Task {
            priority: 5,
            description: "Task B".to_string(),
        };

        let task3 = Task {
            priority: 5,
            description: "Task C".to_string(),
        };

        let mut tasks = vec![task1, task2, task3];
        let original_descriptions: Vec<String> = tasks.iter()
            .map(|t| t.description.clone())
            .collect();

        sort_tasks_by_priority(&mut tasks);

        // We can only verify that all elements are still there with the same priority
        assert_eq!(tasks.len(), 3);
        assert!(tasks.iter().all(|t| t.priority == 5));

        // Check all descriptions are still present (though order may have changed)
        let sorted_descriptions: Vec<String> = tasks.iter()
            .map(|t| t.description.clone())
            .collect();

        let mut original_sorted = original_descriptions.clone();
        original_sorted.sort();

        let mut new_sorted = sorted_descriptions.clone();
        new_sorted.sort();

        assert_eq!(original_sorted, new_sorted);
    }
}

