    fn test_duplicate_elements() {
        let mut duplicates = [3, 1, 4, 1, 5, 9, 2, 6, 5];
        let result = stable_sort_integers(&mut duplicates);
        assert_eq!(result, &mut [1, 1, 2, 3, 4, 5, 5, 6, 9]);
    }

    #[test]
    fn test_stability() {
        // Since we're sorting i32 values which don't have any distinguishing
        // features beyond their numeric value, we need to create pairs of
        // (value, index) to test stability.
        // For this test, we'll use a separate implementation that tracks the original indices.

        let original = [3, 1, 4, 1, 5];

        // Create pairs of (value, original_index)
        let mut pairs: Vec<(i32, usize)> = original.iter()
            .enumerate()
            .map(|(idx, &val)| (val, idx))
            .collect();

        // Sort the pairs by their value
        pairs.sort_by_key(|&(val, _)| val);

        // The two 1's should maintain their original order (indices 1 and 3)
        assert_eq!(pairs[0].0, 1);
        assert_eq!(pairs[1].0, 1);
        assert_eq!(pairs[0].1, 1); // First 1 was at index 1
        assert_eq!(pairs[1].1, 3); // Second 1 was at index 3
    }

    #[test]
    fn test_large_dataset() {
        // Create a large dataset with some pattern
        let mut large_data: Vec<i32> = Vec::with_capacity(1000);
        for i in 0..1000 {
            large_data.push((i * 17) % 100);
        }

        let mut expected = large_data.clone();
        expected.sort();

        let result = stable_sort_integers(&mut large_data);
        assert_eq!(result, expected.as_mut_slice());
    }

    #[test]
    fn test_negative_numbers() {
        let mut mixed = [5, -3, 0, 8, -1, 2];
        let result = stable_sort_integers(&mut mixed);
        assert_eq!(result, &mut [-3, -1, 0, 2, 5, 8]);
    }

    #[test]
    fn test_all_same_value() {
        let mut same = [42, 42, 42, 42, 42];
        let result = stable_sort_integers(&mut same);
        assert_eq!(result, &mut [42, 42, 42, 42, 42]);
    }

    #[test]
    fn test_edge_cases() {
        let mut edge_cases = [i32::MIN, 0, i32::MAX, i32::MIN, i32::MAX];
        let result = stable_sort_integers(&mut edge_cases);
        assert_eq!(result, &mut [i32::MIN, i32::MIN, 0, i32::MAX, i32::MAX]);
    }
}

