#[cfg(test)]
mod tests {
    use super::*;
    use std::mem::{MaybeUninit, size_of, align_of};
    use std::ptr;

    #[test]
    fn test_buffer_size() {
        let size = 100;
        let buffer = create_uninitialized_buffer(size);

        assert_eq!(buffer.len(), size, "Buffer length should match requested size");
    }

    #[test]
    fn test_buffer_alignment() {
        let size = 1024;
        let buffer = create_uninitialized_buffer(size);

        // Check that the buffer is properly aligned for u8
        let ptr = buffer.as_ptr() as usize;
        assert_eq!(ptr % align_of::<u8>(), 0, "Buffer should be aligned for u8");
    }

    #[test]
    fn test_zero_size_buffer() {
        let buffer = create_uninitialized_buffer(0);

        assert_eq!(buffer.len(), 0, "Zero-size buffer should have length 0");
    }

    #[test]
    fn test_large_buffer() {
        // Test with a reasonably large buffer (4 MB)
        let size = 4 * 1024 * 1024;
        let buffer = create_uninitialized_buffer(size);

        assert_eq!(buffer.len(), size, "Large buffer length should match requested size");
    }

    #[test]
    fn test_write_read_buffer() {
        let size = 10;
        let mut buffer = create_uninitialized_buffer(size);

        // Safely write to buffer
        for i in 0..size {
            buffer[i].write(i as u8);
        }

        // Safely read from buffer
        for i in 0..size {
            unsafe {
                assert_eq!(buffer[i].assume_init(), i as u8, "Read value should match written value");
            }
        }
    }

    #[test]
    fn test_memory_layout() {
        let size = 32;
        let buffer = create_uninitialized_buffer(size);

        // Verify the memory layout is contiguous
        let expected_size = size * size_of::<MaybeUninit<u8>>();
        let actual_size = std::mem::size_of_val(&*buffer);

        assert_eq!(actual_size, expected_size, "Buffer memory layout size should be correct");
    }

    #[test]
    fn test_no_initialization() {
        // This test verifies that we don't automatically initialize memory
        // (it's a bit tricky to test directly, but we can check for overhead)

        use std::time::{Duration, Instant};

        let size = 64 * 1024 * 1024; // 64 MB should be large enough to measure

        let start = Instant::now();
        let _buffer = create_uninitialized_buffer(size);
        let duration = start.elapsed();

        // Creating uninitialized memory should be much faster than initializing it
        // This is a bit of a fuzzy test, but it checks that we're not doing full initialization
        // We allow a very generous time limit that should pass on any reasonable system
        assert!(duration < Duration::from_millis(500), 
                "Creating uninitialized buffer took too long, might be initializing memory");
    }

    #[test]
    fn test_buffer_drop() {
        // Test that the buffer is properly deallocated when dropped
        // This is mostly to check for memory leaks, which are hard to test directly
        // But we can at least make sure the code runs without panicking

        let size = 1024;
        let buffer = create_uninitialized_buffer(size);
        drop(buffer);
        // If we get here without panicking, the test passes
    }
}

