fn calculate_triangle_centroid(
    p1: Box<(f64, f64)>,
    p2: Box<(f64, f64)>,
    p3: Box<(f64, f64)>,
) -> ((f64, f64), String) {
    use std::fmt;

    // Centroid = average of vertices.
    const INV3: f64 = 1.0 / 3.0;
    let x = (p1.0 + p2.0 + p3.0) * INV3;
    let y = (p1.1 + p2.1 + p3.1) * INV3;

    // Explicitly exercise fmt::Pointer for Box<T, A>.
    struct Ptr<'a, T: ?Sized>(&'a Box<T>);
    impl<'a, T: ?Sized> fmt::Display for Ptr<'a, T> {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            // This calls the fmt::Pointer trait method on Box directly.
            fmt::Pointer::fmt(self.0, f)
        }
    }

    let debug_id = format!("{}|{}|{}", Ptr(&p1), Ptr(&p2), Ptr(&p3));
    ((x, y), debug_id)
}

