    fn test_simple_triangle() {
        let p1 = Box::new((0.0, 0.0));
        let p2 = Box::new((3.0, 0.0));
        let p3 = Box::new((0.0, 3.0));

        let ((cx, cy), id) = calculate_triangle_centroid(p1, p2, p3);
