use std::num::FpCategory;

pub fn classify_float(value: f64) -> FpCategory {
    value.classify()
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use std::num::FpCategory;
    use std::f64::{INFINITY, NEG_INFINITY, NAN, MIN_POSITIVE};

    #[test]
    fn test_normal_values() {
        // Regular normal numbers
        assert_eq!(classify_float(1.0), FpCategory::Normal);
        assert_eq!(classify_float(-1.0), FpCategory::Normal);
        assert_eq!(classify_float(42.5), FpCategory::Normal);
        assert_eq!(classify_float(-42.5), FpCategory::Normal);

        // Large normal values close to but not at infinity
        assert_eq!(classify_float(1.7e308), FpCategory::Normal);
        assert_eq!(classify_float(-1.7e308), FpCategory::Normal);
    }

    #[test]
    fn test_subnormal_values() {
        // Smallest positive subnormal
        let smallest_subnormal = f64::from_bits(0x0000000000000001);
        assert_eq!(classify_float(smallest_subnormal), FpCategory::Subnormal);
        assert_eq!(classify_float(-smallest_subnormal), FpCategory::Subnormal);

        // Largest subnormal value
        let largest_subnormal = f64::from_bits(0x000fffffffffffff);
        assert_eq!(classify_float(largest_subnormal), FpCategory::Subnormal);
        assert_eq!(classify_float(-largest_subnormal), FpCategory::Subnormal);

        // A midpoint subnormal value
        let mid_subnormal = f64::from_bits(0x0008000000000000);
        assert_eq!(classify_float(mid_subnormal), FpCategory::Subnormal);

        // Values just below MIN_POSITIVE should be subnormal
        assert_eq!(classify_float(MIN_POSITIVE * 0.5), FpCategory::Subnormal);

        // Check a few more subnormal values
        let subnormal1 = MIN_POSITIVE / 2.0;
        let subnormal2 = MIN_POSITIVE / 1000.0;
        assert_eq!(classify_float(subnormal1), FpCategory::Subnormal);
        assert_eq!(classify_float(subnormal2), FpCategory::Subnormal);
    }

    #[test]
    fn test_zero_values() {
        // Positive and negative zero
        assert_eq!(classify_float(0.0), FpCategory::Zero);
        assert_eq!(classify_float(-0.0), FpCategory::Zero);

        // Make sure explicit bit patterns for zeros are recognized
        let pos_zero = f64::from_bits(0x0000000000000000);
        let neg_zero = f64::from_bits(0x8000000000000000);
        assert_eq!(classify_float(pos_zero), FpCategory::Zero);
        assert_eq!(classify_float(neg_zero), FpCategory::Zero);
    }

    #[test]
    fn test_infinite_values() {
        // Standard infinity constants
        assert_eq!(classify_float(INFINITY), FpCategory::Infinite);
        assert_eq!(classify_float(NEG_INFINITY), FpCategory::Infinite);

        // Verify with bit patterns for infinity
        let pos_inf = f64::from_bits(0x7ff0000000000000);
        let neg_inf = f64::from_bits(0xfff0000000000000);
        assert_eq!(classify_float(pos_inf), FpCategory::Infinite);
        assert_eq!(classify_float(neg_inf), FpCategory::Infinite);

        // Operations that result in infinity
        assert_eq!(classify_float(1.0 / 0.0), FpCategory::Infinite);
        assert_eq!(classify_float(-1.0 / 0.0), FpCategory::Infinite);
    }

    #[test]
    fn test_nan_values() {
        // Standard NaN constant
        assert_eq!(classify_float(NAN), FpCategory::Nan);

        // Various NaN bit patterns (quiet and signaling)
        let quiet_nan = f64::from_bits(0x7ff8000000000000);
        let signaling_nan = f64::from_bits(0x7ff4000000000000);
        let neg_nan = f64::from_bits(0xfff8000000000000);

        assert_eq!(classify_float(quiet_nan), FpCategory::Nan);
        assert_eq!(classify_float(signaling_nan), FpCategory::Nan);
        assert_eq!(classify_float(neg_nan), FpCategory::Nan);

        // Operations that result in NaN
        assert_eq!(classify_float(0.0 / 0.0), FpCategory::Nan);
        assert_eq!(classify_float(0.0 * INFINITY), FpCategory::Nan);
        assert_eq!(classify_float(INFINITY - INFINITY), FpCategory::Nan);
    }

    #[test]
    fn test_boundary_cases() {
        // Test boundary between normal and subnormal
        assert_eq!(classify_float(MIN_POSITIVE), FpCategory::Normal);
        assert_eq!(classify_float(nextdown(MIN_POSITIVE)), FpCategory::Subnormal);

        // Boundary between normal and infinity
        let max_normal = f64::from_bits(0x7fefffffffffffff);
        assert_eq!(classify_float(max_normal), FpCategory::Normal);

        // One bit more than max normal is infinity
        let just_infinity = f64::from_bits(0x7ff0000000000000);
        assert_eq!(classify_float(just_infinity), FpCategory::Infinite);

        // Between subnormal and zero
        let smallest_subnormal = f64::from_bits(0x0000000000000001);
        assert_eq!(classify_float(smallest_subnormal), FpCategory::Subnormal);

        // Truncation/rounding edge cases
        let almost_normal = nextdown(MIN_POSITIVE);
        assert_eq!(classify_float(almost_normal), FpCategory::Subnormal);
    }

    #[test]
    fn test_hardware_edge_cases() {
        // Create values that might be misrepresented on different hardware

        // Values that might be flushed to zero on some hardware
        let tiny_subnormal = f64::from_bits(0x0000000000000010);
        assert_eq!(classify_float(tiny_subnormal), FpCategory::Subnormal);

        // Test with values that have specific bit patterns that might be problematic
        // on x87 or other non-standard FPUs
        let x87_edge_case = f64::from_bits(0x0010000000000000);
        match classify_float(x87_edge_case) {
            FpCategory::Subnormal => { /* Expected on most hardware */ },
            FpCategory::Normal => {
                // This could happen on hardware that doesn't fully support subnormals
                // We allow this case but document it
                println!("Note: Hardware treats some subnormals as normal");
            },
            other => panic!("Unexpected classification for x87 edge case: {:?}", other),
        }

        // Test with operations that might lose precision
        let iterative_subnormal = (0..10).fold(MIN_POSITIVE, |acc, _| acc / 2.0);
        assert!(matches!(classify_float(iterative_subnormal), 
                         FpCategory::Subnormal | FpCategory::Zero));
    }

    // Helper function to get the next smaller representable f64 value
    fn nextdown(x: f64) -> f64 {
        if x.is_nan() || x == f64::NEG_INFINITY {
            return x;
        }
        if x == 0.0 {
            return -f64::from_bits(0x0000000000000001); // Smallest negative subnormal
        }
        if x < 0.0 {
            return f64::from_bits(x.to_bits() + 1);
        } else {
            return f64::from_bits(x.to_bits() - 1);
        }
    }
}

