    fn test_allocate_zeroed_memory_basic() {
        // Create a layout for a u64
        let layout = Layout::new::<u64>();

        unsafe {
            // Allocate zeroed memory
            let ptr = allocate_zeroed_memory(layout);

            // Verify the pointer is not null
            assert!(!ptr.is_null(), "Allocation should return a non-null pointer");

            // Verify memory is zeroed by reading it as a u64
            let value = *(ptr as *const u64);
            assert_eq!(value, 0, "Memory should be initialized to zero");

            // Clean up
            dealloc(ptr, layout);
        }
    }

    #[test]
    fn test_allocate_zeroed_memory_array() {
        // Number of elements
        const ELEMENTS: usize = 10;

        // Create a layout for an array of u32
        let layout = Layout::array::<u32>(ELEMENTS).unwrap();

        unsafe {
            // Allocate zeroed memory
            let ptr = allocate_zeroed_memory(layout);

            // Verify the pointer is not null
            assert!(!ptr.is_null(), "Allocation should return a non-null pointer");

            // Create a slice from the raw pointer
            let slice = std::slice::from_raw_parts(ptr as *const u32, ELEMENTS);

            // Verify all elements are zero
            for (i, &value) in slice.iter().enumerate() {
                assert_eq!(value, 0, "Element at index {} should be zero", i);
            }

            // Clean up
            dealloc(ptr, layout);
        }
    }

    #[test]
    fn test_allocate_zeroed_memory_struct() {
        // Define a test struct
        #[derive(Debug, PartialEq)]
        struct TestStruct {
            a: u32,
            b: u64,
            c: [u8; 16],
        }

        // Zero-initialized instance for comparison
        const ZERO_STRUCT: TestStruct = TestStruct {
            a: 0,
            b: 0,
            c: [0; 16],
        };

        let layout = Layout::new::<TestStruct>();

        unsafe {
            // Allocate zeroed memory
            let ptr = allocate_zeroed_memory(layout);

            // Verify the pointer is not null
            assert!(!ptr.is_null(), "Allocation should return a non-null pointer");

            // Read the memory as TestStruct
            let test_struct = ptr as *const TestStruct;

            // Verify struct fields are all zero
            assert_eq!(*test_struct, ZERO_STRUCT, "Struct should be zero-initialized");

            // Clean up
            dealloc(ptr, layout);
        }
    }

    #[test]
    fn test_allocate_zeroed_memory_alignment() {
        // Test with a layout requiring specific alignment
        // Create a layout with alignment of 32 bytes and size of 64 bytes
        let layout = Layout::from_size_align(64, 32).unwrap();

        unsafe {
            // Allocate zeroed memory
            let ptr = allocate_zeroed_memory(layout);

            // Verify the pointer is not null
            assert!(!ptr.is_null(), "Allocation should return a non-null pointer");

            // Verify alignment
            assert_eq!(
                ptr as usize % 32, 
                0, 
                "Allocated memory should be aligned to {} bytes", 
                layout.align()
            );

            // Verify memory is zeroed by checking the first 16 u32 values (64 bytes)
            let slice = std::slice::from_raw_parts(ptr as *const u32, 16);
            for (i, &value) in slice.iter().enumerate() {
                assert_eq!(value, 0, "Element at index {} should be zero", i);
            }

            // Clean up
            dealloc(ptr, layout);
        }
