        // Note: Rust's allocator may return a special non-null pointer for zero-sized allocations
        let layout = Layout::from_size_align(0, 1).unwrap();

        unsafe {
            // Allocate zeroed memory
            let ptr = allocate_zeroed_memory(layout);

            // We don't dereference this pointer since it might be a sentinel value
            // Just test that the call doesn't crash and clean up

            if !ptr.is_null() {
                // Only deallocate if the pointer isn't null
                // (Some allocators might return null for zero-sized allocations)
                dealloc(ptr, layout);
            }
        }
