    #[test]
    fn test_allocate_zeroed_memory_large() {
        // Test with a large allocation (1 MiB)
        const SIZE: usize = 1024 * 1024; // 1 MiB

        let layout = Layout::from_size_align(SIZE, 1).unwrap();

        unsafe {
            // Allocate zeroed memory
            let ptr = allocate_zeroed_memory(layout);

            // Verify the pointer is not null
            assert!(!ptr.is_null(), "Allocation should return a non-null pointer");

            // Verify memory is zeroed by checking every byte
            let slice = std::slice::from_raw_parts(ptr, SIZE);
            for (i, &byte) in slice.iter().enumerate() {
                assert_eq!(byte, 0, "Byte at index {} should be zero", i);
            }

            // Clean up
            dealloc(ptr, layout);
        }
    }

    #[test]
    fn test_allocate_zeroed_memory_write() {
        // Test that we can write to the allocated memory
        let layout = Layout::array::<u32>(4).unwrap();

        unsafe {
            // Allocate zeroed memory
            let ptr = allocate_zeroed_memory(layout);

            // Verify the pointer is not null
            assert!(!ptr.is_null(), "Allocation should return a non-null pointer");

            // Create a mutable slice
            let slice = std::slice::from_raw_parts_mut(ptr as *mut u32, 4);

            // Verify initial values are zero
            for &value in slice.iter() {
