        assert_eq!(result, &mut [1, 1, 2, 3, 4, 5, 5, 6, 9]);
    }

    #[test]
    fn test_stability_with_custom_type() {
        // Create a structure that will test stability
        #[derive(Debug, PartialEq, Eq)]
        struct Item {
            key: i32,
            original_position: usize,
        }

        // Manually implement comparison that only looks at the key
        impl PartialOrd for Item {
            fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
                self.key.partial_cmp(&other.key)
            }
        }

        impl Ord for Item {
            fn cmp(&self, other: &Self) -> std::cmp::Ordering {
                self.key.cmp(&other.key)
            }
        }

        // Create test data with duplicate keys
        let mut items = vec![
            Item { key: 5, original_position: 0 },
            Item { key: 3, original_position: 1 },
            Item { key: 5, original_position: 2 },
            Item { key: 2, original_position: 3 },
            Item { key: 3, original_position: 4 },
            Item { key: 1, original_position: 5 },
        ];

        // Define our own version of stable sort for the test
        fn test_stable_sort(data: &mut [Item]) -> &mut [Item] {
            data.sort_by(|a, b| a.cmp(b));
            data
        }

        // Sort the items
        let sorted_items = test_stable_sort(&mut items);

        // Check if the result is sorted by key
        for i in 1..sorted_items.len() {
            assert!(sorted_items[i-1].key <= sorted_items[i].key);
        }

        // Verify stability: for elements with the same key, the original order should be preserved
        // Find all indices of elements with the same key and check their order
        let mut indices_by_key: std::collections::HashMap<i32, Vec<usize>> = std::collections::HashMap::new();

        for (i, item) in sorted_items.iter().enumerate() {
            indices_by_key.entry(item.key).or_insert(Vec::new()).push(i);
        }

        for (_key, indices) in indices_by_key.iter() {
            if indices.len() > 1 {
                // For elements with the same key, check if original positions are in ascending order
                for i in 1..indices.len() {
                    assert!(
                        sorted_items[indices[i-1]].original_position < sorted_items[indices[i]].original_position,
                        "Stability violation: elements with the same key are not in their original order"
                    );
                }
            }
        }
    }

    #[test]
    fn test_large_dataset() {
        // Create a large dataset with many duplicates
        let mut large_data: Vec<i32> = Vec::with_capacity(10000);
        for i in 0..1000 {
            // Add duplicates
            for _ in 0..10 {
                large_data.push(i);
            }
        }

        // Shuffle the data deterministically
        let seed = 42;
        shuffle_deterministic(&mut large_data, seed);

        // Sort the data
        let sorted_data = optimize_stable_sort(&mut large_data);

        // Verify the data is sorted
        for i in 1..sorted_data.len() {
            assert!(sorted_data[i-1] <= sorted_data[i]);
        }

        // Verify that all elements are still present
        let mut counts = std::collections::HashMap::new();
        for &value in sorted_data.iter() {
            *counts.entry(value).or_insert(0) += 1;
        }

        for i in 0..1000 {
            assert_eq!(counts.get(&i).unwrap_or(&0), &10);
        }
    }

    // Helper function for deterministic shuffling
    fn shuffle_deterministic(data: &mut [i32], seed: u64) {
        // Simple deterministic shuffle using a linear congruential generator
        let mut x = seed;
        for i in (1..data.len()).rev() {
            // Generate a random index from 0 to i
            x = (x.wrapping_mul(6364136223846793005) + 1) % u64::MAX;
            let j = (x % (i as u64 + 1)) as usize;

            // Swap elements
            data.swap(i, j);
        }
    }

    #[test]
    fn test_negative_numbers() {
        let mut data = vec![-5, -3, -10, -1, -8];
        let result = optimize_stable_sort(&mut data);
        assert_eq!(result, &mut [-10, -8, -5, -3, -1]);
    }

    #[test]
    fn test_mixed_positive_negative() {
        let mut data = vec![5, -3, 10, -1, 0, 8, -8];
        let result = optimize_stable_sort(&mut data);
        assert_eq!(result, &mut [-8, -3, -1, 0, 5, 8, 10]);
    }

    #[test]
    fn test_all_same_value() {
        let mut data = vec![42; 10]; // 10 elements all with value 42
        let result = optimize_stable_sort(&mut data);
        assert_eq!(result, &mut [42, 42, 42, 42, 42, 42, 42, 42, 42, 42]);
    }
}

