            (NonZeroU32::new(u32::MAX - 1).unwrap(), NonZeroU32::new(65535).unwrap()),
            (NonZeroU32::new(4_294_836_225).unwrap(), NonZeroU32::new(65535).unwrap()), // 65535^2
            (NonZeroU32::new(4_294_836_224).unwrap(), NonZeroU32::new(65534).unwrap()), // 65535^2 - 1
