#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, Mutex};
    use std::thread;
    use std::time::{Duration, Instant};

    #[test]
    fn test_pause_returns_ok() {
        assert!(efficient_pause(Duration::from_millis(1)).is_ok());
    }

    #[test]
    fn test_unpark_wakes_early() {
        let started = Arc::new(Mutex::new(None));
        let started_clone = Arc::clone(&started);

        let handle = thread::spawn(move || {
            *started_clone.lock().unwrap() = Some(Instant::now());
            efficient_pause(Duration::from_secs(2)).unwrap();
        });

        // Wait until the worker records its start.
        while started.lock().unwrap().is_none() {
            thread::yield_now();
        }

        let start = started.lock().unwrap().unwrap();
        handle.thread().unpark();
        handle.join().unwrap();

        let elapsed = start.elapsed();
        assert!(elapsed < Duration::from_secs(1), "unpark should end early: {:?}", elapsed);
    }

    #[test]
    fn test_thread_continues_after_pause() {
        let data = Arc::new(Mutex::new(0));
        let data_clone = Arc::clone(&data);

        let handle = thread::spawn(move || {
            efficient_pause(Duration::from_millis(10)).unwrap();
            *data_clone.lock().unwrap() = 42;
        });

        handle.join().unwrap();
        assert_eq!(*data.lock().unwrap(), 42);
    }
}

