        update_socket_ip(&mut socket, unspecified);
        assert_eq!(*socket.ip(), unspecified);
        assert!(socket.ip().is_unspecified());

        // Test with multicast address
        let multicast = Ipv6Addr::new(0xff00, 0, 0, 0, 0, 0, 0, 0);
        update_socket_ip(&mut socket, multicast);
        assert_eq!(*socket.ip(), multicast);
        assert!(socket.ip().is_multicast());
    }

    #[test]
    fn test_update_socket_ip_with_flowinfo_and_scope_id() {
        // Test with non-zero flowinfo and scope_id
        let initial_ip = Ipv6Addr::new(0x2001, 0xdb8, 0, 0, 0, 0, 0, 1);
        let flowinfo = 42;
        let scope_id = 7;
        let mut socket = SocketAddrV6::new(initial_ip, 8080, flowinfo, scope_id);

        let new_ip = Ipv6Addr::new(0x2001, 0xdb8, 0, 0, 0, 0, 0, 5);
        update_socket_ip(&mut socket, new_ip);

        // Verify IP was updated but flowinfo and scope_id preserved
        assert_eq!(*socket.ip(), new_ip);
        assert_eq!(socket.flowinfo(), flowinfo);
        assert_eq!(socket.scope_id(), scope_id);
    }

    // This test verifies that the function can be used in const contexts
    // by testing it with a const IP (though we can't fully test const fn usage in tests)
    #[test]
    fn test_update_socket_ip_with_const_ip() {
        const CONST_IP: Ipv6Addr = Ipv6Addr::new(0x2001, 0xdb8, 0, 0, 0, 0, 0, 9);

        let initial_ip = Ipv6Addr::new(0x2001, 0xdb8, 0, 0, 0, 0, 0, 1);
        let mut socket = SocketAddrV6::new(initial_ip, 8080, 0, 0);

        update_socket_ip(&mut socket, CONST_IP);

        assert_eq!(*socket.ip(), CONST_IP);
    }
}

