use std::thread;
use std::time::{Instant, Duration};

fn log_thread_execution_time(thread: &thread::Thread, start_time: Instant) -> Duration {
    let thread_id = thread.id();
    let elapsed = start_time.elapsed();
    println!("Thread {:?} executed for {:?}", thread_id, elapsed);
    elapsed
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, Barrier};
    use std::thread;
    use std::time::{Duration, Instant};

    #[test]
    fn test_log_thread_execution_time_returns_correct_duration() {
        let start_time = Instant::now();
        thread::sleep(Duration::from_millis(10));
        let elapsed = log_thread_execution_time(&thread::current(), start_time);
        assert!(elapsed >= Duration::from_millis(10));
    }

    #[test]
    fn test_log_thread_execution_time_from_different_threads() {
        let thread_count = 3;
        let barrier = Arc::new(Barrier::new(thread_count));
        let mut handles = Vec::with_capacity(thread_count);

        for _ in 0..thread_count {
            let barrier_clone = Arc::clone(&barrier);
            let handle = thread::spawn(move || {
                let start_time = Instant::now();
                // Simulate some work
                thread::sleep(Duration::from_millis(15));

                // Ensure all threads reach this point before proceeding
                barrier_clone.wait();

                // Log the execution time and capture the return value
                let thread = thread::current();
                let duration = log_thread_execution_time(&thread, start_time);
                (thread.id(), duration)
            });
            handles.push(handle);
        }

        // Collect results from all threads
        let results: Vec<_> = handles
            .into_iter()
            .map(|h| h.join().expect("Thread failed"))
            .collect();

        // Verify each thread's duration
        for (thread_id, duration) in results {
            println!("Verified thread {:?} ran for at least 15ms: {:?}", thread_id, duration);
            assert!(duration >= Duration::from_millis(15));
        }
    }

    #[test]
    fn test_log_thread_execution_time_with_zero_time_elapsed() {
        let start_time = Instant::now();
        let elapsed = log_thread_execution_time(&thread::current(), start_time);
        // The elapsed time should be very small but positive
        assert!(elapsed >= Duration::from_nanos(0));
    }

    #[test]
    fn test_log_thread_execution_time_with_longer_execution() {
        let start_time = Instant::now();
        // Simulate more substantial work
        for _ in 0..5 {
            thread::sleep(Duration::from_millis(10));
        }
        let elapsed = log_thread_execution_time(&thread::current(), start_time);
        assert!(elapsed >= Duration::from_millis(50));
    }

    // Mock test to verify output format - This is not a perfect test since
    // we can't easily capture stdout in Rust tests without additional crates
    #[test]
    fn test_log_format_indirectly() {
        let start_time = Instant::now();
        thread::sleep(Duration::from_millis(5));
        let elapsed = log_thread_execution_time(&thread::current(), start_time);

        // This test is more for documentation - the actual output validation
        // would require capturing stdout
        assert!(elapsed.as_nanos() > 0);
    }
}

