mod tests {
    use std::net::{IpAddr, Ipv4Addr, Ipv6Addr, SocketAddr};

    use super::modify_port_in_const_context;

    #[test]
    fn test_modify_ipv4_port() {
        // Setup an IPv4 address
        let ip = IpAddr::V4(Ipv4Addr::new(127, 0, 0, 1));
        let mut addr = SocketAddr::new(ip, 8080);

        // Modify the port
        let result = modify_port_in_const_context(&mut addr, 9090);

        // Assert the port was changed
        assert_eq!(result.port(), 9090);
        // Ensure the original address was modified
        assert_eq!(addr.port(), 9090);
        // Ensure the IP address remains the same
        assert_eq!(addr.ip(), ip);
    }

    #[test]
    fn test_modify_ipv6_port() {
        // Setup an IPv6 address
        let ip = IpAddr::V6(Ipv6Addr::new(0, 0, 0, 0, 0, 0, 0, 1));
        let mut addr = SocketAddr::new(ip, 8080);

        // Modify the port
        let result = modify_port_in_const_context(&mut addr, 9090);

        // Assert the port was changed
        assert_eq!(result.port(), 9090);
        // Ensure the original address was modified
        assert_eq!(addr.port(), 9090);
        // Ensure the IP address remains the same
        assert_eq!(addr.ip(), ip);
    }

    #[test]
    fn test_modify_port_zero() {
        // Setup a socket address with a non-zero port
        let ip = IpAddr::V4(Ipv4Addr::new(192, 168, 1, 1));
        let mut addr = SocketAddr::new(ip, 8080);

        // Modify the port to zero (which is a valid port number)
        let result = modify_port_in_const_context(&mut addr, 0);

        // Assert the port was changed to zero
        assert_eq!(result.port(), 0);
        assert_eq!(addr.port(), 0);
    }

    #[test]
    fn test_modify_port_max() {
        // Setup a socket address
        let ip = IpAddr::V4(Ipv4Addr::new(192, 168, 1, 1));
        let mut addr = SocketAddr::new(ip, 8080);

        // Modify the port to the maximum u16 value
        let max_port = u16::MAX;
        let result = modify_port_in_const_context(&mut addr, max_port);

        // Assert the port was changed to the maximum value
        assert_eq!(result.port(), max_port);
        assert_eq!(addr.port(), max_port);
    }

    #[test]
    fn test_return_value_is_same_reference() {
        // Setup a socket address
        let ip = IpAddr::V4(Ipv4Addr::new(192, 168, 1, 1));
        let mut addr = SocketAddr::new(ip, 8080);

        // The returned reference should be the same as the input reference
        let addr_ptr = &mut addr as *mut _;
        let result = modify_port_in_const_context(&mut addr, 9090);
        let result_ptr = result as *mut _;

        // Assert that the pointers are the same
        assert_eq!(addr_ptr, result_ptr);
    }

    #[test]
    fn test_multiple_modifications() {
        // Setup a socket address
        let ip = IpAddr::V4(Ipv4Addr::new(192, 168, 1, 1));
        let mut addr = SocketAddr::new(ip, 8080);

        // First modification
        let result1 = modify_port_in_const_context(&mut addr, 9090);
        assert_eq!(result1.port(), 9090);

        // Second modification using the returned reference
        let result2 = modify_port_in_const_context(result1, 7070);
        assert_eq!(result2.port(), 7070);

        // Check that the original address was modified both times
        assert_eq!(addr.port(), 7070);
    }
}

