    fn test_multiple_elements_found() {
        let set: BTreeSet<i32> = [1, 3, 5, 7, 9].iter().cloned().collect();
        assert!(contains_value(&set, 5));
        assert!(contains_value(&set, 1));
        assert!(contains_value(&set, 9));
    }

    #[test]
    fn test_multiple_elements_not_found() {
        let set: BTreeSet<i32> = [1, 3, 5, 7, 9].iter().cloned().collect();
        assert!(!contains_value(&set, 0));
        assert!(!contains_value(&set, 2));
        assert!(!contains_value(&set, 10));
    }

