    fn test_negative_values() {
        let set: BTreeSet<i32> = [-10, -5, 0, 5, 10].iter().cloned().collect();
        assert!(contains_value(&set, -10));
        assert!(contains_value(&set, 0));
        assert!(!contains_value(&set, -7));
    }

    #[test]
    fn test_large_set() {
        let set: BTreeSet<i32> = (0..1000).collect();
        assert!(contains_value(&set, 0));
        assert!(contains_value(&set, 500));
        assert!(contains_value(&set, 999));
        assert!(!contains_value(&set, 1000));
        assert!(!contains_value(&set, -1));
    }

    #[test]
    fn test_i32_boundaries() {
        let mut set = BTreeSet::new();
        set.insert(i32::MIN);
        set.insert(i32::MAX);
        set.insert(0);

        assert!(contains_value(&set, i32::MIN));
        assert!(contains_value(&set, i32::MAX));
        assert!(contains_value(&set, 0));
        assert!(!contains_value(&set, i32::MIN + 1));
        assert!(!contains_value(&set, i32::MAX - 1));
    }
}

