    #[test]
    fn test_replace_existing_element() {
        let mut set = BTreeSet::new();
        set.insert(5);
        set.insert(10);
        set.insert(15);

        // Replace an existing element
        let replaced = replace_element(&mut set, 10);

        // Should return the element that was replaced
        assert_eq!(replaced, Some(10));

        // Set should still contain the same elements
        assert!(set.contains(&5));
        assert!(set.contains(&10));
        assert!(set.contains(&15));
