        set.insert(5);
        set.insert(15);

        // Try to replace an element that doesn't exist
        let replaced = replace_element(&mut set, 10);

        // Should return None
        assert_eq!(replaced, None);

        // Set should now contain the new element
        assert!(set.contains(&5));
        assert!(set.contains(&10));
        assert!(set.contains(&15));
        assert_eq!(set.len(), 3);
    }

