        let mut set = BTreeSet::new();
        set.insert(5);
        set.insert(10);

        // Replace multiple times
        let replaced1 = replace_element(&mut set, 10);
        assert_eq!(replaced1, Some(10));

        let replaced2 = replace_element(&mut set, 15);
        assert_eq!(replaced2, None);

        let replaced3 = replace_element(&mut set, 5);
        assert_eq!(replaced3, Some(5));

        // Verify final set state
        assert!(set.contains(&10));
        assert!(set.contains(&15));
        assert!(set.contains(&5));
        assert_eq!(set.len(), 3);
    }

    #[test]
    fn test_negative_values() {
        let mut set = BTreeSet::new();
        set.insert(-10);
        set.insert(-5);

        // Replace with negative value
        let replaced = replace_element(&mut set, -10);

        // Should return the element that was replaced
        assert_eq!(replaced, Some(-10));

        // Set should remain unchanged
        assert!(set.contains(&-10));
        assert!(set.contains(&-5));
        assert_eq!(set.len(), 2);
    }

