#[cfg(test)]
mod tests {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};
    use super::create_secure_hasher;

    #[test]
    fn test_create_secure_hasher_returns_instance() {
        let hasher = create_secure_hasher();
        assert!(std::mem::size_of_val(&hasher) > 0);
    }

    #[test]
    fn test_hasher_produces_consistent_results() {
        let mut hasher1 = create_secure_hasher();
        let mut hasher2 = create_secure_hasher();

        // Hash the same value with both hashers
        let test_value = "test_string";
        test_value.hash(&mut hasher1);
        test_value.hash(&mut hasher2);

        let hash1 = hasher1.finish();
        let hash2 = hasher2.finish();

        assert_eq!(hash1, hash2, "Hashers should produce consistent results for the same input");
    }

    #[test]
    fn test_hasher_produces_different_results_for_different_inputs() {
        let mut hasher = create_secure_hasher();

        // Hash first value
        let test_value1 = "test_string_1";
        test_value1.hash(&mut hasher);
        let hash1 = hasher.finish();

        // Create a new hasher and hash second value
        let mut hasher = create_secure_hasher();
        let test_value2 = "test_string_2";
        test_value2.hash(&mut hasher);
        let hash2 = hasher.finish();

        assert_ne!(hash1, hash2, "Hashers should produce different results for different inputs");
    }

    #[test]
    fn test_hasher_state_changes_when_data_added() {
        let mut hasher1 = create_secure_hasher();
        let mut hasher2 = create_secure_hasher();

        // Add data to hasher1, but not hasher2
        hasher1.write_u32(42);

        let hash1 = hasher1.finish();
        let hash2 = hasher2.finish();

        assert_ne!(hash1, hash2, "Hasher state should change when data is added");
    }

    #[test]
    fn test_hasher_handles_different_types() {
        let mut hasher = create_secure_hasher();

        // Test with different types
        42_u32.hash(&mut hasher);
        let hash_u32 = hasher.finish();

        let mut hasher = create_secure_hasher();
        42_u64.hash(&mut hasher);
        let hash_u64 = hasher.finish();

        let mut hasher = create_secure_hasher();
        "42".hash(&mut hasher);
        let hash_str = hasher.finish();

        // All three hashes should be different
        assert_ne!(hash_u32, hash_u64);
        assert_ne!(hash_u32, hash_str);
        assert_ne!(hash_u64, hash_str);
    }

    #[test]
    fn test_hasher_finish_doesnt_reset_state() {
        let mut hasher = create_secure_hasher();

        // Add data and get hash
        hasher.write_u32(1);
        let hash1 = hasher.finish();

        // Call finish again without adding data
        let hash2 = hasher.finish();

        // Both hashes should be the same
        assert_eq!(hash1, hash2, "Calling finish() should not reset the hasher state");

        // Add more data and check that hash changes
        hasher.write_u32(2);
        let hash3 = hasher.finish();

        assert_ne!(hash1, hash3, "Hash should change when more data is added");
    }
}

