use std::io::Cursor;

pub fn set_cursor_position_at_compile_time(cursor: &mut Cursor<Vec<u8>>, pos: u64) -> &mut Cursor<Vec<u8>> {
    cursor.set_position(pos);
    cursor
}

test_program:
#[cfg(test)]
mod tests {
    use std::io::{Cursor, Read, Seek, SeekFrom};
    use super::set_cursor_position_at_compile_time;

    #[test]
    fn test_basic_position_setting() {
        let data = vec![1, 2, 3, 4, 5];
        let mut cursor = Cursor::new(data);

        let cursor = set_cursor_position_at_compile_time(&mut cursor, 3);

        assert_eq!(cursor.position(), 3);
    }

    #[test]
    fn test_position_at_start() {
        let data = vec![10, 20, 30, 40, 50];
        let mut cursor = Cursor::new(data);
        cursor.set_position(2); // Set initial position

        let cursor = set_cursor_position_at_compile_time(&mut cursor, 0);

        assert_eq!(cursor.position(), 0);
    }

    #[test]
    fn test_position_at_end() {
        let data = vec![10, 20, 30, 40, 50];
        let mut cursor = Cursor::new(data.clone());

        let cursor = set_cursor_position_at_compile_time(&mut cursor, data.len() as u64);

        assert_eq!(cursor.position(), 5);
    }

    #[test]
    fn test_position_beyond_end() {
        let data = vec![10, 20, 30];
        let mut cursor = Cursor::new(data);

        let mut cursor = set_cursor_position_at_compile_time(&mut cursor, 10);

        assert_eq!(cursor.position(), 10);

        // Verify read behavior after setting position beyond end
        let mut buffer = [0u8; 1];
        let read_result = cursor.read(&mut buffer);
        assert!(read_result.is_ok());
        assert_eq!(read_result.unwrap(), 0); // Should read 0 bytes
    }

    #[test]
    fn test_read_after_position_change() {
        let data = vec![10, 20, 30, 40, 50];
        let mut cursor = Cursor::new(data);

        let mut cursor = set_cursor_position_at_compile_time(&mut cursor, 2);

        let mut buffer = [0u8; 2];
        cursor.read_exact(&mut buffer).unwrap();

        assert_eq!(buffer, [30, 40]);
        assert_eq!(cursor.position(), 4);
    }

    #[test]
    fn test_seek_after_position_change() {
        let data = vec![10, 20, 30, 40, 50];
        let mut cursor = Cursor::new(data);

        let mut cursor = set_cursor_position_at_compile_time(&mut cursor, 2);

        cursor.seek(SeekFrom::Current(1)).unwrap();
        assert_eq!(cursor.position(), 3);

        cursor.seek(SeekFrom::Start(0)).unwrap();
        assert_eq!(cursor.position(), 0);
    }

    #[test]
    fn test_empty_vec() {
        let data = Vec::<u8>::new();
        let mut cursor = Cursor::new(data);

        let cursor = set_cursor_position_at_compile_time(&mut cursor, 0);

        assert_eq!(cursor.position(), 0);
    }

    #[test]
    fn test_chained_operations() {
        let data = vec![10, 20, 30, 40, 50];
        let mut cursor = Cursor::new(data);

        // Chain multiple position changes
        let mut temp_cursor = set_cursor_position_at_compile_time(&mut cursor, 2);
        let final_cursor = set_cursor_position_at_compile_time(&mut temp_cursor, 4);

        assert_eq!(final_cursor.position(), 4);
    }
}

