    #[test]
    fn test_duplicate_values() {
        // Note: BTreeSet doesn't allow duplicates, but testing this for documentation purposes
        let mut set = BTreeSet::from([1, 2, 3]);
        set.insert(3); // This won't create a duplicate

        assert_eq!(set.len(), 3); // Confirm no duplicate was added

        let result = remove_first_occurrence(&mut set, 3);
        assert_eq!(result, Some(3));
        assert_eq!(set, BTreeSet::from([1, 2]));

        // Try removing again - should be gone
        let result = remove_first_occurrence(&mut set, 3);
        assert_eq!(result, None);
    }
}

