fn is_ethernet_encapsulation(protocol: i32) -> bool {
    protocol == IPPROTO_ETHERNET
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use libc::IPPROTO_ETHERNET;

    #[test]
    fn test_ethernet_encapsulation_true() {
        // Should return true when protocol matches IPPROTO_ETHERNET
        assert!(is_ethernet_encapsulation(IPPROTO_ETHERNET));
    }

    #[test]
    fn test_ethernet_encapsulation_false() {
        // Common IPv6 extension headers that are not Ethernet encapsulation
        let non_ethernet_protocols = [
            libc::IPPROTO_HOPOPTS,    // IPv6 Hop-by-Hop Options
            libc::IPPROTO_ROUTING,    // IPv6 Routing Header
            libc::IPPROTO_FRAGMENT,   // IPv6 Fragment Header
            libc::IPPROTO_ICMPV6,     // ICMPv6
            libc::IPPROTO_NONE,       // IPv6 No Next Header
            libc::IPPROTO_DSTOPTS,    // IPv6 Destination Options
            libc::IPPROTO_TCP,        // TCP
            libc::IPPROTO_UDP,        // UDP
        ];

        for &protocol in &non_ethernet_protocols {
            assert!(!is_ethernet_encapsulation(protocol), 
                   "Protocol {} should not be identified as Ethernet encapsulation", protocol);
        }
    }

    #[test]
    fn test_with_arbitrary_values() {
        // Random values that are unlikely to be IPPROTO_ETHERNET
        let arbitrary_values = [-1, 0, 42, 100, 255, 1000];

        for &value in &arbitrary_values {
            if value == IPPROTO_ETHERNET {
                assert!(is_ethernet_encapsulation(value),
                       "Failed with value that happens to equal IPPROTO_ETHERNET: {}", value);
            } else {
                assert!(!is_ethernet_encapsulation(value),
                       "Failed with arbitrary value: {}", value);
            }
        }
    }

    #[test]
    fn test_edge_cases() {
        // Test with i32 min/max values
        assert_eq!(is_ethernet_encapsulation(i32::MIN), i32::MIN == IPPROTO_ETHERNET);
        assert_eq!(is_ethernet_encapsulation(i32::MAX), i32::MAX == IPPROTO_ETHERNET);
    }
}

