test_program:
use time::{OffsetDateTime, Duration, macros::datetime, PrimitiveDateTime};
use time::format_description::well_known::Iso8601;
use time::error::Format;
use super::format_timestamp;

#[test]
fn test_format_timestamp_utc() {
    // Create a UTC timestamp - 2021-01-01T00:00:00Z
    let timestamp = OffsetDateTime::from_unix_timestamp(1609459200).unwrap();

    // Expected ISO8601 format with nanoseconds
    let result = format_timestamp(timestamp).unwrap();
    assert!(result.starts_with("2021-01-01T00:00:00"));
    assert!(result.contains("Z"));
}

#[test]
fn test_format_timestamp_with_offset() {
    // Create a timestamp with UTC+2 offset
    let timestamp = OffsetDateTime::from_unix_timestamp(1609459200).unwrap()
        .to_offset(time::UtcOffset::from_hms(2, 0, 0).unwrap());

    let result = format_timestamp(timestamp).unwrap();
    assert!(result.starts_with("2021-01-01T02:00:00"));
    assert!(result.contains("+02:00"));
}

#[test]
fn test_format_timestamp_returns_ok() {
    let timestamp = OffsetDateTime::now_utc();
    let result = format_timestamp(timestamp);
    assert!(result.is_ok());
}

#[test]
fn test_format_timestamp_contains_date_components() {
    // Create a specific timestamp: 2023-04-15 17:05:30 UTC
    let timestamp = OffsetDateTime::from_unix_timestamp(1681578330).unwrap();

    let formatted = format_timestamp(timestamp).unwrap();
    assert!(formatted.contains("2023"));
    assert!(formatted.contains("04") || formatted.contains("-4-"));
    assert!(formatted.contains("15"));
    assert!(formatted.contains("17:05:30"));
}

