use chrono::{DateTime, Duration, TimeZone, Timelike, Utc};
use std::time::SystemTime;

fn calculate_duration(start: DateTime<Utc>, end: DateTime<Utc>) -> Duration {
    end - start
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_positive_duration() {
        let start = Utc.with_ymd_and_hms(2023, 1, 1, 0, 0, 0).unwrap();
        let end = Utc.with_ymd_and_hms(2023, 1, 1, 1, 0, 0).unwrap();

        let duration = calculate_duration(start, end);

        assert_eq!(duration, Duration::hours(1));
    }

    #[test]
    fn test_zero_duration() {
        let timestamp = Utc.with_ymd_and_hms(2023, 1, 1, 0, 0, 0).unwrap();

        let duration = calculate_duration(timestamp, timestamp);

        assert_eq!(duration, Duration::zero());
    }

    #[test]
    fn test_negative_duration() {
        let start = Utc.with_ymd_and_hms(2023, 1, 1, 1, 0, 0).unwrap();
        let end = Utc.with_ymd_and_hms(2023, 1, 1, 0, 0, 0).unwrap();

        let duration = calculate_duration(start, end);

        assert_eq!(duration, Duration::hours(-1));
    }

    #[test]
    fn test_nanosecond_precision() {
        let start = Utc.with_ymd_and_hms(2023, 1, 1, 0, 0, 0).unwrap()
                     .with_nanosecond(100_000_000).unwrap();
        let end = Utc.with_ymd_and_hms(2023, 1, 1, 0, 0, 0).unwrap()
                   .with_nanosecond(600_000_000).unwrap();

        let duration = calculate_duration(start, end);

        assert_eq!(duration, Duration::nanoseconds(500_000_000));
    }

    #[test]
    fn test_mixed_precision() {
        let start = Utc.with_ymd_and_hms(2023, 1, 1, 0, 0, 0).unwrap();
        let end = Utc.with_ymd_and_hms(2023, 1, 1, 0, 0, 1).unwrap()
                   .with_nanosecond(500_000_000).unwrap();

        let duration = calculate_duration(start, end);

        assert_eq!(duration, Duration::milliseconds(1500));
    }

    #[test]
    fn test_large_duration() {
        let start = Utc.with_ymd_and_hms(2020, 1, 1, 0, 0, 0).unwrap();
        let end = Utc.with_ymd_and_hms(2023, 1, 1, 0, 0, 0).unwrap();

        let duration = calculate_duration(start, end);

        // 3 years (including a leap year)
        assert_eq!(duration, Duration::days(365 * 3 + 1));
    }

    #[test]
    fn test_from_system_time() {
        // Test with SystemTime conversion for real-world use case
        let now = SystemTime::now();
        let later = now + std::time::Duration::from_secs(10);

        let start = DateTime::<Utc>::from(now);
        let end = DateTime::<Utc>::from(later);

        let duration = calculate_duration(start, end);

        assert_eq!(duration, Duration::seconds(10));
    }

    #[test]
    fn test_performance() {
        // Simple performance test
        let start_time = Utc::now();

        // Perform many duration calculations in a loop
        let base = Utc.with_ymd_and_hms(2023, 1, 1, 0, 0, 0).unwrap();
        let mut total = Duration::zero();

        for i in 0..10_000 {
            let end = base + Duration::seconds(i);
            total = total + calculate_duration(base, end);
        }

        // Ensure the calculation completed in a reasonable time
        let elapsed = Utc::now() - start_time;
        assert!(elapsed < Duration::milliseconds(500), "Duration calculation performance test took too long: {:?}", elapsed);

        // Verify the result to prevent the loop from being optimized away
        assert_eq!(total, Duration::seconds((0..10_000).sum::<i64>()));
    }
}

