        assert_eq!(requires_timestamp_update(libc::PF_BLOCK_TS), true);

        // Test with PF_BLOCK_TS and some other bits set
        assert_eq!(requires_timestamp_update(libc::PF_BLOCK_TS | 0x4000), true);
        assert_eq!(requires_timestamp_update(libc::PF_BLOCK_TS | 0x8000 | 0x2000), true);
    }

