    fn test_valid_service_count() {
        // Test with 0 services (minimum possible value)
        assert!(is_service_count_valid(0));

        // Test with a small positive number
        assert!(is_service_count_valid(5));

        // Test with exactly the maximum allowed value
        assert!(is_service_count_valid(DCCP_SERVICE_LIST_MAX_LEN));
    }

    #[test]
    fn test_invalid_service_count() {
        // Test with one more than the maximum allowed value
        assert!(!is_service_count_valid(DCCP_SERVICE_LIST_MAX_LEN + 1));

        // Test with a large positive number
        assert!(!is_service_count_valid(1000000));
    }

    #[test]
    fn test_negative_service_count() {
        // While the function accepts negative numbers due to i32 parameter,
        // in practice this is likely an invalid input for the domain
        // Testing to document the current behavior
        assert!(is_service_count_valid(-1));
        assert!(is_service_count_valid(-100));
    }

    #[test]
    fn test_boundary_conditions() {
        // Test values around the boundary
        assert!(is_service_count_valid(DCCP_SERVICE_LIST_MAX_LEN - 1));
        assert!(is_service_count_valid(DCCP_SERVICE_LIST_MAX_LEN));
        assert!(!is_service_count_valid(DCCP_SERVICE_LIST_MAX_LEN + 1));
    }

    #[test]
    fn test_extreme_values() {
        // Test with i32 minimum value (should be valid as it's less than max)
        assert!(is_service_count_valid(i32::MIN));

        // Test with i32 maximum value (should be invalid as it's greater than max)
        // This assumes DCCP_SERVICE_LIST_MAX_LEN is less than i32::MAX
        if DCCP_SERVICE_LIST_MAX_LEN < i32::MAX {
            assert!(!is_service_count_valid(i32::MAX));
        }
    }
}

