    use std::time::{SystemTime, UNIX_EPOCH};

    #[test]
    fn test_timestamp_is_non_negative() {
        let timestamp = get_current_timestamp();
        assert!(timestamp >= 0, "Timestamp should be non-negative, got {}", timestamp);
    }

    #[test]
    fn test_timestamp_in_reasonable_range() {
        let timestamp = get_current_timestamp();
        let system_time = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("SystemTime before UNIX EPOCH")
            .as_secs() as i64;

        let difference = (timestamp - system_time).abs();
        assert!(difference <= 1, "Timestamp difference from system time should be within 1 second, got {}", difference);
    }

    #[test]
    fn test_timestamp_increases_monotonically() {
        let timestamp1 = get_current_timestamp();
        std::thread::sleep(std::time::Duration::from_millis(10));
        let timestamp2 = get_current_timestamp();
        assert!(timestamp2 >= timestamp1, "Timestamps should increase monotonically: {} -> {}", timestamp1, timestamp2);
    }

    #[test]
