    fn test_random_in_range_mixed_signs() {
        let low = -50;
        let high = 50;
        let result = random_in_range(low, high);

        assert!(result >= low, "Result {} should be >= low {}", result, low);
        assert!(result < high, "Result {} should be < high {}", result, high);
    }

