        let low = 1;
        let high = 1000;
        let results: Vec<i32> = (0..100).map(|_| random_in_range(low, high)).collect();

        // Check all values are within bounds
        for &result in &results {
            assert!(result >= low, "Result {} should be >= low {}", result, low);
            assert!(result < high, "Result {} should be < high {}", result, high);
