use std::panic::PanicHookInfo;
use std::collections::HashMap;
use std::sync::Mutex;

static HANDLERS: Mutex<Option<HashMap<&'static str, fn(&PanicHookInfo<'_>)>>> = Mutex::new(None);

fn register_module_panic_handler(module_name: &'static str, handler: fn(&PanicHookInfo<'_>)) {
    let mut handlers = HANDLERS.lock().unwrap();
    if handlers.is_none() {
        *handlers = Some(HashMap::new());
    }
    handlers.as_mut().unwrap().insert(module_name, handler);
}

