pub enum AlertSeverity {
    Critical,
    Warning,
    Info,
}

fn analyze_panic_for_health_check(info: &PanicHookInfo<'_>) -> HealthAlert {
    let message = if let Some(s) = info.payload().downcast_ref::<&str>() {
        s.to_string()
    } else if let Some(s) = info.payload().downcast_ref::<String>() {
        s.clone()
    } else {
        "Unknown panic occurred".to_string()
    };

    let severity = if message.contains("out of memory") || message.contains("stack overflow") {
        AlertSeverity::Critical
    } else if message.contains("assertion") {
        AlertSeverity::Warning
    } else {
        AlertSeverity::Info
    };

    let (source_file, line_number) = info.location()
        .map(|loc| (Some(loc.file().to_string()), Some(loc.line())))
        .unwrap_or((None, None));

    HealthAlert { severity, message, source_file, line_number }
}

