mod tests {
    use super::*;
    use std::panic;
    use std::sync::{Arc, Mutex};

    #[test]
    fn test_health_alert_creation() {
        let alert = Arc::new(Mutex::new(None));
        let alert_clone = alert.clone();

        panic::set_hook(Box::new(move |info| {
            *alert_clone.lock().unwrap() = Some(analyze_panic_for_health_check(info));
        }));

        let _ = panic::catch_unwind(|| {
            panic!("test panic for health check");
        });

        let _ = panic::take_hook();
        let result = alert.lock().unwrap();
        assert!(result.is_some());
        let a = result.as_ref().unwrap();
        assert_eq!(a.severity, AlertSeverity::Info);
    }

    #[test]
    fn test_critical_severity_detection() {
        let alert = Arc::new(Mutex::new(None));
        let alert_clone = alert.clone();

        panic::set_hook(Box::new(move |info| {
            *alert_clone.lock().unwrap() = Some(analyze_panic_for_health_check(info));
        }));

        let _ = panic::catch_unwind(|| {
            panic!("out of memory error");
        });

        let _ = panic::take_hook();
        let result = alert.lock().unwrap();
        assert!(result.is_some());
        let a = result.as_ref().unwrap();
        assert_eq!(a.severity, AlertSeverity::Critical);
    }

