use std::panic::PanicHookInfo;
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Debug, Clone)]
pub struct SpanEvent {
    pub trace_id: String,
    pub event_type: String,
    pub message: String,
    pub timestamp_ms: u128,
    pub thread_name: String,
}

fn telemetry_panic_handler(info: &PanicHookInfo<'_>) -> SpanEvent {
    let message = if let Some(s) = info.payload().downcast_ref::<&str>() {
        s.to_string()
    } else if let Some(s) = info.payload().downcast_ref::<String>() {
        s.clone()
    } else {
        "Unknown panic payload".to_string()
    };

    let trace_id = format!("{:x}", std::process::id());
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis();
    let thread_name = std::thread::current()
        .name()
        .unwrap_or("unnamed")
        .to_string();

    let location_info = if let Some(loc) = info.location() {
        format!("{}:{}:{}", loc.file(), loc.line(), loc.column())
    } else {
        "unknown location".to_string()
    };

    SpanEvent {
        trace_id,
        event_type: "panic".to_string(),
        message: format!("{} at {}", message, location_info),
        timestamp_ms: timestamp,
        thread_name,
    }
}

