use std::panic::PanicHookInfo;

#[derive(Debug, Clone, PartialEq)]
pub enum RecoveryAction {
    RestartComponent(String),
    GracefulShutdown,
    ImmediateAbort,
    LogAndContinue,
}

fn decide_recovery_action(info: &PanicHookInfo<'_>) -> RecoveryAction {
    let message = if let Some(s) = info.payload().downcast_ref::<&str>() {
        s.to_string()
    } else if let Some(s) = info.payload().downcast_ref::<String>() {
        s.clone()
    } else {
        "".to_string()
    };

    let location_file = info
        .location()
        .map(|loc| loc.file())
        .unwrap_or("");

    // Decide recovery strategy based on panic message and location
    if message.contains("out of memory") || message.contains("OOM") {
        RecoveryAction::GracefulShutdown
    } else if message.contains("critical") || message.contains("CRITICAL") {
        RecoveryAction::ImmediateAbort
    } else if location_file.contains("database") || location_file.contains("db") {
        RecoveryAction::RestartComponent("database_connection".to_string())
    } else if location_file.contains("network") || message.contains("connection") {
        RecoveryAction::RestartComponent("network_service".to_string())
    } else {
        RecoveryAction::LogAndContinue
    }
}

test_program:
#[test]
#[should_panic]
fn test_decide_recovery_action() {
    // Test 1: OOM panic should trigger GracefulShutdown
    std::panic::set_hook(Box::new(|panic_info| {
        let action = decide_recovery_action(panic_info);

        let msg = if let Some(s) = panic_info.payload().downcast_ref::<&str>() {
            s.to_string()
        } else if let Some(s) = panic_info.payload().downcast_ref::<String>() {
            s.clone()
        } else {
            String::new()
        };

        // Verify recovery action based on message
        if msg.contains("out of memory") {
            assert_eq!(action, RecoveryAction::GracefulShutdown);
        } else if msg.contains("critical") {
            assert_eq!(action, RecoveryAction::ImmediateAbort);
        } else {
            assert!(matches!(action, 
                RecoveryAction::LogAndContinue | 
                RecoveryAction::RestartComponent(_)));
        }
    }));

    panic!("out of memory");
}

#[test]
#[should_panic]
fn test_critical_recovery_action() {
    std::panic::set_hook(Box::new(|panic_info| {
        let action = decide_recovery_action(panic_info);
        assert_eq!(action, RecoveryAction::ImmediateAbort);
    }));

    panic!("CRITICAL error");
}

