        let end = 220;
        let delta = calculate_time_interval(start, end);
        assert_eq!(delta.num_seconds(), 120);
    }

    #[test]
    fn test_zero_interval() {
        let delta = calculate_time_interval(50, 50);
        assert_eq!(delta.num_seconds(), 0);
    }

    #[test]
