    fn test_large_interval() {
        let delta = calculate_time_interval(0, 86400); // 1 day
        assert_eq!(delta.num_hours(), 24);
        assert_eq!(delta.num_minutes(), 1440);
    }

    #[test]
    fn test_uses_timedelta() {
        // Verify we're using TimeDelta not Duration
        let delta = calculate_time_interval(0, 60);
        assert_eq!(delta.num_seconds(), 60);

        // TimeDelta operations
        let delta2 = delta + TimeDelta::seconds(30);
        assert_eq!(delta2.num_seconds(), 90);
    }
