use std::sync::atomic::{AtomicBool, Ordering};
use std::hint;

fn spin_lock(lock: &AtomicBool) {
    while lock.compare_exchange_weak(false, true, Ordering::Acquire, Ordering::Relaxed).is_err() {
        while lock.load(Ordering::Relaxed) {
            hint::spin_loop();
        }
    }
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::Arc;
    use std::thread;
    use std::time::Duration;

    #[test]
    fn test_spin_lock_acquires_unlocked() {
        let lock = AtomicBool::new(false);

        spin_lock(&lock);

        assert_eq!(lock.load(Ordering::Acquire), true, "Lock should be acquired (set to true)");
    }

    #[test]
    fn test_spin_lock_waits_for_locked() {
        let lock = Arc::new(AtomicBool::new(true));
        let lock_clone = Arc::clone(&lock);

        let start_time = std::time::Instant::now();
        let handle = thread::spawn(move || {
            thread::sleep(Duration::from_millis(10));
            lock_clone.store(false, Ordering::Release);
        });

        spin_lock(&lock);
        let elapsed = start_time.elapsed();

        handle.join().unwrap();
        assert_eq!(lock.load(Ordering::Acquire), true, "Lock should be acquired");
        assert!(elapsed >= Duration::from_millis(10), "Should have waited for lock release");
    }

    #[test]
    fn test_spin_lock_mutual_exclusion() {
        let lock = Arc::new(AtomicBool::new(false));
        let counter = Arc::new(std::sync::Mutex::new(0));
        let mut handles = Vec::new();

        for _ in 0..5 {
            let lock_clone = Arc::clone(&lock);
            let counter_clone = Arc::clone(&counter);

            handles.push(thread::spawn(move || {
                spin_lock(&lock_clone);

                let mut num = counter_clone.lock().unwrap();
                *num += 1;
                let current = *num;

                lock_clone.store(false, Ordering::Release);
                current
            }));
        }

        let results: Vec<_> = handles.into_iter().map(|h| h.join().unwrap()).collect();
        let final_count = *counter.lock().unwrap();

        assert_eq!(final_count, 5, "Counter should be incremented 5 times");
        assert_eq!(results, vec![1, 2, 3, 4, 5], "Increments should happen sequentially");
    }

    #[test]
    fn test_spin_lock_reentrant_behavior() {
        let lock = AtomicBool::new(false);

        spin_lock(&lock);
        assert_eq!(lock.load(Ordering::Acquire), true);

        lock.store(false, Ordering::Release);
        spin_lock(&lock);

        assert_eq!(lock.load(Ordering::Acquire), true, "Should be able to reacquire after release");
    }

    #[test]
    fn test_spin_lock_with_concurrent_access() {
        let lock = Arc::new(AtomicBool::new(false));
        let barrier = Arc::new(std::sync::Barrier::new(3));
        let mut handles = Vec::new();

        for _ in 0..3 {
            let lock_clone = Arc::clone(&lock);
            let barrier_clone = Arc::clone(&barrier);

            handles.push(thread::spawn(move || {
                barrier_clone.wait();
                spin_lock(&lock_clone);

                let result = lock_clone.load(Ordering::Acquire);
                lock_clone.store(false, Ordering::Release);
                result
            }));
        }

        let results: Vec<_> = handles.into_iter().map(|h| h.join().unwrap()).collect();

        assert_eq!(results.len(), 3, "All threads should complete");
        assert!(results.iter().all(|&r| r == true), "All threads should acquire lock successfully");
    }

    #[test]
    fn test_spin_lock_initial_state_false() {
        let lock = AtomicBool::new(false);

        assert_eq!(lock.load(Ordering::Relaxed), false, "Initial state should be false");

        spin_lock(&lock);

        assert_eq!(lock.load(Ordering::Acquire), true, "Lock should be acquired");
    }
}

