use std::fmt::Display;

fn get_error_details<E: Error + Display>(err: &E) -> (String, Option<String>) {
    let message = err.to_string();
    let source = err.source().map(|s| s.to_string());
    (message, source)
}

test_program:
#[cfg(test)]
mod tests {
    use super::*;
    use std::fmt;

    #[derive(Debug)]
    struct OuterError {
        msg: String,
        source: Option<InnerError>,
    }

    #[derive(Debug)]
    struct InnerError(String);

    impl fmt::Display for OuterError {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            write!(f, "Outer: {}", self.msg)
        }
    }

    impl fmt::Display for InnerError {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            write!(f, "Inner: {}", self.0)
        }
    }

    impl std::error::Error for InnerError {}

    impl std::error::Error for OuterError {
        fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
            self.source.as_ref().map(|e| e as &(dyn std::error::Error + 'static))
        }
    }

    #[test]
    fn test_error_with_source() {
        let inner = InnerError("root cause".to_string());
        let outer = OuterError {
            msg: "outer error".to_string(),
            source: Some(inner),
        };
        let (msg, src) = get_error_details(&outer);
        assert_eq!(msg, "Outer: outer error");
        assert!(src.is_some());
        assert!(src.unwrap().contains("root cause"));
    }

    #[test]
    fn test_error_without_source() {
        let err = OuterError {
            msg: "standalone error".to_string(),
            source: None,
        };
        let (msg, src) = get_error_details(&err);
        assert_eq!(msg, "Outer: standalone error");
        assert!(src.is_none());
    }
}

