use bytes::Bytes;
use http_body_util::StreamBody;
use tokio::sync::mpsc;
use futures_util::stream;

fn create_stream_body() -> (mpsc::Sender<Bytes>, StreamBody<impl futures_util::Stream<Item = Result<Bytes, std::io::Error>>>) {
    let (tx, mut rx) = mpsc::channel::<Bytes>(10);

    let stream = stream::poll_fn(move |cx| {
        use std::pin::Pin;
        use std::task::Poll;

        match Pin::new(&mut rx).poll_recv(cx) {
            Poll::Ready(Some(bytes)) => Poll::Ready(Some(Ok(bytes))),
            Poll::Ready(None) => Poll::Ready(None),
            Poll::Pending => Poll::Pending,
        }
    });

    (tx, StreamBody::new(stream))
}

